-- 경기도의회 행정사무감사 회의록(경기연구원 관련) 이관 데이터 (자동 생성: tools/import_audit.py)
-- 게시판 코드 audit. 여러 번 실행해도 중복되지 않습니다.
insert into public.boards (code,name,members_only,admin_only_write) values ('audit','행정사무감사',false,true) on conflict (code) do nothing;
create unique index if not exists posts_legacy_idx on public.posts ((attachments->>'legacy_id')) where attachments ? 'legacy_id';
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2009.11.17. 화요일] 경기개발연구원 — 기획위원회 2009년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제7대 경기도의회 기획위원회</b> · 2009년도 행정사무감사(2009. 11. 16. ~ 2009. 11. 25.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2254" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2009년도 행정사무감사
</p>
<h4>기획위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 2009년 11월 17일(화)
</p>
<p>장  소 : 경기개발연구원회의실   
</p>
<p><hr /></p>
<p class=''ar''>(10시20분 감사개시)
</p>
<p><b>○ 위원장 김대원 </b> 좌석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기개발연구원에 대한 2009년도 행정사무감사를 시작하겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기개발연구원 원장을 비롯한 임직원 여러분! 안녕하십니까? 기획위원회 감사위원장 김대원 위원입니다. 오늘 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되겠습니다. 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2010년도 예산안 심사자료 및 정보 획득을 통해 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 할 수 있습니다. 따라서 경기도의 싱크탱크인 경기개발연구원의 운영실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도의 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  끝으로 증인선서에 앞서 한 가지 알려드릴 말씀이 있습니다. 우리 위원회는 감사가 미진할 경우 오는 24일 저희 위원회 회의실에서 해당 부서를 대상으로 종합감사를 실시할 계획입니다. 모쪼록 다시 감사받는 일이 빚어지지 않도록 연구원 원장님과 임직원 여러분께서는 감사에 충실하게 임해 주실 것을 다시 한 번 당부드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부원장, 부장, 센터장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 합니다. 
</p>
<p style="padding-left:1.2em">  증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2009년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받고자 하는 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 그러면 먼저 증인출석 여부를 확인하겠습니다. 피감기관의 증인들은 모두 자리에서 일어나 주시기 바랍니다. 
</p>
<p style="padding-left:2.4em">    (일동기립)
</p>
<p style="padding-left:1.2em">  원장 나왔습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 부원장 나왔습니까? 
</p>
<p><b>○ 부원장 조응래 </b> 네, 나왔습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 기획조정실장 나오셨습니까? 
</p>
<p><b>○ 기획조정실장 김군수 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 사무처장 나오셨습니까? 
</p>
<p><b>○ 사무처장 엄정수 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 자치행정연구부장 나오셨습니까? 
</p>
<p><b>○ 자치행정연구부장 신원득 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 도시ㆍ지역계획연구부장 나왔습니까? 
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 교통정책연구부장 나왔습니까? 
</p>
<p><b>○ 교통정책연구부장 지우석 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 환경정책연구부장 나왔습니까? 
</p>
<p><b>○ 환경정책연구부장 이정임 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 경제사회연구부장 나왔습니까? 
</p>
<p><b>○ 경제사회연구부장 이상훈 </b> 네, 나왔습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 수도권정책센터장 나오셨습니까? 
</p>
<p><b>○ 수도권정책센터장 김제국 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 팔당물환경센터장 나왔습니까? 
</p>
<p><b>○ 팔당물환경센터장 김연제 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 통일ㆍ동북아연구센터장 나왔습니까? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 의정연구센터장 나왔습니까? 
</p>
<p><b>○ 의정연구센터장 신원득 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 문화관광연구센터장 나왔습니까? 
</p>
<p><b>○ 문화관광연구센터장 김흥식 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 경기과학기술센터 소장 나왔습니까? 
</p>
<p><b>○ 경기과학기술센터소장 이원영 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 다음은 선서의 요령을 설명드리겠습니다. 선서는 전체 증인을 대표해서 원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손만 들어주시기 바랍니다. 그러면 선서해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 본인은 경기도의회가 지방자치법 제41조, 같은 법 시행령 제39조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관 업무에 대한 2009년도 행정사무감사를 실시함에 있어 기관장으로서 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법 시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2009년 11월 17일. 직위 원장. 성명 좌승희.
</p>
<p><b>○ 위원장 김대원 </b> 자리에 앉아주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (일동착석)
</p>
<p style="padding-left:1.2em">  그러면 원장님 나오셔서 간부소개와 업무보고를 요약하여 보고해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 안녕하십니까? 연구원장 좌승희입니다. 오늘 경기도의회 기획위원회 행정사무감사 수감에 앞서 존경하는 김대원 위원장님과 위원님 여러분을 모시고 우리 연구원의 주요업무를 보고드리게 된 데 대해 감사의 말씀을 드립니다. 우리 연구원은 경기도정을 선도하는 싱크탱크로서 경기도와 나아가 대한민국의 발전을 견인하고 도민의 삶의 질 향상을 위한 정책개발에 임직원 모두 노력하고 있습니다. 우리 연구원은 금년 남은 기간과 내년도에도 이와 같은 목표를 차질 없이 추진해 나갈 계획이오니 기획위원회 위원님들의 많은 도움과 성원을 부탁드립니다. 그러면 보고에 앞서 우리 연구원의 간부를 소개해 올리겠습니다. 
</p>
<p style="padding-left:1.2em">  조응래 부원장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김군수 기획조정실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  엄정수 사무처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  왼쪽으로 신원득 자치행정연구부장입니다. 의정연구센터장을 겸직하고 있습니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상대 도시ㆍ지역계획연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  지우석 교통정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이정임 환경정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상훈 경제사회연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김제국 수도권정책센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음 제 오른쪽으로 김연제 팔당물환경센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음 김동성 통일ㆍ동북아연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음 김흥식 문화관광연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  마지막으로 이원영 부설 경기과학기술센터 소장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 준비된 주요업무보고 자료를 중심으로 업무를 보고 올리도록 하겠습니다. 배부해 드린 유인물의 목차를 봐주시기 바랍니다. 보고드릴 순서는 일반 및 재정운영 현황, 2009년도 연구사업목표 및 추진실적, 2009년도 주요 연구사업실적, 2010년도 연구사업계획, 마지막으로 부설 경기과학기술센터 업무보고 순입니다. 연구사업목표와 주요 연구사업실적을 중심으로 간략히 보고 올리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 일반 및 재정운영 현황입니다. 일반 현황, 재정운영 현황, 기구개편 그리고 인력충원 현황 순으로 보고드리도록 하겠습니다. 3쪽 일반 현황에 대해 보고드리겠습니다. 우리 연구원은 1995년에 개원하여 내년에 15주년을 맞이하게 됩니다마는 현재 1실 1처 5부 5센터 2과 10팀 부설 1센터의 조직으로 성장했습니다. 각 연구부나 센터의 기능에 대해서는 3쪽에 상세히 설명 올렸습니다.
</p>
<p style="padding-left:1.2em">  다음 4쪽 인력 현황에 대해서 보고드리겠습니다. 현재 본 원의 인력은 원장 1명, 부원장 1명, 연구직 53명, 관리직 등 정규직 77명과 비정규직 95명으로 총 172명이 근무하고 있으며 이와 별도로 보고 후반에 설명을 드리겠습니다마는 부설 경기과학기술센터는 소장 1명, 직원 7명 그리고 본 원 파견연구직 2명 등 총 10명이 근무하고 있습니다. 이렇게 해서 우리 원의 전체 인원은 비정규직 포함 180명이 근무하고 있습니다. 연구직의 부족한 인력은 분야별로 보강해 나갈 계획입니다. 4쪽에 있는 기구도표 중에 진하게 표시된 부분은 신규 설립된 조직입니다마는 다음에서 추가로 더 설명 올리도록 하겠습니다.  
</p>
<p style="padding-left:1.2em">  다음 5쪽의 재정운영에 대해서 말씀을 올리겠습니다. 올해의 총 재정규모는 743억 9,900만 원이며 여기에는 일반회계, 수탁용역사업특별회계, 기금, 경기과학기술센터 사업비가 포함되어 있습니다.
</p>
<p style="padding-left:1.2em">  일반회계 수입ㆍ지출내역을 구체적으로 살펴보면 수입 총액은 185억 3,100만 원이고 수입항목은 경기도 출연금이 전체의 69%인 126억 9,600만 원, 기금이자수입 등이 10%인 18억 8,600만 원, 사업수입이 6%인 11억 8,400만 원, 전기이월금이 15%인 27억 6,500만 원이며 지출항목으로는 연구사업비가 전체의 51%인 94억 2,700만 원, 인건비가 37%인 68억 1,700만 원, 부서운영비가 5%인 9억 9,300만 원, 청사관리비가 6%인 11억 4,400만 원, 예비비가 1%인 1억 5,000만 원입니다.
</p>
<p style="padding-left:1.2em">  수탁용역사업특별회계의 수입은 37억 1,800만 원이며 지출항목은 인건비가 21%인 7억 9,700만 원, 직접경비가 64%인 23억 7,300만 원, 전출금이 15%인 5억 4,800만 원입니다.
</p>
<p style="padding-left:1.2em">  다음 6쪽이 되겠습니다. 경기과학기술센터는 독립회계로 운영되고 있는데 센터의 수입ㆍ지출내역은 유인물 39쪽에서 별도로 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  연구원의 기금에 대해서 말씀을 드리면 총 272억 원이 기금인데요. 출연기관별로는 경기도가 54%인 147억 원, 시군이 15%인 39억 6,100만 원, 민간부문이 7%인 20억 원, 자체적립이 24%인 65억 3,900만 원입니다. 예산이 효율적으로 운용될 수 있도록 노력을 다하겠습니다. 기금 예치기관별 예치현황은 6쪽에 상세히 기록했습니다. 
</p>
<p style="padding-left:1.2em">  다음 7쪽 기구개편에 대해서 보고 올리겠습니다. 우리 원은 경기도의 정책현안과 관련된 신속한 정책대안 제시와 체계적 의사결정 지원을 위하여 문화관광센터 등 1센터 2팀을 신설하였습니다. 구체적으로는 문화관광센터는 경기도 문화관광분야의 비전 및 전략 수립을 목적으로 당초 사회문화연구부를 개편 전담조직화함과 동시에 부족한 전문인력을 충원하여 현재 4명의 박사급 연구직으로 운영하고 있습니다. 공공기관평가팀은 경기도 공공기관 및 시군 공기업의 평가를 위한 상시평가시스템 구축을 목적으로 현재 2명의 박사급 연구직으로 운영하고 있으며 부족한 인력은 향후 충원할 예정입니다.
</p>
<p style="padding-left:1.2em">  다음 8쪽이 되겠습니다. 민군정책팀은 민관군 협력 및 정책개발을 목적으로 민군 협력의 한계를 극복하기 위하여 군전문가를 초빙하여 운영하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음 금년도 인력충원 현황에 대해서 보고드리겠습니다. 연구직은 지난 2월과 6월 두 차례의 채용공고를 통해 관광문화분야 1명, 문화콘텐츠분야 1명 그리고 국제정치경제 1명 등 총 3명의 신규 박사급 연구직을 충원하였습니다. 그리고 현재 경기도의 교육정책 수요에 대응하여 교육분야의 박사급 연구직 충원을 추진 중에 있습니다. 우리 원은 또한 연구인력의 충원과 동시에 보완적으로 초빙연구원제도를 운영하여 관련 분야의 연구수요에 대응하고 있습니다. 그 내역은 8쪽에 상세히 보고 올렸습니다. 
</p>
<p style="padding-left:1.2em">  다음은 2009년도 연구사업목표 및 추진실적에 대해서 보고드리겠습니다. 유인물 11쪽과 12쪽이 되겠습니다. 먼저 11쪽 2009년도 연구사업목표입니다. 우리 원은 비전으로써 대한민국을 움직이는 중심 브레인 GRI와 연구원이 지향하는 기관목표인 경기도정을 선도하는 종합적 연구기관, 대한민국의 미래를 여는 중추적 연구기관, 동북아와 국제사회와 함께하는 세계적 연구기관으로 설정을 하고 그 역할을 다하기 위해 노력해 왔습니다. 2009년도 연구사업목표를 이에 맞추어서 글로벌 이슈에 대응한 정책연구를 선도하고 수도권의 경쟁력 강화를 위한 기반연구를 수행하며 민선4기 경기도정 4대 분야 24개 중점과제를 지원하는 데 목표를 두고 연구를 해왔습니다. 그리고 이와 같은 연구사업목표의 달성을 위하여 연구분야를 자치행정연구분야 등 10대 분야로 세분하고 광역행정체계 개편 대응 등 총 26개 대과제를 선정하여 이를 중심으로 연구사업을 추진하였습니다. 10대 분야와 26개 대과제에 대해서는 11쪽 하단에 상세히 보고 올렸습니다.
</p>
<p style="padding-left:1.2em">  다음은 12쪽이 되겠습니다. 우리 원의 연구과제사업 등 4대 사업별 사업계획 대비 추진실적을 보고드리겠습니다. 2009년도 연구과제사업은 신규과제 158개 과제와 전년도 이월과제 68개 과제를 포함하여 총 226개 과제 수행을 계획하였으며 10월 31일 현재 신규과제 기준계획 대비 착수실적은 98% 진행 중에 있습니다.
</p>
<p style="padding-left:1.2em">  연구부대사업은 정책세미나 24회, 정책포럼 운영 39건 등을 수행하여 현재 76% 진행 중에 있습니다. 다만 정책동향분석인 CEO Report나 Policy Brief의 발간건수는 각각 22건, 39건으로 계획목표에 상당 부족하나 현재 제한된 과제가 계획대로 추진될 경우 연말까지 계획목표를 달성할 수 있을 것으로 예상합니다. 
</p>
<p style="padding-left:1.2em">  연구지원사업은 정보자료지원, GIS사업, 전산사업 등을 차질 없이 수행하여 연구과제사업 및 부대사업을 지원하고 있습니다. 
</p>
<p style="padding-left:1.2em">  연구기반사업은 GRI 웹뉴스 43회, GRI 홍보물 2회 등을 수행하여 현재 62% 진행 중에 있습니다. GRI 웹뉴스의 낮은 실적, 이게 좀 낮게 나와 있습니다마는 이것은 발간기준을 원래 당초 이슈별 발간에서 너무 많은 발간이라고 하는 지적들이 있어서 주별 통합해서 발간하는 형식으로 배포방식을 바꿈에 따라서 횟수가 줄어들었지만 내용에 있어서 실적이 줄어든 건 아니라고 생각합니다. 각 단위사업별 구체적인 추진실적은 부록에 상세히 보고 올렸기 때문에 필요하시면 참고를 부탁드리겠습니다.
</p>
<p style="padding-left:1.2em">  그러면 2009년도 주요 연구사업실적을 중심으로 해서 좀 더 상세하게 보고를 올리도록 하겠습니다. 유인물 15쪽부터 29쪽이 되겠습니다. 주요 연구사업실적은 우리 원이 금년도에 수행완료 또는 수행 중인 연구과제사업, 연구부대사업 중 모두에 보고드린 금년도 연구사업 10대 분야 26개 대과제와 관련하여 총 112개 연구성과를 중심으로 보고드렸습니다. 저희 연구원이 연간 수행하고 있는 연구과제 숫자는 대충 300개 가까운 숫자에 이르는데요, 이걸 다 보고하기는 어렵고 뒤에 첨부자료로 첨부했고요. 그중에서 112개의 연구성과를 중심으로 본 보고자료에 실었습니다. 물론 이외에도 경기도 화장시설 건립 모형연구라든가 부담금제도 개선방안, 경기도 주요 도정시책 효과에 대한 31개 시군별 연구한 조사 등 모두 경기도 도정현안에 대응한 다양한 연구가 있었습니다마는 이걸 전부 다 보고드리지 못한 것을 아쉽게 생각합니다.
</p>
<p style="padding-left:1.2em">  먼저 15쪽 자치행정분야의 실적에 대해서 보고드리겠습니다. 자치행정분야는 금년도…….
</p>
<p><b>○ 위원장 김대원 </b> 원장님!
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 
</p>
<p><b>○ 위원장 김대원 </b> 분야별은 생략하시고요. 그건 자료로 다 제출된 걸로…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇게 해주시면 제가…….
</p>
<p><b>○ 위원장 김대원 </b> 연구실적에 대해서는 위원님들이 세부자료로 별도로 다 요구하셔서…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그럼 제가 특히 강조할 것만 부서별로 하나씩만 말씀드리고 가겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 16쪽 지방자치분야와 관련해서는 지방행정체계 개편에 대한 전문가 의견조사 연구에서 정치ㆍ행정전문가 151명 중 74.8%가 행정구역 개편은 자치단체 간 자율적 통합을 지지한다는 조사결과를 발표하여 중앙정부 주도 행정구역 개편의 전향적 방향모색을 이끌어냈다고 평가를 합니다. 이게 사실은 이번에 지방자치제도 개혁하는데 새로운 방향을 제시한 노력의 하나가 아니었나 싶고요.
</p>
<p style="padding-left:1.2em">  그다음에 도시지역분야는 GTX 건설에 따른 경기도 공간개발 전략구상 연구를 통해서 경기도의 GTX 건설사업과 관련한 수도권 및 경기도의 공간구조 개편 효과분석 및 역세권 개발확대 전략을 수립 제시하여 지금 경기도가 적극적으로 추진하고 있는 GTX와 수도권 교통통합정책을 뒷받침한 것이 아마 특이한 사항이 아닌가 하는 생각이 들고요. 
</p>
<p style="padding-left:1.2em">  그다음에 교통정책분야는 경기도 도시철도사업의 활성화 방안이라는 연구를 통해서 GTX 추진과 관련하여 행정조직 개편, GTX를 포함한 간선철도와 연계하는 도시철도 건설 방안 및 경기도 도시철도 기본계획 수립방향을 제시하였고 이와 같은 연구결과는 내년도 경기도 도시철도 기본계획 수립에 기초자료로 활용될 수 있을 것으로 생각합니다. 
</p>
<p style="padding-left:1.2em">  환경정책분야는 저탄소 사회형성을 위한 지역의 실천전략 연구를 통해서 저탄소사회로의 진입을 위해 크게 지속가능한 인프라, 녹색경제 및 생활양식 등 세 부분의 혁신주제를 설정해서 제시했고 세부적으로 저탄소형 공간구조, 녹색물류, 그린빌딩과 그린에너지, 녹지, 자원순환, 탄소배출권, 그린비즈니스, 녹색일자리, 산림의 탄소경영, 도시농업, 탄소포인트제, 기후변화 교육 및 홍보 등 지역의 저탄소화에 중요한 12개 실천과제를 선정하여 각각에 대한 동향, 쟁점, 사례를 분석하고 실천방안을 제시하였습니다. 이것은 저희 환경정책분야에서 중점과제로 실행한 과제인데 휴식시간에 이 자료를 위원님들한테 배포해 드리면 좋을 것 같은데, 그렇게 해주시고요. 
</p>
<p style="padding-left:1.2em">  산업경제분야는 여러 가지 과제를 많이 했습니다마는 특히 경기도 신성장동력 육성전략에 대한 연구를 통해서 경기도의 신성장동력의 발굴 및 선정, 주요 선진국 사례연구를 통해서 어떻게 하면 경기도에 3만 불 시대를 주도해 갈 산업육성전략 및 신성장동력산업을 육성할 것인지에 대한 로드맵을 제시할 예정으로 연구가 진행되고 있고요.
</p>
<p style="padding-left:1.2em">  사회문화분야에서는 여러 가지 연구를 했습니다마는 최근에 경기도 전통주 관광자원화 방안연구를 시행해서 막걸리 열풍과 관련해서 우리나라 전통주의 현황 및 내용, 국내외 전통주관광 성공사례, 관광자원화에 따른 기대효과를 검토하여 포천막걸리와 더불어 가평의 잣막걸리, 연천의 율무막걸리 등 기능성 탁주까지 경기도 전통주 관광자원화의 과제를 제시한 것이 특이할 만한 사항이라고 생각합니다.
</p>
<p style="padding-left:1.2em">  다음으로 수도권정책분야는 역시 중요한 연구를 많이 했습니다마는 중국 이전 기업의 실태분석에 근거한 기업지원정책 방향이라는 연구를 통해서 중국에 이전한 21개 기업에 대한 심층적 실태분석을 통해서 도내 군사보호시설, 상수도보호시설 및 수도권정비계획법 등 규제에 따라 중국으로 이전한 기업이 국내로 돌아올 수 있는 규제완화 등 지원정책의 구체적 방향을 제시한 바가 있습니다. 
</p>
<p style="padding-left:1.2em">  다음으로 물환경분야는 팔당물 수질개선 문제를 중심으로 해서 그동안 많은 노력을 했고 우리 김연제 박사는 KIST에서 파견해서 저희가 모셔 가지고 지금 센터장으로 일을 하고 있습니다.
</p>
<p style="padding-left:1.2em">  통일ㆍ동북아분야의 특이할 만한 연구는 북한이탈주민 정착지원 및 경제적 자립을 위한 경기도 정책방안 연구를 통해서 북한이탈주민의 경제활동 실태, 기존 정책의 한계 및 과제를 분석하고 경제적 자립을 위한 정책모델 개발을 통해서 북한이탈주민의 경제적 자립을 위한 정책추진방향을 제시했습니다. 특히 금년도에는 도의회 제1호 의안으로 발의된 경기도 남북교류협력의 증진에 관한 조례 전부개정으로 향후 우리 원의 관련분야 연구수요가 증가할 것으로 전망되어 어느 때보다 더욱 남북교류문제에 대한 연구를 강화할 계획으로 있습니다.
</p>
<p style="padding-left:1.2em">  의정연구분야는 금년 첫해에 출범해서 애를 썼습니다마는, 인력 충원과 이런 문제로 인해서 많은 연구를 하지 못했습니다마는 특히 특이할 만한 연구는 지방의원선거제도와 지방자치역량에 관한 연구를 통해서 공직선거법 및 관련 법령ㆍ제도 분석, 지방의원선거제도와 자치역량의 상관관계 분석 그리고 제도적 측면의 쟁점과제 분석을 통한 지방정치 엘리트의 충원 여건 확보 및 자치역량 제고방안을 제시할 예정으로 있습니다. 그리고 최근에 진행되고 있는 거는 경기도의회 전략적 홍보활동 구축을 위한 미디어 보도분석 연구를 지금 진행하고 있습니다. 
</p>
<p style="padding-left:1.2em">  이상 너무 주마간산(走馬看山)이 됐습니다마는 2009년도 연구사업계획 진행상황을 간략히 보고 올렸고요.
</p>
<p style="padding-left:1.2em">  유인물 33쪽부터 36쪽에 2010년도 연구사업계획에 대해서 보고드리겠습니다. 먼저 33쪽 2010년도 연구사업목표 및 연구사업분야별 과제에 대해 보고 올리겠습니다. 우리 원은 아까도 말씀드렸습니다마는 우리 원의 비전과 3대 미션 및 6개 전략의 성공적 추진을 위해서 2010년도 연구사업목표를 민선5기 경기도정 비전ㆍ목표ㆍ중점과제의 발굴 및 지원, 수도권의 경쟁력 강화를 위한 기반연구 주도, 저탄소녹색성장 대응 정책연구를 선도하는 그런 방향으로 목표를 설정했습니다. 특히 민선5기 경기도정과 관련해서는 내년에 새로운 도정이 출범할 것에 대비해서 경기도가 나아갈 방향과 정책과제를 발굴하는 그런 연구가 되겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 이와 같은 연구사업목표의 달성을 위하여 연구분야를 6대 분야로 세분하고 주요 대과제 24개를 선정해서 이를 중심으로 연구사업을 추진할 계획입니다. 6대 분야 24개 대과제에는 의정ㆍ행정분야의 공공기관ㆍ공기업 평가 선진화 등 4대 과제, 도시ㆍ교통분야의 수도권 광역급행철도 연계 도시ㆍ교통정책 등 4대 과제, 환경ㆍ물분야의 기후변화ㆍ녹색성장 대응 환경ㆍ물정책 등 4대 과제, 산업ㆍ경제분야의 신성장동력산업의 글로벌 거점화 등 4대 과제, 수도권ㆍ동북아분야의 세계 대도시권 지역연구 등 4대 과제, 문화ㆍ복지분야의 녹색관광산업 육성 등 4대 과제가 포함되어 있습니다.
</p>
<p style="padding-left:1.2em">  다음 34쪽 2010년도 연구사업 총괄에 대해 보고드리겠습니다. 2010년도 연구사업도 2009년도와 동일하게 연구과제사업 등 4대 단위사업으로 구분하여 추진하겠습니다. 특히 연구과제사업에 포함된 168개 과제는 앞쪽에서 제시한 연구사업목표와 분야별 과제를 중심으로 내년도 대외여건의 변화를 반영하여 추진할 예정입니다.
</p>
<p style="padding-left:1.2em">  다음 2010년도 연구사업 6대 분야 24개 과제별 계획된 기본과제와 정책과제 목록은 자료로 대신하겠습니다. 오늘 감사의 목적이 2009년도 연구성과에 대한 감사임에 비추어 내년도 사업계획은 자료로 대체하는 것을 양해해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음 부설 경기과학기술센터 업무에 대해서 간략히 보고 올리겠습니다. 유인물 39쪽부터 41쪽이 되겠습니다. 먼저 39쪽 경기과학기술센터의 일반 현황에 대해 보고드리겠습니다. 경기과학기술센터는 경기도 기술개발사업의 효율적 수행과 성과관리, 정책연구와 사업관리의 통합추진으로 경기도 과학기술정책의 시너지효과 창출을 목적으로 지난해 8월 29일 개소하였습니다. 
</p>
<p style="padding-left:1.2em">  경기과학기술센터의 인력은 소장 1명, 직원 7명 그리고 본 원 파견 연구직 2명 등 총 10명이 근무를 하고 있습니다. 부족한 인력은 도와 상의해서 앞으로 추후 보강해 나갈 계획입니다. 
</p>
<p style="padding-left:1.2em">  경기과학기술센터의 총 수입은 249억 5,000만 원이고, 수입항목은 고유목적사업수입이 전체의 85.4%인 213억 원, 고유목적사업 외 수입이 0.6%인 1억 4,800만 원, 이월금이 14%인 35억 200만 원이며 지출항목으로는 기술개발사업이 전체의 93.3%인 232억 7,100만 원, 과학기술진흥사업이 0.6%인 1억 4,900만 원, 사업운영비가 5.1%인 12억 9,000만 원, 지원 및 기타가 1.0%인 2억 4,000만 원에 해당됩니다. 
</p>
<p style="padding-left:1.2em">  다음은 40쪽 2009년도 경기과학기술센터의 사업분야 및 실적에 대해서 보고드리겠습니다. 경기과학기술센터의 사업분야는 크게 경기도 기술개발사업 관리와 과학기술 정책연구 및 진흥사업으로 구분할 수 있습니다. 경기도 기술개발사업 관리는 경기도 전략산업의 경쟁력 강화를 위하여 수요조사 및 사전기획에 의하여 기술개발 과제를 발굴 지원하는 사업입니다. 2009년도 사업계획서 공모결과 전략산업기술개발 19과제 등 총 77개 과제가 선정되었습니다. 과학기술 정책연구 및 진흥사업은 과학기술 정책연구, 익년도 기술개발사업 기획 그리고 네트워크 사업으로 구분이 되는데 2009년도 과학기술 정책연구는 위탁과제 1건, 자체연구 1건, 세미나 17회를 완료 또는 개최하였으며 익년도 기술개발사업 기획을 위한 수요조사 결과 12개 산업분야 184개 과제가 접수되어 사업기획 단계에 있음을 보고드립니다.  
</p>
<p style="padding-left:1.2em">  다음 쪽이 되겠습니다. 경기과학기술센터 사업목표와 2010년도 추진계획에 대해 보고드리겠습니다. 2010년도 경기과학기술센터의 사업목표는 경기도 기술개발사업 관리ㆍ평가ㆍ지원 체계의 구축과 사업관리의 내실화 및 효율화, 우수과제 발굴 지원을 통한 기업경쟁력 및 지역경제 활성화 유도, 과학기술분야 정책연구기능 강화로 경기도 과학기술 비전 제시 및 정책기획 지원 그리고 산학연 기술혁신 네트워크의 지속적인 확대로 지방과학기술 진흥으로 설정하였습니다. 2010년도 경기과학기술센터 사업추진 계획은 허락해 주신다면 자료로 대신하겠습니다. 
</p>
<p style="padding-left:1.2em">  이상으로 주요 업무보고를 마치도록 하겠습니다. 위원 여러분! 경청해 주셔서 대단히 감사합니다.
</p>
<p>업무보고서
</p>
<p><b>○ 위원장 김대원 </b> 원장님 수고하셨습니다. 들어가서 좌석에 앉으셔도 됩니다. 다음은 감사를 위한 질의 답변 순서가 되겠습니다. 감사의 효율적인 진행을 위하여 질의는 일문일답으로 하되 질의시간을 제한하도록 하겠습니다. 우선 위원님 한 분당 15분씩 시간을 드리고 추가질의는 1회에 한하여 5분을 드리도록 하겠습니다. 그리고 본질의 후에 보충질의를 해주시기 바랍니다. 원활한 감사진행을 위해 부득이하게 시간제한을 두게 된 점 널리 양해해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  또 질의에 앞서 위원장으로서 한 가지 부탁의 말씀을 드리겠습니다. 위원님들의 질의에 대하여 원장님의 답변이 어려울 경우 업무담당 부장 및 센터장 등 실무자가 답변을 하여도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후 발언대에 나와서 소속과 직, 성명을 분명히 밝히고 답변해 주시기 바랍니다. 또 아울러 원활한 감사진행을 위해서 원장님께서는 앉은 자리에서 준비된 마이크로 답변을 하셔도 됩니다. 
</p>
<p style="padding-left:1.2em">  그러면 질의를 시작하겠습니다. 질의하실 위원님께서는 거수로 신청해 주시기 바랍니다. 이승철 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이승철 위원 </b> 오늘 이렇게 감사를 준비해 주신 원장님 이하 여러분들께 진심으로 감사를 드립니다. 이번 행감 자료로 제가 신청한 연구원들의 연구용역 사업에 대해서 제가 쭉 자료를 분석해 봤습니다. 좀 부적절하게 연구비가 사용된 부분이 있어서 제가 그 부분에 대해서 지적을 드리고자 합니다. 
</p>
<p style="padding-left:1.2em">  우선 원장님께 질문드리겠습니다. 우리 연구과제에 대한, 연구원들한테 배분하는 과정은 어떤 형식으로 배분하는 겁니까? 연구과제 수가 연구원들 보니까 너무 과다하게 가신 분들이 여러 분 계시더라고요. 그 부분에 대해서는 어떤 식으로 연구과제를 배분하셨나 여쭤보는 겁니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우선은 기본ㆍ정책연구과제는 연구원들의 자체적인 판단에 의해서 시작을 하고요. 그 외에 연중에 진행되는 과제는 도나 위탁처에서 요청이 오면 그걸 분야별로 각 부서에서 판단을 해서 어떤 박사가 적절하게 이를 대응할 수 있는지를 판단합니다. 그런 다음에 연구심의위원회를 거쳐 가지고 적절성을 판단해서 하는 게 좋다 그러면 저는 그것에 대해서 일단 결재를 합니다마는 그런 과정에서 일부 박사들한테, 모든 박사들에게 균등하게 가지 않는 현상이……. 
</p>
<p><b>○ 이승철 위원 </b> 알겠습니다, 무슨 얘긴지. 그런데 제가 여기 요청한 자료에 보시면 특별하게 네다섯 분에게만 지금 과제가 굉장히 많이 가 있습니다. 여섯 과제, 같은 기간 동안에 여섯 과제를 소화하고 있습니다, 책임연구원이. 어떤 분은 한 가지밖에 안 하는데 여섯 가지씩 소화를 하고 계십니다, 현재. 그러면 전문가니까 그쪽으로 주셨다고 말씀을 하시는데 그 기준을 연구회에서, 그럼 원장님 주재하에 하시는 겁니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 연구심의회는 원장 주재하에 하는 건 아닙니다. 
</p>
<p><b>○ 이승철 위원 </b> 그럼 어느 분이 주재하시는 겁니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 선결로 하고 부원장 주재하에 하고요……. 
</p>
<p><b>○ 이승철 위원 </b> 부원장님 주재하에 하시는 겁니까? 그럼 부원장님께 묻겠습니다. 지금 연구원들 네다섯 분에게 집중적으로 가 있거든요. 그 부분은 어떻게 설명하실 겁니까? 간략하게만. 
</p>
<p><b>○ 부원장 조응래 </b> 부원장 조응래입니다. 지금 과제가 6건 정도 되시는 분들, 945쪽하고 946쪽 보시면 나오는데 이게 순간적으로 그 분야를 지금 각각 담당을 하고 있습니다. 그러다 보니까 신기동 박사 같은 경우도 유통이나 이런 거 관련된 과제는 다른 사람이 하는 거보다는 조금 과제업무가 있더라도 신기동 박사가 담당하는 게 훨씬 더 효율적으로 빠르게 정리가 될 수 있기 때문에 그런 차원에서 좀 집중이 되는 경우들이 있는데 저희가 개략적으로는 다 안분(按分)을 하는 구조로 가고 있습니다. 그래서 2009년 같은 경우는 평균 한 4.2건인데 그런 건을 되도록이면 유지를 하는 걸로 체크를 하면서 진행하고 있습니다. 
</p>
<p><b>○ 이승철 위원 </b> 같은 시기에 거의 비슷한 자료로 연구를 한다는 게 문제입니다. 지금 보시면 연구과제 수가 그렇게 많으면서도, 예를 들어 연구하고 계신 내용을 보시면 한 연구원이 거의 비슷한 자료로 계속 집행되는 예산이 많게는 2억 정도에 대한 연구비가 책정이 됐습니다. 그 정도로 한 연구원한테 이렇게 집중되게 가 있는 과정이, 또 같은 기간 안에 비슷한 내용에 대해서 수행과제를 줬다는 것이 제가 지금 문제로 삼는 거고요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 말씀을 좀 올려도 되겠습니까? 걱정하시는 부분에 대해서. 
</p>
<p><b>○ 이승철 위원 </b> 네. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저도 위원님과 마찬가지로 연구과제가 편중되는 것에 대해서 걱정을 많이 하고 그런 일이 안 생기도록 노력을 합니다마는 대체로 보면 자기 전문분야 일을 하기 때문에 일종의 시너지효과가 있는 것이죠. 주제를 많이 한다고 하지만 풀로, 말하자면……. 
</p>
<p><b>○ 이승철 위원 </b> 원장님, 죄송합니다. 우리 연구원들이 지금 총 몇 명입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 정규직이 53명.
</p>
<p><b>○ 이승철 위원 </b> 53명이죠? 그런데 전문적인 사람이 한 사람밖에 없습니까? 그 분야에 대해서 전문가는 한 사람입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이 경우에는, 여기 지금 특정한 경우를 말씀을 드린다고 하면 신기동 박사 같은 경우 서비스업 부분은 이 사람이 주로 하는 일입니다. 그래서 불가피하게 이리로 가는 경향이 있는데 연구 숫자가 많아지면 경우에 따라서는 외주도 많이 하고요. 외부에서 아웃소싱을 많이 해서 부담을 낮추도록 노력도 하고, 본인이 그거는 판단해서 할 수 있도록 연구원에서……. 
</p>
<p><b>○ 이승철 위원 </b> 제가 실명을 거론하지는 않는데 지금 여기 계신 분들이 전부 유능하시기 때문에 연구과제를 많이 받으신 건데, 현재 53명이라는 연구원이 계시는데 부득이 그분들한테만 이렇게 많은 연구과제가 주어져서 그분들이……. 제가 말씀드리는 건 연구비가 계속 한 사람한테 집중돼 있지 않느냐 하는 것을 지적드리고 싶은 겁니다. 
</p>
<p style="padding-left:1.2em">  그럼 연구비 내역에 대해서 여쭤보고 싶습니다. 연구비 내역 산출에 대해서는 어떻게 뭐를 근거로 하십니까, 예산액은? 어느 분이 하시는 겁니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 연구심의회 위원장이…….
</p>
<p><b>○ 부원장 조응래 </b> 부원장 조응래입니다. 제가 답변드리겠습니다. 연구위원회에서 기본적으로 정책과제라든지 이 부분에 대한 과제심사를 합니다. 그래서 과제의 필요성 이런 것들을 하고 저희가 과제를 선정하는데 도에서 의뢰를 한다든지 저희가 자체적으로 필요한 내용들을 중심으로 과제를 선정하고 적정한 과제비는 연구위원회에서 다 검토를 합니다. 그래서……. 
</p>
<p><b>○ 이승철 위원 </b> 연구위원회 주재하시는 분이 누구십니까? 
</p>
<p><b>○ 부원장 조응래 </b> 제가 주재를 하고 있습니다. 
</p>
<p><b>○ 이승철 위원 </b> 부원장님께서 또 하시는 거고요? 그럼 부원장님께 여쭤보겠습니다. 제가 과제별 예산집행 현황을 받았습니다. 그 현황에 보면, 제가 대충 봐서, 당초예산 금액하고 예산 배정액이 있고 집행액이 있습니다. 그런데 같은 기간이면서 연구비, 당초예산액에 세목별을 보시면 운영수당, 국내여비, 국외여비, 재료비, 업무추진비 쭉쭉 있지 않습니까? 애초에 그걸 어디서 책정해 주시는 겁니까? 
</p>
<p><b>○ 부원장 조응래 </b> 연구위원회에서 조정을 합니다. 
</p>
<p><b>○ 이승철 위원 </b> 그러면 제가 의문 드는 거는 같은 기간 안에, 예를 들어 국내여비 같은 경우에도 같은 기간 안에 산출근거를 어떻게 잡고 하셨는지, 어디는 30만 원인데, 같은 기간 안에. 어느 쪽은 300만 원입니다, 국내여비 자체만. 국외여비도 아니고. 거기는 무슨 근거로, 같은 기간 안에. 
</p>
<p><b>○ 부원장 조응래 </b> 같은 기간이라 할지라도 그게 과제가 현장출장이 많은 과제에 대해서는…….
</p>
<p><b>○ 이승철 위원 </b> 제가 다시 말씀……. 그럼 현장출장이 없는 경우라고 얘기하셨을 때 1년간인데 1년간 들어가는 교통비가 40만 원 정도 되는 사람도 있고 어떤 분은 1년간 400만 원도 있습니다. 그러면 어떤 분은 연구과제를 1년 동안 했는데 1년 내내 집에서만 연구과제를 합니까? 
</p>
<p><b>○ 부원장 조응래 </b> 조금 설명을 드리겠습니다. 예를 들어서 만약에 916쪽하고 917쪽에 보시면 국내여비라든지 업무추진비 이런 부분들이, 저희가 전체적으로 정책과제라는 것은 보통 한 900만 원에서 1,000만 원 수준에서 예산을 잡도록 돼 있습니다. 그건 연구진들이 다 알고 있고요. 그래서 그 범위 내에서 개략적으로 여비가 많이 필요한 과제다, 아니면 이건 자문회의가 많이 필요한 과제다 그러면 그 내용에 맞춰서 운영수당은 916쪽에 있는 것은 운영수당이 90만 원이고 국내여비는 한 45만 원인데 917쪽의 경우는 운영수당은 같지만 국내여비는 72만 원 정도로 연구자가 이 연구를 수행하기 위해서 얼마나 현장을 다녀야 되는지 이런 것들을 판단하고 그런 부분들이 연구위원회에 올라오면 연구위원회에서 적정성 여부를 검토하는 그런 과정으로 진행되고 있습니다. 
</p>
<p><b>○ 이승철 위원 </b> 그럼 888페이지 봐주세요. 이게 같은 기간인데요. 3월 달부터 8월 달까지 5개월간 교통비가 150만 원입니다. 그리고 밑에 거는 8개월간에 40만 원 정도입니다. 888, 889 보시면, 제가 의문 나는 점이 이것뿐만이 아니에요. 일반 연구비 쓴 내용 일일이 다는 확인을 못했거든요. 몇 가지 해본 거에 나온 걸 보시면 과연 연구과제를 놓고 어떤 식으로 평가를 했기에 금액 차이가 이렇게 많이 날 수 있느냐? 그럼 1년 내내 방 안에서만 연구과제를 하신 분이 계시고 어떤 분은 1년 내내 바깥에 나가서만 연구과제를 한 분이 계시다는 쪽으로밖에 제가 이해가 안 되거든요.
</p>
<p><b>○ 부원장 조응래 </b> 그런 내용들은, 지금 888쪽 같은 경우는 이 과제도 마찬가지로 비상임연구위원이라고 그래 가지고 행정체제 개편에 따른 비용을 산정하는 데 있어서, 외부전문가와 같이 연구했습니다. 그래서 그 비용이 700만 원 정도 소요가 됐고 그 700만 원을 빼고 나면 결국 이 과제도 940만 원 정도의 예산을 소요해서 진행을 한 그런 내용이 되겠습니다. 그래서 저희가 정책과제라고 하는 것들은 기본적으로는 1,000만 원을 갖고서 인쇄비가 보통 290만 원 정도 이렇게 진행이 되기 때문에 그 나머지 돈을 가지고 자문회의라든지 현장출장이라든지 그런……. 
</p>
<p><b>○ 이승철 위원 </b> 제가 말씀드리는 건 여비를 말씀드리는, 국내여비요. 여비가 뭐를 하는, 여비 자체가 내용이 뭡니까? 
</p>
<p><b>○ 부원장 조응래 </b> 이런 비용을 갖고, 만약에 888쪽 같으면 여기서는 국내여비가 타 사례보다 좀 많은데 지방행정체제 개편……. 
</p>
<p><b>○ 이승철 위원 </b> 거기뿐이 아니에요. 거기만 많은 게 아니라……. 부원장님! 자꾸 그런 식으로 설명하시지 말고, 다른 데도 많아요. 지금 한두 군데가 아니기 때문에 그냥 아무 데나 보고 한 건데, 여러 군데가 많으니까 그렇게 설명하시지 마시고 정확하게. 그리고 또 한 가지 운영수당이나 이런 부분은 어떻게 평가를 하시는 겁니까, 운영수당은? 
</p>
<p><b>○ 부원장 조응래 </b> 운영수당은 이 과제를 추진하면서 자문회의가 몇 회 필요하다, 그래서 어떤 사람들하고 자문을 할 것이다 하는 내용들을 연구위원회에서 얘기를 해서 운영수당도 결정이 됩니다. 
</p>
<p><b>○ 이승철 위원 </b> 운영수당 같은 차이도 제가 보면 이게 어떤 방식으로 어떻게 위원회에서 결정했는지는 모르겠지만 이렇게 많은 차이, 운영수당 차이도 굉장히 많아요. 몇백만 원 주는 분이 있는 반면에 어디는 몇십만 원만 주는 경우도 있고. 그래서 이런 부분에 대해서 굉장히 의문이 많이 간다 하는 쪽으로 말씀을 드리고요. 예를 들어 여비 같은 경우에는 제가 봤을 때 국외여비라든가 국내라든가 이렇게 따로따로 돼 있어서 국외 쪽을 꼭 갔다와야 하는 입장이라서 한다면 이해를 하겠는데 같은 국내여비 가지고도 이런 차이가 많다는 거는 다시 한 번 세심하게, 당초예산 잡을 때 좀 세심한 배려가 있어야 되지 않겠느냐. 그리고 이게 도민의 세금으로 나가는 거거든요. 이 부분을 부원장님이나 원장님께서 각별히 하시고 따져주셨으면 하는 생각을 갖습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 감사하고요. 적절한 지적이 아니신가 싶습니다. 저희도 이거는 규명을 해보고 싶은데요, 해야 될 것 같아요. 그런데 지방출장도 이게 출장의 내용이 다르지 않은가 싶은 생각도 들어요. 조성호 박사 같은 경우에는 지방에 가서 지방협의회 같은 걸 많이 한 케이스가 아닌가 하는 생각도 드는데, 본인이 와 있는데…….
</p>
<p style="padding-left:2.4em">    (좌승희 경기개발연구원장, 관계직원에게)  
</p>
<p style="padding-left:1.2em">  왜 이렇게 많이 들어갔죠, 150만 원? 
</p>
<p style="padding-left:2.4em">    (「시군 통합 그거 때문에 많았습니다…….」하는 관계직원 있음)
</p>
<p style="padding-left:1.2em">  각 지방을 순회하면서 이 프로젝트를 진행하다 보니까 그런 문제가 생긴 것 같은데 지금 위원님께서 지적하신 문제에 대해서 저희가 다시 재검토하고 그래서 보고를……. 
</p>
<p><b>○ 위원장 김대원 </b> 원장님, 이 부분에 대해서는 협의하셔 가지고 세부적인 자료를 제출하시든가 나중에 보충발언 때 이 부분에 대해서 심도 있게 더 하시도록 하겠습니다. 계속 하셔야…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 설명을 나중에 따로 문서로 해서 올리든가 그렇게 하겠습니다. 
</p>
<p><b>○ 이승철 위원 </b> 아직 제가 말씀드릴 게 많이 남아 있는데 추가질문으로 하겠습니다. 이상 질의를 마치겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 이승철 위원님 수고하셨습니다. 고영인 위원님 질문해 주시기 바랍니다. 
</p>
<p><b>○ 고영인 위원 </b> 안산 출신 고영인 위원입니다. 행감 준비하시느라 고생들 많이 하셨고 아까 원장님 자랑하셨듯이 조성호 박사님을 비롯해서 행정체제 개편에 대한 연구와 적극적인 대응 이런 것들이 불합리한 행정체제 개편에 상당히 영향을 준 것 같습니다. 
</p>
<p style="padding-left:1.2em">  오늘 제가 크게 두 가지를 하겠는데요. 일단 경기국제보트쇼 이거에 대한 평가시스템의 문제에 대해서 먼저 문제제기를 하겠습니다. 오늘 황상연 연구원은 안 왔죠? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 그 공동연구를 했던 이상훈 박사가 여기, 경제사회연구부장이 와 있습니다. 
</p>
<p><b>○ 고영인 위원 </b> 그러면 이따 필요하면 이상훈 박사가 답변을 해주셨으면 좋겠습니다. 어디 계시죠? 앞자리로 나오셔 가지고……. 제 요구자료 91쪽부터 한번 같이 좀 보겠습니다. 제가 지적하려고 하는 건 일단 우리가 다른 기본연구과제라든가 정책과제의 내용은 각 연구원의 소신과 또 그 연구의 객관성에 따라서 그것은 반영되면 된다고 생각하고 있습니다. 그러나 특히 집행부의……. 자리에 일단 앉아 계세요. 좀 이따 필요할 때 하겠습니다. 집행부의 여러 가지 행사 이런 것에 대한 평가용역은 다른 기본ㆍ정책연구과제하고는 좀 다른 것 같습니다. 왜냐하면 이 평가는 굉장히 객관성이 중요하게 작용이 돼야 되고. 그래서 이거는 용역 발주자의 입장을 얼마만큼 반영하느냐의 문제로 끝나는 게 아니라 이 평가결과가 그 행사의 지속 여부 내지는 개선점에 심대하게 영향을 주기 때문에, 그것이 도민들에게 직접적인 영향을 주는 거예요. 그러니까 예산문제에 있어서도 그렇고 행사의 효과가 어떻게 나타나느냐에 있어서도 그렇고 상당히 영향을 줍니다. 그런 측면에서 객관성 확보가 굉장히 중요한데요. 일단은 이번에 보트쇼를 하고서 평가서를 제출했는데 현장조사를 위한 것들을 했다고 했습니다. 
</p>
<p style="padding-left:1.2em">  이상훈 박사, 잠깐 앞으로 좀 나오시죠. 실무적인 걸 먼저 물어볼게요. 현장조사를 위해서 수행한 걸 간략하게만 몇 가지 얘기해 보세요, 평가를 위한.
</p>
<p><b>○ 경제사회연구부장 이상훈 </b> 경제사회연구부장 이상훈입니다. 현장조사를 위해서 행사가 시작되기 전에 진행되는 과정을 연구진이 가서 체크를 했고요. 그다음에 행사가 진행되는 과정에 한편에서는 일반 관람객 입장한 숫자도 저희들이 파악을 했고 그다음에 참가기업들, 해외 참가기업, 투자자/바이어에 대한 설문조사가 진행이 됐습니다. 그리고 해외자문관 등 전문가에 대한 현장 심층인터뷰 이런 내용들을 행사 전 아니면 진행과정 중에 저희들이 수행했습니다. 
</p>
<p><b>○ 고영인 위원 </b> 좋습니다. 그런 조사를 했는데 예를 들면 설문조사를 했지 않습니까? 
</p>
<p><b>○ 경제사회연구부장 이상훈 </b> 네. 
</p>
<p><b>○ 고영인 위원 </b> 관람객 수를 측정도 하고 관객과 참가기업, 전시업체, 바이어들에 대한 설문조사를 했는데, 뒤에 설문조사 내용들이 쭉 있어요. 그런데 여기에 응답자 확인용으로 본인 이름과 회사명 이런 걸 반드시 기입해야만 이 결과물을 만들 수 있나요? 
</p>
<p><b>○ 경제사회연구부장 이상훈 </b> 반드시 꼭 그렇지는 않습니다. 특히 기업체 관련된 설문조사는 개인 기업의 비밀사항이 될 수 있기 때문에 저희들이 요청을 합니다만 본인이 굳이 안 적겠다고 했을 때는 저희들이 적지는 않습니다. 또 특히 동시에……. 
</p>
<p><b>○ 고영인 위원 </b> 그러니까 거기 113쪽 같은 경우에 보트쇼 바이어/투자자 설문조사에도 보면 상세하게 적게 돼 있어요. 그런데 제가 왜 이 질문을 하냐면 지난번에 제가 김문수 지사한테 도정질문을 통해서 보트쇼의 전반적인 문제제기를 했는데 혹시 그 내용을 알고 계세요? 
</p>
<p><b>○ 경제사회연구부장 이상훈 </b> 네, 알고 있습니다. 
</p>
<p><b>○ 고영인 위원 </b> 거기에서 보면 우리가 바이어/투자자들이 2008년도에 190개 업체가 참가를 했어요. 그래 가지고 올해 2009년도에 재방문을 하겠냐라는 설문조사에 90%가 응답한 걸로 돼 있습니다. 그런데 실제 재방문율이 얼마나 됐는지 알고 계신가요? 빨리 진행하기 위해서 제가 얘기할게요. 10%, 18개 업체가 방문했어요. 그러니까 내년에 다시 오겠다고 90%가 답변을 해놓고 실제 온 업체는 10%예요. 이거는 제가 볼 때 무슨 얘기냐면 이런 설문조사를 할 때, 이 바이어 업체들에게 경기도에서 여비, 올해 같은 경우 비행기 값으로 평균 80만 원 정도 지원을 했고 또 숙박비하고 교통비 이런 것들을 다 지원했습니다. 그러니까 그들이 여기에 와서 나름대로, 어차피 정보도 취득할 겸 여러 가지 지원혜택이 다른 대회보다 워낙 크니까 온다 이 말이죠. 그런데 와서 이 설문조사를 하는데 자기 회사명 이런 거 다 하고, 혜택은 엄청 받고 여기 응답을 할 때 아주 비판적으로만 해놨을 때 갖는 자신들의 부담들이 나는 있을 거라고 생각하는 거예요. 그렇기 때문에 응답은 다 한다 그러는 거죠. 90%가 다시 오겠다고 얘기하는 건 다 오겠다는 얘기예요. 그런데 실제 오는 건 10%밖에 안 왔다 이거지. 이건 일단 설문조사 방식에 있어서도 문제가 있다고 생각하는데 어떻게 생각하십니까? 
</p>
<p><b>○ 경제사회연구부장 이상훈 </b> 설문조사 자체는 저희들이 총 예산 한 6,000만 원 중에 한 2,000만 원을 할애해서 방문객, 기업체, 바이어들 면접조사를 하는데요. 어쨌든 본인들이 오겠다라고 90% 답을 했는데 그다음에 10% 오는 것이 어떤 문제가 있느냐라고 하는데 저희들이 차후에, 중간에도 그렇습니다마는 자문회의를 통해서 저희들은 많은 의견을 청취했습니다. 이 문제에 대해서 어떻게 판단을 하느냐라고. 그런데 이게 보니까 보트업 그다음에 특히 요트산업의 특징이라고 저희들은 파악하고 있습니다. 즉, 한국에서 그동안 요트산업이 없었고……. 
</p>
<p><b>○ 고영인 위원 </b> 아니, 간단하게 말씀해 주세요. 제가 오늘 질문의 초점이 그게 아니니까. 그러니까 다른 여러 가지 요인들과 여건이 있다는 얘기죠? 
</p>
<p><b>○ 경제사회연구부장 이상훈 </b> 네, 그렇습니다. 
</p>
<p><b>○ 고영인 위원 </b> 그런데 저는 어쨌든 전반적으로 만족도도 전체적으로 계속 떨어지고 있고, 여러 가지 이유들이 있어요. 그런데 제 얘기는 설문조사는 자신이 솔직하게 느끼는 것을 제대로 반영할 수 있도록 설문지 구성이나 형식이 돼서 그들의 현재 마음상태나 이 대회를 바라보는 평가가 제대로 될 수 있도록 형식이 갖춰질 때 올바른 평가가 이루어진다 그걸 지적하려고 하는 겁니다, 일단. 원인이 이것 때문에 안 왔다는 게 아니라 실제……. 그렇잖아요. 안 온 이유는 다른 데 있는 거예요. 그러니까 안 올 생각이 있는데 설문조사에는 다 오겠다고 한다 이거지. 그런 부분에 있어서 개선사항을 제가 지적하는 거고. 
</p>
<p style="padding-left:1.2em">  이 보트쇼를 평가하는데 제가 생각할 때 제일 중요한 거는 도 집행부에서 이 보트쇼를 통해서 얻으려고 하는 목표가 있어요. 관람객 수 그다음에 요트 전반에 대한 수출판매액, 1억 불 수출과 40만 관광객을 목표로 했죠. 그런데 이런 목표가 얼마만큼 달성됐느냐를 가지고 이 성패를 홍보한다 이거예요, 집행부가. 그런데 여기 평가에 보면 여러 가지가 있지만 이 중요한 목표지수에 대한 평가에 있어서 23만 7,000여 명의 관람객이 다녀갔다. 그다음에 몇 %죠? 그 1억 불에 대해서 직접 대답을 한 게 90% 달성을 했다 그랬어요. 1억 불 수출목표를 세워 가지고 8,900만 불이니까 거의 90%가 달성이 됐다고 했는데 이 부분에 대해서 자체적으로 검증을 해본 적 있어요? 실제 도 집행부가 이렇게 달성했다라고 얘기한 것에 대해서 그 말이 맞는지 이것에 대해서 검토해본 적 있습니까? 
</p>
<p><b>○ 경제사회연구부장 이상훈 </b> 저희들이 그 행사가 끝난 이후에 자체적으로 자문위원회를 개최했습니다. 계약건수라든지 이런 부분. 어차피 쇼가 진행되는 과정에서 계약건수가 실제 도달하는, 도착하는 거하고는 차이가 있을 수밖에 없고요. 다만 저희들이 확인을 한 것은 그 행사가 끝난 이후에, 행사기간 중에는 계약을 안 했는데 행사가 끝난 이후에 특히, 그 회사를 거명할 수는 없습니다만 모 회사의 엔진에 대해서 관심 있다 그래서 그 부분에 대해서 계약을 하려고 한다라는 그런 많은 건수가 있습니다. 그래서 그 문제는, 일반적인 외자유치도 마찬가지겠습니다만 보트쇼 같은 경우는 저희들이 그런 부분이 특히 크게, 하나의 기술 관련된 부분이 굉장히 예민하게 작용하기 때문에 또 일부 업체들은 그런 얘기도 합니다. 그 구성원이 누구냐가 더 중요하지 전체적인 액수라든지 실질적으로 참여한 기업체 수 이것은 오히려 중요하지 않을 수 있다라고 하는 그런 얘기도 하는데 저희는 한 가지 희망은 봤습니다. 한 가지 희망은 참여한 업체 중에서…….
</p>
<p><b>○ 고영인 위원 </b> 네, 알겠습니다. 그러니까 여러 가지 그런 조건에 따라서 연구를 하시는데 연구 자체를 한 걸 제가 뭐라 하려고 하는 게 아니고 지금 이 문제가 아까도 얘기했듯이 객관성 확보가 굉장히 중요한데 제가 가장 이 문제에서 지적하려고 하는 내용은 뭐냐? 도 집행부가 자체 집계를 해가지고 우리 이러 이렇게 성과를 냈다라고 제시한 것에 대해서 전혀 비판의식이 없어요. 그걸 비판적 검증을 하려고 하는 자세가 안 돼 있다는 거예요, 경기개발연구원이. 그러니까 다른 많은 연구과제를 통해서 성과를 내고 기여를 함에도 불구하고 이런, 특히 도 집행부와의 관계 문제 이런 부분으로 인해서 욕을 먹는데 저는 이런 부분들이 굉장히 안타깝습니다. 
</p>
<p style="padding-left:1.2em">  일단은 이 박사님 잠깐 들어가시고 원장님 답변을 해주시기 바랍니다. 이 관광객 수가 23만 7,000명이라고 했는데, 제가 길게는 얘기 안 하겠습니다. 제가 지난번에 도정질문을 통해서, 뭐 조용필 쇼를 통해서 3만 명 해가지고 그걸 집계에 넣었고요. 집계에 안 넣어도 관람객 수는 다 정해져 있는 건데 그걸 넣었다든가 또는 전곡항에 온 사람이 탄도항에 다시 가는데 그걸 탄도항하고 별도로 집계를 해가지고 2개를 합산했다든가 이래서 제가 볼 때 한 5~6만 명이 엉터리로 플러스가 됐다고 해서 집행부에서도 인정을 했습니다. 
</p>
<p style="padding-left:1.2em">  그다음에 이 수출계약을 했다라는 게 대부분이, 한 70~80%가 다 상담액이에요. 계약이 이루어진 게 아니고 앞으로 계약을 해볼 수 있도록 검토하겠다라는 건데 그것을 그렇게 결정을 했다 이 말이에요. 아주 도덕적 해이가 심각한 수준이죠. 거의 조작수준이라고까지 제가 질타를 했는데 이런 부분에 대해서 문제의식이 없이 집행부에서 준 자료를 그대로 연구원에서 가져다가 설문조사 정도만 해가지고 쭉 다른 평가들을 했어요. 물론 온 관객들이나 반응 같은 건 체크가 됐는데 가장 중요한 이 집행부의 목표 성과에 대한 부분들에 대해서 문제의식이 없이 그대로 갖다가 인용을 했다 이거죠. 그래도 되는 겁니까, 원장님?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그 주장에 대해서는 제가 드릴 말씀이 없습니다. 적절한 지적이 아닌가 하는 생각이 들고 위원님들이 집행부에 대해서 할 수 있는, 말하자면 모니터할 수 있는 그런 역량과 책임의 한계와 우리 연구원이 할 수 있는 건 좀 다르죠. 그런 점에서 저희가 사실은 위원님 지적하는 문제에 대해서, 도정에서 발표하는 것에 대해서 검증을 하고 또 비판적으로 검토하는 그런 일을 우리가 얼마나 잘하고 있느냐에 대해서 저 자신도…….
</p>
<p><b>○ 고영인 위원 </b> 제가 얘기하는 것은 이걸 지금 해도 되고 안 해도 되는 게 아니고요. 보트쇼에 대해서 평가를 용역을 줬잖아요. 이게 얼마입니까? 몇천만 원이죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 6,000이었나……. 
</p>
<p><b>○ 고영인 위원 </b> 6,000만 원을 들여서 평가를 하는데 관람객 수가 그렇다. 이 정도 수출을 했다라고 집행부에서 준 자료를 그냥 갖다 평가에다 해가지고 성공적이다라고 얘기하는 게, 6,000만 원을 어디다 썼습니까? 제가 얘기하는 것은 단순히 집행부와의 어떤 관계의 문제가 아니라 주어진 과제에 대해서 경기개발연구원이 해야 될 본연의 임무를 저버렸다는 겁니다, 제가 볼 때. 준 지표를 과연 그게 정확한가 검증을 하는 게 평가의 기초 아닙니까? 어떻게 그걸 갖다 그대로 인용을 하느냐 이 말이에요? 그러니까 다른 거를 다 잘 해놓고서, 특히 집행부의 어떤 공약사항이라든가 이런 주요 사안에 대한 평가에 있어서 이런 식으로 되면 이런 것들이 부각이 돼 가지고 경기개발연구원이 계속 욕을 먹는 거 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 말씀에 대해서 저도 충분히 이해가 갑니다. 그런데 지금 우리 이상훈 박사의 말에 의하면 23만 7,000명 관광객은 도에서 나온 숫자라기보다는 우리 조사에서 이렇게 나왔다고 얘기를 합니다마는 어쨌든 정확성에 대해서는 또 다른 논란이 있을 수…….
</p>
<p><b>○ 고영인 위원 </b> 실제 집계를 했고 그것을 도에 보고하고 같이 했다고 제가 들었어요. 그렇기 때문에 제가 지적한 내용 자체는 그대로 곧바로 이 집계 자체의 문제로 가는 거예요, 일단. 그러니까 40만 목표에 부응하는 게 목표가 아니라 제가 그때도 지적을 했듯이, 목표를 세우고 왜 못했느냐를 지적하는 게 아니에요. 너무 성과주의로 가다 보니까 과도한 목표를 잡고 그것을 어떻게 해서든지 채우려고 하니까 무리한 관광객 집계 그다음에 수출판매도 우리나라 요트산업의 여건으로 보면 그렇게 수출이 이루어질 수 없는 여건임에도 불구하고 1억 불을 목표로 만들고 80~90% 달성했다고 하려고 하니까 상담액을 그렇게 한다 이 말이에요. 그러니까 내실을 기해야지. 이거 악순환입니다. 또 평가를 그렇게 해놓고 잘했다. 그러면 내년에 목표가 더 올라가야 되겠죠. 그러면 다음에는 어떻게 해야 되겠어요? 또 조작을 해야 되겠지요, 그 목표에 대해서. 그러니까 제가 지적하려고 하는 것은 경기개발연구원에서 해야 될 일은 객관적인 정확한 반영을 통해서 과연 이것의 지속 여부 문제 또는 개선해야 될 문제를 정확하게 짚어주는 게 경기개발연구원의 역할이에요. 집행부는 당연히 성과를 높이려고 하는 성향이 있죠? 자기 관성이 있습니다. 그러나 여기의 역할은 다르다 이거죠. 그런데 왜 전곡항에 간 사람하고 탄도항에 간 사람이 다 대부분 중복되는데 그걸 갖다 따로 집계하고 조용필 쇼 3만 명을 왜 거기다 넣습니까? 그런 것들 자체가, 자세가 잘못돼 있다라는 걸 제가 지적하는 거고요.
</p>
<p style="padding-left:1.2em">  그래서 향후에는, 특히 이런 집행부의 행사 이거는 도민들에게 직접 영향을 주기 때문에 저는 거기에서 준 자료라든가 이런 것에 대해서 검증시스템을 정확히 가졌으면 좋겠습니다. 이것에 대해서 연구원들만이 아니라 연구평가심의회를 연 적이 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 최종보고회를 한 번 했습니다. 
</p>
<p><b>○ 고영인 위원 </b> 거기에 몇 분이나 참여했습니까? 
</p>
<p><b>○ 위원장 김대원 </b> 실무자가 나와서 답변하시죠. 이상훈 박사님. 
</p>
<p><b>○ 고영인 위원 </b> 아니, 대략만 얘기하시면 돼요. 원장님 아니면 부원장님이 참석하셨잖아요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 수탁과제 결과보고를 제가 받았습니다. 받았는데, 그거는 출판 관련된 것을 중심으로 해서 주요 결과를 보고하는 것이고 절차에 대한 상세한 것은 보지 못했습니다마는…….
</p>
<p><b>○ 고영인 위원 </b> 물론 상세한 것을 그 자리에서 원장님이나 부원장님이 다 보시기는 어렵겠지만 이런 문제에 대해서는 굉장한 경각심을 갖고 해주셨으면 좋겠고요. 그래서 이런 문제가, 다 성공이라고 해놓고 최고 집행부 수장 바뀌고 만약에 보트쇼 중단이라도 되면 나중에 책임 다 질 수 있어요, 경기개발연구원에서? 아니잖아요? 그러니까 이런 문제에 대해서 좀 더 목표에 대한, 성과에 대한 검증시스템을 정확히 갖게 해달라는 것을 주문드리겠고요.
</p>
<p style="padding-left:1.2em">  두 번째 질문하겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 마무리해 주시기 바랍니다.
</p>
<p><b>○ 고영인 위원 </b> 두 번째는 간단히 하겠습니다. 지금 연구를 하고 연구평가심의회를 열죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 고영인 위원 </b> 연구평가심의회를 여는데 지금 기본연구과제는 7명 그다음에 정책과제는 6명이 평가심의위원인데 일단 선정은 누가 하십니까, 이 대상을? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리 연구원에 평가심의위원으로 참여하는 전문가 풀이 있죠. 그것을 중심으로 해서 본인도 추천을 하고 우리 기조실에서도 점검을 해가지고 적절하다고 판단되는 분들을 선정하는 것으로 알고 있습니다. 그래서 각 개인이 2배수 정도 추천하는 것으로 알고 있고요. 그러면 그중에서 기조실이나 지휘부에서 판단해서 적절한 분을 선정해서 하고 있습니다. 
</p>
<p><b>○ 고영인 위원 </b> 그래서 보니까 제가 생각했던 것보다도, 요구자료 197쪽 거기서부터 제가 쭉 검토를 해보니까 과제성격에 따라서 착수, 중간, 최종이라든지 이런 연심회가 굉장히 알차게 진행이 되는 것 같습니다. 그래서 그 부분들은 연심회를 통해서 그런 여러 가지 객관성 확보를 위해서 노력을 하시는 게 보였고요. 
</p>
<p style="padding-left:1.2em">  제가 여기서 간단히 두 가지 정도 제기해 보려고 하는 것은 201쪽에 보면, 물론 저보다야 다 전문가들이시니까 많은 시행착오를 거쳐서 이렇게 됐다고 생각하지만 비전문가 입장에서 볼 때 제안을 드리고 싶은 거예요. 뭐냐 하면 특히 201쪽에 정책연구과제 같은 경우는 단기정책이기 때문에 이 연구성과가 정책으로 집행부에 가서 채택이 되면 집행이 되지 않습니까? 그러면 그것이 그 집행의 대상이 있죠? 보통 도민들이 될 수도 있고. 그런데 그렇다면 이것이 한번 정책과제로 결정이 돼서 집행이 되려면 거기에 따른 객관성 확보가 굉장히 중요하죠, 현실성. 그런데 여기 평가지표에 쭉 보면 분석의 합리성이라든가 연구결과의 논리적 타당성이 이 안에 대부분 들어가 있다라고는 생각하지만 제가 볼 때는 현장성을 반영하는, 그러니까 얼마만큼 이것이 나중에 현장과 괴리되지 않고 어떤 학술적이고 이론적인 것에 자칫 매몰될 수 있는 것을 방지하기 위해서는 현장성이 굉장히 강화될 때 객관성이 확보된다고 저는 생각을 해요. 그래서 기본과제와 달리 정책연구과제에 있어서는 그런, 물론 제 제안일 뿐일 수 있는데요. 현장조사 내지 현장성 반영도가 어땠는가? 그것은 현장조사라든가 또는 현장의 메커니즘들을 분석했다든가 또 여러 가지 이런 지표들을 통해서 얼마만큼 반영이 됐으면 좋겠다라는 제안을 하나 드리고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 고영인 위원 </b> 두 번째는 이 연심회가 정책과제는 6명으로 되어 있는데 그 연심회 구성원의, 지금 자체 연구원들 그다음에 공무원 한 분이 오시고 그렇게 쭉 구성이 되어 있어요. 외부전문가도 2명이 되어 있는데 대부분 다 박사님들이고 공무원이 한 분 끼는데 제가 볼 때는 사안에 따라서 현실적합성을 얼마만큼 갖느냐라고 하는 것들을 반영하려면 예를 들면 그 정책의 대상자 중에 연관성이 큰 부분, 그러니까 예를 들면 그것과 관련된 산업체의 직원이라든지 아니면 어떤 시민사회단체라든지 또는 그 대상인 소비자 중에 대표성을 가질 수 있는 분 이렇게 해서, 정책이 이런 식으로 만약에 집행부에서 채택돼서 될 때 과연 현실적으로 문제는 없겠느냐라고 하는 것들을 그 과정에서 한번 필터링을 할 수 있는 이런 것들이 연심회 구성에 된다면 현장감각이 조금이라도 더 반영이 돼서 객관성을 확보하는 데 도움이 되지 않겠느냐 이런 판단을 한번 해보는데 어떻게 생각하십니까? 
