<p><b>○ 경기개발연구원장 좌승희 </b> 우선 지적하신 건 아주 적절한 지적이신 것 같고요. 그 아이디어를 저희가 수용해서 심의할 때, 자문위원회 같은 것을 또 많이 하거든요. 그것을 할 때 정책수요자들을 모셔서 들을 수도 있다는 생각이 들고 내년에는 저희가 정책모니터링제도라고 그래서 정책이 실제로 집행되는 과정까지 쭉 팔로우 업(follow up) 하는 그것을 도하고 상의해서 하려고 그럽니다. 그런데 전반적으로 위원님 말씀이 아주 적합한 지적이신 것 같아서 저희가 그런 방향으로 노력을 하겠습니다. 
