<p><b>○ 위원장 김대원 </b> 임우영 위원 수고하셨습니다. 중식시간이 다 됐는데 중식시간 전에 혹시 오후 감사의 진행을 위해서 자료 요청하실 위원님들께서만 지금 신청해 주시기 바랍니다. 전동석 위원.
</p>
<p><b>○ 전동석 위원 </b> 전동석입니다. 답변하시느라 고생 많습니다. 금방 임우영 위원님께서 말씀하신 내용 중에서 본 위원이 사실상 자료요청을 했었는데요. 자료 내용을 보면, 지금 답변하신 거 보니까 사실상 소송도 제기돼 있고 또한 경찰 판단이 없어서 검찰로 넘어가 있다는 얘기를 하셨는데 자료 제출해 준 내용에 의하면 아무런 상관이 없는 것처럼 그렇게 자료를 제출해 주셨어요. 그래서 그 이후에 어떤 일을 계속 하고 계신지, 보니까 합의가 도출 안 돼서 지금 계속 진행하고 있다는 말씀도 하셨고 여러 가지 있습니다. 그래서 될 수 있으면 그 이후의 조치를 자료로 제출해 주시면 고맙겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 이상입니다. 
</p>
<p><b>○ 위원장 김대원 </b> 전동석 위원 수고하셨습니다. 오전의 감사 열기가 아주 높다 보니까 중식시간이 됐습니다. 더 하시면 늦을 것 같아서 중식과 자료준비를 위해서 잠깐 감사중지를 하겠습니다. 14시까지 감사중지를 선언합니다. 
</p>
<p class=''ar''>(11시54분 감사중지)
</p>
<p class=''ar''>(14시01분 감사계속)
</p>
<p><b>○ 위원장 김대원 </b> 자리를 정돈해 주시기 바랍니다. 감사를 계속하겠습니다. 계속해서 감사 질의 답변을 진행토록 하겠습니다. 정인영 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 정인영 위원 </b> 양평 출신 정인영 위원입니다. 경기개발연구원이 대한민국을 움직이는 중심 브레인으로서 경기도정을 선도하고 대한민국의 미래를 여는 중추적인 기관, 글로벌 이슈에 대응한 정책연구를 선도하고 수도권의 경쟁력 강화를 위한 기반연구를 수행하는데 많은 기여와 발전을 이룩한 데에는 좌승희 원장님을 비롯한 연구원 및 직원 여러분들께서 각고의 노력 끝에 이러한 크나큰 성과를 이루었다고 생각을 해봅니다. 저는 경기개발연구원을 행정사무감사하면서 감사라기보다는 우리 원장님이 대한민국의 석학으로서 많은 비전을 제시한 분이기 때문에 평소 궁금하고 또 견해를 달리하는 부분이 있다면 한번 여쭤보는 것으로 제 시간을 할애할까 합니다. 
</p>
<p style="padding-left:1.2em">  원장님이 경제학이 전공이시기 때문에 여쭤보겠습니다. 제가 여쭤보고자 하는 것은 재정건전성 문제인데 이미 글로벌 경제위기로 인해서 많은 재정투입을 하지 않았습니까? 그래서 우리나라도 예산의 조기집행을 통해서 가시적인 자산의 증가라고 할까, 경기가 회복되는 듯한 느낌을 주는 경기가 계속되고 있습니다. 그런데 문제는 국가부채인데 얼마 전에 발표한 국가부채 규모를 보면 한 400조 정도 된다 그래요. 그리고 국가부채와 공기업, 정부에서 보증한 채무까지 합치면 1,400조에 이른다고 합니다. 국가부채가 이렇게 많다고 하는 것은, 제가 경기도 부채도 말씀을 드리겠습니다만 우리나라 부채가 통상 GDP 대비 40%밖에 되지 않기 때문에, 일본은 GDP 대비 200%, 미국은 GDP 대비 80%, 거기에 비해서는 퍼센티지로 아직은 재정건전성이 위험수위에 도달한 것은 아니다라고 얘기들을 하고 있습니다. 그렇지만 OECD 국가에서 국가부채를 산정하는 방식이 조금 다르다고 하는데, 우리나라의 경우에는 400조라고 그러는데 공기업 부채나 보증채무 같이 채무로 산정을 하지 않는 금액까지 하면 실지로는 한 1,400조가 된다고 한다면 140%의 국가채무를 가지고 있습니다. 
</p>
<p style="padding-left:1.2em">  경기도는 어떠냐 하면 부채 증가속도가 굉장히 빠릅니다. 07년도에 6,502억, 08년도에 4,699억의 지방채를 발행했고 09년도에는 상반기에만 3,572억 원의 지방채를 발행했습니다. 경기도 공기업의 부채는 6조 7,172억 원입니다. 또 시설관리공단의 부채는 350억 원이라고 본다면 정말 경기도에서도 감당할 수 없는 이런 부채들이 늘어나고 있습니다. 거기에 2010년도 예산을 편성하는 단계에서 보면 가용재원이 4,000억밖에 안 된다고 하는 보고를 받은 바 있습니다. 지방채 2,500억을 발행해서 6,500억인데 그것은 예년의 1/2밖에 안 되는 가용재원입니다. 이러한 세수의 감소 또 재정건전성이 어려운 상태에서 과연 어떤 예산을 세워야 하는가라는 물음을 봤을 때 경기도의 재정건전성도 상당히 위험수위에 와 있는 것만은 분명한데 여기에 대해서 원장님께서 평소에 생각하시던 점이 있으시면 말씀해 주시면 고맙겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 경기도 재정 현황에 대해서는 제가 한 일주일 전에 자료를 챙겨봤는데요. 지금 자료를 가지러 가라고 했습니다, 구체적인 숫자는. 경기도가 부채 증가속도도 빠르고 특히 09년도에 많이 증가했다고 하는 보도가 있어서 체크해 봤는데 전체 규모로 보면 그렇지만 1인당 인구비례로 보거나 하면 그렇게 높은 수준은 아니었습니다. 중간 정도 수준이라서 언론보도처럼 그렇게 아주 위험하다 하기에는 좀 이르지 않을까 하는 생각이 들었고요. 그 자료는 제가 제공해 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 특히 민선 4기 들어와서 많이 늘은 건 제 생각에는 그동안 경기가 좋은 시절에 많이 커미트(commit)한, 지출하기로 했던 부분이 이어져서 계속 나간 그런 부분도 있고. 교통부문에 교통통합 활성제도라든가 이런 걸 하면서 나간 보조금 이런 것들이 일부 있어서 많이 증가를 했는데 금년은 아까 말씀하신 대로 상당히 어렵지 않은가 하는 생각이 듭니다. 어쨌든 제 생각에는 전체 총액의 변화는 어떻게 보면 좀 우려스럽게 보이겠지만 전체 경기도의 경제규모라든가 재정규모, 인구규모 이런 걸 가지고 비율로 따져 보면 그렇게 위험한 수준은 아니지 않은가 생각을 하고 있습니다. 
</p>
<p><b>○ 정인영 위원 </b> 원장님이 그런 답변을 해주시니까 도민의 한 사람으로서 마음의 안정감을 가질 수 있겠습니다마는 실지로 인구비례라든가 또 16개 시도에서의 부채비율이 중간 정도이기 때문에 괜찮다 이런 얘기들은 그동안 많이 들어왔습니다. 그럼 괜찮았다면 과연 2009년도 대비 2010년도 예산이 1.2%, 전체 금액의 1.2%가 증가됐는데 그럼에도 불구하고 가용재원은 1/3로 줄었다는 얘기죠. 그럼 앞으로 경기가 현 상태를 유지하거나 더 안 좋아진다고 봤을 때 과연 경기도가 어떠한 재정정책을 취할 수가 있겠느냐 하는 의문이 드는 거죠. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이건 좀 테크니컬한 얘기가 되겠습니다마는 재정의 경기완화 효과라는 것은 경기가 나쁠 때는 적자재정을 하고 경기가 좋을 때는 흑자로 해서, 매년 균형재정을 할 필요는 없지만 한 3년, 5년 이런 단위로 해서 중기재정계획을 세워 가지고 균형이 되도록 하는 게 요즘 새로 많이 활용하는 전략이라고 생각을 합니다. 그런 차원에서 보면 최근에 경제가 나쁘기 때문에 경기도만이 아니라 전체적으로 재정이 취약하고, 중앙은 물론 적극적인 재정지출을 했기 때문에도 그런 면이 있습니다마는 경기도 재원이 줄어드는 거는 너무 당연한 거 아닌가 싶고요. 이때는 제가 보기에는 필요하면 지방채를 발행해서 필요한 재원을 조달하고 그렇게 함으로써 재정의 경기진작 효과를 볼 수 있지 않을까 하는 생각이 들고. 그렇기 때문에 부채라든가 이런 게 악화되는 걸 지금 상황에서 너무 위기의식을 가지고 볼 필요는 없지 않을까. 경기가 회복되기 시작하면 자연스럽게 수입이 늘어나기 때문에, 사실 내년 하반기 가면 재정수지가 지금 기대했던 거보다 더 좋아질 가능성도 상당히 배제하기가 어렵기 때문에 그런 관점에서 상황을 판단할 수 있지 않을까 싶고 필요하면 지방채를 발행할 수 있다고 생각합니다. 
</p>
<p><b>○ 정인영 위원 </b> 지방채를 발행하는 것을 문제 삼는 것이 아니고 결국 앞으로의 경기를 낙관적으로 보느냐 비관적으로 보느냐 하는 문제인데 지금 경기도의 입장이……. 소위 GTX 사업을 추진한다라고 하는 이야기를 들었습니다. 이 GTX 사업은 어떤 의미에서는 여러 가지 장점이 있겠죠. 지금 경기도에서 국토해양부에 제안한 것으로 알고 있습니다마는, 제안해서 지금 타당성 조사를 하고 있는데 민간제안사업으로서 A노선, B노선, C노선 3개의 노선을 지금 타당성 검토를 하고 있습니다. 그런데 문제는 3개 업체 내지는 컨소시엄으로 구성을 해서 제안을 한 저것도 있습니다마는 2011년도에 시작해서 2016년도에 끝나는 사업으로 해서 민자로 한 20조 정도의 예산이 수반된다고 하는데 과연 지금 이러한 사업을 이렇게 어려운 상태에서 시작할 필요성이 있는가 하는 의문을 가지게 되고요. 물론 민자이기 때문에, 재정이 투입이 안 되기 때문에 할 수 있다라고 하는 이야기도 들었습니다마는 그건 사실 민자라고 하더라도 민간기업이 현금이 있어서 하는 게 아니고 결국은 은행에서 돈 빌려서 사업을 하게 되는 건데 그렇게 하다 보면 여러 가지, 인천공항철도나 여러 가지 사업들을 봤을 때 이것도 역시 재정 불건전성의 한 사업이 아니겠느냐 하는 생각을 해보면서, 이제는 SOC 사업이 덜 돼 있고 안 돼 있어서 성장동력이 떨어진다는 거보다는 청년들에게 일자리를 주는 문제 또 저출산 문제 이런 문제들에 예산과 재원을 집중 투입함으로써 해결점을 찾아야 됨에도 불구하고 그렇지 못하다고 하는 점이 안타까운 면이 있습니다. GTX 사업에 대해서도 생각해 보신 점이 있는지요?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> GTX에 대해서는 기간이나 들어가는 돈에 대해서는 지금 교통개발연구원인가요, 거기서 이미 타당성 검증을 하고 있기 때문에 검증결과를 봐야 되지 않을까 하는 생각이 듭니다. 그러나 제가 이해하기로는 도에서도 이 사업이 엄청나게 큰 사업이기 때문에 민자가 없이는 안 된다고 얘기를 하는 걸로 알고 있고 더 나아가면 이게 경기도 사업만이 될 수는 없죠. 지금은 경기도가 적극적으로 나서서 이걸 추진하지만 궁극적으로는 서울시ㆍ인천, 수도권 전체 자치단체가 힘을 합치고 더 나아가서 중앙정부까지 여기에 힘을 보태야지만 될 수 있는 게 아닌가 싶습니다. 우리가 철도를 놓는데 서울을 지나가서 서울시민들한테도 다 혜택이 가는데 서울시가 빠질 수는 없는 것이고요. 그래서 자금조달 하는 문제라든가 이것은 그런 관점에서 보면 좀 더 긍정적으로 생각을 해볼 수 있지 않을까 하는 그런 생각이 들고요.
</p>
<p style="padding-left:1.2em">  시기를 이렇게 바쁘게 2016년까지 할 필요가 있겠느냐 하는 그런 얘기도 하겠지만, 또 이것보다도 더 중요한 일자리 창출이라든가 이런 사업에 더 신경을 쓰면 좋겠다는 지적도 일면 타당성이 있습니다만 결국 이 GTX가 수도권 경쟁력을 높이는 데 기여하리라고 생각하는 거죠. 수도권이 그동안 수도권 규제 때문에도 많은 피해를 봤지만 서울ㆍ경기ㆍ인천이 상호 분할이 돼서, 행정적으로 분할된 건 물론이고 교통체계 면에서도 통합이 잘 안 돼서 여러 가지 불편한 점이 있고 그래서 수도권 전체의 경쟁력이 취약하다 하는 그런 시각이 있었기 때문에 이 GTX가 그런 소위 통합과 경쟁력 강화에 기여할 수 있기 때문에, 이것이 단순한 SOC뿐만 아니라 더 나아가면 경쟁력 강화에 기여하기 때문에 같은 맥락에서 이해할 수 있지 않을까 하는 생각이 들고요. 물론 시기나 기간, 금액에 대해서는 아까도 말씀드렸지만 중앙정부에서 보다 더 심층 검토를 해서 조만간에 발표하지 않을까 하는 생각이 듭니다. 
</p>
<p><b>○ 정인영 위원 </b> 연구원에서 경기도 도시철도사업의 활성화 방안, 수도권 철도망 완성을 위한 경기도 도시철도 추진방안, 2개의 리포트하고 연구과제가 나온 것을 검토를 해보니까 그 결론이 결국은 철도중심의 대중교통체계를 구축할 필요가 있다. 그것은 기후변화, 요새 소위 그린(Green)이라고 하는 이쪽에다 포커스를 맞췄고 그다음에 SOC 투자재원을 계속해서 늘릴 필요가 있다. 또 경기도 역할을 제고하고 조직정비나 전문인력을 확충해서 경기도가 계획을 하고 협상수준을 제고하는 과제를 발표했습니다. 문제는 이 사업이 필요하지 않다고 하는 것이 아니라, 지금 세종시 논란도 있습니다마는 그 세종시 사업을 어떻게 하느냐 하는 문제를 차치(且置)하고라도 과연 지금 우리나라 경제 상황에서 또 이러한 정부부채가 1,400조에 이르고 우리 경기도에도 많은 지방부채가 있음에도 불구하고 과연 이러한 사업에 집중할 필요가 있느냐 하는 문제를 제기하는 겁니다.
</p>
<p style="padding-left:1.2em">  제가 말씀드리고자 하는 것은 경기도 도정의 발전방향이 이제는 패러다임을 바꿔야 되지 않겠느냐? 물론 이제까지는 재정 포퓰리즘에 의해서 많은 사람들이 예산은 그저 갖다 쓰고 보자 하는 주의, 시작하고 보자 하는 주의, 이렇게 해서 전 국토가 공사장화 돼 있지 않습니까? 사업이 하나하나 매듭이 지어지고 그것이 성과가 나야 그 예산이 사장되지 않음에도 불구하고 계속 사업을 한다는 얘기는 그 예산들을 투입하는 동안은 계속 그 예산이 사장되고 있다는 얘기거든요. 그러니까 재원의 효율적인 배분에서도 문제가 있는 거고 해서, 이제는 청년일자리를 만들자고 하면서 실질적으로 청년고용이 늘어난 게 없지 않습니까? 그리고 저출산 문제가 향후 대한민국의 운명을 좌우할 성장동력의 문제로까지 거론되고 또 내년부터는 베이비붐 세대가 퇴직하는, 시대가 변하는 상황에서 60, 70년대 개발시대의 사고방식으로 지금 경기도가 대처하고 나간다면 문제가 있지 않겠느냐는 지적을 많은 분들이 합니다마는, 청년일자리를 창출하는 방법은 결국은 제조업을 육성시켜서 기업에서 일자리를 창출하고 고용을 해야 되는데 어차피 21세기는 고용 없는 성장을 하기 때문에 이제 지방자치단체에서는 공공사회서비스 일자리를 확충하는 데 예산을 투입해야 되는 거 아니냐 하는 생각이 드는데 그 점에 대해서는 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 정인영 위원님, 국가재정 문제에서부터 시작해서 지방재정, 더 나아가서 국가 전체 개발문제까지 아주 폭넓은 식견을 말씀해 주셨는데 저는 그 관심과 걱정하시는 부분에 대해서는 충분히 그럴만한 이유가 있다고 생각을 합니다. 우선 국가재정 전체로 놓고 보면 아까 부채 말씀도 하셨지만 지금 한국이 하겠다고 하는 게, 새만금 저게 얼마의 돈이 들어갈지도 모르는 큰 사업이고 지금 4대강사업이 있죠. 세종시가 있고, GTX 그렇고 더 나아가면 지난 정부에서 시작한 특성도시, 기업도시 이래 가지고 거기에도 수십조 원이 들어가는 사업들이 전국에 펼쳐져 있는데 국가가 지금, 아까 말씀하신 대로 GDP 대비로 본다면 140%의, 물론 이건 보는 사람에 따라 차이가 있겠습니다마는 국제기준으로 봐도 절대 적은 게 아니고 상당히 위험한 수준이라고 볼 수도 있겠습니다. 그런 상황에서 국가가 이런 여러 가지 사업을 할 수 있겠느냐? 더 나아가면 지방자치단체가 이런 큰 사업을 할 수 있겠느냐 하는 질문은 대단히 타당한 질문이라고 생각되고요. 그렇기 때문에 제가 보기에는 국가가 사업의 우선순위를 정할 수 있어야 된다고 봐요. 아까 거론한 4대강, 세종시, 새만금 이 중에 어디에 더 우선순위를 두고 할지 하는 것은 사실은 중앙정부가 상당한 고민을 해야 될 사업이 아닌가 싶고 그렇게 안 하면 국가의 힘이 분산이 돼서 상당히 어려울 수도 있다는 생각을 해봅니다. 
</p>
<p style="padding-left:1.2em">  그러나 어느 특정사업의 경우에 있어서도, 아까 청년일자리를 위해서 지방재정에서 일종의 말하자면 공공고용이랄까 이런 창출 역할을 많이 말씀을 하셨지만 정부가 돈을 써 가지고 고용을 창출하는 것은 절대 지속 가능하지 않습니다. 결국은 청년실업이든 장년실업이든 고용창출은 기업이 하는 것이고 그렇기 때문에 지방정부가 할 수 있는 유일한 고용창출 노력은 인프라를 제대로 깔고, 하드웨어뿐만 아니라 소프트웨어 측면에서도 노조문제라든가 각종 법제, 규제 이런 걸 잘 정비해서 좋은 투자자가 들어와서 투자를 많이 하도록 만드는 것만이 항구적으로, 그게 제조업이 됐든 서비스업이 됐든, 요즘 서비스업이 더 고용창출 효과가 높다고 얘기를 합니다마는 그런 방법을 통해서 고용을 창출해 나가는 것이 옳은 것이지 지방재정이 아주 취약한데 거기서 돈을 써서 사회적 일자리를 만들거나 하는 건 아주 마지널(marginal)한, 한계적인 도움이 될 뿐이지 근본적인 해결책이 되기는 어렵지 않을까 하는 생각이 들고요.  
</p>
<p><b>○ 정인영 위원 </b> 그렇습니다. 이제까지 복지정책을 얘기할 때 성장 없는, 파이를 키우지 않는 분배가 무슨 소용이 있느냐 하는 이론들을 많이 제기했습니다. 그럼에도 불구하고 지금 국가재정이 든든하면 여러 가지 필요한 것들을 다 할 수 있겠지만 과연 어디에다 집중해야 그 효과를 발휘할 수 있느냐 하는 문제인데 지금 산술적으로는 복지예산이 굉장히 많이 늘어났다고 합니다. 그런데도 불구하고 과연 앞으로 이 나라를 짊어질 청년들에게 과연 얼마나 투자를 했느냐 하는 문제를 생각해 보는 거죠. 청년실업 문제, 저출산 문제 이런 문제들이 해결되지 않고는 대한민국에 희망이 없지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 저도 동감입니다. 
</p>
<p><b>○ 정인영 위원 </b> 얼마 전에 칠레 여성 대통령께서 한국을 방문하셨습니다마는 그분의 지지율이 80%라고 합니다. 그 이유는 소위 젊은이들한테 일자리를 만들고 보육시설을 0세부터 4세까지 100% 국가에서 책임지고 보육하는 정책을 실시함으로 인해서 국가가 많이 변화했고 또 수출품이 구리가 제일 많은데 그것을 펀드화시켜서 이런 위기에 대처했다.
</p>
<p style="padding-left:1.2em">  그런데 지금 현재 경제위기를 겪는 나라들은 결국은 하나같이 부채가 많다는 얘기죠. 그러면 개인이나 지방자치단체나 국가가 빚이 많다고 하는 얘기는 헤어날 길이 없다고 하는 것이 동서고금의 진리인데도 불구하고 그것이 아직도 경기도에서도 안 되고 있다 하는 답답한 마음에서 의정활동을 하면서 ‘이게 좀 패러다임이 바뀌어야 되겠다. 생각이 바뀌어야 되겠다.’ 하는 생각을 하면서 이번 행정사무감사를 통해서 원장님의 고견을 들어보고자 했던 것입니다. 
</p>
<p style="padding-left:1.2em">  하여간 진솔한 답변에 감사드리고요. 앞으로도 제가 기획실이나 여러 가지 행정사무감사가 남았습니다만 원장님의 고견을 참고해서 경기도의 정책이 조금이나마 긍정적인 방향으로 바뀌는 데 역할을 하는 것이 이번 행정사무감사의 제 소임이 아닐까 생각을 하면서 질의를 마치고자 합니다.  
</p>
<p><b>○ 위원장 김대원 </b> 정인영 위원 수고하셨습니다. 다음 질의하실 위원 신청해 주시기 바랍니다. 이경천 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이경천 위원 </b> 이경천 위원입니다. 감사자료를 한번 봤습니다. 여러 가지 연구들을 많이 하셨고 또 연구를 하기 위해서 많이 활동하신 그러한 흔적이 많이 있었던 것 같습니다. 많은 노력을 하셨다는 부분에 대해서 치하의 말씀을 우선 드립니다. 여러 위원님들께서 여러 부분에 대해서 말씀을 하셨기에 본 위원은 팔당물환경센터에 대해서 질문을 드리겠습니다. 물환경센터 설립목적이 어떤 것입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 팔당 수질개선을 제일 중요한 목적으로 내걸고 출발했습니다. 
</p>
<p><b>○ 이경천 위원 </b> 인적 구성은 어떻게 돼 있나요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지금 저희 연구원 박사가 세 사람이 있고요. KIST에서 2명입니다. 1명은 연구위원급이고 1명은 김연제 박사님이라고 센터장으로 모셔서 있고요. 보건환경연구원에서 한 사람의 박사가 참여해서 연구하고 있습니다. 
</p>
<p><b>○ 이경천 위원 </b> 자료를 보면 설립목적에 부합하는 연구결과가 별로 없는 것 같습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇게 말씀하시면 저희가 참, 그동안 우리는 그걸 위해서 한다고 애를 썼는데…….
</p>
<p><b>○ 이경천 위원 </b> 이 외에 자료가 또 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지금 업무보고자료 보시고 계신가요?
</p>
<p><b>○ 이경천 위원 </b> 연구하신 자료들 보면 지금 말씀하신 수질개선과 관련한, 직접적으로 관련된 연구는 별로 없으신 것 같아요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 수자원 관리와 그걸 통한 수질개선 혹은 악화를 막는 그런 방향으로 대부분의 연구를 저희는 해오고 있다고 생각을 하는데요. 어느 자료를 지금 보고 계신지…….
</p>
<p><b>○ 이경천 위원 </b> 여태까지 연구해 오신 자료 중에서 수질개선과 직접적인 관련이 있는 연구가 어떤 것들입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제일 대표적인 게 오염총량제가 지금 도입이 되고 있기 때문에 그거에 대한 연구가 많이 있었고요. 또 그걸 하기 위해서 데이터베이스를 구축해야 되는데 그런 것과 관련된 연구, 뭐 축산이나 폐수 같은 데서 생기는 오염원을 관리하는 문제 그리고 또 강 자체의 수리ㆍ수문 문제랄까요. 이런 물관리 자체에 대한 연구도 제법 했고요. 위원님 양해해 주신다면 우리 센터장님 모셔 가지고…….
</p>
<p><b>○ 이경천 위원 </b> 네. 누가 답변 정확히 하실 분 있으면 아무나 하셔도 상관없습니다. 
</p>
<p><b>○ 팔당물환경센터장 김연제 </b> 팔당물환경센터장 김연제입니다. 저희들이 실질적으로 이 연구센터를 운영해온 게 2년 반 정도 됐습니다. 저희들이 2년 반 동안 운영하면서 수질개선에 대해서 획기적인 어떤 효과를 실질적으로 기대하기는 어렵습니다. 그리고 또 연구비 지원하는 것도 사실 그렇게 충분히 지원되는 편도 아니고요. 그래서 저희들이 실질적으로 할 수 있는 제한된 여건하에서 최대한으로 할 수 있는 것들만 수행하고 있습니다. 그중에 내년부터 당장 의무제로 진행되는 수질오염총량제 관련된 기초연구를 쭉 해왔고요. 그다음에 그런 수질오염총량제가 제대로 도입될라 그러면 실질적으로는 데이터베이스가 사실 잘 구축이 돼 있어야 합니다. 그것 없이는 오염총량제를 개선하기가 사실 어렵고요. 
