<p><b>○ 팔당물환경센터장 김연제 </b> 그런데 저희들이 실질적으로 지금 한 2년 반 정도 해가지고, 저희들은 연구한다는 측면이 상당히 강합니다. 그리고 저희들은 과학적인 측면이 많습니다. 그런데 과학적인 측면의 연구를 1~2년 해가지고 정책을 어떻게 바꿔야 되겠다 이런 것은 사실 어렵습니다. 사실 지금 저희들이 축산폐수나 비점오염원 연구도 하고 있는데요. 이런 것들을 1~2년 연구해 가지고 이것은 어떤 정책을 펴야 된다 하고 결론 내리기가 상당히 어렵습니다. 
