<p><b>○ 경기개발연구원장 좌승희 </b> 제가 조금 보충말씀을 올릴까요? 그동안 한 연구는 일종의 말하자면 기반연구랄까요, 주로 이런 게 포함이 되죠. 오염총량제도 내년부터 도입을 하는데 그걸 하기 위한 준비를 지금 계속 하고 있는 것이고 그 관련된 데이터베이스를 어떻게 관리하느냐 하는 그런 문제. 그다음에 여기 보고자료 27페이지에 쭉 리스트가 되어 있습니다, 연구프로젝트가. 이런 것을 보면 전부 다 이게 팔당수질개선본부가 정책을 구체적으로 하는 데 도움이 되는 소위 인프라라고 할까요. 그런 측면의 연구를 주로 많이 했기 때문에 가시적으로 우리가 이걸 해서 수질 개선하는데 이렇게 기여했다고 주장하기는 저희가 좀 아직 미흡하다는 말씀이고.
</p>
<p style="padding-left:1.2em">  연구자금 문제는 저도 잘 몰랐습니다마는 수질개선 관련된 연구가 액수가 무지하게 많이 들어가는 연구들입니다. 그런데 우리 연구원은 아시다시피 정책연구 하면 1,000만 원에서 3,000만 원 사이 왔다 갔다 하고 그러니까요. 그 정도 가지고는 이 연구가 제대로 진행이 안 된다고, 특히 KIST에서 오신 박사님들이랑 얘기를 하는데. 그렇다고 해서 저희가 예외적으로 여기에 더 특별히 배려를 해서 하기도 어렵고 그래서 사실 연구자금에 있어서 좀 제약이 있었다 하는 것을 제가 알고 있고요. 앞으로 그것을 개선하려고 노력하고 있습니다. 
</p>
<p><b>○ 이경천 위원 </b> 비용이 많이 들어도 필요한 연구라면 당연히 그 부분에 대해서 연구를 용역하는 사람이 충분한 용역비를 낼 수 있게끔, 그게 허구가 아니고 사실이면, 그렇지 않습니까? 그러한 노력을 하셔야 한다고 보고요. 오염총량제 얘기 나온 지가 꽤나 오래됐죠? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아주 오래됐죠.
</p>
<p><b>○ 이경천 위원 </b> 그런데 이제 데이터베이스를 하신다고 하면 경기도 발전을 선도한다고 하는 경기개발연구원이 그렇게 하셔서는 안 된다. 오염총량제 얘기 나온 지가 제가 알기로는 한 5~6년 된 걸로 알고 있는데…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그동안 저희가 꾸준히 계속 했습니다마는 그렇습니다. 
