<p><b>○ 이경천 위원 </b> 우리 경기도에서 팔당호 수질개선을 위해서 예산을 어느 정도 쓰고 있는지는 아십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 경기도에서 쓰는 예산은 제가…….
</p>
<p><b>○ 이경천 위원 </b> 이게 제가 알기로는 99년도부터 수질개선사업을 해왔거든요. 그런데 국도비를 포함해서 10조 원이 넘게 투여됐다고 제가 알고 있습니다. 그런데 수질 개선은 그렇게 제대로 되지 않고 있거든요. 이것은 연구 부족이다, 저는 그렇게 생각합니다. 옛날에 초창기에 주먹구구식으로 한 것을 계속하고 있다는 말이죠. 잘못된 것을 인정하고 다시 시작하는 것이 더 바람직한데 지금 잘못됐다고 스스로 인정하는 사람들이 없단 말이죠. 그래서 내가 봤을 때 지금까지 10조 원이나 넘는 예산을 투여했는데도 불구하고 개선이 안 되는 부분이라면 정말로 경기개발연구원 같은 데서 연구를 하셔서 이러한 부분은 이렇게 이렇게 돼서 잘못된 것이고 앞으로 이러한 예산이 효율적으로 쓰여질 수 있으려면 이러한 이러한 방법으로 가야 한다, 이러한 대안제시를 해야 한다고 생각하는데 어떻게 생각하세요? 
