<p><b>○ 경기개발연구원장 좌승희 </b> 옳은 말씀이십니다. 저희가 사실 그렇게 한다고 애를 썼지만 아직도 충분히 성과를 내지 못하고 있다고 생각이 되고요. 말씀하신 대로 저희가 그런 방향으로 더 노력을 하도록 하겠습니다. 
