<p><b>○ 이경천 위원 </b> 제 기억으로는 금년도부터 2013년까지 경기도 재정계획을 보면 팔당호 수질개선을 위해서, 제가 좀 기억이 가물가물한데요. 4조 7,700억 원인지 2조 7,700억 원인지 이렇거든요. 이러한 엄청난 예산을 지금 들어붓고 있는데도 불구하고 효과가 제대로 안 나고 있다는 것이죠. 그래서 제가 봤을 때에는 집행부에서 스스로 문제점을 찾아내고 개선할 의지도 없고 능력도 없다고 봅니다. 그래서 이러한 부분은 경기개발연구원에서, 연구용역비가 많이 든다고 하면 그것은 마련할 수 있는 거 아니겠습니까? 이걸 좀 해야 한다고 생각하는데 어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 돈을 마련하는 거야 저희가 마음대로 할 수는 없습니다마는 연구의 정당성이 있다고 그러면 상대적으로 자금을 확보하는 데 도움이 되지 않을까 하는 생각이 들어서, 좌우간 지적하신 대로 그동안 그렇게 많은 액수의 돈을 쓰고 노력도 했는데 크게 개선이 안 됐다고 하면 그 원인이 뭔지 한번 이것을 점검하는 작업은 할 필요가 있지 않을까 하는 생각이 들고요. 그 과정에서 저희가 고쳐야 될 게 있다고 하면 또 고치고 그렇게 해야 되지 않을까 싶고.
</p>
<p style="padding-left:1.2em">  또 한 가지는 팔당문제가 경기도만의 문제가 아니고 서울이나 인천, 강원도와 다 관련된 지역이 있지 않습니까? 그래서 이런 지역들하고 한강수계기금을 어떻게 서로 효율적으로 활용할 것이냐 하는 그런 논의가 지금 진행되고 있어서 그것을 통해서 좀 더 기금이 우리한테 확보가 되면 아까 말씀하신 그런 방향으로 더 노력을 하도록 하겠습니다. 좌우간 우선 지적하신 말씀은 상당히, 말하자면 포인트가 있는 것 같습니다. 우리가 노력한 것에 비해서 성과가 얼마나 나왔는지 한번 그동안의 그걸 점검을 하는 것은 필요한 게 아닌가 하는 그런 생각이 들어서 저희가 해보겠습니다. 
</p>
<p><b>○ 이경천 위원 </b> 금년도 예산만 해도 6,478억입니다. 수질개선에 쓴 예산이요. 그리고 조금 전에 말씀하신 물이용부담금, 제가 알기로는 1년에 한 3,700~3,800억 있는데 그것이 정말로 수질개선을 위해서 제대로 안 쓰여지고 있다고 보여지거든요. 그중에서 지자체로 쓰여지는 돈이 한 700억 정도밖에는 안 됩니다. 그래서 그러한 부분도 우리 경기개발연구원에서 좀 제대로 연구를 하셔서 그러한 예산이 수질개선을 위해서 또 주민지원사업을 위해서 쓰일 수 있게끔 객관적인 연구발표를 해주셔야겠다 이런 생각이 듭니다.
