<p style="padding-left:1.2em">  본 위원이 생각하기에는 사실 연구원은 이런 높은 도덕성과 신뢰성을 먹고사는 곳이 아닙니까? 그러니까 이런 문제에 적극적으로 대처해 가지고 연구원들이 연구논문이나 연구자료에 대해서 내놓기 전에 다시 스크린할 수 있는 어떤 제도적인 장치가 필요하지 않겠습니까? 
