<p><b>○ 전동석 위원 </b> 아니, 일상적인 것 말고. 그런 거야 지금까지 해오셨는데. 진짜 연구원에 대한 새로운 어떤 판단을 해서 상대방 아니면 연구원들로 하여금 이것을 충실히 스크린할 수 있는 제도가 필요하다는 얘기입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 해야죠. 해야 되고 이번 사건도 제가 지금 파악하기로는 이게 아래 보조연구원하고 같이 하는 과정에서 박사가 일이 많고 그러니까 다 점검을 못해서 인용하는 게 한두 개 누락된 게 말썽이 된 건데…….
</p>
<p><b>○ 전동석 위원 </b> 일이 많으신 줄 압니다. 아는데…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그래서 최선을 다해서 이런 일이 안 생기도록 하고 최종보고회 할 때 박사님이라든가 같이 일하는 연구보조원 쪽에서 다시 한 번 그런 걸 체크하도록 하는…….
</p>
<p><b>○ 전동석 위원 </b> 다시 한 번 체크하는 그런 기관을 두시고, 기관이라기보다는 그런 어떤 것을 맡을 사람들을 두시고 거기서 감수한 거에 대해서 만약에 문제가 생기면 감수한 사람까지도 책임질 수 있는 시스템이 가능하다 이런 생각이 들어서 말씀드린 건데요. 한번 깊이 생각해 주시고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 검토해 보겠습니다.
</p>
<p><b>○ 전동석 위원 </b> 이제 휘말릴 수 있는 여건들을 보면 위조나 변조나 표절시비 이게 주로 휘말릴 수 있는 사건이라고 생각됩니다. 그런 제도적 장치를 꼭 마련해 주셔서 조만간에 그런 어떤 계획을 가지고 계신다면 본 위원한테 얘기해 주시면 좋겠습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 
</p>
<p><b>○ 전동석 위원 </b> 여기에 대해서는 여기까지 하고요. 연구비에 대해서 한번 간략히 여쭙도록 하겠습니다. 본 위원이 CEO Report하고 Policy Brief 관련해 가지고 말씀을 들었는데요. 제가 각 연구원별 연구수행에 따른 연구비 지급현황을 요청했더니 친절하게도 제가 물으려는 의도를 아셨는지 보면 “연구과제보고서를 의도적으로 재가공하여 원고료를 받은 사례는 없다.”라고 강변을 해놨습니다. 재가공이라는 단어가 좀 그렇긴 한데요. 몇 가지 짧게 말씀해 주십시오. 우리는 이걸 재가공해서 Policy Brief 아니면 CEO Report로 냈습니다. 그런데 이거는 우리가 일부러 이렇게 했습니다 하는 것이 바로 살아있는 생태박물관 DMZ라든가 광역경제권의 재원조달과 재원배분방안이라든가 이 6개인가 하는 부분에 대해서는 우리가 따로 냈습니다라고 말씀을 해주셨습니다. 이것도 물론 재가공인데, 재가공이지 않습니까, 그렇죠? 재가공해서 CEO Report로 냈을 때 이것을 50만 원에서 10만 원까지 따로 받았어요. 이미 연구된 사항입니다. 그렇죠? 그랬을 경우에 이것을, 여기 보면 경영진의 연구내용의 성격상 여론선도 및 가독성이 높은 CEO Report나 Policy Brief로 제공해서 이렇게 배포했다, 누구누구에게 배포했다고 말씀하셨는데요. 이렇게 재가공했다면 사실상 연구원으로서 연구비를 받아야 됩니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저는 연구를 재가공해서도 필요하면 CEO Report를 내라고 장려를 합니다. 왜 그러냐 하면 연구보고서가 나오면 그게 장문의 서적으로 나오기 때문에 그걸 짧게 5분 정도 해서 기자 브리핑을 합니다마는 그게 보도가 충실히 안 되고 그래서 그 내용이 사장되는 경우가 많기 때문에 좋은 보고서를 냈으면 그걸 다시 축약해서 소위 지도급, 여론지도층에 알리는 게 좋겠다는 의미에서 그걸 제가 장려를 하고 있고. 그렇다고 많이 나오지는 않아요. 그다음에 그렇다고 해서 원고료를 똑같이 주면 안 된다 해서 차등을 해서 상당한 정도의 차등이, 원고료를 10만 원 수준으로 지금 주고……. 
</p>
<p><b>○ 전동석 위원 </b> 원고료가 어떤 거는 50만 원도 냈고 또 10만 원에 낸 분들도…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 50만 원 그건, 거의 창작에 가깝다 해서 한 거는 50만 원이고 재가공에 가깝다 그런 건 10만 원으로 해서 하고 있습니다. 
</p>
<p><b>○ 전동석 위원 </b> 그래서 말씀은 이렇게 했습니다. 했을지라도 일반 사람들이 보기에는 같은 문건에 대해서 이중으로 연구비를 탔다 이렇게 해석하는 분들이 있더라고요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇게 오해를 할 소지도 있다고 생각이 됩니다. 지금 말씀을 들어 보니까.  
</p>
<p><b>○ 전동석 위원 </b> 이거에 대해서 관심을 가지셔야 되고요. 그러면 2008년, 2009년도에 나온 재가공한, 어떤 걸 재가공한지 아시죠, 원장님? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 
</p>
<p><b>○ 전동석 위원 </b> 이렇게 돼 있습니다. 이거 외에는 재가공해서 받은 사례가 없다고 단언하실 수 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아마 없다고 저는 생각이 되는데요. 철저하게 저희가 관리를 하고 있습니다. 바로 위원님이 염려하는 그런 것 때문에 같은 연구를 해가지고 같은 연구원 안에서 두 번 그렇게 하는 건……. 또 금전적으로 그렇게 가는 것도 옳지 않은데 10만 원 주는 건 그 사람이 노력을 했고 그래도 약간의 인센티브는 줘야지 추가로 하지 않겠는가 하는 그런 차원에서 하는 거니까요. 
</p>
<p><b>○ 전동석 위원 </b> 사실 10만 원이든 50만 원이든 박사님들의 일에 대해서 다시, 거의 창작수준의 재가공을 하는 일에 대해서 보면 50만 원도 사실 쌀 수도 있어요. 그렇지만 일반인들이 보면, 금방도 말씀드렸지만 같은 문건에 대해서 이중으로 연구비를 탔다는 그런 지적이 있을 수 있거든요. 그거에 대해서 그렇고요. 지금 말씀하셨는데요. 제가 그래서 혹시나 싶어서 몇 가지, 다는 볼 수가 없었어요. 혹시나 싶어서 몇 가지 체크를 한번 해봤습니다. 해봤는데, 2008년도 8월호에 게재했던 사안을 가지고 똑같이 연구비를 지급한 사례가 있더라고요. 그 내용은 제가 못 읽어봤습니다, 솔직히 말씀드려서. 지금 제가 미리 말씀드렸습니다. “똑같은 재가공 사례가 없느냐?” 하는 말씀을 드리니까 그런 게 없을 가능성이 있다고 말씀하셨는데요. 제목은 말씀드리지 않겠습니다. 제도적 개선방안에 대해서 썼던 얘긴데요. 보면 2008년도 8월 달에 경제동향에 나갔던 과제더라고요. 8월호에 나갔어요. 그런데 그전에 8월 달에 CEO Report에 똑같이 냈더라고요. 똑같이 받았어요. 예를 들면 이런 것도, 제가 잘못 해석하고 있는지 모르지만 보니까 거의 같은 거더라고요. 같은데, 경제동향에 내고 또 그다음에 CEO Report에 같이 내가지고 이중적인 의심을 가질 수 있는 이런 내용들이 있더라고요. 또 대라면 또 대겠습니다. 제가 몇 개만 챙겨봤습니다. 챙겨봤는데, 이런 문제가 있을 수 있어요. 그래서 우리 좌승희 원장님께서 연구원에 오랫동안 계시면서 워낙에 경기도 연구의 수준을 높였다고 생각돼서……. 따라가지도 못하면서 막 질타하는 건 좀 무리라고 생각되고요. 그렇지만 그런 문제들에 있어서 체크하지 못하는 사안들이 있습니다. 그래서 아까 본 위원의 1번 질문에서 이참에 연구원들의 연구결과를 스크린할 수 있는 제도적 장치를 마련하지 않으면 앞으로도 연구원들이 수백 건을 만드는데 그거 1건으로 말미암아서 연구결과가 전부 다 물거품이 되는 수도 있다. 경기도 연구를 책임지고 있는 경기개발연구원이 정말 역할을 못하고 있다는 평가를 받을 수 있다는 생각에서 말씀드렸습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 우려하시는 것도 충분히 이해가 되고요. 저희도 체크하는 과정에서 조금 불찰이 있었을지도 모르겠습니다. 그러나 어떤 경우에는 같은 제목이거나 같은 주제라도 그게 처음에 나왔던 자료에 비해서 이게 더 디벨럽(develop) 돼서 결론이 더……. 이런 경우도 있을 수 있으니까, 이건 제가 변명하는 건 아니고. 그렇기 때문에 제가 드릴 수 있는 말씀은 그런 우려가 충분히 있을만하기 때문에 이걸 다시 체제를 강화해서 그런 일이 안 생기도록 앞으로 하겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 본 위원의 생각도 박사님들의 논문이라는 것이 거기에 벽돌 한 장 더 얹히고 얘기 틀리게 해서, 이렇게 해서 새로운 논문이 더욱더 발전되는 거 압니다. 완전히 똑같은 걸 냈다고 주장하지는 않습니다. 그렇지만 누가 봐도 이건 좀 이중적인 성격이 있고 뭔가 이해가 안 가는 부분이라고 생각하는 부분이라면 미리 사전에 검토하는 게 좋고요. 10만 원, 20만 원 안 받으면 어떻습니까? 다른 데서…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그거 받으려고 그걸 다시 했다고는 생각하지 않습니다. 
</p>
<p><b>○ 전동석 위원 </b> 그러니까 다른 분들이……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 어쩌면 제가 “그거 괜찮으니까 한번 써라.” 이렇게 명령 아닌 명령을 했을 경우도 있습니다. 
</p>
<p><b>○ 전동석 위원 </b> 네, 그러실 수 있어요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> “내가 그걸 보니까 괜찮은데 그걸 CEO Report로 해서 널리 알려라.” 제가 이렇게 하는 경우가 있기 때문에 그게 그렇게 했을 경우도 있습니다.  
</p>
<p><b>○ 전동석 위원 </b> CEO Report라든지 Policy Brief라든가, 본 위원이 보기에는 두꺼운 책을 집으로 보내오는 거보다는 상당히 간단명료하게 돼 있어서 많이 참고하고 있습니다. 그래서 상당히 좋은 제도라고 생각되는데 이왕이면 그런 걸 만들면서 욕을 먹을 필요는 없다 하는 생각이 듭니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 한 가지만 간단하게 더 하겠습니다. 깊이 좀 해주시고요. 스크린할 수 있는 제도적 장치는 꼭 좀 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 
</p>
<p><b>○ 전동석 위원 </b> 그리고 간행물을 보면 간행물이 많게는 450부 정도 발간하고 있고 적게는 80부 정도 발간하고 있는 걸로 알고 있어요. 그런데 그게 보니까 1년 판매량을 보면 한 500만 원에서 700만 원, 많게는 1,000만 원 정도 판매했더라고요. 했는데, 보니까 1개 판매한 게 많아요. 그건 도대체 어떻게 판매하는 겁니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그건 교보문고에서 판매……. 
</p>
<p><b>○ 전동석 위원 </b> 그걸 한 사람이 사 가지고 가는 겁니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 1권이 나갔다고……. 
</p>
<p><b>○ 전동석 위원 </b> 그러면 1개보다는, 나머지 쌓아놓지 말고 비매품으로 하는 게 좋지 않겠습니까? 지금 완전히 온라인으로 오픈시켜 놨는데……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 사실은 인터넷에 다 오픈돼 있기 때문에 그걸 실물로서 확보하고자 하는 아주 적극적인, 책 사랑하는 마음이 있지 않고는 살 이유가 별로 없죠. 
</p>
<p><b>○ 전동석 위원 </b> 그러니까 선착순으로 줄 수 있는 방안으로 생각하든지 아니면 애착심을 가진 사람들 주기 시작하면 그래도 좀 더 이걸 요구하는 사람도 있을 거 아니에요. 그래서 이게 오픈돼 있으니까 판매보다는 비매품으로 했으면 좋겠다 싶어요. 지금 어디 창고에다 쌓아놓기도 힘들걸요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아주 어렵습니다. 버려야 되죠. 세월이 지나면 또 버리고 하는데요. 아주 큰 고민입니다. 좌우간 저희가 고민 좀 해보겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 무슨 고민을? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 비매품으로 다 줄지……. 그런데 다른 위원님들은 또 “연구원에서 해가지고 왜 그냥 다 주냐?” 또 그럴 위원님도 계시지 않을까 하는 생각도 드는데요.  
</p>
<p><b>○ 전동석 위원 </b> 1권 판매예요, 1권 판매. 그러니까 그거에 대해서 좀 신경…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그건 그렇지만 인기 있는 건 또 제법 나가는 것도 있고요.  
</p>
<p><b>○ 전동석 위원 </b> 1권짜리가 많거든요. 그러니까 신경을 써주시고. 알겠습니다. 그게 의미를 갖지는 않습니다. 그렇지만 오히려 비매품으로 하는 게 낫다 이런 생각이 들어서 여쭤봤습니다. 
</p>
<p style="padding-left:1.2em">  한 가지 더 여쭤봐도 돼요? 1분만 하겠습니다. 그냥 주문만 하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 상당히 많이 팔린 책들도 있습니다, 위원님.
</p>
<p><b>○ 전동석 위원 </b> 네, 있습니다. 삼십몇 권 팔린 것도 있어요, 보니까. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아니, 100권 이렇게……. 이게 처음 나갔을 때 그런데 세월이 가면서 점점 많이 팔리고요…….  
</p>
<p><b>○ 전동석 위원 </b> 아, 그래요? 무조건 그렇게 할 건 아닌 건가 보죠? 깊이 한번 생각해 주시고, 그게 의미는 있지 않습니다. 한 가지만 더 부탁말씀 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  제가 최근에 상공회의소에 나가셔서 토론하신 걸 봤습니다. 봤는데, 세종시와 관련해서. 지금 세종시, 좀 전에 그린도시 이런 쪽으로 움직인다고 얘기 들었습니다. 그때에 세종시가……. 그때 아주 강변하셨더라고요. “이렇게 가면 안 된다. 진짜 손해를 좀 보더라도 대한민국의 장래 발전을 위해서 가면 안 된다.”라고 강변하셨던데 그 말씀을 조금만 해주시죠.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 우선 세종시 문제하고 관련해서는 우리가 두 가지 질문을 던져봐야 한다고 생각합니다. 첫째는 왜 행정부처가 거기 가야 되느냐? 그리고 두 번째는 소위 균형발전을 한다고 그러면, 충청도를 잘 되게 한다고 그러면 왜 연기군이냐? 이 두 가지 질문을 우선 던져야 되는데.
</p>
<p style="padding-left:1.2em">  첫째, 행정부처가 가야 될 이유는 전 아무리 논리적으로 따져도 없다고 생각합니다. 박정희 대통령 시절에 수도를 이전하고자 하는 계획이 있었는데 그건 38선 부근에 수도가 집적돼 있기 때문에 안보상의 문제가 있어서 움직이려고 그런 건데 지금은 시대가 달라졌기 때문에 그런 이유 때문에 수도를 옮겨야 될 이유도 없고. 그다음에 충남을 균형발전 시키기 위해서, 자립발전 시키기 위해서 연기군에 뭘 해야 된다는 것도 제가 보기에는 논리적으로 맞지가 않습니다. 따라서 결론은 뭐냐? 이건 정치적인 판단에서 왔지 않을까 하는 그런 생각을 했고요. 더구나 최근에 와서는 충청남도가 경기도보다 더 잘삽니다. 여러분도 아시겠지만 경제성장률이 대한민국에서 두 번째로 높고, 1인당 GRDP가 대한민국에서 두 번째 높은 충청남도를 왜 균형발전을 시킨다고 거기 가서 그런 도시를 지어야 되느냐? 나머지 15개 시도가 그건 수긍할 수 없다고 봅니다. 
</p>
<p style="padding-left:1.2em">  따라서 이건 결정도 잘못됐고, 그러면 앞으로 이 도시가 잘 되겠느냐? 전 될 가능성이 상당히 없어 보이기 때문에, 그동안 한 5조 정도의 돈이 들어갔다고 하지만 그 돈이 아까워서 도시를 계속하는 건 경제학적인 관점에서 보면 대단히 잘못된 의사결정과정이기 때문에, 지나간 버스는 지나간 버스입니다. 그래서 그건 잊어버리고, 5조 원은 버렸다 치고 스톱하는 게 제일 좋겠다. 그런 게 정치적으로 어려우면 충청남도 도지사를 비롯해서 충청남도 도민들이 일어서서 “우리가 15개 시도에서 돈을 받아서 도시를 만드는 데 우리가 주도력을 발휘해서 뭔가 잘 해보겠다.” 자기 자주의 노력을 보인다고 하면 그때 가서 15개 시도에서 도와줄 수도 있지 않겠느냐 이런 정도의 얘기를 제가 했습니다. 
</p>
<p><b>○ 전동석 위원 </b> 방안제시를 하셨네요. 아무튼 알겠습니다. 거기에 대해서 고견을 가지고 계신 원장님 이하 박사님들이 좀 더 좋은 방향으로 갈 수 있도록 제시하고 여기에 대해서 신경을 써주시기 바랍니다. 고맙습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 감사합니다. 
</p>
<p><b>○ 전동석 위원 </b> 질의를 마칩니다. 아무튼 본 위원이 했던 스크린 문제, 그 문제에 대해서는 반드시 제도적인 장치를 해주시기 바라고요. 질의를 마치겠습니다. 감사합니다. 
</p>
<p style="padding-left:2.4em">    (김대원 위원장, 이승철 간사와 사회교대)
</p>
<p><b>○ 위원장대리 이승철 </b> 전동석 위원님 수고하셨습니다. 다음 질의하실 위원님, 정문식 위원님 질의하시기 바랍니다. 
</p>
<p><b>○ 정문식 위원 </b> 고양 출신 정문식 위원입니다. 먼저 연구원 관련된 거 말고요. 저희 2청에 남북협력담당관실 관련된 거 하나, 연구원의 책임연구원 관련된 사항 하나 확인하고 가겠습니다. 김동성 박사 나오셨죠?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 여기 나와 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 잠깐만 발언대로 나와 주시겠습니까? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 통일ㆍ동북아연구센터장 김동성입니다. 
</p>
<p><b>○ 정문식 위원 </b> 센터장님, 지난 10월 28일부터 11월 6일까지 통일전문가 양성프로그램으로 도에서 수행하는 연수프로그램에 같이 참여하셨죠? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네, 참여했습니다. 10월 28일부터 11월 6일까지입니다. 
</p>
<p><b>○ 정문식 위원 </b> 이때 같이 참여하신 김학성 교수는 센터장님이 추천하신 겁니까, 도에서 추천한 겁니까? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 저희 센터에서 추천했습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그럼 김학성 교수를 센터에서 추천해서 이번 연수에 참여하신 건가요? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정문식 위원 </b> 이 프로그램이 도에서 계획 수립해서 연구원에다 전문가 부분만 의뢰하신 거죠? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그럼 이 일정은 누가 잡은 겁니까? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 일정은 제2청에서 잡았습니다. 
</p>
<p><b>○ 정문식 위원 </b> 전체 일정은 그럼 2청에서 하신 거고? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그럼 센터장님하고 김학성 교수는 어떤 역할을 하신 거죠? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 3개국을 방문하는데 방문기관 섭외하는 데 있어서 저희가 나름대로 의견을 드렸습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그럼 여기 프리드리에버트재단 가고 폴란드 사회과학아카데미 가시고 바르샤바국립대학교 가시고, 이 세 군데를 추천해 주신 건가요? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 지금 여기에 나와 있는 문건은 초안이기 때문에 실제로는 조금 변동이 생겼습니다. 그래서 독일 같은 경우에는 베를린의 프리드리 에버트재단을 갔었고요. 그다음에 정확한 명칭은 다른데 구 동독재건특별사무관실이 있습니다. 거길 갔었고, 폴란드에서는 바르샤바대학을 가지 않고 폴란드 투자유치청을 갔습니다. 아울러 폴란드 주재 한국대사관을 방문했었고요. 
</p>
<p><b>○ 정문식 위원 </b> 나머지는 동일한 일정이고요? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네. 체코 같은 경우는 체코 산업자원부차관과 면담을 했습니다. 
</p>
<p><b>○ 정문식 위원 </b> 산업부차관 면담이 있었고요. 이 프로그램이 통일전문가 양성프로그램입니다. 알고 계시죠? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네. 
</p>
<p><b>○ 정문식 위원 </b> 여기 보면 일선 시군에서 참여하신 분들이 부단체장하고 기획예산 쪽에 계신 분하고 총무 파트 책임자 이런 분들이 참여하셨거든요. 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정문식 위원 </b> 이런 분들이 이번에 통일전문가 양성프로그램을 다녀오셔서 일선 시군에서 우리 남북협력기금 관련된 대북업무라든가 안 그러면 일선 시군에서 이런 대북업무 진행되는 시가 있었나요? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 다녀오고 나서……. 
</p>
<p><b>○ 정문식 위원 </b> 아니, 그전에도 그렇고 다녀오고 나서도 이게 실무에 반영된 사례가 있나요? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 일단 한수이북의 시군들은 여건만 되면 남북교류협력사업을 독자적으로 해볼 의향을 가지고 있습니다. 그래서 이번 출장이 아마 거기에 많은 참고가 되지 않을까 싶습니다. 
</p>
<p><b>○ 정문식 위원 </b> 독자적 사업시행을 하는 데 있어서 참고가 될 만한 사업이다? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정문식 위원 </b> 우리 센터장님께서 보시기에는 이번 프로그램이 유익하고 필요했던 프로그램이다? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 제가 보기에는 상당히 유익했었습니다. 독일과 폴란드, 체코의 책임 있는 사람들과 만나서 인터뷰를 하고 또 얘기를 직접 들을 수 있는 계기가 돼서 아주 유익했다고 생각합니다. 
</p>
<p><b>○ 정문식 위원 </b> 폴란드 사회과학아카데미에서 하루종일 계신 걸로 돼 있는데요.  
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 폴란드 투자유치청입니다. 
</p>
<p><b>○ 정문식 위원 </b> 투자유치청은 두 번째 날이고요. 첫 번째 날은 폴란드 사회과학아카데미에서만 계셨거든요. 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 폴란드에서 방문지가 두 군데만 정해졌습니다. 첫 번째가 폴란드 투자유치청이고 두 번째가 폴란드 주재 한국대사관이었습니다. 그래서 오전에는 투자유치청, 오후에 한국대사관을 방문했습니다. 
</p>
<p><b>○ 정문식 위원 </b> 여기에는 지금……. 폴란드 사회과학아카데미도 그럼 안 가신 거예요? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네, 그렇습니다. 안 갔습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그럼 바르샤바대학도 안 가신 거고요? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네, 안 갔습니다. 
</p>
<p><b>○ 정문식 위원 </b> 오전에 투자유치청 가고 오후에 한국대사관 가셨다는 거잖아요? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그런데 일정상으로는 바르샤바에 3일 계시잖아요?  
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네. 제가 말씀드리면 바르샤바에 밤에 도착했습니다. 그래서 그다음 날 두 군데 기관방문을 하고 3일째 되는 날 저녁 비행기로 체코로 떠났습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그럼 세 번째 날은 일정 없으신 거네요? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 세 번째 날은 이동하는 일정만 있었습니다.
</p>
<p><b>○ 정문식 위원 </b> 이동은 18시 50분에 이동이시고요. 그러니까 그날은 일정이 하나도 없으신 거네요? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 그렇습니다. 공식방문은 없었습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그러니까 프라하로 출발하신 날은 일정 없이, 그날은 전체 일정 없는 날. 맞죠? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 그렇습니다. 
</p>
<p><b>○ 정문식 위원 </b> 지금 보고서 거의 작성되셨나요? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 지금 출장에 참여했던 분들이 자기 맡은 부분을 갖고 보고서를 작성해서 일부는 보내고 일부는 작성 중인 것으로 알고 있습니다. 전체 취합은 2청에서 하고 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 전체 취합은 2청에서 하시고 센터장님 것은…….
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 저희는 이미 보냈습니다. 
</p>
<p><b>○ 정문식 위원 </b> 센터장님 부분은 송부하셨고. 김학성 교수 것도 송부된 상태입니까? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 김 교수와 제가 같이 작성해서 이미 보냈습니다. 
</p>
<p><b>○ 정문식 위원 </b> 센터장님이 보시기에는 이 통일전문가 양성프로그램이 계속돼야 될 프로그램이라고 생각하십니까, 어떠십니까? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 제가 보기에는 한수이북의 시군에 계신 주요 간부분들은 가능하면 한 번쯤은 이쪽 동부권을 다녀오실 필요가 있다는 생각이 듭니다.  
</p>
<p><b>○ 정문식 위원 </b> 지금 우리 센터장님도 개인적 의견이고 저도 제 개인적 의견이지만 지금 우리가 남북협력사업을 담당하고 있는 부서가 있지 않습니까? 남북협력담당관실에서 하고 있고 실질적으로 일선 시군에서는 북한 업무를 안 하고 있거든요. 그런데 이런, 이게 개인당 한 600만 원 정도씩 예산 들여서 가신 거죠? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 정확한 액수는 저는 모르겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 센터장님 것도 도에서 부담했으니까. 그런데 이게 보면 연속성이 없더라고요. 한 번 갔다 오시고 마는 거더라고요, 담당자들은. 여기에 참여하신 분들을요. 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 이걸 계획할 때 제가 들은 바에 따르면 내년에도 유사한 프로그램을 계약하겠다는 얘기를 들었습니다. 
</p>
<p><b>○ 정문식 위원 </b> 우리가 차라리 남북협력담당관실에 업무자들, 이런 분들이 이런 단기연수가 됐건 해외연수도 가시고 또 국내에서 이런 학위과정이라든가 전문과정도 이수하셔 가지고 업무를 심화시키는 게 더 효율적이지 않느냐라는 의견이 들거든요. 이렇게 지금 일선 시군에 계신 부단체장들이나 예산을 총괄하는 책임자들이나 이런 고위직 공무원들이 한번 이렇게 가서 외국사례 보고 오셔 가지고 그런 분들이 얼마나 이 업무에 관여를 하실지 또 그다음에 관여하신다면 얼마나 효율성이 생길지에 대한 의문이 생겨서 확인해 보는 부분인데요. 개인적으로는 그래도 의미가 있다고 보시는 건가요? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 위원님 지적하신 대로 일단 남북협력담당관실에 근무하는 공무원들의 연수가 가장 중요하다고 볼 수가 있겠습니다. 그러나 아울러 시군에 계신 분들도, 시군에 몇몇 분들 정도는 최소한 통일 과정에 대한 이해는 가지고 있어야만이 향후에 일어나는 여러 가지 상황에 대비할 수 있을 거라고 저는 믿습니다. 그래서 일단은 과장급들부터 먼저 이에 대한 교육이 필요하다는 그런 생각을 저는 하고 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 네, 잘 알겠습니다. 들어가시고요. 2청사에 보낸 보고서 사본 한 부만 제출해 주시기 바랍니다. 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네, 그렇게 하겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 원장님께 여쭤보겠습니다. 이번에 기구개편들이 있었던데요. 민군정책팀을 만드셨더라고요. 전문 예비역 장성들하고 대령분을 모셔서 구성하셨던데 우리 도청에 보니까 안보자문단하고 성격이나 하는 일이 비슷한 것 같습니다. 이분들이 어떻게 보면 좀 더 이론적으로나 현안에 대해서 대안을 내시기 위해서 이렇게 민군정책팀을 만드신 것 같은데 오히려 이렇게 고위직 장성들보다도 지금 좀 더 현업에서 은퇴하신지 얼마 안 되고 또 실무를 담당했던 영관급이라도, 이런 분들이 오히려 지금 군 내부의 논리라든가 활동성이 더 있지 않을까 하는 견해가 있는데 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우선 안보자문단 하는 일하고 중복이 된다고 하는 말씀은 기능상은 그런 측면이 없지 않아 있는데 안보자문단은 말하자면 비상임으로 하기 때문에 영속성이 없고 그런 차원에서 우리는 영속적으로 이 문제를 팔로우 업해야 한다는 차원에서 한 것이고요. 그다음에 아까 말씀하신 건 정확한 말씀인데 지금 우리 연구원에 와 있는 스타급들은 전부 다 최근에 하신 분들입니다. 그러니까 최근에 해서 군 안에 인적 네트워크가 있는 분들을 했고요. 안보자문단 하시는 분들은 오래 전에 예편(豫編)해서 그런 게 좀 덜합니다. 그래서 저희가 그런 걸 고민해 가지고 체계적으로……. 죄송합니다. 로비할 건 로비도 하고……. 
</p>
<p><b>○ 정문식 위원 </b> 당연히 해야죠. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 하는 식으로 하려고 기능을 좀 분할했습니다. 
</p>
<p><b>○ 정문식 위원 </b> 지난번에 경기도시공사가 조성했던 파주에 당동산업단지 같은 경우에도 화학부대 같은 부대가 사업부지 안에 있어서 이전했었거든요. 그런데 실제로 현재 군부대 수준보다도 훨씬 현대화되고 최첨단 설비를 요청해서 경기도시공사에서 그렇게 해줬어요. 그 부분이 협의가 안 되면 산업단지 조성이 안 되니까. 결과적으로 과도하게 하다 보니까 분양가가 올라가는 거 아닙니까? 그런데 실질적으로 그럴 때는, 왜 그러냐 하면 지금 저희가 적정한 현재의 군부대 수준을 유지 안 해준다면 문제가 되겠지만 그거보다 너무 과도하게 요청을 했었거든요. 그런데도 속수무책으로 갔었는데 그런 부분들은, 원장님이 로비라는 표현도 쓰셨지만 사실은 우리 경기도 입장을 잘 대변해 가지고 적정한 수준에서 이전시킬 수 있는 역할들도 해야 되거든요. 
</p>
<p style="padding-left:1.2em">  그리고 지금 경기도 내에서 이런 산업단지라든가 택지개발지구, 이번에 보금자리 같은 경우에도 할 때마다 군부대하고의 업무협의 때문에 지구지정이라든가 도시계획이 잘 안 되고 있거든요. 이럴 때 우리 경기도 입장이라든가 또 군 내부에서 작전계획을 변경할 수 있는 그런 부분들에 대한 상식이 있는 민군정책팀에 계신 분들이나 안보자문단에 계신 분들이 잘 협력해서 할 수 있는 게 우리 실용학문을 하시는 경기개발연구원의 목적에 맞을 것 같습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 좋은 지적 감사하고요. 특히 저도 파주나 고양 이쪽 출신 의원님들하고는 긴밀하게, 현장을 더 잘 아실 테니까 협의도 하고 해서 여론을 수렴할 수 있는 그런 채널을 만들 수 있도록 우리 팀에 얘기를 해놓겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그래서 여기 분장사무에 예시적으로 몇 개 해놓으신 부분을 하겠지만 결과적으로 법령 개정되는 데 있어서 이분들이 좋은 역할을 해주셔야 되거든요. 그래서 이분들 같은 경우에는 아까 말씀드린 것처럼 개발사업에 있어서의 업무협의라든가 안 그러면 군사시설보호구역 해제라든가 이런 것에 있어서 어떻게 보면 도민들이 느끼시는 데 있어서는 가시적 성과를 더 빨리 가져오실 수도 있는 분들이니까 이걸 잘 운영하셔서, 더 필요하다면 확충해서라도 실질적인 혜택이 갈 수 있게끔 뒷받침을 해주시고 또 좋은 결과가 나오면 잘 홍보를 하셔 가지고, 우리 연구원의 위상과도 관련된 문제 아니겠습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 자랑 좀 하나 해도 되겠습니까? 저희가 그동안 군사규제 완화에 대해서 정말 목이 터져라고 지난 한 3년 동안 외쳤는데 지난달에 청와대 경쟁력강화위원회에서 국방부에서 군사규제 완화에 대한 보고를 했습니다. 그 내용을 보니까 저희가 주장했던 내용이 대단히 많이 들어가 있고요. 특히 제가 그날 발언하면서 국방부장관한테 받아낸 답이, “북부의 전략을 바꿔라, 그동안 개활지(開豁地) 전투만 생각했는데 이제는 도시가 들어오고 해야 방어가 제대로 된다.” 이런 얘기를 했더니 대통령님 앞에서 “그런 방향으로 전략을 바꾸도록 계획을 짜서 하겠습니다.” 이렇게 또 해주시고 해서 우리 민군팀이 상당히 기여를 하고 있고요. 좌우간 북부에 계신 의원님들한테 도움이 되도록 채널링을 잘 하게 해놓겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 네. 원장님 말씀처럼 우리 위원들이 결과적으로 도민들의 입장을 대변하는 거니까 도민들 입장을 잘 살펴 주시기를 당부드리겠고요. 또 성과가 나오면 적극적으로 홍보하셔서 우리 연구원의 입장을 잘 알려 주시기 바라겠습니다. 
</p>
<p style="padding-left:1.2em">  또 한 가지 보니까 공공기관평가팀이 기구개편으로 상설화하는 걸로 돼 있는데요. 공공기관 평가가 상당히 중요한 것 같습니다. 지금 우리 경기도 내에 공공기관이 여러 기관들이 생겨서……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 너무나 중요하죠. 
</p>
<p><b>○ 정문식 위원 </b> 이번에 연구원은 서울대에서 평가받으셨더라고요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 따로 받았습니다. 
</p>
<p><b>○ 정문식 위원 </b> 주체다 보니까 따로 받으셨는데 제가 공공기관평가팀, 보니까 이게 연속성이 중요한 것 같아요. 그다음에 평가를 받는 분들이 여기에 대해서 수긍할 수 있는 그런 서로 간의 관계가 되려고 그러면 처음에 평가지표에 대한 설명도 잘 있어야 되고 또 평가 이후의 개선책에 대한 그런 컨설팅과 조언과 앞으로 개선책에 대해서 같이 해나가는 부분이 가장 중요한 것 같은데…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 너무 정확한 말씀이십니다. 
</p>
<p><b>○ 정문식 위원 </b> 이런 부분을 하려면 공공기관평가팀에 좀……. 작년도 예산 갖고서는 상당 부분 부족하지 않을까 그런……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 인력도 충분치 않고 예산도 모자랍니다. 그래서 저희가, 죄송한 말씀이지만 좌판을 일단 벌리고 시작을 하면, 금년에 본격적으로 하게 되면 예산도 좀 더 넣고 인력도 보강하고, 지금 말씀하신 대로 팔로우 업을 통해서 그 기관이 개선할 수 있도록 하는 걸 도와주는 게 중요하지 단순히 평가해서 줄 세우는 것만으로는 미흡하다고 봅니다. 그래서 지금 정 위원님이 정확하게 지적해 주셨는데 그런 방향으로 업무를 확장하고 지속할 수 있도록 노력하겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그때도 제가 이런 예를 들었어요. 경기도시공사하고 경기신용보증재단 같은 경우에는 당기순이익이나 영업이익이 너무 많이 남으면 잘못된 공공기관이다. 처음 설립목적대로 공사 운영이 안 되고 있는 거 아니냐? 경기신보 같은 경우에 S등급 계속 받으면 잘못된 거 아니냐? 적정하게 어려운 기업들에 대해서 보증을 해주고 하다 보면 부도도 좀 나고 악성채권이 생겨야 되는데 계속 건전채권만 있다는 게 너무 처음의 취지하고 안 맞지 않느냐 해서 이번에 지표 변경할 때 반영을 해달래서 그런 부분들을 했는데 공공기관 평가라는 게 경상적인 부분에 대해서 경영적 평가도 되지만 우리 공공기관이 사실은 잘 운영이 돼야지, 경기도청하고 나머지 도민과의 중간지대에 있는 정말 중요한 부분에서 역할하시는 분들이 잘 해줘야 도민들한테 혜택들이 가는 거 아니겠습니까? 그러니까 그런 것들이 또 연구원에서 평가하는 팀이 상설화되면 여기서 평가를 잘해주시는 게 아주 중요한 역할이 되거든요. 그다음에 그분들한테 개선책을 제시하실 때 그런 공공성에 대한 부분들을 강조해 주시는 게 도민들한테 혜택이 가지 않을까 싶어서 다시 한 번 강조를 드리고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 물론입니다. 신용보증재단 말씀하셨습니다마는 저도 같은 공공기관으로서 다른 기관 얘기를 할 입장은 아니지만 아까 지적하신 것이 적합한 지적이 아닌가 싶은 생각이 들고요. 그런 점에서 앞으로 저희가 자문도 하고 이렇게 하면서 도청과 도민 사이에서 일종의 말하자면 링크역할을 하는 이 공공기관들이 대민서비스를 잘 해가지고 도의 역할이 강화되도록 하는 게 중요하기 때문에 그런 점에서 우리 센터가 앞으로 기능을 잘할 수 있도록 배려를 하겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그리고 업무보고 6페이지에 보니까 우리 기금에 대해서 잘 정리해 놓으셨던데 요즘에 여건이 많이 어려워 가지고 운영하시는 데 어려움이 있는 것은 잘 알겠습니다. 그래서 전에 보다는 많이들 신경 쓰고 계신 것 같아서 다행이라고 생각하고요. 보니까 비슷한 시기에 체결이 됐는데도 기관에 따라서 좀 이율들이 차이가나는 사례들이 있더라고요. 제일은행 같은 경우가 제일 낮아요. 양도성예금증서 4.1%가. 같은 2009년도 8월 달에 하더라도. 같은 8월 달에 3개 하시고 그다음에 7월 달에 2개 하셨는데도 유독 제일은행 게 제일 낮더라고요, 눈에 탁 띄게. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 일부러 그렇게 했을 리는 없을 텐데…….
</p>
<p><b>○ 정문식 위원 </b> 그때그때 위원회 개최해서 하시는 건 알고 있는데요. 우리 원장님께서, 기관의 장께서 이런 걸 직접 챙기시다 보면 밑에 운영하시는 분이 더 각별하게 신경 쓸 테니까요. 원장님께서 보다 관심 가지고 챙겨 주시기를 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이걸 좀 제가 챙겨보겠습니다. 잘 알겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 질의 마치고 나머지는 보충질의 때 하겠습니다. 
</p>
<p style="padding-left:2.4em">    (이승철 위원장대리, 전동석 부위원장과 사회교대)
</p>
<p><b>○ 부위원장 전동석 </b> 위원님들 양해해 주시면 상당한 시간이 흘렀고 해서요. 잠시 동안 정회하려고 하는데요. 괜찮으시겠습니까? 
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  잠시 동안 휴식을 위하여 감사를 중지하도록 하겠습니다. 
</p>
<p class=''ar''>(15시29분 감사중지)
</p>
<p class=''ar''>(15시48분 감사계속) 
</p>
<p><b>○ 위원장 김대원 </b> 좌석을 정돈해 주시기 바랍니다. 감사를 계속하겠습니다. 질의하실 위원님 계십니까? 이승철 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이승철 위원 </b> 안녕하십니까? 오전 질문에 이어서 오후에도 질문을 바로 드리도록 하겠습니다. 오전에 제가 말씀드렸던 한 연구원께서 같은 시기에 비슷한 과제로 여러 건을 같이 수행하시는 것에 대해서는 분명하게 지적을 하겠습니다. 그 부분에 대해서는 연구위원회에서 연구과제를 주실 때 좀 더 세밀하게 판단을 해주십사 하는 말씀을 다시 한 번 드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 잘 알겠습니다. 
</p>
<p><b>○ 이승철 위원 </b> 시작하면서 지금 신문기사 내용을 한 가지만 제가 읽어드리겠습니다. 경인일보 10월 26일자인데 “경기도의 싱크탱크인 경기개발연구원이 김문수 지사의 주장과 입장을 그대로 옹호하면서 홍위병 역할을 한다.”라는 그런 내용이 있습니다. “도가 추진 중이거나 계획 중인 주요 정책에 대해 연구하는 정책연구보고서는 매년 70~80편씩 쏟아져 나오고 있다. 하지만 연구보고서 대부분이 김 지사의 발언과 치적을 그대로 되풀이하고 있어 앵무새 노릇을 면치 못하고 있다.” 이런 얘기와 함께 “수도권 규제와 국가균형발전을 비롯해 지방행정체제 개편, 대수도론 등에 대해서도 경기연은 김 지사의 주장을 뒷받침하는 연구보고서를 잇따라 내놓고 있다.”라는 기사가 있습니다. 
</p>
<p style="padding-left:1.2em">  제가 이 기사내용에 대해서 혹시나 경기연에서 무슨 반박하신 자료가 있나 해서 자료요청을 했었는데 전혀 반박하거나 이런 내용이 없었던 것 같습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아, 반박한 사실이 있느냐 하는 것을 여쭤…….
</p>
<p><b>○ 이승철 위원 </b> 네. 혹시 반박한 자료가 있느냐라는 걸, 제가 자료가 있으면 달라 그랬는데 그 자료가 없다고 회신이 왔거든요. 그러면 원장님, 이거 보시고 그냥 아무 말씀 안 하셨습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 속이 많이 탔습니다. 그리고 항의도 좀 했고요. 그런데 저는……. 이보다 더 좋은 기사도 사실 상당히 많습니다. 그래서 이걸 보고서 너무 기자가 일방적으로 판단을 했다고 생각이 돼요. 물론 오전에도 잠깐 그런 지적이 있었습니다마는 저희가 집행부의 정책을 대놓고 비난하거나 반대하거나 하는 건 어렵지만, 그러나 저희가 최선을 다해서 문제가 있는 것은 내부적으로 조율하고 이러면서 저희 의견이 반영되도록 노력하고 있고 그냥 단순히 지사님의 공약이나 이것을 그냥 들고 그렇게 하는 건, 연간 50개 넘는 주요 기본과제와 정책과제는 전부 다 박사들이 자체적으로 판단해서 하는 거고요. 
</p>
<p style="padding-left:1.2em">  그다음에 정책과제가 오는 것도 일부 지사님의 공약사항하고 관련이 있지만 이렇게 70~80편이 다 지사님 거 하려고 그러는 거다 이렇게 하는 것은 제가 보기에는 상당히 문제가 있는데 그렇다고 해서 무슨 정정 보도를 한다고 될 것도 아니고, 똑같은 신문에서 바로 직전에 아까 지적재산권 침해 보도가 있었는데 그것도 사실은 저희가 내부적으로 문제제기를 했지만 이걸 공개적으로 하는 것이 좋을까 좋지 않을까 판단을 하다가 사실은 저희가 조용히 덮었습니다. 그래서 답답할 뿐입니다.
</p>
<p><b>○ 이승철 위원 </b> 잘 알겠습니다. 속이 타시고 그러셨으면 기본적으로 사실 경기개발연구원에서 여러 가지 자체적인 홍보도 있고 많이 있는데 그 부분에 대해서 어떻게 한 말씀도 안 하셨나 해서 제가 그래서 지금 여쭤 본 겁니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 여기 책임자 되시는 분을 제가 사석에서, 사석이 아니라 공석이나 다름없는 곳에서 한번 만났는데 이 점에 대해서 약간 죄송하다는 투의 말씀을 하셔서 제가 바로 그랬습니다. “저희가 불찰이 있어서 그렇지 않겠습니까? 저희가 반성도 하고 이렇게 하겠습니다.” 하는 얘기를 제가 드린 적은 있지만 참 이게 그렇습니다. 
</p>
<p><b>○ 이승철 위원 </b> 잘 알겠습니다. 질문을 드리겠습니다. 제가 요청한 자료 612페이지 보시면 CEO Report랑 Policy Brief에 대해서 예산, 연구과제명에 있는데 뭡니까? 내용을 모르겠네. 연구과제 집행액이 8,700여만 원, 4,600여만 원…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 몇 번이신가요?
</p>
<p><b>○ 이승철 위원 </b> 612, 613.
</p>
<p style="padding-left:2.4em">    (좌승희 경기개발연구원장, 관계직원을 바라보며)
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이게 CEO Report를 전부 다 포함해서 책정된 예산이죠? 
</p>
<p><b>○ 이승철 위원 </b> 그 내용을 좀 알고 싶습니다. 이게 전체 책정된 돈입니까, 아니면 따로 연구를 하신 겁니까? 지금 과제명에 들어가 있어요. 76가지 연구과제에 들어가 있거든요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> CEO Report라고 하는 그 대과제 속에 연간 저희가 40건을 계획해서 진행하고 있고요. 아까 오전에 제가 보고드렸지만 집행률이 좀 떨어지는데 다른 연구과제는 일단 과제가 시작이 되면 집행 중이라고 해서 나오는데 이거는 딱 2~3일, 일주일 안에 이게 자료가 나오는 거라서 출판이 돼야지만 이걸 잡기 때문에 그렇습니다. 
</p>
<p><b>○ 이승철 위원 </b> 원장님 제가 여쭤보고 싶은 것은 612페이지에 나와 있는 CEO Report라는 게 8,700여만 원에 대한 집행액이 되어 있거든요. 이 내용이 지금 우리 책자로 발간되는 CEO Report 그 액수입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 2008년도에…….
</p>
<p><b>○ 이승철 위원 </b> 2008년도에 나온 CEO Report 전체 액수가 8,700여만 원이 소요가 된 겁니까? 
</p>
<p style="padding-left:2.4em">    (좌승희 경기개발연구원장, 관계직원을 바라보며)
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 8,700이 전부인가요?
</p>
<p style="padding-left:2.4em">    (「8,700이 맞습니다.」하는 관계직원 있음)
</p>
<p><b>○ 이승철 위원 </b> 8,723만 5,000원으로 되어 있지 않습니까? 이게 맞아요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 맞습니다.
</p>
<p><b>○ 이승철 위원 </b> 그러면 CEO Report로 지출된 돈이, 연구비가 8,723만 5,000원이 맞습니까?
</p>
<p style="padding-left:2.4em">    (「인쇄비…….」하는 관계직원 있음)
</p>
<p style="padding-left:1.2em">  인쇄비나 이런 게 다 들어갔겠죠. 저자료나…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아닙니다. 제가 말씀을 올리겠는데요. 74%가 인쇄비입니다. 이걸 해가지고…….
</p>
<p><b>○ 이승철 위원 </b> 제가 그걸 여쭤보는 게 아니고 제가 별도로 가지고 있어요. 저기는 주신 자료에 이렇게 어느 분이 얼마 집행됐다 하는 것까지 다 가지고 있는데 제가 여쭤보고 싶은 것은 그걸 말씀드린 거고요. 
</p>
<p style="padding-left:1.2em">  제가 아까 오전에도 질문드렸듯이, 지금 자료 주신 것에도 보면 CEO Report를 쓰시는 분이, 지금 여기 2008년도 자료밖에 안 갖고 있는데 제가 가지고 있는 것은  2005년도부터 쓴 목록을 가지고 있거든요. 이 목록을 보시면 CEO Report 쓰신 분이 2005년도, 2006년도에 10편이 실렸습니다, 책자가 10편이.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 2005년도에는 그 제도가 없었는데. 제가 온 다음에…….
</p>
<p><b>○ 이승철 위원 </b> 아닙니다. CEO는 있어요. CEO는 있고요. Policy Brief는 2008년도, 2009년도만 있고 CEO는 2005년도 자료까지 있거든요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아, 몇 개 있었던 모양이군요. 제가 와서…….
</p>
<p><b>○ 이승철 위원 </b> 아니, 제가 말씀드릴게요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 맞습니다. 
</p>
<p><b>○ 이승철 위원 </b> 맞죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 이승철 위원 </b> 2005년도, 2006년도에 10편의 책자가 발행이 됐는데 10편 중에 8편을 한 분이 하셨어요. 한 분이 하셨거든요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이게 그 당시에…….
</p>
<p><b>○ 이승철 위원 </b> 잠깐만요. 제가 질문드리고요. 그리고 2008년도에도 나온 거에 이분이, 제가 이분에 대해서 개인적으로 저기한 건 아니고 이분이 지금……. 제가 오전에, 정책연구과제도 이분이 최고 많이 썼거든요. 그리고 CEO Report도 이분이 다 했어요, 다. 2005년도부터 2009년도까지 총 17편의 책자를 내셨습니다, 이분이. 그래서 제가 아까 부원장님께 말씀드렸던 것처럼 이렇게 많은 양을 어떻게 한 분한테 다 몰아서 책을 만들 수 있느냐? 부원장님께서 연구위원회에서 결정을 하시고 CEO Report나 이 부분에 대해서는 분명히 원장님께서도 감수작업까지 하셔 가지고 내보내신 것으로 제가 알고 있는데 이 당시에 분명히 이게 다 됐을 것 아닙니까? 2008년도에도 지금 이렇게 많은…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 사실은 틀리지 않습니다. 말씀하신 대로 사실인데. CEO Report나 Policy Brief는 다른 연구하고 달라서 결정되는 절차가 좀 다릅니다. 이거는 단기정책 대응이기 때문에 사실은 제가 시켜서 하기도 하고 어디서 요청을 제가 부탁을 해서 하기도 하고 여러 가지 방식으로 하지만 정책분석팀이 이걸 관리하는데요. 제가 오기 전에도 CEO Report가 좀 있었던 것은 조성호 박사가 제가 오기 전에 정책분석팀장을 하고 있었습니다. 그래서 다른 일반박사들이 여러 가지 업무 때문에 잘 못하기 때문에 본인이 팀장으로서 자기가 할 수 있는 분야를 중심으로 해서 1년에 몇 건씩 쓴 걸로 이렇게 알고 있고요. 최근에 와서 이 사람이 또 많이 쓴 것은 이 사람이 주로 하는 게 지방자치제도 개편문제라든가 이쪽을 하기 때문에 수요가 많아요. 그래서 유사하게 연결된 주제를 많이 쓰다 보니까 그렇게 됐는데 그렇다고 해서 이 사람이 이것 때문에 자기가 하는 기본과제라든가 이런 것을 못할 정도는 아니지 않은가! 제가 판단하기에는 그렇습니다마는 말씀하신 대로 이렇게 편중이 되면 물론 문제가 있기 때문에 모두에 지적하신 대로 저희가 이런 일이 안 생기도록 조절을 하고 연구심의위원회도 이런 걸 관심을 가지고 배려를 하도록 하겠습니다. 
</p>
<p><b>○ 이승철 위원 </b> 아까 전동석 위원께서 질문하셨을 때도 그렇고 연구원들의 과중한 업무에 대해서 얘기를 하셨는데 제가 봤을 때 이런 부분이 누가 봐도, 뭐 전문적인 분들이 보셨을 때는 어떻게 판단하실지 모르겠지만 일반인들인 우리가 봤을 때는 굉장히 많은 양의 업무를 수행하고 있다 이렇게밖에 저희들이 볼 수 없거든요. 그래서 처음에도 제가 그 부분에 대해서 자꾸 말씀을 드리고 지적을 드렸던 사항 중의 하나입니다. 그 부분은 다 알아들으셨으니까…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 이해하겠습니다. 
</p>
<p><b>○ 이승철 위원 </b> 한 가지만 더 질문을 드리도록 하겠습니다. 아까 부원장님과 잠깐 대화하는 과정에서 제가 궁금했던 거 하나는 말씀을 안 드렸는데 연구원들이 연구하는 과제가 기본연구과제, 정책연구과제, 수탁과제도 있고요. 그다음에 지역과제는 원래 하나밖에 없으니까 그게 별로 저기가 없고 CEO Report나 Policy Brief나 이렇게 있는데 제가 여기 자료에 보면, 595페이지 첫 자료입니다. 2007년도, 2008년도, 2009년도 쭉 연구비 내역서가 있습니다. 여기 보면서 제가 제일 의심스럽다고 생각했던 게 뭐냐 하면 기본연구과제나 여기 수탁연구과제를 따로 제가 자료를 받았는데 수탁연구과제랑 정책연구과제랑 다른 점이 뭐가 있습니까? 따로따로 다른 게, 연구과제 내용.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 기본연구과제는 상당히 표현이, 이게 영어표현이 되겠습니다. 좀 아카데믹하고, 그러니까 분석을 중심으로 해서 자기 연구분야의 중심이 될 수 있는 연구를 하는 거죠. 그러니까 정책연구하고는 좀 다릅니다. 이론적인 연구가 많고 이걸 기초로 해서 그다음에 정책연구를 하는 셈이 되고요. 
</p>
<p><b>○ 이승철 위원 </b> 연구하는 과정은 거의 비슷하잖아요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 과제는 비슷합니다. 
</p>
<p><b>○ 이승철 위원 </b> 기본연구과제랑 정책연구과제랑 수탁연구과제는 연구하는 과정은 비슷하잖아요. 비슷한 건데, 제가 여쭤보고 싶은 것은 기본연구과제 또 수탁연구과제 그다음 지역연구과제나 이런 것들은 집행된 예산액의 잔액이 분명히 여기 다 남아 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잔액이요?
</p>
<p><b>○ 이승철 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 기본연구과제는 남아 있기가…….
</p>
<p><b>○ 이승철 위원 </b> 그런데 정책연구과제만 여태까지 잔액이 남아 있는 게 없거든요. 그 부분에 대해서는, 어떻게 연구상태는 다 똑같은데 정책연구과제는 연구가 딱 끝나는 순간에 제로로 털고 나오거든요. 이 기본연구과제나 수탁연구과제는 다 치르고 남은 거에 대해서 잔액이 꼭 남아 있거든요. 그런데 이것만 없다. 그런데 부원장님께서 답변을 해주셨을 때 다 남아 있다고 저한테 분명히 말씀하셨거든요. 정책연구과제도 남아 있다.
</p>
<p><b>○ 부원장 조응래 </b> 제가 설명을 좀 드리겠습니다. 부원장 조응래입니다. 기본과제나 수탁과제 같은 경우에 집행잔액이 남고요. 정책과제도 과제가 끝났을 때는, 처음에 예산을 1,000만 원을, 저희가 보통 평균적으로 한 1,000만 원이라고 했는데 그게 인쇄까지 다 해서 600만 원, 700만 원만 쓰고 300만 원이 남았을 때 그것을 잔액으로 남기지 않고 풀 예산으로 다시 포함을 시켜버립니다. 그러니까 쓴 것만큼만 그냥 끝내고 나머지 집행잔액은 정책과제의 풀 예산으로 다시 집어넣어 가지고 편성을 해서 쓰기 때문에 정책과제는 기본적으로…….
</p>
<p><b>○ 이승철 위원 </b> 다른 기본과제나 수탁연구과제는 그렇게 안 하시고요?
</p>
<p><b>○ 부원장 조응래 </b> 그렇게 안 합니다.
</p>
<p><b>○ 이승철 위원 </b> 이유는요?
</p>
<p><b>○ 부원장 조응래 </b> 그러니까 정책과제는 저희가 수시로 필요하다고 도에서 요구하는 그런 사업들을 하기 때문에 예산을 너무 과다하게 편성해 놓고 쓰다 보면, 집행잔액이 남았는데도 그것을 안 쓰게 되면 다른 예산들이 부족해지기 때문에 저희가 그것은 수시로 점검을 해가지고 집행률이 낮으면 예산도 다시 한 번 짜게 하고 그런 과정들을 겪기 때문에 100% 다 집행잔액이 없이 추진되는 그런 내용입니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그러니까 연초에 저희가 사업계획을 짤 때 기본연구라든가 이런 것은 개별연구를 중심으로 해서 다 사업계획이 나오는데 정책과제에 대해서는 사실 연초에 다 할 수가 없죠. 도에서 무슨 일이, 어떤 주제가 올지 모르니까 그걸 풀로 예산을 해놓고 이 속에서 정책과제를 요구하면 하겠다 이렇게 해놓기 때문에 거기서 쓰다가 남으면 들어오고 하지만 개별적으로 하는 개인의 기본연구과제는 애초부터 거기에 예산이 확정이 돼서 들어가기 때문에 연간 쓰다가 보면 남는 게, 완전하게 쓰지 못하고 남는 셈이 되는 거죠, 그 예산이.
</p>
<p><b>○ 이승철 위원 </b> 그러면 예산집행하면서 남는 잔액에 대해서는 다시 들어와서 풀로 한다?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 정책연구과제의 경우…….
</p>
<p><b>○ 이승철 위원 </b> 그러면 기본연구과제 같은 경우는…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그건 남으면 연말에 다음 해로 이월해서 넘어가죠.
</p>
<p><b>○ 이승철 위원 </b> 아, 기본연구과제는 그렇게 하고요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 이승철 위원 </b> 여기 지금 주신 자료에는 이런 식으로만 표시되어 있으니까…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 죄송합니다. 
</p>
<p><b>○ 이승철 위원 </b> 연구과제 중에서 정책연구과제는 제로로 다 만들어 놓고 일반 기본연구과제는 다 남아 있는 걸로, 집행률이 다 남아 있는 걸로 표시를 해주시니까…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이해하는 데 어려움이…….
</p>
<p><b>○ 이승철 위원 </b> 제가 이해하는 데 좀 어려움이 있는 것 같습니다. 그래서 아까 오전에 질문했듯이 업무추진비나 여비 같은 경우에 제가 사실 세밀한 부분까지 말씀드리기가 좀 뭐해서 말씀을 잘 안 드렸는데 그 부분에 대해서 좀 더 세밀하게 해주십사 하는 말씀을 드리고요. 
</p>
<p style="padding-left:1.2em">  마지막으로 제가 사실 장애인에 대한 것을 달라 그랬었는데 장애인 물품구입에 대해서 쓰신 자료를 다시 갖다 주시는 바람에 질의는 그냥 안 하도록 하겠습니다. 특별히 원장님께서 장애인 쪽에 되어 있는 물품에 대해서는 웬만하면 여기서 구입할 수 있으면 이쪽 것을 구입해 주십사 하는 말씀을 드리면서…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 잘 알겠습니다. 
</p>
<p><b>○ 이승철 위원 </b> 마지막 질문을 마치면서 제가 원장님께 마지막으로 당부의 말씀을 드리겠습니다. 경기도의 싱크탱크라 불리는 경기개발연구원을 모든 도민들이 사실 지켜보고 있습니다. 여기서의 연구과제가 경기도민의 삶의 질 향상뿐만 아니라 대한민국을 이끌어가는 정책을 여기서 만들어낸다고 보고 있습니다. 도민의 세금으로 운영되고 있는 연구기관인 만큼 책임을 지고 원장님께서 좀 더 세심한 배려와 관심을 갖고 운영해 주시기를 다시 한 번 당부의 말씀을 드리면서 질문을 마치도록 하겠습니다. 감사합니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 말씀 명심하겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 이승철 위원님 수고하셨습니다. 다음 질의하실 위원 신청해 주시기 바랍니다. 정문식 위원 질의해 주시기 바랍니다. 
</p>
<p><b>○ 정문식 위원 </b> 추가질문 드리겠습니다. 2009년도 연구사업 추진실적 보니까 신규사업으로 광고공모전이 하나 있습니다. 그리고 또 광고공모전 관련해 가지고 언론에 광고도 경인일보하고 시대일보에 두 번 하셨던데요. 이 광고공모전 하셔 가지고 거둘 수 있는 성과는 어떤 게 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리가 2년째 했습니다. 이번에는 작년보다 훨씬 더 작품들이 좋았다고 생각하는데요. 저희가 홍보용으로 많이 씁니다. 저희 연구원의 이미지 광고를 경쟁을 통해 가지고 뽑는 건데 거기서 대상서부터 쭉 뽑아 가지고 우리가 여기저기 대외홍보 활동할 때 그걸 내세워 가지고 쓰기 때문에 제가 보기에는 상당히 의미가 있다고 생각을 하는데요.
</p>
<p><b>○ 정문식 위원 </b> 연구원에 대한 홍보용 광고 대상인가요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇죠. 한번 비행기하고 쪽배도 보여드리고 하면 좋을 것 같은데.
</p>
<p><b>○ 정문식 위원 </b> 그러면 2년 하셨는데 계속 하시는 사업인가요, 이거는? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 쓰다가 참신성이 떨어지면 다시 하고, 꼭 매년 해야 될 필요가 있는지 잘 모르겠습니다마는, 한번 검토를 해봐야 하지 않을까 싶습니다.
</p>
<p><b>○ 정문식 위원 </b> 그러니까 광고공모전이 전체적인 경기도라든가 이런 거랑 관련된 건 아니고 경기개발연구원에 대한 대외적인 홍보, 이미지 광고…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니다. 그런데 이게 그걸 우리가 쓰는 것도 중요하지만 이 공모전 하는 과정에서 많은 사람이 여기에 어플라이(apply)하기 때문에 그게 연구원에 대한 관심을 많이 높이고 그런 효과도 있다고 제가 들었습니다. 
</p>
<p><b>○ 정문식 위원 </b> 광고에 종사하시는 분들이나 학생들이나 이런 분들이 관심을 가지게 되니까 효과가 있다? 그래서 실제로 공모전에 채택된 공모작품을 활용하고 계신 건가요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 금방 제가 보여 올리겠습니다.
</p>
<p><b>○ 정문식 위원 </b> 그러면 보여 주시고요. 업무보고 63페이지 보면 연구홍보 해가지고  신문사에 스물한 번 광고 게재하신 것 같은데요. 총 금액이 얼마입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 홍보팀장이 보고하도록…….
</p>
<p><b>○ 정문식 위원 </b> 네, 실무자가 답변하셔도 좋습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 김성진 홍보팀장이 보고 올리겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 네.
</p>
<p><b>○ 홍보팀장 김성진 </b> 홍보팀장 김성진입니다. 2009년도 광고홍보비 집행내역은 총 8억 3,000만 원 정도 되어 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 스물한 번 집행하신 게 8억 3,000이에요?
</p>
<p><b>○ 홍보팀장 김성진 </b> 11월 16일 현재로 저희가 지금 잡고 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그러니까 스물한 번이 8억 3,000이란 얘기세요, 안 그러면…….
</p>
<p><b>○ 홍보팀장 김성진 </b> 아닙니다. 24건에 대한 겁니다. 지금 11월 달 내용을 업데이트한 상태입니다. 
</p>
<p><b>○ 정문식 위원 </b> 아, 그러면 21건인데 총 24건이 진행될 거고 총 예산은 8억 3,000이다?
</p>
<p><b>○ 홍보팀장 김성진 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그럼 이게 1회당 어느 정도 나가는 겁니까? 이게 주로 신문지면에 나가는 광고죠?
</p>
<p><b>○ 홍보팀장 김성진 </b> 신문지면도 있고요. 방송도 있고 그다음에 배너광고도 같이 진행하고 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그럼 가장 비싼 건 어떤 거고 가장 싼 거는 어떤 겁니까? 
</p>
<p><b>○ 홍보팀장 김성진 </b> 현재 진행 중이거나 진행 예정 중에서…….
</p>
<p><b>○ 정문식 위원 </b> 여기 지금 광고로 잡혀 있는 거 있잖아요. 여기 광고로 잡혀 있는  것 중에 YTN 공익캠페인도 있고 오마이뉴스 같은 경우에는 배너일 테고 동아일보나 경기일보나 시대일보나 이렇게 지면들도 있고 한데 신문을 기준으로 하면 신문사당 어느 정도 되는 거죠?
</p>
<p><b>○ 홍보팀장 김성진 </b> 이게 광고내용에 따라서 좀 다릅니다. 예를 들어서 창간광고 같은 경우에 1회에 끝나는 이미지광고 같은 경우는, 보통 지방지 같은 경우는 300만 원 정도 선에서 하고 있고요. 중앙지 같은 경우는 가급적 1,000만 원 정도에 맞춰서 진행을 하려고 하고 있습니다. 반면에 기획기사 같은 경우는 저희가 자체적으로 판단하기에 홍보효과가 오히려 이미지광고보다 높다고 생각하고 있기 때문에 좀 더 높은 단가를 책정해서 지금 진행을 하고 있습니다. 이 단가 같은 경우는 저희가 한국언론재단을 통해서 단가의 적정성을 의뢰하고서 거기에 따라서 진행을 하고 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그럼 기획연재기사 같은 경우에도 기획연재기사랑 같이 광고가 나간다는 얘기인가요?
</p>
<p><b>○ 홍보팀장 김성진 </b> 그러는 경우가 있고요. 예를 들어서 저희가 5회 기획기사라고 할 경우에 5회를 다 기사로 하는 경우도 있고 4회 기사에 1회 이미지광고 이렇게 진행하는 경우도 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 지금 말씀하신 광고내역에 대해서 자료로 따로 한 부 주시기 바랍니다. 
</p>
<p><b>○ 홍보팀장 김성진 </b> 네. 11월 16일 현재 자료를 한 부 준비해서 드리겠습니다. 
</p>
<p style="padding-left:2.4em">    (관계직원, 정문식 위원에게 책자를 건네며)
</p>
<p><b>○ 정문식 위원 </b> 네, 들어가셔도 좋습니다. 지금 광고공모전 하신 도록은 제가 받아봤는데요. 아주 참신하고 좋은 아이디어들이 많이 있는 것 같습니다. 이건 전체 예산이 얼마죠, 원장님? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 3,000만 원입니다.
</p>
<p><b>○ 정문식 위원 </b> 1회당 3,000만 원?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 3,300. 죄송합니다. 
</p>
<p><b>○ 정문식 위원 </b> 상당히 많은 작품들이 선발이 되고, 선정이 되고 있는데요. 상당히 아이디어들이 많네요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 그래서 저희가 여기저기 쓰고 있습니다. 경품도 제법 많이 나갔고요. 대상은 300만 원이고 그렇습니다. 그러니까 1,000만 원이 상금으로 나갔고 나머지는 행사비용 이런 게 2,000만 원 해가지고……. 저도 개인적으로는 그렇게 IT세대가 아니라서 이게 또 얼마나 가치가 있는지, 몇 번 제가 브레이크를 걸고 그랬는데 여러 사람들이 이걸 해야 된다고 그러고 자문을 받아 가지고 해보니까 좋다고 해서 제가 이것을 하는 걸로 했습니다. 
</p>
<p><b>○ 정문식 위원 </b> 저는 이 사업이 부정적이거나 해서 말씀드린 건 아니고요. 어떤 취지로 하시는지도 궁금하고 이게 계속적으로 해마다 하셔도 좋은 사업인지 궁금해서 한번 여쭤본 건데 아이디어가 1회 때랑 2회 때랑 또 많은 차이들이 있고 의견수렴이 되는 것 같아서 좋은 제도인 것 같은데. 우리 도에 있는 디자인총괄본부라든가 이런 부분들하고도 같이 하셔 가지고 또 사업도 연계하시면 더 좋지 않을까라는 생각이 들고요. 이렇게 도록으로 만들어 놓으니까 참 예쁜데 실제적으로 잘 활용하셨으면 좋겠다는 생각이 듭니다. 잘 활용해 주시고.
</p>
<p style="padding-left:1.2em">  원장님! 부설 과학기술센터, 작년 행감 때도 그렇고 업무보고 때도 계속 위원들께서 이 부분이 이제 좀 별도로 정리돼야 되지 않느냐라는 의견들이 많이 있었는데 아직도 부설로 같이 계신데…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 도에서 아마 결정이 거의 나지 않았나 싶은데요. 내년에는 독립하는 걸로, 독립한다는 게 우리 센터만 독립하는 게 아니라 과학기술 관련된 기관들을 관리하는 어떤 엄브렐러(umbrella), 과학기술진흥원 이런 개념으로 해서 바이오센터하고 우리 센터를 같이 묶고 해서 독립기관으로 출범하는 걸로 거의 얘기가, 결론이 나고 있는……. 지사님 결심은 난 걸로 알고 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그러면 지금 말씀하신 것처럼 과학진흥원 정도의 단위로 해서 분리 운영되는 걸로 진행되고 있다? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 금년은 아직 안 됐기 때문에 저희 쪽에 와서 하고 있지만 지금 그런 상황입니다. 
</p>
<p><b>○ 정문식 위원 </b> 알겠습니다. 사실 예산도 많고 중요한 부분인데 저희 상임위에서도 그렇고 또 경투라든가 이런 데서 보다 심도 있게 다뤄져야 될 부분인데 너무 업무가 연관성 때문에 소홀히 지나가는 면이 있는 것 같아서 연구원 차원에서도 의견을 내셔서 이 부분은 분리 진행하는 게 맞을 것 같아서 말씀드리고요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 알겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 작년에 제가 행감하면서 사전 타당성 조사나 적격성 용역 같은 거 수행하시는 거 도로교통분야 관련돼서 예를 들어드린 적이 있습니다. 작년 행감 때, 기억하실지 모르겠는데 그때 과천-의왕고속도로나 제3경인고속도로 관련해서 말씀드렸었는데 우리 경기개발연구원이 당연히 실용적 학문을 하고 경기도의 장래 발전동력이라든가 도민들의 편안한 환경과 그런 혜택들을 위해서 노력하시는 부분들이 당연히 맞고 또 그렇게 가신다고 생각하는데요. 요즘에 보면 국회 예산정책처의 기능이 아주 긍정적이고 효율적이다라는 평가를 많이 받고 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그런 보도가 있는 걸 봤습니다. 
</p>
<p><b>○ 정문식 위원 </b> 네. 그런데 거기 핵심 중에 하나가 예산정책처에서 정치적 판단이나 이런 정책결정의 부분에 있어서 상당히 정치적 부분들은 배제하고 그런 현 상황에 있어서의 판단을 위주로 하고 있기 때문에 자리를 잘 잡아가고 있다고 하는데 경기개발연구원이 예산정책처와의 기능은 좀 다르기 때문에 꼭 그렇게 갈 수 없다는 건 저도 개인적으로 동의를 하는데 지금 우리가 이렇게, 지금 정책과제 중에, 기본과제보다도 정책과제 중에서 도와 관련된 사업들에 있어서 어떨 때는 좀 억지스러운 부분이나 또 나중에 다소 무리가 나타나는 부분들에 대해서, 작년에도 원장님께서 저한테 그런 부분들은 좀 우리 연구원들께서 좀 더 자유롭게 연구할 수 있는 방안을 만들겠다고 하셨거든요. 그래서 저도 그런 방향으로 주문을 드린 거고. 그래서 이거는 우리가 연구원 기본 운영방침에 있어서의 큰 틀에서 좀 방향성 제시가 있어야 될 것 같아요. 우리가 기본적인 현황에 대한 거라든가 어떤 예비타당성이라든가 적격성 조사를 할 때 있어서 견지돼야 될 자세라든가 이런 것에 있어서의, 남들이 보기에 우리가 도의 정책적 기반을 대변하는 면도 분명히 있고 또 그런 거를 중앙논리가 아니고 우리 경기도의 논리로 대변해야 할 부분도 있지만 일정 부분은 경기도의 도지사라든가 도의 집행부들이 가는 데 있어서 견제할 수 있는 역할을 우리 연구원에서 이론적으로나 내용적으로 해줘야 되는 부분이 있을 거거든요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아주 정확한 지적을 해주셨습니다마는 제가 그냥 “잘 알겠고 그렇게 하겠습니다.” 해서 될 일은 아닌 것 같고요. 
</p>
<p><b>○ 정문식 위원 </b> 작년에 그렇게 답변하셨는데 변화가 없으셔서…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이게 문제가 어떠냐면 집행부에서 예산을 받기 때문에 집행부 산하에 있는 기관은 집행부에 대해서 바른 소리를 하기가 참 어렵습니다, 실질적으로. 아시다시피 중앙도 KDI나 이런 데는 중앙정부가 하는 일을 얘기하기 힘든데 국회에 가 있기 때문에 그 기능이 되는 거거든요. 그래서 제가 아이디어를 낸 게 바로 의정연구센터입니다. 시작은 연구원에서 하지만 이 기능이 조금 더 활성화되면 의회에서 이 센터를 가져가시면 된다고 생각해요, 제 개인적인 생각으로는. 그래서 의회 안에 국회 무슨……. 
</p>
<p><b>○ 정문식 위원 </b> 예산정책처요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그와 같은 역할을 할 수 있는 기관으로 여러분들이 키워주시면, 그러고 나서 가져가시면 그게 정답이지 저희가 노력은 하겠지만 사실은 좀 어렵지 않을까! 기대에 부응하기가 쉽지는 않겠다는 생각이 들지만 그럼에도 불구하고 저희가 또 그런 역할을 하도록 노력은 해야 하지 않겠습니까? 상황이 그렇습니다. 좌우간 의정연구센터를 제가 처음에 만들 때 여러 가지 구상을 해서 했기 때문에 기획위원회에서 그 점을 잘 감안해서 서포트해 주시면 조만간에 의회 안의 연구기능으로서, 우리 과학기술센터를 독립하는 것과 비슷하게 할 수 있으면 좋지 않을까 하는 생각을 해봅니다. 
</p>
<p><b>○ 정문식 위원 </b> 네. 원장님의 의정연구센터에 관한 애정이나 제안도 감사하고 또 저희 의회에서도 잘 검토돼야 할 부분이라고 생각하고요. 제가 말씀드린 것 중에 하나는 이런 거예요. 연구원에 윤리강령 같은 것도 있고 연구원의 원훈같이 목표도 있지 않습니까? 그런 것에 있어서의 큰 틀에서라도 학자적 양심뿐만 아니라 우리가 정책적 결정을 하는 데 있어서 기본적으로 중앙논리가 아니고 도의 입장을 대변하는 부분은 분명히 우리가 인정하고 인지해서 가야 하지만 그런 면에 있어서 도지사나 도 집행부의 가는 방향에 있어서 우리가 정확히 판단하고 조언할 수 있는 부분에 대한 거를 선언적 의미로라도 표시를 하시는 게 보다 더 효율적이지 않겠느냐 하는 건의입니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그래서 저희가 공개적으로 당당하게 할 수 있으면 좋겠지만 그건 여러 가지 어려움이 있고, 우리가 개별 박사들이 지사님한테 보고를 많이 합니다. 또 도에 가서 협의회도 하고 그렇기 때문에 그 과정에서 저희가……. 우리 박사들이 원칙에 안 맞는 얘기할 사람들이 아니기 때문에 그렇게 해서 인포멀(informal)하게 대화를 통해서 의견은 제시할 수 있고 그렇게 합니다마는 공개적으로 깃발을 들고 이게 잘못됐다 이렇게 하는 건……. 하지 않겠다는 얘기가 아니라 제가 약속을 하더라도 조금 빈말이 될 가능성도 있고 해서 최선을 다해 보겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그러세요. 원장님도 최선을 다하시고요. 또 우리가 의회에서 역할을 할 부분이 있다고 하면 의회랑 허심탄회하게 논의하셔서 대안을 마련하는 데 저희도 같이 동참할 수 있게 해주시고. 
</p>
<p style="padding-left:1.2em">  제가 연구원 올 때마다 드리는 말씀인데 저는 연구원에서 예산이라든가 인력이라든가 이런 부분들이 좀 더 확충되고 보다 적극적인 연구라든가 대안들을 내셔서 이런 것들이 도정에, 그러니까 도가 집행하고 나서 평가받는 게 아니고 도가 가는 방향성에 대해서 제시하시고 또 거기에 대해서 책임도 지시는 그런 자세로 가셨으면 하는 바람이고요. 그런 차원에서 아까 말씀드린 공공기관평가팀이라든가 민군협력팀 운영하시는 이런 부분들도 분명히 의미 있는 부분이고 또 성과를 낼 수 있는 부분이라고 생각합니다. 이런 부분들에 대해서 원장님과 연구원에 계신 모든 식구들이 아주 명예를 가지시고, 자부심을 가지시고 도정발전에도 기여해 주시고 도민발전에 기여해 주시기를 당부드리겠습니다. 이상 마치겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 감사합니다. 
</p>
<p><b>○ 위원장 김대원 </b> 정문식 위원 수고하셨습니다. 다음 질의하실 위원 신청해 주시기 바랍니다. 더 질의하실 위원 안 계시죠? 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원이 안 계시면 이상으로 경기개발연구원에 대한 질의와 답변을 모두 마치겠습니다. 
</p>
<p style="padding-left:1.2em">  장시간 열의를 갖고 감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료 준비와 위원님들의 질의에 성실히 답변해 주신 좌승희 원장님을 비롯한 임직원 여러분께 감사를 드립니다. 
</p>
<p style="padding-left:1.2em">  오늘 위원님들께서 감사 시 지적해 주신 사항은 도민의 뜻이니 만큼 이를 겸허히 받아들여서 연구원 업무에 적극 반영하여 경기도의 싱크탱크인 경기개발연구원이 한 단계 도약될 수 있도록 최선의 노력을 다해 주시기 바랍니다. 아울러 모두에서 말씀드렸다시피 추후에 행정사무감사 종합감사나 또 저희들 예산심의 시 또 업무보고 시 모자라는 부분에 대해서 충분히 설명하고 협조를 구할 수 있는 사안은 사전에 설명할 수 있는 자리가 마련돼서 오해가 없기를 바랍니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 연구원 임직원 여러분! 수고하셨습니다. 이상으로 경기개발연구원에 대한 2009년도 행정사무감사를 마치겠습니다.  
</p>
<p class=''ar''>(16시26분 감사종료)
</p>
<p><hr /></p>
