insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2008.11.13. 목요일] 경기개발연구원 — 기획위원회 2008년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제7대 경기도의회 기획위원회</b> · 2008년도 행정사무감사(2008. 11. 12. ~ 2008. 11. 21.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2332" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2008년도 행정사무감사
</p>
<h4>기획위원회 회의록 
</h4>제2호
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 2008년 11월 13일(목)
</p>
<p>장  소 : 경기개발연구원회의실
</p>
<p><hr /></p>
<p class=''ar''>(11시11분 감사개시)
</p>
<p><b>○ 위원장 김대원 </b> 좌석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기개발연구원에 대한 2008년도 행정사무감사를 시작하겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기개발연구원 원장을 비롯한 임직원 여러분! 안녕하십니까? 기획위원회 감사위원장 김대원입니다. 오늘 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2009년도 예산안 심사자료 및 정보 획득을 통해 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다 할 수 있습니다. 따라서 경기도의 싱크탱크인 경기개발연구원의 운영실태를 감사하는 것이니만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  끝으로 증인선서에 앞서 한 가지 알려드릴 말씀이 있습니다. 우리 위원회는 감사가 미진할 경우 오는 20일 위원회 회의실에서 해당 부서를 대상으로 종합감사를 다시 실시할 계획입니다. 모쪼록 다시 감사를 받는 일이 빚어지지 않도록 원장님과 임직원 여러분께서는 감사에 충실히 임해 주실 것을 다시 한 번 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부장, 센터장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기 위해서는 먼저 선서를 하여야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2008년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다.  
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인출석 여부를 확인하겠습니다. 피감기관의 증인들께서는 모두 자리에서 일어나 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (일동기립) 
</p>
<p style="padding-left:1.2em">  원장 나왔습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 부원장 나왔습니까? 
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 기획조정실장 나왔습니까? 
</p>
<p><b>○ 기획조정실장 김동성 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 사무처장 나왔습니까? 
</p>
<p><b>○ 사무처장 엄정수 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 자치행정연구부장 나왔습니까? 
</p>
<p><b>○ 자치행정연구부장 이용환 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 도시ㆍ지역계획연구부장 나왔습니까? 
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이외희 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 교통정책연구부장 나왔습니까? 
</p>
<p><b>○ 교통정책연구부장 지우석 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 환경정책연구부장 나왔습니까? 
</p>
<p><b>○ 환경정책연구부장 이정임 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 산업경제연구부장 나왔습니까? 
</p>
<p><b>○ 산업경제연구부장 김군수 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 사회문화연구부장 나왔습니까? 
</p>
<p><b>○ 사회문화연구부장 김흥식 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 수도권정책센터장 나왔습니까? 
</p>
<p><b>○ 수도권정책센터장 이상대 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 경제동향분석센터장 나왔습니까? 
</p>
<p><b>○ 경제동향분석센터장 조성종 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 팔당물환경센터장 나왔습니까? 
</p>
<p><b>○ 팔당물환경센터장 최용수 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 통일ㆍ동북아연구센터장 나왔습니까? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 의정연구센터장 나왔습니까? 
</p>
<p><b>○ 의정연구센터장 신원득 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 경기과학기술센터소장 나왔습니까? 
</p>
<p><b>○ 경기과학기술센터소장 이원영 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 다음은 선서요령을 설명드리겠습니다. 선서는 전체 증인들을 대표하여 원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손만 들어주시기 바랍니다. 그러면 선서해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은 법 시행령 제39조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 소관 업무에 대한 2008년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법 시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 의해 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 처벌을 받기로 서약하고 이에 선서합니다. 2008년 11월 13일 증인 원장 좌승희. 
</p>
<p><b>○ 위원장 김대원 </b> 앉으시죠. 
</p>
<p style="padding-left:2.4em">    (일동착석)
</p>
<p style="padding-left:1.2em">  그러면 원장님 나오셔서 간부소개와 업무보고를 같이 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 안녕하십니까? 경기개발연구원장 좌승희입니다. 오늘 경기도의회 기획위원회 행정사무감사 수감에 앞서 존경하는 김대원 위원장님과 위원님 여러분을 모시고 우리 연구원의 주요 업무보고를 드리게 된 데 대해 감사의 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  우리 연구원은 경기도정을 선도하는 싱크탱크로서 경기도와 나아가 대한민국의 발전을 견인하고 도민의 삶의 질 향상을 위한 정책개발에 임직원 모두 노력하고 있습니다. 우리 연구원은 금년 남은 기간과 내년도에도 이와 같은 목표를 차질 없이 추진해 나갈 계획이오니 기획위원회 위원님들의 많은 도움과 성원을 부탁드립니다. 그러면 보고에 앞서 우리 연구원의 간부를 소개해 드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 조응래 부원장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동성 기획조정실장입니다. 통일ㆍ동북아연구센터장을 겸직하고 있습니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  엄정수 사무처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이용환 자치행정연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이외희 도시ㆍ지역계획연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  지우석 교통정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이정임 환경정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김군수 산업경제연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김흥식 사회문화연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상대 수도권정책센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  조성종 경제동향분석센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  최용수 팔당물환경센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  신원득 의정연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이원영 경기과학기술센터소장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 지금부터 우리 연구원의 주요업무를 보고드리도록 하겠습니다. 배부해 드린 유인물의 목차를 봐주시기 바랍니다. 보고드릴 순서는 일반 및 재정운영 현황, 2008년도 연구사업 목표 및 추진체계, 2008년도 주요 연구사업실적 그리고 2009년도 연구사업계획, 마지막으로 부설 경기과학기술센터 업무를 보고하겠습니다. 연구사업 목표와 주요 연구사업실적을 중심으로 간략히 보고드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 다음 페이지 일반 및 재정운영현황입니다. 일반현황과 재정운영현황 순으로 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  일반현황에 대해 보고드리겠습니다. 3쪽입니다. 우리 연구원은 1995년에 개원하여 현재 1실 1처 6부 5센터 2과 7팀 부설 1센터의 큰 조직으로 성장했습니다. 옆의 내용을 좀 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음 쪽은 인력현황에 대한 보고입니다. 현재 인력은 원장 1명, 부원장 1명, 연구직 50명, 관리직 등 정규직 73명과 비정규직 95명으로 총 168명이 근무를 하고 있습니다. 연구직의 부족한 인력은 분야별로 보강해 나갈 계획으로 있습니다.  
</p>
<p style="padding-left:1.2em">  다음 쪽 재정운영현황에 대해 보고드리겠습니다. 올해의 총 재정규모는 661억 3,300만 원이며, 여기에는 일반회계, 수탁용역사업특별회계, 경기과학기술센터 사업비가 포함되어 있습니다.
</p>
<p style="padding-left:1.2em">  일반회계 수입ㆍ지출 내역을 구체적으로 살펴보면 수입 총액은 168억 6,000만 원이고 수입항목은 경기도 출연금이 65%인 110억 3,100만 원, 기금이자수입 등이 10%인 16억 9,800만 원, 사업수입이 7%인 11억 8,400만 원, 전기이월금이 18%인 29억 4,700만 원입니다. 지출항목으로는 연구사업비가 전체의 48%인 81억 1,700만 원, 인건비가 38%인 63억 2,000만 원, 부서운영비가 7%인 12억 1,800만 원, 청사관리비가 6%인 10억 5,500만 원, 예비비가 1%인 1억 5,000만 원입니다. 수탁용역사업특별회계의 수입은 44억 1,800만 원이며 지출항목은 인건비가 21%인 9억 4,100만 원, 직접경비가 64%인 28억 400만 원, 전출금이 15%인 6억 7,300만 원입니다.
</p>
<p style="padding-left:1.2em">  다음 6쪽이 되겠습니다. 경기과학기술센터의 수입ㆍ지출 내역은 유인물 29쪽에서 보고드리겠습니다. 연구원의 기금은 총 272억 원입니다. 출연기관별로는 경기도가 54%인 147억 원, 시군이 15%인 39억 6,100만 원, 민간부분이 7%인 20억 원, 자체적립이 24%인 65억 3,900만 원에 해당합니다. 예산이 효율적으로 운용될 수 있도록 최선을 다하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 2008년도 연구사업 목표 및 추진체계에 대해 보고드리겠습니다. 유인물 9쪽부터 11쪽이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 9쪽 연구사업 목표입니다. 2008년도 사업목표 및 사업추진방향을 보시면 우리 연구원은 첫째로 글로벌 스탠더드에 맞는 규제개선을 위한 수도권 규제개혁 정책 및 전략개발을 위해 노력해 왔으며, 둘째로 경기도 서해안ㆍ북부권ㆍ동부권 3대 신발전 전략을 수립 지원했으며, 셋째로 국가적 이슈의 발굴 및 제시, 도민의 삶의 질 향상을 위한 정책연구를 수행하고 있습니다. 
</p>
<p style="padding-left:1.2em">  또한 의정연구센터를 중심으로 경기도 의정발전을 위한 정책개발 및 입법지원연구를 수행하고 있습니다. 이러한 연구사업을 지원하기 위하여 국내외 연구기관 간 연구교류의 강화, 연구평가심의회를 통한 연구의 질 제고를 위한 노력, 온ㆍ오프라인 연구홍보시스템을 개선해서 연구결과를 대외에 알리기 위해 노력했습니다. 그리고 각종 세미나 및 정책포럼을 활성화해 왔습니다.
</p>
<p style="padding-left:1.2em">  다음 10쪽은 연구사업 추진체계에 대해서 보고드리겠습니다. 우리 연구원의 연구사업 목표를 달성하기 위한 연구사업 추진체계는 연구과제사업을 중심으로 해서 연구부대사업, 연구지원사업, 연구기반사업의 4대 사업으로 구분되고 있습니다. 연구과제사업은 연구원의 중심사업으로 연구과제의 특성에 따라 기본연구과제, 정책연구과제, 위탁연구과제, 지역연구과제, 협약연구과제 그리고 수탁연구과제로 구성됩니다.
</p>
<p style="padding-left:1.2em">  연구부대사업은 도정 및 대외연구협력을 위한 사업이며, 연구지원사업은 연구수행지원 및 시군 협력을 위한 사업입니다. 마지막으로 연구기반사업은 연구원의 운영과 홍보를 위한 사업입니다. 
</p>
<p style="padding-left:1.2em">  다음 쪽입니다. 우리 연구원의 4대 사업별 사업계획 대비 추진실적을 보고드리겠습니다. 2008년도 연구과제사업은 신규과제 151개 과제와 전년도 이월과제 72개 과제를 포함하여 총 223개의 과제 수행을 계획하여 10월 20일 현재 94% 정도 완료되었으며 계속 진행 중에 있습니다. 연구부대사업은 82%, 연구지원사업은 62% 그리고 연구기반사업은 86% 진행 중에 있습니다. 각 단위사업별 구체적인 추진실적은 보고서의 부록을 참고해 주시기 바랍니다. 연말까지 모든 사업 분야에서 계획 대비 실적을 100% 완료할 수 있도록 최선의 노력을 다하겠습니다.
</p>
<p style="padding-left:1.2em">  그다음은 2008년도 주요 연구사업 실적에 대해 보고드리겠습니다. 보고순서는 첫째 글로벌 스탠더드 규제개선 연구, 서해안ㆍ북부권ㆍ동부권 3대 신발전 전략, 국가적 이슈의 발굴 및 대안 제시, 도민의 삶의 질 향상을 위한 정책연구, 의정발전을 위한 정책개발 및 입법지원 순으로 보고 올리겠습니다.
</p>
<p style="padding-left:1.2em">  유인물 15쪽에서부터 20쪽이 되겠습니다. 먼저 15쪽 글로벌 스탠더드 규제개선과 관련된 연구사업 실적에 대해 보고드리겠습니다. 올 한 해는 수도권 규제, 군사시설 규제, 상수원 규제, 토지 규제 등 경기도의 경쟁력을 약화시키는 각종 규제를 개선하기 위해 많은 노력을 기울였고 어느 정도 가시적인 성과를 이루지 않았나 생각해 봅니다. 지금도 국회와 전국 시도 간에는 수도권 규제완화와 관련하여 많은 논쟁이 진행되고 있습니다만 우리 연구원에서는 객관적인 사실에 근거하여 수도권 규제개선 정책이 추진될 수 있도록 수도권 규제백서 등 각종의 다양한 분석자료를 냄으로써 중앙정부의 정책을 바꾸기 위해서 노력을 해왔습니다. 
</p>
<p style="padding-left:1.2em">  다음 16쪽 서해안ㆍ북부권ㆍ동부권 3대 신발전 전략과 관련된 연구사업 실적을 보고드리겠습니다. 경기도의 다른 지역에 비해 낙후되어 있는 북부권과 동부권의 발전전략을 마련하기 위해 경기북부 신종합발전 구상, 주한미군기지 이전 동두천지역 지원방안 연구 등을 수행하고 있습니다. 또한 서해안지역 발전방안 마련을 위해 환황해경제권의 거점화 전략과 경기도의 대응방안 연구 등 여러 가지 연구를 해왔습니다.
</p>
<p style="padding-left:1.2em">  다음으로 국가적 이슈의 발굴 및 대안 제시와 관련된 연구사업 실적에 대해서 보고드리겠습니다. 국가적 이슈의 발굴 및 대안제시를 위하여 지방자치단체의 기후변화 적응에 관한 연구, 한반도 평화체제 논의와 구축방향 연구뿐만 아니라 최근 이슈가 되고 있는 행정구역 개편의 평가와 대안 제시에 관한 연구 등을 수행했고 연구하고 있습니다.  
</p>
<p style="padding-left:1.2em">  다음 18쪽 도민의 삶의 질 향상을 위한 정책연구 실적에 대해 보고드리겠습니다. 도민의 삶의 질 향상과 관련된 연구는 우리 연구원 본연의 업무라 할 수 있겠습니다. 이를 위해 올해는 보행환경 만족도 연구, 인구추계 시나리오에 따른 복지정책 대응방안 연구, 광역 주민기피시설 입지갈등 해소 및 주민지원방안 연구 등을 수행하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 20쪽 의정발전을 위한 정책개발 및 입법지원과 관련된 연구사업 실적에 대해 보고드리겠습니다. 올해는 의정연구센터가 운영이 된 첫해입니다. 의정연구센터를 중심으로 지방의회 법령구조 연구, 지방의회의 의원신분에 관한 연구 등을 수행하였고, 경기도의회의 정책보좌기능 제고방안 연구는 외부기관에 위탁하여 추진할 예정입니다. 의정연구센터는 생긴 지가 얼마 안 돼서 아직도 걸음마 단계에 있습니다마는 위원님들께서 많은 관심을 갖고 계신 것으로 알고 있습니다. 내년도에는 보다 더 다양한 연구가 이루어질 수 있도록 노력하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 2009년도 연구사업계획에 대해서 보고드리겠습니다. 유인물 23쪽부터 26쪽이 되겠습니다. 우선 23쪽에 2009년도 연구사업 목표 및 연구사업 분야별 과제에 대해 보고 올리겠습니다. 우리 연구원의 비전인 대한민국을 움직이는 중심 브레인 GRI와 연구원이 지향하는 기관목표인 경기도정을 선도하는 종합연구기관, 대한민국의 미래를 여는 중추적 연구기관, 동북아와 국제사회와 함께하는 세계적 연구기관으로의 역할을 다하기 위해서 2009년도 연구사업 목표를 글로벌 이슈에 대응한 정책연구 선도, 둘째로 수도권의 경쟁력 강화를 위한 기반연구 수행, 셋째 민선4기 경기도정 4대 분야 24개 중점과제의 지원으로 설정하였습니다. 그리고 이와 같은 연구사업 목표를 달성하기 위하여 우리 연구원의 10대 분야 26개 과제를 선정하여 이를 중심으로 연구과제사업을 추진할 계획입니다. 10대 분야 26개 과제에는 지방행정분야의 광역행정체계 개편, 환경정책분야의 저탄소사회 형성, 신재생에너지, 산업경제분야의 미래성장동력산업, 사회문화분야의 저출산 고령화 사회, 수도권정책분야의 수도권 규제개혁의 구체화, 의정분야의 의정발전정책연구 등이 포함되어 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 24쪽 2009년도 연구사업 총괄에 대해서 보고 올리겠습니다. 2009년도 연구사업도 2008년도와 동일하게 4대 단위사업으로 구분하여 추진하겠습니다. 특히 연구과제사업에 포함된 158개 과제는 앞쪽에서 제시한 연구사업 목표와 분야별 과제를 중심으로 내년도 대외여건의 변화를 반영하면서 추진해 나갈 예정입니다.
</p>
<p style="padding-left:1.2em">  다음 2009년도 연구사업 10대 분야 26개 과제별로 계획된 기본과제와 정책과제 목록은 부록자료로 대신하겠습니다. 양해해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 우리 연구원의 부설 경기과학기술센터에 대한 업무를 보고하겠습니다. 유인물 29쪽부터 31쪽이 되겠습니다. 먼저 29쪽 경기과학기술센터의 일반현황에 대해 보고드리겠습니다. 경기과학기술센터는 경기도 기술개발사업의 효율적 수행과 성과를 관리하고 정책연구와 사업관리의 통합추진으로 경기도 과학기술 정책의 시너지효과 창출을 목적으로 지난 8월 29일 개소하였습니다. 경기과학기술센터의 인력은 소장 1명, 2급에서 3급 2명, 5급 5명으로 총 8명이 근무를 하고 있습니다. 부족한 인력은 추후 보강해 나갈 계획으로 있습니다.  
</p>
<p style="padding-left:1.2em">  경기과학기술센터의 총예산은 176억 5,500만 원이며 지출항목은 사업비가 97%인 170억 4,500만 원, 일반운영비가 3%인 6억 1,000만 원으로 책정됐습니다. 
</p>
<p style="padding-left:1.2em">  다음은 30쪽에 2008년도 경기과학기술센터의 사업분야 및 실적에 대해 보고드리겠습니다. 경기과학기술센터의 사업분야는 크게 경기도 기술개발사업과 과학기술정책 연구 및 진흥사업으로 구분할 수 있습니다. 경기도 기술개발사업은 경기도 전략산업의 경쟁력 강화를 위하여 수요조사 및 사전기획에 의하여 기술개발과제를 발굴 지원하는 사업입니다. 2008년도 사업계획서 공모결과 전략산업 과제 81개 등 총 223개 과제가 제안되었으며 엄정한 심사를 거쳐 11월 중에 선정과제를 확정하고 통보 예정으로 추진 중에 있습니다.
</p>
<p style="padding-left:1.2em">  과학기술정책 연구 및 진흥사업은 과학기술정책연구와 익년도 전략산업 기술개발사업 기획으로 구분되며 2008년도 과학기술정책연구는 4건을 완료 및 수행 중에 있습니다. 익년도 전략산업 기술개발사업으로 4대 분야 12개 전략산업 선정을 완료하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 2009년도 경기과학기술센터 사업목표와 추진계획에 대해 보고드리겠습니다. 2009년도 경기과학기술센터 사업목표는 경기도 전략산업의 혁신역량 및 기술경쟁력 강화, 개발기술의 사업화 촉진으로 개발효과 극대화, 산학연 기술혁신 네트워크 구축으로 설정하였습니다.
</p>
<p style="padding-left:1.2em">  2009년도 경기과학기술센터 사업추진계획은 허락해 주신다면 자료로 대신했으면 좋겠습니다.
</p>
<p style="padding-left:1.2em">  다음 부록 2008년도 단위연구사업 실적도 자료로 대신하겠습니다.
</p>
<p style="padding-left:1.2em">  이상으로 주요 업무보고를 마치도록 하겠습니다. 위원 여러분, 경청해 주셔서 대단히 감사합니다.
</p>
<p>업무보고서(경기개발연구원)
</p>
<p><b>○ 위원장 김대원 </b> 원장님 수고하셨습니다. 자리에 앉으시죠. 다음은 감사를 위한 질의 답변 순서가 되겠습니다. 감사의 효율적인 진행을 위하여 질의는 일문일답으로 하되 질의시간을 제한하도록 하겠습니다. 우선 위원님 한 분당 10분씩 시간을 드리고 추가질의는 1회에 한해 5분씩 드리도록 하겠습니다. 그리고 본질의 후에 보충질의를 해주시기 바랍니다. 원활한 감사진행을 위해 부득이하게 시간제한을 두게 된 점 널리 양해해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  질의에 앞서 위원장으로서 한 가지 부탁의 말씀을 드리겠습니다. 위원님들의 질의에 대하여 원장이 답변이 어려울 경우 업무담당 부장 및 센터장 등 실무자가 답변해도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후 발언대로 나와서 소속과 직, 성명을 분명히 밝히고 답변해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그럼 질의해 주실 위원은 거수로 질의신청 해주시기 바랍니다. 임우영 위원 질의해 주시기 바랍니다. 
</p>
<p><b>○ 임우영 위원 </b> 파주 출신 임우영 위원입니다. 감사준비 하시느라고 수고들 많으셨습니다. 제가 주어진 시간이 10분이기 때문에 그냥 문제 지적, 또 아니면 제기 차원에서 한 두어 가지만 말씀을 드리고 추가적인 거는 오후에 추가질의를 하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 확인 좀 해보겠습니다. 여러분들이 주신 기금관리 예치기관별 저축 있지 않습니까? 액수는 맞습니다. 액수가 틀린 건 아닌데 예치기간이 잘못 표시가 돼 있는 게 있어서 어느 게, 농협에 15억인가요? 15억이 들어가 있는데 운영기간을 보니까 감사기간 중에 주신 자료에 보면 2007년도 11월 15일부터, 이게 몇 년입니까? 7년간입니까? 이렇게 표시가 이상하게 되어 있는데요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 2013년으로 되어 있지요?
</p>
<p><b>○ 임우영 위원 </b> 네. 그런데 여러분들이 의회에 보고한 주요 업무보고서에 보면, 9월5일 날 도의회에서 있었던 거기에 보면 이것이 2007년도 10월 15일부터 2008년도 10월 15일까지 1년짜리로 들어가 있었단 말이죠. 그런데 어느 게, 이거는 사실만 확인을 하겠습니다. 어느 게 맞는 겁니까? 
</p>
<p style="padding-left:2.4em">    (「감사자료에 있는 게 맞습니다.」하는 관계직원 있음)
</p>
<p style="padding-left:1.2em">  그러면 지난번 저희들 업무보고 한 게 잘못됐다 이런 말씀이죠? 
</p>
<p style="padding-left:2.4em">    (「네.」하는 관계직원 있음)
</p>
<p style="padding-left:1.2em">  왜냐하면 제가 질의한 요지는 9월 5일 날 준 거에는 2008년 10월 15일 날이 만기로 되어 있는데 여기 감사자료에 보면 2007년도 11월 15일 날 시작을 해서 2013년이 만기로 되어 있어요. 그래서 시작한 것도 그렇지만, 예를 들어서 2008년 10월 15일까지 1년짜리인데 중도에 해지를 하고 했다는 얘기인지, 중도에 해지했다면 이율의 차이는 어떤 건지 이런 걸 제가 확인하려고 한 건데 오기라면 알겠습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 오기라도 그냥 오기일 수는 없지요. 
</p>
<p><b>○ 임우영 위원 </b> 확인을 좀 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 담당자에게 확인 좀 해도 되겠습니까?
</p>
<p><b>○ 임우영 위원 </b> 나중에 쉬는 시간에 저한테 좀 알려주시고.
</p>
<p style="padding-left:2.4em">    (「네.」하는 관계직원 있음)
</p>
<p style="padding-left:1.2em">  제가 자료 요구한 이사회 회의록을 보니까 기금 운용에 있어서 우리 연구원의 기금은 연평균 5.71%의 수익률을 올리는 그런 상품에다가 예치를 하고 있더라고요. 그런데 퇴직기금을 보니까 연평균 4.8%의 수익률을 올리는 곳에 예치를 하고 있어요. 왜 이런 차이가 나는 건지. 퇴직기금도 여러분들 기금 운용에 있어서 수익이 높은 상품에다 해야 되는 거 아닌가. 아니면 이 퇴직기금이 여러분들 이사 중에 한 분의 금융기관에다 해놓다 보니까 그런 건지. 우선 그런 걸 좀 확인을 해보겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리 기금에 비해서 퇴직금이 규모가 많이 적어서 아마 은행하고 협상하는 과정에서 금리가 어느 정도 조정이 가능한 걸로 알고 있습니다. 그래서 퇴직금 규모가 적기 때문에 우리가 협상력이 떨어진 게 아닌가 하는 생각이……. 
</p>
<p><b>○ 임우영 위원 </b> 아니, 그건 말이 안 되죠. 아니, 퇴직금의 조성금액이 11억 2,226만 5,000원 이렇게 돼 있어요. 2006년도에는 2억 얼마가 조성이 돼 가지고 총 조성금액이 2007년도 2008년도 들어가기 전에 한 보고에, 여러분들 이사회에 보고한 겁니다, 이게. 11억 2,226만 5,000원. 그런데 이게 4.8%란 말이죠.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 임우영 위원 </b> 이게 하나의 상품에 가입이 돼 있습니까, 아니면 이것도 분산돼 있습니까? 분리해서 돼 있죠? 
</p>
