<p style="padding-left:1.2em">  분리돼 있다 하더라도 10억 미만의 여러분들 기금 운용하는 거 보면 연구원 기금 같은 경우는, 물론 그 뒤에 맺어진 계약이겠지만 여기는 9억짜리도 6.7%의 높은 수익률로 계약을 했단 말이죠. 그러니까 기금이 적어서 했단 얘기는 얘기가 안 된다 이런 얘기예요. 이건 해마다 갱신이 되는 겁니까, 어떻습니까? 
