<p><b>○ 임우영 위원 </b> 제가 왜 이런 말씀을 드리냐면 지난해에도 아마 박사님들이 내놓은 연구물을 갖고 이야기가 한참 있었습니다, 평택항과 관련돼서. 또 금년에도 보면 자동차 홀짝수 운행과 관련된 정책과제를 발표를 했더니 그것도 또 얘기가 많았고 또 최근에는 팔당상수원 이전문제와 관련돼서 기자회견까지 받는 그런 경우가 종종 있었습니다. 그렇죠? 
