</p>
<p><b>○ 임우영 위원 </b> 그래서 제가 생각했을 때는 연구원들이 연구활동을 하는 데 있어서 본연의, 진짜 학문에 전념해서 객관성을 갖고 연구를 하고 그 연구결과를 내놓은 것에 대해서 이렇게 이의제기를 하고 외부에서 자꾸만 연구결과를 갖다가 왜곡하려고 하고 하는 부분에 있어서, 여러분들이 기본적으로 가지고 있어야 될 기준은 있어야 되지 않겠느냐. 연구원들이 연구하는 데 있어서 기본적인 기준을 한번 만들어 보는 건 어떠냐 하는 그런 차원에서 제가 문제지적을 하는 겁니다. 
