<p><b>○ 경기개발연구원장 좌승희 </b> 좋은 말씀입니다. 저희가 한번 윤리규정을 보고요. 말씀하신 대로 연구 쪽에 좀 더 보강을 해야 될 부분이 있으면 한번 보완을 하도록 하겠습니다. 그리고 아까 말씀하신 몇 개 사안에 대해서 제가 조금 해명을 할 수 있을까 하는 생각이 드는데요.
