<p><b>○ 임우영 위원 </b> 네, 말씀하세요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우선 팔당상수원 문제와 관련해서는 두 가지 문제가 있었습니다. 제가 2006년에 오자마자 바로 지시해서 한 사업 중에 하나가 그동안 팔당물을 가지고 오랜 세월 동안 여러 가지 정책을 썼지만 별로 물도 깨끗해지지 않고 주변의 주민들은 다 어렵다고 그러니 뭔가 패러다임이 잘못된 게 아니냐. 그래서 제가 아주 객관적으로 외부학자들까지 동원해서 정말, 원장도 일체 얘기 안 할테니 한번 해봐라 그래서 나온 게 팔당정책에 대한 새 패러다임 연구인데. 거기에 우리 연구원 박사가 두 사람이 썼는데 하나는 경제학을 한 사람으로서 환경을 한 유영성 박사가 있었고 또 한 사람은 공학을 한, 수리수문을 공부한 백경오 박사, 두 사람이 페이퍼를 썼어요. 그런데 이 두 사람이 보는 관점이 좀 다른 것이죠. 그런데 저는 이걸 어떻게 이해하느냐 하면 공학을 공부한 사람은 물의 절대 공급량이 최악의 경우에 얼마나 되느냐 하는 게 가장 중요한 것이겠죠. 그런데 사회학을 공부하는 사람은 물이라는 게 물값에 따라서 수위도 달라질 수가 있고 다른 대체물이 나오면 수위도 달라질 수 있고. 그러니까 경제환경에 따라서, 수요공급의 변화에 따라서 꼭 필요한 물의 양이 고정적이지 않다 하는 생각을 늘 갖는 것입니다. 그래서 그런 관점에서 하다 보니까 유영성 박사가 한 것은 물의 양이 모자라지 않다 하는 결론에 이른 것이고 백 박사는 아까 얘기한 대로 최악의 경우에 절대수량이 어떠냐 이걸 판단하다 보니까 모자랄 수 있다 하는 결론이 나와서, 저도 개인적으로 이걸 어떻게, 내가 어느 게 옳다고 얘기하기는 참 어렵습니다. 그래서 NGO한테도 그 사실을 잘 알리고, 이건 학문을 하는 사람들의 기본적인 패러다임에 차이가 있기 때문에 내가 어떻게 조정하기도 어렵고 이건 정책판단을 나중에 도지사 차원에서라든가 국가 차원에서 좀 더 고민을 해야 될 문제가 아닌가 하는 의견을 드렸고. 
</p>
<p style="padding-left:1.2em">  또 하나 문제는, 2006년인가요? 과거에 저희가 비공개로 상수원 이전과 관련된 BC분석을 한 게 있었습니다. 그런데 그 분석이 그때는 BC가 낮다 그래서 이전하는 게 문제가 있다 하는 지적을 내부적으로 보고서가 나와서, 그게 사실은 공개는 안 된 걸로 알고 있습니다, 그 연구보고서가. 그런데 이번에 또 유영성 박사가 한 같은 연구에서 나온 얘기는 BC분석을 했더니 타당성이 있다 이렇게 분석이 나왔어요. 그래서 그거 가지고 논쟁이 있는데, 물론 같은 사람이 했습니다. 그래서 제가 검토를 해봤더니 2006년에 할 때는 상수원 규제를 풀면 땅값이 올라가는데 땅값이 올라가는 부분에 대해서 두 가지 부분으로 나눴던 것 같아요. 하나는 자연스럽게 올라가는 부분이 있겠지만…….
</p>
