<p><b>○ 경기개발연구원장 좌승희 </b> 금년 초를 기준으로 보면 보수 수준이 거의 시정개발연구원하고 비슷한 수준으로 간 걸로 제가 확인을 하고 있습니다. 그래서 개선이 됐고요. 그런데 저희가 사람 뽑는데 그냥 막 뽑을 수는 없어서 여러 가지 엄격한 기준을 가지고 뽑습니다마는, 그런대로 저희가 노력을 했는데 반드시 반대로 두 사람, 세 사람 꼭 떠나는 사람이 이렇게 자꾸 생깁니다. 그러니까 충원하면 또 결원이 생기고 이렇게 하면서 숫자가 별로 변화가 안 돼서 위원님들 보기에 너무 인력충원에 소원한 게 아니냐 하는 지적을 듣고 있습니다마는……. 
