</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저 나름대로 판단하기에, 저는 연구원 생활을 계속 한 사람이기 때문에 역시 학교로 가는 게, 보수가 좀 떨어지고 그래도 아직은 여러 가지 면에서 자유롭고 좋다고 생각을 하는 것 같습니다. 그리고 죄송한 말씀……. 학교의 랭킹이나 이런 것에 관계없이 기회가 있으면 그렇게 하는 그런 경향이 있는데 이건 전반적으로 대한민국의 연구산업의 현황, 환경하고 관련이 돼 있지 않을까 하는 생각이 들고 KDI나 다른 데도 마찬가지로 여전히 학교로 가는 사람이 계속 있기 때문에 우리와 비슷한 추세가 있는 게 아닌가 그렇게 생각을 해봅니다.  
</p>
<p><b>○ 임우영 위원 </b> 알겠습니다. 시간이 10분이기 때문에 길게 여쭤보지도 못하겠는데 하여튼 훌륭하신 분들이 오셔서 경기도 발전을 위해서, 또 어떻게 보면 경기도뿐만이 아니고 나아가서는 국가의 발전을 위해서 여러분들이 열심히 노력하는 만큼의 효과가 있지 않을까 하는 생각을 해봅니다. 하여튼 원장님을 중심으로 연구원에서 보다 심혈을 기울여서 좋은 연구물들도 내시고 정책도 개발해서 경기도의 발전을 이끌어 주십사 하는 부탁의 말씀을 드리면서 질의를 마치겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 격려의 말씀 감사합니다. 명심하겠습니다. 
