<p><b>○ 고영인 위원 </b> 그 내용은 알겠는데 문제는 본인이 이것을 새로 한다고 했을 때는 6년 전의 결과에 대해서 당시에 근거가 무엇이고 그 근거가 어떤 상황과 환경이 변했기 때문에 이런 결과가 나올 수 있다라고 하는 그걸 제시해야 돼요. 6년 전의 결과에 대한 정확한 그런 것들이 돼야 되는데 지금 이번에 나온 결과 자체는 어떻게 보면 그냥 손바닥 뒤집듯이 뒤집은 거란 말이죠. 이게 어쨌든 도지사께서 대운하 언급도 있었지만 상수원 이전의 필요성이 있다라고 언론에도 말씀하신 이후의 결과라고 하는 데 굉장히 문제가 있는 거죠. 
