<p><b>○ 고영인 위원 </b> 어떻게 그렇게……. 0.5라고 하는 건 굉장한 차이인데, 서울시정개발연구원이라든가 타 기관에서 나온 거하고 어떻게 그렇게 차이가 날 수 있죠? 
