<p style="padding-left:2.4em">    (좌승희 경기개발연구원장, 관계직원에게 확인 중) 
</p>
<p style="padding-left:1.2em">  아까 말씀드린 대로 제 개인적인 생각은 이렇게 해봅니다. 2002년에 이걸 개선할 때 말이죠, 이건 제 개인적인 추측입니다마는 그 당시의 사회 분위기라든가 부동산 투기라든가 이런 것에 대한 상당한 압박이 있었거나 이랬다면 혹시 연구하는 사람이 이런 걸 수익부문에, 이익부문에 넣는 게 좀 그렇지 않겠느냐 하는 판단을 했을 수도 있겠다 하는, 진짜로 제 개인적인 추측인데요. 그런 생각도 들긴 드는데 어쨌든 이 사람이 처음에 할 때는……. 
</p>
<p><b>○ 고영인 위원 </b> 시간이 없으니까 일단 제가 마무리하고 오후에 추가질의 하겠습니다. 문제는 동일인의 문제하고, 저도 일정 정도 도지사나 도정의 정책방향과 연구원이 완전히 무관하게 할 수는 없다는, 현실적인 고려 이런 건 하는데 문제는 내부에 여러 가지 이견이 있다든가 이런 것이 있을 때 시스템적으로 한 연구원의 결과가 연구원 전체의 결과처럼 비쳐지고, 내부에는 과연 다른 시각은 없는지 이런 것들이 의문이 든단 말이죠. 그래서 연구평가심의회 기능이 있긴 한데 보니까 작년에는 제대로 안 됐던 것 같고 올해부터 그거를 활성화시키고 있다고 하는데 그런 것들을 운영을 하면서 실제 평가를 통해서 내부의, 동일 센터 내의 다른 의견들 또는 심의 과정의 의견을 보고서에 반영해서, 도의원들이 이걸 참조한다든가 집행부에서 참조할 때, 다들 어린 아이들이 아니니까 다른 이견이 있다 하더라도 그런 것들을 참조해서 이거에 대한 객관적 타당성을 볼 수 있다 이 말이죠, 우리가. 그런 것들을 반영할 수 있는 게 불가능한가요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아닙니다. 지적하신 대로 저희가 그런 방향으로 제도를 정착해야 되지 않을까 하는 저 개인적인 반성도 있습니다. 사실은 이걸 그냥 내놓는 것이, 어떻게 보면 학자들 입장은 그냥 반영했다 하지만 혼란을 가져올 가능성도 지적하신 대로 충분히 있기 때문에 향후에는 그런 경우에 연구책임자가 중심이 돼서 외부 전문가들을 모으거나 이래서 서로 토론을 통해 가지고 뭔가 정리를 하고……. 
</p>
<p><b>○ 고영인 위원 </b> 네. 그러니까 차라리 헌법재판소에 소수의견이 있듯이 좀 예민한 사항일 때는 두 가지 의견이든 세 가지 의견들을 이렇게 해서, 결론은 이렇게 냈지만 이런 이견들이 존재하고 어떤 측면 때문에 그렇다. 이렇게 해서 우리가 그것을 객관화시킬 수 있는 근거들을 제시해 주는 게 오히려 정책반영에 더 유리하지 않겠냐 이런 주문을 해봅니다. 그러니까 거기에 대한 안을 내부적으로 토론해서 나중에 답변 주시기 바랍니다. 이상입니다. 
