<p><b>○ 정문식 위원 </b> 고양 출신 정문식 위원입니다. 존경하는 고영인 간사께서 질의하신 사항에 대해서 보충질의 드리겠는데요. 지금 우리 경기개발연구원이 앞으로 우리 경기도의 비전과 정책을 결정하는 데 아주 중요한 역할을 하고 있다 생각합니다. 우리 원장님께서 답변하신 사항은 아주 민감한 사항이고 중요한 사항인데요. 지금 보시면 6년 전의 연구하고 지금하고 사정변경의 절차가 있었다면 그만한 변화의 결과들이 당연히 나와야 되는 거지요. 그전과 지금과, 지금 답변상으로 보시면 기준점이나 지금 평가하는 잣대를 달리 적용하셨다는 얘기잖아요, 요지가요. 저는 사실 우리 경기개발연구원이 학문적 소신도 중요하다고 제가 언제나 강조하고 있고 또 우리 경기개발연구원의 목적상 실용적 학문도 하셔야 되는데 지금 답변상으로는 이게 사정변경에 의한 연구결과의 변경인지 안 그러면 정말 정책적 판단을 하셨는지에 대한 답변이 좀 애매모호하세요. 이 부분을 좀 정확히 해주셔야 될 것 같고요.
</p>
<p style="padding-left:1.2em">  그다음에 우리가 지금 보면 이 연구과제하시면서 중간에 연심회 많이 하셨죠? 우리 경기개발연구원 내부 분들 의견만 들어가 있는 게 아니지 않습니까, 이 부분이?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 외부 집필진이 많이 참여를 했습니다. 
</p>
<p><b>○ 정문식 위원 </b> 네, 많이 참여하셨고 중간에 연심회에서 의견들 내신 것들을 충분히 수용해 가지고 이 결과가 지금 발표된 것 아닙니까? 그러니까 오후 감사 중에 이 연구에 참여하셨던 당사자도 좀 나오시고요. 그다음에 보다 명확하게, 왜 이 수익성부분에서 변경이 있었는지에 대해서 간략하고 명확한 설명을 해주시기를 당부드리겠습니다. 가능하시겠지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우선 우리 유영성 박사는 지금 해외 사바티컬(sabbatical)을 나가 있어서, 그런 사정이고요. 우리 백 박사, 물이 모자라다고 주장한 사람은 오후에 불러서 얘기를 들어볼 수 있습니다. 그리고 지금 말씀하신……. 
</p>
<p><b>○ 정문식 위원 </b> 지금 만약에 당사자가 안 계시더라도 제가 지금 가장 원장님께 듣고 싶은 답변은 우리가 정말 2002년과 이번에, 6년 사이에 이루어진 연구에 있어서의 사정변경 사항이 있으면 당연히 변경되는 것 아닙니까? 그렇죠?
