<p><b>○ 정문식 위원 </b> 그다음에 이 평가하는 기준이 달라졌다 그러면 결과는 또 달라질 수 있는 거고요. 그다음에 서울시정개발연구원과 우리 경기개발연구원의 기준이 달랐다면 결과는 당연히 달라야 되는 것 아닙니까? 같은 기준이 아니면. 그런데 지금 답변상으로는 좀 애매모호하신 게 있어요.
