<p><b>○ 정문식 위원 </b> 네, 대충은 말씀하셨는데 오후에 그것을 보다 간략하고 정확하게, 2002년도에 기준이 이런 데 중점을 두고 했고 이번 평가에서는 이렇게 했기 때문에 수익성이 변했다는 설명이 없으시면 여러 도민들한테도 오해의 소지가 있는 것 같습니다, 조금 전의 답변 갖고서는. 제가 아직 이해를 잘 못하는지 모르겠지만…….
