<p><b>○ 경기개발연구원장 좌승희 </b> 기준을 바꾼 거는 제가 분명히 말씀을 올렸고요. 왜 기준이 바뀌었느냐 하는 것에 대해서는 제가 추측 말씀을 드렸지만, 사실 그건 제가…….
