<p><b>○ 경기개발연구원장 좌승희 </b> 기준이 바뀐 건 분명합니다마는 그런데 여기 또 하나 위원님들이 좀 생각을 해주실 것이 경제를 분석한다는 게 제가 좀 과도하게 표현하면 연구하는 사람의 의지에 따라서 다른 결과가 많이 나올 수 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그렇죠. 원장님 말씀처럼 연구원의 의지도 다를 수가 있고요. 그다음에 참여하시는 분들이 어느 분야의 전문가냐에 따라서도 서로 중점을 두는 부분이 달라지지 않습니까? 그런 부분들에 있어서 2002년도와 2008년도에 참여자 분들이 다르면서 또 거기에 우리 자료들이 남아 있잖아요. 저번과 이번에 변한 이유가 어떠어떠한 이유 때문에 변했다라고, 제가 지금 기억은 못하지만 그것들에 대해서 명확한 답변이 좀 필요하실 것 같습니다. 오후에 그 답변을 준비해 주시고요. 
