<p><b>○ 경기개발연구원장 좌승희 </b> 저는 그냥 이렇습니다. 우선 제가 연구결과에 대해서 전혀 어느 방향으로 얘기한 적이 없고, 더구나 같은 보고서에 같은 연구원의 두 사람이 서로 다른 견해를 낼 수 있다는 것, 이것도 위원님들이 좀 평가를 해주셔야 되지 않을까 싶습니다. 예를 들면 어떤 방향을 정해 놓고 지사나 도정의 방향이다, 이렇게 해서 하지 않았다는 것이 사실은 여실히 나타나는데 단지 문제가 있었다면 다른 의견을, 말하자면 아까 고영인 위원님 지적하신 대로 좀 이해할 수 있도록 저희가 정리해서 외부에 제공하지 못한 것, 그거는 저희가 불찰이라고 생각합니다. 그래서 앞으로 그런 건 제도적인 장치를 만들어서 보완하겠지만 좌우간 연구의 객관성을 높이기 위해서 노력했다는 점은 조금 그래도 평가를 해주시면 고맙겠다는 말씀을 드리고 싶습니다.
