<p><b>○ 정문식 위원 </b> 지금 최소 3회 이상하고 있지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다. 그런데 이 연구보고서가 중점연구과제로, 이거는 사실은 그동안에 우리 연구원에서 하던 그런 연구트랙하고는 다른 방식으로 한 겁니다. 제가 조금 말씀을 드리면 우리 연구원이 지방이슈만 다루고 있고 이러다 보니까 소위 말하자면 중앙정책이 정해놓은 속에서, 벗어나지 못하는 그런 문제가 있다 생각이 돼서 제가 중앙의 정책을 바꿀 수 있는 방법을 우리가 강구해야 되지 않겠느냐? 수도권 규제완화 문제도 똑같은 문제입니다마는. 그래서 제가 와서 문제제기한 게 중앙이슈에 대해서 외부사람을 불러서 좀 자유롭게 이렇게 해가지고 정책대안도 내고 이렇게 하면 어떻겠느냐 하는 그런 아이디어에서 출발해서 이걸 중점연구과제다 그래서 서로 다른 부서가 참여하고 외부인력이 참여해서 이렇게 하다보니까 이게 그동안 했던, 세 번에 걸치는 연심회 과정 이런 거는 아마 일부 생략이 되지 않았을까 하는 생각이 들어서, 그 점에 대해서도 사실 불찰이 아니었나…….
</p>
<p><b>○ 정문식 위원 </b> 저는 지금 원장님께서 큰 틀에서 말씀하신 의미에는 공감을 하고요. 보충질의이기 때문에 여기서 발언을 마무리할 텐데요. 제가 아까 말씀드린 첫 번째 전제가 학자의 소신입니다. 학자의 소신은 당연히 지켜져야 되는 거고요. 대신에 우리 경기개발연구원의 특성상 경기도의 입장에서 정책을 결정하는 데 많은 필요성과 그런 결정을 하는 데 도움을 줄 수 있는 실용적 학문을 하셔야 되는 부분은 분명히 있거든요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 물론입니다.
</p>
<p><b>○ 정문식 위원 </b> 그런데 우리가 실용적 학문을 하고 도정과 도민들의 안녕과 발전을 위해서 연구를 한다 하더라도 학자적 소신을 버리면서 할 수는 없는 거죠. 학자적 소신을 가지고 있는 상태에서 가장 실용적이고 가장 경기도의 입장은 무엇인가를 대변할 수 있는 방안을 찾아내는 게, 그 합의점을 도출해 내는 게 어려움이 있지만 그런 노력들을 하고 계시다고 생각하는 겁니다. 제가 그런 차원에서 오후에 추가로 그 부분을 답변하시기를 요청한 거니까 그런 차원에서 준비해 주시기 바랍니다. 이상 보충질의 마치겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아주 좋으신 말씀입니다.
</p>
<p><b>○ 위원장 김대원 </b> 정문식 위원 수고하셨습니다. 
</p>
<p style="padding-left:2.4em">    (정인영 위원 거수)
</p>
<p style="padding-left:1.2em">  이 건과 관련된 보충질의입니까? 
</p>
<p><b>○ 정인영 위원 </b> 네, 보충질의입니다.
</p>
<p><b>○ 위원장 김대원 </b> 한 분만, 본 건과 관련해서는 오후에 본질의를 하시겠다는 위원들 많으니까 보충질의는 한 분으로 마무리하겠습니다.
</p>
<p><b>○ 정인영 위원 </b> 간단히 하겠습니다. 팔당상수원 이전과 관련한 연구결과 발표에 대해서 많은 분들이 이견이 있을 수 있습니다. 팔당상수원을 이전하는 데 찬성하는 분도 있고 반대하는 분도 있습니다. 또 연구원이 팔당상수원 이전문제를 이전해야 된다라고 주장할 수도 있고 이전해서는 안 된다라고 주장할 수 있는, 각계의 의견이 있을 수 있습니다. 그러나 경기개발연구원의 본래 임무인 연구목적을 가지고, 그 결과물을 가지고, 연구는 연구일 뿐이지 그걸 가지고 경기도정과 연관 지어서 오해하고 또 갑론을박하는 것은 맞지 않다고 생각하고요.
</p>
<p style="padding-left:1.2em">  특히 연구원 당사자가 없는 상태에서 어떤 의도를 가지고, 또 그 당시 상황과 어떻게 상황이 바뀌어서 그런 결과물이 나왔는지를 물어볼 수 있는 그런 상황이 아니기 때문에 이런 문제들은 좀 더 신중하게 다룰 필요가 있다고 생각하고요. 그것은 연구 결과물을 내놓은 연구원만이 답변할 수 있는 문제라고 생각합니다. 그것을 원장님 입장에서 내지는 경기개발연구원 입장에서 평가하고, 물론 평가하고 심의하는 그런 과정이 있을 수 있겠습니다마는 그런 문제들은 좀 더 신중할 필요가 있다라고 하는 차원에서 보충질의를 드리는 겁니다. 여기에 대한 답변 있으십니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 명심하겠습니다. 
</p>
<p><b>○ 정인영 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 김대원 </b> 정인영 위원님 수고하셨습니다. 다음 질의하실 위원님 신청해 주시기 바랍니다. 전동석 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 전동석 위원 </b> 광명 출신 전동석 위원입니다. 
</p>
<p><b>○ 위원장 김대원 </b> 본질의시죠?
</p>
<p><b>○ 전동석 위원 </b> 네. 본질의 들어가기 전에 제가 보충질의를 계속 하려고 했었는데 이건 오후에 본질의를 할 분들이 상당히 많아서 하나만 상기시켜 드리고 본질의에 들어가고자 합니다. 
</p>
<p style="padding-left:1.2em">  우리 좌승희 경기개발연구원 원장님이 어느 언론에서 인터뷰한 걸 보니까 그런 말씀하신 적이 있습니다. 2006년도였는데요. “연구자들이 연구생산물로 자신의 목소리를 내기보다는 연구과제를 발주하는 관료의 방패막이로 전락한 실정이다.” 이게 무슨 얘기냐 하면 국책연구소들이 그런 역할을 하고 있다 하는 얘기를 약간 자탄적인 말로 말씀하신 적이 있습니다. 그러면서 민영화를 주장하시기도 하셨는데요. 이번 연구도 아마 어떻게 생각하면, 존경하는 임우영 위원님께서 오비이락 이런 말씀도 하셨는데 실제로 그 시기가 좀 맞아떨어져 가지고, 연구과제 발굴은 2006년도에 했다고 하지만 시기가 맞아떨어지는 바람에 실제로 지사님 언급한 다음에 어떤 결과물을 내놓은 결과가 되어 버렸어요. 그런 경향이 있었으니까요. 오후에 본질의를 하시는 분들에 대한 답변을 정확히 하셔야 되지 않겠나 그런 생각이 듭니다. 본 위원의 생각이었고요. 본질의를 제가 시간을 정확하게 지켜서 하나 하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  본 위원이 자료 요청한 것 중에서 몇 가지만 하도록 하겠습니다. 행정사무감사 요구자료 1편에 87페이지를 한번 봐주시죠. 87페이지입니다. 87페이지를 보면 2007년 모든 과제에 집행잔액이 발생돼 있습니다. 왼쪽에 보면, 2007년도에요. 집행잔액이 쭉 발생돼 있는데 이게 항상 그런 겁니까? 또 정책연구과제 집행잔액이 발생되지 않고 있습니다. 이거에 대해서 한번 설명해 주시겠습니까? 
</p>
<p style="padding-left:2.4em">    (좌승희 경기개발연구원장, 관계직원에게 확인 중) 
</p>
<p style="padding-left:1.2em">  이미 모든 것이 완료됐는데도 불구하고 집행잔액이 발생돼 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이 집행잔액이 제일 많이 발생하는 쪽이 외부에서 받는 수탁용역과제가 많죠. 그거는 우리 전출금으로 해서 연구원 기금으로 들어오는 부분이 있습니다. 
</p>
<p><b>○ 전동석 위원 </b> 돈을 받지 못하는 경우입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아니, 받아서 우리가 집행을 다 하면 안 되고 연구원에 들어와야죠. 
</p>
<p><b>○ 전동석 위원 </b> 들어와서요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 옛날 영어표현으로 오버헤드라고 그러나요. 뭐 이렇게 떼는 거 있잖아요, 연구원에. 그게…….
</p>
<p><b>○ 전동석 위원 </b> 빼놓습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그래서 연구원 예산으로 다시 들어오는 게 있습니다. 그게 상당한 비중을 차지하고요. 정책연구과제는 전체 예산을 풀로 해가지고 쓰다가, 그러니까 결국은 그걸 다 소진하는 형식으로 가게 되고요. 기본연구과제 같은 거는 하다가 일부 출장을 간 비용이라든가, 처음에 계획했던 것보다 여분이 남는 경우가 없지 않아 있고 어떤 경우에는 박사들이 연구계획서를 사전에 낼 때 대단히 큰 뜻을 가지고 내는데 그걸 집행하는 과정에서 하다 보면 다 집행을 못하는 경우도 사실 전혀 없다고 할 수는 없습니다. 
</p>
<p><b>○ 전동석 위원 </b> 잘 알겠습니다. 그러면 88페이지를 또 봐주시죠. 거기 보면 2007년도 기본연구과제가 25과제가 나와 있습니다. 25과제 중에 천편일률적으로 15%를 집행잔액으로 남겼습니다. 비고란에 보면 그 이유를 책임연구자의 전공분야별 과제가 대부분으로 연구의 직접경비 외에는 예산을 절감했다고 되어 있습니다. 이것도 설명해 주셔야 될 것 같아요. 아까 말씀하신 것도 제가 완전히 이해하지 못했는데. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이 뜻은 연구하는 사람이 연구하는 과정에서 자기가 잘 모르는 분야에 대해서 외부에 용역을 줄 수도 있고 자문을 들을 수도 있고 비상임연구위원을 초빙해서 쓸 수도 있고 이런 여러 가지 가능성이 있는데 그럴 가능성이 상대적으로 낮았다 하는 겁니다. 자기가 잘 아는 분야를 했기 때문에, 그런 말씀이고…….
</p>
<p><b>○ 전동석 위원 </b> 그렇다고…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 15%라는 거는 모든 데가 각각 15%라는 얘기가 아니라 전체 합쳐서 평균적으로 15% 정도 된다는 의미로 해석해 주시면…….
</p>
<p><b>○ 전동석 위원 </b> 그게 아닌데요. 정확하게 아셔야 될 것 같은데요. 아까도 설명하셨는데, 그 돈을 연구과제비로 또 빼놓는다는 설명도 제가 정확하게 모르겠고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아니, 수탁연구과제는 일단 수탁을 받으면 거기에 일정 부분을 연구원의, 소위…….
</p>
<p><b>○ 전동석 위원 </b> 수탁연구과제만 얘기하는 것이 아닙니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그건 그렇습니다. 전출금으로 우리가 사전에 떼어내기 때문에…….
</p>
<p><b>○ 전동석 위원 </b> 그러면 이 15%의 집행잔액을 만약에 예산절감이라고 말씀하시고 15%의 집행잔액이 남았는데, 그러면 이게 완전히 집행될 경우에 누구한테 어떻게 돌아가는 돈입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 누구한테 돌아가는 게 아니라 연구에 참여한 사람들한테 돌아가거나 연구와 관련된 비용으로 쓰이겠죠.
</p>
<p><b>○ 전동석 위원 </b> 그러면 천편일률적으로 15%를 갖다 집행잔액으로 남기라는 어떤 말씀이 계셨기 때문에 이게 이렇게 된 거라고 생각되는데…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이 남은 거는 당연히 불용액으로 해서 내년 예산으로 넘어가는 걸로…….
</p>
<p><b>○ 전동석 위원 </b> 아니, 지급될 걸 지급하지 않았다는 얘기죠. 지급돼야 되는데도 불구하고 천편일률적으로 15%를 남긴 이유가 설명이 되지 않지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아니, 전체가……. 전체로 봤을 때 15%고 과제별로는 비율이 다 다를 겁니다, 제가 생각하기에는요. 전체 예산 총계를 놓고 볼 때 집행잔액으로 남아 있는 게 15% 수준에 이른다는 걸로 이해를 해주셔야 되지 않을까 싶습니다. 
</p>
<p><b>○ 전동석 위원 </b> 본 위원이 처음에 생각하기에는 이거를 예산절감 했다고 할 수 있는 상황인지 그게 의문이 돼서 제가 질의를 드렸고요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 두 가지 차원이 다 있을 수 있습니다. 
</p>
<p><b>○ 전동석 위원 </b> 그렇게 되면 연구의 어떤 가치척도를 나타내는, 어떤 가치를 떨어뜨리는 그런 영향도 있을 수 있지 않습니까? 
</p>
