<p><b>○ 부원장 조응래 </b> 부원장 조응래입니다. 저희가 일반적으로 기본과제 같은 경우는, 기본연구과제는 전년도에 예산액을 설정해 가지고 그거를 박사별로 연구를 수행합니다. 그러다 보면 어떤 박사는 예산에 거의 맞게 쓰는 사람도 있고 또 어떤 박사는 그거보다 못하게 집행을 하는 경우가 있고 그렇기 때문에 지금 자료에서 보시는 바와 같이 1번, 2번, 3번, 4번 이런 것들이 비율로 보면 15%, 15%, 5% 이런 식으로 사람별로 다 집행률이 다릅니다. 그런데 총액적으로 보니까 전체 예산액 대비로 봤을 때 지금 85%를 집행하고 집행잔액이 15%가 남았다는 그런 얘기가 되겠습니다. 
