<p><b>○ 이경천 위원 </b> 이런 많은 노력을 하셨고 또 이런 논리개발도 하셨고 아까 얘기하실 때 객관적 사실이다 이렇게까지 말씀을 하셨습니다. 그런데도 불구하고 우리 수도권이나 저희 위원들은 다 공감하는 부분이긴 하지만 아직도 비수도권이나 중앙정치 일부에서는 여기에 공감하지 않고 어저께도, 오늘인가요? 오늘 신문에 보니까 수도권 규제완화에 대해서 반대운동들을 하고 있는데 이렇게 열심히 노력하셨는데 이러한 결과가 속된 얘기로 잘 먹혀 들어가지 않는 이유가 어디에 있는지 생각해 보신 부분 있으면 말씀해 주십시오. 
