<p><b>○ 경기개발연구원장 좌승희 </b> 우선 먹혀 들어가지 않았다는 말씀에 대해서는 우리가 연구한 결과가 많은 자료가 돼서 청와대 경쟁력강화위원회라든가 정부 쪽에서 수도권 규제완화를 하겠다는 결심을 하고 실제로 행동을 취하는 데 큰 기여를 한 것으로 알고 있습니다. 제가 듣기로는 국회 대정부질문 답변 과정에서도 총리께서 왜 수도권 규제완화를 했느냐 하는 그런 질문에 대해서 경기개발연구원 자료가, 말하자면 경제적인 효과가 있다고 하는 그런 연구들이 있고 해서 이걸 참조했다는 말씀을, 답변으로 드렸다는 걸 제가 듣고 그랬습니다마는, 지방에서는 아까 말씀하신 대로 거의 먹혀 들어가지 않고 있는데 이거는 저희가 어떻게 할 방법이 없어 보입니다. 이거는 수도권 규제문제가 이념처럼 고착화가 되어 있고 지방에서는, 일종에 말하자면 논리라기보다는 감성적인 접근을 하는 경향도 있고 무조건 수도권 규제를 완화하면 지방이 죽는다는 그런 일방적인 주장을 많이 하고 있는데 이 점에 대해서는 저희가 노력도 하긴 합니다마는 뾰족한 대책이 지금 없는 상태입니다.
</p>
<p><b>○ 이경천 위원 </b> 글쎄, 우리가 목적하는 것은 수도권 규제가 완화돼서 지금 대한민국이 경제성장력을 잃어가는 것을 다시 복원해야 할 그런 책무가 있다, 이런 생각을 갖고 우리 경기도에서 적극적으로 하고 있는 일인데 방법이 없다고 이렇게 원장님께서 말씀하시면 참 암담한 것 아니겠습니까? 문제가 발생한 것 아니겠어요. 우리가 목적하는 바대로 목적을 달성 못하는 것은 어디엔가 문제가 있다는 것이죠. 문제가 있으면 그 문제를 찾아서 해결할 수 있는 방안을 찾는 것이 또 경기개발연구원의 몫이다, 저는 이렇게 생각을 합니다. 그래서 문제를 인식하지 못하고 있다면 그 자체가 문제가 아니냐, 저는 그렇게 생각하는데 문제를 찾아서 문제를 해결할 방안을 찾아 가지고 현재의 문제를 해결하는 것이 우리가 하고자 하는 목적을 달성할 수 있는 길인데 방법이 없다라고 말씀하시면 이거는 우리가 포기해야 하느냐? 방법을 찾으셔야 한다고 생각합니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 드린 답변에 어폐가 있었던 것 같습니다. 방법이 없다는 게 아니라 저희가 아무리 논리적으로 설명을 하고 해도 지방 쪽에서는 논리적인 대화가 잘 안 되기 때문에 우리가 연구를 통해서 설득하는데 한계가 있어 보인다는 그런 말씀 드리고요. 그러나 저희가 각종 언론활동이라든가, 언론기고, 발표, 방송출연 이런 걸 통해서 수도권 규제완화 문제에 대한 토론에 적극적으로 참여해서 저희들의 연구결과를 알리고 합니다마는 그런 경우에도 저희가 하는 것이 결국 경기도 연구원이기 때문에 그렇지 않느냐 하는, 소위 색안경을 끼고 보기 때문에 적지 않은 한계가 있다는 말씀을 드리고요. 
</p>
<p style="padding-left:1.2em">  그다음에 정치적인 문제가 돼서 어떻게 하면 국회의원이나 중앙에서 정책을 결정하시는 분들한테 저희 의견을 잘 전달해서 중앙의 여론을 끌고 가느냐 하는 점에 저희가 지금까지 주로 노력을 해왔다고 생각해 주시면 되겠습니다. 
</p>
<p><b>○ 이경천 위원 </b> 글쎄, 지금 원장님께서 답변하신 대로 경기개발연구원에서 연구한 것이 객관적인 사실이다, 이렇게까지 말씀을 하시는데 그럼 다른 기관에서는 연구한 부분이 없습니까, 이 부분은? 다른 학자들이라든지……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 불행하게도 수도권 규제를 했을 때, 혹은 완화했을 때 경제적인 효과가 어떻게 되겠느냐 하는 것에 대해서는 제가 아는 한 거의 연구가 없습니다. 우선 중앙에 있는 국책연구기관들은 지난 10년 혹은 5년 동안 균형발전이라고 하는 큰 정책 틀 속에서 연구를 했기 때문에 이런 문제에 대해서 문제제기를 할 수 있는 여건이 아니었고 그러다 보니까 연구도 사실은 거의 이루어진 게 없습니다. 동시에 지방에서 나오는 연구들은 가끔 있긴 있는데 제가 감히 말씀을 드리면 연구의 치밀성이라든가 이론적인 틀이라든가 이런 측면에서 볼 때는 조금 문제가 있다고 보이는 몇 가지가 있는데요. 그렇다 하더라도 그런 것이 수도권 규제완화를 해서는 안 된다고 하는 논리로 설득력 있게 그런 논리를 제시하기에는 좀 미흡하다고 생각이 되고 그나마 제가 보기에는 저희 연구원이 한 지난 2년 동안 나름대로 해놓은 연구들이 중앙에서 많이 활용되고 있고 그렇습니다. 
</p>
<p><b>○ 이경천 위원 </b> 네, 잘 알았습니다. 그러면 연구하신 결과를 어디 홍보하는 데가 있습니까? 책자라든가 발부해서 어디 보내고 그렇게 하십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우선 정규 기본과제나 정책과제 같은 거는 아까 말씀드렸지만 400여 부 넘는 부수를 찍어서, 우리가 배부처가 있기 때문에 다 돌리고 그렇게 나온 자료뿐만 아니라 우리가 긴 연구를 긴 시간에 걸쳐서 할 필요가 없이 정책적인 대안을 낼 필요가 있는 거는 CEO Report라든가 Policy Brief라는 형태로 정책대안들을 계속 생산하고 있고 이런 것들을 청와대를 포함해서 중앙정부의 정책결정자들한테 배포하는 일을 계속 하고 있습니다. 그리고 저희 연구원에서 나온 거의 모든 연구는 도청의 대변인실을 통해서 계속 기자들한테 브리핑을 하고 있고 중앙에도 가능하면 저희 연구결과를 알리도록 다각도로 노력을 하고 있습니다. 
</p>
<p><b>○ 이경천 위원 </b> 원장님께서는 400부 정도 인쇄해서 보내신다 그랬는데 우리 경기도 내에서만 주고 받아서는 의미가 없지 않습니까? 지금 수도권에서는 다 공감하는 부분이고 이게 어떤 마찰 없이 우리의 목적을 달성하기 위해서는 우리 경기도 수도권이 아니라 비수도권에 이게 보내져야 하고 객관적 사실이라고 하면 많은 사람들이 읽고 보고, 연구하신 결과가 파급이 되면 이게 이론도, 이의가 줄어들 것이라고 생각하는데 그러한 노력은 안 하신 것 같아요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저희가 한 연구결과는 16개 시도 연구원에 다 공유를 하게 돼 있습니다. 그리고 솔직히 말씀드리면 저희가 16개 시도 연구원에 있는 박사들도 초치(招致)를 하고 해서 수도권 규제문제에 대한 공동 세미나라든가 이런 걸 많이 해보죠. 그런데 그 입장이 전혀 바뀔 수가 없는 그런 상황에 있다는 생각을 많이 하게 됩니다. 아시다시피 연구원의 독립성 문제라든가 이런 것에 대해서 아까도 약간의 언급들이 있었지만 지사님들이 이런 문제에 대해서 유연한 자세를 취하지 않는 한은 해당 시도의 연구원 박사들이 나와서 그와 다른 얘기를 하기는 그렇게 쉽지 않은 것처럼, 제가 지난 한 2년 동안 대화를 하면서 느낀 소감인데요. 우리가 연구를 해서 다 나눠주고 서로 공유하긴 하지만 영향을 미치는데 좀 한계가 있다 하는 느낌을 받고 있습니다. 
</p>
<p><b>○ 이경천 위원 </b> 하여튼 본 위원이 느끼기에는 많은 노력을 하셔 가지고 주옥 같은 이런 논문들을 많이 발표하셨는데 그 부분이 많은 사람들에게 읽혀지고 앎으로 해서 전국적인 공감대를 이끌어내야 한다고 생각하는데 그러한 부분에 미흡하기 때문에, 우리 경기도 안에서만, 입 안에서만 맴도는 것 같습니다. 이러한 부분을 해결할 수 있는 방안이 무엇인지 연구하셔서, 이 부분들이 널리 보급돼서 전국적으로 이 길만이 우리 대한민국이 다시 성장궤도에 올라설 수 있고 바로 대한민국의 미래를 여는 길이라는 공감대를 우리가 이끌어내야만 수도권 규제의 철폐라는 목적을 달성할 수 있다고 보기 때문에 여기에서 그냥 그치지 마시고 이런 부분을 더 연구하시고 확장해 나가야 한다고 생각합니다. 그렇게 해주시겠습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 물론입니다. 격려말씀 감사하고요. 한 가지 제가 첨언을 드린다면 지난 한 2년 동안 저희가, 중앙에 있는 각종 학회가 있습니다. 지방경제문제를 연구하는 학회라든가 규제문제를 연구하는 학회라든가 이런 학회들하고 공동으로 저희의 의견을 제시할 수 있는 기회를 많이 가져서 그게 사실은 학회라든가 이런 쪽에는 여론을 바꾸고 하는데 많은 도움이 됐습니다마는 지방에는 좀 미흡했다고 저도 느끼기 때문에 앞으로 좀 더 노력을 강화하도록 애를 쓰겠습니다. 
</p>
<p><b>○ 이경천 위원 </b> 네. 문제가 있으면 틀림없이 해결방법이 있습니다. 그런데 그 해결방법을 우리가 찾지 못하고 어렵다든지 이러한 부분에 봉착하는 것이지 문제가 있으면 꼭 해결방법이 있습니다. 해결방법을 찾으셔서 우리가 목적하는 부분을 달성할 수 있도록 연구에 노력을 열심히 해주시기 바랍니다. 이상입니다. 
</p>
