<p><b>○ 정인영 위원 </b> 수도권 규제하고 관련해서 존경하는 고영인 위원님 또 이경천 위원님께서 질의를 해주셨는데, 일요일 날이든가요? 김은경 박사가 일요진단에 나와서 토론하는 모습을 아주 잘 봤습니다. 물론 언론기관에서 그런 토론하는 자리를 만들어서 수도권과 지방 간의 이견이라고 할까 이런 것을 국민들에게 알리는 그런 시간이었습니다마는, 문제는 물론 경기도에서도 이런 홍보문제를 집중적으로 하고 있습니다마는 연구원에서도 연구과제를 내서 그 연구물이 나온 것을 비수도권에 배부하는 것뿐만 아니라 언론매체를 통해서 적극적으로 홍보를 해야 된다고 보는데, 지금 홍보비용이 금년에 얼마 정도나 됐죠? 
