<p><b>○ 경기개발연구원장 좌승희 </b> 꼭 수도권 문제만은 아니고 저희가 홍보를 많이 하고 있다고 생각합니다. 12억이 책정돼 있습니다. 
</p>
<p><b>○ 정인영 위원 </b> 12억 정도, 물론 수도권 문제뿐만 아니라 다른 경기개발연구원의 모든 홍보비용으로서 이 정도 책정이 됐는데 이 문제는 사실 경기도의, 아니면 수도권의 사활이, 대한민국의 사활이 걸려 있는 문제기 때문에 앞으로 이런 것이 계속 논쟁이 된다는 것을 전제로 봤을 때 2009년도에라도 그 홍보비용을 대폭적으로 증대해서 언론매체를 통해서, 사실 이 문제를 우리 경기도 주민들도 잘 모르는 경우가 있다는 얘기죠. 그래서 경기개발연구원에서도 연구 자체로 끝나는 것이 아니라 홍보비를 대폭 증액시켜서 언론매체를 통해서 홍보를 해주셨으면 하는 바람입니다. 가능하시겠습니까? 
