<p><b>○ 경기개발연구원장 좌승희 </b> 괜찮습니다. 이렇게 해야지 위원님들 대면이 돼서, 저도 편하고……. 
</p>
<p><b>○ 정인영 위원 </b> 연구직 충원과 의정연구센터에 대해서 질의를 하고자 합니다. 경기개발연구원은 우리 경기도의 싱크탱크로서 어려운 환경하에서도 그 역할을 충분히 해내고 있다고 생각을 합니다. 그런데 문제는 요즘 행정구역 개편과 아울러서, 국회에서도 행정구역개편 법안이 제출되어 있습니다마는 그 안 중에는 경기도를 폐지하는 그런 안도 포함되어 있는 것으로 알고 있습니다. 그렇다고 한다면 앞으로 행정구역 개편이 어떠한 방향으로 어떻게 진행될는지는 모르겠습니다마는 만약에 도 폐지 후에 과연 경기개발연구원의 존속 가치와 활로모색을 한다면 어떤 방법으로 활로모색이 돼야 할까요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 대단히 어려운 질의이십니다. 우선 저는 지금까지도 도를 폐지하는 안이 국회나 중앙에서 간헐적으로 나오긴 하지만 그게 현실화되리라고는 전혀 생각을 못했는데 지금 위원님 질의를 받으니까 그동안 별로 고민을 못해봤다는 자책감이 듭니다. 우선 퍼뜩 생각하기에 예를 들면 경기도 안에 70만 정도의 새로운 시가 생긴다고 하면 말하자면 시의 연합 연구센터로서 그런 기능으로 갈 수 있지 않을까 하는 생각이 들고 도가 없어진다 그러지만 그게 행정적으로 완전히 없어지는 건 아니고 도지사를 직접 선거에 의해서 뽑지 않고 중앙에서 임명하는 식으로 가겠다고 하는 게 안이기 때문에 그냥 갈 수도 있지 않을까 하는 생각도 들긴 듭니다. 
</p>
<p><b>○ 정인영 위원 </b> 물론 경기개발연구원이 경기도에서 출자한 연구원인데 순수 연구원으로서 발전시킬 생각은 안 갖고 계신가요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 거기까지는 미처 생각을 못했는데 그것도 좋은 한 가지 비전이 될 수도 있겠다는 생각이 들긴 듭니다. 
</p>
<p><b>○ 정인영 위원 </b> 그래서 앞으로 행정구역 개편이라든가, 정국이 어떻게 변화할는지 모르겠습니다마는 경기개발연구원이 경기도의 싱크탱크로서만 아니라 대한민국의 싱크탱크로서 발전할 수 있는 연구원이 돼야 된다고 생각합니다. 그러기 위해서는 지금 재정문제가 상당히 어렵고 그렇기 때문에 지금 연구원들이나 직원들의 후생복지가 상당히 열악한 상황하에서 이직률도 높고 또 정원도 연구원을 제대로 충원하지 못하는 그런 상황에 있는 것으로 알고 있습니다. 그런 의미에서 이런 행정구역 개편이라든가 이런 것이 어떻게 변할지는 모르겠습니다마는 기금을 최대한도로 확보를 해서 재정상으로도 충분히 독립을 할 수 있는 연구원으로서 거듭날 수 있는 비전과 계획을 세워야 된다고 보는데 원장님은 어떤……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 정말 제가 미처 생각하지 못했던 점을 지적해 주셔서 저희가 바로, 몇 가지 대안이 있을 수 있을 것 같습니다. 그러니까 차제에 이렇게 되면 독립화해서 독립기금을 가지고, 물론 경기도를 위해서 일하겠지만 그걸 더 뛰어넘는 국가적인 차원의 연구원으로까지 발돋움할 수 있는 기회로 활용할 수도 있을 것 같고, 또 아까 제가 잠깐 말씀드린 대로 70만 정도의 시군과 협력해서 똑같이 어떤 형태의 모양을 만들 수도 있을 것 같고, 그래서 몇 가지 대안을 가지고 행정구역 개편에 따른 대처방안이라고 해서 한번 내부에서 자료를 만들어서 기회가 되면 한번 위원님한테도 상의를 드리고 기획위원회에서도 좋은 의견을 들어서 만들어 보도록 하겠습니다. 
</p>
<p><b>○ 정인영 위원 </b> 앞으로 경기개발연구원의 발전구상을 한번 해주셨으면 하는 바람이고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 감사합니다.  
</p>
<p><b>○ 정인영 위원 </b> 그런 의미에서 2009년도에는 110억 정도의 출연금이 예산에 편성된 걸로 알고 있는데 그 금액 중에서 기금에 편성되는 예산은 있나요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지금 기금에 들어가는 건 사전에 없고요. 아까 말씀드린 대로 전출금 이런 것들이 들어오고 그래서 나중에 불용액 중에서 일부가 들어가고 하는, 결산을 다 하고 나서 그때 결정하도록 돼 있고 도에서 아예 기금에 넣는 걸로 과거에는 아마 일부를 줬던 게 아닌가 싶은데 최근에 와서는 그런 예가 없습니다. 그래서 아직 내년에는 사전에 얼마가 들어갈지 말씀드리기가 좀 어렵습니다.  
</p>
<p><b>○ 정인영 위원 </b> 물론 경기도 재정도 상당히 어렵습니다마는 경기개발연구원을 순수 연구원으로서 발전시키려면 기금을 확보해야 됩니다. 그래서 그런 것도 2002년도 기준으로 보면 한 50억 정도의 출연금이 출연되고 했는데 그 후에 70억, 80억 이렇게 되면서도, 기금을 한 10억 정도 매년 적립을 했는데 그런 현 상태에서 경영을 하는 것도 좋지만 차후에 대비해서라도 기금 확보를 해주시기 바랍니다.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 
</p>
<p><b>○ 정인영 위원 </b> 그다음에 물론 재정이 어렵기 때문에 이런 문제들이 생기는데 지금 본 위원한테 제출한 자료를 보면 2006년도에는 15명의 결원이 있었고, 연구원인 경우에. 그다음에 2007년도에는 13명, 2008년도에는 11명, 물론 연구원이 이렇게 결원이 줄어드는 것은 굉장히 좋은 현상입니다. 본 위원은 계속해서 왜 연구원에서 연구원이 항상 부족하냐, 정원을 채우지 못하느냐 하는 질의를 했을 때 그때마다 상당히 열악한 후생복지 때문에 훌륭한 인재들이 오려고 하지 않는다라고 답변을 들었습니다. 지금도 그러리라고 봅니다마는 여기 자료에 나타나듯이 2007년도에도, 2008년도에도 2명이 대학으로 가기 위해서 다 의원면직 됐다는 얘기죠. 그렇다면 지금 우리 연구원들은 어느 때라도 대학에 자리가 있거나 불러주면 갈 준비가 돼 있는 연구원들이 아닌가 이런 추측도 해보는데 대학이 오히려 부러워하는, 오고 싶어 하는 그런 연구원으로 발전시켜 주시기를 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 노력하겠습니다. 그런데 아직까지는 대학이 더 매력이 있는 걸로 볼지 모르지만 제가 볼 때는 대학사회가 지금 또 새로운 변화를 해나가고 있기 때문에 조만간에 양쪽이 균형이 되지 않을까 하는 생각도 가지고 있고요. 그렇다고 해서 저희가 노력하지 않는 건 아니고 저희가 적극적으로 해서 연구 분위기도 좀 더 개선하고 이렇게 해가지고…….
</p>
<p><b>○ 정인영 위원 </b> 테뉴어(tenure)에 대해서 연구 검토한다고 하는 그런 답변이 있었는데 지금 그거는 어느 정도 진척이 되고 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 테뉴어가 연구 테뉴어는 아니고 지금 제일 긴 기간이 5년인가요, 몇 번 이렇게 재임용을 한 다음에 맨 마지막에 가서 5년 단위로 재임용하는 그런 제도가 있는데요. 사실 그걸 테뉴어라고 얘기할 수 있지 않을까 하는 생각이 듭니다. 
</p>
<p><b>○ 정인영 위원 </b> 네, 좋습니다. 하여간 우리 연구원들이 연구에 매진할 수 있도록 후생복지에 특별히 관심을 가져주는 것도 원장님의 한 역할이라고 생각돼서 드린 말씀이고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다.   
</p>
<p><b>○ 정인영 위원 </b> 시간이 한 2분 정도밖에 안 남았는데, 의정연구센터가 있는데 연간 예산규모가 얼마나 됩니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 풀로 저희가 전체로 쓸 수 있는 게 한 1억 원 정도 가까이…….
</p>
<p><b>○ 정인영 위원 </b> 의정연구센터가 예산이 1억 정도밖에 안 됩니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 정인영 위원 </b> 그러면 인원도 지금 신원득 센터장 외에는 2명의 임시직만 있지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 지금 위촉으로 두 사람, 초빙으로 쓰고 있습니다. 
</p>
<p><b>○ 정인영 위원 </b> 물론 연구원에서 경기도 집행부나 의회나 같은 맥락이겠습니다마는 의원들의 의정을 뒷받침해 주기 위한 의정센터가 만들어졌으니까, 센터장 혼자서 다할 수는 없는 거니까 이 부분에도 좀 연구원이 충원이 돼서 우리 119명의 의원들의 의정을 충분히 도와줄 수 있는 그런 의정센터로 거듭나기를 바랍니다. 
</p>
<p style="padding-left:1.2em">  그리고 인원이 없다 보니까 연구도 부족하고 의원들을 도와줄 수 있는 다양한 연구가 이루어져야 되는데 그런 것들이 아직 미미한 상태고, 물론 금년에 처음 만들어졌고 기획위원회에서 감사 때 지적을 해서 의정연구센터가 만들어졌습니다마는 2009년도에는 좀 더 확대 발전시킬 수 있는 방향으로 하셔야 되는데 그건 어떻게 생각합니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 정말입니다. 열심히 노력하겠고요. 사실은 저희가 인력충원 문제도 적절한 분을 찾고 있는데, 아무나 할 수는 없잖아요. 또 지방의정에 대해서 이해가 깊은, 좋은 분을 모시려고 애를 쓰고 있고, 내년에 가서 위원님 말씀하신 대로 저희가 확충을 해가지고 좀 더 많은 일을 하도록 노력하겠습니다. 
</p>
<p style="padding-left:1.2em">  그런데 지금 한 6∼7개월밖에 안 됐지만, 신원득 박사 혼자서 했습니다만 아까도 제가 보고드렸듯이 상당히 많은 일을 했습니다. 그래서 일단 소위 출발, 기초는 좀 닦았기 때문에 거기다 좀 더 좋은 분을 모시고, 그래가지고 좀 더 성과를 내도록 내년에 노력하겠습니다. 
</p>
<p><b>○ 정인영 위원 </b> 앞으로 경기도의회 역할에 대해서도 더 관심을 가져주시고 경기개발연구원이 싱크탱크로서 어떤 대안제시를 해주시길 바라면서 질의를 마치겠습니다. 이상입니다.
</p>
<p style="padding-left:2.4em">    (김대원 위원장, 김기수 부위원장과 사회교대)
</p>
<p><b>○ 부위원장 김기수 </b> 정인영 위원님 수고하셨습니다. 좌승희 원장님, 오전에도 계속 서서 하셨는데 앉아서 하시죠.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아니, 괜찮습니다. 이따 제가 힘들면 양해를 구하도록 하겠습니다. 
</p>
<p><b>○ 부위원장 김기수 </b> 더우시면 위에 겉옷도 벗으시고 하십시오. 그러면 다음 질의 하실 위원님 계십니까? 정문식 위원님 질의하시기 바랍니다. 
</p>
<p><b>○ 정문식 위원 </b> 고양 출신 정문식 위원입니다. 존경하는 정인영 위원께서 질의하는 도중에 저는 원장님 답변 듣고 깜짝깜짝 놀라는데요. 지금 행정구조 개편 같은 것을 물어보시는데 거기에 대해서 생각을 안 해보셨다는 말씀에 저는 도저히 이해를 못하겠습니다. 지금 이게 임명직과 선출직의 그런 차이가 아니지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 다시 말씀드리죠. 행정구역 개편에 대해서 연구원에서 고민을 안 했느냐 하는 질의가 아니고 행정구역 개편이 됐을 때 연구원의 미래를 어떻게 생각해 봤느냐 하는 질의에 대해서 그것은 충분히 제가 고민을 못했다는 말씀을 드렸습니다.
</p>
<p><b>○ 정문식 위원 </b> 연구원의 미래도 당연히 도의 미래와 동일시되죠. 그리고 지금 보면 우리가 이 부분을 위원들께서 도민 입장에서 질의드리는 것은 이거 한 가지입니다. 이 행정구조 개편이 과연 우리 도민들한테 어느 게 유리하고 어느 게 도민들의 안녕과 지역발전에 기여하냐에 대해서 우리 위원들도 고민하고 있는 거고 우리 도도 고민하는 겁니다. 그리고 그 분야에 관련돼서 우리 연구원에서도 당연히 그 책무를 가지고 고민하실 필요가 있는 거고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이것은 당연합니다. 하고 있고, 질의를 그렇게 하시면 제가 답을 하지요. 질의를 그렇게 하신 게 아니고 도를 없앴을 때 어떡하겠느냐 하는 질의를 했기 때문에 제가 그 말씀을 드린 거고요. 
</p>
<p style="padding-left:1.2em">  행정구역 개편 문제에 대해서 도를 없애는 거는 저희는 사실 찬성하지 않습니다, 저희 의견은. 여러 번 저희 연구원의 의견을 냈습니다마는 도는 없앨 수가 없다. 그러나 그와 관련해서 도를 좀 더 광역화하는 그런 방향으로 가는 것에 대해서는 저희가 찬성하고 있고 시군의 경우에는 자발적인 노력에 의해서 일부 시군이 통합을 하거나 이렇게 해서 좀 더 큰 모양으로 가는 것에 대해서도 저희가 반대하지 않습니다마는 지금 중앙에서 얘기하는 식으로 50만 인구에 70여 개 정도의 시로 만든다는 그 안에 대해서는 저희가 별로 찬성을 하고 있지 않고, 그래서 제가 도가 없어지는 문제에 대해서는 별로 실현성이 있다고 생각을 안 했었기 때문에 연구원의 미래문제를 좀 깊이 있게 생각 안 했다는 말씀을 드린 것입니다.
</p>
<p><b>○ 정문식 위원 </b> 지금 실효성이 있고 없고의 문제가 아니죠. 지금 보면 정치적으로 이 논의가 상당히 급박하게 이루어지고 있고요. 지금 언론보도만 해도 2010년 안에 이걸 해결하겠다는 의지표명을 계속 하고 있습니다. 그리고 야당에서도 이 부분에 대해서 일정 부분 동의하고 있다고 그러면 사실 우리 경기개발연구원에서는 이 문제에 대해서 지금도 많이 준비하셨다고 하시지만 보다 근원적인 문제에 대한 접근이 필요한데 저는 우리 원장님께서 이 문제에 대해서, 우리 역할에 대해서 너무 가볍게 생각하지 않나 하는 우려가 있어서 먼저 말씀드렸던 부분이고요.
</p>
<p style="padding-left:1.2em">  저는 먼저 우리 연구원에 계신 분들의 처우하고, 그다음에 우리 연구원이 기획조정실, 도청 산하에 있는 문제에 대해서 좀 말씀을 드리고 나머지 것들은 추가질의 때 질의드리도록 하겠는데요.
</p>
<p style="padding-left:1.2em">  지난 업무보고 때 저한테 보고하시면서 연구원 결원부분에 있어서의 아까 학교문제라든가, 그다음에 우리의 이런 지리적 한계성에 대해서 말씀하신 적이 있습니다. 기억하시죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 정문식 위원 </b> 그래서 제가 그 부분에 대해서 우수한 분들이 와서 우리 연구원에 봉직할 수 있게끔 그런 지원제도에 대해서 고민하시고 자료를 내달라고 했는데 따로 제가 받은 건 없는데요. 아직 성과물이 나온 게 없는 거죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그 당시에 봉급수준에 대해서 아마 자료를 요청하신 것 같은데…….
</p>
<p><b>○ 정문식 위원 </b> 봉급수준은 단순 비교를 해주셨고요. 그 당시에 교통개발연구원하고…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 시정연구원하고 이렇게 해서…….
</p>
<p><b>○ 정문식 위원 </b> 서울시정개발연구원하고를 비교해 주셨고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지리적인 것 때문에 무슨 교통비를……. 글쎄, 그 점에 대해서는 제가 특별하게 위원님이 요청하신…….
</p>
<p><b>○ 정문식 위원 </b> 지금 무슨 얘기냐 하면 결원이 생기는 연구원들에 대해서 우리가 지금 학교처럼 안식년제는 하고 있지만, 휴식제는 하고 있지만 다른 부분들에 있어서 우리가 지리적으로 서울시라든가 다른 국책연구기관보다 불리한 점이 있다면 이런 것을 커버할 수 있는 것들이 내용적으로 보자면 자기가 학자적 소신을 지킬 수 있고 또 연구의 편의성이 도모되는 부분이라든가, 또 우리가 후생적으로는 경제적 여건이라든가 이런 게 급여하고도 연결되고, 우리 한국사회가 급여로 그 사람에 대한 평가가 이루어지는 부분이 있으니까요. 이런 부분에 대해서 종합적인 검토를 제가 부탁드렸던 거고. 제가 단순히 요구했던 자료는 지금 우리 개발원에 계신 연구원들의 처우가, 임금부분이 다른 기관과 어떻게 되냐를 제가 보자고 했던 거, 이 부분만 지금 주신 거거든요. 이건 단순비교 자료를 주신 거고 여기에 대해서, 우리가 비교만 하면 뭐합니까, 만날 자료 나오면. 개선책이 나와야지요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그래서 저희는 아까도 말씀드렸지만 금년으로 해서 거의 시정연구원하고 평균적으로 비슷한 수준까지 갔고, 그래서 일단 보수문제에 대해서는 저희가 노력했지만 그다음에 남아 있는 문제는 그게 물리적으로 쉽게 해결되는 문제가 아니라서 고민은 하고 있습니다마는 지리적으로 이렇게 중앙에서 떨어져 있는 것을 어떻게 할 방법도 없는 것이고, 물론 그것의 대안으로 보상 차원에서 저희 연구원 분위기를 좀 더 개선하고 여러 가지 다른 연구원에 비해서 훨씬 더 좋은 연구환경을 만드는 거, 이거는 제가 취임서부터 “대한민국에서 가장 연구하기 좋은 연구원을 만들겠다. 그래서 연구천국을 한번 만들어 보자.” 하는 그런 메시지를 가지고 제가 노력을 하고 있습니다마는 아까도 여러 위원님이 지적했지만 그런 노력만으로 그렇게 좋은 연구원들을 뽑고 또 그런 분들을 떠나지 않게 하는데 여러 가지 한계도 있는 게 아닌가 하는…….
</p>
<p><b>○ 정문식 위원 </b> 지금 원장님 답변은 선언적 의미만 있고요. 원장님 취임 일성으로 하셨던 얘기처럼 그런 환경을 만들겠다고 하셨으면 지금 결원부분이 사실은 해결이 됐어야지요. 지금 말씀하시는 부분 다 맞는 말씀이세요, 큰 틀에서는. 그런데 우리가 보면 현실적으로는 그런 부분들에 대한 대안이 나와 줘야 되는 거죠. 예를 들자면 우리가 지금 지리적으로 어려우니까 여기 주거하는 문제에 있어서의 지원이라든가 이런 부분에 대해서 무슨, 이게 해마다 지적됐던 내용입니다. 행감 때마다 왜 우리 연구원에 연구인력들이 부족하고 우수인력 유치를 못하느냐라고 하시면 지금 같은 말씀을 계속 해오셨어요. 그럼 변화가 있어야 되지 않습니까? 그러면 적어도 우리가 이번에 도에다가 연구원들에 있어서, 도에서도 이번에 판교에다 파스퇴르연구소 유치할 때 파격적 조건에 유치를 했습니다. 그러면 우리가 정말 모시고 싶은 분들에 대해서 이러이러한 조건으로 가겠다라고 제안을 한다든가, 그다음에 지금 연구원 부지 안에 있는 부지들을 어떻게 활용한다든가 이런 구체적인 안들이 한 번도 제시된 것을 제가 자료로 보지 못했다는 거죠. 마음은 다 똑같습니다. 마음은 지금 원장님 마음이나 제 마음이나 같은 것 같은데 가시적으로 보수 올려주는 거는 한계가 있잖아요, 지금. 그런 부분에서 말씀을 드리는 거고요. 이 부분은 지금처럼, 우리가 9월 5일 업무보고 받았습니다. 그때 제가 두 가지 부탁을 드렸었는데요. 한 가지는 우리 연구원에 계신 분들의 임금과 관련된 처우문제에 있어서 대우의 개선책에 대해서 말씀드렸고요.
</p>
<p style="padding-left:1.2em">  또 한 가지는 기금 운용하고 계신 거에 있어서 지금 새로운 기금으로 이율을 바꾸시는 부분에 대해서 말씀을 드렸었습니다. 지금 두 달이 지났는데 경제적 여건은 안 좋아졌습니다. 그런데 이 기금 변경을 시도했다는 얘기를 제가 못 들었습니다. 
</p>
<p style="padding-left:2.4em">    (좌승희 경기개발연구원장, 관계직원에게 확인 중)
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 최근에 상황 변화에 따라서 몇 개는 수익률 높은 쪽으로 바꾸도록 했습니다마는…….
</p>
<p><b>○ 정문식 위원 </b> 지금 보시면…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 질의하신 후순위채권에 대해서는 저희가 기간 때문에 안 되는 것이고, 하여간 나중에 서면으로 상세하게 보고 올리면 안 되겠습니까? 
