<p><b>○ 정문식 위원 </b> 서면으로 보고하시고요. 그때 보시면 9월 5일자 주요 업무보고 책자에 있는 내용하고 지금 상품종류하고 금액에서 차이가 없거든요. 뭐가 바뀌었는지 제가 이해가 안 가고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 후순위…….
