<p><b>○ 정문식 위원 </b> 후순위채권이 서로 양도가 되고 하는 부분은 원장님하고 저랑 그때 서로 확인했던 부분이니까 그거는 여기서 불필요한 것 같고. 그래서 그걸 바꿀 수 있는 부분을 인정하셨기 때문에 바꿔달라고 제가 요청을 했던 거고요. 그런데 바뀐 부분이 있는 겁니까, 여기에 지금?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지금 바꿀 수가 없었다는 게 후순위…….
</p>
<p><b>○ 정문식 위원 </b> 바꿀 수가 없었다?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 기간이 지금 나와 있는 내용으로 보면 이게 2009년 11월이 돼야 조기상환이 가능한 콜옵션이 들어가 있다고 그러는데 그때가 돼야지 저희가 일부 손을 댈 수 있을 것 같아요. 10년짜리 후순위채권은 내년 11월에 조기상환 할 수 있다고 되어 있는데 그때 가서 수익률을 검토해 가지고 새로 조정을 하거나 이렇게 하도록 하겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 지금 외환은행이나 하나은행 게 내년까지 콜이 걸려 있는 거라고요?
</p>
<p style="padding-left:2.4em">    (「내년 11월까지…….」하는 관계직원 있음)
