<p><b>○ 정문식 위원 </b> 오늘자 신문에 이런 기사가 났습니다. HP가 다국적기업 중에 최고 매출을 올리고 있는 IT기업인데 사장까지…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 휴렛패커드…….
