<p><b>○ 정문식 위원 </b> 네, 휴렛패커드. 휴렛패커드가 본사 지시로 사장도 해외출장 시에 전부 다 이코노미로 바꾸라고 했는데 그 얘기에서 보면 인텔이 2005년부터 바꿨고 그다음에 휴렛패커드에서도 당연히 그렇게 하겠다. 우리가 지금은 상황이 좋지만 세계경제 영향 때문에 본사의 조치에 순응하고 조치가 타당하다고 인정한다라는 인터뷰가 있었습니다. 보셨습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저는 보지 못했습니다. 
</p>
<p><b>○ 정문식 위원 </b> 우리 경기개발연구원은 제가 말씀드린 이런 부분하고 이율배반적으로 들릴 수 있지만 저는 그렇게 생각하지 않고 우리 연구원들에 대한 처우나 그런 부분들 말고 경상적인 부분이나, 우리가 또 지금 경제적 상황에 대비해서 공기관으로서의 그런 대응책을 마련하고 계신지 묻고 싶습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 특별히 대응책이라고 따로 이머전시(emergency), 비상계획을 가지고 있지는 않고요. 금년 하반기 이후에 해외출장에 대해서 다소 경직적으로 저희가 검토를 하고 있고, 출장 시에도 저는 1등석을 타본 적이 없습니다마는 가능하면 그레이드도 낮춰서 가도록 해서 외화를 절약할 수 있는 그런 방향으로 애를 쓰도록 내부적으로 독려를 하고 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 지금 휴직제 때 연구원들 나가실 때 체재비하고 항공료 지원하시잖아요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다.  
