<p><b>○ 정문식 위원 </b> 그런데 상당히 비싸네요. 지금 보면 미국 노선 같은 경우에도 전부 다 360만 원, 370만 원, 330만 원, 350만 원 이 정도 이용하고 계신데, 그런데 지금 1년짜리 인터넷 가서 보면 그렇게까지는 안 하거든요. 지금 보면…….
