<p><b>○ 경기개발연구원장 좌승희 </b> 글쎄, 그렇게 상세히 물어보면 저는 사실 답변할 재주가 없습니다마는…….
</p>
<p><b>○ 정문식 위원 </b> 지금 제가 오늘 날짜 대한항공 들어가 보면 1년짜리 일반석으로 하면 200만 원 정도에서 한 230만 원, 그다음에 우리가 흔히 얘기하는 비즈니스석이 380만 원, 1년짜리들입니다. 경유하거나 하는 경우에 따라서 좀 달라지는데요. 제가 구체적으로 이 금액 가지고 논하고 싶은 마음 없고요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 좌우간 저희가 절약할 수 있는 방법을 좀 강구하도록, 좋은 지적을 해주셨는데. 아까 주신 숫자에는 아마 유류할증료 같은 것들도 추가로 들어가는 그런 면이 있겠습니다마는 그런 구체적인 숫자를 떠나서 해외연수 가는 사람들도 가능하면 싼 비행기로 할 수 있도록 제가 독려를 해가지고 애를 써보도록 하겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그러세요, 원장님. 유류할증료가 도입된 지 얼마 안 됐거든요. 그러니까 그런 차원에서, 제가 적절한 예인지 모르겠는데 우리가 경상적인 부분들에서 줄일 수 있는 부분들을 좀 줄여보고, 또 대신에 저는 연구원에 계신 분들이 가장 중요한 게 자기의 명예를 지키는 일이라고 생각합니다. 우리가 정말 학자적 소신을 가지고서 연구할 수 있는 풍토가 얼마나 잘 돼 있냐에 따라서도 훌륭한 연구원들이 우리 연구원에 봉직할 거라고 생각하고요. 그런 풍토를 만드는 데 있어서 우리 원장님 역할이 크고요.
</p>
<p style="padding-left:1.2em">  그리고 또 한 가지는 지금 기획조정실 산하로 있는데 제 개인적인 생각으로는 어떤 도의 기관을 거치는 것보다는 경기개발연구원에서 최종적으로 나온 보고서들은 지사가 정책결정 할 때 참조하고 의회에 이런 부분들이 들어오지만 사실은 그 과정들에 더 중요한 면들이 있지 않습니까? 그 과정 안에서 서로 이렇게 또 걸러지기도 하는데 우리 경기개발연구원 직제를 지금 기획조정실 체제가 아니고 행정1부지사나 별도 독립기관으로 할 수 있는 의향은, 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 보기에는 그게 아주 상당히 훌륭한 생각 같기는 한데 현실적으로 어떨까 하는 생각이 듭니다. 왜냐하면 도하고 실제 업무협조를 계속 해야 되는데 어딘가 창구가 돼야 될 테고 그런 면에서 도 업무를 종합적으로 판단하고 관리하는 기획조정실이 연구원의 카운터파트(counterpart)가 되지 않았을까 하는 그런 생각이 드는데 도지사 직속으로 하거나 행정1부지사…….
</p>
<p><b>○ 정문식 위원 </b> 그러니까 저는 어떤 얘기냐 하면 기획조정실의 업무도 사실은 우리 경기개발연구원 업무와 유사한 점이 있습니다. 경기도 전체의 현황을 챙겨야 되고 또 경기도 전체적인 비전과 대응들을 구상하는 업무적 특성도 있고, 그런데 그런 비슷한 업무를 하는 부서 밑에 있다 보니까 아까 존경하는 고영인 간사께서 질의드린 것처럼 그렇게 오해의 소지도 있고, 또 어떤 부분에서는 만약에 견해를 달리하거나 실무적 견해에서 그렇게 가는 경우에 경기개발연구원이 기획조정실의 의도대로 따라 가고 있지 않냐라는, 그리고 또 심리적 부담도 느끼고 있다는 현실적인 애로사항도 있는 것 같아서 말씀을 드리는 거고요. 여기서 지금 그 문제에 대한 계획이나 이런 걸 말씀하시기는 어려울 테니까 거기에 대해서 경기개발연구원 차원의 검토를 하셔 가지고 보고를 해주시기 바라겠습니다. 가능하시겠지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 알겠습니다. 그런데 지금 현재 체제가 지적하신 대로 그런 우려가 없지 않아 있습니다만, 그래서 저희가 요즘 보고서라든가 이런 중요한 거는 지사님께 직접 전달하거나 보고할 시간을 갖도록 이렇게 해서 약간의 보완을 하려고 애를 쓰긴 씁니다. 그래서 지적하신 대로 저희가 그런 저런 점을 고려해 가지고 한번…….
</p>
<p><b>○ 정문식 위원 </b> 네, 그렇습니다. 제가 아까도 말씀드린 실용적 학문이 필요하다는 게 결과적으로 우리 경기개발연구원에서 생산된 이 결과물들이 우리 도민들의 생활에 영향을 미쳐줘야 되잖아요. 그러려면 정책결정자가 그 부분에 대한 이해라든가 공감대를 형성할 수 있는 기회들이 많이 생겨야 되는데 그런 부분에 있어서 걸러지거나 또 다른 여건들 때문에 왜곡되는 일이 없었으면 좋겠다는 거고요. 그리고 또 나중에 최종적으로 판단한 거는 정책결정자가 책임져야죠. 그 부분에 책임지는데 그 부분까지 가는 그런 과정들을 우리 연구원 측에서도 고민을 하셔 가지고 지금 말씀하신 것처럼 공무원 조직과 연구원 조직이 다르고 또 의회 조직이 다르고 도민들이 바라는 것들이 같은 점도 있지만 다른 점이 있는 그 부분들에 대한 접합점을 찾는데 있어서 좀 더 고민을 해보자는 의견입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아주 좋은 지적이라고 생각합니다. 제가 와서 느낀 것 중의 하나가 저희 연구원이 도정의 어느 한 분야에 관련이 없는 부분이 없는데 제가 도청 실국장 회의를 배석해서 보면 많은 보고가 우리 연구원 연구결과하고 아주 흡사한 것들이 많습니다. 그런데 우리 연구원의 이름이 없는 경우도 많고 이래서 사실은 연구원의 진짜 역할이 충분히 잘 부각이 안 되는 그런 문제가 없지 않아 있다 생각이 돼서, 그래서 저희가 독자적인 PR활동도 강화하고 있고 아까 말씀드린 대로 지사님한테 직접 보고하거나 자료를 전달해서 인풋을 넣는 그런 여러 가지 노력을 하고 있는데 어쨌든 지금 정 위원님께서 좋은 지적을 해주셨기 때문에 저희가 한번 검토를 해가지고 상의를 드리도록 하겠습니다. 
</p>
<p><b>○ 정문식 위원 </b> 저도 지금 잘 받아보고 있습니다. CEO Report나 이런 정책제안서 오는 것들 아주 분량도 좋고요. 많은 고민도 하게끔 해주셔서 감사한데 지금 보면 예를 들어서 부천시 같은 경우에 거의 용역을 없애고 있습니다. 부천시 같은 경우에는 직원들한테 자체적으로, 적어도 부천시의 중장기발전계획이나 이런 부분들을 기획파트에서 하게끔 하고 있거든요. 그다음에 전문가들의 자문을 받고 참조를 하게 하고 있는데 지금 우리 도는 사실 용역만능이잖아요. 그리고 그 부분의 상당 부분을 우리 경기개발연구원에서 해소하고 계시면서 또 어떤 면에서는 정책부서의 의견을 대변하고 있지 않느냐라는 오해를 사시고 있는 부분이 있으니까 많은 고민을 해주시고 거기에 대해서 발전방안을 내주셨으면 좋겠습니다. 
</p>
<p style="padding-left:1.2em">  제가 실질적인 예를 하나 들어 볼게요. 우리 경기도의 미래사업으로 해가지고 콘텐츠 지원시설에 대한 건립에 대해서 예비타당성 조사와 기본계획에 대한 용역을 진행한 게 있었습니다. 이 당시에도 우리 경기개발연구원에서 예비타당성 조사를 담당했었고요. 불과 한 6개월 있다가 타당성 조사는 딜로이트 컨소시엄이라는 거대 용역회사에서 이 용역을 수행했거든요. 그런데 불과 6개월 차이인데 용역결과가 다르게 나왔어요. 이게 결과적으로 고양시의 한류우드 부지 안에 3,800억 정도를 들여서 콘텐츠 지원시설 센터를 건립하는 문제였는데 그 당시에 우리 경제사회연구부에 있는 성명기 박사가 수행을 했었고요, 예비타당성 조사는. 타당성 조사 및 기본계획 용역은 딜로이트에서 임승옥 전무이사가 했었거든요. 그래서 간단하게 이런 겁니다. 우리 연구용역에서는 그때 건물을 IBC센터와 콘텐츠지원센터를 나눠서, 국제비즈니스지원센터랑 콘텐츠지원센터를 나눠서 단독 건물로, 별개 건물로 건설하자 하는 거였고 두 번째는 그것을 복합적으로 건물 하나로 모으자 하는 거였는데 불과 6개월 차이였어요, 이게. 예비타당성 조사한 거랑 본 용역 한 거랑. 결과적으로 나중에 타당성 조사 용역결과대로 해가지고 진행이 돼서 지금 추진이 되고 있습니다. 
</p>
<p style="padding-left:1.2em">  그런데 제가 이번에 자료 요청하면서 우리 연구원에서 이런 예측했던 자료들과 현실결과가 달랐던 경우에 대해서 여쭸더니 단 1건도 없다라고 저한테 보고를 하셨는데 실제로 이렇게 실 사례들에서는 다른 경우들이 나타나고 있습니다.
</p>
<p style="padding-left:1.2em">  그런데 저는 뭐를 말씀드리고 싶냐면 지금 민자도로 같은 경우에 교통량 예측결과가 계속 다르게 나타나고 있습니다. 그래서 지금 국가 재원이 들어가는 경우가 많이 있는데요. 여기서 지금 이번에도 인천에서 지적됐던 문제가 뭐냐 하면 아직 건설되지 않은 도로까지도 집어넣고서 교통량을 조사했다는 거지요. 그런데 그 부분에 대해서 그 연구용역을 수행한 기관도 승인해 주고 또 행정당국에서도 그 부분을 승인해 줬다는 거죠. 그래서 그 산정량을 측정하다 보니까 그 손실부분을 결과적으로 시민들의 혈세 갖고 계속 물어준 겁니다. 그런데 그 당시 민자투자가 시급했다, 이런 궁색한 변명들을 하고 있는데 저는 사실 이런 부분들은 결과에 대한 책임을 져야 될 부분이라고 생각합니다. 이거는 학자적 소신, 명예 부분이 아니고 이거는 위법행위입니다, 위법행위. 뻔히 예견되고 있는 행위에 대해서 그것을 용인해 준다는 건 잘못된 거 아닙니까? 어떻게 생각하세요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 드릴 말씀이 없습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그래서 저는 그 당시에 이 예비타당성 조사가 6,000만 원이 넘는 금액이었고요. 여러 용역들이 있습니다. 우리 경기개발연구원에서 수행했던 용역하고, 예비타당성 조사라든가 기본계획 용역이라든가 타당성 조사라든가 이런 게 왔다갔다 한 경우들이 있어요. 왔다갔다 한 경우들이 있는데 이런 경우에 정말 우리가 결정을 하는 데 있어서 이 부분들이 용역만 여러 번 했다고 해서 되는 것도 아니고요. 그 용역의 결과에 대해서 정말, 우리 경기개발연구원은 우리가 내놓은 결과에 대해서 책임지겠다는 자세를 가지고 한다면 이런 결과들이 안 나오지 않을까? 그런데 이게 제가 꼭 잘못됐다고 말씀드린 예는 아닙니다. 분명히 기간도 짧았고 결과적으로 완전히 결과가 다른 내용이기 때문에 제가 예를 들었던 거고요.
</p>
<p style="padding-left:1.2em">  지금 성명기 박사 우리 연구원에 재직 안 하시죠? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 국회 예산정책처에 가 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 계셨으면 제가 이것도 직접 발언대에서 좀 듣고 싶었는데 안 계시다 그러니까, 이런 사례들이 최소화되고, 또 그다음에 모든 게 다 똑같이 나온다고 저는 좋다고 생각하지 않습니다. 그 나온 근거와 소신에 대한 정확한 근거들을 가지고서 접근하신다면 가장 좋을 것 같고요. 나머지 질의는 추가질의 때 드리도록 하겠습니다. 고맙습니다. 
</p>
<p style="padding-left:2.4em">    (김기수 부위원장, 김대원 위원장과 사회교대)
</p>
<p><b>○ 위원장 김대원 </b> 정문식 위원님 장시간 수고하셨습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그런데 한 가지만 제가 보충답변 조금만 해도 되겠습니까?
</p>
<p><b>○ 위원장 김대원 </b> 정문식 위원 답변이 필요합니까?
</p>
<p><b>○ 정문식 위원 </b> 네, 해주십시오.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 맨 처음에 지방자치제도 개혁에 대해서 저를 포함해서 연구원이 너무 소홀히 대응하지 않았냐 하는 그 지적에 대해서 제가 다시 꼭 드리고 싶은 말씀은 그 문제에 대해서는 저희가 절대 소홀히 다루지 않고 적극적으로 우리가 대안을 내고 있고 필요하시면 제가 많은 자료를 제공해 드리겠습니다. 그런데 단지 제가 말씀드린 대로 도가 없어진다는 사실에 대해서, 제가 도가 없어지지 말아야 된다는 생각을 너무 하다 보니까 제가 그 점을 미처 배려치 못했다는 점을 양해를…….
</p>
<p><b>○ 정문식 위원 </b> 원장님 그 말씀, 저는 원장님이 평상시에 하신 말씀 때문에 그렇게 생각하지 않는다고 저도 생각하고요. 저는 기본적으로 이번 행정구조 개편에 있어서 이 논의 중의 하나가 지금 우리나라가 열심히 해왔던 지방자치제에서 후퇴되는 면이 있는데 그런 부분들에 대해서 언론이나 이런 부분에서 제대로 직시 안 해주는 면에 대해서 과연 누가 얘기할 거냐는 거죠. 대한민국도 대한민국 국민 때문에 있어야 되고요, 경기도도 경기도민 때문에 있어야 되고, 도민들의 안녕과 평화가 최우선 아닙니까? 그리고 그분들의 여건과 개발이 최우선인데 그런 차원에서는 정말 우리가 그냥 우리 밥그릇 때문에 얘기한다는 식의 그런 거는 불합리한 거고 연구원 같은 곳에서 역할을 제대로 해주셨으면 하는 당부입니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 진솔한 답변과 질의 수고하셨습니다. 오후 의사일정 조율과 감사진행 때문에 잠깐 정회하고자 하는데 이의 없으시죠? 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음) 
</p>
<p style="padding-left:1.2em">  잠깐 정회를 선포합니다.  
</p>
<p class=''ar''>(15시18분 감사중지)
</p>
<p class=''ar''>(15시39분 감사계속)
</p>
<p><b>○ 위원장 김대원 </b> 좌석을 정돈해 주시기 바랍니다. 감사를 계속하겠습니다. 
</p>
<p style="padding-left:1.2em">  질의하실 위원님, 고영인 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 고영인 위원 </b> 제가 요청한 자료집 159쪽. 연구원 자체 평가시스템 및 평가보고서를 제가 요청했는데요. 2008년도에는 보니까 양에 대한 평가를 35%, 질 평가를 35%, 근무평가 이게 30% 해서 100%로 평가하는 걸로 돼 있습니다. 그래서 그거를 등급을 매겨서 하는데 일단은 우리가 객관화시키기가 어렵기 때문에 어떻게 보면 상대평가를 하고 있단 말이죠. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니다. 
</p>
<p><b>○ 고영인 위원 </b> 그런데 제가 볼 때는 이게 인위적으로, S 5%, F 5% 해서 인위적으로 딱딱 인원을 배치하는 게 막상 합리적이지 않을 수 있을 것 같은데 어떻게 판단하고 계시죠? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저도 대체로 같은 생각을 가지고 있는데요. 연구원이 출발부터 가지고 있는 게 소위 말하는 정규분포로 이걸 강제하는 그걸 가지고 있어서, 그리고 대부분이 아마 국내 연구원들이 이런 식의 평가시스템을 가지고 있을 겁니다. 그래서 탈피하기가 그렇게 쉽지 않습니다. 너무 인위적으로 하는 경향이 없지 않은데요. 
</p>
<p><b>○ 고영인 위원 </b> 문제는……. 고민은 알죠. 객관화시키기가 어렵기 때문에, 평가라는 게 주관성이 있고 그러다 보니까 이거를 인위적으로 상대적 비율을 정해서 하는 건데. 어려움은 있다 하더라도 좀 몇 가지 객관적 기준을 해서, 어느 연구센터는 다 양적으로나 질적으로 우수할 수도 있고 어떤 연구원은 문제가 될 수도 있고 이런 것들이 내부적으로 객관화되는 시스템이 필요할 것 같고요. 문제는 이것에 대한 평가 이후에 그 활용에 있어서, 160쪽에 밑에서 두 번째 평가활용에 보면 “승진, 재임용 등 인사관리와 성과연봉 지급에 반영” 이렇게 돼 있거든요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 
</p>
<p><b>○ 고영인 위원 </b> 그러면 실제 이 연구평가를 가지고 재임용에서 탈락된 사례가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아직은 없습니다. 아! 탈락은 아니고 계약기간을 바꾸는 게 있어요. 그러니까 우리가 1년 계약, 3년 계약, 5년 계약 이렇게……. 성적이 좋고 오래 한 사람은 나중에 5년 이상으로 가고 하는데 3년 계약하다가 성과가 계속 몇 년 나쁘면 1년 계약으로 갈 수도 있고 이런 등급하향, 이런 건 있었지만 퇴출은 아직 없습니다. 
</p>
<p><b>○ 고영인 위원 </b> 네. 그래서 우리가 사회적으로 보면 학교 교사도 그렇고요, 우리 연구원 굉장히 고생들 하시지만 어쨌건 우리 연구원들도 그렇고 도의원들도 그렇고 도민의 세금으로 되는 거기 때문에 자기 역량을 최대한, 십분 발휘해야 되고 그리고 그런 것이 제대로 부합되지 못한다고 했을 때는 냉정한 평가를 하는 것이 저는 필요하다고 생각하는데, 정치적으로 부당한 재임용을 한다든가 이런 건 막아야 되겠죠, 다른 이유가 있어서. 그렇지만 좀 엄격한 잣대를 통해서 ‘이건 진짜 자질 미달이다.’ 이랬을 때 내부적으로 분명히 손을 대야 된다고 저는 생각하는데 이게 자칫하면 인센티브만 있고 여러 가지 재임용에 있어서는 요식행위로만 된다면 이런 평가가 별 의미가 없다고 생각합니다. 그래서 향후에 이 평가결과에 따른, 아까 재임용 여부, 승진 여부 이런 결과 정도가 있으면 저한테 자료를 주시도록 해주고요. 좀 엄격한 그런 걸 통해서 내부 경각심을 갖고 책임감 있게 할 수 있도록 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 
</p>
<p><b>○ 고영인 위원 </b> 그리고 저도 CEO Report를 잘 받고 있는데, 동북아연구센터장님이 잠깐 답변하실까요? 행정사무감사의 내용에 연구원님들의 내용까지 평가할 그런 영역은 아니라고 보지만 하나의 방향에 있어서 저는 심각한 문제로 하나 느껴서 질의하겠습니다. 
</p>
<p style="padding-left:1.2em">  지난 2008년 북한사회의 실상과 대북협력사업이라는 CEO Report가 나왔어요. 알고 계시죠? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 알고 있습니다. 
</p>
<p><b>○ 고영인 위원 </b> 여기 오관치 초빙 수석연구위원으로 돼 있는데. 나름대로 이런 Report를 작성하려면 여러 가지 객관적 근거라든가 또 정책방향에 대해서 균형감을 갖고 해야 되는데 지금 이 Report에 대해서 내부적으로 센터장으로서 어떻게 보고 있습니까? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 그 Report는 오관치 박사님이 작성한 것입니다. 그런데 CEO Report의 성격이 연구원의 공식적인 의견을 반영하는 것이라기보다는 연구자 개개인의 학문적 성과라든지 주장을 표현하는 장으로 여기고 있습니다. 그래서 오관치 박사님의 그 글은 일견 보수적으로 보일 수도 있습니다. 그래서 그 글을 보면서 상당히 보수적인 평가를 받을 수도 있겠다 싶었지만 이것 또한 북한을 연구하는 오관치 박사님 개인의 의견이기에 그걸 존중해서 출간에 대해서 특별히 부동의를 하지 않았습니다. 그런데 오 박사님이 그 Report를 작성하는 데 있어서는 많은 탈북자들을 만났습니다. 그러니까 본인이 그냥 작성한 것이 아니고 여러 차례…….
</p>
<p><b>○ 고영인 위원 </b> 무슨 얘긴지 알겠어요. 알겠는데, 저는 이걸 보면서 굉장히 분노스러울 정도로 그런 느낌을 받았는데 우리가 최소한 경기개발연구원의, 연구센터의, 거기서 나오는 것일 때는 아무리 개인의 의견을 쓴다 하더라도 그 근거라고 하는 것들에 있어서 학문적 근거라든가 객관성을 유지하기 위한 노력이 굉장히 필요하고, 그리고 이것이 나오면 감수를 해야 된단 말이죠. 저는 이런 것이 과연 우리가 현재 남북 냉기류 상태에서 남북협력을 통해서 어떤 방향으로 가려고 하는지 이유를 잘 모르겠어요. 
</p>
<p style="padding-left:1.2em">  지금 제가 무슨 얘기하는지 잘 모르시는 분들이 있어서 간단히 두세 가지 예를 들어보면, 여기서 보면 기획위원회와 남북협력담당관실에서 굉장히 전략적으로 추진했던 양묘장 사업에 대해서도 전혀 잘못된 것이다, 이런 평가를 하고 있어요. 물론 개인의 판단근거로는 할 수 있지만, 여기에 보면 탈북자들 의견을 많이 했는지 모르겠는데 거의 우리 70년대, 80년대 무슨 반공강연 수준으로 작성이 돼 있단 말이죠. 그래서 “양묘장 사업을 하면 다들 땔감이 없으니까 싣자마자 다 땔감으로 땔 거니까 이런 것들은 오히려 반감만 살 거다.”라든지 그다음에 북한에 우리가 지원품을 주면 그런 것들이 다 쇼를 해가지고 나눠주는 척했다가 도로 다 거둬들인다든지 이런 내용들이 줄줄이……. 주로 그런 내용들이 쭉 있는데 과연 이러한 것이, 우리가 지금 남북협력사업이나, 여기서 연구를 해가지고 우리가 도대체 뭘 지향하느냐? 그러니까 이것을 협력사업을 통해서 통일의 토대를 만들고 북한의 경제력을 높여서 경제력 격차를 좁혀서 통일비용도 줄이고, 우리가 그것을 진척시키는데 도움이 되는 연구가 돼야 되는데 굉장히 주관적이다 이런 얘기죠. 그리고 가장 결정적인 건 뭐냐면 결론이 이래요. 북한 핵문제가 미해결되기 전에는 아주 긴급한 구호만 지원해야 된다. 수해가 났을 때나 전염병 그리고 농장의 소득증대를 위한 사업도 소토지 중심으로 해야 되고 농장원 소득증대 이런 건 하면 안 되고. 그래서 모든 사업은 북한 핵문제 해결 그다음에 남북한 간 군비통제 실시 후에 해야 된다 그래 가지고 우리가 현재 하고 있는 내용도 하지 말아야 된다는 거예요, 이 내용으로 보면. 
</p>
<p style="padding-left:1.2em">  그러면 사실 지금 이 문제가 해결되기 전에 우리가 할 수 있는 게 아무 것도 없다라는 결론을 도출하고 있어요. 그래서 저는 우리가 최소한 연구원이면 그런 학위가 중요한 게 아니라 본인이 주장하는 어떤 근거에 대한 객관적 근거라든가 이런 것들을 통해서, 균형감을 통해서 이 연구의 목적에 부합하도록 이런 걸 해야 되는데 저는 진짜 의심스럽습니다. 이게 동북아연구센터에서 개인의 의견으로 그냥 방치하는 건지 아니면 내부토론을 거쳐서, 아무리 그렇다 하더라도 이런 식으로 진행될 수 있는지 저는 의문이 드는데 어떻게 생각하십니까? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네. 일단 저희 통일ㆍ동북아연구센터는 경기도청과 함께 남북교류협력사업을 2002년부터 해왔습니다. 상당히 적극적으로 참여하고 여러 자문활동을 하고. 기본적으로 저의 인식은 남북 간의 협력사업 활성화를 통해서 남북 간의 평화, 안정, 통일까지 가야 된다라는 생각을 가지고 있습니다. 저희 센터 입장은 그러한데, 저희 센터에 박사가 저와 최용환 박사, 오관치 박사 세 사람으로 구성돼 있습니다. 그러나 박사 중에는, 오 박사님 같은 경우에는 생각이 좀 다를 수도 있습니다. 다른 의견에 대해서 그걸 또 경청하는 자세도 필요하다는 생각을 했었는데 오늘 고영인 위원님 말씀을 듣고 보니까 향후에 저희 연구원에서 Policy Brief나 CEO Report 이런 식으로 나간다손 치더라도 조금 더 조율하는 그런 자세를 갖도록 하겠습니다. 
</p>
<p><b>○ 고영인 위원 </b> 여기서 북에 대해 표현하고 있는 게 혹시 북으로라도 가면 아주 악영향만 끼치지 전혀……. 경기도에서 추진하고 있는 남북협력사업에 도대체 어떻게 기여하려고 작성된 건지 저는 이유를 모르겠어요. 그래서 이 부분에 대한 내부 정확한 논의와 평가를 통해서 향후에 논의의 결과를 저한테 다시 한 번 얘기해 주시기 바랍니다. 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네, 그렇게 하겠습니다.  
</p>
<p><b>○ 고영인 위원 </b> 이런 식의 자료나 방식으로는 경기개발연구원의 전반적인 수준을 저는 의심할 정도라고 생각합니다. 이상입니다. 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 알겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 전동석 위원 보충질의 해주시기 바랍니다. 
</p>
<p><b>○ 전동석 위원 </b> 전동석 위원입니다. 금방 CEO Report에 대해서 고영인 위원님께서 지적하셨는데요. 본 위원도 관심이 많아서 본 적이 있습니다. 저런 CEO Report 같은 것도 심의위원회 심사를 거칩니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 심의위원회는 안 하지만 리더(reader)라고 해서 감수를 하는 사람이 있습니다. 다른 견해를 가진 사람이. 
</p>
<p><b>○ 전동석 위원 </b> 감수는 어떻게 정해집니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 부원장 주관으로 CEO를 작성하는 팀이 있습니다. 거기서 감수할 수 있는 적절한 사람을 선정해서 읽도록 하죠. 
</p>
<p><b>○ 전동석 위원 </b> 지금 그 Report 같은 경우는 어떻게 감수를 했는지요? 
</p>
<p><b>○ 고영인 위원 </b> 김태산 북한구원정책연구…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 김태산이라고 북한구원정책연구소장이라고, 외부 사람입니다. 
</p>
<p><b>○ 전동석 위원 </b> 저는 존경하는 원장님, 항상 제가 존경한다는 말씀도 붙이고 제가 많이 뵈어왔습니다마는 CEO Report라든가, 집에 상당히 많이 들어옵니다. 지금 여기서 개발되는 과제가 끝나는 것들은 전부 책이 집으로 들어오는데요. 거의 제목을 보고, 많이는 못 읽어봅니다마는 가끔 저런 내용들이 지적사항에 나오면 사실상, 물론 학자적인 면이 다르고 또한 생각하는 분야가 다르고 하겠지만, 아마 연구원 누구, 어느 분을 지적하기보다는 연구원 박사님들 자체로도 좀 더 신중하게 생각해야 된다 하는 생각이 들고요. 저는 어디 가서 경기개발연구원이 어디보다 뛰어나다고 얘기하는 사람 중에 하나인데. 어떤 연구결과가 지적을 당하면 그거에 대해서 저도 상당히 분노를 느끼는 입장인데요. 어떻게 생각하세요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저희가 조금 더, CEO Report 제도를 시행한 지가 한 1년여 정도, 활성화된 지가 그래서 이 관리시스템이 조금 미흡했을 수 있다 그런 생각이 듭니다. 그래서 아까 고 위원님 지적도 참작해서 앞으로 감수하는 사람을 늘려서 좀 더 객관성을 높이도록 노력하겠습니다. 
</p>
<p style="padding-left:1.2em">  그런데 그럼에도 불구하고 또 한 가지 측면에서는 이걸 이렇게 관리하기 시작하면 사실은 별로 작품이 나오지 않아서, 저희가 균형을 맞출 수 있도록 최선을 다해서, 아까 지적한 그런 면은 제가 아까 들으면서 그런 얘기를, 죄송합니다. 지금 연결이 되는 질의라서 그런데요. 탈북자들을 만나서 들은 얘기를 다시 들었어요, 직접 듣지는 못했지만. 그래서 그 탈북자들의 얘기 중에 그런 제안이 있었다는 걸 제가 들었거든요. 그래서 아마 이런 것들을 종합적으로 하다 보니까 이런 팩트(fact) 기능이, 쓴 사람도 들은 얘기를 중심으로 정리하다 보니까 그렇게 된 측면도 있지 않나 생각도 들고 그래서, 좌우간 우리가 관리를 좀 더 강화하도록 하겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 엊그제 본 위원이 일이 있어서 국정원에 잠깐 들렀는데요. 국정원에서 책을 한 권 주더라고요.「내 딸을 백 원에 팝니다」이런 책이 있더라고요. 제가 한 반 정도 읽어봤는데 상식적으로 북한을 이해할 수 없는 내용을 그걸 사실화시킨 거죠. 탈북자 시인이 쓴 거예요. 고영인 위원님이, “상식적으로 옛날 60년대, 교육하는 방식으로 되지 않지 않겠느냐.” 물론 그런 면도 있습니다. 그런데 그 책을 읽어보면 그 내용이 시적으로 표현됐는데도 불구하고 상식적으로 이해가 안 가요. 이 정도인가 할 정도로. 우리 상식 이하의 북한이 아닙니까? 상식 이하의 북한이라고 얘기하니까, 그거 속기록에서 지워주세요, 상식 이하라고 얘기한 거 말이에요. 
</p>
<p style="padding-left:1.2em">  어쨌든 우리가 알지 못하는 미지의 세계 것이 많습니다. 오관치 박사님이 직접 탈북자들을 만나보고 어떤 소견서를, 개인적인 소견서를 해가지고 나타냈다고 생각합니다. 하지만 고영인 위원님이 지적하신 대로 스크린을 충분히 해서 적어도 가치 있는 작품들이 나와야 경기개발연구원의 권위가 서지 않겠습니까? 본 위원 생각이 그렇습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 충분히 이해하고요. 제 불찰일 수도 있습니다. 앞으로 관리를 강화하도록 하겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 질의를 마칩니다.  
</p>
<p><b>○ 위원장 김대원 </b> 전동석 위원 수고하셨습니다. 임우영 위원 질의해 주시기 바랍니다. 
</p>
<p><b>○ 임우영 위원 </b> 저도 방금 고영인 위원님 질의에 대한 보충질의입니다. 저는 좀 다르게 생각을 합니다. 제가 오전에도 말씀을 드렸습니다. 연구원들께서 연구하는 것에 있어서 외부에서 어떠한, 의도를 했든 의도를 하지 않았든 어떤 결과물에 대해서 예단(豫斷)을 갖고 여러분들에게 수탁을 줬든 아니면 용역을 줬든 이건 분명히 여러분들이 지켜야 될 선이 있다는 거죠. 그래서 제가 연구하는 데 있어서의 연구활동을 강령할 수 있는 어떤 윤리강령이나 이런 게 있느냐라고 질의를 했었습니다. 
</p>
<p style="padding-left:1.2em">  탈북자를 만나서 탈북자들이 이야기하는 것에 대한 나름대로의 평가를 담고 있다고 저는 생각을 했습니다. 저도 이걸 읽었고 저 또한 탈북자들도 많이 만나봤고 북한도 여러 번 다녀왔고, 평양도 갔었고 개성도 갔었고 또 제가 2년 전에 갔었고 최 근래에 다녀오면서 많은 걸 또 느꼈습니다. 나름대로의 객관성을 갖고 했다라고, 이렇게 판단하고 하는 게 아니라 이것은 지금 오관치 박사 주관을 갖고 탈북자들의 의견을 여기다 정리를 했다고 저는 그렇게 판단을 했었거든요. 그런데 이것이, 물론 이런 것들이 대외적으로 발표가 됨으로 인해서 미칠 수 있는 영향이라든가 이런 것에 대해서는 연구원 자체적으로 한번 검토는 해볼 필요는 있지만 이러한 연구하는 것에 대해서 연구 결과물 하나하나를 갖고 우리가 “이거는 잘됐다, 잘못했다.” 이야기하면 문제가 있지 않나 저는 개인적으로 그렇게 생각을 합니다.
</p>
<p style="padding-left:1.2em">  그래서 오전에도 제가 말씀을 드렸지만 기본적인, 우리 연구활동과 관련된 기본적인 강령 정도는 여러분들이 좀 만드는 것도 어떻게 보면 방금 이러한 논란 속에서 벗어날 수 있는 방법이 아닌가 하는 생각을 해서 보충질의를 했습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 임우영 위원 수고하셨습니다. 고영인 위원 보충질의입니까? 
</p>
<p><b>○ 고영인 위원 </b> 네. 존경하는 임우영 위원님과 전동석 위원님이 나름대로 의견을 얘기해 주셨는데 혹시 오해가 있을까봐 제가 한 말씀 더 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  저도 아까 전제로 한 건 뭐냐면 우리가 행정감사에서 경기개발연구원의 전반적인 시스템이나 방향 또는 예산, 조직 이런 것들을 중심으로 우리가 감사를 하는 거고, 연구원님들의 연구내용까지 일일이 여기서 평가하고 감사할 수 있는 사안은 저도 아니라고 생각합니다. 그건 존중을 해야 되고. 그렇지만 제가 굳이 이걸 지적하는 건 뭐냐면 여러 연구센터가 있는데 이 연구센터에서 우리가 전반적으로 공유하는 하나의 목표가 있어요. 경기개발연구원의 연구과제를 통해서 무엇을 지향하고 어디에 기여하려고 하느냐라고 하는 연구방향이 있단 말이에요. 오늘 거기에 다 제시하지 않았습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 물론입니다. 
</p>
<p><b>○ 고영인 위원 </b> 그러면 이런 연구방향에 입각했을 때, 우리가 누구든지 개인의견을 다 얘기할 수 있겠죠, 연구원이면. 그렇지만 우리가 전체적으로 공유할 수 있는 연구방향이라고 하는 거에 복무(服務)할 수 있도록 하는 데 있어서 굉장히 결정적으로 거기에 배치된다든가. 그 흐름에, 이거는 우리가 목표로 하는 남북협력사업의 활성화와 통일을 앞당겨 나가는 이런 과제에 복무하는 게 아니라 오히려 굉장히 해를 끼칠 수 있는 그런 심각함이 있다라고 했을 때는 논의해 볼 수 있다라고 저는 보는 겁니다. 그런 측면에서 보기 때문에 제기를 한 거고. 단순히 북한 난민들의 증언을 실었다, 안 실었다 이런 거는 저는 있을 수 있다고 보지만 문제는 여기서 내리는 결론이라든가, 또는 사전에 하는 게 객관성에 있어서도 저는 굉장히 하자가 많단 얘기예요. 
</p>
<p style="padding-left:1.2em">  그러니까 최소한 박사님들이 이런 걸 하면 근거를 제시하지 않습니까? 우리가 논문을 쓰든가 뭘 하면 그것이 누구의 인용이라든가 이런 것들을 통해서 하는데 여기는 그야말로 통제장치 없이 얘기하는데, 예를 하나 더 들어볼게요. “김정일은 주민들이 기아로 죽어나가더라도 핵무기 미사일을 포기하지 않겠다는 자세다.” 그리고 “한국에서 핵포기를 달성하기 위해서는 북한주민의 상당한 희생을 감수해야 된다.” 이런 결론을 내리고 있어요. 그러면 이런 것들이 어느 정도 근거를 가지고, 제가 볼 때는 북한 핵을 가지고 나름대로 북한이 어떤 협상을 하고, 미국과의 관계나 남한과의 관계에서 그걸 해가지고, 핵무기를 나름대로 하나의 수단으로, 자신들도 내부의 체제 안정을 위해서는 경제력이 향상돼야 체제가 안정된다고 생각할 거 아닙니까? 그런데 이런 것을 단정적으로 이렇게 결론을 내려놓고 이런 핵문제와 군비통제 실시 전에는 지원사업을 하면 안 된다고 내리고 있어요. 그러면 지금 우리가 남북협력사업 하고 있는 걸 전체적으로 부정하고 있다 이 말이에요, 현재 진행되고 있는 내용들을. 그럼 이런 부분들에 대해서 저는 그런 객관적인 근거를 갖고 하는 자세가 기본적으로 안 돼 있다라고 하는 그런 연구의 방향과 배치되는 걸 지적하는 겁니다. 
</p>
<p style="padding-left:1.2em">  그래서 혹시라도 제가 무슨 연구원님들 나름대로의 학문적 소신과 그것을 통해서 나타나는 거를 존중하지 않는다든가 결코 그런 의도는 없는 거고요. 좀 이해를 해주셨으면 좋겠습니다.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 알겠습니다. 더 질의하실 위원님, 보충질의입니까? 
</p>
<p><b>○ 정문식 위원 </b> 네.
</p>
<p><b>○ 위원장 김대원 </b> 정문식 위원 질의해 주시기 바랍니다. 
</p>
<p><b>○ 정문식 위원 </b> 의사진행발언인데요.  
</p>
<p><b>○ 위원장 김대원 </b> 네.
</p>
<p><b>○ 정문식 위원 </b> 지금 고영인 간사께서 말씀하신 내용하고 제가 어제 2청사에서 기획행정실 때 대북 관련돼서 지적했던 내용하고 어떻게 보면 일맥상통하는 내용입니다. 어제 우리 대북기금에 있어서의 두 가지 원칙이 하나는 인도주의 원칙이고 또 하나는 상호호혜평등의 원칙으로 하겠다고 했는데 우리가 상호주의에 입각한 혜택을 본 게 없다는 걸 제가 지적했거든요. 그다음에 제가 개풍양묘장 같은 경우에도 CO₂배출권에 대해서 이걸 우리가 가질 것인지에 대한 협의 없이 진행된 부분에 대해서 지적을 하였고 기획행정실에서는 CO₂배출권을 금년도 이번 대북협력사업 의제로 다뤄서 우리가 CO₂배출권을 갖는 쪽으로 하겠다는 거거든요. 그런데 지금 간사님 말씀하시는 부분이 연구원에 관련된 부분뿐만 아니라 우리 의원들 상호 간에 관련됐던 의정활동과도 관련된 부분이고 하기 때문에 잠시 정회를 하셔서 이 부분은 정리를 하시고서 다시 속개해 주시기 바라겠습니다.  
</p>
<p><b>○ 위원장 김대원 </b> 아니, 이건 속기록에 기록된 사항이니까 대북사업문제는 예산과 사업설명 시, 대북 관련 부서에서 사업설명 시 이 문제는 우리 위원회 안으로 모아서 결정할 사안이지 지금 감사장에서 의사진행으로 진행될 사항이 아니니까……. 
</p>
<p><b>○ 정문식 위원 </b> 아니, 그게 아니고 지금 논의되는 부분이……. 
</p>
<p><b>○ 위원장 김대원 </b> 아니요. 이거는 지금 현재 감사장에서는 의원 각기(各其)의 소신으로 감사를 하시고 사업목적이나 결정은 사업설명이나 대북관계 실제 사업부서인……. 
</p>
<p><b>○ 정문식 위원 </b> 제가 말씀드리는 건 위원장님, 지금 우리 간사께서 지적하신 부분이 연구원의, 연구자의 발표에 대한 소신과 관련된 부분뿐만 아니라 다른 의원들의 의정활동과도 관련된 부분까지 지적이 되셨다는 부분입니다.  
</p>
<p><b>○ 위원장 김대원 </b> 아니, 개인적인 소신이니까요, 개인적인 감사시니까 그거는 관여치 마시고 답변은 연구원장 소신에 따라서 하는 거니까. 그건 관여치 마십시오. 
</p>
<p><b>○ 고영인 위원 </b> 각 의원의 의견으로 해서 자기 판단을 가지고 질의를 하는 거고 거기에 대한 답변을 듣는 자리니까 저는 그렇게 진행은 하면 된다고 생각하고, 아까 단지 제가 질의한 것에 대해서. 추가질의 나왔던 부분에 대해서 상호 답변을 했으니까 그걸로 끝내고 의견이, 예를 들면 남북협력사업에 있어서 이견과 방향 이런 것들은 우리 내부의 자체 토론을 나중에 하면 되죠. 그렇게 하면 되고요. 
</p>
<p><b>○ 위원장 김대원 </b> 그거는 사업부서에서 사업설명이나 예산심사 할 때 사업목표를 정해 주면 되는 것이고 여기는 의원 각기의 소신으로 감사를 하시고 또 원장님도 그 사안에 따라서 소신껏 답변하시고 그 사안은 연구하시는 박사님 개인 소신이니까 그 부분은 저희들이 위원회에서 방향을 제시할 필요는 없다고 봅니다. 이 문제에 대해서는……. 추가질의 더 하시겠습니까? 추가질의로 하시든가 아니면 정회하고 의사진행을 협의를 보고 하시든가. 그런데 이 부분은 위원장 생각으로는 감사부분이니까 예산이나 사업설명회 때 조율하는 게 옳다고 봅니다. 
</p>
<p><b>○ 정문식 위원 </b> 그럼 대북사업 부분은 그렇게 사업 분야 할 때 정리하기로 하고요. 원장께서는 지금 고영인 간사 질의에 CEO Report라든가 이런 대외적으로 나가는 거에 대해서 통제기구를 가지거나 심의를 좀 더 강화하신다고 하셨습니다. 어떤 취지입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 예를 들면 감수인을 한 사람 더 해서 제3의 의견을 또 한 번 들어본다든가 하는 그런 체제를 해볼 수 있지 않을까 싶은데요. 제가……. 
</p>
<p><b>○ 정문식 위원 </b> 지금 그거 말씀하시는 건 우리 시스템적으로 한 번 더 의견을 수렴해 보자는 차원이지 구체적으로 적시돼서 논의되고 있는 사안에 대한 의견은 아니신 거죠? 
</p>
