</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니다. 이 사안 자체에 대해서는……. 
</p>
<p><b>○ 정문식 위원 </b> 개별사안에 대한 답변이라고 받아들이는 건 아닌……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 김동성 팀장이 상당한 정도로, 충분히 설명을 드렸다고 생각이 됩니다마는 저는 솔직히 말씀을 드려서 고 위원님 의견에 상당히 일리가 있고 우리가 수용할 점이 있지만 또 다른 견해도 있을 수 있다는 생각을 버릴 수가 없습니다. 이 북한문제는 정말 첨예하게 다른 견해들이 공존하고 있기 때문에 단지 이 보고서가 어느 한 쪽 의견만을 너무 강하게 제시했다는 점에서 균형을 좀 잃었다 이렇게 지적을 할 수 있지 않을까 하는 생각은 들지만 그렇다고 이게 전혀 돌출된 생각이다, 이렇게만 얘기하기는 어려운 게 한국사회의 현실이 아닌가 싶어서 상당히 미묘한 사안이라고 생각돼서 제가……. 일단 이 보고서가 이렇게 나가면 그다음에 또 한 번, 제가 이런 문제도 다시 한 번 CEO Report를 쓸만한 사람을 찾아서 더 제3의 의견을 들어볼 수 있는 기회를 가져본다든가. 좌우간 밸런스를 맞출 수 있도록 제가 노력은 해보겠습니다마는 그럼에도 불구하고 현재 나타나는 견해의 차이라든가 이런 거는 제가 보기에는 쉽게 해소되기는 어렵지 않을까 하는……. 
</p>
<p><b>○ 정문식 위원 </b> 지금 원장님 답변을 가만히 듣고 있다 보면 지금 이 문제를 어떻게 좀 더 시정해야 되지 않냐라는 오해가 생길 수 있는 답변이 있었다고 제가 느끼기 때문에 이 말씀을 드리는 거고요. 지금 CEO Report 발간하는 체제 자체에 있어서 보완을 하겠다는 거에는 제가 개인적으로 동감합니다. 감수자를 1명 더 둔다든가, 그다음에 서로의, 내부에서 필진을 구성하는 부분에 있어서의 고민이라든가 이런 부분은 가능한 부분이지만 아까의 답변은 얼핏 듣기에는 지금 발행되어 있는, 지금 발간되어 있는 특정 Report에 대한 견해처럼 들릴 수 있기 때문에…….
</p>
