</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 공식적이라는 말을 붙이기는 다소 어려움이 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그러니까 공식 견해라는 게, 저의 표현에도 오해가 있을 수 있겠지만 이미 우리 연구원에서 발간한 발표문 아닙니까, 그렇죠? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
