<p><b>○ 정문식 위원 </b> 그거를 다시 철회하거나 할 수 있는 사항은 아니지 않습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 주워 담을 수는 없지요. 그런데 그렇게 해서 교훈이 있다고 하면 앞으로 전체 시스템에 대한 관리를 좀 더 합리적으로 하는 문제가 하나 있을 것이고 이 문제에 대해서도 우리 팀 내에서 한번 고민을 해보고 제3, 제4의 의견이 있을 수 있다면 유사한 CEO Report를 한번 구상해 볼 수도 있지 않을까 하는 생각은 드는데 그거는 제가 나중에 팀원들하고 생각을 해봐야 될 것 같습니다. 
</p>
<p><b>○ 정문식 위원 </b> 아까도 제가 처음에 말씀드렸듯이 우리 연구원에서 연구원들은 본인의 학문적 소신이 제일 우선입니다. 그리고 저는 두 번째 우리 연구원의 존립목적 중의 하나는 실용적 학문이거든요. 우리 경기도정에 얼마나 이바지하시고 자료들과 버팀목이 돼 주시느냐 하는 부분입니다. 그래서 그게 실질적 도민들의 생활에 영향을 미치는 학문을 하신다고 생각하는 거거든요. 그래서 그러한 차원에서 좀 더 심도 있게 고민을 하신 후에 답변을 해주셨으면 하는 바람입니다.
