</p>
<p><b>○ 임우영 위원 </b> 혹시 원장님, 이 CEO Report를 읽어보셨습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 읽지는 않았지만 오관치 박사하고 이 문제를 심도 있게 얘기를 같이 해서 이런 내용을 쓰겠다는 얘기를 들어서 알고 있습니다. 
</p>
<p><b>○ 임우영 위원 </b> 이게 우리 고영인 위원님이 이해를 해주시리라고 생각하고 제가 말씀드리겠습니다. 여기 보면 이렇게 되어 있습니다. “경기도가 대북협력사업을 추진함에 있어서 북한의 실상을 이해하여야만 본래의 목적대로 사업효과를 기할 수 있음. 본 보고서는 북한 내부사정에 정통한 전문가에 대한 심층면접과 관련 자료를 통하여 파악된 북한의 실상을 제시함으로써 향후 경기도의 효과적인 대북협력사업 구상과 추진을 지원하는 데 목적이 있음.” 이렇게 되어 있습니다. 
</p>
<p style="padding-left:1.2em">  그리고 우리 고영인 위원님께서 말씀하신 내용들은 전문가들 면접하는 내용입니다. 탈북자가 됐든 북한의 전문가가 됐든 그분들이 하시는 내용들을 그대로 옮겨놓은 부분들이 많습니다. 그런데 이러한 부분까지 우리가 여기서 얘기하면 문제가 복잡해지지요. 여기 연구하는 거 다 일일이 우리가 하나하나 전부 이런 식으로 해야 됩니까? 그거는 아니라고 생각하는데. 우선 이런 부분들에 대한 질의가 나왔을 때 처음에 답변하시는 분들이 제대로 해주셔야지요. 동북아센터 센터장님도 그렇고 이런 게 나오면 그거는 이러이러한 목적을 가지고 우리가 만든 Report입니다라고 얘기를 해줘야지 어떻게 그 의견에 일맥상통한다는 얘기가 나오고, 도대체 뭐 하시는 겁니까? 그래 가지고 어떻게 자유로운 연구가 되고 어떻게 여러분들의 근무여건을 제대로 지원해 준다고 말할 수 있겠어요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 말씀 좀 올려도 되겠습니까? 
</p>
<p><b>○ 임우영 위원 </b> 아니, 연구목적이, 이 Report를 내는 목적이 딱 나와 있잖아요. 이게 경기도에 사업을 못하게 하겠다든지 아니면 내 주관을 가지고 어떻게 하겠다는 게 아니고 “북한에 대한, 전문가들에 대한 심층면접과 관련 자료를 제시함으로써 한다.” 이렇게 명백하게 목적이 나와 있다고, 목적이. 이런 것이 나와 있으면, 도대체가 동북아센터장님이라는 분도 그렇고 이런 Report 감수도 안 하고 그랬으면 나오면 읽어도 보고, 이런 게 나오면 최소한 이 정도의 Report입니다라고 답변을 할 정도가 돼야 얘기가 되는 것 아니냐 이런 얘기예요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아까 제가 답변 모두에 오관치 박사가 탈북자를 중심으로 면접을 해서 거기서 얻은 사실을 기초로 해서 CEO Report를 쓰겠다는, CEO Report를 쓸 때 많은 경우에 제가 사전에 그 내용을 인지를 하고 이게 정보로서 값어치가 있다고 했을 때 제가 해보라고 해서 시작하는 경우가 많습니다. 그래서 아까도 말씀드렸지만 이 사람은 탈북자를 접촉해서 거기서 나온 정보를 가지고 정리하고 그걸 알리는 것에 사실은 최초 목적이 있었습니다, 제가 아까도 잠깐 언급을 했지만. 그러나 이게 보는 관점에 따라서는, 특히 대북문제 관련돼서는 이념적으로도 서로 다른 이념을 가진 생각들이 많고 이러기 때문에 거기에 따라서는 또 그렇게 해석할 소지도 있지요. 그 점을 제가 시인을 한 것이지 이 연구의 출발점이나 목적에 대해서는 제가 아까도 언급을 하지 않았나 하는 생각이 듭니다. 그러나 아까 우리 김동성 팀장이나 제가 얘기하는 과정에서 임우영 위원님 말씀하신 그런 점을 보다 더 명백히 하지 못한 것에 대해서는 저희가 불찰이 아닌가 싶습니다.
</p>
<p><b>○ 임우영 위원 </b> 최소한 연구원들이 내놓은 결과물에 대해서 개인의 의견이 되었든 어쨌든지 간에 경기개발연구원이라는 기관을 앞에 내걸고 발표하는 연구보고서입니다. 그게 개인의 의견이 됐든 아니면 기관의 의견이 됐든 경기개발연구원이라는 기관의 이름을 내걸고 나가는 Report예요. 그러면 그러한 Report에 대해서는 이유야 어디에 있었든지 간에 우리 원장님을 비롯해서 관리하시는 임원들이 그거에 대한 책임을, “나도 공감한다. 나도 그 연구원과 같은 생각을 가지고 있다.”가 아니고 “이 Report에 대한 책임은 내가 감수한다.”라는 기본적인 자세가 되어 있어야지 방금 원장님이나 동북아센터장님 말씀하신 대로라면 그건 오관치 박사 개인의 의견이니까 전부 오관치 박사한테 떠미는 거 아닙니까? 그런 식의 답변이 어디 있을 수 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저는 오해의 소지가 좀 있다고 생각이 됩니다. 만일 그렇지 않고 이거를 아까 여러분들이 누차 말씀을 하셨지만 나가는 게 전부 다 연구원의 공식견해처럼 하게 되면 제가 누차 말씀드렸지만 우리 CEO Report를 하는 이 사업은 할 수가 없습니다. 이게 많은 것 중에 이런 문제가 생길 수가 있지요. 그러나 아까도 말씀드렸듯이 이런 문제를 가능하면 최소화하기 위해서 관리체제를 좀 더 합리화하고 이렇게 하는 것은 제가 해나가면서 고쳐나갈 수 있지만 그렇다고 해서 제가 나가는 걸 전부 읽고서 다 할 수는 없습니다. 그러나 물론 사전에 제가 어떤 내용이 담길 것이고 어떤 과정을 통해서 이런 걸 하겠다고 하는 것인지에 대해서는 사전에 인지를 하고 CEO Report를 추진하라고 지시를 하기 때문에 그런 점에서는 아까 임 위원님 말씀하신 것처럼 제 책임이지요. 책임이지만, 고 위원님이 지적하신 거와 같은 그런 입장에서 문제를 볼 수도 있을 만큼 이 문제는 첨예한 이념적인 차이가 있기 때문에 제가 그 점을 충분히 인지해야 하지 않을까 하는 그런 점에서 제가……. 
</p>
<p><b>○ 임우영 위원 </b> 제가 우리 고영인 위원님의 질의에 대해서 문제를 제기하는 게 아닙니다. 충분히 그럴 수 있습니다. 여기 내용을 읽어보시면 충분히 그럴 수 있어요. 그렇지만 문제 제기부터 결론과 건의내용을 읽어보시면 이게 어떤 내용으로 이루어졌구나 하는 기본적인 이해는 갑니다. 그러면 최소한 그런 거에 있어서는 관리하시는 입장에 있는 분들이 어떻게 보면 연구원들을 대변할 수도 있고 기관의 명예를 걸고 이야기할 수도 있다고 저는 생각을 합니다. 그러한 마음자세가 참 중요하다, 그거를 제가 지적하기 위해서 말씀을 드리는 거예요.
</p>
<p style="padding-left:1.2em">  분명히 여기는 이 Report의 목적이 어디에 있고 또 시사, 결론부분에 보면 우리 경기도에서 앞으로 해야 될 대북사업에 대해서는 엄격하게 구분을 해서 추진하는 게 바람직하다. 그래 가지고 이렇게 쭉 결론을 내려놨어요. 왜? 아까도 얘기했듯이 기본적인 북한의 실상에 대해서 많은 국민들이나 도민들이 알지 못하니까 이러한 탈북자들을 중심으로 해서 한번 그런 걸 여기다, 그러한 이야기하는 내용을 한번 쭉 적어놓은 거예요. 그러니까 그 Report를 우리 원장님이 꼭 한번 읽어봐 주시기를 부탁드립니다. 이상입니다.
</p>
<p><b>○ 위원장 김대원 </b> 임우영 위원님 수고하셨습니다. 북한문제에 대해서 더 질의하실 위원님 계십니까? 연구원에 대해서 더 질의하실 위원님 계십니까? 임우영 위원 질의해 주시기 바랍니다. 
</p>
<p><b>○ 임우영 위원 </b> 제가 오전에 이어서 몇 가지만 더 확인을 하도록 하겠습니다. 지금 보면 도정의 정책개발연구나 정책과제나 아니면 수탁연구, 정책기본연구 해가지고 기본적으로 연구원들이 가지고 있는 업무의 양이 지금 과중하지요? 어떻습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 과중 이런 표현, 상당히 많다고 생각합니다. 그런데 과중이라고 표현해야 할지 모르겠습니다마는…….
</p>
<p><b>○ 임우영 위원 </b> 보통 평균적으로 연구원 한 분당 수행하는 과제 수가 몇 개 정도 됩니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 평균과제가, 매년 맨먼스(man/month) 수로 따지면 1인당 4.3건을 수행하고 있고 공동으로 참여하는 것까지 다 하면 9.7건을 연간…….
</p>
<p><b>○ 임우영 위원 </b> 거의 1년에 10건 정도를 수행하네요. 평균적으로 따지면 한 달에 1건 정도를 수행한다고 봐야 되겠네요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 임우영 위원 </b> 그런데 기본적으로, 어떻습니까? 출장을 가시거나 아니면 대학에 출강을 나가거나, 제가 여기 출강하는 것을 보니까 전부 야간학부에 출강을 나가시는 모양이죠. 전부 다 늦은 시간에 출강을 가신다고 되어 있는데, 이러한 잦은 출장이나 출강이 연구에 혹시 큰 지장을 초래하거나 그런 경향은 없습니까, 어떻습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 출장은 많은 경우가 연구하고 관련돼서 나가는 출장이 많습니다. 
</p>
<p><b>○ 임우영 위원 </b> 예를 들어서 세미나 참석이라든가…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 세미나 참석하는 것도 있지만 자기 연구프로젝트와 관련해서 현장파악이라든가 면담 이런 게 많기 때문에, 주로 그런 게 많고요. 그러니까 그냥 나가는 출장은 연구에 도움이 된다고 보는 게 옳고요. 강의 나가는 것은 대부분 일과 후에 하기 때문에 그건 본인이 밤잠을 덜 자거나 이렇게 하면서…….
</p>
<p><b>○ 임우영 위원 </b> 물론 그렇다 하더라도 연구에 영향을 미쳐서는 안 되겠죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 물론이지요.
</p>
<p><b>○ 임우영 위원 </b> 그런데 그것이 어떻게, 출강을 나가시는 신분이 어떻게 됩니까? 전임강사입니까, 어떻게 나가시는 겁니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 전임강사가 아니고 시간강사지요.
</p>
<p><b>○ 임우영 위원 </b> 시간강사입니까, 시간강사로?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 임우영 위원 </b> 하여튼 제가 그런 것까지 문제제기를 하는 것이 아니고 이러한 것들이 연구원 고유의 목적과 아니면 연구하시는 데 있어서 많은 지장을 초래해서는 안 되겠다 하는 차원에서 제가 한번 여쭤봤습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 명심하겠습니다.
</p>
<p><b>○ 임우영 위원 </b> 그리고 또 하나는 지난번에 이사회 회의록을 제가 보니까 사무실의 협소문제, 별도의 사무실을 준비하는 게 좋겠다 하는 차원에서 말씀을 하신 적이 있습니다. 그거는 어떻게 그 이후에 추진된 게 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 중간에 사무실난이 좀 있었는데요. 저희가 팔당물환경센터가 생기고 나서 실험실이 12층에 있었는데 그 실험실을 폐쇄했습니다. 그래서 여기 자리를 새로 만들어 가지고 지금은 충분한 여유는 아니지만 어느 정도 사무실난을 좀 해소해서 가고 있는데 여러 위원님들 지적하셨다시피 앞으로 충원을 좀 하고 이렇게 하게 되면 사무실 문제가 또 부각이 되지 않을까 싶습니다마는 지금 당장 한 1∼2년 정도는, 당분간은 우선 일단 갈 수 있지 않을까 하는 생각이 듭니다. 
</p>
<p><b>○ 임우영 위원 </b> 그때 이사회에 보고하시고 나서 그럼 그 뒤에 다른 변화되는 거나 아니면 어떻게 노력하시고 있는 그런 거는 없습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 근본적인 대책 말씀이죠?
</p>
<p><b>○ 임우영 위원 </b> 그렇죠.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 근본적인 대책은 우리 연구원 건물을 어디 확보를 한다든가 다른 데로 가는 문제, 아니면 따로 건물을 추가로 임대하는 그런 문제가 되겠는데 이 건물 자체를 옮기자는 문제는 2년 전부터 간헐적으로 그런 문제를 고민하고 논의를 했습니다마는 당장 사무실 일부가 모자라서 어디 새롭게 임대를 하거나 하는 것은 특별하게 계획을 생각해 보지 못했습니다. 
</p>
<p style="padding-left:1.2em">  더구나 최근에 우리 과학기술정책센터가 광교로 독립사무실 해서 나가면서 거기에 있던 인력이 일부 또 나가고 그래서 당분간 조금 여유가 있지 않을까 판단하고 있습니다. 
</p>
<p><b>○ 임우영 위원 </b> 글쎄요. 여기 보고하신 것 보면 기존에 있는 이 건물에 다른 사무실들이 이동할 수 있는 공간이 나올 수도 있다. 그랬을 때는 이 건물 전체를 독립청사로 우리 연구원이 쓰는 것도 하나의 방법이다라고 말씀하셨는데 그거는 어떻습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 글쎄, 그게 지금 뭐, 사실 이 부지 안에 큰 건물이 있는데 저게 건물은 중앙정부 소유고 땅은 경기도 소유라고 제가 그렇게 알고 있습니다. 그래서 우리 지방행정연수원이 행정복합도시로 이전계획이 있기 때문에 만일 그게 실현이 되면 그때 경기도에서, 지금도 좀 있고 그러니까 저 건물을 인수하거나 하는 걸 통해서, 좌우간 여기 교육원하고 협력을 해서 서로 독자적으로 건물을 확보하는 방안이 있지 않을까 하는 그런 얘기를 지사님한테 한번 들은 적이 있고 그렇습니다마는 당장 그게 실현이 될지 안 될지 우선 그것부터가, 행복도시 자체가 지금 진척이 안 되고 있습니다.  
</p>
<p><b>○ 임우영 위원 </b> 하여튼 고민을 좀 많이 하셔야 되겠네요. 그리고 오전에도 얼핏 이야기했습니다만 정원이, 특히 연구직 같은 경우 부족하다는 말씀이 계셨는데 이게 각 센터별로, 연구부서별로 정원이 정해져 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 정원은 정해져 있지 않고요. 우리가 지금 가지고 있는, 이게 역사가 뭐 아시겠지만 지금 한 10여 명 되는 TO가 빈 거는 과거에 무슨 역사적인 이유가 좀 있습니다. 여기 무슨 센터를 새로 만들었다가 그 센터가 기능을 다하면서 그 센터에 배정됐던 인원을 전부 다 연구원 정규 TO로 주는 과정에서 이렇게 됐는데, 그렇다고 해서 필요하지 않다는 얘기가 아니라 이거는 저희가 중기적으로 연구원의 비전하고 관계해서 좀 시간을 가지고 한 10여 명 이렇게 채우는 거지 이걸 당장 채운다는 목적으로 이걸 가지고 있는 게 아니기 때문에, 상황이 좀 그렇습니다. 
</p>
<p><b>○ 임우영 위원 </b> 그래서 그런 차원이라면, 아까도 오전에 존경하는 정인영 위원님께서도 말씀하셨습니다. 의정연구센터 같은 경우 센터장님하고 계약직인가요? 두 분의 직원만 있는데 이런 쪽에도 충원을 할 수 있으면 좀 하셔서…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저희가 오픈해서 사람을 찾고 있고 지금 아마 우리 홈페이지에 가면 수시채용에 열려있을 걸로 알고 있는데요. 그런데 사실 그렇게 우리가 찾는 사람을 못 골라 가지고 지금 그렇게 하고 있는 상황입니다.
</p>
<p><b>○ 임우영 위원 </b> 알겠습니다. 그다음에 지난 5월 달인가요, 한중해저터널 심포지엄 때 중국 측에서 오는 패널들에 문제가 있어 가지고 한 번 해명하고 하신 적이 있지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다.  
</p>
<p><b>○ 임우영 위원 </b> 그것 좀 잠깐 설명해 주시겠어요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 그 기관의 이름을 기억을 못하기 때문에 우리 부원장이 상세한 얘기를 압니다. 조금 설명을 해주세요. 
</p>
<p><b>○ 부원장 조응래 </b> 부원장 조응래입니다. 지난 5월 달에 한중해저터널 국제세미나 할 때 리홍이라고 해가지고 국가발전계획위원회 종합운수연구소 산하의 연구원이 왔었습니다. 그런데 그 소속을 종합운수연구소가 아니라 국가개혁위원회라고 그래 가지고 좀 논란이 있었습니다마는, 사실은 지금 우리나라 체계로 보면 그 소개는 원래 우리나라의 KDI 소속처럼 되어 있었는데 내용적으로 보면 또 다른 국가개혁위원회에 소속되어 있는 종합운수연구소라고 해서 한국교통연구원 같은 국책연구를 수행하는, 교통을 전담으로 하는 국책연구기관에서 온 연구원이었습니다. 
</p>
<p><b>○ 임우영 위원 </b> 그런데 중국 측에서는 그 종합운수연구소에도 있는 사람이 아니다…….
</p>
<p><b>○ 부원장 조응래 </b> 그렇지 않습니다. 
</p>
<p><b>○ 임우영 위원 </b> 그거는 확실합니까? 
</p>
<p><b>○ 부원장 조응래 </b> 네, 저희가…….
</p>
<p><b>○ 임우영 위원 </b> 제가 신문에서 봤기 때문에 지금 질의를 드리는데…….
</p>
<p><b>○ 부원장 조응래 </b> 그러니까 그게 경인일보에서 그 부분에 대해서 조금 오보가 난 내용이고, 그 내용에 대해서 인터넷상에서 그 사람이 그 소속이라는 것을 사실은 그전 날 다시 해명을 위해서 소속이 아니다라는 얘기를 저희한테 전화를 했기에 저희가 인터넷상에서 소속이라는 걸 보여줬는데도 불구하고 그다음 날 그런 언론보도가 나온 것입니다. 
</p>
<p><b>○ 임우영 위원 </b> 하여튼 이렇게 각종 세미나나 토론회가 많은데 주제발표자는 물론이거니와 패널들에 대해서 신중을 기해서 선정을 해야 되지 않나. 여기 신문에 나온 대로 처음에 발표가 오류에 의해서 이렇게 됐다. 그래서 여러분들 인쇄도 새로 하고 아마 그렇게 번거로움을 거치신 모양인데 그런 부분을 좀 더 신중하게 선정해야 되지 않나 하는 차원에서 제가 한번 확인을 했습니다. 
</p>
<p><b>○ 부원장 조응래 </b> 네, 유념하겠습니다. 
</p>
<p><b>○ 임우영 위원 </b> 시간 더 써도 됩니까? 
</p>
<p><b>○ 위원장 김대원 </b> 더 써도가 아니라 추가질의까지 해서 지금 임우영 위원님께서 총 보충질의까지 그냥 제대로 하고 있습니다. 
</p>
<p><b>○ 임우영 위원 </b> 알겠습니다. 또 시간이 되면 다시 하겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 다시 하실 것 같으면 계속하시든가.
</p>
<p style="padding-left:2.4em">    (웃   음)
</p>
<p style="padding-left:1.2em">  자, 분위기 좀 가볍게 하시고, 오늘 감사가 너무 진지하다 보니까 감사 때 없던 이런 의사진행발언까지 나왔는데, 환영합니다. 다음 전동석 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 전동석 위원 </b> 원장님, 장시간 동안 고생 많으십니다. 본 위원이 요구한 자료를 토대로 질의하도록 하겠습니다. 1권 303페이지에 있는 감사원과 도 자체 감사결과보고서 사본 요구한 게 있었는데요. 거기 봐주시겠습니까. 거기에 보면 2008년 4월 1일부터 11일까지 8일간 감사를 한 적이 있지요, 그렇죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 전동석 위원 </b> 그때 결국에는 조치결과가 재정상 조치 1건과 신분상 조치 10명으로 되어 있습니다. 이 사항에 대해서는 상당히 본 위원이 관심을 가지고 봤는데요. 몇 가지만 지적하도록 하겠습니다. 특히 7번에 자문회의 참석수당 지급 부적정에 대해서 본 위원이 보고는 상당히 놀라움을 금치 못하는데요. 이 사항이 도대체 어떻게 된 건지 간략히 설명해 주실 수 있겠습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이게 제가 기억하기로는 과거에 이런 자문회의에 참석하는 분들한테 수당을 지급할 때 여러 가지 복잡한 회계기준에 맞춰 가지고 서류를 많이 징구하고 이렇게 했던 모양인데 아마 중간에 그게 너무 번거롭고 그렇다 그래 가지고 그거를 좀 폐지를 했죠. 그래서 직접 통장으로 넣어주는 식으로 했는데 그게 지적받은 걸로 제가 알고 있습니다. 
</p>
<p><b>○ 전동석 위원 </b> 본 위원이 알기로는 회계규정이 그렇게 번거롭게 할 저거도 없었고 안 맞다고 해서 회계규정에 위배되게 제도를 자체적으로 고쳤다는 게 경기개발연구원에서 해야 될 일인지 모르겠어요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 규정에 안 맞게 했으면 안 되죠.
</p>
<p><b>○ 전동석 위원 </b> 아니, 위배됐다고 지금 감사에 지적을 받았지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리 부원장이 그때 직접 감사를 받았기 때문에 이 내용을 설명드리도록 해도 되겠습니까? 
</p>
<p><b>○ 전동석 위원 </b> 네, 부원장님 설명해 보시죠.
</p>
<p><b>○ 부원장 조응래 </b> 부원장 조응래입니다. 저희가 자문회의를 수행하게 되면 그동안에는 자문회의 개최건의를 해가지고 자문수당을 지급하고 그다음에 결과보고를 하고 그랬는데 그런 부분들이 조금 번거롭다는 의견들도 있고 그래 가지고 그 이후에는 자문회의 개최건의는 굳이 안 해도 개최결과보고만 하는 그런 행위들이 있었습니다. 그래서 그런 부분들이 향후에는 반드시 개최건의를 하고 그에 따라서 결과보고와 함께 자문에서 있었던 내용들을 명확하게 정리를 해서 수당을 지급하고 결과를 정리하라는 그런 취지의 감사처분 내용이었습니다. 
</p>
<p><b>○ 전동석 위원 </b> 그러니까 결국에는 수당을 지급하는데 많은 어떤 다른 조건들이 있으니까 회계규정에 위배되게 제도를 개선했다면서요. 여기 지적사항이 그렇지 않습니까. 어려우니까 경기개발연구원에서 회계제도, 이 지급방법을 수월히 하기 위해서 그것을 개선했다는 얘기 아닙니까? 
</p>
<p><b>○ 부원장 조응래 </b> 그때 당시에 자문회의뿐만 아니라 여비나 이런 것들이 개최건의를 하고서 또 불참자가 생기고 그러면 또 그거를 반납건의 하고 이런 일들이 있었습니다. 그래서 그러다 보니까 그런 행위들을 한 번에 정리하기 위해서 왔었던 분들의 영수증만 갖고서 건의하는 이런 형태로 바꾸자는 그런 내용이 있었는데 그런 부분들이 좀 문제였던 것 같습니다. 
</p>
<p><b>○ 전동석 위원 </b> 아무튼 우리 부원장님 말씀의 취지는 어떤지 충분히 알겠습니다마는 이런 사항들이 행정적으로 처리가 잘 안 됐다는 게 아무리 연구만 하는 부서라고 하더라도 좀 창피하지 않나 이런 생각이 들어서 했고요.
</p>
<p style="padding-left:1.2em">  이게 지금 보면 총 872명에게 1억 900만 원의 참석수당을 지급했어요. 물론 이게 전부 다 부당하게 지급했다고는 할 수 없지만 싸잡아서 아마 그렇게 넘어간 걸로 알고 있어요. 그렇죠?
</p>
<p><b>○ 부원장 조응래 </b> 이거는 총 건수 자체가 그렇다는 거고요. 그런 것들이 부당하게 지급됐다는 그런 내용은 아니었습니다. 
</p>
<p><b>○ 전동석 위원 </b> 아무튼 부적절하게 지급했다는 지적이 있지 않습니까? 그 지적이.
</p>
<p><b>○ 부원장 조응래 </b> 네, 몇 건에 있어서 그런 부분들이 있었다는 겁니다. 
</p>
<p><b>○ 전동석 위원 </b> 그걸 보면 “용역과제 수행에 따른 연구자문 및 원고 집필ㆍ보완의 사유로 연구원을 방문한 자문위원들에게 자문회의 개최절차 없이 자문회의 참석수당을 부적정하게 지급했다.” 이렇게 지적을 했어요. 그렇죠?  
</p>
<p><b>○ 부원장 조응래 </b> 그러니까 사전에 이거를 개최건의 하지 않고 이렇게 연구원에 와서 같이, 그동안에 외부에다가 원고료를 좀 지급하고서 그 원고 결과를 갖고서 협의하고 이런 부분들에 대해서 자문비를 지급했다는 건데 연구원 자체는 어쨌든 간에 원고료를 통해서 원고를 받긴 받았지만 그 부분에 대해서 수정하고 이런 것들을 갖고서 같이 아이디어를 나누고 이렇기 때문에 자문의 형태로 판단해서 자문비를 지급했는데 그게 부적정하다라는 내용이었습니다. 
</p>
<p><b>○ 전동석 위원 </b> 아무튼 감사원의 지적이 적당한 거였죠?
</p>
<p><b>○ 부원장 조응래 </b> 네. 그래서 저희가 그 부분에 대해서는 그 이후에 자문회의 개최를 할 때 개최건의 공문을 내부결재를 받도록 하고 개최가 끝나고 나면 결과보고를 반드시 하도록 바꿨습니다. 
</p>
<p><b>○ 전동석 위원 </b> 아무튼 이런 지적도 연구원의 어떤 오점이라면 오점일 수 있거든요. 4번 한번 보세요. 4번에 보면 수의계약 체결 부적정이 있습니다. 쭉 읽어보면 “500만 원 초과 용역ㆍ물품에 대하여는 정보처리장치에 의하여 견적서를 2인 이상에게 제출받은 후” 해가지고 쭉 설명을 해놓고 있습니다. 그런데 그게 안 맞으니까 이거는 계약에 관한 법률을 준용토록, 그러니까 “지방자치단체를 당사자로 하는 계약에 관한 법률을 준용토록 개정하고 동 예규에 의거 수의계약 업무를 수행하고 있음.” 이렇게 설명해 놨는데요. 이것도 또한 사실 이사회에서 바꿔 가지고 거기에 합당하도록 만든 거죠?
</p>
<p><b>○ 부원장 조응래 </b> 이 내용도 사실은 저희가 그동안에, 이거는 인쇄와 관련된 건이었습니다. 그래서 인쇄를 경기인쇄협동조합을 통해 가지고 단체계약을 했었는데 연구보고서를 내다 보면 연구책임 박사가 연구보고서의 어떤 질이라든지 편집 이런 것들 때문에, 이 품질을 높이기 위해서 서울에 있는 업체와 어쩔 수 없이 계약을 해야 되겠다라고 해서, 요청에 의해서 그렇게 계약이 된 세 가지 건이 되겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 이 부분에 대해서, 수의계약 체결이 부적정하다는 지적에 대해서 지적이 적절하다고 생각합니까? 
</p>
<p><b>○ 부원장 조응래 </b> 네. 그래서 지적에 대해서는 조치를 했습니다. 
</p>
<p><b>○ 전동석 위원 </b> 네, 알겠습니다. 원장님 오시죠.
</p>
<p style="padding-left:1.2em">  그다음 거 보면 용역과제 위탁기관 선정의 부적정이라는 게 있습니다. 거기 보면, 제가 잠깐 읽어드리겠습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 몇 페이지인가요?
</p>
<p><b>○ 전동석 위원 </b> 305페이지입니다. 305페이지 보면 주의조치를 받은 건데요. “협상에 의한 용역과제 제안서를 평가하기 위한 심사위원은 7인 내지 10인으로 하여 해당 분야 전문가, 대학교수 등으로 다양하게 구성하고” 이렇게 되어 있습니다. 쭉 설명이 되어 있는데요. 그런데 용역과제 제안서 심사평가를 하면서 심사위원을 박사 3명으로만 구성하고 원래 그 평가요건에 전혀 맞지 않게 해가지고 지적을 받았는데요. 결국에는 이런 심사를 하고 하니까, 나중에 세 번 아니라 네 번 심사를 계속 하더라도 스크린이 완전히 되지 않는 결과가 나오지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이거는 우선 규정에 안 맞게 한 것에 대해서는 저희가 입이 열 개라도 할 말은 없습니다. 그러나 꼭 이렇게 숫자가 줄어들었다고 대단하게 부실하게 했다고만 보기는 어렵지 않을까 생각도 듭니다. 제가 이걸 잘했다는 의미가 아니라……. 그래서 일단 이 사안에 대해서는 저희가 규정에 맞지 않게 했기 때문에 더 이상 항변할 얘기가 없습니다. 
</p>
<p><b>○ 전동석 위원 </b> 6년, 7년, 8년 이렇게, 만 3년은 아니지만 10건의 내용을 그전에 이런 도 감사를 받은 적이 없죠? 
</p>
<p style="padding-left:2.4em">    (좌승희 경기개발연구원장, 관계직원의 설명을 들으며)
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 격년제로 받는답니다.  
</p>
<p><b>○ 전동석 위원 </b> 그런데 이건 6년, 7년, 8년……. 2006년, 2007년을 합쳐서 2008년까지 감사를 받은 건데 격년제로 받았습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> ……. 
</p>
<p><b>○ 전동석 위원 </b> 2006년 1월부터 2008년 4년까지……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 3년에 한 번인 모양입니다. 
</p>
<p><b>○ 전동석 위원 </b> 3년에 한 번입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그리고 중간에 감사원 감사가 한 번 있고 이런 거 아닌가 싶습니다.  
</p>
<p><b>○ 전동석 위원 </b> 10건밖에 되지 않지만 제목을 보면 말이에요, 제목만 읽어보십시오. 읽어보시면 “정책연구과제 수행 부적정, 위탁연구과제 추진 부적정” 전부 다 부적정이고 “복지기금설치 부적정” 제목만 보면 경기개발연구원의 권위가 사라지는 듯한 그런 느낌을 받습니다. 아무튼 이런 지적에 대해서 나중에 사후조치를 해가지고, 전부 다 했다고 말씀은 돼 있지만 말이에요. 운영부서도 좀 더 확실하게 해야 되지 않겠나 이렇게 생각됩니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 물론입니다. 여기서 지적한 건 저희가 고칠 건 고치고 이렇게 했습니다마는 일부 건에 대해서는 제가 동의하지 않는 점도 있고 감수하는 사람들의 주관적인 판단이 있는 것도 전혀 없지는 않습니다. 
</p>
<p><b>○ 전동석 위원 </b> 동의하지 않는 부분을 한번 간단하게 말씀해 주십시오. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아까 한두 건이 있었는데요. 위촉연구원을 과다하게 썼다든가 이런 얘기는 전, 대단히 주관적인 판단이에요. 
</p>
<p><b>○ 전동석 위원 </b> 네? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 위촉연구원을 너무 많이 쓴다든가 이런 거는 제가 보기에는 그건 연구하는 사람이 판단할 문제고, 결과를 가지고 얘기를 해야지. 몇 가지 그런 건 있습니다마는, 그러나 규정을 만들어 놓고 그걸 충분히 지키지 않은 데 대해서는, 때때로 제가 좀 지나치게 일을 신속하게 처리하도록 압력을 넣어서 그런 문제가 생기는 경우도 있고 제 불찰도 있는 것이죠. 그리고……. 
</p>
<p><b>○ 전동석 위원 </b> 잘하신다고 생각합니다. 아무튼……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 성의를 가지고 최선을 다하다 보니까 무리가 온 게 아닌가 싶어서……. 
</p>
<p><b>○ 전동석 위원 </b> 지적사항은 지적이니까 외부 사람들이 보기에는 상당히 큰 문제로 삼을 수 있습니다. 그러니까 그냥 가벼이 생각하지 마시고 그걸 좀 반영시켰으면 좋겠고요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 49페이지 봐주시겠습니다. 49페이지 보면 연구과제 현황이 쭉 나오고, 본 위원이 정책반영 여부에 대해서 여쭤봤습니다. 기본연구과제 그다음에 정책연구과제 70건 그다음에 위탁ㆍ수탁, 기타 등등 반영되지 않은 게 없습니다, 반영되지 않은 게. 본 위원이 이렇게 한 건 사실은, 집에서 가만 생각해 보니까 반영되지 않을 수는 없겠다, 자의적인 생각으로 한다면 말이에요. 어떻게든 누가 읽어봐도 그건 반영된 것이고 한데. 이걸 전부 반영이라고 써놔 가지고 좀 의아한데 한번 설명해 보시겠습니까?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 도 쪽에서 받는 정책과제라든가 이런 거는 우선 사전에 정책목적을 가지고 하는 거니까요. 
</p>
<p><b>○ 전동석 위원 </b> 네. 정책과제는 그렇다고 하더라도. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 또 저희가 자체 발굴해서 하는 정책과제도 그걸 그냥 하지 않고 도에서 리드를 좀, 저희가 판단을 해서 하기 때문에 대부분의 정책과제는 반영됐다고 봐야 될 것이고. 기본과제의 경우는 사안에 따라서는 좀 다를 수 있습니다. 그리고 기본과제 자체가 성격상 바로 정책하고 연결되는 게 아니라 기본 기초연구에 해당되는 거기 때문에. 그렇지만 기본연구과제를 심의하는 과정에도 반드시 도의 과장님, 해당 과가 항상 참여해서 같이 하기 때문에 그런 과정에서 도하고 협의가 되고 좋은 정책안이 나오면 반영이 되고 그래서……. 또 연구하는 사람 입장에서는 다 반영이 됐다고 볼 소지도 있지 않을까 하는 생각이 들어서, 좀 과장된 점이 있다면 그 점은 좀 양해해 주시기 바랍니다. 
</p>
<p><b>○ 전동석 위원 </b> 그게 만약에 도에서 이러이러한 연구용역을 맡겼을 때에 뜻이 그런 게 아니다라고 결과가 반대적으로 나온다면 그게 반영이 안 되는 것이죠. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 도에서 무슨 방향을 꼭 정해서가 아니라 이 문제를 해달라 이렇게 해서 답을 우리한테 요구하기 때문에 답을 정해서 주는 경우가……. 
</p>
<p><b>○ 전동석 위원 </b> 모든 게 그렇습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 대부분이 그렇죠.  
</p>
<p><b>○ 전동석 위원 </b> 그러면 결국에는……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그리고 경우에 따라서, 사람 사는 세상이기 때문에 사전에 답의 방향을 협의할 수 있고 합의할 수도 있죠. 그러나 대부분의 경우에 그렇게 안 합니다. 
</p>
<p><b>○ 전동석 위원 </b> 그러면 결국에는 경기개발연구원은 목적에 맞는, 일반 사람들이 지적하는 도의 어떤 일을 반영시키고 또한 관료의 방패막 역할을 충실히 했다 이렇게밖에 안 되는 거지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇게 생각하시면 안 되죠. 제가 말씀드린 얘기는 정책과제를 받을 때 방향이나 결론에 대해서 사전에 뭐 이렇게 하는 게 아니고 어떤 문제의 답을 찾아달라고 부탁을 하기 때문에……. 
</p>
<p><b>○ 전동석 위원 </b> 그렇죠. 문제의 답을 한다고 하더라도 결과가 완전히, 하나도 반대적인 발언이 안 나왔다면 그것 좀 이상한 거 아닙니까? 반영은 전부 다 시켰어요. 그러면 요구하는 답을 충실히 내줬을 따름이지 연구했다고 볼 수 없지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 아까 말씀드린 대로 약간의 과대평가도 있고, 각자 자기 한 일에 있어서. 저는 그건 없지 않으리라고 봅니다. 그러나 그런 거보다는 아까 지적한 대로 도하고 항상 정책과제를 협의하기 때문에 이런 현상이 생기지 않을까 하는 생각이 들고, 전 위원님께서 생각하신 대로 그런 측면이 있을 수도 있겠죠. 그 점에 대해서는 저희가 염두에 두고 연구가 독자적으로 될 수 있도록 노력하는 수밖에 없지 않을까 싶습니다.  
</p>
<p><b>○ 전동석 위원 </b> 본 위원도 경기도 사람이고 경기도 의원이기 때문에 어디 가면 “아, 우리도 경기도 정책을 하는 데 있어서 60명 이상의 박사들이 앉아서 항상 연구하고 있다. 그리고 가장 좋은 자료들을 나타내고 있다.”고 자랑하고 있습니다. 자랑하고 있는데, 아무튼 그래도 냉정하게 잘 성찰할 수 있는 그런 것도 필요하다 이런 생각이 들어서 말씀드리는 거고. 
</p>
<p style="padding-left:1.2em">  좌 원장님 말씀하신 답변에 대해서 본 위원이 이해하지 못하는 건 아닙니다. 그러니까 그거에 대해서 좀 더, 전부 반영이라고 써놨길래 어떻게 이럴 수 있나 이런 생각이 들어서, 그러면 본 위원이 오전에 말씀드렸던 대로 그런 관료주의에 편승한 얘기밖에 되지 않지 않느냐. 여기 있는 사람들은 도의 어떤 정책에 다 따라야 되는 사람이고 아니면 나가야 되고 이런 정도로 되지 않겠습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 참작하겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 아무튼 그런 생각이 들고요. 페이지를 보지 않으셔도 되는데요. 2006년, 2007년, 2008년도에 보면 실제로 연구직, 관리직이 변동이 거의 없어요. 그렇죠? 2명, 1명 이렇게 돼 있는데요. 이건 본 위원 생각에는 연구원이 충실히 복지도 잘 되고 있고 대우도 충분하고, 그렇다라고 해석이 되는데 어떻게 생각하십니까? 움직임이 없다는 것은 그렇다고……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그러나 금년에 연구위원급에서는 조금씩 변동이 있죠. 두 사람, 세 사람 뽑으면 두 사람 정도 나가고 이런 변동이 있는데……. 
</p>
<p><b>○ 전동석 위원 </b> 1년에 한두 사람 정도인데요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 그런데 그걸 가지고 다른 위원님들은 다르게 해석할 수도 있고 그래서. 이것도 또 같은 문제를 서로 다르게 해석하는 그런 문제가 아닌가 싶은데 좌우간 저는 생각보다는 연구원이 상당히 안정적인 연구원입니다. 
</p>
<p><b>○ 전동석 위원 </b> 아직도 한 10명 정도가 정원에 모자라죠? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 
</p>
<p><b>○ 전동석 위원 </b> 그건 충실히 하셔 가지고, 과중하다고 자꾸 하시는데 좋은 연구결과를 발표하시면 좋겠고요. 
</p>
<p style="padding-left:1.2em">  짧은 거 하나만 더 말씀드리겠습니다. 북한이 상당히 변화가 많이 되고 있습니다. 경기도에서는 대북지원정책뿐만 아니고 북한의 변화에 대비해야 된다, 아니면 정부정책의 일이기 때문에 우리는 좀 더 뒷전으로 나앉아야 되지 않느냐 이런 얘기도 많이 있습니다마는 경기개발연구원 쪽에서도 북한을 주시해야 된다고 생각되는데 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 그게 저희가 동북아 북한연구팀을 가지고 있는 이유고요. 그게 그러다 보니까 오늘 같은 보고서도 나오고 그런 게 아니겠습니까?  
</p>
<p><b>○ 전동석 위원 </b> 지금 김동성 박사님이나 최 박사님이나 오관치 박사님이나 다 뵈니까 세 분이서 거의 다 하시고, 연구원이 밑에 더 있는지는 모르겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 초빙연구원이 다 있습니다. 
</p>
<p><b>○ 전동석 위원 </b> 있을 수도 있겠는데 사실상 그런 Report를 내는 정도 가지고 북한을 알리기에는 부족하거든요. 그분들이 북한은 가끔 가십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저는 못 갔지만 최 박사랑 김 박사는 저보다 훨씬 많이 갔습니다. 
</p>
<p><b>○ 전동석 위원 </b> 어떤 루트를 통해서 가는지요?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 위원님들 가실 때, 도에서 갈 때 항상 저희가 자문역으로 가죠. 항상 갑니다. 
</p>
<p><b>○ 전동석 위원 </b> 아무튼 본 위원 생각에는 말이에요. 북한에 대한 신경을 쓰지 않으면 낭패를 당할 수 있다 이런 생각이 들거든요. 그 역할을 경기개발연구원이 담당해 줬으면 좋겠다는 생각이 들어서, 세 분 박사님들만 가지고 실질적인 일을 할 수 없다 이런 생각이 듭니다. 물론 팀별로 나눠서 도시연구부, 어디 연구부 쭉 나눠져 있는데 북한에 대한 신경을 좀 더 쓰기 위해서는 북한 쪽에 인력을 좀 더 배치시켰으면 하는 게 본 위원의 생각입니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 잘 알겠습니다. 그런데 저희가 북한포럼이 있고요. 또 외부 전문가들 해서 수시로 듣고 해서, 좌우간 최선을 다해서 참신한 아이디어를 들여오도록 애를 쓰고 있습니다마는 말씀하신 대로 인력이 필요하면 적극적으로 뽑아서 하겠고, 지금 이미 한 사람이 우리 웹사이트에는 오프닝으로 나가서 열려 있습니다. 동북아문제라든가 남북문제를 하는 박사가.  
</p>
<p><b>○ 전동석 위원 </b> 마무리하겠습니다. 본 위원이 지금 질의한 것 중에, 사실 회계규정에 위반될 정도로 제도를 자체적으로 개선안을 마련해 가지고 자문수당을 지급했다는 것은 어떤 경우든 본 위원이 이해하기 어렵다는 생각이 들고요. 또한 경기도를 대표하는 연구원의 연구가 객관성과 공정성을 가지고 연구되어야 되고 또 그렇게 될 때에 연구결과에 대한 권위가 선다고 생각됩니다. 용역과제 제안서 심사평가를 하면서 또 평가기준에 맞지 않게 한다는 것은 있을 수 없는 일이라고 생각됩니다. 물론 그게 감사기관의 지적을 당해서 한 일이지만 경기도에는 경기개발연구원이 있다라는 얘기가 아주 돌아다닐 정도로 열심히 일해 주시면 고맙겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 질의를 마칩니다.  
</p>
<p><b>○ 위원장 김대원 </b> 전동석 위원님 수고하셨습니다. 더 질의하실 위원님 신청하십시오. 정문식 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 정문식 위원 </b> 고양 출신 정문식 위원입니다. 제가 9월 3일자 도정질문 때 경기도의 민자도로 정책과 관련돼서 질문한 사항이 있었습니다. 그 당시에 도지사 답변사항이나 그다음에 실무부서 의견 중에 서수원-의왕 고속화도로가 민자투자사업으로 시행이 되게 됐는데 여기에 대해서 용역을, 도의 도정연구과제로 해서 연구원에서 수행해서 의견을 내셨습니다. 그래서 이 의견에 따라서 민간투자사업이 진행됐다고 제가 알고 있는데 이 사실 알고 계시죠? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 제가 담당하고 있는 박사를 부를까요?  
</p>
<p><b>○ 정문식 위원 </b> 네. 
</p>
<p><b>○ 교통정책연구부연구위원 류시균 </b> 교통정책연구부에 류시균입니다. 
</p>
<p><b>○ 정문식 위원 </b> 류시균 박사님께서 서수원-의왕 고속화도로 민간투자사업 시행방안 수립에 관한 연구를 수행하셔 가지고 보고하신 적 있으시죠? 
</p>
<p><b>○ 교통정책연구부연구위원 류시균 </b> 네. 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 이 내용 중에 보면 타 사업방식에 비해서 최단기간으로 지방도 309호선의 확포장사업을 완료할 수 있다는 점에서 경기도가 선택할 수 있는 유일한 대안이라고 민간투자사업에 대해서 얘기하셨습니다. 맞습니까? 
</p>
<p><b>○ 교통정책연구부연구위원 류시균 </b> 네, 맞습니다. 
</p>
<p><b>○ 정문식 위원 </b> 제가 9월 3일자 도정질문 때 비교를 했었는데요. 지금 경기도에서 건설했던 과천-의왕 도로의 회수율이 민자도로보다 2배 이상 회수기간이 짧았습니다. 알고 계시죠? 
</p>
<p><b>○ 교통정책연구부연구위원 류시균 </b> 네, 알고 있습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그래서 그 당시 제시했던 것 중에 하나가 경기도가 자체재원으로 도로를 건설하고 유료도로를 운영하는 방안이 가장 도민들한테 혜택이 있지 않느냐는 제안이었고요. 두 번째 제안은 경기도시공사가 경기도시공사의 재원으로서 이것을 건설하였을 때 도민들이 가장 단기간 동안 비용을 분담하지 않느냐라는 지적이었습니다. 그런데 그 부분에 대해서 우리 류 박사께서는 어떤 견해를 갖고 계십니까? 
</p>
<p><b>○ 교통정책연구부연구위원 류시균 </b> 지금 재정을 가지고 하는 방법 중에, 원래 의왕-과천 고속도로를 확포장하는 사업, 그러니까 학의JCT에서 과천 구간을 유료도로사업으로 확포장을 하고 있는데 그 전에, 유료도로사업으로 하기 전에는 사실 재정사업으로 확장을 하고 있었습니다. 재정사업으로 확장을 하면서 사실 재원조달에 상당히 어려움을 겪고 있었고요. 그다음에 지금 민간투자사업 방식으로 하는 방안하고 유료도로사업으로 하는 방안 두 가지가 있는데 유료도로사업으로 하기 위해서 일단은 기채를 발행해야 되는 걸로 알고 있습니다. 어디선가 자금을 차입해 와서 그 자금을 가지고 유료도로 특별회계에 편입을 시켜서 사업을 해야 되는데 그런 일련의 프로세스(process)에서 도의 의사결정이 상당히, 어떻게 보면 어렵다라는 점을 느꼈고요. 그러니까 재원조달하는 데서 상당히 많은 시간이 걸린다라는 게 하나 있고. 
</p>
<p style="padding-left:1.2em">  또 하나는 민간투자사업으로 진행을 하는 의사결정 과정에서 적격성 조사라는 것을 하게 됩니다. 적격성 조사는 저희 연구원에서만 하는 것이 아니고 원래는 KDI의 공공투자관리센터에서 적격성 조사를 하는데 그 적격성 조사의 분석결과는 1차적으로는 지금의 수원영업소가 아니고 그걸 아래에 부곡IC하고 월암IC, 그러니까 월암영업소로 옮기는 방안을 전제로 해서 적격성 조사를 했을 때는 적격성이라는, 그러니까 민간투자사업의 타당성은 얻지 못했습니다. 다만 그 당시에 도가 유료도로사업으로 하는 데 대한 재원조달의 부담 때문에 민간투자사업으로 하는 방안을 일단은 방향에 대해서 검토를 필요로 했고요. 거기에 대해서 제가 정책과제로 하면서 다시 재적격성 조사를 했습니다. 그 재적격성 조사에서는 현재의 수원영업소를 존치하는 방안을 가지고 적격성 조사를 했을 때 경기도가 자금을 차입해서 하는 방안보다는 일단은 민자사업으로 하는 방안이 보다 재정을 효율적으로 운용할 수 있고 두 번째는 일단 민간투자사업으로 성사만 되면 자본조달에 대해 전혀 문제가 없기 때문에 그런 차원에서 상당히 사업이 신속하게 진행될 수 있다라는 차원에서 장점을 거론했습니다. 
</p>
<p><b>○ 정문식 위원 </b> 지금 답변 중에 있었듯이 한국개발연구원 공공투자관리센터에서는 IC의 위치 때문에 부적격 받았었죠? 
</p>
<p><b>○ 교통정책연구부연구위원 류시균 </b> 네, 맞습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그다음에 이번 연구과제 때는 IC의 위치를 변경하셨죠? 
</p>
<p><b>○ 교통정책연구부연구위원 류시균 </b> 네, 맞습니다. 
</p>
<p><b>○ 정문식 위원 </b> 그리고 지금 답변 중에도 보시면 도에서 재원조달의 의사결정 어려움 때문에 이런 결과를 도출하신 것처럼 답변하셨습니다. 처음 답변은 민간투자사업이 가장 학자적 소신에 의한 발언이라고 하시고 두 번째 답변에서 보시면 도에서 재원조달에 있어서의 의사결정을 십분 고려하셔서 그 부분이 반영된 듯한 답변이세요. 정확하게……. 
</p>
<p><b>○ 교통정책연구부연구위원 류시균 </b> 적격성 조사 결과 자체는……. 
</p>
