<p><b>○ 정문식 위원 </b> 저는 연구원에 계신 연구자들의 학문적 소신은 언제나 존중합니다. 당연히 존중받아야 마땅한 가치가 있는 일이라고 생각합니다. 그런데 지금처럼 이렇게, 제가 조금 전에 예를 하나 들어드린 건데요. 도정과제라든가 도정연구과제로 받으신 사항 중에서 이렇게 확정적인 사항들에 대해서 제안하신 경우들이 꽤 있습니다. 그리고 이걸 근거로 해서 도의 실무 공직자들이 집행하면서 근거로 들고 있습니다. 이런 부분들은 도민의 직접적인 생활과 연결돼 있는 부분입니다. 어떻게 보면, 우리 류시균 박사가 많은 고민을 했겠죠. 류시균 박사도 저와 같은 고민을 해서 민간투자 방식이 지금 도의 현 상황에서는 어려움을 극복할 수 있는 방안이라고 생각하셔서 이런 표현을 쓰셨을 수도 있고 여러 가지 경우가 있겠죠. 그거는 우리가 앞으로도 더 고민해 볼 부분이라 생각을 하는데. 그런데 이런 도정연구과제라든가 이런 부분들이 전부 다, 연구원의 결과가 정책에 반영된 걸로 다 돼 있습니다. 이런 데 있어서 오히려 저희가 지켜드리고 싶은 학문적 소신들이 그런 도정을 집행하는 공직자들과의 의견조율 과정에서 변화가 있거나 하지는 않으시냐는 지적입니다. 어차피 연구원도……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 전혀 없다고 할 수가 없겠지만 박사들은 박사들 나름대로 그렇지 않고 자기 소신을 지키려고 많은 애를 쓰고 있다고 생각합니다. 그래서 보기에 따라서는 그런 면도 있지만 특히 기본연구과제라든가 이런 건 자기 소신대로 하는 것이고 정책과제 중에 도가 요청한 과제를 하는 과정에서 협의가 있고 하기 때문에 어느 정도 서로 교감이 있을 수는 있지만 박사들이 그래도 마지노선이랄까 하는 걸 지키기 위해서 애를 쓰고 있다고 믿고 싶습니다. 
</p>
<p><b>○ 정문식 위원 </b> 믿고 싶으신 게 아니고요. 그렇게 되게끔 원장님이 만드셔야 되고요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아, 물론…….
</p>
<p><b>○ 정문식 위원 </b> 제가 아까도 오후 질의 때 첫 번째 말씀드렸던 사항이 그런 겁니다. 지금 보면 정책을 결정하는 결정권자나 의회에서 받아보고 있는 건 최종 결과물을 받아보고 있습니다. 도지사도 이런 결과를 요약한 요약본을 가지고, 갖고 온 보고서를 받고서 ‘그래, 그럼 민간투자에 내가 사인하자.’ 하고 사인한 겁니다. “이거 왜 하셨습니까?” 하니까 “공무원들 의견도 그렇고 연구원에서도 그게 맞대.”, “이렇게 가야 될 것 같습니다.”라고 양해를 구합니다. 그런데 저는 사실 양해가 안 됩니다. 제가 너무 무지해서 그런지 모르겠는데. 그런 부분들에 있어서 이런 것들이 우리 연구원이 일정 부분은 도의 공직자가 갖고 있는 생각과 다른 부분들 또 다른 결과들을 과감히 내셔야 되고 또 내신 결과물에 대해서 책임을 지셔야 됩니다. 책임지신다는 게 다른 거 아닙니다. 어떠한 경우에도 그 주장에 대한 근거와 이해를 구할 수 있는 자세면 전 된다고 생각하는 겁니다. 앞으로 그렇게 해주시기 바라고요. 오후에 제안드렸던 연구원의 직제에 대한 고민도……. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 도와의 관계……. 
</p>
<p><b>○ 정문식 위원 </b> 네. 도와의 관계에 대한 고민도 보다 심도 있게 고민하셔서 그 안에 대해서도 고민하신 결과물을 나중에 내주시기 바라겠습니다. 이상입니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 정문식 위원님 수고하셨습니다. 더 질의하실 위원님 계십니까? 
</p>
<p><b>○ 임우영 위원 </b> 확인만 하겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 아니, 계속 하십시오, 막. 
</p>
<p><b>○ 임우영 위원 </b> 위원장님이 자꾸만 감사위원들을 독촉을 하면 자유로운 감사가……. 
</p>
<p><b>○ 위원장 김대원 </b> 아니, 시간을 왜 정했습니까, 시간을? 
</p>
<p><b>○ 임우영 위원 </b> 그래도 확인할 부분이 있으면 확인 좀 해야죠. 
</p>
<p><b>○ 위원장 김대원 </b> 아니, 서면확인도 있고 평상시 자기 질의시간에 확인할 시간 충분히 있지 않습니까? 시간을 왜 정해요, 그럼?
</p>
<p><b>○ 임우영 위원 </b> 나중에 말씀을 드리겠습니다.
</p>
<p style="padding-left:1.2em">  확인을 한 가지 하겠습니다. 지금 민선4기 들어와서 벌써 네 번째 조직개편안이 의회에 제출되어 있습니다. 혹시 이와 관련해서 자문이나 이런 게…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 도 조직개편이요?
</p>
<p><b>○ 임우영 위원 </b> 네, 이번에 조직개편안과 관련돼 가지고.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저는 개인적으로 자문한 적이 없는데…….
</p>
<p style="padding-left:2.4em">    (관계직원들을 바라보며)
</p>
<p style="padding-left:1.2em">  혹시 행정자치부나 어디 부서에서 한 게 있습니까? 
</p>
<p><b>○ 임우영 위원 </b> 자치행정연구부서에서 혹시 한 거 없습니까? 
</p>
<p><b>○ 자치행정연구부장 이용환 </b> 자치행정연구부장 이용환입니다. 자문은 없었던 걸로 알고 있습니다. 다만 도 조직에 관련돼서 연구를 현재 진행 중인 사항은 하나 있습니다. 그 연구결과가 아직, 연구종료가 되지 않은 사항이 있습니다.  
</p>
<p><b>○ 임우영 위원 </b> 이번 개편안과 관련된 겁니까? 
</p>
<p><b>○ 자치행정연구부장 이용환 </b> 직접적인 관련이 있을 거라는 생각은 되지 않는데요. 어차피 조직 관련된 연구기 때문에 간접적인 연관이 있지 않을까 생각합니다. 저도 뉴스에서 봤는데, 또 담당하는 박사님한테 한번 여쭤봤는데 직접적인 연관성은 없었지만 간접적인 연관은 있을 수 있다는 그런 내용입니다.
</p>
<p><b>○ 임우영 위원 </b> 알겠습니다. 그러면 그거를, 기본적인 연구목적이나 목차 정도는 정해졌을 것 같은데 그 자료를 저한테 서면으로 주시기 바랍니다.
</p>
<p><b>○ 자치행정연구부장 이용환 </b> 네, 그렇게 하도록 하겠습니다.  
</p>
<p><b>○ 임우영 위원 </b> 알겠습니다. 한 가지만 더 하겠습니다.
</p>
<p style="padding-left:1.2em">  선진화위원회라고 있습니다. 그렇죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 임우영 위원 </b> 민선4기 들어와서 설치가 된 거죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다.  
</p>
<p><b>○ 임우영 위원 </b> 여기 보면 분과가 5개 되어 있고 자문단도 있고 쭉 있습니다. 여기 보면 도정현안에 대한 원활한 추진에 기여를 하고 각종 도정 홍보를 위해서 이렇게 쭉 되어 있는데 혹시 위원회에, 제가 위원회를 쭉 보니까 외부전문가들이 주로 많이 들어가 계시더라고요. 예를 들어서 도의회에 각 상임위원회에서 나름대로 전문적인 지식을 가지고 있는 위원들도 참여를 한번 하면 오히려 더 효과적이지 않을까 하는 개인적인 생각이 들어서 그런 부분도 한번 검토를 해주십사 하는 부탁의 말씀을 드리려고 말씀을 드렸습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 알겠습니다. 
</p>
<p><b>○ 임우영 위원 </b> 너무 많이 말을 해서 죄송합니다. 이상 마치겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 괜히 분위기 이상하게 만들지 마시고, 임우영 위원님 수고하셨습니다. 더 질의하실 위원님 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  위원님 여러분! 수고하셨습니다. 저도 몇 가지만 위원장으로서 확인하고 넘어가겠습니다. 8월 달에 부설 경기과학기술센터가 설립이 됐습니다. 예산이 얼마인지 아시죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 178억…….
</p>
<p><b>○ 위원장 김대원 </b> 176억 5,500만 원에 하셨는데 지금 우리 경기개발연구원 올 일반회계 예산이 얼마인지 아십니까, 총예산이? 제가 계속 얘기를 할게요. 168억입니다. 그런데 176억 5,500만 원짜리 부설 기술센터를, 우리 중기지방재정계획에도 없었고 그랬던 사항이 8월 달에 이렇게 만들어졌습니다. 만든 설립배경에 대해서 알고 계십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 다른 특별한 배경은 제가 모르겠고요. 
</p>
<p><b>○ 위원장 김대원 </b> 그러면 설립목적에 대해서는 아시죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 알고 있습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 그 목적을 제가 읽어드리겠습니다. “경기도가 위임하는 연구개발사업의 기획, 관리, 평가 그리고 경기도 과학기술정책연구, 경기도 연구개발사업 및 정책의 성과분석과 평가” 입니다. 그래서 지금까지 저희들이 보기로는 경기개발연구원보다 예산도 더 많이 투입하고 사업목적도 연구개발사업의 기획, 관리와 평가까지 이 부설기관에서 합니다. 그러면 쉽게 말하면 경기개발연구원의 감시기구와 기획기구가 됩니다. 옥상옥이 하나 만들어지는 격이 됩니다. 이 목적대로 운영이 된다면. 또 심지어는 경기도의 연구개발사업 또 정책의 성과분석과 평가까지 이 기관에서 하게 됩니다. 그래서 부설기관이 경기개발연구원의 평가기관이 됩니까, 기획ㆍ평가 기관이 됩니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 경기개발연구원의 출연금이 R&D 자금으로 간주할 수 있느냐, 없느냐에 대해서 약간의 다른 생각도 있을 수 있다고 생각이 됩니다마는 최근에 하는 것은 저희 연구원에 출연하는 것도 R&D 사업 중의 하나로 들어가는 걸로 이해하고 있거든요. 그래서 그런 면에서는 이 센터가 우리 연구원에 대한 자원배분 문제에 대해서 의견을 낼 수도 있겠다 하는 생각이 듭니다. 
</p>
<p><b>○ 위원장 김대원 </b> 아니요. 지금 설립목적이 그렇게 되어 있습니다. 그리고 내년도 예산 확보는 어떻게 하실 계획입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 200억, 우리 센터 소장이 나와 있는데 답변을 좀…….
</p>
<p><b>○ 위원장 김대원 </b> 그러니까 말만 부설기관이지 별도기관 아닙니까, 별도기관. 원장님이 내년도 예산 계획도 모르시는데 어떻게 부설기관입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 한 200억 정도 간 걸로 알고 있고, 아까 예산 보고는 안 드렸습니다마는, 215억이 배정됐다고 지금…….
</p>
<p><b>○ 위원장 김대원 </b> 215억이 경기개발연구원 예산으로 포함된 겁니까? 안 그러면 별도 예산으로, 배꼽 다른 데 붙여서 나온 겁니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 예산이 아니라 특별회계로 지금 하는 걸로…….
</p>
<p><b>○ 위원장 김대원 </b> 그 예산편성이 연구원에 편성이 됩니까, 아니면 다른 데로 편성이 됩니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 연구원에 특별회계로 편성되는 걸로 알고 있습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 그건 나중에 자료로 제출해 주시고. 
</p>
<p style="padding-left:1.2em">  오늘 업무보고서 6페이지에 경기과학기술센터 수입ㆍ지출 내역이 이렇게 기재가 되었습니다. 그런데 176억 5,500만 원을 사업수입으로 잡았는데 8월 달에 갑자기 만들어진 부설 기술센터가 사업을 해서 176억 5,500만 원을 벌어서 여기 기재를 한 겁니까? 도에서 이렇게 옆구리로 받아 가면 사업수입입니까, 이게? 이게 출연금이지 어떻게 사업수입입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이걸 가지고 사업을 한다는 관점에서…….
</p>
<p><b>○ 위원장 김대원 </b> 지출에서는 사업비가 맞지요, 당연하게. 그렇지만 받아갈 때 돈도 사업비입니까? 도에서 받아간 돈이 사업비입니까? 사업해서 받아간 거예요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 사업비로 본다고 지금…….
</p>
<p><b>○ 위원장 김대원 </b> 아니, 지출항목에서는 사업이 맞지요. 경기도에서 받아간 돈이 사업비냐고?
</p>
<p><b>○ 임우영 위원 </b> 도의 업무를 위탁해서 하는…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 도의 업무를 위탁받은 겁니다, 사실은. 그런데 그걸 어떻게 이름을 명명해야 되는지에 대해서는 제가…….
</p>
<p><b>○ 위원장 김대원 </b> 아니, 수입에서, 총수입에서 사업비는 아니지 않습니까? 출연금이지.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 도의 업무를 위탁받아서 하는 위탁사업수입금으로 이렇게 보는 모양입니다. 위탁사업수입금으로 보고 내년에는 출연금으로 하는데 그걸 특별회계로 해가지고 회계하는 걸로…….
</p>
<p><b>○ 위원장 김대원 </b> 알겠습니다. 본 위원이 지금 인터넷상으로 확인을 해본 결과 제가 모두에 말씀드린 것과 같이 지금 현재 설립목적과 주요 업무내용을 보면 경기개발연구원에 대한 이렇게 옥상옥격인 개념이 상당히 많습니다. 현재 인력채용도 연구원에서 인력채용을 했습니까, 안 그러면 부설기관에서 직접 하셨습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 부설기관에서 하지만 제가 최종적인 결재와 감독을 했습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 거기에 지금 연구원 직함을 알고 있습니까, 직책을? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 연구원 거기에…….
</p>
<p><b>○ 위원장 김대원 </b> 네. 부설 기술센터의 그 명칭을 알고 계시냐고요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리 연구원하고 좀 다른 직책을 가지고 있는 것으로 알고 있습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 제가 불러드리겠습니다. 기획평가실장, 뭐를 의미하는가 잘 보십시오. “정책연구실장, 관리지원실장, 기획평가팀장” 이렇게 되어 있습니다. 그렇게 되어 있죠? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 
</p>
<p><b>○ 위원장 김대원 </b> 그거 하는 목적이 글자 그대로 말하면 기획평가, 정책연구, 관리지원 또 기획평가팀장, 이거 보면 목적하고 똑같은 거 아닙니까? 경기도가 위임하는 연구개발사업의 기획, 관리, 평가, 경기도 연구개발사업 및 정책의 성과 분석ㆍ평가 및 시행, 그러면 결과적으로 연구를 이렇게 위에서 옥상옥으로 지켜보는 그런 기관 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇게 해석할 수가 있을는지 모르겠는데…….
</p>
<p><b>○ 위원장 김대원 </b> 지금 분명히 말씀드리겠습니다. 이건 소관 상임위원회인 저희 위원회에서도 부설기관에 대해서 논의가 없었고 예산부분에 대해서도 충분한 설명이 없었습니다. 그러니까 이 부분은 원장님 이하 부설 소장님께서 자료를 만들어서 우리 위원회에 충분히 설명이 될 수 있도록 부탁을 드립니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 잘 알겠습니다. 미리 제가 챙기지 못한 걸 죄송하게 생각합니다. 
</p>
<p><b>○ 위원장 김대원 </b> 내년도 예산이 215억이라는 부분이 지금 이 자리에서 바로 나온 얘기입니다. 내년 경기개발연구원 예산 요구액이 얼마인지 아십니까? 
</p>
<p style="padding-left:2.4em">    (좌승희 경기개발연구원장, 관계직원에게 확인 중) 
</p>
<p style="padding-left:1.2em">  아니, 내년 예산안이 지금 의회에 상정됐는데 원장님께서 내년도 살림살이가 얼마인지도 모르시면…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 136억입니다.
</p>
<p><b>○ 위원장 김대원 </b> 그러니까 배보다 배꼽이 훨씬 더 큰 부설기관을 두고 있어서 엄청 힘드시겠습니다. 그 배꼽 달고 다니려면. 
</p>
<p style="padding-left:2.4em">    (웃   음)
</p>
<p style="padding-left:1.2em">  하여간 독립시켜 주시든가 사업목적이 다르면 분리를 시키시든가 연구를 좀 해보십시오. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 잘 알겠습니다. 
</p>
<p><b>○ 위원장 김대원 </b> 더 이상 질의하실 위원님이 안 계시므로 이상으로 경기개발연구원에 대한 질의와 답변을 모두 마치겠습니다. 원장님, 앉으시죠.
</p>
<p style="padding-left:1.2em">  장시간 열의를 갖고 감사에 임해 주신 위원 여러분과 행정사무감사 자료준비와 위원님들의 질의에 성실히 답변해 주신 좌승희 원장님을 비롯한 임직원 여러분께 감사드립니다. 오늘 여러 위원님들께서 감사 시에 지적해 주신 사항은 도민의 뜻이니 만큼 이를 겸허히 받아들이셔서 연구원 업무에 적극 반영하여 경기도의 싱크탱크인 경기개발연구원이 한 단계 도약될 수 있도록 최선의 노력을 다해 주시기를 바랍니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 연구원 임직원 여러분! 수고하셨습니다. 그러면 이상으로 경기개발연구원에 대한 2008년도 행정사무감사를 마치겠습니다. 
</p>
<p class=''ar''>(17시20분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원
</b></p>
<p class=''aMan''>김대원김기수전동석고영인김영환송찬규이경천이승철임우영정문식</p>
<p class=''aMan''>정인영</p>
<p><b>○ 출석전문위원 
</b></p>
<p class=''em15''>   오태철
</p>
<p><b>○ 피감사기관 참석자
</b></p>
<p><p class=''em15''>경기개발연구원장 좌승희부원장 조응래</p>
<p><p class=''em15''>기획조정실장 겸 통일ㆍ동북아연구센터장 김동성</p>
<p><p class=''em15''>사무처장 엄정수자치행정연구부장 이용환</p>
