            <div','경기도의회',false,'{"legacy_id": "audit-2332", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2332"}'::jsonb,'2008-11-13'::date,'2008-11-13'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-2332');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2007.11.16. 금요일] 경기개발연구원 — 기획위원회 2007년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제7대 경기도의회 기획위원회</b> · 2007년도 행정사무감사(2007. 11. 13. ~ 2007. 11. 22.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2390" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2007년도 행정사무감사
</p>
<h4>기획위원회 회의록 
</h4>제 3 호
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 2007년 11월 16일(금)
</p>
<p>장  소 : 경개개발연구원회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시13분 감사개시)
</p>
<p><b>○ 위원장 김영복 </b> 좌석을 정돈하여 주시기 바랍니다.  지금부터 지방자치법 제41조, 동법시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기개발연구원에 대한 2007년도 행정사무감사를 시작하겠습니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 좌승희 경기개발연구원장을 비롯한 임직원 여러분!  안녕하십니까?  기획위원회 감사위원장 김영복입니다.  지역구 활동과 의정활동을 병행하며 수행하시느라 위원님들 고생이 많으십니다.  오늘은 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다.  여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2008년도 예산안 심사자료 및 정보 획득을 통해 이를 도정 시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 할 수 있습니다.  따라서 경기도의 싱크탱크인 경기개발연구원의 운영 실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다.  아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다.  감사를 받는 원장 및 부장, 센터장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하기 위해서는 먼저 선서를 하셔야 합니다.
</p>
<p style="padding-left:1.2em">  증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2007년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김 없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다.  만약 증인이 허위증언을 한 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다.  또한 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만원 이하의 과태료가 부과될 수 있음을 알려드립니다.
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인 출석여부를 확인하겠습니다.  피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다.  원장 나왔습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 부원장 나왔습니까?
</p>
<p><b>○ 부원장 신원득 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 기획조정실장 나왔습니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 사무처장 나왔습니까?
</p>
<p><b>○ 사무처장 이정열 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 자치행정연구부장 나왔습니까?
</p>
<p><b>○ 자치행정연구부장 이용환 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 도시지역계획연구부장 나왔습니까?
</p>
<p><b>○ 도시지역계획연구부장 이외희 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 교통정책연구부장 나왔습니까?
</p>
<p><b>○ 교통정책연구부장 조응래 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 환경정책연구부장 나왔습니까?
</p>
<p><b>○ 환경정책연구부장 성현찬 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 산업경제연구부장 나왔습니까?
</p>
<p><b>○ 산업경제연구부장 김군수 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 사회문화연구부장 나왔습니까?
</p>
<p><b>○ 사회문화연구부장 김흥식 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 수도권정책센터장 나왔습니까?
</p>
<p><b>○ 수도권정책센터장 이상대 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 경제정책분석센터장 나왔습니까?
</p>
<p><b>○ 경제정책분석센터장 조성종 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 팔당물환경센터장 나왔습니까?
</p>
<p><b>○ 팔당물환경센터장 정종수 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 과학기술정책센터장 나왔습니까?
</p>
<p><b>○ 과학기술정책센터장 문미성 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 통일문제연구센터장 나왔습니까?
</p>
<p><b>○ 통일문제연구센터장 김동성 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 다음은 선서의 요령을 설명드리겠습니다.  선서는 전체 증인을 대표해서 원장이 발언대로 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손을 들어 주시기 바랍니다.  그러면 선서를 해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 선서!  본인은 경기도의회가 지방자치법 제41조, 동법시행령 제39조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 소관업무에 대한 2007년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조의 규정에 의하여 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다.  2007년 11월 16일.  증인 원장 좌승희.
</p>
<p><b>○ 위원장 김영복 </b> 앉으시고요.  그러면 원장 나오셔서 간부소개와 업무보고를 간략하게 해주시기를 바랍니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 안녕하십니까?  원장 좌승희입니다.  존경하는 김영복 위원장님과 위원님 여러분을 모시고 금년도 주요업무 추진현황과 내년도 연구사업계획을 보고드리게 된 데 대해 감사의 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  저희 연구원은 당초에 계획한 연구사업을 차질 없이 수행하고 있으며 2단계 국토균형발전대책을 비롯한 현안 대응 및 경기도의 싱크탱크로서 정책개발과 신속한 도정지원에 노력하고 있습니다.  앞으로도 연구업무와 도정 지원을 차질 없이 추진해 나갈 계획이오니 기획위원회 위원님들의 많은 도움과 성원을 당부드립니다.
</p>
<p style="padding-left:1.2em">  그러면 보고에 앞서 우리 연구원의 간부를 소개해 드리도록 하겠습니다.  먼저 신원득 부원장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음으로 이상훈 기획조정실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이정열 사무처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음으로 이용환 자치행정연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음으로 이외희 도시지역계획연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음 조응래 교통정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음 성현찬 환경정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김군수 산업경제연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음 김흥식 사회문화연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음 이상대 수도권정책센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음 정종수 팔당물환경센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음 문미성 과학기술정책센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음으로 김동성 통일문제연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 지금부터 우리 연구원의 주요업무를 보고드리도록 하겠습니다.  보고드릴 순서는 준비된 자료에 따라서 유인물을 바탕으로 제일 먼저 일반현황, 재정운용, 2007년도 연구사업 추진현황, 2008년도 연구사업계획에 대해서 중요한 사항을 중심으로 간략히 보고드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 유인물 1페이지 일반현황에 대해서 말씀드리겠습니다.  저희 연구원은 ’95년 개원 후 12주년이 되었습니다.  저희 연구원의 주요기능은 위원님들이 다 아시다시피 도정의 비전 제시와 정책개발을 하는 데 있습니다.  이를 위해서 자치행정연구부를 비롯한 6개의 연구부서와 수도권정책센터 등 6개의 연구센터를 두고 있습니다.  맨 나중에 나와 있는 의정연구센터는 최근 11월 1일자로 설립하였는데 의정발전 관련 정책연구, 의정포럼 및 의정세미나 개최 등을 주로 수행할 계획으로 있습니다.  본 센터는 의정발전과 관련되어 있는 만큼 앞으로 위원님들과 적극 협력해서 의회 발전에 노력하도록 하겠습니다.  보다 자세한 사항은 배부해 드린 유인물을 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 2페이지 말씀드리겠습니다.  본 원의 기구는 1실 1처 6부 6센터이고 현재 인력은 박사급 연구직 48명을 포함해서 전체 71명이 재직하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음 3페이지의 시설 및 장서현황을 보고드리겠습니다.  먼저 청사는 2004년 6월 23일부터 경기도인재개발원 6층에서 12층까지 대지 3만 327㎡, 건평 5,465㎡를 사용 중에 있습니다.  연구에 필요한 장서는 3만 9,000여권 정도를 보유하고 있으며 주로 최신의 국내외 전문서적 및 경기도 관련 자료로 구성되어 있습니다.
</p>
<p style="padding-left:1.2em">  다음 4쪽의 재정운용 현황에 대해 보고드리겠습니다.  먼저 올해의 총 예산규모는 178억 9,600여만원이며 수입재원은 출연금이 55%에 해당되는 99억원, 기금이자수입 등이 9%인 17억 1,500여만원, 사업수입이 5%인 8억 1,300여만원, 그리고 전기이월금이 31%인 54억 6,700여만원에 이릅니다.  다음에 지출항목으로는 연구사업비가 전체의 50%인 89억 3,000여만원, 인건비가 33.8%인 60억 5,500여만원, 부서운영비가 9.5%인 17억 900여만원, 청사관리비가 6.1%인 10억 9,000여만원, 예비비 및 기타가 0.6%인 1억 1,000여만원 등입니다.  기금현황에 대해 보고를 드리면 총 272억원의 기금이 적립돼 있으며 출연기관별로는 경기도가 54%인 147억원, 시&#8228;군이 15%인 39억 6,000만원, 민간부문이 7%인 20억원, 그리고 자체적립이 24%인 65억 3,900만원입니다.  참고로 자료에는 지금 아직 안 나왔습니다만 위원님들의 비교를 돕기 위해서 내년도 예산규모를 간략히 말씀드리겠습니다.  내년도 예산규모는 168억 6,000만원이며 이 중 연구사업비가 48%에 해당하는 81억 1,700만원, 인건비가 38%인 63억 2,000만원, 부서운영비가 7%인 12억 1,800만원, 청사관리비가 6%인 10억 5,500만원으로 계획을 하고 있습니다.  물론 위원님들이 추후에 결정을 해주시면 확정이 될 것으로 생각합니다.
</p>
<p style="padding-left:1.2em">  다음 5쪽의 금년도 연구사업 추진현황에 대해서 보고드리겠습니다.  금년도에 저희 연구원은 사업목표를 첫째로 경기도와 국가의 경쟁력을 강화하기 위한 수도권 규제개선 등 국가적 이슈에 대한 종합적이고 중장기적인 정책방안을 제시하고 둘째로는 경기도와 31개 시&#8228;군의 정책 효율성 제고 및 삶의 질과 복지 향상을 위한 정책추진 방안에 대해서 연구하고 셋째로는 수도권 경쟁력 강화, 수도권 광역교통정책, 팔당종합대책, 뉴타운사업 등 4대 주요 도정 현안에 대한 정책개발 및 지원에 두고 연구사업을 추진해 왔습니다.  이런 기본방침을 토대로 연구원은 6쪽부터 14쪽에 이어서 주요 연구사업 실적에서 보시는 바와 같이 다양한 여러 분야에 걸쳐 연구성과를 이루었습니다.
</p>
<p style="padding-left:1.2em">  6쪽을 참조해 주시기 바랍니다.  먼저 국가적 이슈를 주도하고 이를 통해 국가와 경기도의 발전을 위한 대안제시 성격을 갖는 내셔널 이슈(National Issue)에 대한 연구를 핵심연구과제로 추진했습니다.  수도권정책, 지방분권, 환경정책, FTA 대책 등 8개 과제를 수행했거나 지금 수행 중에 있습니다.
</p>
<p style="padding-left:1.2em">  7쪽을 참고해 주십시오.  위원님들께서도 많은 관심을 가지고 계시는 민선4기 4대 주요 도정 현안에 대한 연구도 핵심연구사업으로 수행하고 있습니다.  구체적인 현황은 유인물 7페이지를 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  8쪽으로 넘어가도록 하겠습니다.  보시는 바와 같이 경기 동북부지역의 발전방안, 주한미군 반환공여구역 발전계획, DMZ평화생태공원 조성, 서해안권 신개발 구상 연구 등 지역의 경쟁력을 강화할 수 있는 정책개발연구도 다양하게 수행했습니다.
</p>
<p style="padding-left:1.2em">  다음 9쪽부터 12쪽까지는 금년도에 수행한 연구활동 결과의 정책반영 사례들을 정리했습니다.  국가 발전을 위한 전략과제연구 결과를 각 정당의 대선공약 및 차기정부 개혁과제로 반영시키기 위해서 연구결과를 각 정당에 지금 돌리고 있고요.  뉴타운사업 대상지 선정 및 뉴타운사업 추진계획 제안, FTA 대책, 경기도 소방행정조직 개편방향 제시 등 각종 도정 현안 정책개발 및 지원에 기여했습니다.
</p>
<p style="padding-left:1.2em">  다음에 10쪽으로 가서 화성시 에듀타운 조성, 군포시의 영어체험센터 건립 등 시&#8228;군 현안정책 지원에도 기여한 바 있습니다.  10쪽에서 11쪽에 걸쳐서 북부와 동부지역에 관련된 연구에 대해서 보고드리겠습니다.  저희 연구원은 경기도 내에서 상대적으로 낙후되어 있는 북부지역과 동부지역의 발전을 위한 현안정책 개발에도 심혈을 기울여 왔습니다.  대표적으로 연천군의 대학유치 추진을 돕기 위한 연구를 하고 있고요.  주한미군 반환공여구역 1단계 종합계획을 도와 더불어서 연구해서 행자부에 제출했고 동부권의 도시개발, 산업&#8228;관광&#8228;농업 부문별 발전전략 제시를 위해서 노력했습니다.
</p>
<p style="padding-left:1.2em">  다음으로 11쪽과 12쪽에서 보시는 바와 같이 수도권 통합환승할인제도 시행, 대기질측정망 운영방안 개선, 경기도 연구개발사업 조사 및 신규 R&D 과제 기획, 경기도 연구개발사업 평가 진행 등을 비롯해서 교통, 환경, 과학기술정책 분야에서도 다양한 정책기여를 했습니다.  12쪽을 보시면 위와 같은 연구과제 활동을 통한 정책기여뿐만 아니라 도정 현안을 중심으로 해서 단기적인 급한 정책과제를 지원하는 연구를 계속 수행했습니다.  금년 1월에서 9월까지 수도권정책, 2단계 국토균형발전정책 대응전략, 현안 관련 도지사 토론자료 공급, 재정, 지식산업, 지방행정 혁신, 교통, 환경분야 현안에 대한 지원, 황해경제자유구역, 학교용지부담금, 수도권 차별 대응책, 북부지역 발전, 수도권규제도 등을 비롯한 지리정보시스템 구축 등 총 226건에 이르는 단기 도정 현안대책 지원활동을 수행한 바 있습니다.  12페이지 맨 밑에 있는 막대그래프를 보시면 일목요연하게 정리가 돼 있습니다.
</p>
<p style="padding-left:1.2em">  13쪽을 말씀올리겠습니다.  연구네트워킹 활성화를 위해서 세미나, 정책포럼, 선진화위원회 운영, 외부기관과의 MOU 체결과 공동연구를 적극 추진했습니다.  KIST, 수도권 3개 시&#8228;도 연구원, 국토연구원, 과학기술정책연구원, 중국 산동사회과학원 등과 공동연구를 현재 수행하고 있습니다.  그밖에 연구성과를 경기도민들한테 알리기 위해서 제가 취임한 이후에 연구결과를 기자분들한테 브리핑하는 사업을 진행하고 있습니다.  대언론 브리핑을 지난해에 23회에 걸쳐서 개최했습니다.  그리고 GRI 이슈분석, GRI 주간경제동향, GRI 경제칼럼 등을 7만명의 오피니언 리더들에게 메일링서비스로 발송하는 등 연구성과의 마케팅 강화를 위한 온&#8228;오프라인 홍보활동을 적극 추진해 왔습니다.
</p>
<p style="padding-left:1.2em">  14쪽에 대해서 말씀드리겠습니다.  그리고 현안 대응력 강화, 전략 실행을 위해 경제정책분석센터, 과학기술정책센터, 통일문제연구센터, 팔당물환경센터, 의정연구센터를 신설 운영하는 등 연구시스템 개선 및 강화에도 주력했습니다.  특히 도정의 범위가 넓어지고 관심사항이 다양해지면서 이를 뒷받침하기 위한 노력으로 이런 새로운 연구부서를 설립하게 되었습니다.
</p>
<p style="padding-left:1.2em">  참고로 경제정책분석센터에서는 경기도 거시경제 동향 및 전망에 대한 심층분석, 산업동향 및 경제현안을 분석 대응하는 일을 주로 수행해 오고 있습니다.  지표별로 통계분석을 하고 경기도 주요산업 동향분석을 병행해서 경기도 경제 및 산업 전반에 대한 의미 있는 정보를 제공하고 있는 경기도경제동향을 월간으로 발간하고 있으며 또한 주간경제동향을 매주 온라인으로 발송하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 15페이지의 2007년도 연구사업 총괄에 대해서 간략히 보고올리겠습니다.   연구사업은 현재 513건을 완료했습니다.  그리고 223건을 추진 중에 있어서 전체로 보면 당초계획 대비 114%를 추진 중에 있습니다.  수행 중인 과제들을 계획대로 차질 없이 완료할 수 있도록 노력하고 있습니다.
</p>
<p style="padding-left:1.2em">  세부 추진상황을 16페이지부터 34쪽에 걸쳐서 간략하게 보고올리겠습니다.  먼저 16쪽에서 보시면 기본연구과제는 25개 과제를 수행하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음으로 17페이지부터 21페이지까지의 정책연구과제는 총 77건 중 규제개혁과 생활기반 정비 정책개발 기초연구, 2003년 지역산업연관표로 본 경기도 경제 등 43건을 완료했고 경기도 과학기술정책의 현안과제와 정책대응 등 33건을 수행 중에 있습니다.  21페이지에서 보시는 바와 같이 수도권 취수원 이전 타당성 연구는 11월 5일자로 현재 중지된 상태에 있습니다.
</p>
<p style="padding-left:1.2em">  22쪽으로 넘어가도록 하겠습니다.  22쪽에서 25쪽까지는 수탁연구과제에 대한 보고입니다.  전년도에서 이월된 24개 과제와 금년도에 신규로 계약한 39개 과제를 포함해서 총 63개 과제 중 제4차 경기도권역 관광개발계획수립 연구용역 등 27건을 완료했고 2006년 수도권 가구통행실태조사 연구용역 등 35건을 현재 수행 중에 있습니다.
</p>
<p style="padding-left:1.2em">  위원님들이 양해하신다면 26쪽으로 넘어가도록 하겠습니다.  26쪽의 위탁연구과제는 총 24건인데 이 중 한미 FTA가 경기도 농업에 미치는 영향과 대응방안 등 9건은 완료했고 나머지 15건은 수행 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음 28쪽의 협약연구과제와 지역연구과제 등에 대해서 설명을 올리겠습니다.  협약연구과제는 총 7건 중 한국 선진화의 길 대토론회 등 2건을 완료했고 나머지 5건은 수행 중에 있습니다.  지역연구과제는 과천시와 의정부시를 대상으로 각각 연구 중에 있습니다.  결과는 12월 중에 나올 예정입니다.
</p>
<p style="padding-left:1.2em">  과천지역 연구는 도시디자인, 기후변화 대응 시범도시, 양재천 관리, 지역문화 진흥 및 관광산업에 중점을 두고 있으며 의정부지역 연구는 도시계획 방향, 지역문화 및 관광 활성화, 공원녹지, 지역경제 및 산업 활성화에 중점을 두고 진행하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음으로 29쪽에 대해서 설명을 올리겠습니다.  29쪽부터 34쪽까지는 연구부대&#8228;지원&#8228;기반사업을 요약 정리했는데요.  상세한 내용은 유인물을 참조해 주시면 좋겠고요.  제가 간략하게만 보고올리겠습니다.  세미나는 전체 18회를 개최했습니다.  정책포럼은 33회 개최, 등재후보지 이상 학술지 논문 게재가 34건으로 전년 대비 16건이 증가했습니다.  GRI 이슈분석 제공 30건, 선진화위원회 46회 개최, GRI 웹뉴스 81회 발송 등이 부대&#8228;지원&#8228;기반사업의 주요실적이 되겠습니다.  사업별 구체적인 내용은 유인물로 대체하도록 하겠습니다.  35쪽의 연구사업 연도별 수행 현황도 유인물을 역시 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  36쪽부터 49쪽까지의 2008년도 연구사업계획을 보고드리겠습니다.  36쪽에 대해서 말씀올리겠습니다.  내년도 연구사업계획의 사업목표는 첫째, 동북아 환황해경제의 중심 경기도 실현을 위한 각종 정책을 개발할 계획이고 둘째는 한미&#8228;한EU&#8228;한중 FTA 추진에 따른 경기도의 대응전략을 개발하고 셋째로는 경기도의 삶의 질 향상과 동북부지역 균형발전을 위한 정책개발 및 지원에 역점을 두고자 합니다.  37쪽부터 39쪽에서 보시는 바와 같이 이러한 기본목표를 토대로 내년도 연구사업계획은 37쪽을 참조해 주십시오.  연구과제사업이 151건이고, 연구부대사업이 9종에 289건, 연구지원사업이 4종, 연구기반사업이 5종에 268건을 추진할 계획이며 사업예산 등 구체적인 것은 유인물을 참고해 주시면 고맙겠습니다.
</p>
<p style="padding-left:1.2em">  다음 39페이지로 넘어가서 39페이지부터 49페이지에 걸쳐 단위사업별 개요 및 계획을 보고드리겠습니다.  먼저 40쪽을 참조해 주시면 금년도에 이어 내년에도 내셔널 이슈(National Issue)를 주제로 중점 연구과제를 수행할 계획입니다.  내년에는 지금 계획입니다만 수도권 성장패턴 예측 및 파급효과 연구 등 6개 분야를 우선 추진할 예정이며 중앙 및 경기도의 향후 정책동향을 봐가면서 필요하다면 추가적으로 내셔널 아젠다를 발굴해서 연구를 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  41쪽 기본연구과제 계획을 설명드리겠는데요.  내년도 기본연구과제는 지방자치단체 자체평가제도의 성과분석 연구를 비롯해서 24개 과제를 계획하고 있습니다.  과제현황은 41쪽의 유인물을 참고해 주시면 고맙겠습니다.  또한 42쪽에서 43쪽을 보시면 정책연구과제 65건, 위탁연구과제 15건, 지역연구과제 2건, 수탁연구과제 45건을 각각 계획하고 있습니다.
</p>
<p style="padding-left:1.2em">  44쪽부터 46쪽에 걸쳐서 연구부대사업 등 연구 관련사업을 보고드리고 있는데요.  우선 세미나의 경우는 연간 25회를 계획하고 있고 정책포럼 운영이 44회, 해외연구 교류를 계획하고 논문 현상공모를 실시하고 월간 경기도경제동향을 발간하고 계간 연구원 학술지 경기논단을 발간하고 정책동향 분석, 연구홍보, 선진화위원회 관리운영 등을 계획하고 있습니다.  분야별 사업량과 사업비에 대한 구체적인 사항은 유인물을 참고해 주시기 바랍니다.  
</p>
<p style="padding-left:1.2em">  47쪽과 48쪽에 걸쳐서 보고를 올리겠습니다.  연구지원사업으로 정보자료 지원, GIS사업, 전산사업, 다음 페이지 시ㆍ군담당제 등을 계획하고 있으며 구체적인 내용은 유인물을 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  48쪽과 49쪽에서 보고드리는 연구기반사업으로 초빙연구원과 위촉연구원을 활용하는 연구인력 아웃소싱제도를 활성화하고 연구평가심의회, GRI웹뉴스, GRI브로슈어 제작, 연구교육 개발 등의 사업을 추진할 계획입니다.  사업별 개요는 역시 유인물을 참고해 주시면 감사하겠습니다.  이상 2007년 사업 진행상황과 2008년 사업계획을 간략하게 보고올렸습니다.
</p>
<p style="padding-left:1.2em">  다음은 마지막 50쪽입니다.  2006년도 행정사무감사 처리요구사항 조치결과를 보고드리겠습니다.  2006년 11월 21일 행정사무감사 시 처리요구사항은 14건이었고 이를 개선하기 위해 최선을 다했습니다.  먼저 서울시정개발연구원과 비교하여 홈페이지 조회건수가 저조하다는 지적이 있었습니다.  그래서 이런 문제를 해결하기 위해서 간행물회원제 구입 안내문과 연구보고서의 판매가 및 조회건수 표기 관련사항은 지적하신 대로 수정하였으며 홈페이지 방문건수를 올리기 위해서 여러 가지 노력을 했습니다.  결과적으로 많은 성과를 냈는데요.  월 평균 접속건수가 2006년 약 2만 5,000건에서 2007년 5만건으로 증가하였습니다.  아직도 미흡합니다마는 지적하신 사항을 개선하기 위해서 노력을 하고 있습니다.
</p>
<p style="padding-left:1.2em">  그 외에 지난해 지적해 주신 지적사항에 대한 저희들의 처리결과는 유인물 50쪽에서부터 53쪽에 걸쳐서 보고를 올렸습니다.  위원님들 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  이상으로 2007년도 주요 업무보고를 마치겠습니다.  위원 여러분, 경청해 주셔서 대단히 감사합니다.
</p>
<p>업무보고서(경기개발연구원)
</p>
<p><b>○ 위원장 김영복 </b> 경기개발연구원 좌승희 원장님 수고하셨습니다.  다음은 감사를 위한 질의답변 순서가 되겠습니다.  감사의 효율적인 진행을 위해서 질의는 일문일답으로 하되 질의시간을 제한하도록 하겠습니다.  우선 위원님 한 분당 10분씩 시간을 드리고 추가질의는 1회에 한해서 5분을 드리도록 하겠습니다.  그리고 본질의 후에 보충질의를 해주시기 바랍니다.  다만 보충질의는 가능하면 간략하게 요약해서 일문일답으로 해주시기 바랍니다.  원활한 감사진행을 위해서 부득이하게 시간 제한을 두게 된 점 널리 양해해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  질의에 앞서 위원장으로서 한 가지 부탁의 말씀을 드리겠습니다.  위원님들의 질의에 대해서 원장이 답변이 어려울 경우에 업무담당 부장 및 센터장 등 실무자가 답변해도 좋겠습니다.  다만 사전에 위원장에게 동의를 얻은 후에 발언대로 나와 소속과 직ㆍ성명을 분명히 밝히고 답변을 해주시기 바랍니다.  위원님들께 양해의 말씀을 드리겠습니다.  장시간 감사로 인해서, 또 원활한 답변을 위해서 원장님이 앉아서 답변하는 것을 원칙으로 하려고 하는데 이의 있습니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  이의가 없으므로 원장님 자리에 돌아가서 앉아서 답변해 주셔도 좋겠습니다.  그 뒤에서는 위원님들이 양쪽에서 원장님이 보일 수 있도록 발언대를 조정해 주시기 바랍니다.  그럼 질의하실 위원께서는 거수로 신청하여 주시기 바랍니다.
</p>
<p><b>○ 임우영 위원 </b> 자료 좀…….
</p>
<p><b>○ 위원장 김영복 </b> 질의에 앞서 자료 요청 요구가 들어왔습니다.  임우영 위원님 자료 요청해 주시기 바랍니다. 
</p>
<p><b>○ 임우영 위원 </b> 죄송합니다.  아까 도정 현안정책 개발을 지원하셨다 그랬는데, 환승할인제도하고 그다음에 경기도 소방행정조직 개편방안 제시를 하셨다 그랬고 경기도 명품신도시 개발정책 수립에 기여하고, 또 뉴타운과 관련된 사업에 대해서 제안을 하셨다 그랬는데 이 자료를 주셨으면 좋겠습니다.  자료를 갖다주시기 바랍니다.  이상입니다.
</p>
<p><b>○ 위원장 김영복 </b> 다른 위원님, 자료요청하실 위원님 요청해 주시기 바랍니다. 
</p>
<p><b>○ 이해문 위원 </b> 과천 이해문 위원입니다.  저도 자료 먼저 하나 확인하겠습니다.  아까 2006년도 행정사무감사 조치결과에 대한 확인을 위해서 지금 등기부등본 떼어놓은 것 있으면 사본이라도 좋습니다.  제출해 주시고요.  그다음 금년에 이사회 개최된 회의록을, 기재된 회의록을 지금 제출해 주시기 바랍니다.  이상입니다.
</p>
<p><b>○ 위원장 김영복 </b> 다른 위원님, 조선미 위원님 자료 요청…….
</p>
<p><b>○ 조선미 위원 </b> 조선미 위원입니다.  지금 국책연구기관이, 국토개발연구원이라든가 이런 다른 기관에서 연구원들이 1인당 연간 몇 건 정도 하는지 그런 자료가 있으면 제출해 주시기 바랍니다. 
</p>
<p><b>○ 위원장 김영복 </b> 장윤영 위원님 자료 요청해 주시기 바랍니다. 
</p>
<p><b>○ 장윤영 위원 </b> 다른 기관에 늘 있는 부분인데 혹시 과제중심으로 해서 발주현황 있지 않습니까.  발주현황은 있는데 계약방법 있지 않습니까.  특히 재위탁한 것에 대한 공개경쟁일찹이나 수의계약이나 어떤 계약의 형태가 있을 것 같습니다.  그래서 제가 요청한 연구과제물에 대한 계약방법에 따른 과제내용들 있지 않습니까.  가능하시겠지요?  이상입니다.
</p>
<p><b>○ 위원장 김영복 </b> 다른 위원님, 자료 요청하실 위원님 안 계십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 죄송합니다만 위원님들 말씀이 잘 안 들리면 제가 확인할 수 있도록 해주십시오.
</p>
<p><b>○ 위원장 김영복 </b> 네, 그렇게 하겠습니다.  그러면 자료 요청이 다 되셨으면 질의하실 위원님 계십니까?  장윤영 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 장윤영 위원 </b> 먼저 행정사무감사 요구자료 관련 페이지를 말씀드리겠습니다.  첫 번째 연구과제 수행현황 안에 있는 목록입니다.  그다음에 두 번째가 제가 요청한 부분입니다.  657페이지에 있는 타 기관 수탁연구과제 수행현황입니다.  그다음 세 번째 참고목록이 695페이지에 있는 의뢰받은 연구과제 중 재위탁현황입니다.  이 세 가지 자료를 중심으로 해서 질의토록 하겠습니다.  그래서 마지막 질의를 하기 위해서 자료가 오면 질의할 테니까 이거 반드시 중간에 말씀 주셔야 됩니다.  특히 695페이지 원 발주처가 없습니다.  지금 분명히 재위탁을 했는데 경기도로부터 발주를 받았는지 아니면 어느 시ㆍ군에서 했는지 이 내용하고요.  그다음에 처음에 받았을 때 가격이 있을 겁니다.  아마 2,500만원에 재위탁을 했는데 원래 받은 것이 2,500만원이 아니고 오버헤드 부분이 있었을 것 같습니다.  이 가격 자료 갖다 주시고요.  
</p>
<p style="padding-left:1.2em">  그러면 이 세 가지 자료를 중심으로 해서 질의토록 하겠습니다.  먼저 첫 번째 질의입니다.  657페이지, 타 기관의 수탁연구과제 수행현황 했는데 2006년도에 5개입니다.  그다음에 658페이지에 있는 것이 4개입니다.  그런데 이 숫자하고요.  바로 첫 번째 연구과제 있지 않습니까.  2006년하고 2007년도 연구과제 수행현황의 개수가 전혀 맞지······.  이쪽에서는 어떤 형태로 자료가 분류되어 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 뒷부분 말씀을 놓쳤는데 다시 한 번 뒷부분 말씀해 주시겠습니까? 
</p>
<p><b>○ 장윤영 위원 </b> 별도 자료로 타 기관의 수탁연구과제 수행현황 해가지고 657페이지에 요구를 해놨습니다.  그러니까 경기바이오센터, 경기관광공사, 수도권교통조합 이런 데로부터 지금 받았지 않습니까?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 그런데 여기는 개별현황인데 총 현황이 바로 첫 번째 이해문 위원님께서 요청하신 자료입니다.  연구과제 수행현황 2006년도하고 2007년도요.  그래서 제 질의핵심은 뭐냐 하면 기본과제, 수탁과제, 정책연구과제, 지역연구과제, 그다음에 위탁연구과제 이 다섯 가지 외에 다른 과제가 또 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지금 말씀하신 카테고리는 전부 다 커버가 되는 것 같은데요.  그 외에 따로 저희가 연구과제를 하는 것은 없는 것 같은데요.
</p>
<p><b>○ 장윤영 위원 </b> 내용상에서 이건, 그러니까 분명히 첫 번째 있지 않습니까.  첫 번째 연구과제에 나와 있는 것은 5개인데 타 기관 수탁연구과제는 어디에 포함이 됩니까?  그러니까 지금 수탁연구과제 있지 않습니까.  2006년도에 보면 수탁연구과제가 28개로 되어 있습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이 표는 우리가 늘 수탁을 받는 위탁처가 있는데요.  경기도라든가 경기도 31개 시ㆍ군이 있지요.  여기서 주로 받지만 그 외에 여타 기관에서 받은 수탁과제를 여기에 리스트 업을 한 거니까 이것은 전체 수탁연구과제의 일부에 해당합니다.  그 안에 다 포함되어 있다고…….
</p>
<p><b>○ 장윤영 위원 </b> 제 질의 이해 못하셨습니까?  수탁이라고 하는 것은 외부기관이 대전제가 되는 겁니다.  그런데 첫 번째 자료에는 수탁과제가 28개라고 되어 있는데요.  수탁이란 건 100% 외부기관 아닙니까?  그렇죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇게 봐야죠.
