<p><b>○ 장윤영 위원 </b> 그런데 왜 657페이지 자료에는 2006년도에 5개밖에 없느냐라는 겁니다.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그러니까 이건 전체 수탁과제 중에 공공기관, 예를 들면 도청이라든가 31개 시ㆍ군에서 받은 것 이외에 기타 기관에서 받은 것을 여기 정리한 것 같습니다.  그러니까 이건 전체 수탁과제의 아주 일부에 해당하는 겁니다. 
</p>
<p><b>○ 장윤영 위원 </b> 그러면 일단은 질의의 핵심내용은 아니니까 여기서는 분명히 수탁이라는 대전제는 외부기관이라는 것이 있는데 그렇다고 한다면 의미해석이, 그렇다면 여러분들은 성남시라든지 이건 외부기관 아닙니까?  맞지 않습니까?  그래서 만약에 28개 과제가 이쪽으로 다 왔으면 상관이 없습니다.  임의해석을 하지 말아달라는 겁니다.  그래서 이건 질의의 핵심은 아닙니다.  숫자가 헷갈려 가지고 이거 분석하는 데 시간이 너무 많이 걸렸습니다. 
