<p><b>○ 경기개발연구원장 좌승희 </b> 죄송합니다.
</p>
<p><b>○ 장윤영 위원 </b> 그러면 질의의 핵심으로 넘어가도록 하겠습니다.  695페이지 봐주시겠습니까.  이런 행정감사 자료가 어디 있습니까?  제가 조금 전에 질의를 하긴 했지만 원청기관이 표시가 되지 않았습니다.  그래서 어디서 받은 건데 어디로 넘겼다라는 것, 넘긴 데는 나와 있습니다.  받은 데 표시하지 않은 이유 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 특별한 이유는 없고요.  과제 요청하실 때 저희 연구원이 잘못 이해를 한 게 아닌가 싶습니다.
</p>
<p><b>○ 장윤영 위원 </b> 그러면 두 번째 질의입니다.  이게 2006년도 겁니까, 2007년도 겁니까, 아니면 경기개발연구원 창립 이래 전부 다입니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 2006년과 2007년 양년에 걸쳐 의뢰받은 연구과제로 보시면 되겠습니다. 
