<p><b>○ 장윤영 위원 </b> 행정감사 자료 맞다고 말씀하셨습니까?  조금 전에 말씀드렸지만 이게 언제 자료인지 표시가 전혀 안 되어 있어요.  그리고 조금 전에 했던, 지금 제일 보고자 하는 것 자체는 몇 가지 이유가 있었는데 확인하는 과정이 이게 어디서 왔을까라고 하는 겁니다.  왜냐하면 여기서는 경기개발연구원에 위탁했을 때 가장 커다란 이유가 뭡니까?  소위 말해서 지식에 관한 전문기관이라고 해서 맡긴 것도 있겠지만 혹시 자치단체나 이런 쪽에서 보안 때문에 맡겼을 가능성은 없습니까? 
