<p><b>○ 장윤영 위원 </b> 아니요.  이것은 의뢰받은 것이니까 위탁받은 과제입니다.  그렇다고 한다면 발주처에서 경기개발연구원의 연구인력이 우수하다라고 해서 맡겼을 가능성도 있고요.  제일 중요한 것은 관에서 운영하기 때문에 보안이 유지가 될 것이다라고 하는 판단에서 맡겼을 수도 있습니다.
