<p><b>○ 장윤영 위원 </b> 그런데 지금 여기서 몇 가지만 보겠습니다.  두 번째 수도권 계획관리 기본계획 수정에 따른 세부계획 수립입니다.  수도권 계획관리라고 하는 내용 자체는 극히 제목상에서 보안을 유지해야 될 내용으로 판단되는데 그렇지 않습니까?
