<p><b>○ 장윤영 위원 </b> 뒤에서 분명히 이거 계약하신 분이 있고, 그럼 여기서 질의하겠습니다.  이 동림피엔디는 여기 전부 다 포함이 되겠지만, 업체 선정을 어떻게 합니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 항상 공개경쟁입찰을 원칙으로 하고 있습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 그 자료 갖다 주시고요.  그렇다라고 한다면 이건 제한이 있었어야 됩니다.  수도권 계획관리 기본계획 수정입니다.  세부계획 수립이거든요.  그런데 동림피엔디라는 업체는 교평 업체입니다.  교통영향평가, 환경영향평가 업체입니다.  일반 민간업체입니다.  2002년도에 창립된 자본금 5,000만원으로 설립된 회사라는 겁니다.  그래서 1번 같은 경우도 그렇습니다.  1번 같은 경우도 에듀타운에 대한 개발타당성 기본구상하고요.  그다음에 실질적으로 맨 마지막이, 이거 번호가 없으니까 세 번째가 되면 이렇게 해야 되거든요.  안에 주요 내용 보면 697페이지 첫 번째 있지 않습니까.  경기도 뉴타운 정비구상 및 전략수립 이건 바로 김문수 지사가 들어오고 나서 한 것이기 때문에 개인사무실이 아니라 공공기관에서 진짜 보안을 유지하면서 가야 될 사항이었다라고 판단하는 겁니다.  그렇지 않습니까?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 장윤영 위원님 말씀에 충분히 동감입니다.  저희가 중요한 공공정책에 관련된 연구를 할 때 저희가 연구하는 연구의 성격상 그게 잘못 공개되거나 했을 때 불필요한 문제를 야기할 수 있다는 걸 제가 충분히 인지하고 있고 요.  그렇기 때문에 이런 외주의 경우에는 특별히 기술적인 문제를 중심으로 해서 전문성 있는 민간업체나 연구자를 활용하는 것이지 수도권 계획을 수정한다든가 했을 때 그 전체 내용을 이런 사람들한테 그려달라고 하는 게 아니라 아주 세부적인 기술적인 것을 요구하는 것이고 뉴타운 같은 경우에도 그런 식으로 저희가 접근을 하려고 노력합니다.  그래서 저희가······.
</p>
<p><b>○ 장윤영 위원 </b> 원장님, 시간이 제약되어 있으니까 그냥 단답으로 가겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 그러면 이거 수도권 계획관리 기본계획 수정에 따른 세부계획 수립 원청 발주처가 어디입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이 연구를 담당하고 있는 수도권정책센터 이상대 박사로 하여금 답변을 드리도록 하면…….
