<p><b>○ 수도권정책센터장 이상대 </b> 경기도 신도시개발과입니다.  그 당시에는 신도시개발지원단이고 지금은 신도시개발과입니다.
</p>
<p><b>○ 장윤영 위원 </b> 원청 발주금액 얼마입니까? 
</p>
<p><b>○ 위원장 김영복 </b> 위원장으로서 말씀드리겠습니다.  장윤영 위원님 이해를 해주신다면 아시는 분이 직ㆍ성명을 밝히고 마이크 앞에서 답변하도록 그렇게 하시죠.
</p>
<p><b>○ 수도권정책센터장 이상대 </b> 수도권정책센터장 이상대입니다.  그리고 그 과제 연구책임자고요.  원래 발주처는 그 당시에 경기도 신도시개발지원단입니다.  그리고 일부 기술적인 부분에 대해서 공개 공고를 거쳐서 공모를 했지만 계속 유찰이 됐습니다.  그래서 보안을 유지할 수 있고 그다음에 기술 수준을 갖추고 있는 업체 중에서 선정을 했었습니다.  그리고 분명히 도시계획기술사가 있고 도시계획 파트가 있는 회사였습니다. 
