<p><b>○ 수도권정책센터장 이상대 </b> 맞습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 850만원은 통상적으로 수의계약을 합니다.  850만원을 공모하면서 유찰이 계속됐다라고 하는데 그러면 전체를 발주하셨습니까? 
</p>
<p><b>○ 수도권정책센터장 이상대 </b> 아닙니다.  부분만 발주했습니다.
</p>
<p><b>○ 장윤영 위원 </b> 부분 발주했을 것 같습니다.  그런데 850만원을 공개 발주한 것 맞습니까?  공모한 것.
</p>
<p><b>○ 수도권정책센터장 이상대 </b> 아마 그랬을 겁니다.
</p>
<p><b>○ 장윤영 위원 </b> 아마 그랬을 겁니다?  지금 이 자리가 감사 자리인 것을 유념해 주시기 바랍니다.
