<p><b>○ 수도권정책센터장 이상대 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 다시 한 번 질의하겠습니다.  금액이 850만원입니다.  이게 계약금액입니까, 아니면 공모했던 금액입니까?.
</p>
<p><b>○ 수도권정책센터장 이상대 </b> 계약금액입니다.  제가 알기로는 계약금액이고요.  그것은 아마 재정지원과장이 확실히 알 텐데 500만원 이상은 일단 공모과정을 거치는 것을 저희 원내에서는 원칙으로 하고 있습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 그렇다면 아까 조금 전에 말씀드렸던 동림피엔디라는 회사에 홈페이지를 확인해 봤습니다.  2002년도에 자본금 5,000만원으로 시작된 회사입니다.  내용에 보니까 주로 교통영향평가를 담당하는 교평 업체였습니다.  이런 곳에 이런 중요한 부분이 발주됐을 적에는 문제가 발생될 가능성이 있기 때문에 제한을 뒀어야 된다라고 판단하는데 혹시 제한 둔 사항 있습니까? 
</p>
<p><b>○ 수도권정책센터장 이상대 </b> 무엇보다 중요한 것은 당시에 보안 유지였습니다.  그리고 워낙 금액이 적기 때문에 대형 업체들이 들어오는 것은 기대할 수가 없습니다. 
