<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 이거 같은 경우는 금액이 적기 때문에 외주를 준 겁니까, 아니면 조금 전에 말씀드렸던 것처럼 혹시나 보안······.  보안 때문에 이 회사에 줬다라고 말씀하셨는데 결론적으로 들어간다면 향후에 외부 발주 주는 것 중에 보안이 필요한 것에 대해서 계속 이런 식으로 공모를 나갈 계획이십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아까 이 박사가 지적했습니다마는 금액이 일정한 수준 이상이 되면 규정과 내규에 의해서 저희가 공개입찰을 원칙으로 하고 있으니까 그 원칙을 벗어날 수는 없겠지요.  그러나 하는 과정에서 가능하면 보안을 최대한 유지할 수 있는 그런 업체를 선정하도록 내부에서 심사하는 과정에서 신경을 써서 하도록 해야 되지 않을까 싶습니다.  
</p>
<p><b>○ 장윤영 위원 </b> 위원장님, 가급적 제한된 10분의 시간을 지키기 위해서 질의를 여기서 마치도록 하는데요.  이 부분에 대해서는 조금 전에 말씀드렸던 원청기관, 그다음에 원청기관으로부터 받았던 예산, 그다음에 여기서 이게 계약금액이라고 얘기하셨는데 공모했던 금액하고 계약금액, 공모방법에 대한 자료가 온 다음에 다시 질의토록 하겠습니다.  가급적 시간을 지키도록 애를 쓰겠습니다.  이상 질의 마치겠습니다.
</p>
<p><b>○ 위원장 김영복 </b> 장윤영 위원님 수고하셨습니다.  장윤영 위원님께서 타 기관의 수탁연구과제 수행현황, 그리고 의뢰받은 연구과제 중 재위탁 현황에 대해서 질의해 주셨습니다.  보충질의하실 위원님 계십니까?  보충질의 안 계십니까?  그러면 질의하실 위원님 있으십니까?  전동석 위원님 질의하시기 바랍니다. 
</p>
<p><b>○ 전동석 위원 </b> 안녕하십니까?  원장님 이하 많은 분들이 감사 준비하시느라고 고생 많으셨습니다.  자료 하나만 우선 확인하도록 하겠습니다.  원장님, 오늘 업무보고한 이 자료하고 위원들한테 제출한 이 자료가 같아야 되지 않습니까?
