<p><b>○ 전동석 위원 </b> 한번 확인하도록 하겠습니다.  업무보고한 자료 16페이지에 보면 기본연구과제가 있습니다.  기본연구과제가 행정사무감사 요구자료에 보면 673페이지에 있습니다.  본 위원이 요구한 자료인데요.  673페이지에 보면 같은 기본연구과제가 있습니다.  확인해 주시기 바랍니다. 
