</p>
<p><b>○ 전동석 위원 </b> 그다음에 수탁연구과제가 업무보고자료 22페이지에 나와 있습니다.  거기 보면 63과제 중에 27과제가 완료됐고 1과제 중지됐고 35과제 추진 중이라고 나와 있는 것을 보면 63과제로 되어 있습니다.  그런데 수탁연구과제 요구자료 제출 자료에 보면 이것도 또 53과제밖에 없습니다.  그렇죠?
