<p><b>○ 경기개발연구원장 좌승희 </b> 잠깐이요.  53과제…….
</p>
<p><b>○ 전동석 위원 </b> 674페이지부터 나와 있는 수탁연구과제를 보면 53과제밖에 안 되어 있습니다.  찾으려 해도 서로 비교가 안 됩니다.  앞뒤 뒤죽박죽되어 있어서 전혀 뭐가 빠졌는지를 알 수 없을 정도로 되어 있습니다.  
</p>
<p style="padding-left:1.2em">  하나 더 확인하겠습니다.  그다음 보면 정책연구과제가 있습니다.  업무보고자료 17페이지부터 정책연구과제가 되어 있는데 77개 과제에 43과제 완료, 1과제 중지, 33과제 추진 중으로 되어 있습니다.  그런데 실제로는 여기에 70과제밖에 안 되어 있습니다.  682페이지까지 되어 있는 정책연구과제를 보면 70과제밖에 안 되어 있습니다.  그래서 본 위원이 이걸 혹시나 무엇을 잘못했나 해서 보니까 거의 뒤섞여 있고 비교하느라고 아주 골머리를 썩었는데요.  이게 전혀 비교가 안 됩니다.  너무 다른 자료가 온 것 같은 느낌이에요.  그래서 이게 어떻게 된 건지 한번 해명하시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 요청하신 자료를 작성할 때 저희가 10월 말 기준으로 작성을 했는데요.  제가 오늘 보고올린 것은 11월 5일 기준으로 했기 때문에 그 사이에도 몇 개 수탁과제가 늘어났을 가능성이 있습니다.  그게 아마 가장 큰 이유가 아닌가 싶은데…….
</p>
<p><b>○ 전동석 위원 </b> 좀 정확하게 말씀해 주시지요.  몇 과제가 어떻게 늘어나서 됐다는 사실인지.
