<p><b>○ 경기개발연구원장 좌승희 </b> 우선 두 자료의 차이가 다음과 같습니다.  위원님이 질의하신 내용에 대한 자료는 작년 행감을 했던 2006년 10월부터 2007년 10월 사이에 수행한 과제 중에 도정에 정책적으로 반영된 게 뭐냐를 정리한 것이고요.  그중에 우리가 연구 진행 중인 것도 들어갈 수가 있습니다.  그 기간 동안에 시작된 사업을 가지고 정리했기 때문에.  그런데 제가 오늘 보고드린 사항은 그 사업이 언제부터 시작이 됐든 관계없이 2005년부터 2006년에 시작해서 이월된 사업 혹은 2007년에 가서 새로 시작된 사업까지 다 포함해서 전체적으로 진행됐던 사업을 정리한 거기 때문에 두 개 간에 숫자도 다를 수밖에 없고 일부 과제내용이 좀 다를 수 있다는 걸 발견했습니다.  그래서 제가 확인한 바에 의하면 연구원에서 준비한 게 위원님들의 질의의 의도를 잘 파악을 못해서 대응을 불충분하게 했던 것이 아닌가 싶고요.  장윤영 위원님 질의에도 마찬가지입니다만 저희가 앞으로 이런 행감 자료를 준비할 때는 질의하신 위원님과 접촉을 해서 필요한 자료가 의도에 맞게 제출될 수 있도록 최선의 노력을 다하겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 알겠습니다.  시간이 많지 않기 때문에 본질의 잠깐 하도록 하겠습니다.  자료집 681페이지 정책연구과제를 펴주시기 바랍니다.  두꺼운 자료입니다.  제출한 자료에 보면 39번에 민선4기 1년 성과 평가와 향후 운영방향에 관한 연구라고 있습니다.  그것 관련해서 질의를 드리겠습니다.  정책반영 내용을 보면 민선4기 1년 성과작성 자료에 반영하겠다고 되어 있습니다.  그렇죠?  오른쪽에 정책반영 및 미반영 사유에 보면 민선4기 1년 성과작성 자료에 반영한다고 돼 있습니다.  확인하셨습니까?
