<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다.  제가 의정연구센터의 기능에 대해서 잠정적인 사업방향을 정리한 자료가 있기 때문에 그 자료를 제출해 드릴 테니까 위원님께서 보시고 추가적으로 저희가 고려해야 될 사항이 있으면 앞으로 기능에 보완을 해 나가겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 마무리 발언하겠습니다.  경기도청 공무원들이 고유업무인데도 불구하고 연구원들에게 정식으로 연구용역을 위탁하는 것 이외에 많은 업무를 가중시킬 수 있는 그러한 요구가 있다고 들었습니다.  우리 원장님께서도 그것에 대해서 부인하지 않으셨는데 연구원들의 얘기를 들어보면 그것에 대한 업무 과중이 상당히 많고 또한 경기개발연구원이 경기도의 하수기관, 표현이 좀 과합니다만 시키면 하는 정도로만 생각하고 있다면 연구원의 독립적인 연구는 아주 요원하다고 생각됩니다.  이런 부분에 대해서도 그게 틀렸으면 하지 말아라 하는 얘기를 해야 된다고 분명히 생각되거든요, 도청 쪽에도.  그냥 맡기는 대로 할 것이 아니라 분명히 바른 연구가 될 수 있도록 진행해 주셨으면 고맙겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 잘 알겠습니다.  명심하겠습니다.  
</p>
<p><b>○ 전동석 위원 </b> 본 위원의 질의는 10분간으로 지정됐기 때문에 다음 보충질의 때 다시 하도록 하겠습니다.  질의를 마칩니다. 
</p>
<p><b>○ 위원장 김영복 </b> 전동석 위원님 수고하셨습니다.  10분이 아니라 20분이 넘었습니다.  위원님들 오후에 시간 좀 잘 지켜주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  중식시간이 되어서 중식 후에 계속 감사를 진행코자 하는데 이의 없습니까?
</p>
