<p><b>○ 위원장 김영복 </b> 좌석을 정돈해 주시기 바랍니다.  감사를 계속하겠습니다.  질의하실 위원님 질의해 주시기 바랍니다.  임우영 위원님 보충질의 해주시기 바랍니다.
</p>
<p><b>○ 임우영 위원 </b> 원장님께 확인만 하고요.  아까 그러면 과제 이외에 개인적으로 주문과제죠.  공무원들의 주문과제가 많다, 연구에 차질이 있다라고 말씀을 하셨죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 주문과제라는 게 수시로 정책과제가 생기는 거죠.
</p>
<p><b>○ 임우영 위원 </b> 아니, 그런 게 많아서 연구에도 차질이 있을 수 있다라고 얘기하셨죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 글쎄요.  우리가 연구라고 얘기할 때 아까 전동석 위원님께서 지적하신 대로 순수하게 학문적인 연구뿐만 아니라 도정의 미래 비전에 관련된 장기연구라고 얘기를 할 수 있겠죠.  그런 연구가 많이 이루어져야 되는데 도에서는 또 필요에 따라서는 아주 단기적인 현안문제들이 많으니까 그런 걸 또 정책과제로 많이 줍니다.  그런 걸 연초에 계획하지 않았던 일을 많이 하게 되고 또 그뿐만 아니라 그걸 꼭 정책과제 형식이 아니고 아주 단기적으로 1주일이나 며칠 사이에 급하게 정책방향에 대한 결정을 위해서 필요로 하는 자료를 요청하는 경우가 있는데 제가 아까 설명드린 226건인가 금년 중에도 했다는 게 일종의 그런 것들입니다.  
</p>
<p><b>○ 임우영 위원 </b> 그 목록을 우선 자료로 주시고요.  이상훈 실장님께 제가 여쭤보겠습니다.  이상훈 실장님 나와 주세요.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기조실장 이상훈입니다.
</p>
<p><b>○ 임우영 위원 </b> 지금 연구원 인원이 몇이시죠?
