<p><b>○ 임우영 위원 </b> 연구원 중에 기본적인 과제, 수탁과제를 포함한 수행을 안 하고 있는 연구원이 있습니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 수행을 안 하고 있는 연구원은, 새로 임용이 돼서 48명 중에 1명 정도는 수습기간이 있습니다.  처음에 와서 본격적인 연구활동을 하기 전의 연구원이 있고요.  그다음에 기획조정실 내지 행정업무를 보는 연구원들이 있습니다. 
