<p><b>○ 임우영 위원 </b> 그 연구원은 몇 분 정도 됩니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 지금 부원장하고요, 그다음에 기조실장, 연구기획팀장, 정책분석팀장 그렇게 돼 있습니다.
</p>
<p><b>○ 임우영 위원 </b> 왜냐하면 제가 자료 요구를 한 것 중의 하나가 연구원별 수행 중인 과제명을 요구했는데 보니까 인원이 방금 말씀하신 대로 비어서 수행을 안 하고 있는 분들이 계신 것 같아서 확인을 한 거고요.
</p>
<p style="padding-left:1.2em">  아까 원장님께서 말씀하신 것 중에 긴급 도정 현안과 관련돼서 이런 주문이 왔을 때 그게 어떤 식으로 옵니까, 도에서?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 주문이 오는 경우 경우에 따라서는 과제형식으로 요청했는데 이것은 과제로 수행할 만한 비중이라든가 이런 게 안 된다라고 했을 때 CEO리포트라든가 다른 방법이 있고요.  또 하나는 주무부서에서 어떤 현안이 발생할 수가 있습니다.  그 현안에 대해서 유무선을 통해서 부탁을 하는 경우도 있고 아니면 원장님이나 다른 소스를 통해서 들어오는 경우가 있습니다. 
</p>
<p><b>○ 임우영 위원 </b> 담당 연구원에게 직접 오는 것도 있습니까? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 직접 오는 경우도 있습니다.  과제가 발생하는 게 자문하는 형식으로 저희한테 요청이 들어왔는데 전화상으로 답변을 하다가 그런 문제에 대해서는 좀 체계적으로 정리해서 우리가 제시하는 게 낫겠다고 했을 때 그런 과제들이 있고요.  대개 기간이 한 일주일 정도씩 걸리는 경우가 대부분 있습니다.
</p>
<p><b>○ 임우영 위원 </b> 그러면 그렇게 해서 주문이 와서 개발된 안들은 거의 다 정책에 바로 반영이 됩니까? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 대부분 아주 급한 초단기 현안과제인 제목들이 많고요, 타이틀도 그렇고.  그다음에 도 입장에서 앞으로 이런 상황이 벌어질 것 같다.  아마 도에 담당하는 주무부서에서 판단을 하는 경우도 있고 아니면 연구원 자체적으로 판단하는 경우도 있습니다.  이런 상황이 발생할 것 같다라고 그래서 미리 준비하는 경우도 물론 있지요.  
</p>
<p><b>○ 임우영 위원 </b> 그러면 일반적으로 연구원들이 연구하는 과제가 최고 많이 연구과제를 갖고 있는 분이 몇 개인지 알고 계십니까? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 현재 집계상으로는 20개 과제, 정식과제로 되어 있는 것이 20건 정도.
</p>
<p><b>○ 임우영 위원 </b> 아니, 연구원별 개인이 현재 수행 중인 과제 중에서 제일 많이 수행 중인 과제가 몇 개까지 하고 있는 줄 알고 계시냐고요.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네, 알고 있습니다.
</p>
<p><b>○ 임우영 위원 </b> 몇 개까지입니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 그것이 제일 많은 게 20건입니다.  
</p>
<p><b>○ 임우영 위원 </b> 그리고요?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 과제 형식으로 되어 있는 게 20건 플러스 지금 말씀드린 도정 지원현안에 대해서 한 자료 그런 식으로 이해해 주시면 되겠습니다.   
</p>
<p><b>○ 임우영 위원 </b> 그러면 그런 것이 과중하다거나 아니면 이렇게 도정 현안이 주문이 와서 연구에 차질이 있다면 어떤 것이 있다는 것입니까?  연구에 차질이 있다는 것은.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 저희가 통상 판단하기에는 약 3～3.5개 과제를 하는 것이 연구원 한 사람당 일반적으로 알려져 있는 적정규모라고 판단하고 있습니다.  거기에 3.5과제 플러스 지금 보고드린 도정 지원이라든가 부수적인 업무들이 있는데 현재 저희 같은 경우 책임이 한 4.3과제 그리고 공동이 한 5과제 그래서 약 9.8과제.  연구원 평균이 그렇습니다. 
