<p><b>○ 기획조정실장 이상훈 </b> 그렇게 해서 제일 많은 게 20개 과제입니다.  그러니까 3.5과제를 수행하는 게 적정하다고 봤을 때 20개 과제라고 판단해 주시면 되겠습니다. 
