<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 임우영 위원 </b> 제가 그냥 간단하게 말씀만 드리겠습니다.  지금 말씀하신 것처럼 이렇게 가지고 있는 자기의 연구할 과제가 굉장히 과중합니다.  그렇죠?  그러다 보니까 이것이 다시 정책으로 피드백될 수 있는 그런 것을, 공무원들은 바로바로 그런 것을 요구하기 때문에 충분한 시간을 갖고 연구한 과제물이 있는데도 불구하고 당장에 쓸 수 있는 엑기스만 뽑아서 요약한 도정 현안에 대한 보고서를 별도로 요구하는 사례도 저는 있다고 들었습니다.  그래서 이런 것을 감안해서 원장님께서 도정과 관련된 것은 연구원에게 바로 전화하고, 시간을 다툰다라고 얘기를 하는데 제가 봤을 때 시간을 그렇게 다퉈서 할 것 같으면 공무원들 스스로도 할 수 있습니다.  전문적인 것만, 필요한 사항만 전화로 물어서 확인해서 자기네들이 해야죠.  실질적으로 연구원들이 시간을 갖고 충분히 연구할 수 있는 시간을 주거나 아니면 그와 같은 연구된 것을 참고로 해서 정책에 반영할 수 있는 방법 이런 걸 좀 강구해 주시고요.
</p>
<p style="padding-left:1.2em">  또 하나는 물론 도에서 출연한 연구기관이긴 하지만 어느 정도의 체계는 잡아줘야 되겠다.  도정 현안에 관련된 사안이 있으면, 예를 들어서 부원장님을 채널로 한다든가 기조실장을 채널로 한다든가 하는 그런 체계적인 것도 갖춰주면 좋겠다 하는 개인적인 생각이 있어서 전동석 위원님 질의에 대해서 보충질의를 했습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 아주 좋은 지적이라고 생각이 되고요.  또 그 취지에 대해서도 제가 동감입니다.  그래서 아까 이상훈 실장이 얘기했지만 일을 한다는 게 서로 사람을 알고서 일을 하는 거기 때문에 채널을 하나로 통로를 단일화한다고 해서 꼭 그렇게 되지는 않습니다.  그러니까 연구하는 사람들을 상대로 해서 대화가 되기 때문에 그렇습니다마는 지금 연구원에서는 기획조정실에 정책분석실을 만들어 가지고 단기적인 현안 이런 문제는 정책분석실을 통해서 걸러지게 하고 있는…….
</p>
<p><b>○ 임우영 위원 </b> 그런 시스템이 있습니까? 
