<p><b>○ 경기개발연구원장 좌승희 </b> 우선 조례에 나와 있는 사항과 꼭 워드 바이 워드, 1 대 1로 매치는 안 되지만 넓게 해석을 하면 그런 사항이 포함될 수 있지 않을까 하는 그런 면도 없지 않아 있습니다마는 그럼에도 불구하고 아마 이 정관을 바꿀 때 저희가 그 조례에 관심을 덜 뒀던 게 아닌가 하는, 저희 불찰이 아니었나 하는 생각이 들어서 이것이 통과된 다음에 연구원에서 도하고 협의하면서 어떻게 하면 조례하고 맞춰서 해야 될지에 대한 고민을 하고 있었습니다.  그래서 지적하신 것에 대해서는 추후에 도나 위원님들하고 상의를 해서 정관과 조례가, 전체적인 정신이나 큰 틀에서 뿐만 아니라 좀 더 구체적으로 매치가 될 수 있도록 바꾸는 데 노력을 하도록 하겠습니다. 
