<p><b>○ 이해문 위원 </b> 그런데 아예 과제를 받을 때 여기에 해당 연구원이 없다든지 특별한 사유가 있어서 하기 어려운 것들에 대해서는 다른 기관으로 할 수 있는 방법도 있고, 또 여기서 위탁을 받았을 경우에는 나중에 책임소재가 있는데 그런 부분에 대해서 앞으로 계획이 있으면 말씀해 주시기 바랍니다. 
