<p><b>○ 경기개발연구원장 좌승희 </b> 현재 하고 있는 것이, 아까 전동석 위원님이나 임우영 위원님께서도 이미 지적을 했습니다마는 도의 연구 수요가 워낙 많다 보니까 우리 연구원 안에 있는 연구인력으로는 사실 다 감당하기가 어려운 경우가 많습니다.  그래서 어떤 경우에는 도에서 연구수탁을 받고 그 전체를 외주를 주는 경우도 있고 일부에 대해서 외주를 주는 경우도 있고 도 말고 다른 쪽에서 들어오는 수탁과제에 대해서도 그런 경우가 많이 있는데요.  그런 경우에 항상 우리가 중요한 것은 책임자를 분명하게 정하고 관리책임을 분명히 하기 때문에 그런 관리상의 문제는 아직까지 별로 없었습니다.  그렇지만 외주를 주다 보면 소홀하게 하는 경우도 없지 않아 있기 때문에 그 점을 감안해서 철저히 관리하도록 하겠습니다. 
</p>
<p><b>○ 이해문 위원 </b> 잘 알겠습니다.  그것은 앞에 다른 위원님들의 질의가 있었기 때문에 제가 더 이상 질의하지 않겠습니다.  단 아까 정관의 변경과 관련돼서는 필요하다면 의회에서도 조례를 개정하는 것을 검토하겠습니다마는 경기개발연구원에서도 그런 필요시에는 조례에 대한 건의를 해주시기 바랍니다. 
