<p><b>○ 진종설 위원 </b> 지난번에 본 위원이 연구용역을 당부드렸는데 책자 779페이지에 보니까 9월부터 해서 12월에 끝난다고 기록이 된 걸 봤습니다.  본 위원이 작년부터 말씀드려서 이것을 과제로 채택해서 지금 연구하고 계신데 저는 시급성 때문에 계속 말씀드렸는데 좀 늦어지는 것에 대한 유감을 표시하면서요.  한류우드가 도에서 수행하는 사업이고 특별회계로 예산이 집행되고 투자비를 회수하는 것 아닙니까? 
</p>
<p><b>○ 사회문화연구부장 김흥식 </b> 네.
</p>
<p><b>○ 진종설 위원 </b> 그렇기 때문에 한류우드 조성과 관련해서 용역결과가 빨리 나와서 같이 수행이 돼야만 투자비 회수도 될 뿐만 아니라 연계해서 할 수 있기 때문에 그렇게 말씀을 드린 거거든요.  그리고 지금 보면 9월부터 12월까지면 한 3～4개월인데 3～4개월 가지고 제대로 된 용역결과가 나올 수 있겠습니까?  
</p>
<p><b>○ 사회문화연구부장 김흥식 </b> 위원님이 말씀하셨듯이 사실 이게 굉장히 중요한 사안이고요.  그리고 문화관광적인 측면에서 접근되는 것보다는 어떻게 보면 기술적인 부분에, 환경문제라든가 교통문제라든가 다른 도시계획파트의 그런 문제와 연계돼 가지고 종합적인 연구가 진행돼야 되는 그런 과제의 성격으로 생각하고 있고요.  그래서 제가 생각하기에는, 사실 위원님하고 지난 봄에 한번 만나 뵙고 과제에 대한 의뢰를 해주셨는데 과제가 좀 늦게 성립이 되긴 했지만 사실 그전부터 이 과제에 대해서 한번 기술적인 타당성이 과연 있는가에 대한 부분에 대해서, 저희가 연구를 진행해야 되는가 하는 부분에 대해서 한번 검토해 봤습니다.  그래서 기술적인 부분에 상당히 어려운 점이 노정이 됐고요.  그래서…….
