<p><b>○ 사회문화연구부장 김흥식 </b> 사실 한류우드 이쪽이 기반이 더 낮은 지면이기 때문에 말하자면 그쪽에 배수관문을 연다고 그랬을 때는 침수의 우려가 상당히 있었고요.  그 부분이 상당히 가장 큰 우려의 하나였던 것이고, 또 하나는 사실 저희가 한류천이라고 명명하긴 했지만 사실 구거의, 하천으로서의 어떤 지위를 갖고 있지 못하는 사항이어서 지금 경기관광공사가 그쪽 고양관광문화단지 내에 중앙배수로 형태로 명칭이 되어 있어서 그래서 그것과 연계해서 연구를 진행하기 위해서 9월에…….
</p>
<p><b>○ 진종설 위원 </b> 사실 제가 박사님한테 용역을 부탁드렸던 건 한류우드가 관광문화에, 경기도에 여러 가지 첨단 유비쿼터스라든지 등등이 거기에 도입이 될 텐데 이런 것 등을 하면서 아주 수려한 한강을 끼고 있는 고양시로서는 연계해서 개발하면 그야말로 어느 나라에서도 볼 수 없었던 특화적인 또는 특색적인 면모를 갖출 수 있겠다 해서 부탁을 드린 거고.  그래서 말씀을 다시 드리자면 이것이 지금 3개월 가지고는, 이게 소운하로 연결이 돼야 될 텐데.  아까도 침수 우려라든지 이런 것 등을 염려하시고 문제점이 있다고 그러셨는데.  어쨌든 이명박 대선 후보께서도 지금 한반도 대운하를 공약으로 걸고 계신데 한강에서 1～2㎞뿐이 안 되는 한류우드 내 60m 수로 연결하는 소운하 정도라면 큰 어려움 없이 할 수 있겠다 이런 생각을 가지고 있거든요.
</p>
<p><b>○ 사회문화연구부장 김흥식 </b> 그런데 저희 연구자 입장에서 판단하기는 이게 기술적으로 어떤 문제가 있더라도 극복은 가능할 것이라고 생각은 하고 있습니다.  그래서 지금 두 가지 방법으로 접근하고 있습니다.  현실적인 안으로 해가지고 기존에 있는 부분을 잘라가지고 연계하는 어떤 그런 부분하고 전체적으로 그런 쪽을 다 극복해 나가서 배수관문의 높낮이의 차이를 극복하는 그런 방향으로 해서 직접적으로 한강과 연결시키는 방안 두 가지로 접근을 하고 있는데 가장 중요한 문제는 할 수 있다 하더라도 과연 이게 사업성이라든가 사업성의 검토에 따라서 사실은 불필요하게 되는 사업도 있기 때문에 그 부분이 아직까지 확신이 안 서고요.  그래서 지금 두 가지로 일단 접근해서 12월 중순쯤에는 두 가지 안에 대한 것을 저희가 조금 마쳐서 위원님하고 전문가들을 모시고 사전에 스크린을 받는 그런 자리를 가지려고 지금 계획은 하고 있습니다. 
</p>
<p><b>○ 진종설 위원 </b> 저는 공격적인 연구용역을 통해서 본 위원이 의도하는 바를 충분히 이해하셔서 좋은 결과가 나오기를 기대해 봅니다.  김문수 지사께서 한강하구 개발에 대한 타당성 용역을 연구원에다 던진 걸로 알고 있는데 원장님께 답변 부탁드리겠습니다.  됐습니다.  김흥식 박사님 들어가셔도 좋습니다.  원장님이 그 내용을 잘 모르시면…….
