<p><b>○ 진종설 위원 </b> 그렇게 하겠습니다.  어쨌든 나는 벌써 용역 중에 있는 걸로 판단돼서 지금 말씀드렸던 건데 북한하고의 협의문제라든지 여러 가지 걸림돌이 상당히 있을 겁니다.  그래서 한강하구 개발은 남북한에도 지금 아주 긴장 국면이 많이 해소가 되면서 상당히 기대를 하고 있는 부분인데 경제적으로도 아마 큰 파급효과가 있을 걸로 여겨집니다.  철저하게 연구를 잘해내셔서 남북관계가 해소될 뿐만 아니라 그걸로 인해서 북한에도 경제적인 큰 도움이 됐으면 하는 바람에서 철저하게 해 주십사 하는 당부를 드립니다.
</p>
<p style="padding-left:1.2em">  이어서 809페이지에 보면 기금의 운용 및 관리가 있습니다.  지금 기금이 272억원이 있는데 전체 예치를 한 걸 보면 5～6년, 짧게는 1년 이렇게 있는데 이게 지금 원금 집행은 전혀 하지를 않고 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇죠, 기금은.
</p>
<p><b>○ 진종설 위원 </b> 이자수입을 우리 예산에 반영하고 있는 건데 그래서 보면 이렇게 기금을 운용하면서, 장기적인 예치를 하면서 이율이 큰 차이가 많아요.  지금 많게는 7.2%부터 적게는 4.87% 이게 차이가 굉장히 많은데 이걸 금리별로 계산을 해 보면 한 7억여원 정도가 기금운용을 어떻게 하느냐에 따라서, 어느 은행에 몇 %의 금리로 예치를 하느냐에 따라서 7억여원 정도의 손해를 보고 있다고 본 위원이 판단이 되거든요.  이거 기금 운용에 문제가 있는 것 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 만기가 되면 새로운 운용처를 찾아가고 그럴 때 결재를 할 때마다 항상 금리가 얼마냐, 상대적으로 얼마나 이게 높은 것이냐 하는 걸 항상 따지고 최선을 다하고 있습니다만 우리 기금을 낸 기관이 있기 때문에 일부 기금을 그 기관에다 예치해야 되는 불편도 없지 않아 있고요.  어떤 건 과거에 금리가 낮을 때 들어간 게 아직 만기가 안 된 것도 있고 여러 가지 현실적으로 금리를 일률적으로 높게 운용하기가 쉽지 않은 점이 있습니다만 더 공격적으로 운용한다면 펀드라든가 이런 쪽에도 예치할 수 있지만 그런 경우에는 또 원금에 손상이 올 수도 있고 그래서 아주 보수적으로 하고 있습니다.
</p>
<p><b>○ 진종설 위원 </b> 물론 채권과 정기예금이 이렇게 구분이 돼 있는데 어차피 장기예치를 할 거면, 그렇다고 한다면 이자수익을 가지고 예산에 반영하고 할 정도라면 차라리 전체를 금리가 높은 쪽으로 좀 조정을 해서 예치를 하면 7억여원 정도의 이자수익을 더 올릴 수가 있고 지금 보면 272억원 중에서 214억원이 저금리 쪽으로 판단이 되고요.  58억원만 10%대 금리 신한은행인데, 이렇게 돼 있거든요.  그래서 이건 충분히 아까 말씀드린 대로······.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리 실무자한테 제가 배경을 설명 듣고 올려도 괜찮겠습니까?  지금 신한은행이 제일 높은데 6년짜리고 그 밑에 제일은행, 농협, 외환은행 이런 데가 상대적으로 싼데 이게 왜 그런지 설명을 좀······.
</p>
<p><b>○ 재정지원과장 강윤구 </b> 재정지원과장 강윤구입니다.  이건 예치시점에 상품조사와 최고 금리로 저희가 운용을 했습니다만 그 후순위채권 당시에, 정기예금상품이 예치된 당시에는 후순위채권이나 고금리상품이 없어서 기금 만기시점마다 운용을 하다 보니까 저희가 상품의 이율이 차이나게 됐습니다.  현재 한국은행 발표 금리는 10월 말 현재 5.24입니다.  그래서 저희 나름대로는 최선을 다해서 운용했는데 기금의 만기시점에 따라서 이율을 달리 받았습니다.  하여튼 최고 상품으로 운용하려고 노력을 했습니다. 
</p>
<p><b>○ 진종설 위원 </b> 좋습니다.  그러면 본 위원이 자료를 한 가지만 요청을 하겠습니다.  최초 예치 일자별로 해서 내역을 뽑아 주시기 바랍니다.
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 알겠습니다. 
</p>
<p><b>○ 진종설 위원 </b> 앞으로 기금운용을 철저히 해서 최고 금리 금융기관으로 예치를 해서 이자수익을 더 철저히 놓치지 말고 올릴 수 있도록 해주시기를 당부드립니다.  됐습니다.  들어가셔도 좋습니다.
</p>
<p style="padding-left:1.2em">  아까 위원님들께서 질의해 주신 것 중에 보충이 되겠는데요.  연구원별 연구실적이 지금 상당히 많고 또 연구수요가 상당히 많은데 그렇다고 한다면 이게 업무가 과중되고 이럴 텐데 외부강사 출장이 상당히 있는 걸로 본 위원이 판단이 되거든요.  그렇게 과중한 연구수요가 있음에도 외부 출장강의를 갈만한 여유가 있습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아주 제한적으로 하고 있습니다.  그러나 저는 원장으로서의 제 방침이기도 합니다만 연구원 박사들이 현실적인 정책연구를 통해서 얻은 바를 학생들한테 강의를 통해서 전달하거나 일반사회에 이런 강의를 통해서 사회에 많이 알리고 하는 건 연구원 명예를 위해서도 그렇고 연구원의 비저빌리티(visibility)를 높이는데 아주 도움이 되기 때문에 아주 특별히 불가한 경우를 빼놓고는 능력 있는 연구원들은 그런 일을 여유가 있어서 할 수 있으면 하도록 하고 있는데 그게 지적하신 대로 연구원 전체 업무하고, 로드하고 서로 안 맞는 경우가 있죠.  그래서 저희가 그런 문제를 대처하기 위해서 어느 연구나 오는 걸 다 우리가 할 수 없습니다.  그리고 연구라는 게 인(in) 하우스의, 연구원 안의 모든 사람을 다 가지고 전부 다 그냥 안에 있는 사람이 하는 건 대단히 비효율적인 방법이죠.  그래서 연구를 잘 관리할 수 있는 사람을 둠으로써 아까 여러 위원님들이 지적하셨지만 위탁이라든가 외부의 연구인력을 활용해서 연구를 관리하는 그런 일을 함으로써 연구 부담을 또 줄일 수 있는, 숫자가 많다고 해서 그 사람이 연구시간을 많이 투입하는 건 아닌 경우가 많죠.  그렇기 때문에 이게 굴러갈 수 있는 것 아니겠습니까?  그렇게 해서 외부에 주고 또 필요하면 초빙으로 저희가 연구요원을 모셔서 하는 그런 여러 가지 다각도의 방법을 활용하고 있습니다. 
</p>
<p><b>○ 진종설 위원 </b> 잘 알겠습니다.  연구원의 수장으로서 이런 것을 잘 좀 운영관리를 통해서, 본 위원이 보기에는 이런 수요가 많다고 답변을 하시면서 또 외부출강 현황을 보니까 이렇게 또 나오고 그렇다고 한다면 답변이 어떤······.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 일관성이 없다 이렇게 들리시는 거죠?  그런데 그 문제를 아까 말씀대로 풀기 위해서, 그러니까 저는 연구활동은 항상 연구결과를 가지고 연구원의 위상을 높이는 방향으로 활용하는 게 필요한 일이라고 생각을 하기 때문에 그 일을 하면서 또 많은 연구수요를 수용할 수 있는 다른 대안이라든가 보조수단을 찾아서 이렇게 해 나가고 있습니다.  그래서 여러 위원님이 다 지적하셨지만 현실은 또 현실대로 저희가 해야 될 일은 또 있는 것이죠.  아무리 이상적으로 얘기한다고 그래서 그게 되는 건 아니기 때문에 그런 현실적인 어려움을 풀기 위한 노력을 나름대로 하고 있고 최선을 다하도록 하겠다는 약속을 위원님들한테 드리겠습니다.
</p>
<p><b>○ 진종설 위원 </b> 알겠습니다.  좌우간 능력 있으시고 고매하신 좌승희 원장님께서 이끄시는 우리 경기개발연구원이 경기도의 모든 정책을 연구하는 데 있어서 탁월한 실적을 내주실 것을 당부를 드리면서 이상 질의를 마치겠습니다.  감사합니다.
</p>
<p><b>○ 위원장 김영복 </b> 진종설 위원님 수고하셨습니다.  우리 진종설 위원님께서 한류우드연구사업과 관련하여, 또 한강하구 개발과 관련해서, 또 기금운용과 관련해서 세 가지 질의를 하셨는데 여기에 대해서 보충질의하실 위원님 계십니까?  보충질의 안계시면 정인영 위원님 질의해 주시기 바랍니다.  
</p>
<p><b>○ 정인영 위원 </b> 양평 출신 정인영 위원입니다.  감사준비와 감사를 받으시느라고 수고가 많으십니다.  경기개발연구원 중장기 발전계획에 대해서 원장님께 질의를 하겠습니다.  경기개발연구원을 최고의 연구기관으로 발전시켜 경기도정에 싱크탱크의 역할을 할 수 있도록 하고자 하는 매우 중요한 중장기 발전계획을 보았는데 연구원의 중장기 발전계획에 특별한 내용 있으면 간단히 답변해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 내용이 많은데요.  현재 저희가 GRI 비전 2015 작업을 진행 중에 있습니다.  지금 마무리를 다 못했습니다.  저희 부원장 중심으로 1차 작업이 끝나서 한 번 토론회를 가졌고 이제 추후에 이걸 좀 더 원내 박사들의 의견을 집약해서 최종적인 안을 가지고 또 도하고도 협의를 해서 발표할 계획입니다만 그렇기 때문에 이게 최종적인 거라고 할 수는 없고요.
</p>
<p><b>○ 정인영 위원 </b> 자료로 갈음하도록 하고요.  중기발전계획 책자 37페이지 동기유발시스템의 정비분야에 대해 묻겠습니다.  연구원 인사관리규정 제9조제2호의 재임용제도에 의하면 “연구직 최초 임용 및 최하등급 평가 시 계약기간은 1년 이내 평가결과와 3년 연속 상위 25%인 경우 계약기간은 5년 이내, 기타의 경우는 3년 이내로 하되 평정결과 3년 연속 최하등급을 받은 자는 재임용하지 않을 수 있다.”라고 규정하고 있는데 경기개발연구원 설립 이후 지금까지 3년 연속 최하등급을 받아서 재임용하지 않은 예가 있습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아직 이 조항에 의해서 재임용을 받지 않은 사람은 없습니다. 
</p>
<p><b>○ 정인영 위원 </b> 없죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 정인영 위원 </b> 평가위원의 구성은 어떻게 하고 있으며 외부 평가위원이 있는지 답변해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 연심회를 통해서 프로젝트 결과에 대해서는 항상 외부 전문가를 모셔서 평가를 하고 있고요.  모든 1년 동안의 연구결과를 종합적으로 평가하는 과정에서는 집행부에서 그걸 다 검토를 해서 평가를 내리고 있습니다.  그래서 외부 전문가가 항상 참여를 하고 있습니다.  
</p>
<p><b>○ 정인영 위원 </b> 어저께 수능시험을 봤습니다만 경기도 외고에서 시험문제 유출과 관련된 큰 사건이 터졌습니다.  그것은 평가가 제대로 되어야 사회가 공정성을 담보하고 제대로 된 사회로 나갈 수 있는데 이러한 가장 중요한 교육부분에서 평가가 공정하지 못한 그런 구조적인 모순을 갖고 있고 해서 상당히 경기도에서도 어려운 상태에 있고 이런 평가가 좀 더 공정하게 이루어질 수 있도록 해 주셨으면 고맙겠다고 하는 말씀을 드리고 종신고용제도의 도입을 한다고 하셨는데 종신고용제도의 도입, 물론 중장기 발전계획안입니다만 이 점에 대해서 답변해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 종신고용제도라는 걸 그냥 이렇게 쓰니까 이상하게 들립니다만 학교에서 이걸 테뉴어 시스템이라고 얘기를 합니다.  일정 기간 이상 그 사람의 연구역량이 확인되면 정년까지 재임용을 안 하는 거죠.  그런 의미에서 종신입니다.  그런데 우리 연구원은 제가 와서 보니까 아까 얘기한 대로 1년 단위, 3년 단위, 5년 단위 이렇게 다······.  그래서 현재 여기에 있는 연구진이 전부 다 3년, 5년마다 재계약을 하도록 돼 있거든요.  그래서 이게 조금 연구원의 안정성에 문제가 될 수 있다.  그래서 적어도 10년 이상씩 근무를 하고 연구를 해서 이 사람을 스타라고 표현하기는 어렵지만 충분히 연구역량이 검증됐다고 그러면 정년까지 갈 수 있도록 하는 그런, 기간은 여러 가지 고려가 있을 수 있습니다만 그런 테뉴어 시스템을 좀 도입해야 되지 않겠느냐 하는 그런 취지로 이해해 주시면 되겠습니다.
</p>
<p><b>○ 정인영 위원 </b> 테뉴어 시스템이 아직 도입이 안 됐는데 카이스트 같은 데서는 테뉴어 시스템을 개혁한다고 그래서 세간의 이목을 집중시켰는데.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우린 이거 없습니다.
</p>
<p><b>○ 정인영 위원 </b> 여하간 이런 모든 부분이 실력 있고 능력 있고 인정받을 사람들이 인정을 받아야 되는 그런 사회가 되려면 평가가 제대로 이루어져야 된다고 생각이 돼서 여쭤봤고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 120% 그 점에 대해서는 동감합니다.
</p>
<p><b>○ 정인영 위원 </b> 제가 작년도 행감 때도 질의를 하고 지적을 했습니다만 인력 채용에 있어서 정원이 85명인데 현원이 71명이에요.  14명이 결원인데 관리직 15명, 정보직 5명 해서 20명은 100% 충원이 돼 있는데 연구원의 기능은 연구를 주업으로 하는 연구직이 100% 충원이 돼서 조직에 활성화를 꾀해야 되는데도 불구하고 계속해서 결원이 13명씩이나 있다는 말씀이에요.  충원이 안 되는 이유가 뭡니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우선 제 능력의 부족이 아닌가 하는 생각이 듭니다.  제가 1년 반 동안 연구인력 충원을 위해서 우리 홈페이지를 항상 열어 놓고 수시채용시스템으로 바꾸어서 열심히 노력을 하는데도 사실은 그렇게 우리의 뜻에 맞는, 수준에 맞는 사람을 구하기가 그렇게 쉽지가 않았습니다.  그게 여러 가지 이유가 있었습니다만 그래서 금년에 저희가 페이 수준을 상당한 정도로 보완을 했고 그래서 앞으로 좀 나아지지 않을까 싶은 생각이 드는데요.  아무 사람이나 뽑을 수는 없잖아요.  그래서 저희 전략이 아까도 말씀드렸지만 외부에서 유능하지만 우리가 그분을 그냥 돈을 많이 주고 뽑을 수는 없고 조금 시간적인 여유가 있는 원로 이런 중견 이상의 사람들을 초빙해서 쓸 수도 있고 안 그러면 젊은 프레시 피에이치(Fresh Ph)들을 초빙해서 쓰는 식으로 해서 우리가 필요할 때 필요한 분야에 적극적으로 활용할 수 있는 시스템을 가능한 활성화하면서 우리가 정규직은 정말 고급인력으로 채워나가자 하는 전략으로 하고 있는데 채우는 데 애로사항이 있습니다.  그래서 내년부터는 좀 나아지지 않을까 하는 생각이 들고요.
</p>
<p><b>○ 정인영 위원 </b> 그렇습니다.  지금 한 사람의 인재가 전 국민을 먹여 살린다고 하는 시대 아니겠습니까?  그런데 교육도 하향 평준화돼 있고 또 나라도 균형 발전시킨다고 하향 평준화시키는 정책들을 쏟아내고 있고 또 정치권에서 그런 트러블들을 잘 조정하고 화합하고 한데 모으는 작업들을 해야 되는데도 불구하고 또 그렇지 못하고 해서 상당히 총체적 난국으로 흐르고 있다는 것을 부인하지 못하는 것은 사실입니다.  제가 6대 때에도 지사님이나 전 원장님한테 “왜 충원하지 않느냐?” 하는 질문을 했을 때 답변이 “마땅한 사람이 없다.” 이런 답변을 해서 ‘왜 사람이 없을까?  분명히 지금 직장을 구하지 못하는 박사급 우수한 인력들이 있고 한데 마땅한 사람이 없다고 하는 건 문제가 있지 않느냐.’ 하는 그런 생각을 했는데 답변 중에 말씀하셨습니다만 그건 구조적으로 대우문제, 또 페이 문제가 좀 충분히 연구에 전념할 수 있도록 제도적으로 준비를 해 놓고 사람을 구해야 되겠다 하는 생각이 드는군요.  그래서 의회에서도 그런 점에서 조금 뒷받침이 될 수 있다는 생각을 해 보면서 여하간 우수한 인력으로 충원시켜 주시기를 바랍니다. 
</p>
<p style="padding-left:1.2em">  마지막으로 질의를 드리겠습니다.  포괄적인 질의가 되겠습니다만 원장님께서 연구원에 오신 지 한 1년 되셨죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 1년 반 가까이 돼 갑니다.
</p>
<p><b>○ 정인영 위원 </b> 1년 반 됐습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아직 다 되지는 않았습니다.
</p>
<p><b>○ 정인영 위원 </b> 사실상 원장님께서 연구원 원장으로 오실 때 아마 저희 의회뿐만 아니라 경기도, 또 경기도민들이 많은 기대를 가지고 있었습니다.  참 석학을 이런 경기도 경기개발연구원에 모시게 된 것은 저희로서는 상당히 잘된 일이다 이런 평가를 했고 저렇게 훌륭하신 분이 이렇게 여러 가지로 열악하고 힘든 상황 속에서 이루어지는 경기개발연구원에 오셨다고 하는 자체만으로도 상당히 기대가 컸었습니다.
</p>
<p style="padding-left:1.2em">  그런데 경기도의 주요 도정 현안을 보면 아직 평가하기에는 이르겠습니다만 수도권 경쟁력 강화하고 관련해서 사실상 어떤 측면에서는 투쟁 일변도로 가는 것 아니냐 하는 그런 느낌을 본 위원이 가졌었고요.  논리를 개발하고 또 분명히 우리보다 더 힘든 지역, 또 비수도권 지역이 어려운 건 사실 아닙니까?  이분들 설득하고 이해시키는 데 더 주력을 해야 됨에도 불구하고 여하간 동의를 받지 못하고 있다.  우리의 주장이거든요.  경기도의 주장이 경쟁력 강화와 관련해서 동의를 받지 못하고 있다고 하는 그런 말씀을 드리고, 또 두 번째로 주요 도정 현안에 광역교통정책이 있는데 지금 행감 중입니다만 신문지상의 보도를 보면 6,000억 내지 1조가 도민 부담으로, 혈세로 부담이 되고 있다 하는 이런 지적들이 있고요.  또 이것은 김문수 지사 치적으로 얘기가 되고 있는데 그렇다면 6,000억 내지 1조씩 들여서 광역교통정책이 과연 성공한 정책이냐 아직 평가하기에는 이르겠습니다만 중간평가를 할 단계가 오지 않았느냐 하는 생각을 해 보고요.
</p>
<p style="padding-left:1.2em">  그다음에 팔당종합대책도 마찬가지입니다.  그동안 경기도에서 팔당수질대책본부라고 하는 조직을 만들고 직급을 높이고 인력을 충원하고 했는데 예산은 안 늘어난다는 말씀이에요.  그러면 물이 사람 늘리고 조직 늘린다고 그래서 팔당 1급수가 깨끗해지는 것 아니고 사람 늘리고 조직 늘리면 결국은 규제밖에 할 게 없습니다.  그런 측면에서 한번 짚고 넘어가야 되는 게 아니냐 하는 생각을 해보고 뉴타운사업과 관련해서는 아직 가시적 성과가 없기 때문에 언급을 회피하겠습니다만 경기도의 싱크탱크로서, 또 싱크탱커로서 이러한 총제적인 난국을 어떻게 헤쳐 나갈 것이냐, 물론 집행은 경기도청에서 하겠지만 경기개발연구원에서 원장님 이하 박사님들께서 어떤 방향 제시를 해 주셔야 되는 것 아니냐 이런 생각이 들어서 원장님의 고견을 듣고 싶습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 좋은 말씀 주셨고요.  우선 제가 답변할 수 있는 말씀은 저희 연구원이 할 일을 다 못했다 하는 그런 질책으로 우선 듣겠습니다.  이 정책들이 지금 가고 있는 방향이나 하고 있는 내용이 옳으냐 그르냐 하는 건 사실 지금 이 단계에서 저희가 쉽게 판단하기는 어렵겠죠.  결과적으로 어떤 성과를 가져오느냐 하는 건 좀 더 두고 봐야 될 문제기 때문에 이 시점에서 그런 평가를 내리는 건 대단히 좀 위험하다 하는 생각이 듭니다.
</p>
<p style="padding-left:1.2em">  그러나 지금 위원님께서 지적하신 전체적인 흐름이라든가 문제에 대한 의식은 저희들도 비슷한 생각을 가지고 있습니다만 개별사항에 대해서 저희가 구체적으로 대안을 내거나 하는 그런 일은 하지 못했기 때문에 우선 제가 드리고 싶은 건 충분히 저희가 기대에 부응하지 못했다는 점에 대해서 죄송하다는 말씀을 드리고요.  
</p>
<p style="padding-left:1.2em">  이게 4대 도정 현안을 지금 다 언급을 해 주셨는데 이 4대 프로젝트가 전부 다 선거과정을 통해서 설정이 됐고 이게 도의 가장 중요한 정책으로 셋업이 됐기 때문에 이것 자체에 대해서 저희가 연구원으로서 할 수 있는 일은 첫째는 이런 일을 효율적으로 하기 위한 방법이 뭐냐 하는 걸 일단 검토하는 것이고 두 번째는 그게 문제가 있다고 하면 어떤 개선방안을 가지고 갈 거냐 하는 것이고 만일 이게 정말 안 되겠다고 그러면 정말로 대안을 제시하는 이런 세 가지 단계를 거쳐야 되지 않을까 싶은데 세 번째 단계까지는 아직 갔다고 볼 수는 없고요.  제가 지금까지 한 건 이걸 적극적으로 효율적으로 추진하는 방법이 뭐냐, 거기에 좀 더 효율적으로 하는 방법이 뭐냐에 대한 취지를 가지고 연구를 하고 대응을 해 왔는데 우선 수도권 경쟁력 강화 문제는 저도 안타깝습니다.  이게 지사님이 그렇게 적극적으로 나선다고 그래서 사실 중앙 정치권이 이 문제를 쉽게 풀어줄 것 같은 생각도 안 들고 그렇다고 저희 연구원이 논리적으로 아무리 균형발전의 문제점을 얘기한다고 그래서 중앙정부가 움직일 수 있는 가능성도 그렇게 있어 보이지는 않고요.
</p>
<p style="padding-left:1.2em">  그러나 저희 연구원이 지난 1년 반 동안 이 문제에 대해서 국내 어느 연구원에 비해서도 적극적으로 소신껏, 말하자면 이걸 꼭 경기도를 대변한다고 하는 입장이 아니라 수도권 균형발전정책이 갖는 국가 정체현상이랄까 이런 걸 홍보를 하고 하여튼 노력을 많이 했지만 충분히 저희가 효과를 얻어내지 못했다는 점에 대해서는 죄송하다는 말씀을 드리겠고요.  그럼에도 불구하고 제 생각에는 지사님이 경기도 내에서 낙후지역과 그렇지 않은 지역 간의 균형문제를 대단히 심도 있게 고민하고 있다는 걸 저희가 압니다.
</p>
<p style="padding-left:1.2em">  그래서 아까 저희 연구프로젝트 중에 북부와 동부부분에 대한 연구를 계속 강조하고 있는데, 물론 저희가 충분히 대처를 하고 있지는 못하지만 심정적으로라도 이게 정말로 중요하다 하는 걸 제가 충분히 감지하고 있고 특히 북부문제에 대해서는 저희 연구원의 통일연구센터를 사실은 북청의 산하연구기관으로 생각을 하시라고 제가 북청 부지사님한테 당부를 했습니다.
</p>
<p style="padding-left:1.2em">  그래서 적극적으로 연구원을 활용하시게 앞으로 만들어갈 것이고 양평이나 동부 쪽도 저희가 그동안 적극적으로 못한 점이 없지 않아 있습니다만 앞으로 계속해서 그쪽을 개발할 수 있는 방안을 강구하는 쪽으로 노력을 하고 팔당문제도 사실은 북부와 동부문제하고 직결돼 있습니다.  동부의 어려움이 다 팔당에서 오는 거기 때문에 지금 팔당센터를 만들어서 그동안 성과는 별로 없습니다, 저희 연구원이.  그렇지만 저희가 고민하는 것이 상수원의 이전문제까지도 지금 계속 논의가 되고 있고 그 외에 물을 깨끗하게 어떻게 하면 효율적으로 할 거냐 하는 이런 문제도 결국은 동부의 발전전략과 직결된 것이기 때문에 저희가 열심히 노력을 하겠습니다.
</p>
<p style="padding-left:1.2em">  그래서 물 문제는 이게 민감한 사안이기도 합니다, 상수원 이전문제가.  그러나 얼마 전에 저희가 받았던 프로젝트를 중단하는 일이 있었습니다만 그럼에도 불구하고 연구원은 연구원 나름대로 효율적인 방안을 찾기 위해서 내부에서 계속 고민을 하고 있고요.
</p>
<p style="padding-left:1.2em">  광역교통정책은 아까 지적하신 대로 그런 비판이 있는 걸 압니다.  알지만 일단은 수도권이라는 게 공동체기 때문에 어떻게 하면 네트워킹을 효율적으로 하느냐 하는 차원에서 전 반드시 필요한 일이라고 보는데요.  이걸 하는 과정에서 다소 서두르다 보니까 미흡한 점도 있었을 것이고 이런 점이 만일 있다고 하면 저희 교통정책팀이 이걸 만드는 과정에서 6개월, 한 1년 가까이를 도청에 파견 나가서 전원이 거기에 매달려서 했기 때문에 사업에 부족한 점이라든가 이런 걸 다 잘 알고 있기 때문에 향후에 그 개선점을 찾기 위해서 저희가 최선의 노력을 다하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  그래서 정 위원님이 지적하신 걸 충분히 취지도 이해를 하고요.  그렇기 때문에 앞으로 기대에 충분히 부응은 못하겠지만, 많은 역량도 아니지만 저를 포함해서 우리 연구원 박사들이 최선을 다해서 그런 잡음이 안 나오고 효율적으로 도정이 운영될 수 있도록 뒷받침하는 데 최선을 다하겠습니다. 
</p>
<p><b>○ 정인영 위원 </b> 진솔한 답변 고맙습니다.  경기도에서 바른 소리를 낼 수 있고 누가 뭐라든 그것을 이야기할 수 있는 곳은 바로 연구원이고 또 여기 계신 박사님들이고 원장님이라고 이렇게 생각이 됩니다.  그 역할을 충분히 잘 하고 계시지만 더 노력을 해 주시기를 바라고 특히 수탁과제하고 관련돼서는 위원들이나 기타 과업을 내려주는 기관의 입장도 있습니다만 그런 입장 고려하지 마시고 여러분들께서 소신껏 학문적인 양심에 따라 그대로 발표하고 잘못된 건 잘못됐다라고 지적할 수 있는 그러한 연구원이 되시기를 바라면서 제 질의 마치겠습니다.  이상입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 감사합니다. 
</p>
<p><b>○ 위원장 김영복 </b> 정인영 위원님 수고하셨습니다.  정인영 위원님께서 경기개발연구원의 중장기 발전계획과 관련해서, 두 번째 인력 채용과 관련해서, 세 번째는 김문수 지사 민선4기의 4대 공약에 대해서, 수도권 정책과 평가에 대해서 질의를 해주셨습니다.  여기에 대해서 보충질의하실 위원님 계십니까?  김대원 위원님 보충질의 해주시기 바랍니다. 
</p>
<p><b>○ 김대원 위원 </b> 의왕 출신 김대원 위원입니다.  수도권 경쟁력 강화에 대해서 보충질의 겸 본질의로 연결해서 하겠습니다.  수도권 경쟁력 강화는 우리나라 참여정부 들어와서 추진하고 있는 지방분권과 균형발전 부분에 대해서 균형발전과 수도권 경쟁력 강화부분이 상충돼서 경기도의 현안문제로, 심지어는 정무부지사가 취임 첫날부터 퇴임하는 마지막 날까지 시위장에 있었다라고 소감을 밝히고 떠나는 정도로 현실 문제로 대두되고 있습니다.  그런데 균형발전 부분에 대해서 과연 우리 경기도는 31개 시ㆍ군의 균형발전에 대해서 심각하게 고민하고 실질적으로 이행을 하고 있느냐 하는 부분에 대해서 제가 질의하고자 합니다. 
</p>
<p style="padding-left:1.2em">  지금 도청이 수원시에 있지 않습니까?  1967년에 서울에 있던 경기도청이 수원으로 이전될 때 수원시 인구가 혹시 얼마인지 아십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 죄송합니다.  제가…….
</p>
<p><b>○ 김대원 위원 </b> 구체적으로 필요 없습니다.  그때 경기도 공무원수가 167명이었습니다.  인천까지 합해서 167명이었어요.  그런데 수원시로 이전되고 나서 올 10월 말 현재 수원시 인구가 108만 7,000명입니다.  그래서 경기도를 대표하는 시를 꼽으라면 수원시를 꼽을 정도쯤 됐습니다.  그런데 수원시를 기점으로 해서 경기 중남부권에 있는 시 중에 과천ㆍ의왕시 인구가 혹시 얼마인지 아십니까?  현재 과천시 인구 약 7만에 의왕시 인구 14만입니다.  그런데 경기도청 이전계획을 잡고 있어요.  경기도청 이전계획이 ’95년 11월 27일 민선1기 딱 들어오자마자 첫 번째 한 게 도청 이전 건입니다.  그래서 지금까지 도청 이전문제가 쭉 거론되어 왔는데 공교롭게도, 강식 박사님 계십니까?  
</p>
<p><b>○ 도시지역계획연구부책임연구원 강식 </b> 네.
</p>
<p><b>○ 김대원 위원 </b> 잠깐만 계시지요.  거기에 대한 연구를 경기개발연구원에서 두 번 연구를 했습니다.  도청사 이전 타당성 및 청사 규모 검토연구를 2004년도에 했고요.  현재 도 신청사 기본계획 수립을 위한 사전검토연구를 하고 있는 걸로 알고 있습니다.  그런데 첫 번째 연구에 대한 결론은 도청이 만들어짐으로써의 역할입니다.  급격한 도시화, 광역화 과정에 있는 경기도에 새로운 생활권 및 도시공간 구조에 부응하여 청사 이전이 행정타운 조성방식 등을 채택할 경우 신도시 형성 및 신생활 거점으로 개발될 수 있을 것이라고 했습니다.  그것은 곧 무슨 얘기냐 하면 도청 이전이 조그만 중소도시 하나를 만들 수 있다라는 그런 뜻이기도 합니다.  그런데 과연 수원시 주변에 인근 되어 있는 거리에, 과천시 같은 경우에는 물론 중앙청사가 있습니다마는 중앙청사가 지방분권, 균형발전에 의해서 떠나는 계획을 잡았습니다.  이런 상황인데 굳이 인구 100만이 넘는 수원시에 이전해야 된다는 발상이 이게 31개 시ㆍ군이 균형발전하는 데 과연 우리가 수신제가를 하고 먼저 보여줄 수 있다고 생각하십니까?
</p>
<p style="padding-left:1.2em">  지방 균형발전의 첫 번째 이유는 모든 경제중심과 인구중심이 수도권에 모여 있기 때문에 이 수도권 경제와 인구를 지방으로 분산해야 된다라는 게 우리 수도권을 제외한 나머지 시ㆍ도에서 요구하는 현 상황이지 않습니까.  그 이유 때문인데 과연 31개 시ㆍ군을 거느리고 있는 우리 경기도가 중앙정부에 그런 논리를 따져서 수도권을 역차별한다고 우리 의원들까지 머리띠 매고 머리 깎고 이렇게 투쟁하면서 과연 수신제가해야 될 우리 경기도 차원에서는 뭘 했냐는 얘기지요.  지금 당장 인구 100만이 넘는 수원시에 도청사를 이전하겠다.
</p>
<p style="padding-left:1.2em">  그러면 새로 신도시가 되는 광교신도시에 유입인구가 8만명입니다.  거의 100만이 넘는, 현 110만에 육박되는 거대시에 다시 8만을 새로 수용하는 그런 데에 도청사를 이전하는 게 31개 시ㆍ군의 균형발전입니까?  거기에 대해서 정말 균형발전에 대한 최대의 논리개발자이시고 양심 있는 지식인으로 통하시는 좌승희 원장님이 경기도의 역할에 대해서 말씀해 보십시오.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 과분한 말씀입니다.  저는 개인적으로 균형발전은 쉽게 이루어지지 않는다 하는 것이 제 소신입니다.  소신이라기보다는 세상 이치가 그렇다.  모두 다 같아질 수가 없기 때문에.  그런 의미에서 지금 참여정부가 하고자 하는 균형발전 정책은 기본적으로 생활의 이치에 안 맞다 하는 그런 주장을 합니다마는 삶이라는 것은 다른 측면이 또 있단 말이에요.  그래서 김대원 위원님께서 말씀하시는 도내에 어느 정도의 균형을 추구한다는 건 그건 또 그 나름대로 설득력이 있다고 봅니다.  그래서 제가 어디 가서 “균형발전은 어렵다.” 이렇게 얘기하면 우리 지사님은 바로 제 다음에 나와서 “나는 좌 원장하고 생각이 다르다.  북부와 동부는 균형발전해야 된다.” 하는 얘기를 제가 여러 번 들었습니다.  그래서 저는 도가 그렇게 균형발전 문제에 대해서 소홀히 생각하고 있다고 생각하지는 않습니다.
</p>
<p style="padding-left:1.2em">  그런데 아까 말씀하신 청사 이전문제는 벌써 오래 전에 결정된 문제고 그러다 보니 아마 그런 고민을 상대적으로 덜 했지 않았을까.  그리고 신도시를 만드는데 그걸 아주 정말 최첨단 도시로 만든다 하는 구상 속에서 제가 와서 신도시 부분을 연구하는 학자들하고 쭉 얘기를 들어보니까 그런 멋있는 도시가 되려면 거기에 뭔가 행정중심이 또 가고 이렇게 해야지 소위 시너지가 있고 그러지 않겠느냐 하는 일종의 도시건설의 이상론에 치우치다 보니까 아까 김 지사가 얘기하는 북부라든가 동부 이런 문제에 대한 고려를 상대적으로 좀 덜한 게 아닌가 그래서 지금까지 온 것으로 생각이 됩니다.
</p>
<p><b>○ 김대원 위원 </b> 충분히 알겠습니다.  원장님은 저희들하고 여러 번 토론회도 하셨고 원장님 강의하는 내용도 저희들이 들었습니다.  그런데 지금은 발상을 전환해야 되고 우리가 먼저 모범을 보여야 됩니다.  자기는 안 하면서 남보고 너는 왜 하냐고 욕하면 누가 믿어 주겠습니까?
</p>
<p style="padding-left:1.2em">  그런데 한 가지 예를 들어보면 미국에 대한민국을 대표하는 정치인 두 분이 계시지 않습니까.  워싱턴주의 신호범 펄 신 상원 3선 의원님하고 또 인접해 있는 오리건주의 5선 의원이신 임용근 의원 두 분이 우리 대한민국을 대표하는 미국의 정치인입니다.  또 한국교민사회의 정신적 지도자고요.  그런데 저희 위원회에서 두 주를 방문해 봤습니다.  방문했을 때 북부 시애틀로 잘 알려진 워싱턴주는 시애틀이 주도가 아닙니다.  거기는 올림피아시라는 인구 4만 4,000명밖에 안 되는 데에 주도가 있습니다.  또 오리건주도 포틀랜드시라고 대형시를 알고 있습니다.  그 포틀랜드시가 오리건주 주도가 아닙니다.  거기도 역시 인구 약 한 15만 되는 세일럼이라는 아주 산골짜기 안에 들어있는 그런 데입니다.  그런 데 주도를 둠으로써 균형발전을 꾀했다는 얘기입니다.  거대 도심화되어 있는 데 주도를 두면 어떤 상황이 생기냐 하면, 이것은 시중에 떠도는 얘기입니다마는 어떤 시기에는 심지어 도지사와 수원시장이 힘겨루기를 한 적도 있습니다.  그래서 누가 실제 주인이냐라는 차원까지, 그것은 거대시가 돼감으로써 앞으로 분명히 부딪혀야 될 이유일 것입니다.  만약에 수원시가 인구 150만, 200만 넘어간다면 광역시로 안 된다는 보장이 어디 있습니까?  그렇다면 처음부터 균형발전 부분에 대해서 이런 부분은 심각하게 생각해 보셔야 되고 아직까지 첫 삽도 뜨지 않은 상황입니다.  지금이라도 경기개발연구원이 다른 부분에 대한 논리를 개발하기 이전에 우리가 먼저 수신제가해서 우리 경기도는 이렇게 균형발전을 위해서 노력한다라는 부분을 보여주기 위한 상징적인 부분에서라도 도청사 건립이 수원시에 돼서는 안 된다고 생각합니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아까 좋은 지적을 해주셨는데요.  오리건주나 워싱턴주 같은 경우가, 그 말씀을 듣고 일부 알고 있긴 했습니다마는 새로운 면을 다시 강조하고 싶은 것은 제가 균형발전이 어렵다는 얘기를 할 때는 솟아오르고 발전하는 도시를 규제하면서 균형하겠다는 게 잘못됐다는 얘기죠.  그런 의미에서 수도권 규제가 문제 있다는 말씀이지.  예를 들어 잘하고 역량 있게 발전하는 도시를 그냥 놔두고 새롭게 그런 것을 만들어 가는 것은 정부가 해야 될 일입니다.  그런 의미에서 미국에서 하고 있는, 소위 말해 균형정책이라고 그걸 이름을 붙인다면 그건 지금 오늘날 우리나라 참여정부가 하는 것하고는 전혀 다른 정책인 것이지요.
</p>
<p style="padding-left:1.2em">  그런 의미에서 그건 찬성할 수 있고 또 그건 우리가 추구해야 될 한 가지 정책대안이라고 생각을 하는데, 그러면 현재 아까 지적하신 대로 수원의 미래가 보이고 조금 더 성장하면 소위 광역시가 되고 이렇게 하는 미래를 놓고 광교신도시에 도청사를 옮기는 게 합당하냐 하는 문제는 저는 한번 더 진지하게 논의를 해볼 사안이 아닐까 하는 생각이 듭니다.  그래서 강식 박사가 그 문제에 깊이 인볼브(involve)되어 있기 때문에 어느 정도 그게 진행이 되어 있고 이 상황이, 말하자면 어느 정도 이게 이미 셋업이 된 건지에 대한 것까지 포함해서 한번 얘기를 잠깐 들어보고요.  여기서 우리가 그것을 어떻게 하자 하는 그런 것을 떠나서 논의는 해볼 수 있다 이런 생각이 듭니다.
</p>
<p><b>○ 김대원 위원 </b> 충분히 의논해 보시기를 바라고요.  그리고 제가 이와 관련해서 수도권 문제의 전문가이신 강식 박사님, 이상대 박사님, 김제국 박사님 이런 분들이 중심이 돼가지고 최근에 만들어낸, 경기개발연구원 박사님 열아홉 분이 공동으로 연구하신 책입니다.  국가 발전을 위한 전략과제 여기에 포괄적으로 다 들어 있지 않습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 김대원 위원 </b> 마지막장에도 이 내용이 나와 있습니다.  그리고 첫 페이지 원장님 인사말에도 제가 말한 얘기들이 나옵니다.  그래서 이런 부분을 중앙정부에 따질 게 아니라 저희들부터 수신제가하는 것이 제일 우선이고요.  몇 가지 여기 연구과제를 보면 도시개발 권한의 합리적 지방이양을 위한 연구, 국가발전을 위한 전략과제 연구, 도와 수도권이 가진 문제점 해결을 위한 연구, 도시기본계획 연구 이런 부분으로 다해 가지고, 제가 거명한 박사님들의 수도권에 대한 논리개발 내용에 보면 박사님 말씀하시고 제가 말한 부분이 다 함축되어 들어 있습니다.  인구 분산이라든가 재정 분산이라든가 이런 부분의 지방분권은 요구하고 수도권 역차별 부분만 얘기했지 경기도 자체 문제에 대해서는 어떻게 해 보겠다라는 발상은 없었단 말이에요.  그러니까 지금부터라도 진지하게 연구해 주시기를 충심으로 바랍니다.
</p>
<p style="padding-left:1.2em">  아울러 한 가지만 덧붙인다면 빈곤은 절대빈곤과 상대빈곤으로 나눠진다고 봅니다.  다 호주머니에 1만원씩밖에 안 들어있는 데는 1만 1,000원 가진 사람이 부자입니다.  그러면 내가 가난한지도 모릅니다.  다들 1만원씩밖에 없으면.  그런데 누구는 1,000만원짜리 가졌는데 거기에 1만원짜리 가지고 흔들면 이게 상대적인 빈곤입니다.  다들 1,000만원 가지고 있는데 나 혼자만 1만원짜리 가지고 부자라고 있으면 그게 부자냐고요.  그래서 절대빈곤과 상대빈곤인데 우리 수도권에서도 과천지역 같은 경우에는 재정자립도가 90%가 넘어가는 그런 자족도시가 있는 반면에 인구 100만씩 넘어가는 성남, 용인, 수원, 군포, 안양 이런 지역에 둘러싸인 인구 14만의 의왕시라는 부분도 있습니다.  광교신도시와 의왕시 간에 직선거리는 1.5㎞밖에 안 됩니다.  그리고 93%가 그린벨트로 묶여있어서 아직도 아무런 개발도 안 된 그런 도심 속의 미개발지도 있습니다.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 며칠 전에 의왕시장님이 간부회의에 와서 현황 설명하는 것을 들었습니다.  아마 경기도에서 가장 취약한 지역 중의 하나라는 얘기도 들었고 그래서…….
</p>
<p><b>○ 김대원 위원 </b> 참고로 청사 건립비용이 지금 추정 예상가로 강식 박사님 연구서에 보면 약 4,000억에서 6,000억 정도 소요되는 것으로 되어 있습니다.  그것도 아마 건축비만 그렇겠죠.  그런데 의왕시의 1년 예산이, 지금도 일반회계 1년 예산이 1,000억대 왔다 갔다 합니다.  그런 사정 속에서 이런 부분을, 바로 이웃에 가난한 사람이 있는데 자기 호주머니 크다고 뒤도 돌아보지 않는 이런 정책이 어떻게 균형발전 정책입니까?  하여간 저는 문제제기는 충분히 했다고 보고요.  정말 경기개발연구원에서 지금이라도, 아직 예산 투입되지 않은 상황에서 순수 명품신도시로 거듭난다는데 거기에 명품도청이라고 들어가서 거기를 다시 이렇게 정의할 이유는 없다고 봅니다.  명품신도시는 충분한 명품신도시로서 자족기능을 갖췄으니까 이제는 도청 하나가 이전함으로써의 유발효과, 도심기능효과 이런 부분도 다시 검토하셔서 정말 정책적으로 대안을 제시하실 수 있는 그런 경기개발연구원이 되기를 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다.  그 취지를 제가 충분히 이해했기 때문에 염두에 두고 고민해 보도록 하겠습니다. 
</p>
<p><b>○ 김대원 위원 </b> 이상 발언 마치겠습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 김대원 위원님 수고하셨습니다.  보충질의하실 위원님 계십니까?  임우영 위원님 보충질의하시기 바랍니다. 
</p>
<p><b>○ 임우영 위원 </b> 우선 정인영 위원님 질의에 대해서 보충질의 한 가지만 하겠습니다.  우선 연구원 충원문제인데요.  제가 이사회 회의록을 보니까 금융전문가 이야기가 나오더라고요.  그런 게 한번 나온 적이 있지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 작년의 이사회 말씀하시는 거지요?
</p>
<p><b>○ 임우영 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 금융전문가, 다른 분야도 우리가 못 뽑고 있는 부분이 있습니다.  금융전문가 쪽도 얘기가 있었습니다. 
</p>
<p><b>○ 임우영 위원 </b> 그런데 거기에 보면 원장님께서 충원을 모색해 보겠다라고 말씀하셨는데 혹시 충원이 됐나 해서 제가 여쭤보는 겁니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 금융전문가이기도 하고 같은 비슷한 분야하고 연결해서 경제정책분석센터의 조성종 팀장이 한국은행에서 30～40년 동안 금융문제를 다루고 산업구조문제를 다뤘던 분을 저희가 모셔서 경제정책분석센터장으로 초빙해서 하고 있습니다. 
</p>
<p><b>○ 임우영 위원 </b> 모셨다 이 말씀이지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 모셨습니다.  그리고 질의하셨기 때문에 그런데 저희가 임금수준을 내년까지 노력을 하면 적어도 시정개발연구원 정도의 수준까지 갈 수 있도록 노력하고 있고요.  그렇다고 해서 모든 사람이 다 같이, 아까 여러 번 지적도 있었습니다마는 다 같이 나눠먹는 체제로 갈 수는 없다고 보기 때문에 여러 가지 성과급 체계도 개선을 하고 그것에 따라서 평가체계도 개선하는 노력을 할 계획입니다마는 최근 몇 달에 걸쳐서 인력을 충원해 보니까 가능성이 있다는 생각이 듭니다.  그래서 최근에도 한두 분이 괜찮은 분이 왔고 아주 최근에는 중앙의 내로라 하는 연구소에 있는 박사가 내년부터 이리로 옮기겠다고 하는 확약을 받았습니다.  그래서 여러분들 걱정하는 인력충원 문제가 내년부터는 조금 밝아지지 않을까 하는 희망을 가지고 있습니다.  물론 그렇다고 해서 안에 있는 사람을 제가 폄훼하거나 절대 그렇지는 않습니다.  안에서도 열심히 하는 사람한테 많은 혜택이 가도록 해가지고 훌륭한 연구박사들이 나올 수 있도록 하는 환경을 만들도록 최선을 다하겠습니다.
</p>
<p><b>○ 임우영 위원 </b> 이사회 회의록을 쭉 읽어보고 인원 충원과 관련된 얘기가 있어서 여쭤본 거고요.  김대원 위원님 질의에 대해서 한번 여쭤보겠습니다. 
</p>
<p style="padding-left:1.2em">  명품신도시 얘기가 나왔는데 아까 제가 자료 요구한 것에 보면 선진화위원회에다 명품도시건설분과위원회라고 구성을 했더라고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 있습니다. 
</p>
<p><b>○ 임우영 위원 </b> 그런데 첫 번째 회의를 하는데 보니까 많은 위원이 불참을 해서 그와 관련된 위원장의 얘기도 있었는데 위촉장 수여식 하는 데도 안 나오는 위원이 특별히 이유가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 명품신도시가 최근에 생겼는데 그날 제가 직접 그 모임에 참석을 했었습니다.  그런데 중앙에 있는 도시 관련된 전문가들을 다 모신 모양인데 마침 서둘러서 출범을 해서 그런지 시간약속을 잘 못 받아서 그렇게 했습니다마는 제가 보기에는 많이 안 나와서 문제가 될 정도로 했다고는 생각이 안 되는데요.  그 회의록이 어떻게 됐는지 궁금합니다.  저도 그때 참석을 해서 인사말도 했었습니다.  상황이 그렇습니다. 
</p>
<p><b>○ 임우영 위원 </b> 보면 여기 참석하신 여러 분들이 좋은 얘기도 많이 하셨습니다.  그런데 기본적으로 우리가 흔히 얘기하는 광교명품신도시에 관한 의견들을 쭉 개진했어요.  그런데 제가 읽으면서 참 어이없는 부분이 하나 딱 나왔어요.  여러분들이 읽고 공감하시는 분들이 어느 정도 있을지 모르는데 예를 들어서 이런 겁니다.  어느 거리에서 간판 정리로 지가가 70%, 판매율이, 아마 그쪽에 있는 가게 이용하는 사람이 늘어났다는 거겠죠.  “판매율 50%가 올랐다.  간판정리로 지가가 70%, 판매량이 50% 올랐다.  그러니까 간판 정리를 해야 된다.” 이런 논리가 과연 있을 수 있을까 하는 생각이 제가 들어서 무슨 근거로 이렇게 얘기를 했는지 모르고요.  또 하나는 여기 보면 담장을 허물고 안 허물고가 명품에 들어가는 건지 모르겠습니다.  그런 얘기부터 시작을 해서 쭉 되어 있어요.  그래서 내가 이런 위원회가, 뉴타운사업 관련해서 지원해 주는 위원회도 있지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다.   
</p>
<p><b>○ 임우영 위원 </b> 그것도 신도시 개발하는 것 아니에요?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇죠.  그런데 뉴타운사업은 일반적으로 경기도 안에 뉴타운사업을 개발하는 문제를 도와주고 이건 광교신도시에 목적을, 포커스를 맞춰서 만든 위원회라고 보시면 되겠습니다.
</p>
<p><b>○ 임우영 위원 </b> 그렇습니까?  이게 광교신도시입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.  물론 다른 것도 하려면 할 수 있겠지만 지금으로서는 그게 주책무가 되겠습니다.  
</p>
<p><b>○ 임우영 위원 </b> 그런데 아까 말씀드린 대로 이게 지사님 말씀 한마디에 의해서 이런 위원회가 만들어지고 없어지고 하다 보니까 여기 참여하신 분들도 우리 명품분과가 어떤 활동을 하고 어떤 과제물을 발굴하고 연구할 것인지, 어떤 수행을 해야 될 건지 이런 것도 전혀 없는 상태에서 위원회가 구성된 거예요.  여기 회의록에 다 나와 있어요.  제가 말씀드리고 싶은 것은 그런 차원이 아닙니다.  김대원 위원님이 균형발전정책에 대해서 말씀을 하셨는데 저는 좀 다르게 접근을 하고 싶어요.  어저께 경기도시공사에서도 제가 문제 지적을 했습니다.  뭐냐 하면 경기지방공사는 도의 출연금으로, 다시 말해서 도민들의 세금이 주재원이 돼서 만들어진 사업 공사란 말입니다.  그런 업체에서 사업을 해서 발생시킬 수 있는 이익금을 수원과 용인에만 다시 써라 하는 협약을 맺었어요.  그러면 그것 역시 수원과 용인에 대한 지역적인 특혜고 경기도 전체 도민의 세금으로 만들어져서 운영되는 회사가 사업을 해서 이익을 냈으면 이익금의 얼마는 가져와서 거기 자본금으로 다시 들어가서 경기도 전체에 대해서 활용이 돼야 되는데 그렇지 못한 협약서도 어제 제가 봤어요.
</p>
<p style="padding-left:1.2em">  더더군다나 도로 개설이나 어떤 거 하는데 최저가입찰제 이렇게 하면서 과연 이게 명품신도시가 되겠느냐.  말로만 그렇게 하고 활동만 그렇게 한다고 그래서.  원장님께서 나중에 이거 한번 읽어보세요.  여기 읽어보시는데요.  저는 전문가가 아니니까 이분들이 말씀하시는 부분이 어떤 건지는 구체적으로 이해를 못합니다마는 이분들이 말씀하시는 대로 이렇게 하면 이게 과연 명품신도시인가 하는 생각이 들어서 이런 위원회라면, 또 참석률도 그렇게 저조한 위원회를 이렇게 급박하게 만들어서, 지난 13일에 어디 보고하는 보고서도 만들어야 된다는 것이 여기 다 나와 있어요.  이런 식의 위원회를 우리 연구원에 만들어 가지고 괜히 잘못된, 아니면 가뜩이나 아까 말씀하신 대로 연구시간도 부족해서 압박을 받고 있는 연구원들이 자꾸만 이렇게 다른 일에 쫓기지 않도록 하는 것도 원장님의 역할이 아닌가 하는 차원에서 제가 말씀을 드렸고요.
</p>
<p style="padding-left:1.2em">  도에서 출연해서 만든 거기 때문에, 아까 저한테 주신 자료에 보니까 저는 도정 현안이 우리 도에서만 공무원들이 요구하고 그래서 과제가 나가는 줄 알았어요.  그랬더니 그렇지가 않더라고요.  그렇죠?  일반인들도 요구하면 해줍니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저희가 홈페이지를 통해서 제안을 하면 그걸 우리 내부에서 검토해서 타당성이 있고 우리가 미처 깨닫지 못한 부분을 보완할 수 있는 연구라고 생각이 되면 채택하는 경우가 있는데, 그런 제안제도가 있는데 아직 그게 채택된 경우는 없나봅니다.  우리는 다각도로 의견을 들으니까…….
</p>
<p><b>○ 임우영 위원 </b> 그게 홈피를 통해서 오고 갑니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 홈페이지를 통해서 나올 수 있지요.  그러나 개인이 와서 해달라고 그래서 다 해줄 수는 없지요.  홈페이지에 들어오는 사람들이 그런 주장을 많이 하는 경우가 있어요.  그러면 저희가 안 되는 것은 안 되는 거다 이렇게 해서 하기도 하고 의견을 듣는 하나의 방법으로 활용합니다.
</p>
<p><b>○ 임우영 위원 </b> 제가 지금 인터넷이 안 돼서 그러는데요.  여기 보면 지금 원장님, 도정 현안 그랬는데 그것은 일반게시판에 올라옵니까, 어디에 올라옵니까?  일반인들이 접근을…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 거기 접속하는 데가 저도 들어가서 보고 그랬는데…….
</p>
<p><b>○ 임우영 위원 </b> 아니, 도정 현안이라고 있어요.  도정 현안이라고 있는데 거기는 게시물이 하나도 없습니다.  그리고 제가 아까 여쭤본 것은 도정 현안 보고라고 되어 있단 말이에요.  홈피는 그렇게 만들어 놓고 거기에 게시물이 하나도 없는데 일반인들이 어디 접근해서 어떤 식으로 한다는 거예요?
</p>
<p style="padding-left:2.4em">    (관계직원 자료를 건네며)
</p>
<p style="padding-left:1.2em">  도정 현안이 아니고 이것은 아이디어 제안이죠.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇지요.
</p>
<p><b>○ 임우영 위원 </b> 아니, 그런 제안도 있고 거기 보면 도정 현안도 있고 창이 한 2～3개가 있어요.  그러면 제가 이따 인터넷이 되면 다시 질의하도록 하겠습니다.  이상입니다.
</p>
<p><b>○ 위원장 김영복 </b> 임우영 위원님 수고하셨습니다.  보충질의하실 위원 계십니까? 
</p>
<p style="padding-left:1.2em">  보충질의하실 위원이 안 계시면 회의를 장시간 했기 때문에 감사와 휴식을 위해서 감사를 일시 중지하고자 하는데 이의 없습니까? 
