<p><b>○ 위원장 김영복 </b> 자리를 정돈해 주시기 바랍니다.  감사를 계속하겠습니다.  감사중지 전에 임우영 위원님께서 질의를 하시다가 인터넷이 잘 안 되는 관계로 중단했는데 지금 되신다니까 바로 또 보충질의를 연속해서 해 주시기 바랍니다. 
</p>
<p><b>○ 임우영 위원 </b> 아까 도정 현안 문제인데요.  지금 인터넷을 통해서 들어오는 것을 하는 겁니까, 아니면 개인이나 단체에서······.  일반 외부단체에서 요청을 해서 도정 현안 분석을 해 주시는 경향이 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 외부 개인이나 단체, 그냥 민간단체나 이런 데서 저희한테 연구용역 프로젝트를 요청하거나 그래서 한 적은 거의 없죠.  우리가 그런 일을 하는 기관이 아니기 때문에 그렇고 제가 말씀드린 건 우리 홈페이지에 접속한 시민들이 아이디어를 많이 내요.  그 아이디어에 의해서 우리가 즉각 즉각 답을 하는 경우도 있고 그렇지 않은 경우에 필요하면 채택할 수도 있는데 확인을 해 보니까 아직 그런 실적은 없다고 들었습니다.
</p>
<p style="padding-left:1.2em">  그리고 아까 지적하셨던 도정 현안 문제는 그게 다른 게 아무 것도 올라가 있지 않다고 말씀을 하셨는데 그게 아마 요즘 홈페이지를 개선하면서 새롭게 바뀌었나 봐요.  그래서 내용을 아직 인풋을 못시킨 것 아닌가 하는 생각이 듭니다. 
</p>
<p><b>○ 임우영 위원 </b> 여러분들 홈피 딱 보면 정책분석이라는 게 있어요.  정책분석 밑에 도정현안분석, 선진화위원회, 정책포럼이 있습니다.  이 중에서 자료가 올라와 있는 건 정책포럼 하나만 올라와 있어요.  그런데 정책포럼이라는 것이 남북포럼도 여기에 포함이 될 거고 여러 가지가 있는데 기본적으로 지금까지 올라와 있는 게 2년 동안, 첫 번째가 2006년도부터 여기 되어 있네요.  그런데 10개밖에 안 올라와 있어요.  그런데 올라와 있는 것도 브랜드포럼이나 과학기술정책포럼 이래 가지고 한정돼 있고 이건 제가 봤을 때 각 포럼의 책임자가 스스로 올리는 코너인데 서비스가 안 되고 있고 특히 선진화위원회 같은 경우 아까 명품신도시 관련해서 위원회가 구성이 됐는데 선진화위원회 같은 경우도 예를 들어서 클릭하면 선진화위원회가 어떤 거다 하는 게 올라와야 되는데 그냥 ‘문의’ 해 가지고 담당자 전화번호 하나 올라온 게 전부입니다.
</p>
<p style="padding-left:1.2em">  그다음에 도정현안분석 같은 경우도 똑같아요.  똑같이 게시물이 없고 담당자 전화번호만 올라와 있는데 제가 말씀을 드리고 싶은 것은 가뜩이나 연구시간이 부족하다고 말씀을 하시면서 해주신 도정 현안을 보면 여러분들이 거의 여기 물포럼 반박문, 무엇, 무엇에 대한 검토, 그다음에 지사님 TV 토론 자료 이런 게 굉장히 많아요.  우리 연구원들을 어떻게 보면, 하여튼 연구시간 없고 부족하다고 말씀들을 하는 분들한테, 연구원들이 들으면 기분 나쁜 소리일 수도 있습니다.  그런데 이건 제가 연구원들을 비하하기 위해서 말씀을 드리는 게 아니고 그렇게 시간이 없는 분들한테 이렇게 잔심부름 시키듯이 이런 식으로 시키는데 말이에요.  이게 각 공무원들이 해야 될 일도 연구원들한테 미뤄서 자료를 받는 그런 게 대다수가 있다 하는 얘기예요.
</p>
<p style="padding-left:1.2em">  그래서 아까도 제가 말씀을 드렸지만 자기네들이 한 것에 대해서 검토를, 예를 들어서 의견을 개진한다든가 이렇게 하는 건 괜찮지만 보면 거의가 그런 게 아니고 자기네들이 처음부터 해야 될 걸 이쪽에다 넘기는듯한 제목들이 있단 말이에요.  그다음에 여기 보면 도가 아닌 일반 사기업에서 한 것도 있어요.  언론사에서 의뢰해서 한 것도 있습니다.  경향신문, 파이낸셜뉴스, 그다음에 국회의원 누구 이래서 개인이 이렇게 하는 것도 있단 말이죠.  그러면서 연구할 시간이 없다라고 자꾸 얘기를 하면 문제가 있는 것 아니냐 하는 걸 지적하는 겁니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 위원님 말씀에 대해서 제가 부정하거나 그러기가 쉽지 않다고 생각합니다.  그런 면이 없지 않아 있는데 제가 보기에는 아까 이 전번 세션에서 얘기를 하려고 하다가 전 위원님께서 끝내라고 그래서 말씀을 못드렸는데 연구원과 집행부의 관계가 묘합니다.  제가 오래 국책연구원 생활을 해 봤기 때문에 결국 연구원이 바로 서려면 행정부처가 바로 서야 되고 행정부처의 기획능력이 일정한 수준에 올라가야지 또 연구원이 제대로 연구할 수 있고 하는 둘 간의 관계가 아주 복잡합니다.  그래서 과거에 KDI 같은 데도 보면 KDI가 이런 일을 많이 했어요.  심지어는 ’80년대, ’90년대까지도 그런 일을 했는데 요즘에 와서는 중앙정부의 기획능력이 많이 올라갔기 때문에 KDI가 그런 일을 상대적으로 많이 안 하죠.
</p>
<p style="padding-left:1.2em">  그런데 제가 지금 와서 판단하기에는 우리 도 공무원님들이 다 훌륭하고 그렇지만 기획능력 측면에서 독자적으로 모든 걸 할 수 있는 그런 수준은 아니라고 봅니다.  그래서 이게 시간이 걸릴 문제죠.  그런데 현실적으로 급한 이런 사안들이 떨어지니까 제가 파악하기에는 일을 서로 같이 하는 경우도 있는 거고, 도의 일을 말이죠.
</p>
<p><b>○ 임우영 위원 </b> 무슨 말씀인지 알겠습니다.  제가 제 본질의 때는 질의를 할 텐데요.  여러분들 경영실적 평가보고서를 보고 아까도 말씀을 드린 겁니다.  뭐냐 하면 자꾸만 이렇게 잔심부름에 불과한 과제들도 연구원들이 직접 전화 받아서 하다 보니까 통제가 안 되고 연구시간만 뺏긴단 말이죠.  그러니까 이러한 걸 될 수 있으면 일원화시켜서 거를 건 좀 거르는 장치가 필요하겠다.
</p>
<p style="padding-left:1.2em">  여러분들 외부기관에서 평가한 그 안에도 그런 내용이 있어요.  개선사항으로 돼 있어요, 개선사항으로.  그래서 제가 아까 지적을 한 거니까 이걸 질타하고 뭐가 아니고 여러분들이 연구시간을, 경기개발연구원이 필요한 게 바로 그런 거 아닙니까?  충분한 연구시간을 갖고 도에 필요한 정책을 개발해서 훌륭한 연구 성과물을 내는 게 여러분들의 역할인데 그러기 위해서는 이렇게 공무원들이 해야 될 잔심부름까지, 자기네들 업무를 해야 될 것을 잔심부름하는 일은 더 이상 있어서는 안 되겠다.  아무리 현안, 현안 하지만 그런 게 문제가 된다는 거죠.
</p>
<p style="padding-left:1.2em">  어제 경기지방공사도 도시정책연구소라고 박사 세 분을 신설했어요.  연구할 사람이 필요하다, 필요하다 해 놓고 정작 두 사람은 광교신도시특별계획구역의 팀장으로 가서 앉아 있고 한 사람이 바로 지금 원장님이 말씀하시는 그런 현안을 단타성으로 연구해서 제공하고 있더라 이런 얘기예요.  연구원들을 뽑았으면 그것에 합당한 역할을 할 수 있도록 보호해 주고 그 역할을 제고하는 방안을 개선하는 것도 바로 원장님이 하셔야 될 일이다 싶어서 제가 지적을 하는 겁니다.  이상입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다.  충분히 취지를 이해하겠습니다.
</p>
<p><b>○ 위원장 김영복 </b> 임우영 위원님 수고하셨습니다.  보충질의하실 위원님 계십니까?  질의하실 위원님 계십니까?  조선미 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 조선미 위원 </b> 고양시 출신 조선미 위원입니다.  지난 경기도에 대한 국정감사에서 김문수 지사께서는 팔당상수원의 이전에 대해서 해당지역의 반발이 심해 협의하겠다라면서 경기개발연구원의 취수원 연구도 중단시켰다는 답변을 했습니다.  방금 원장님께서도 사실상 포기했다는 말씀을 하시고 자료에 보니까 2007년 9월부터 지금 11월까지 이걸 하기로 했는데 이걸 중지했다고 21쪽에 나와 있더라고요.  각 언론에서도 팔당취수장을 옮기는 것에 대해서 사실상 포기의사를 밝힌 것으로 보인다라고 평가했습니다.
</p>
<p style="padding-left:1.2em">  그러면 원장님께 질의하겠습니다.  원장님께서는 평소 경기개발연구원에 대해서 변화하는 국내외 정세에 맞춰 국가와 경기도의 발전을 위해 정책대안을 제시하는 명실상부한 경기도의 싱크탱크로서 세계적인 정책연구기관으로 발돋움해 나가도록 노력하겠다는 의지를 밝혀 왔습니다.  그런데 본 위원은 이번 팔당취수원 이전과 관련된 일련의 과정들을 지켜보면서 과연 경기개발연구원이 싱크탱크로서의 역할을 잘 수행하고 있는 것인지 의문을 가질 수밖에 없었습니다.  우선 진정한 의미의 싱크탱크라고 말하기 위해서는 단순히 지시사항을 그대로 순종하고 원하는 대로 연구결과를 제출하려고 해서는 안 된다고 보는데 어떻게 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 존경하는 조선미 위원님의 지적에 대해서 옳은 지적이라고 생각합니다. 
</p>
<p><b>○ 조선미 위원 </b> 그런데 왜 그런 일을 하셨습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이 문제에 대해서 공식적으로 도의 요청이 있어서 시작은 했지만 그건 대단히 중요한 문제입니다.  그리고 연구프로젝트를 공식적으로 하지 않는다고 해서 저희 연구원이 그 문제를 고민하지 않아서는 안 되겠죠.  저희 팔당물환경센터를 만든 이유가 바로 그런 걸 고민하기 위해서 했기 때문에 실질적으로 그런 문제를 계속해서 저희가 연구할 것이고 더 제가 말씀을 드리면 내년에 가서 가능하면 저희가 취수원 이전문제와 관련된 포럼까지 만들어서 이 문제를 공개적으로 좀 더 논의할 필요성이 있지 않느냐 하는 그런 생각을 하고 있고, 제가 약속을 드릴 수는 없습니다.  그러나 내년에 가서 그런 연구모임을 해서 경기도민도 그렇고 국가도 그렇고 취수원 문제가 대단히 심각한 문제고 이것 때문에 생기는 피해라든가 이런 것에 대한 인식을 또 바로 하도록 알리고 동시에 새로운 취수원이 어디가 대안이 될 수 있느냐 하는 걸 지속적으로 좀 고민을 해야 된다 이렇게 생각을 하고 있습니다. 
</p>
<p><b>○ 조선미 위원 </b> 원장님, 수도권 취수원 이전 타당성 연구라는 이 연구의 경우는 명목은 취수원 이전에 관한 연구로 돼 있습니다.  하지만 수도권 취수원이라는 게 뭡니까?  팔당취수장을 의미하고 팔당취수장을 이전할 경우에는 팔당취수장 인근의 남양주, 하남, 광주 등 경기 동북부지역은 상수도보호구역으로 인한 규제에서 벗어나지만 반대로 강원도 춘천지역은 규제를 받게 된다는 것을 전문 연구자가 아니라도 쉽게 알 수 있는 내용입니다.  물론 취수장이 이전만 될 수 있다면 경기도로서는 더할 나위 없이 좋겠지만 취수원 이전을 위해서는 한국수자원공사, 건설교통부, 환경부 등 사실은 관련 중앙부처의 협의가 선행돼야 된다고 봅니다.
</p>
<p style="padding-left:1.2em">  따라서 본 위원은 상수원, 취수원에 관한 연구용역 의뢰가 들어왔을 때 춘천시와 같이 취수원 이전으로 인해 새롭게 규제대상이 될 수밖에 없는 지역의 반발 등 발생할 수 있는 제반 문제점에 대해 충분히 설명하고 용역 추진방안에 대해서도 충분히 함께 검토했어야 한다고 봅니다.  싱크탱크란 발주자의 의도가 불러올 수 있는 문제점까지 사전에 지적해서 충분히 대처할 수 있게 해야 되는 것 아닙니까?  그런 의미에서 적어도 이번 건에 대해서만은 용역 추진과정에서 연구원은 싱크탱크의 역할을 제대로 수행을 하지 못했다고 봅니다.
</p>
<p style="padding-left:1.2em">  이것과 관련해서 한 가지 더 말씀을 드리면 페이지 537쪽 고객 만족도입니다.  경기개발연구원은 연구사업 수행규칙 제4조의2 연구계획서 작성에 의거 수탁과제와 정책과제, 연구보고서 제출 후 2개월이 되는 날에 연구과제를 의뢰한 도, 시&#8228;군 등 기관 관계자에게 만족도를 묻는 설문조사를 실시하고 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 조선미 위원 </b> 지난 2005년부터 2007년 실시한 설문조사 결과를 보면 주요 개선사항은 다음과 같습니다.  2005년입니다.  “연구결과의 내용이 현실성이 떨어져 정책 반영에 어려움이 발생하고 있다.  연구내용이 개론 정도만 제시되었을 뿐 구체적인 내용이 없음.”  또 2006년에는 “용역기관 전문가들의 전문적 지식을 토대로 길잡이 역할이 필요했으나 부서별 업무내용 취합과 검토로 일관하여 행정행위의 보조적인 수단으로 그침.  보다 전문적인 식견이 가미된 성과가 잘 나타나는 지표개발 필요.  정책제안이 명확하고 상세하게 기술되어야 하나 대체적으로 두루뭉술하게 기술하고 있어 정책제안으로서의 역할이 미흡.”  2006년도입니다.  “연구의 개론과 정책적인 방향만 언급하고 구체적인 목표가 제시되지 않아 아쉬움.  문제점의 구체적 도출과 현실행정에 적용 가능한 대책방안이 부족.  실무진과 의견교류가 부족했으며 실질적으로 활용하기에 다소 미흡.”  2007년도에는 “구체적인 실행방안이 미흡.  일부 개선방안이 문제제기 수준에 그쳐 아쉬움.  구상안에 대한 실행방안 제시 미흡 및 문제점 대안&#8228;대책 미흡, 사례중심의 연구진행을 통한 구체적인 방안 제시 필요.”  어떻습니까?  2005년부터 현재까지 개선사항 요지를 듣고 나니 어떤 생각이 드십니까?  이 고객만족도에 대한 원장님의 생각을 듣고 싶습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 읽으신 부분을 지금 찾고 있는데요.  어쨌든 그 말씀을 듣고 여러 가지 생각을 하게 됩니다.  우리가 수행한 연구내용이 우선 미흡하다는 게 제일 큰 문제가 되겠죠.  그러나 수요자와의 관계는 또 여러 가지 복잡한 문제가 있습니다.  지금 여러 분들이 지적한 대로 “왜 발주자의 의견을 잘못했으면 잘못했다고 그러고 바꿔주지 않느냐.” 하는 얘기를 하시는데 바로 그런 게 이런 문제를 야기할 수도 있고 만족도 조사라는 게 말하자면 수요자의 절대적인 판단에 달려 있는 것이기 때문에 일방적인 것이죠.
</p>
<p style="padding-left:1.2em">  그래서 저희가 기본적으로 연구의 질을 높인다는 차원에서 더 열심히 해야 되겠지만 때에 따라서는 수요자에게 문제도 있었다 하는 점을 제가 지적을 드리고, 그럼에도 불구하고 우리가 연구하는 과정에서 수요자하고 보다 더 커뮤니케이션을 잘해서 연구의 결과가 수요자의 니드(need)에 맞도록 열심히 좀 노력을 해야 되지 않을까 하는 그런 생각을 하게 됩니다.
</p>
<p style="padding-left:1.2em">  물론 그렇다고 해서 우리가 독자적인 판단이나 객관적인 연구를 안 하겠다는 얘기가 아니라 어떤 경우에는 정책이나 수탁연구가 수요자가 특별한 목적과 방향을 가지고 수행방법을 물어오는 경우가 있는 것입니다.  그러니까 어떤 경우에는 우리가 그 목적이나 방향을 설정해 주는 연구도 있지만 어떤 경우에는 정해진 목적을 달성하기 위한 효율적인 방법이 뭐냐 하는 것에 대한 연구도 있기 때문에 아까 말씀하신 여러 가지 문제들이 복합적으로 관련이 돼 있습니다.
</p>
<p style="padding-left:1.2em">  그래서 조선미 위원님 지적에 대해서 제가 겸허하게, 저희 연구원이 그동안 수요자를 잘 관리하지 못하고 수요자의 니드(need)에 맞게 못했다는 점을 반성하고 앞으로 싱크탱크로서의 노력을 더 강화하도록 하겠습니다. 
</p>
<p><b>○ 조선미 위원 </b> 제가 말씀드린 개선사항을 한마디로 정의해 보겠습니다.  경기개발연구원이 수행한 연구물의 구체적인 실행 방안 및 목표 제시가 없다는 말입니다.  지금 수탁 3년 동안 매번 설문조사 결과 개선요지 사항에 대해서 구체적인 실행방안이 없다는 지적에 대해서 개선하지 않는 것은 개선하고자 하는 의지가 없는 것 아닙니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 전부 다 그렇다고 하는 의미는 아니죠.  만족도조사를 보면 상당한 수의 만족이 있는데 불만족한 아주 소수의 부분이 있습니다.  그런 부분들의 경우에 생기는 문제는 개별적으로 저희가 그걸 다루려고 개별 연구원들이 노력을 하지만 세상이 그렇잖아요.  다 100% 만족시킬 수는 없으니 그런 일이 계속 반복되는 일이 조금씩 있는데 저희는 가능하면 그 수준이 최소화될 수 있도록 노력을 하고 있는 것입니다. 
</p>
<p><b>○ 조선미 위원 </b> 잘 알겠습니다.  지금 설문조사 결과에 의뢰기관들의 만족도 수준이 상당히 높은 것으로 조사되었음을 자찬하면서 개선사항은 그냥 흘려 들으신 것 아닙니까?  또한 지금 조사결과의 한계에서 밝힌 “회수가 100%에 이르지 못하고 수탁과제를 당초 수행하지 않은 박사들도 있기 때문에 개인별 조사결과를 인사평정의 절대적인 자료로 활용하는 데는 형평성 문제가 있어 주로 개인별 기초자료로 활용하는 것이 적절”이라는 문구는 지난 3년 동안 토시 하나 틀리지 않고 그대로입니다.  회수가 100%에 이르지 못했으면 100%를 만들기 위해 어떻게 노력하셨습니까?  노력하신 걸 한번 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저희가 아시다시피 할 수 있는 건 독려하고 부탁하는 수준 이상 하기가 어렵습니다.  그래서 앞으로 더 노력하도록 하겠다는 말씀밖에 더 드릴 수가 없네요.
</p>
<p><b>○ 조선미 위원 </b> 고객만족도조사라는 것은 불만족 부분의 원인을 경시하지 말고 그것에 대한 대책을 제대로 강구해서 보완하기 위한 목적을 가지고 있는 것입니다.  경기개발연구원은 불만족 부분의 원인을 지난 3년 동안 경시하고 아무런 노력도 하지 않고 있는데 고객만족도조사를 하면 무슨 의미가 있겠습니까?  고객만족도조사 시 일부 불만족 사례와 지적에 대해서는 보강하고 문제를 해결하려는 노력을 지속적으로 기울일 때 경기개발연구원의 완전한 성공이 이루어질 수 있을 것이라고 봅니다.  아까도 말씀드렸지만 이번 팔당취수장 이전용역과 관련된 사태를 거울 삼아서 도정 정책결정 과정에서 책임 있는 의견을 제시할 수 있는 기관으로 발돋움해야 하고 이번 사건이 국감에서 전국에 알려지면서 개발원에 대한 신뢰도도 떨어지는 겁니다.  연구원들에 대해서도 어떻게 생각하겠습니까?  도지사 말이면 안 되는 것 삼척동자도 뻔히 다 아는 걸 연구하겠다고 하는 것 아닙니까?  그러니 31개 시&#8228;군은 어떻게 개발원을 믿고 수탁을 하겠습니까?  그리고 지금 이렇게 고객만족도가 불만족한데도 개선을 하지 않는다고 생각할 것 아닙니까?  하여튼 이번 이 사건에 대해서······.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 위원님, 제가 한 번······.
</p>
<p><b>○ 조선미 위원 </b> 그럼 견해를 한번 밝혀 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지금 취수원 문제에 대해서 지적을 하신 점에 대해서 는 저는 동의하지 않습니다.  저희 연구원이 어떤 내용으로 어떤 결과를 내고 있는지에 대해서 알지 못하는 상황에서 그렇게 말씀하시는 건 연구원 전체에 대한 잘못된 인식을 심어줄 수 있기 때문에 제가 그 의견에 동의하지 않습니다.
</p>
<p style="padding-left:1.2em">  조선미 위원님께서 필요하시다면 그 연구결과를, 실제로 내부적으로 박사들이 연구를 안 한다고 그래서, 공식적으로 그만뒀다고 그래서 박사들이 연구를 안 하는 게 아닙니다.  그 연구결과를 원하신다면 제가 나중에 개인적으로 보여드릴 것이고, 그랬을 때 그게 도의 의견을 무작정 지원을 했는지, 서포트를 했는지 안 했는지에 대해서는 조 위원님께서 판단하실 수 있을 것이라고 생각합니다. 
</p>
<p style="padding-left:1.2em">  그리고 만족도조사에 대해서는 위원님보다 제가 더 이 문제에 대해서 신경을 쓰고 있고 아까도 말씀드렸지만 세상에 100% 만족시킬 수가 없습니다.  항상 그렇기 때문에 저희가 그 불만족 수준을 최소한도 수준으로 컨테인(contain)하기 위해서 노력하고 있음을 말씀드리고 앞으로 그런 점에 대해서는 노력을 더 경주하겠다는 말씀을 드리겠습니다.
</p>
<p><b>○ 조선미 위원 </b> 지금 취수원 연구용역을 선정하고 그다음에 중간에 취소한 것에 대해서, 그럼 계속 연구를 하시지 왜 중간에 중단하셨습니까?  지사가 하라고 그러면 하고 중단하라고 그러면 당장 중단하는 겁니까, 겨우 3개월짜리인데?  그리고 겨우  한 달 추진한 것 아닙니까?  그런데 그렇게 말씀을 하시면······.  그 연구용역 제목이 뭔지 아십니까?  수도권 취수원 이전 타당성 연구입니다.  지금 이걸 지적했는데  원장님께서 제가 연구원 전체에 대해서 불신하는 것처럼 말씀을 하셨는데 그런 의미로 말씀드린 게 아닙니다, 원장님.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그게 아니기를 바랍니다.  그리고 그 취수원 문제에 대해서 다시 말씀드리지만 그 문제는 저희 연구원이 오래 전부터 계속 연구하고 있는 사항이고 이 연구를 취소했다는 것은 공식적으로 저희가 이 연구를 끝내서 도에다가 제출하지 않는다는 걸 의미하는 것입니다.  그렇기 때문에 내부적으로 박사들이 개인적인 관심이나 정책연구로 혹은 기본연구로 계속 할 수 있고 제가 아까 지적했지만 내년에 가서 저희가 이 문제를 가지고 좀 더 공개적으로 국민들의 관심을 환기하고 새로운 적절한 방안을 모색하기 위한 포럼도 추진할 계획을 가지고 있다는 점을 제가 아까 말씀드렸습니다.  사실은 저희가 도에서 요청 안 하는 걸 계속 해야죠, 필요하다고 그러면.  그런 점에서 이 문제는 워낙 중요한 문제기 때문에 이번에 그 상황과 관계없이 저희 연구원에서 계속 연구하고 있고 해 나갈 것이라는 그런 점에서 드리는 말씀입니다.
</p>
<p><b>○ 조선미 위원 </b> 이 팔당상수원에 대해서 저희가 연구한 건 너무 잘 압니다.  저희 김영복 위원장님께서 2007년 9월 과제로 수도권 취수원 이전 타당성 연구를 개발원에서 한다고 했을 때 벌써 그때 지사님한테 반대의견을 내셨어요.  “이건 우리 연구원에서 지속적으로 해 왔고 굳이 이걸 따로 할 필요도 없고 이걸 하기 위해서는 환경부라든가 건교부라든가 타 지자체하고 협의가 먼저 필요합니다.” 그렇게 했는데도 불구하고 지사는 강행해서 이것을, 지금 신규과제입니다.  지속적으로 해 왔던 것 중에 이것만 뽑아서 신규과제를 한 것입니다.  거기에 대한 이해도를 원장님께서 갖고 답변해 주시면 감사드리겠고요.
</p>
<p style="padding-left:1.2em">  다음으로는 경기개발연구원의 연구과제 수행현황을 보면 2006년도에 70건으로 68억 8,104만원이고 2007년도에 96건으로 79억 1,657만원으로 증가하고 있습니다.  그중에서 2007년 위탁연구과제는 57건으로 25억 9,930만원이며 그중 특별회계는 39건으로 16억 9,065만원으로 68%를 차지하고 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 죄송합니다.  제가 페이지를 찾지를 못해서······.
</p>
<p><b>○ 조선미 위원 </b> 임우영 위원한테 주신 위수탁연구과제의 수행현황입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다.  
</p>
<p><b>○ 조선미 위원 </b> 68%를 차지하고 있다고 내신 자료에 있습니다.  특별회계사업은 위탁받은 사업 중에 재위탁을 준 사업이죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 조선미 위원 </b> 자료에 그렇게 나와 있더라고요.  그래서 2007년도 재위탁을 준 사업은 지난 2006년도 26건보다 10건이나 늘었는데 사유가 뭡니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 답변을 일반적인 말씀밖에 못 드리겠는데요.  좀 더 구체적인 얘기가 필요하시면 담당자한테 답변을 요청하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  우선 제 생각에는 외부위탁이 많이 나가는 건 그만큼 저희가 연구 부담이 많아지고 있다는 걸 의미한다고 저는 생각을 하고 가능하면 주어진 인력하에서 연구수요를 충족하다 보면 내부인력이 모자라기 때문에 그렇게 외부로 나가는 경우가 많다는 걸 아까 지적을 들었는데 그런 현상이라고 저는 알고 있습니다.  저희 기조실장이 좀 더 상세하게 말씀을 올리도록 해도 괜찮겠습니까?
</p>
<p><b>○ 조선미 위원 </b> 네, 간단하게 해 주십시오. 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기조실장 이상훈입니다.  외부위탁이 많이 늘어간다고 하는 건 물론 연구진의 연구부담이 점점 늘어가는 것도 있고요.  그리고 최근에 저희한테 의뢰하는 과제동향이 저희 연구원 내부의 전문성 가지고는 부족한 내용들이 상당히 많습니다.  특히 기술적인 부분도 있고요.  도면 작성부터 해서 기술, 실험관련 부분도 있고요.  점점 다양한 여러 가지 과제들이 늘어나고 있기 때문에 이러한 위탁과제는 점점 늘어날 수밖에 없고 또한 발주처에서도 그러한 부분을 요청하고 있습니다.  그중에서 특별회계로 가는 부분에 대해서는 저희들이 수탁과제 및 위탁과제를, 수탁과제를 특별회계로 분류하고 있습니다.  그렇기 때문에 그러한 부분이 점점 늘어난다고 이해를 해주시면 되겠습니다.  저희 입장에서는 아웃소싱입니다.
</p>
<p><b>○ 조선미 위원 </b> 제가 시ㆍ도연구원협의회에서 2007년도에 작성한 것을 보니까 지금 서울 같은 경우에는 1인당 연구실적이 2.3 정도인데 저희가 9.7건으로 가장 높네요?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네, 그 자료에 의하면 그렇습니다. 
</p>
<p><b>○ 조선미 위원 </b> 이것보다 더 많은가요?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 아닙니다.  9.7과제가 맞을 겁니다.
</p>
<p><b>○ 조선미 위원 </b> 우리 연구원님들이 거의 과제에 치여서 죽을 판이겠네요. 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 과제가 많다는 것은 다 같이 인정해 주시는 것으로 알고 있습니다. 
</p>
<p><b>○ 조선미 위원 </b> 그러면 인력을 늘려야 됩니까, 과제를 줄여야 됩니까, 과제를 선별해야 됩니까?  어느 것이 우선과제라고 생각하십니까? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 처음에 저희가 과제를 채택하는 과정에서 보면 저희한테 용역을 의뢰하는 경우에 어떤 경우가 있냐 하면 저희 같은 경우 비교적 과제 수행하는 인력이 연구원 내에 다양하게 포진하고 있고, 그다음에 제3기관에 의뢰하는 것보다 실제적으로 투입하는 비용이라든가 이런 것이 훨씬 높습니다.  아마 그런 이유 때문에 수탁과제가 계속 늘어나고 있고, 물론 바쁜 것은 사실이고 일이 많은 것은 사실이지만 연구를 하다 보면 과제 간에 어떤 시너지효과 같은 것도 있습니다.  그래서 일이 많은 것은 알지만 어차피 지난번에 A라고 하는 연구원이 그것을 수행했기 때문에 거기 한 단계 더 업그레이드된 B연구도 수행하는데 다른 사람한테 맡길 수 없는 그런 부분들이 있고요.  그래서 선정하는 과정에서 그런 어려운 점이 좀 있습니다.
</p>
<p><b>○ 조선미 위원 </b> 제가 조 박사님을 보니까 갑자기 불현듯 생각났는데 파견근무 나간 연구원은 몇 명이나 있습니까? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 현재 파견근무 나간 연구원이요?
</p>
<p><b>○ 조선미 위원 </b> 네.  아예 출근을 그쪽으로 하시는 파견공무원들이 있고 보니까 가끔씩 왔다 갔다 하는 파견 직원들이 있던데 어떻게 분류하는지는 잘 모르겠지만 일단 부서로 파견 나간 연구원들은 몇 명이나 있습니까? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 전에 교통연구부에서 교통 관련된 프로젝트를 하느라고 파견을 나갔다가 지금은 복귀한 상태고요.  현재 파견 나간 인력은 없습니다.  팔당물환경센터인 경우에는 파견이라고 보기보다는 외청으로 판단하기 때문에 현재로는 없는 것으로 판단하고 있습니다. 
</p>
<p><b>○ 조선미 위원 </b> 그러면 파견은 지금 전혀 없는 거예요?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네.
</p>
<p><b>○ 조선미 위원 </b> 알겠습니다.  그냥 업무협조로 왔다 갔다 하는 거예요?  어떤 프로젝트 연구가 있을 때는 그 기간 동안만 잠깐, 그것도 파견이긴 하지만 단기간 파견인 건가요?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 연구 프로젝트인 경우는 그 과제 수행을 위해서 해당 발주기관에서 워크숍이라든가 이런 것을 장기간 동안, 표현은 장기간이라고 하지만 일주일이면 일주일 현지 파악을 위해서 그런 것을 요청하는 경우는 있습니다.  그렇지만 원칙적으로 파견을 해서 연구하는 경우는 없습니다. 
</p>
<p><b>○ 조선미 위원 </b> 알겠습니다.  사실 파견이라는 게 업무협조라고는 하지만 실질적으로 거기 가보면 직원하고 똑같습니다.  일이 더 많습니다.  파견을 나가게 되면 연구할 시간이 없거든요.  그래서 지금 연구원들이 과제도 많은데 혹시 파견연구원이 있는지 궁금해서 여쭤봤고요.  답변 감사드립니다. 
</p>
<p style="padding-left:1.2em">  지금 과제 중에 수행할 수 없는 엔지니어링 부분이라든가 디자인 부분, 금방 말씀하신 것처럼 이런 기술적인 것을 재위탁 주는 것이 예산절감 부분에서 효과가 클 것이라고 생각합니다.  그런데 제가 재위탁된 것을 전체적으로 살펴봤더니 경기방문의 해 사업성과 평가 및 백서 중에 경기방문의 해 인식조사, 소비자조사, 고객만족도조사, 주민의식조사 등등으로 해서 설문하고 인식조사가 주로 재위탁된 게 좀 있더라고요.  그다음에 그걸 받은 업체들도 중복된 업체들이 좀 있었는데 제 생각에는 설문조사의 재위탁이 높다면 단순한 설문이나 통상적인 조사는 연초나 연말에 평균실적 평가나 아니면 공개를 통해서 업체를 한 곳이나 세 곳 정도를 선정해 가지고 연간 단가계약을 한번 검토해봐 주실 것을 제안합니다.
</p>
<p style="padding-left:1.2em">  경기개발연구원의 고유업무에 대한 깊은 이해로 협력업체로서의 내실 있는 조사가 이루어질 수 있는 개연성이 있다고 판단합니다.  또한 현행대로 진행하면 수많은 공고와 재공고 및 협상에 따른 인력과 시간과 경비가 많이 소요되나 제 제안이 적용된다면 인력 및 예산의 절감과 시간상의 절약이 가능하여 연구원 본연의 업무에 충실할 수 있음은 물론이고 선정업체로서도 안정적인 일거리 창출로 알찬 자료와 통계로써 고객을 만족시킬 수 있을 것이라는 생각이 드는데 이에 대해서는 원장님 견해는 어떤지 한번 밝혀주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우선 취지는 좋은 지적이라고 생각이 되고요.  취지에는 동감합니다마는 한 가지 저희가 염두에 둬야 될 것은 이런 여론조사기관을 선정하는 과정에도 저희가 공개입찰이라고 하는, 여러분들이 정해 주신 룰이지요.  이런 것을 따라야 되는 현실적인 어려움이 있기 때문에 그걸 지켜야 되지만 가능하면 장기적인 일 관계를 통해서 효율성도 높이고 단가도 낮출 수 있는 방향으로 큰 틀에서 규정에 위반되지 않는 한도 안에서 위원님께서 지적하신 방향으로 노력해 보도록 하겠습니다.  좋은 지적이라고 생각합니다. 
</p>
<p><b>○ 조선미 위원 </b> 한번 검토해봐 주시면 공고나 다른 잡무로 시간을 보내는 것을 줄일 수 있지 않을까 해서 의견을 말씀드렸습니다.  그럼 이상 본질의를 마치겠습니다. 
