<p><b>○ 경기개발연구원장 좌승희 </b> 저희가 생각하는 경기도의 관심사항을 가능한 합리적으로 정책이 갈 수 있도록 그걸 전달하고 그걸 채택하도록 여러 가지 방법을 통해서 노력하는 수준에서 하고 있습니다. 
</p>
<p><b>○ 전동석 위원 </b> 그렇지요.  경기도에 미치는 영향을 분석하고 또 대처해 나가달라는 그런 말씀입니다.  그런 걸 좀 하실 준비는 되어 있지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 하고 계속 할 계획이고 이제 책이 나왔기 때문에 제가 그 책을 들고 다니면서 홍보를 많이 해야 되겠지요.  여기 저기 돌리고.  차에 싣고 다니면서 그 일을 하겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 방금도 말씀드렸지만 대통령 공약 중에 경기도에 대한 공약이 수도 없이 쏟아져 나옵니다.  사실 엊그제도 필승결의대회 할 때 보면 경기도에 대한 공약이 아주 많이 나옵니다.  그런 것까지도 다 체크할 수 있지는 않겠지만 그래도 경기개발연구원에서, 오전 중에 많은 위원님들이 싱크탱크 역할 그리고 실제로 그것을 하기 위해서는 경기도의 어떤 간섭이 덜 있어야 된다 하는 생각하고 그다음에 심부름꾼 얘기까지 나왔는데 이런 정도의 것은 차치하고 진짜 심도 있는 연구를 부탁드리고 싶습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다.  
</p>
<p><b>○ 전동석 위원 </b> 아까 말씀드린 국가발전을 위한 전략과제 저에게도 한 부 주셨으면 좋겠습니다.  원장님, 제가 오늘 이것으로 질의를 마치려고 하는데요.  본 위원이 이렇게 지적했거나 또 연구과제가 미비했거나 이런 사항들을 지적했는데 경기개발연구원에서 하는 모든 일을 분석한다면 사실 너무나 미비하고 작습니다.  너무나 미비하고 작고요.  우리 위원님들이 좌 원장님에 대해서 굉장한 신뢰를 가지고 있는 상황이거든요.  원장님이 하시는 일에 대해서도 적극적으로 도움을 줘야 되겠다 하는 생각을 가지고 있는 입장입니다.  그렇지만 저희 집에 책들이 많이 옵니다.  여기서 연구한 내용들을 다 읽어보고, 저는 그래도 오면 제목만 보고 혹시나 제가 관심 있는 부분이면 줄 쳐놓았다가 거의 쌓아놓고 있는 입장, 다 볼 시간이 없기 때문에, 책을 굉장히 많이 연구한다는 생각이 듭니다.  그래서 그런 어떤 연구가 그것으로 끝나지 말고, 이게 진짜 상식적인 얘기입니다.  그것으로 끝나서는 안 되고요.  진자 피드백할 수 있는 어떤 시스템이 마련돼야 저희들이 원장님한테 보내는 그런 신뢰가 계속 쌓이지 않겠습니까?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 그렇게 해주셨으면 좋겠고요.  진짜 도정 발전에 빛날 수 있는, 정책으로 빛날 수 있는 정책을 항상 지도해 주시고 노력해 주시기를 당부드립니다.  질의를 마칩니다. 
</p>
<p><b>○ 위원장 김영복 </b> 전동석 위원님 수고하셨습니다.  보충질의하실 위원님 계십니까?  
</p>
<p style="padding-left:1.2em">  본질의하실 위원님, 장윤영 위원님 먼저 하시기 바랍니다. 
</p>
<p><b>○ 장윤영 위원 </b> 행정감사자료 695페이지 부분에 대해서 아까 자료가 다시 나간 것 있지요.  참고하시기 바랍니다.  695페이지 자료인데요.  새로 나눠준 자료 있지 않습니까.  이걸 같이 참고해 주시고요.  그다음에 바로 첫 번째 행정감사자료 연구과제 수행현황 있지 않습니까.  1페이지부터 확인해 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  먼저 맞는지 확인을 하겠습니다.  의뢰받은 연구과제 중 재위탁현황 중에서 25번 한미 FTA 체결에 따른 외국인 투자유치 활성화 방안 있지 않습니까.  발주처가 경기도 맞습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 그다음에 계약금액이 4억원입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 4억원이고 이걸 재위탁을 했는데 2,850만원에 7월 25일, 맞습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 
</p>
<p><b>○ 장윤영 위원 </b> 그러면 이건 샘플링을 했으니까 그다음부터 하겠습니다.  두 번째 것은 계약금액 경기도 발주에 4억, 그다음에 이거 재위탁한 게 7월 26일 맞습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 그다음에 세 번째 게 경기도에서 4억에 발주하고 그다음에 재위탁 7월 27일 했습니다.  그 다음에 네 번째 것 4억에 발주하고 7월 27일 재발주했고요.  다섯 번째 것 여기서 서로 다른 과제입니까, 아니면 1개 과제에서 분야별로 뿌려준 겁니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇게 이해하시면 되겠습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 그러면 5개 과제를 5×4=20, 20억을 받아서 한 거냐, 아니면 4억짜리 과제를 하나 받아서 분야별로 뿌린 거냐를 질의했는데 어느 겁니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 담당한 김은경 박사한테 설명을 드리도록 해도 괜찮겠습니까? 
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 수도권정책센터 김은경입니다.  저 과제는 일단 4억으로 경기도와 협약과제로 맺었고요.  그 안에서 6개 보고서가 나오는데 일단바깥으로 위탁 나간 것은 그 안에서 한 2억 5,000 정도가 나간 걸로 알고 있고요.  지금 4억, 4억 해서 오해를 하시는 거고요.  기본적으로는 4억짜리 협약과제 안에서 2,750 내지는 3,250 이런 식으로 6개 과제가 나갔습니다.  설문조사를 포함해서요. 
</p>
<p><b>○ 장윤영 위원 </b> 그러면 여기 자료 속에는 1개가 빠졌다라는 거네요?
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 지금 5개 했는데 그 안에서 설문조사가 빠졌습니다.
</p>
<p><b>○ 장윤영 위원 </b> 저기에 설문조사 있습니다.
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 한미 FTA 관련이 4개고…….
</p>
<p><b>○ 장윤영 위원 </b> 지금 여러분이 나눠주신 자료를 제가 이리로 옮겼습니다. 
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 지금 위에 외국인 투자유치 활성화 방안 맞고요.  두 번째 경기도의 수출진흥시책개선 방안, 그다음에 한&#8228;EU FTA 파급효과 맞습니다.  첫 번째 두 번째 됐고 농업부분 맞고요.  빠진 게 뭐냐 하면 한미 FTA 체결에 따른 수혜업종에 대한 경쟁력 강화대책, 피해업종에 대한 피해보전, 구조조정 지원 대책에 대한 설문조사가 있습니다.  그것 있고.  아, 경기도 경제관련 직무분석이 빠졌습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 직무분석이 지금 몇 번에 있지요?
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 제가 받은 재위탁 현황에서 32번입니다.
</p>
<p><b>○ 장윤영 위원 </b> 32번 여기는 FTA가 빠져 있습니다.  그렇죠?
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 그렇습니다.  
</p>
<p><b>○ 장윤영 위원 </b> 글자상에서 FTA가 빠져 있어서 제가 여기에 포함시키지 못했는데 그러면 재위탁 금액이 1억 8,500이 아니라 얼마라고 그러셨지요?
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 다 합쳐서 한 2억 5,000 정도가 되는…….
</p>
<p><b>○ 장윤영 위원 </b> 2억 5,000 정도?
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 알겠습니다.  그러면 이 부분에 대해서 질의하도록 하겠습니다.  그러면 결국은 경기도로부터는 1개의 과제로 4억에 받으셨습니까? 
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 그렇습니다.  협약과제 하나로 해서 제목은 한미 FTA 및 한EU에 따른 경기도 대응전략이라는 제목으로 받았고요.  그 안에서 제가 담당한 것이 뭐냐 하면 전반적인 위탁과제를 총괄하면서, 그리고 전반적인 경기도 중장기 지원전략을 제가 하나의 보고서로 만드는 것을 맡았고요.  나머지는 저희 내부 인력 사정이라든지 전문성 때문에 각 분야별로 전문가를 찾아서 위탁을 내보냈습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 김 박사님, 잠깐만요.  다음 화면 넘겨주시겠습니까.  여기에 2006년 위탁과제, 2007년도 수탁연구과제 있는데 지금 말씀하시는 게 이 중에 있습니까? 
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 아니요.  저 두 가지는 작년에 저희 자체 내 발굴위탁과제로 했던 거고요.  저 과제는 기본적으로 경제적 파급효과만 했습니다.  그리고 이번 협약과제는 그 파급효과는 이미 나왔기 때문에 이 파급효과에 근거해서 어떠한 식으로 경기도의 경제성장 전략과 외투의 유치 내지는 경기도 내 피해기업 내지는 수혜업종에 대해서 지원을 할 것인가에 대한 연구입니다.
</p>
<p><b>○ 장윤영 위원 </b> 아니요.  김 박사님, 지금 이건 바로 첫 번째 자료에서 제가 모은 겁니다.  FTA라고 들어간 것만.  5개, 그러니까 2006년도에 2개의 위탁연구과제가 있습니다.  
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 그렇습니다.  제가 했고요.
</p>
<p><b>○ 장윤영 위원 </b> 2개가 있었고요.  그다음에 2007년 수탁연구과제가 있었습니다.  그다음에 2007년 여기 자체 정책연구과제가 하나 있었고요.  그다음에 2007년 위탁연구과제 2개가 있습니다.  그렇다면 전 화면에 나왔던 것이 이 속에 있습니까, 없습니까? 
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 전혀 다른 겁니다.  제가 설명을 드리겠습니다.
</p>
<p><b>○ 장윤영 위원 </b> 지금 제 질의의 취지는 뭐냐 하면 FTA와 관련해서, 이건 다 독자적으로 발주된 것 아닙니까?  그렇죠?  이 화면은.
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 여기서 2007년 수탁연구과제 중 제가 수행한 것은 한미 FTA 국내 대책지원위원회에서 중앙에서 각 시ㆍ도 연구원들을 통합해서 의무적으로 하게 된 연구였습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 지금 제가 옆에다 표시를 해놨었는데요.  김은경 박사님이 하신 게 바로 2006년도, 그러니까 위에 2개 다 김은경 박사님께서 받으신 거고요.  그다음에 수탁연구과제 2007년도 이것도 김 박사님이 하셨습니다.  그렇죠?
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 그렇습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 그다음에 김군수 박사가 따로 한 것 있고요.  그다음에 2007년도 수탁과제가 하나는 이수행 박사님이 하셨고 맨 마지막 것은 김은경 박사님이 하셨고요.
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 네, 국가운영 패러다임 전환&#8228;전략.
</p>
<p><b>○ 장윤영 위원 </b> 그러면 한중 FTA 있지 않습니까?  
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 그건 이수행 박사님이 했습니다.
</p>
<p><b>○ 장윤영 위원 </b> 한중 FTA는 이수행 박사님이 책임연구자가 되어 있던데요.  
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 그러니까 지금 말씀드린 것은, 제가 질의를 하는 것은, 앞에 전 화면 으로 돌려주시겠습니까.  이게 보니까 1개의 과제를 5개로 뿌려서 갔는데 제가 제일 궁금한 게 있습니다.  여기서 제가 본 것이 실은 발주일자였습니다.  발주일자가 금년 7월인데 저희 행감 자료에 나온 것 있지 않습니까.  여기서는 2006년하고 2007년 동안에 발주한 것 보니까 2006년 8월, 2006년 10월, 2007년 3월, 2007년 4월 해당이 안 되고 있거든요, 앞의 사항하고.  그런데 두 번째 위탁연구과제 여기는 한&#8228;중이더란 말입니다.  한&#8228;중이기 때문에 아닐 것이고 이게 한미 FTA 체결에 따른 국가운영 패러다임 전환&#8228;전략이다 보니까, 그런데 앞의 화면은 전부 다 경기도거든요.  그러다 보면 경기도에서 과제수행으로 제출한 작업은 어디 있느냐는 겁니다.  이 속에 있습니까?
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 일단 제가 설명을 드리면요.  맨 마지막의 한미 FTA 체결에 따른 국가운영 패러다임 전환&#8228;전략은 도 의뢰 위탁과제입니다.  그렇고요.  다음에 현재 제가 알기로 경기도 추경에서 4억원의 예산이 추가되면서 저에게 오게 된 과제가 바로 앞에 화면에 떴던 여러 과제이고 이것이 과제가 여러 개로 찢어지게 된 것은 그 협약과제를 제가 받으면서 실제로 도청 실무진하고 의논을 하는 과정에서 저희가 경기도의 상황에서 무엇무엇이 필요한가 주제를 정해서 여섯 개로 잘라서 위탁을 내보내게 된 겁니다.
</p>
<p><b>○ 장윤영 위원 </b> 김 박사님, 그러면 지금 결국은 실제 여기는 다섯 개고요.  하나는 누락시켰죠.  이것의 원청작업은 이 행감 자료에는 없는 겁니다.  
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 원청작업이라는 것은 그전에······.
</p>
<p><b>○ 장윤영 위원 </b> 그러니까 4억짜리가 지금 이쪽의 위탁연구과제나 위수탁 이쪽에 자료가 기재가 안 돼 있습니다.  행감자료에 이것까지.
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 그건 협약과제입니다.  이건 정책과제가 아니고요.  저도 처음 알았는데 도청하고 협약을 해서 나온 과제라서 없답니다.
</p>
<p><b>○ 장윤영 위원 </b> 실질적으로 기본과제하고 정책과제는 예산 수반 없이 내부에서 하는 겁니다.
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 저희 내부 예산으로 하고요.  그렇습니다.
</p>
<p><b>○ 장윤영 위원 </b> 그런데 그게 바로 여기에 정책연구과제로, 그래서 표시를 해 놨습니다.
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 그러니까 일단 이건 김군수 연구원이 하셨고요.  위탁하고 수탁 있지 않습니까.  여기서 지금 제일 헷갈리는 게 그겁니다.  수탁을 받은 겁니다.  그렇죠?  그러면 여기서 위탁연구과제하고 수탁연구과제 외에 협약연구과제라고 또 별도로 있다는 얘기입니까?
</p>
<p><b>○ 수도권정책센터책임연구원 김은경 </b> 네, 협약과제입니다.  협약과제가 따로 있어서, 협약과제라는 건 저도 정확하게 모르는데 도청과 협약하에 도청의 업무를 저희가 대신 수행해 주는 거라고 얘기를 들었습니다.  그래서 4억짜리는 협약과제로 지금 수행하고 있는 중입니다.
</p>
<p><b>○ 장윤영 위원 </b> 김 박사님은 일단 앉아주시고요.  원장님께 질의를 하겠습니다.  지금까지 우리 기획위원회에서 분명하게 말씀드렸었던 것 자체는 오전에 질의를 했었던 겁니다.  기본과제, 그다음에 수탁과제, 정책연구과제, 기획연구과제, 위탁연구과제 다섯 종류라고 했는데 지금 새로운 게 나왔습니다.  협약과제가 뭐죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 협약과제는 제가 디테일한 것은 좀 더 물어봐야 되겠습니다만 이건 도의 의뢰를 받아서 그 돈에 대해서 오버헤드(overhead), 우리 연구원의 서비스에 대한 값을 떼지 않고 그냥 그대로 그 돈을 집행해서 연구해주는 과제고요.  수탁과제는 우리한테로 일단 요청이 오면 우리 원 안의 오버헤드를 다 정리하고 난 다음에 우리가 하는 그런 연구입니다.  그래서 협약과제가 어떻게 보면 경기도의 일을 그냥 바로 대신해 준다고 이렇게 생각하면 되지 않을까 하는 생각이 들고요.  그다음에 물론 지역연구과제가 또 따로 있죠.
</p>
<p><b>○ 장윤영 위원 </b> 잠깐만요, 원장님.  아까 기획담당하시는 분 계시죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리 이상훈 기획실장.
</p>
<p><b>○ 장윤영 위원 </b> 이상훈 기조실장님 자리에 나와 주시겠습니까.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기조실장 이상훈입니다.
</p>
<p><b>○ 장윤영 위원 </b> 혹시라도 다른 건 없습니까?  우리 김 박사님이나 원장님께서 말씀하신 내용이 오류에 의해서 나온 것일 수도 있습니다.  왜냐하면 이건 저희들은 문자를 따지는 사람들이고 실제 일을 하시는 분이시다 보니까 틀릴 수 있습니다.  다시 질의하겠는데 이 다섯 가지 과제에 협약과제라고 있습니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네, 있습니다.
</p>
<p><b>○ 장윤영 위원 </b> 그러면 문제가 될 수 있는 것 자체가요.  바로 행감자료에 연구과제 수행현황에서 협약과제는 빠져도 상관이 없습니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 대부분 협약과제의 경우가······.
</p>
<p><b>○ 장윤영 위원 </b> 단답형으로 가죠.  그러면 협약과제가 2007년도에 몇 건이나 있었습니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 6건으로 지금 자료상 나와 있습니다.  업무보고자료 28쪽에 7개 과제가 있습니다.  
</p>
<p><b>○ 장윤영 위원 </b> 업무보고 자료요?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 행감자료에는 없습니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네, 없습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 일단 이 부분에 대한 것은 지금까지 제가 기획위원회나 전문위원실에서 확인했을 때는 협약과제라고는 사실 들어보지 못했습니다.  이것에 대해서는 일단은 시간을 두고서 오늘 중에 다시 한 번 보겠습니다만 이건 다시 따지겠습니다.  실장님 들어가셔도 좋겠습니다.  원장님.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 조금 언급을······.
</p>
<p><b>○ 장윤영 위원 </b> 아니요.  일단 이것에 대한 것은 저희가 협약과제에 대해서 지식이 없기 때문에, 질의 속에서 나온 거기 때문에요.  이 문제는 질의 끝난 다음에 사실을 확인한 다음 다시 질의토록 하겠습니다.
</p>
<p style="padding-left:1.2em">  그러면 제 질의를 마무리하겠습니다.  화면을 봐주시죠.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  이건 다른 게 아니라 소위 말해서 FTA라는 것에 관련해서 지금 경기도가 발주한 연구과제입니다.  이게 말이 됩니까?  이건 정책을 위한 것이 아닌 것 같습니다.  연구를 위한 연구 아니냐.  이건 경발연의 문제가 아닙니다.  먼저 말씀드리겠습니다.  지금 여기에서 제가 자료 속에서 뽑아낸 게 6개입니다.  그런데 보니까 협약과제라는 게 또 있답니다.  FTA라는 것에 관련해서 6～7개, 10여개의 과제물이 나오고 있다라는 겁니다.  이건 전부 다 예산 수반이거든요.  최소한 아까 보면 4억대는 될 것 같습니다.  혹시 말씀 주실 수 있겠습니까?  이것 정책과제 빼놓고서 맨 위의 것부터 예산이 얼마인지 혹시 기조실장님 자료 있으십니까?  최소한 봤을 때 아까 김은경 박사님 나오신 게 그게 4억짜리였거든요.
</p>
<p style="padding-left:1.2em">  그렇다고 한다면 이건 한번 문제제기를 해 주십시오.  이건 경발연의 문제가 아니라 경기도의 문제일 수 있다.  소위 말해서 어떤 문제점이 발생을 했을 적에 연구를 남발하는데 이 형태로 보면 아마 농정국, 그다음에 경투실, 그다음에 기획관리실 정도에서도 서로 다른 부서에서 경발연에다가 연구업무를 맡기고 있는 것 아니냐.  그래서 시너지효과가 아니라 이건 분산돼서 실질적으로 시기를 놓치고 때를 놓치고 진짜 중복투자나 중복연구를 요청을 하는, 그래서 결국은 보면 경발연의 연구능력을 저하시키는 요인이 될 수도 있다라는 겁니다.
</p>
<p style="padding-left:1.2em">  그래서 이 문제에 대해서는 지금 본 위원이 이 행감자료 속에서 뽑아낸 것만 이만큼이라는 겁니다.  이러다 보면 아주 진짜 경발연에서 전체 종합을 해 가지고 경기도에 재고 요청해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  위원장님, 지금 제가 한 것은 도대체 이게 경발연의 문제점인지 경기도의 문제점인지 지금 파악이 도저히 안 되고 있습니다.  그렇게 하고 저는 이 협약과제에 대해서 업무 파악 후에 다시 질의토록 하겠습니다.  그래서 지금의 질의를 마치도록 하겠습니다.  이상입니다.
</p>
<p><b>○ 위원장 김영복 </b> 장윤영 위원님 수고하셨습니다.  장윤영 위원님 그렇게 하시죠.  나중에 기획관리실 감사가 아직 남아 있습니다.  그래서 거기서 총괄적으로 다시 질의를 해 주시기를 바랍니다.
</p>
<p style="padding-left:1.2em">  장윤영 위원님께서 의뢰받은 연구과제의 재위탁 현황에 대해서 오전에 이어 두 번째 질의를 해 주셨는데 여기에 대해 보충질의 계십니까?  안 계시면 제가 사과를 드립니다.  임우영 위원님이 아까 했는지 알고서 제가 시간을 못 드렸는데 죄송합니다.  본질의해 주시기를 바랍니다.
</p>
<p><b>○ 임우영 위원 </b> 장윤영 위원님이 방금 질의하신 그런 문제점 때문에 제가 경기도 학술용역에 관한 조례를 제정했어요.  그래서 이번 12월에 심의를 하니까 장윤영 위원님 적극적으로 검토를 해주셔서 앞으로 이런 일이 없도록 하는 데 같이 동참을 해 주시기 바랍니다.
</p>
<p><b>○ 장윤영 위원 </b> 네, 알겠습니다.
</p>
<p><b>○ 임우영 위원 </b> 우선 보충질의만 쭉 했는데요.  제 질의라 그래서 별다른 건 없습니다.  다만 제가 아까도 말씀드렸지만 외부기관에서 발주해 가지고 여러분들 경영평가를 했던 걸 중점적으로 해서 질의를 하겠습니다. 
</p>
<p style="padding-left:1.2em">  그것에 앞서 제가 금년 2월에 언론에서 15년 전의 풋내기 도의원의 질의다라는 사설까지 실명을 거론해 가면서 경기개발연구원에 질의를 했다가 아주 뭇매를 맞은 적이 있습니다.  바로 여러분들 홈피의 회원제 관련이었던 내용인 것 같아요.  그런데 제가 이렇게 보니까 여러분들도 이 사설과 뜻을 같이 하는 것 같아서 굉장히 가슴이 착잡합니다.
</p>
<p style="padding-left:1.2em">  우선 여러분들 제가 그 당시에 얘기했던 것이 주안은 뭐냐 하면 홍보였습니다, 홍보.  아무리 좋은 정책을 펴고 아무리 좋은 연구과제를 내놓더라도 이게 홍보가 안 되면 무용지물이다 하는 걸 제가 그 당시에도 여러분들한테 얘기를 했을 겁니다.  그런데 저와 뜻을 같이 하는 분이 계세요.  김문수 도지사도 보니까 이사회에서 똑같은 얘기를 했습니다.  여기 보면 이사회에서 당신이 하신 말씀 중에 이런 얘기가 나와요.  “지금까지 연구결과물을 우리 연구원 내에 한정되지 않고 도민과 외부에 적극 알리도록 하는 홍보활동에 주력하고 정기적으로 경기의 동향분석을 제공하여서 발표하도록 하는 사후 추진방향을 가지고 있어야 된다.” 하는 문제 지적을 했습니다.  이게 2006년도 12월 이사회에서 도지사가 한 얘기예요.  그런데 저는 금년 2월에, 물론 제가 늘 가지고 있는 평소 생각이 “행정이나 이런 데도 이제는 사기업과 같이 PR을 해야 된다.  그것도 적극적으로 해야 된다.”라는 것을 갖고 있기 때문에 그렇게 문제를 지적했는데 오늘 이사회 회의록을 보니까 우리 김문수 지사도 저하고 뜻을 같이 하는 것 같아서 굉장히 그런 쪽에서는 개인적으로 고무도 받습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저도 위원님과 뜻을 같이 합니다. 
</p>
<p><b>○ 임우영 위원 </b> 그런데 왜 제가 마음이 착잡하다고 얘기를 했냐 하면 여러분들 홈피를 보면 말이에요.  예를 들어서 회원에 등록하려고 하면 바로 홈페이지 창에서 회원가입 이런 게 딱 떠야 적극적이다라는 표현을 하는데 우리 경기개발연구원 웹사이트의 회원으로 가입을 하려면 연구보고서창에 들어가서 간행물 회원제 구입을 클릭하면 거기에 바로 신상 그걸 할 수 있도록 이렇게 아주 절차가 복잡합니다.  이런 것도 홍보차원에서, 여러분들 회원을 늘리고 줄이고 하는 그런 차원이 아니고 여러분들이 하시는 일, 진짜 심혈을 기울여서 박사님들이 본인의 이름을 내걸고 하는 연구결과물에 대해서 도민이나 우리 국민들한테 제대로 알릴 수 있는 것은 역시 요즘 정보통신기술이 하도 발달이 돼 있어서 웬만한 분들은 인터넷으로 다 보고 하니까 그런 부분에 있어서도 정기적으로 우리 경기개발연구원의 소식을 접할 수 있는 그런 회원들을 많이 확보하는 것이 더욱 바람직하지 않을까 하는 차원에서 먼저 그 점을 지적합니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 이해하겠습니다.  제가 한 가지 말씀을 드리면 저도 임우영 위원님과 똑같은 생각이라서 저희가 이메일을 통해서 연구결과라든가 연구원 동정, 동향 이런 것들도 보내는 시스템을 강화하고 기자분들한테 연구결과를 설명하는 일을 열심히 했는데 사실 그러다 보니까 우리 홈페이지하고 서로 이중으로 가는 그런 문제가 발생이 됐습니다.  그래서 아마 지금 임 위원님 지적하신 그런 문제가 발생하는 것 같아서 저희가 바로 홍보팀을 재구성해서 홈피를 바꾸는 일을 하고 있고 지금 지적하신 점을 감안해서 개선하도록 최선을 다하겠습니다. 
</p>
<p><b>○ 임우영 위원 </b> 그러면 여러분들 경영실적 평가보고서에 준해서 질의를 몇 가지 하겠습니다.  경영평가보고서는 최종 보고서를 받은 게 언제쯤입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 최종 보고서는 한 달쯤 된 것 같습니다.
</p>
<p><b>○ 임우영 위원 </b> 한 달요?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그 이전의 내용에 대해서는 저희가 이런 저런 경로를 통해서 어느 정도 알고 있었습니다만.
</p>
<p><b>○ 임우영 위원 </b> 최종 납품된 게 여기 인쇄상으로 보면 9월 17일인데 그런데 한 달이라면 좀 문제가 있는 것 아닙니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 좀 늦게 도착한 모양입니다.
</p>
<p><b>○ 임우영 위원 </b> 좋습니다.  여기 보면 2005년도 경영평가도 나등급이고 2006년도 나등급입니다.  우선 평균 이상의 등급을 받은 것을 제가 개인적으로 축하를 드립니다.  그런데 지난해에 개선사항으로 지적됐던 것이 아까 조선미 위원이 얘기했던 고객만족도조사입니다.  그런데 이게 전혀 개선이 안 됐는데요.  이게 다른 뜻이 아닙니다.  팔로우 업 프로세스(follow up process)에 대해서 미흡하다 하는 겁니다.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 무슨 프로세스요?
</p>
<p><b>○ 임우영 위원 </b> 팔로우 업 프로세스 미흡이요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 임우영 위원 </b> 그래서 이게 발주자를 대상으로 하는 만족도 조사인데, 그렇죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니다.
</p>
<p><b>○ 임우영 위원 </b> 그래서 여러분들이 하고 있는 이 조사 자체가 경영평가상에서 조사원들이 생각했을 때의 조사방법과 지금 경기개발연구원에서 하고 있는 조사방법이 차이가 있다.  지금 이 연구결과보고서를 보면 그런 차원에서 이건 개선이 돼야 된다고 얘기를 하는 것 같아요.  제가 쭉 읽어봤습니다.  이와 관련된 자료도 여러분들한테 요구를 해서 제가 그와 관련된 자료도 받아서 쭉 읽어봤어요.  그리고 우리 조선미 위원이 지적했듯이 조사결과 한계와 활용 그 내용을 보면 지금까지는 전부 똑같습니다.  무엇 때문에 그렇다 하는 내용이 그대로 다 돼 있어요.  그래서 아까 원장님께서 그것에 대해서 그렇게 지적하는 것에 대해서는 문제점이 있다라고 말씀을 하셨는데 그것을 죄송하지만 다시 한 번 말씀해 주시겠어요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우선 수요자 만족도조사라는 것이 이런 문제가 있습니다.  첫째 문제는 그게 중요한 조사고 그걸 통해서 우리가 개선할 건 개선하고 수요자의 입장을 만족시키는 게 대단히 중요하죠.  그런데 우리가 수익을 목적으로 하는 연구소라면 뭐든지 수요자가 원하는 걸 다 해 줄 수 있습니다.  100% 만족시키고 우리가 돈을 받아서 경영할 수 있죠.  그런데 공공연구기관으로서 저희가 할 일은, 여러분들 계속 지적하지만 객관적인 입장에서 옳은 얘기를 하라고 말씀을 하시잖아요.  바로 거기에서 이 문제가 발생할 소지가 있습니다.
</p>
<p style="padding-left:1.2em">  예를 들면 도에서 우리한테 위탁하는 것도 우리 연구원들하고 의견이 다를 수가 있습니다.  그리고 31개 시&#8228;군도 그렇고.  그러니까 우리한테 연구를 발주하는 사람들이 원하는 걸 잘해줘서 그 방향까지 포함해서 100% 만족시키는 데는 여러 가지 방법이 있죠.  그 사람들이 원하는 걸 그냥 해 주면 되는 것도 있고 원하는 방향이 잘못됐지만 이렇게 하는 게 좋다고 설득해서 옳은 방향으로 가게 할 수도 있고 그런데 이게 사실 여러 가지 개연성이 있기 때문에 불만족이라고 한 사람들의 불만족의 원인을 규명하기가 그렇게 간단치가 않습니다.  그렇다고 해서 저희가 이 불만족도조사에 대해서 나온 것 자체를 무시하거나 그런 게 절대 아니고 그럼 어떻게 하면 줄일 것이냐 하는 걸 정말 저도 개인적으로 고민을 하고 우리 박사들하고 머리를 맞대고 있는데 어렵습니다.
</p>
<p style="padding-left:1.2em">  그래서 우선 첫째는 만족도 수준을 가능하면 높이는 쪽으로 가고, 그렇다고 해서 100% 만족은 못 시킬 것이다.  그렇지만 불만족인 사람들의 경우를 우리가 확인해서 그 불만족의 원인과 그 연구에 참여를 했던 주책임자라는 사람들이 수요자하고 계속 접촉을 한 사람들이니까 개인적으로 그런 좋지 않은 평가를 받은 사람들로 하여금 뭐가 문제였는지를 확인해서 차후에 그런 평가가 안 나오도록 어떻게 할 것인지에 대해서 고민을 하지만 여기에 또 하나 계속적으로 제가 지적을 합니다만 그렇다고 해서 100% 그 사람 원하는 것만을 다 해줄 수 없다 그런 한계가 항상 있지만 다시 되풀이 말씀을 올리면 만족도를 높이도록 노력을 하겠습니다.
</p>
<p><b>○ 임우영 위원 </b> 연구결과가 발주자의 의도와 똑같을 수는 없습니다.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 그것을 많이 경험하고 있습니다.  특히 수탁되는 건 그렇습니다. 
</p>
<p><b>○ 임우영 위원 </b> 예를 들어서 수탁하는 데서는 A라는 것이 옳다라고 자기는 개인적으로 판단해서 의뢰를 했는데 연구를 해 보니까 A가 아니고 B가 옳을 수도 있는 거고 그런 차이점에서 오는 불만도 있을 겁니다.  그래서 여러분들이 할 수 있는 그러한 개선사항에 대해서 계속 고민을 하고 계시다니까 그런 연구결과물에 대해서 꼭 그러한 결과가 본인의 의도와 다른 그런 거라면 그런 차원에서는 이해가 충분히 갑니다.  그런데 여기 여러분들이 개선사항에 대한 의견 요지라고 해서 나온 것 중에 보면 예를 들어서 연계방안과 관련 법령 검토가 미흡하다든지 아니면 홍보문제를 간과했다든지 아니면 자기하고 수시로 문제점에 대해서 협의를 안 했다든지 하는 것들은 문제가 있지 않나 하는 거죠.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리가 고칠 수 있는 사항이죠.
</p>
<p><b>○ 임우영 위원 </b> 최소한 이런 것들에 대해서 연구과정에서 충분히 검토도 하고 서로 의견도 주고받고 해서 결과물이 본인의 의도와 다르게 나온 것에 대해서는 별 문제 없지만 그렇지 않고 이런 걸 해야 될 것도 안 하고 나오는 것에 대해서는 문제가 있다 하는 점을 지적을 드립니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 잘 알겠습니다.
</p>
<p><b>○ 임우영 위원 </b> 그리고 또 하나가 조직과 관련된 내용들입니다.  예를 들어서 구성원들의 자긍심 및 성취감이 점점 사라지고 있다 하는 내용이 있어요.  이건 왜 그렇다고 생각합니까?  왜 이 사람들이 그런 식으로 평가를 했다고 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그게 제가 알기로는 우리 연구원 직원들을 대상으로 와서 평가를 한 걸로 알고 있습니다.  그런데 저희 연구원에 직원이 다양하게 구성돼 있습니다.  오늘 제가 보고드린 저희 직원은 정규직 직원이죠.  이 정규직 직원 말고도 연구사업에 참여하는 위촉연구원들도 있고 다양한 구성이 있는데 그런 면에서 소위 비정규직이라고 표현을 드리겠습니다만 그쪽에서 항상 그런 문제가 있다.  이건 연구원이 무슨 일을 하느냐에 관계없이 석사급 위촉연구원의 입장에서는 사실 연구원이 비전이 있을 수가 없죠.  그런 점은 저희가 좀 알면서도 그걸 우리 연구원이 풀어줄 수 있는 방법이 별로 없기 때문에 그런 게 많이 반영됐지 않을까 그런 생각이 있습니다.
</p>
<p><b>○ 임우영 위원 </b> 원장님 말마따나 바로 여기도 지적한 게 이러한 자긍심이나 성취감을 고취할 수 있는 프로그램이 없다 하는 것을 지적했거든요.  그러니까 조직 전체가 자긍심도 갖게 할 수 있는 프로그램을 원장님이 개발을 해서 활용을 했으면 좋겠다는 생각이 들고요.
</p>
<p style="padding-left:1.2em">  그 다음에 인적자원 관리 면에서도 보면 연구직 성과평가체계의 개선이 필요하다.  제가 그래서 자료로 받았습니다.  개인적인 성과평가체계가 어떻게 돼 있나 봤더니 연구직 같은 경우 연구의 양, 얼마만큼 많이 했느냐가 30%고 또 연구의 질 평가가 30%고 일반근무평가가 40% 해서 100%를 기준으로 해서 돼 있더라고요.  그렇죠?
</p>
