<p><b>○ 임우영 위원 </b> 그런데 이게 어떤 점에서 개선이 돼야 된다고 이분들은 생각을 했을까요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 평가한 사람들의 견해는 이런 것 같습니다.  우선은 질 평가가 좀 더 강화돼야 된다 그건 저도 개인적으로 동감입니다.  30, 30이 아니라 질 쪽이 더 많이 강화돼야 된다 그런 것 같고 그다음에는 질을 높이기 위해서는 내부 서로 간의 평가는 그 평가에서 신뢰성이 떨어질 가능성이 있어서 외부의 평가자를 좀 더 많이 둬라 하는 얘기입니다.  그래서 제가 아까 이전에도 말씀을 올렸습니다만 연심회라든가 이런 걸 하는 과정에서 외부 평가자의 비중을 더 높이는 쪽으로 개선을 했습니다.  물론 그렇다고 해서 그게 다 좋은 방향으로만 가리라고 생각은 못하겠지만 한 가지 보완책이 연심회라든가 이런 과정에서 외부 전문가를 더 많이 해서 우리 안에서 하는 사람뿐만이 아니라 밖에서 객관성도 높이고 그다음에 질평가를 강화하는 쪽으로 이렇게 해 나가는 그런 노력을 경주하려고 그럽니다.
</p>
<p><b>○ 임우영 위원 </b> 그래서 제가 여러분들 연심회의 회의록 사본, 평가보고서 사본을 자료 요청을 해서 봤습니다.  제가 이걸 보면서 또 많은 걸 느꼈습니다.  예를 들어서 중간 연심회 평가표에 제가 정말 보고 싶어 했던 난은 전부 가려 가지고 복사를 해서 저한테 자료 제출을 해 주셨어요.  예를 들어서 정작 평가를 하면서 이 자료가 제대로 되고 있는지 안 되고 있는지를 나타내는 척도가 이 보고서에 있어야 되는데 그 부분은 전부 가려서 저한테 제출을 해 줬어요.  그럼 제가 여기서 뭘 보고 해야 됩니까?  여기서 어느 분이 글씨를 그냥 막 날려 써가지고 제대로 알아볼 수도 없을 정도로 쓴 그걸 내가 문제 지적을 해야 됩니까,  아니면 워드로 깨끗하게 쳐 가지고 진짜 성심성의껏 해 가지고 뒤에다 첨부물까지 붙여 가지고 심사를 해 주시는 분들을 잘했다고 평가를 해야 됩니까? 
