<p><b>○ 임우영 위원 </b> 그래서 전화가 왔어요.  이 자료를 만드시는 분한테 전화가 왔습니다.  그래서 제가 뭐라고 그랬냐.  “다른 분한테 드릴 필요 없고 저만 주십시오.” 제가 그렇게 말씀을 드렸어요.  그런데 이걸 책자로 만들었더라고요.
