<p><b>○ 조선미 위원 </b> 조선미 위원입니다.  아까 제가 만족도조사에 대해서 질의를 드렸었는데요.  지금 연구결과 만족도설문조사 딱 3개입니다.  상기 연구과제의 결과에 대해 어느 정도 만족하셨습니까?  그다음에 상기 연구과제의 결과가 귀 기관의 정책활용에 어느 정도 기여했다고 보십니까?  상기 연구과제의 결과에 대해 아쉬운 점이나 개선할 사항이 있다면 적어주십시오.  원장님, 이 설문지에 대해서 어떻게 생각하십니까? 
