<p><b>○ 조선미 위원 </b> 그래서 보니까 그런 식으로 있고 뒤쪽에 말씀하신 것처럼 조금씩 변화를 가져오는데 제가 보니까 아무래도 재위탁하는 건에서 이런 피드백들이, 만약에 고객만족도조사 결과에서 고객이 만족하지 못한다는 것은 연구원에 전화해서 뭘 물었는데 그것을 재위탁했으니까 그 요구사항이나 문의사항에 대해서 바로바로 피드백이 신속하게 이루어지지 않으니까 거기에 대해서 감정들이 쌓이게 되고, 그다음에 현장 중심적인 실질적인 사실은 거의 다 위탁하고 있으니까 그런 상황 파악이 좀 안 되니까 실무진하고 의견 교류하는 데 좀 부족하지 않나 이런 것들이 나타나서 그런 것들이 한두 개 나타나는 것 같습니다.  그래서 이렇게 재위탁사업 같은 경우에 어떻게 사후관리를 계획하고 계신지 말씀해 주시기 바랍니다. 
