<p><b>○ 경기개발연구원장 좌승희 </b> 재위탁의 경우에는 다 아시겠지만 원내에 연구책임자가 있습니다, 수탁과제도 물론 그렇지만.  연구책임자가 중심이 돼서 하는데 저희가할 수 있는 건 이런 문제의 소지를 알아서 책임자가 위탁처하고, 그러니까 발주처하고 사전에 대화를 많이 하도록 하는 길밖에 없다고 봐요.  그래서 제가 계속 강조하는 것이 사전에 문제를 파악하는 과정도 그렇고 연구의 아젠다를 정하는 과정에서 발주처와 보다 많은 대화를 하는 게 제일 중요하다, 서로 이해를.  아까 처음에 저희가 위원님들 요청한 자료를 가지고 핀잔을 많이 들었는데 바로 그런 문제가 우리가 수요자하고 서로 대화가 잘 안 돼서 그런 거지요.  저희가 조금 더 친절하게 그런 노력을 해서 불신을 우선 없애고 그런 다음에는 저희가 꼭 발주처가 요구한다고 그래서 그것만 따라갈 게 아니라 우리가 보는 입장에서 옳은 걸 설득하고 또 얘기하는 그런 과정을 거치고 그래서 연구의 질을 높이는 쪽으로 노력도 하고 이렇게 하는 수밖에 없지 않을까.  대단히 대책 없는 말씀처럼 들리겠습니다마는 지금 제가 드릴 수 있는 말씀이 이 정도임을 양지해 주시기 바랍니다. 
