<p><b>○ 경기개발연구원장 좌승희 </b> 제가 설명을 올려도 되겠습니까?  이 국내출장이 여러 가지 종류가 있습니다.  우선 프로젝트를 하기 위한 출장이 제일 많고요.  31개 시ㆍ군과 관련된 일을 할 때는 거기 가서 있는 것이 연구하는 일이기 때문에 출장이 무슨 버리는 일이 아닐 뿐만 아니라 국내 학회 가는 거는 한나절 가는 것, 도청에 위원회 참석하는 것도 한두 시간 가는 거니까 국내출장을 너무 무리하게 하루나 이렇게 생각하면 오해의 소지가 있고요.  해외출장은 아시다시피 시간을 풀로 쓰는 거지만 그것도 가서 다 프로젝트 하는 겁니다.  저희 연구원에서 하는 거의 모든 연구가 외국의 케이스 스터디를 하지 않고는 보고서를 낼 수가 없습니다.  그래서 외국에 가서 우리보다 선진지역의 변화를 보면서 하는 거니까 그것도 보면 다 공부하러 가는 거기 때문에 그렇게 이해를 해주시면 좋겠습니다. 
</p>
<p><b>○ 김대원 위원 </b> 좋습니다.  그리고 2006년, 2007년도에 국제학술발표회에 참석하신 건이 제가 파악하기로는 3건이거든요.  그런데 논문보고서를 혹시 받아보셨습니까? 
