<p><b>○ 경기개발연구원장 좌승희 </b> 178페이지 같은 경우는 연구원에 이정훈 박사가 쓴 모양인데요.  이것은 우리 연구원에서 했던 연구프로젝트 결과를, 경기도도 중요한 케이스 스터디가 되니까요.  
</p>
<p><b>○ 김대원 위원 </b> 그러니까 순수 영문으로만 이렇게 보고서가 작성되어 있으니까 이것을 인용이나 활용할 수는 없다는 얘기지요.  기왕에 이렇게 책자를 만들어서 인용할 정도라면 번역이라도 해서 같이 공유할 수 있는 이런 방안이, 기왕에 논문을 발표했으면 논문 발표자도 다른 부분에서 인용이 된다면 살아있는 논문이 안 되겠습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다.  그런데 제가 의견의 취지는 충분히 이해를 하는데요.  아까도 말씀드렸지만 이정훈 박사 같은 경우도 그렇고 다른 경우도 우리가 국문으로 연구한 것을 이렇게 전환하는 경우가 많기 때문에 이것을 다시 국문으로 번역하라고 그러는 것은 사실은 대단히 과중한 요구입니다.  그래서 필요하다면 영문 페이퍼에 관련된 국내 연구를 같이 위원님들한테 전달을 하거나 이렇게 할 수는 있는데 이것을 다 번역해라 하는 것은 원장으로서 하기가 어려운 일이 아닌가 하는 생각이 드네요.
</p>
<p><b>○ 김대원 위원 </b> 그렇습니까?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 김대원 위원 </b> 그래서 2006년, 2007년에 학술대회에 발표한 게 3개인데 전부 다 원문으로만 되어 있으니까 사실상 인용하기는 상당히 어렵지 않느냐라는 부분이라서 한번 건의드린 거고요.
</p>
<p style="padding-left:1.2em">  또 한 가지만 더 하겠습니다.  제가 자료를 요구하니까 이만한 책을 3권이나 줘가지고, 그렇다고 자료는 이만큼 내놓으라고 그러고 발언을 안 하면 또 연구원 무시하는 처사라 그럴 거고, 그래서 하권 309페이지하고 361페이지를 한번 보십시오.  하권 309페이지를 보십시오.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이정임 박사…….
</p>
<p><b>○ 김대원 위원 </b> 이정임 박사가 일본 환경부로 갔다오신 거지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 김대원 위원 </b> 그 뒷페이지 내용을 한번 보십시오.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이것은 뭔가 잘못된 거 아닌가…….  이것은 다른 겁니다.  아마 출장보고서가 누락됐거나…….
</p>
<p><b>○ 김대원 위원 </b> 아닙니다.  그러니까 그다음에 361페이지를 한번 봐주시라니까요.  여기 이상대, 김태경 박사님이 미국 대도시권 운영 때문에 간 건데 여기에 내용을 한번 보십시오.  이거 맞는 겁니까?
</p>
<p style="padding-left:2.4em">    (「앞부분에 있습니다」하는 관계직원 있음)   
</p>
<p style="padding-left:1.2em">  그러니까 “책 이만하게 만들어줬으니까 너희들 숨은그림찾기 하듯이, 3권 다 읽어 보겠어.  그러니까 숨은 그림 찾듯이 너희들 알아서 찾아라.”
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 위원님 그렇게 말씀하셔도 사실 이렇게 돼서 저희가 변명의 여지가 없습니다.  그런데 저희가 어떻게 그런 생각을 가지고 했겠습니까?  그래서 저희 업무불찰에 따른 거라고 생각하고 제가 대단히 죄송하다는 말씀을 드리겠습니다. 
</p>
<p><b>○ 김대원 위원 </b> 제가 왜 이 질의를 드렸냐 하면 사실상 저희들도 그렇습니다.  늘 위원들이 지적받는 일이 아무런 관계없는 과도한 자료요구를 해서, 본연의 임무에 차질을 줄 정도로 과도한 자료를 요구한다.  그리고 또 제 생각에 이렇게 책자를 만들 때는 아마 상당한 금액이 투입됐을 거라고 보는데 이것을 다른 데서 이렇게 만들었다면 이해를 하겠습니다.  그런데 이것은 출장 갔다 오면 누구든지 다 내는 출장보고서 그냥 이렇게 번호순대로 나열해서 꿰매주면 되는 그런 부분인데도 결과적으로 아무런 관심도 없이 많으니까 그냥 꿰매서 던져 준 부분으로 느껴지고요.
</p>
<p style="padding-left:1.2em">  아까 제가 착오를 일으켜서, 날짜별로까지 착오가 있었는데 그러다 보니까 이 착오가 분명히 출장 갔을 때, 또 여기 출장 처음 계획일자, 그리고 그때 그 사람이 한국에 있었다고 이렇게 나오니 3개가 다 다를 정도로, 착오를 일으킬 수 있을 정도니까 좀 일목요연하게 만들어 주시고 이렇게 상세하게 자료를 준비해 주셔서 감사드립니다.
</p>
<p style="padding-left:1.2em">  그리고 만약에 이런 출장보고서 중에 3개의 논문이, 학술대회에 발표한 논문, 2006년, 2007년 해가지고 3개 맞긴 맞습니까?  제가 알기로는 3개인데. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 제 기억에 그 정도 간 것 같아요. 
</p>
<p><b>○ 김대원 위원 </b> 그렇게 2년에 3개밖에 학술대회에 발표를 못할 정도면 그런 거라도 진짜로, 아까 한글로 다시 번역하는 것이 어려우면 그 부분을 발췌해서, 아마 이 원문을 보고 시ㆍ군 관계자가 그런 사례를 인용할 수 있는 사람은 많지 않다고 생각됩니다, 박사님들이 자문해 주지 않는 이상에는.  그러니까 좀 쉽게 풀어서 같이 공유할 수 있는 그런 대책도, 아니면 학술발표를 한글로 다 풀라는 게 아니라 이런 내용이 이렇게 응용됐다라고 간단하게 편집집이라도 달아주시면 상당히 도움이 되지 않을까 하는 뜻에서 말씀드립니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 한국말로 간략하게 반 페이지나 한 페이지짜리 주요 요약을 붙여서 출장보고서를 낼 때 같이 낼 수도 있지 않을까 하는 생각이 드는데 좌우간 저희가 그 방안을 한번 강구해 보겠습니다마는 번역을 다 하라고 하는 것은…….
</p>
<p><b>○ 김대원 위원 </b> 연구원에 수많은 박사님들 계신데 2년에 학술발표 세 번밖에 못하는 그런 어려운 것을 저희들이 이해하겠습니까마는 하여간 그렇게 어려운 것을 했으면 진짜로 시ㆍ군 부분을 인용했다든가 그랬을 경우에는 설명될 수 있고 인용될 수 있는, 그런 학술이 공용될 수 있는 이런 부분이 이루어졌으면 좋겠습니다.  하여간 이것은 제 개인적인 사항이기도 합니다.  좀 문외한이라서 무례하게 말씀드렸어도 이해를 해주십시오. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 별말씀을요.
