<p><b>○ 임우영 위원 </b> 우선 저희들한테 주신 이 서류가 전부 문서화되어 있지요?  전부 온라인으로, 이메일로 보내줄 수 있는 자료들이지요?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 다 그렇게 되어 있습니다.  그렇다고 봐야지요.
</p>
<p><b>○ 임우영 위원 </b> 예를 들어서 디스켓으로 한 장을 만들어서 주거나 이러면 더욱 더 편하겠지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇죠.
