<p><b>○ 임우영 위원 </b> 어떻습니까?  자료를 전부 취합해서 디스켓 1장으로 만들어 주면 더 좋겠지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇게 할 수 있습니다. 
