<p><b>○ 임우영 위원 </b> 알겠습니다.  제가 그렇지 않아도 지금 생각하는 것 중의 하나가 그런 것을 디스켓으로, 서면으로 주고받는 것을 정보통신이 발달되어 있는 우리 현실을 감안해서 행정에도 디지털행정을 했으면 좋겠다.  그래서 문서가 없는 행감 이런 것도 한번 고려해볼 필요가 있지 않나 해서, 제가 그러면 생각하고 있는 것을 좀 더 연구해서 한번 해보도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 아까 제가 도정 현안 자료 요청한 것 중에 경기도립의료원 운영검토 의견 해가지고 한 게 있습니다.  이거 혹시 내신 분이 계신가요?  
