<p><b>○ 경기개발연구원장 좌승희 </b> 한번 들은 적이 있는데 기억이 나지 않습니다.  세 사람을 지금 우리가 법에 의하면 써야 되는 책임이 있습니다.
</p>
<p><b>○ 임우영 위원 </b> 이분들을 의무적으로 고용을 해야 되는데 못해서 부담금이 한 100만원 정도 나가겠네요?
