</p>
<p><b>○ 행정과장 김용수 </b> 아닙니다.  1인당 750씩이니까 저희가 1,500이었거든요.  그러니까 절반이니까 375만원 해서 700만원 가까이 됩니다. 
</p>
<p><b>○ 임우영 위원 </b> 그런데 지금 보니까 작년도에도 정원을 다 채우지 못해서 인건비가 불용이 되고 이런 것이 여러분들 결산보고에 보니까 돼 있더라고요.  그런 부분도 고용을 하는 데 있어서 이런 부분도 한번 고려를 해서 장애인을 채용하는 데도 관심을 가져주셨으면 좋겠다 하는 차원에서 말씀을 드렸고요.
