<p><b>○ 정책분석팀장 유영성 </b> 네.
</p>
<p><b>○ 임우영 위원 </b> 제가 서두로 이유를 말씀을 드려야 이해가 가실 것 같아서.  지금 파주에 도립의료원이 있습니다.  그런데 이게 시설이 굉장히 노후돼 있어요.  그래서 재건축은 병상수도 늘리고 운영을 개선하겠다 해서 보사부에서 국비도 연차적으로 지원을 하도록 돼 있고 금년도에도 제가 나와 있는 걸로 알고 있습니다.  그런데 금년도 한 달밖에 이제 여유가 없는데 아직까지도 이게 전혀 진척사항이 없어요.  그래서 제가 여기를 보니까 “흑자경영을 하기 위해서는” 해서 한 7개를 쭉 했습니다.  병상수는 250에서 300병상을 유지해야 되고 100병상당 75.6명의 직원수를 유지해야 되고 해서 한 일곱 가지가 있는데 지금 도에서 하는 파주의료원의 현대화사업을 보면 증축 후에도 병상수가 220밖에 안 돼요.  그렇죠?  그러면 앞에 기본적인 흑자 충족요건에는 일단 안 맞는 거죠.  그래서 이 부분도 제가 지사님께 문제제기를 해서 얘기를 드렸는데 파주 같은 경우는 종합병원도 하나 없어요.  하나도 없는데 우리 도립병원이 그나마 종합병원 역할을 하고 있습니다.  수원 같은 경우는 제가 봤을 때 종합병원도 많은데 여기는 또 병상수를 330으로 증축을 해야 되고.  저 개인적인 생각은 말이에요.  수원 같은 데 도립병원 있을 이유가 없습니다.  흑자를 내면 그나마 이해가 가는데 적자 내면서 이렇게 일반 민간 종합병원들이 여럿 있는 곳에 도에서 병원을 운영하면서 적자를 내서 도 재정을 악화시킨다는 건 문제가 있다 저 개인적으로 그렇게 생각을 하거든요.  지사님한테도 그렇게 제가 말씀을 드렸는데 제가 왜 여쭤보고 싶으냐 하면 여기에 이렇게 220개 정도의 병상을 현대화하는 데도 지사님이 지금 여러 가지 문제점 때문에, 노조문제라든가 이런 걸 빌미로 진행을 하고 있지 않은데 우리 도립의료원에 대한 그냥 일반적인 의견을 제가 한번 듣고 싶어서 오시라고 그랬습니다.  도립의료원의 운영에 대해서 평소에 가지고 있는 생각이 있으시면 한번 말씀을 해 주세요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그런데 두 사람 중에 진짜 전문가가 누구예요.  두 사람이 다 이걸 같이 일을 해서.  당신이 얘기할 수 있는 거예요?  김희현 박사 이리로 나오세요.  죄송합니다.  위원님 중간에······.
</p>
<p><b>○ 사회문화연구부책임연구원 김희현 </b> 사회문화연구부의 김희현입니다.  
</p>
<p><b>○ 임우영 위원 </b> 제가 질의를 했는데요.  다시 해야 됩니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 다시 해야 될 필요는 없고요.
</p>
<p><b>○ 임우영 위원 </b> 예를 들어서 제가 물은 건 그겁니다.  우리 박사님이 이 검토의견을 내셨는데 박사님이 가지고 있는, 저는 파주병원을 예를 들었어요, 가지고 있는 도립의료원을 어떻게 했으면 좋겠는지.  제가 일단 도움을 드리기 위해서 말씀을 드리면 지사님하고 이야기할 때 “의정부와 수원에 있는 도립의료원은 없앱시다.  오히려 거기 들어가는 재원을 나머지 도립의료원에다가 해 주십시오.”라고 제가 요구를 했거든요.  그런 상황이기 때문에 일반적인 의견을 한번 듣고 싶습니다.
</p>
<p><b>○ 사회문화연구부책임연구원 김희현 </b> 개별적으로 저도 사실은 도립의료원과 관련해서 전공은 아니고요.  엄격하게 구분이 돼 있거든요.  보건의료하고 사회복지는 구분이 되어 있는 상태에서 저 같은 경우는 전공이 사회복지인데 가장 연관돼 있다고 그래서 도립의료원에 대한 검토의견을 제가 제시를 했습니다.
</p>
<p style="padding-left:1.2em">  그렇기 때문에 6개 의료원의 개개의 경영성과라든지 이런 것들은 지금 당장은 정확하게 기억은 나지 않는데요.  그때 검토의견을 위원님도 보셨겠지만 제가 생각할 때는 경영성과에 못미치는 그런 곳은 폐쇄조치를 하는 것이 낫다, 그다음에 각각 6개 도립의료원 중에서 법적으로 정해진 의료과목들이 있는데 그중에서 개별적으로 판단을 했을 때 성과가 나지 않는 과목들은 법적으로 운영을 한다고 하더라도 그런 진료과목들은 없애면 좋겠다라는 그런 의견을 개진했거든요.
</p>
<p><b>○ 임우영 위원 </b> 그러니까 여기에 있는 매각조치를 심각하게 고려하는 것도 좋겠다라고 얘기를 한 부분에 대해서 제가 확인을 한 겁니다.  무슨 말씀인지는 알겠습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 위원님 죄송합니다.  저희가 약간 혼선이 있어 가지고.
</p>
<p><b>○ 임우영 위원 </b> 아니요.  제가 왜 이걸 확인하냐 하면 지금 파주 같은 경우 처음에 금년 초에 추진을 했어요.  지하주차장 요건을 강화하라는 파주시의 조건부 동의가 설계상 반영이 안 되는 바람에 결국 이게 질질 끌어서 1년이 다 됐습니다.  지난해 연말에 이게 추진이 됐었는데.  금년에 지금 예산이 나와 있는데 결국 이것 불용으로 내년도로 이월을 시키는 거예요.  국비도 나와 있고.  그런 문제점이 있기 때문에 그걸 제가 예결위 하는데 여러 가지 도움이 될까 싶어서 개인적인 의견을 여쭤봤습니다.  이상입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 감사합니다.
</p>
<p><b>○ 위원장 김영복 </b> 임우영 위원님 수고하셨습니다.  질의하실 위원님 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원이 안 계시므로 이상으로 경기개발연구원에 대한 질의와 답변을 모두 마치겠습니다.
</p>
<p style="padding-left:1.2em">  장시간 열의를 갖고 감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료 준비와 위원님들의 질의에 성실히 답변해 주신 좌승희 원장님을 비롯한 임직원 여러분에게 감사를 드립니다.  오늘 여러 위원님들께서 감사 시에 지적해 주신 사항은 도민의 뜻인 만큼 이를 겸허히 받아들여서 연구원 업무에 적극 반영하여 경기도의 싱크탱크인 경기개발연구원이 한 단계 도약할 수 있도록 최선의 노력을 다해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 연구원 임직원 여러분!  수고 많으셨습니다.  그러면 이상으로 경기개발연구원에 대한 2007년도 행정사무감사를 모두 마치겠습니다.
</p>
<p class=''ar''>(18시28분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원
</b></p>
<p class=''aMan''>김영복이해문조선미권혁조김기수김대원임우영장윤영전동석정인영</p>
<p class=''aMan''>진종설</p>
<p><b>○ 출석전문위원
</b></p>
<p class=''em15''>   박춘배
</p>
<p><b>○ 피감사기관 참석자 
</b></p>
<p><p class=''em15''>경기개발연구원장 좌승희부원장 신원득</p>
<p><p class=''em15''>기획조정실장 이상훈사무처장 이정열</p>
