            <div','경기도의회',false,'{"legacy_id": "audit-2390", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2390"}'::jsonb,'2007-11-16'::date,'2007-11-16'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-2390');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2006.11.21. 화요일] 경기개발연구원 — 기획위원회 2006년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제7대 경기도의회 기획위원회</b> · 2006년도 행정사무감사(2006. 11. 20. ~ 2006. 11. 29.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=2440" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2006년도 행정사무감사
</p>
<h4>기획위원회 회의록 
</h4>제2호
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 2006년 11월 21일(화)
</p>
<p>장  소 : 경기개발연구원회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시18분 감사개시)
</p>
<p><b>○ 위원장 김영복 </b> 좌석을 정돈하여 주시기 바랍니다.  지금부터 지방자치법 제36조, 동법 시행령 제16조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기개발연구원에 대한 2006년도 행정사무감사를 시작하겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기개발연구원 원장을 비롯한 임직원 여러분!  안녕하십니까?  기획위원회 감사위원장 김영복입니다.  오늘은 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다.  여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2007년도 예산안 심사자료 및 정보획득을 통해 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 할 수 있습니다.  따라서 감사위원 여러분께서는 도민을 대표하여 도비출연기관인 경기개발연구원의 운영실태를 감사하는 것인 만큼 심도있는 감사활동으로 소기의 성과를 거둘 수 있게 되기를 기대하며 아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 당부드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다.  감사를 받는 원장 및 실ㆍ부장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다.  증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2006년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다.  만약 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법규정에 의하여 500만원 이하의 과태료가 부과될 수 있음을 알려드립니다.
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인 출석여부를 확인하겠습니다.  피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. 
</p>
<p style="padding-left:2.4em">    (일동기립)
</p>
<p style="padding-left:1.2em">  원장 나왔습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 부원장 나왔습니까? 
</p>
<p><b>○ 경기개발연구원부원장 신원득 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 기획조정실장 나왔습니까? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네. 
</p>
<p><b>○ 위원장 김영복 </b> 사무처장 나왔습니까? 
</p>
<p><b>○ 사무처장 이정열 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 수도권정책센터장 나왔습니까? 
</p>
<p><b>○ 수도권정책센터장 이상대 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 자치행정연구부장 나왔습니까? 
</p>
<p><b>○ 자치행정연구부장 이용환 </b> 네. 
</p>
<p><b>○ 위원장 김영복 </b> 도시ㆍ지역계획연구부장 나왔습니까? 
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이외희 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 교통정책연구부장 나왔습니까? 
</p>
<p><b>○ 교통정책연구부장 조응래 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 환경정책연구부장 나왔습니까? 
</p>
<p><b>○ 환경정책연구부장 성현찬 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 경제사회연구부장 나왔습니까? 
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 네.
</p>
<p><b>○ 위원장 김영복 </b> 다음은 선서의 요령을 설명드리겠습니다.  선서는 증인을 대표해서 원장이 발언대로 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손만 들어주시면 되겠습니다.  그러면 선서를 해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 본인은 경기도의회가 지방자치법 제36조, 동법 시행령 제16조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 소관업무에 대한 2006년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법 시행령 제17조의4제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제18조의 규정에 의하여 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다.  2006년 11월 21일 증인 원장 좌승희.
</p>
<p style="padding-left:2.4em">    (일동착석)
</p>
<p><b>○ 위원장 김영복 </b> 그러면 원장 나오셔서 간부소개와 업무보고를 해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 안녕하십니까?  경기개발연구원장 좌승희입니다.  존경하는 김영복 위원장님과 위원님 여러분을 모시고 금년도 주요업무 추진상황과 내년도 연구사업계획을 보고드리게 된 데 대해 감사의 말씀을 드립니다.  저는 올 7월에 원장에 취임한 이후 현재까지 짧은 기간이었고 미흡하지만 경기도의 싱크탱크로서 정책개발과 신속한 도정지원에 임직원들과 함께 노력해 왔습니다.  앞으로도 연구업무와 도정지원을 차질없이 추진해 나갈 수 있도록 할 계획입니다.  기획위원회 위원님들의 많은 도움과 성원을 당부드립니다.
</p>
<p style="padding-left:1.2em">  보고에 앞서 우리 연구원의 간부를 소개해 올리겠습니다.  먼저 신원득 부원장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상훈 기획조정실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이정열 사무처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상대 수도권정책센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이용환 자치행정연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이외희 도시ㆍ지역계획연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  조응래 교통정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  성현찬 환경정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김군수 경제사회연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  참고로 말씀드리면 수도권정책센터는 금년 8월에 수도권 경쟁력 강화와 규제개혁연구 등 수도권 정책을 전략적으로 전담 수행하기 위해 신설된 조직입니다.
</p>
<p style="padding-left:1.2em">  이상 간부에 대한 소개를 마치고 지금부터 우리 연구원의 주요업무를 보고드리도록 하겠습니다.  보고드릴 순서는 배부해 드린 유인물을 바탕으로 해서 일반현황, 재정운용, 2006년도 연구사업 추진상황, 2007년도 연구사업계획에 대해 중요사항을 중심으로 보고드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 유인물 1페이지를 봐주시기 바랍니다.  일반현황입니다.  저희 연구원은 ’95년에 개원 후 11주년이 되었으며 2004년 6월 23일 현 청사로 이전하였습니다.  연구원의 주요기능은 위원님들 이미 다 아시겠습니다만 도정의 비전제시와 정책개발을 위하여 기획조정실, 수도권정책센터 등 7개 연구부가 경기도 수요에 맞게 다양하고 깊이 있는 전문적인 연구를 수행하고 있습니다.  보다 자세한 사항은 배부해 드린 유인물을 참고해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 페이지로 넘어가겠습니다.  본원의 기구 및 인력에 대해서 말씀드리겠습니다.  본원의 기구는 1실 1처 1센터 6부이고, 현재 인력은 박사급 연구직 52명을 포함해 75명이 재직하고 있습니다.  
</p>
<p style="padding-left:1.2em">  다음 3페이지의 연구원의 시설 및 물자현황을 보고올리겠습니다.  먼저 청사는 2004년 6월 23일부터 경기도공무원교육원 6층에서 12층까지 대지 9,190평에 건평 1,656평을 사용하고 있습니다.  연구에 필요한 장서는 3만 6,000권 정도를 보유하고 있으며 주로 최신의 국내외 전문서적 및 경기도 관련 자료로 구성되어 있습니다.  또한 저희 연구원의 자료실은 일반시민, 학생, 공무원은 물론 사계의 전문가에 이르기까지 언제든지 방문하여 이용이 가능하도록 개방되어 있습니다.  전자도서관을 통해서 소장자료에 대한 검색뿐만 아니라 신간자료에 대한 정보를 제공하여 정보지식의 공유를 확대하고 보다 질 높은 서비스를 제공하고자 노력하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음 4페이지 말씀올리겠습니다.  재정운영 상황입니다.  먼저 올해의 총 예산 규모는 167억 3,600만원입니다.  수입재원은 출연금이 53%에 해당되는 88억원, 기금이자수입 등이 10%에 해당되는 16억 5,700만원, 사업수입이 4%인 8억 1,300만원, 전기이월금이 33%인 54억 6,500만원입니다.  지출항목으로는 연구사업비가 전체의 40.6%로 68억 800만원, 인건비가 34.4%로 57억 5,700만원, 부서운영비가 10.4%로 17억 4만원, 청사관리비가 4.8%로 8억 800만원, 예비비 및 기타가 9.7%인 16억 2,000만원 등입니다.  
</p>
<p style="padding-left:1.2em">  다음으로 기금현황에 대해 보고를 드리겠습니다.  금년도에 15억원을 추가 적립하여 총 272억원이 적립되었으며, 출연기관별로는 경기도가 54%인 147억원, 시ㆍ군이 15%인 39억 6,000만원, 민간부문이 7%인 20억원, 자체적립이 24%인 65억 3,900만원 등입니다.  참고로 자료에는 없습니다만 내년도 예산규모에 대해서 간략하게 보고올리겠습니다.  내년도 예산규모는 157억 1,600만원입니다.  이것은 지난해에 비해서 10억원 정도 감소된 수준입니다.  이중 연구사업비가 49%로써 76억 7,000여만원, 인건비가 35%인 55억 3,900만원, 부서운영비가 25억 1,100만원입니다.  이 예산은 앞으로 도의회에서 승인을 받고 집행되겠습니다.  예산집행에 있어 충실한 연구가 수행될 수 있는 여건 지원에 중점을 두어 내실있는 운영을 할 수 있도록 최선을 다하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 5페이지의 금년도 연구사업 추진상황 중 주요실적을 보고올리겠습니다.  5페이지를 참고해 주시기 바랍니다.  금년도에 저희 연구원 연구사업의 기본방향은 다음과 같습니다.  첫째, 경기도의 경쟁력 강화와 삶의 질 향상을 위한 정책개발 싱크탱크 역할을 수행하고 둘째, 경기도의 여건, 전망과 정책적 현안 등을 검토ㆍ분석하여 연구과제를 추출ㆍ선정하고 우선순위에 따라 연구를 진행했으며, 셋째, 연구성과의 품질과 활용성을 제고하고 쟁점과제에 신속 대응하는 탄력적 사업운영에 역점을 두고 추진해 오고 있습니다.  이러한 기본방침을 토대로 경기도와 일부 시ㆍ군의 비전을 수립한 바 있고 수도권정책센터를 설립하여 도정현안에 보다 신속히 대응하는 시스템을 구축하였습니다.  특히 대표적인 시책개발 사례로는 미군기지 공여구역 주변지역 지원특별법의 시행령 제정에 저희 연구원이 크게 기여하였으며 이러한 시책을 토대로 경기 북부지역 개발의 전기가 마련될 것으로 기대됩니다.  또한 국가 및 도정이슈에 대한 기획세미나를 수시 개최하여 국가 및 경기도의 정책현안과제에 대한 전문가의 의견수렴과 경기도의 정책방향 모색 및 여론선도를 위해 노력해 왔습니다.  그간 연구원에서 공들여 연구한 결과들이 외부에 잘 홍보되지 않은 경향이 있었는데 금년 들어서는 언론브리핑, 메일링서비스 등을 통해 연구결과를 수시로 홍보하여 외부로부터 좋은 반응을 얻고 있기도 합니다.
</p>
<p style="padding-left:1.2em">  다음 6페이지에서 8페이지에 걸쳐서 주요 연구사업 실적을 보고드리겠습니다.  보시는 바와 같이 연구원은 다양한 분야에 걸쳐서 연구성과를 가져왔습니다.  경기비전 2020 중기계획을 6월 말에 수립ㆍ배포하였으며, 한국규제학회, 한국비교경제학회와 공동으로 수도권규제개혁을 주제로 기획세미나를 개최하여 중앙 및 지방 언론보도를 통해 규제개혁 여론선도 및 국가 경쟁력 강화를 위한 경기도의 역할과 중요성에 대한 공감대 형성에 기여한 바 있습니다.  또한 분야별 경기도 중기정책기조 수립, 경기도 대중교통정책 연구에 종합적인 대응, 경기 북부지역 발전계획 연구, 경기도 시ㆍ군의 행정기구 조직진단과 종합발전계획 수립 수행, 한ㆍ미 FTA 추진과 경기도의 대응방안 연구, 타 시ㆍ도 연구원과 교류협력 및 공동연구 활성화 등을 또 다른 성과로 꼽을 수 있겠습니다.  한편 금년 들어 최초로 실시한 도 출연기관 경영평가에서 저희 연구원이 좋은 점수를 얻었습니다.  연구원은 이에 자만하지 않고 앞으로도 미흡한 부분을 지속적으로 개선해 감은 물론 효율적인 연구사업과 연구 경영에 최선을 다해 가도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 9페이지의 2006년도 연구사업을 총괄 요약해서 보고드리도록 하겠습니다.  9페이지를 참고해 주시기 바랍니다.  연구사업은 현재 151건을 완료하였고 97건을 추진 중에 있어 당초 계획 대비 102% 추진 중에 있습니다.  수행 중인 과제들을 계획대로 차질없이 완료할 수 있도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  다음에 10페이지부터 22페이지에 걸쳐서 세부추진상황을 보고올리겠습니다.  먼저 10페이지의 기본연구과제입니다.  기본연구과제는 24개 과제를 수행하고 있으며 당초 계획했던 경기도 평생학습도시 기반조성에 관한 연구는 연구를 책임지던 연구원이 대학교수로 이직함에 따라 위탁연구과제로 전환하여 수행 중에 있습니다.
</p>
<p style="padding-left:1.2em">  11페이지부터 13페이지까지의 수탁연구과제 추진상황을 말씀드리겠습니다.  전년도에서 이월된 43개 과제와 금년도에 신규로 계약된 15개 과제를 포함하여 총 58건을 진행 중에 있고 이 중에서 주한미군 공여구역 주변지역 등 지원특별법 시행에 따른 제도개선 연구용역 등 35건을 완료했습니다.  그리고 관련 법ㆍ제도 미비 등 용역의뢰기관의 사정에 의해서 잠정중지로 인해서 2020년 수도권 광역도시계획수립 연구용역 등 6건이 연구중지된 상태에 있습니다.  군포비전 2020 연구용역 등 17건을 현재 수행 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음 14페이지부터 17페이지까지의 정책연구과제에 대해서 보고올리겠습니다.  정책연구과제는 69건 중 경기도 주택종합계획수립 연구 등 34건을 완료했습니다.  경기도 자치행정사무 실태분석 등 35건을 현재 수행 중에 있습니다.  상세한 내용은 자료를 참고해 주시기 부탁드리겠습니다.  
</p>
<p style="padding-left:1.2em">  다음에 18페이지로 넘어가겠습니다.  위탁연구과제에 대해서 보고올리겠습니다.  위탁연구과제는 총 13건 중 사회정책적 관점에서의 경기도 소득양극화 진단과 완화방안 연구 등 7건은 완료했고 나머지 6건은 수행 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음 19페이지의 협약연구과제에 대해서 보고올리겠습니다.  협약연구과제는 총 4건 중 경기도 지역혁신협의회 운영사업 1건은 완료했고 나머지 3건은 수행 중에 있습니다.  지역연구과제는 여주군을 대상으로 현재 연구 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음 간행물발간사업은 경기논단, 경기도 경제동향과 전망, 연구원 안내책자는 정상적으로 발간하고 있으며, GRI 웹뉴스는 기존 오프라인 연구원소식지인 뉴스레터를 온라인 메일링서비스 시스템으로 변경한 것으로 전국 2만여명의 오피니언 리더들에게 수시로 발송을 하고 있습니다.  연구결과 홍보를 위해서 적극 노력하고 있습니다.  
</p>
<p style="padding-left:1.2em">  다음 페이지 말씀올리겠습니다.  20페이지를 봐주시기 바랍니다.  번역사업은 현재 3종이 수행 중에 있습니다.  
</p>
<p style="padding-left:1.2em">  다음으로 20페이지부터 21페이지까지의 정책세미나 및 기타활동에 대해서 보고올리겠습니다.  현재까지 정책세미나는 10회를 개최하였고 남북포럼, 동북아포럼 등 경기도정 관련 주요이슈에 대해 각계 전문가를 모시고 대안을 모색하는 정책포럼은 지금까지 16회 개최한 바 있습니다.  그리고 외국인투자유치포럼, 철도포럼을 금년에 신설하여 운영하고 있습니다.  자세한 내역은 유인물을 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음 22페이지를 참고해 주시기 바랍니다.  도정현안 홍보사업과 관련해서는 도정주요정책홍보 8건, 수도권규제관련 여론조사 등 주요정책여론조사 9건을 각각 추진한 바 있습니다.
</p>
<p style="padding-left:1.2em">  다음 23페이지의 연구사업 연도별 수행현황은 유인물을 참고해 주시기 바랍니다.  
</p>
<p style="padding-left:1.2em">  이어서 24페이지부터 48페이지까지의 2007년도 연구사업계획안을 보고드리겠습니다.  내년도 연구사업계획의 사업목표는 경기도와 국가의 경쟁력을 강화하기 위한 수도권규제개선 등 국가적 이슈에 대한 종합적이고 중장기적인 정책방안 제시, 경기도 31개 시ㆍ군의 정책효율성 제고 및 삶의 질, 복지 향상을 위한 정책방안을 연구하고 그리고 수도권 경쟁력 강화, 수도권 광역교통정책, 팔당종합대책, 뉴타운사업 등 4대 주요 도정현안에 대한 정책개발 및 지원을 주목표로 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 페이지를 봐주시기 바랍니다.  25～27페이지에서 보시는 바와 같이 이러한 기본목표를 토대로 내년도 연구사업계획을 보고올리고 있습니다.  연구과제사업은 총 164건, 연구부대사업 9종, 연구지원사업 5종, 연구기반사업 5종을 향후 추진할 계획이며 사업예산 등 구체적인 것은 유인물을 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음으로 27페이지부터 48페이지에는 단위사업별 개요 및 계획을 보고드렸습니다.  간략하게 요약해서 말씀올리면 먼저 중점연구과제는 종합연구기관으로서의 위상강화와 전국적으로 문제를 제기할 수 있는 국가적 정책과제를 적극 발굴하여 수행하는 연구사업으로써 우선 수도권 경쟁력 강화, 지방분권, 지방자치제도의 문제점 분석, 환경정책 패러다임 전환 등을 소재로 추진할 예정이며, 중앙 및 경기도의 향후 정책동향을 봐가면서 추가 소재를 발굴하여 추진할 계획입니다.  중점연구과제는 그동안 저희 연구원이 상대적으로 경기도 문제에 대해서는 많은 시간을 썼지만 중앙의 정책문제에 대해서는 별로 시간을 쓸 여유가 없었다고 판단돼서 제 생각으로는 중앙의 정책이 바뀌지 않고는 경기도가 노력을 한다고 큰일을 이루어내기가 참 어렵다는 그런 생각을 많이 했습니다.  그래서 국가 아젠다 문제가 있는 부분에 대해서 저희 연구원이 적극적으로 나서서 문제제기를 하는 그런 역할을 해야 되겠다는 판단 하에 이런 국가적 정책과제연구를 중점과제로 추진하기로 했습니다.
</p>
<p style="padding-left:1.2em">  다음에 28페이지입니다.  28페이지에는 기본연구과제를 보고올렸는데요, 간략하게 말씀올리면 기본연구과제는 총 26개 과제를 계획했습니다.  과제현황은 유인물을 참고해 주시고요.  모든 기본연구과제 계획은 제안서 발표과정을 통해서 점검했고 앞으로도 계속 점검해 나갈 계획입니다.  
</p>
<p style="padding-left:1.2em">  다음에 29페이지를 보시면 연구과제사업으로 정책연구과제 71건, 위탁연구과제 15건, 지역연구과제 2건, 수탁연구과제 50건을 계획하고 있습니다.
</p>
<p style="padding-left:1.2em">  30페이지부터 32페이지에 걸쳐서 연구부대사업 등을 보고올렸습니다.  우선 연구부대사업은 세미나를 30회 개최할 계획이고 정책포럼을 30회 운영하고 해외연구교류, 논문발표공모, 월간 경제동향과 전망, 계간 연구원 학술지 경기논단의 발간, 정책동향분석, 연구홍보, 선진화위원회 관리운영 등을 계획하고 있습니다.  분야별 사업량과 사업비에 대한 구체적인 사항은 유인물을 참고해 주시기 바라며, 이 계획은 위원님들께서 추후에 저희 예산을 확정해 주는 것에 따라서 저희가 추진하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 33페이지부터 34페이지에 걸쳐서 보고올리겠습니다.  연구지원사업으로 정보자료지원, GIS사업, 전산사업, 실험실 운영, 시ㆍ군담당제를 계획하고 있으며 구체적인 내용은 유인물을 참고해 주시기 바랍니다.  시ㆍ군담당제는 과거에도 일부 운영을 한 것으로 알고 있습니다만 내년에는 좀더 적극적으로 시ㆍ군의 정책수요를 감안해서 저희 연구원이 시ㆍ군을 도울 수 있는 방안을 모색하도록 노력하겠습니다.
</p>
<p style="padding-left:1.2em">  34～35페이지에 걸쳐서 말씀드리겠습니다.  연구기반사업으로 연구지원인력 활용을 위한 아웃소싱, 연구평가심의회, GRI웹뉴스, GRI브로셔 제작, 연구교육개발 등의 사업을 추진할 예정입니다.  사업별 개요는 유인물을 참고해 주시면 감사하겠습니다.
</p>
<p style="padding-left:1.2em">  36페이지 말씀올리겠습니다.  36페이지에서 48페이지에 걸쳐서 내년도 기본연구과제별 연구개요와 자체발굴 정책연구과제 현황을 참고로 첨부했습니다.  구체적인 것은 유인물을 참고해 주시면 고맙겠습니다.
</p>
<p style="padding-left:1.2em">  49페이지 말씀올리겠습니다.  2005년도 행정사무감사 처리요구사항 조치결과를 보고올리도록 하겠습니다.  2005년 11월 17일 행정사무감사 시 처리요구사항은 4건이었고 이를 개선하기 위해 최선을 다해 왔습니다.  먼저 연구과제사업이 정책과제에 편중되지 않도록 하기 바란다는 요구사항이 있었습니다.  이에 대해 저희 연구원은 연구사업이 정책과제에 지나치게 편중되지 않도록 기본연구과제사업을 보다 내실화하고 연구 부대ㆍ지원ㆍ기반사업을 다양하게 추진해오고 있으며 정책과제는 도정현안 지원과 직접 관련된 사업 위주로 수행할 수 있도록 수행시스템을 개선하고, 연구위원회에서 연구내용을 엄격히 심의하여 추진하고 있습니다.  그 외 구체적인 조치결과는 배부해 드린 유인물을 참고해 주시면 고맙겠습니다.
</p>
<p style="padding-left:1.2em">  한 가지 더 부연할 것은, 50페이지입니다.  작년도에 경기도내 균형적 발전을 위해 양평, 가평, 이천 등 경기 동부지역을 대상으로 하는 종합발전계획을 추진해 주기를 바란다는 지적이 있었는데요.  저희가 그동안 동부지역의 발전을 위한 연구를 과거에도 많이 했을 뿐만 아니라 금년에 들어서는 아까 보고올린 대로 여주군에 대한 개발방향에 대해서 저희가 연구를 진행하고 있습니다.  미흡한 점은 차후에 계속 노력해서 지방의 발전을 위한 정책제안을 할 수 있도록 노력하겠습니다. 
</p>
<p style="padding-left:1.2em">  너무 간략하기도 합니다만 이상으로 2006년도 주요업무보고를 마치도록 하겠습니다.  경청해 주셔서 감사합니다.
</p>
<p>업무보고서(경기개발연구원)
</p>
<p><b>○ 위원장 김영복 </b> 원장님, 수고하셨습니다.  다음은 감사 질의답변 순서가 되겠습니다.  감사의 효율적인 진행을 위하여 질의는 일문일답으로 하되 질의시간을 제한하도록 하겠습니다.  우선 위원님 한 분당 10분씩 시간을 드리고 추가질의를 1회에 한하여 5분을 드리도록 하겠습니다.  원활한 감사진행을 위해 부득이하게 시간제한을 두게 된 점 널리 양해를 해 주시면 고맙겠습니다. 
</p>
<p><b>○ 김기수 위원 </b> 위원장님!
</p>
<p><b>○ 위원장 김영복 </b> 네.
</p>
<p><b>○ 김기수 위원 </b> 의사진행발언 하나 하겠습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 네.
</p>
<p><b>○ 김기수 위원 </b> 지금 감사자료 보면 나중에 목록을 줬지만 우리 경기개발연구원 감사 한두 번 합니까?  네?  여기 목록에 위원들 하나도 없습니다, 목차에.  나중에 주기는 줬지만 한두 번 감사하는 것 아니잖아요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 상세한 목차가 없었다는 말씀인가요?
</p>
<p><b>○ 김기수 위원 </b> 나중에 준 것 있지 않습니까?  그러면 여기에 요구자료 누가 했는지.  이거 목차만 주고.  이거 경기개발연구원에서 물론 연구도 많이 하지만 이건 상식적인 겁니다.  이거 갖고 장난하는 겁니까?  감사장에 감사받을 때 장난합니까?  실수를 해도 실수할 게 따로 있지 이런 걸 가지고 실수합니까? 
</p>
<p><b>○ 위원장 김영복 </b> 김기수 위원님, 잠깐만요.  진행 좀 하고요.
</p>
<p><b>○ 김기수 위원 </b> 앞으로 시정할 거예요, 안 할 거예요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지적하신 부분의 문제에 대해서는 저희가 너무 소홀했던 게 아닌가 하는 생각이 듭니다.
</p>
<p><b>○ 김기수 위원 </b> 시정하시기 바랍니다.  이상입니다.
</p>
