<p><b>○ 임우영 위원 </b> 원장님은 더 잘 아실 겁니다.  기업마케팅이 얼마나 중요합니까?  그런데 이제는 제가 어느 부서에 가서 얘기하든 늘 똑같은 얘기를 합니다.  무슨 얘기냐면 행정에도 PR을 고려해야 된다.  이 행정 PR이라는 것은 그냥 우리가 이런 정책을 개발해서 추진만 하면 되는 게 아니고 그것을 일반 사기업에서와 같이 진짜 제대로 된, 아까 말씀하신 대로 제대로 된 포장을 갖고 도민이나 국민들한테 홍보를 해야 됩니다.  그러려면 마케팅 홍보에 대해서 전문적인 지식을 가진 분들이 이제는 행정 쪽에서도 일을 해 주셔야 된다, 저는 그렇게 늘 주장하고 있습니다.  그래서 아까 말씀하신 판매나 경기개발연구원의 이미지 제고, 모든 차원에서 대도민 홍보라든가 대국민, 더 나아가서 국제적으로 우리가 위상을 정립하고 높이려면 그런 쪽에도 관심을 가져주십사 하는 말씀을 드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다.
</p>
<p><b>○ 임우영 위원 </b> 그리고 또 하나는 우리가 하도 도정이나 각 시ㆍ군에서 위탁하는 과제들을 수행하다 보니까 국제적인 학술이나 이런 쪽에 특히 실적이 저조한 것으로 지난번 경영평가에서도 나왔거든요.  그런 부분에 대해서 한번 말씀해 주시죠.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 말씀하신 대로 저희가 하는 연구내용이 국제적인 저널에 실릴 수 있는 내용들을 연구하는 것이 아니기 때문에 다소 저조합니다.  그런데 얼마 전에 언론보도는 사실 저희 실적을 과소평가해서 실은 거고요.  제가 보기에는 연간 한 20～30개 이상의 국내외 저널에 출판을 하고 있기 때문에 그런 것은 최선을 다하고 있는 것이 아닌가 생각이 듭니다만 그럼에도 불구하고 연구원의 경쟁력을 높이고 국제화를 위해서는 외국 일류저널에도 페이퍼를 보내고 국내 저널은 물론입니다만 그렇게 할 수 있도록 노력하겠습니다.  그냥 노력만 해서 되는 것은 아니고 연구원 내부에 인센티브를 그렇게 바꿔야 될 것 같아요.  그래서 제가 연구원 평가기준을 쭉 살펴봤더니 외부에 논문을 실은 것이 별로 대접을 받지 못하고 있어요.  그래서 내년에 제가 제일 첫 번째로 하고자 하는 것이 외부 좋은 저널에 좋은 글을 싣는 것을 좋은 점수를 많이 받도록 해서 연구원들 평가할 때 항상 염두에 두고 열심히 퍼블리시할 수 있도록 하는 제도적인 장치를 만들도록 제가 구상하고 있습니다. 
</p>
<p><b>○ 임우영 위원 </b> 그래서 제가 경기도 출연기관 2005년도 경영실적평가보고서라는 책자를 받아서 쭉 검토해 봤습니다.  물론 잘된 점도 있는데 아까 말씀하신 대로 미흡한 점 해 가지고 나온 것을 제가 잠시 읽어드리겠습니다.  “사업지표에서는 국제 산ㆍ학ㆍ연 협동연구의 활성화 부분에서 국제 산ㆍ학ㆍ연 협동연구 1건, 국제학술포럼 1건 등 총 2건으로 매우 부족했다.” 이렇게 표현이 되어 있어요.  아까 과소평가를 하셨다고 말씀하셨는데 이런 평가를 할 때 우리 연구원의 잘못이 아닌가.  왜냐면 제대로 된 자료들을 제출했으면 평가를 하는데 이러한 평가는 받지 않지 않았나 생각을 하면서 시간이 짧으니까 나중에 다 끝난 다음에 추가적으로 전체적인 질의를 다시 한 번 하겠습니다.  감사합니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 출판 많이 못한 것은 저희한테 책임이 있죠.  열심히 개선하도록 하겠습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 임우영 위원님 수고하셨습니다.  임우영 위원님이 경기개발연구원의 명칭이라든가 연구과제, 판매 등 여러 가지 질의를 하셨는데 거기에 대해서 보충질의하실 위원 계십니까?  장윤영 위원님 보충질의하시기 바랍니다. 
