</p>
<p><b>○ 장윤영 위원 </b> 지금 우리 경기개발연구원에는 특별회원과 일반회원으로 나뉘어져있습니까?  연회비를 내는 회원들 있지 않습니까?  특별회원은 몇 명이나 되고 일반회원은 얼마나 됩니까? 
