<p><b>○ 장윤영 위원 </b> 이것 자체가 기술적으로 보면 소위 말해서 일반행정 같으면 세외수입 있지 않습니까?  기타 잡수입이 될 수 있겠습니다만.  경기개발연구원이 발족된 지 10년이 넘었습니다.  회원이 30명이 안 된다고 하는 것 자체에 대해서 경기개발연구원의 문제입니다.  그리고 참고적으로 하나 묻겠습니다.  진짜 맞습니까?  특별회원이면 연구보고서, GRI에서 발행되는 연구서 다 줍니까? 
</p>
<p><b>○ 지식정보팀장 이인애 </b> 다는 아니고 명시를 했습니다만 수탁연구과제 같은 경우는 저희가 발주처에 전부 제출하기 때문에, 저작권이 없기 때문에 줄 수가 없습니다.  그래서 저희가 배부대상을 따로 회원에 명시하고 있습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 분명히 홈페이지에 특별회원 15만원, 연구보고서 괄호 열고 과제전부입니다.  신뢰성 문제입니다.  그래서 이쪽에서는 연구과제가 기본이 있고 수탁이 있고 위탁이 있고 협약이 있고요.  무척 많이 있지 않습니까?  거기에서는 구분해 주셨어야 되고, 회원수에 관심을 안 가지셨기 때문에.  그러면 적어도 회비는 어떻게 쓰여 집니까?
</p>
<p><b>○ 지식정보팀장 이인애 </b> 회비는 저희가 도서판매수입으로 매달 결재를 올려서 저희 수입으로 잡고 있습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 그러니까 아까 특별회원이 20 몇 명이라고 그러셨죠?
</p>
