<p><b>○ 장윤영 위원 </b> 그쪽에서는 도서마다 연구목록이 있지 않습니까?  연구목록을 얼마나 조회했는지가 홈페이지에 나타납니다.  그리고 이 연구물에 대한 판매여부가 나타나고요.  연구물에 대한 판매가격이 나와 있습니다.  아십니까? 
</p>
<p><b>○ 지식정보팀장 이인애 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 이것은 수익에도 문제가 있지만 일반시민사회에서 이 연구물에 대한 호응도 있지 않습니까?  충분하게 느낄 수 있습니다.  우리 GRI에서는 홈페이지나 기타 여러분들이 만들어 낸 과제에 대해서 호응도를 객관적으로 판단할 수 있는 근거자료가 있습니까? 
</p>
<p><b>○ 지식정보팀장 이인애 </b> 일단 홈페이지 접속건수가 기준이 될 것 같은데요.  그 부분은 저희가 홈페이지 구축 당시에, 일단 저희가 구축한 지 얼마 안 되었고 그 부분에 대해서는 앞으로 검토해 보자는 의견이 있어서 일단 지금은 오픈하지 않은 것으로 알고 있습니다.  그것은 사실 저희 전산시설팀장이 관할하고 있는 문제여서 제가 정확하게 답변드리기는 어렵습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 전산 관련된 분 있으십니까?  지금 분명하게 서울시정개발연구원에 보면 과제마다 조회 수가 1,432회, 판매 여부, 판매 불가, 판매 가능, 9,000원, 1만원 되어 있습니다.  그런데 현재 홈페이지 아까 원장님께서 페이지뷰 수에 대해서 파악하지 못한다고 말씀하셨는데, 맞습니까?  그럴 리가 없을 텐데.  로그 파일 자료가 있을 거거든요.  그런데 지금 GRI 홈페이지에서 나타나고 있는 연구물 있지 않습니까?  여기에서 나온 각 과제에 따른 조회 수 내지는 다운로드 받은 것에 대해서는 로그 파일 자료가 있겠죠? 
</p>
<p><b>○ 지식정보팀장 이인애 </b> 제가 그 부분에 대해서는 정확하게 알고 있지 못합니다. 
</p>
<p><b>○ 장윤영 위원 </b> 보충질의기 때문에 뭐 하지만 분명히 80부를 만든다고 하는 것 자체는 판매의지가 없다고 판단합니다.  여러분들의 과제물이 예를 들어서 31개 시ㆍ군이 있습니다.  31개 시ㆍ군의 시의원, 군의원님들한테만 나간다 하더라도 엄청난 판매부수가 될 겁니다.  관련 시민단체나.
</p>
<p><b>○ 지식정보팀장 이인애 </b> 그 부분에 대해서 제가 보충의견을 드려도 되겠습니까?  일단 저희 연구원은 비영리 연구원이기 때문에 저희가 영리를 목적으로 판매하는 것을 사실 생각을 별로 하지 못했습니다.  왜냐하면 초창기에 저희가 홍보를 목적으로 대량으로 많은 곳에 기증 형식으로 배부를 하다가 저희 유관기관이나 관련된 사람들에게만 배부하고 있는데요.  그리고 일단 저희가 관련된 사람은 거의 기증형식으로 책을 드리고 있고요.  경기도민이나 일반인들이 저희 연구보고서를 보고 싶다고 할 때에는 저희가 홍보차원에서 많은 국책연구기관을 비롯해서 하고 있습니다만 원문파일을 제공하고 있습니다.  보통 사람들은 그것을 보고자 할 경우에는 저희 홈페이지나 전자도서관을 통해서 얼마든지 사실 원문을 볼 수가 있습니다.  그래서 사실 저희는 그것을 얼마간의 책을 더 판매해서 영리를 추구하는 것보다는 많은 경기도민이나 일반인들에게 저희 연구과제를 공유하는 것을 더 중요하다고 생각했기 때문에 판매보다는 연구결과를 공개하고 있었기 때문에…….
</p>
<p><b>○ 장윤영 위원 </b> 답변중지를 요청합니다.  그러면 조금 전에 말씀드렸지만 서울시정개발연구원은 비영리단체입니까, 영리단체입니까? 
</p>
<p><b>○ 지식정보팀장 이인애 </b> 비영리단체입니다.
