<p><b>○ 경기개발연구원장 좌승희 </b> 원장이 대신 답변드려도 괜찮겠습니까?  아까 말씀하신 SERI의 경우는 저희하고 비교하기 어렵겠죠.  아까도 얘기했습니다만 저희 연구원이 비매형태로 많은 연구결과를 배포하기 때문에 우선 판매에 목적을 두지 않았다는 것은 저는 옳았다고 봅니다.  그런데 시정개발연구원이 하는 그런 형식의 접속이라든가 연구내용을 알리고 평가하는 시스템은 저희가 앞으로 벤치마킹해야 되지 않을까 생각이 들어서 저희가 그동안 해온 것을 방어하려고 할 게 아니라 오히려 적극적으로 시정개발연구원에서 하는 것을 좀더 벤치마킹을 해서 장 위원님께서 말씀하신 방향으로 더 홍보하도록 노력하겠습니다.  그러나 제약이 있다고 하면 그것은 우리 연구의 내용이 수탁자, 정책을 원하는 사람, 소비자 중심으로 되어 있기 때문에 팔릴 성질이 별로 없고요.  특히 기본과제가 팔릴 수 있는 연구지만 1년에 30부도 안 나온 상황이고 그래서 그것만이라도 보다 더 저희가 열심히 마케팅 해서 알리고 회원 모집을 해서 저희 연구원의 연구결과를 좀더 많이 평가받도록 노력하겠습니다.  그런데 지적하신 대로 저희가 그동안 미흡했던 것이 아닌가 생각이 됩니다. 
