<p><b>○ 장윤영 위원 </b> 이 질의에 대해서 마무리하겠습니다.  권고사항으로.  분명한 것 자체는 연구물에 대해서는 연구하신 분들은 자긍심이 있어야 됩니다.  연구물이 31개 시ㆍ군과 경기도의 정책으로 자리 잡아야 됩니다.  그렇게 하기 위해서는 그 연구물을 많은 사람들이 봐야 되는데 비매로 공짜로 얻었을 경우에는 경기개발연구원 재정이 압박을 받습니다.  좋은 연구물이었을 경우에는 요구를 할 겁니다.  가치가 있어야 합니다.  그리고 판매를 하십시오.
</p>
<p style="padding-left:1.2em">  그 다음에 경기개발연구원에서 이런 좋은 연구물이 나오고 있다는 것을 알려주셔야 됩니다.  조금 전에 말씀드렸지만 31개 시ㆍ군의 기초의원들한테 만이라도 이 목록을 알려주면 엄청난 자료요구가 들어올 것입니다.  그리고 조금 전에 비매에 대해서 부정하지는 않습니다만 그렇다고 한다면 이것이 아까 말씀하셨던 특별회원을 일반회원으로 유도하실 수가 충분히 있습니다.  이쪽으로 해서 특히 정치나 시민사회단체를 특별회원으로 가입하게 해서 기초의원님들만 본다 하더라도 충분하게 1,000명 이상 확보할 수 있습니다.  이렇다고 한다면 여기에서만 충분하게 재정자립을 위해서, 연구원 여러분들의 자긍심을 위해서, 보다 나은 연구과제 선택을 위해서 서울시정개발연구원의 홈페이지를 심도 있게 검토하셔서 빠른 조치가 이루어지기를 소망합니다.  이상 보충질의를 마치겠습니다.
</p>
