<p><b>○ 전동석 위원 </b> 저도 장윤영 위원님이나 임우영 위원님 말씀하신 것에 상당히 공감하는 것이 실제로 연구에 대한 실적보다는 홍보문제가 상당히 떨어지지 않는가 하는 생각을 많이 했습니다.  그 분야에서 생각한다면 언론브리핑 실시도 중요하고 또한 이슈와 동향 이런 주기적인 메일링서비스, 메일링서비스는 제가 집에서 많이 보고 있기 때문에 진전된 사항이 있었다고 생각되는데요.  좋은 반응을 보이고 있다고 아까 말씀하셔서, 그러면 그게 객관적인 어떤 데이터가 필요하지 않느냐는 생각에 상당히 공감을 했습니다.  그래서 앞으로도 홍보활성화를 통한 반응에서 객관적으로 정말 피드백을 할 수 있는 그런 것을 해서 그냥 좋은 연구로 끝나는 것이 아니라 정말로 그것이 적용되고 있는가를 확인해 주셨으면 하는 생각입니다.
