<p><b>○ 김기수 위원 </b> 그래서 거기에 대한 중장기적인 인력수급방안을 잠깐만 간단하게 말씀 좀 해 주세요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우선 저는 연구원은 이직이 좀 있어야 된다고 봅니다.  너무 오래 연구원에, 평생 연구원에 있는 것은 바람직한 것은 아니라고 보고요.  한 4, 5년쯤 연구원에서 했으면 다른 데 가는 사람도 있고 그러면 새로운 사람도 오고 하는 이런 플로어가 있어야 된다고 보는데 그런 면에서 보면 우리 연구원은 사실 이직률이 그리 높은 데가 아니라고 생각합니다.  그러나 아주 우리가 꼭 필요한 사람, 이런 사람들이 나가는 것에 대해서는 저희가 안에서 다른 인센티브를 통해서 그런 사람들을 확보할 수 있도록 하는 노력을 해나가야 되지 않을까 하는 생각이 듭니다. 
</p>
<p><b>○ 김기수 위원 </b> 그런데 경기개발연구원에 대한 정보유출이나, 이적을 해가지고 정보 유출될 염려는 없습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저는 저희가 그렇게 심각한 정보를 다룬다고 생각이 안 들고요.  오히려 이직해서 다른 학교로 가든 어디 가든 그게 경기개발연구원의 사상과 이념, 더 나아가면 그 명예를 다 가지고 나가기 때문에 오히려 더 많이 연구원 출신이 학계에 가서 퍼져있는 것이 연구원의 지원세력도 되고 그렇기 때문에 순환이 많이 되는 게 사실은 연구원에 도움이 된다고 생각합니다.
</p>
<p><b>○ 김기수 위원 </b> 물론 연구원은 그렇다 치고 관리직은 법률에 보면 장애인을 2% 채용하게 돼 있습니다.  그리고 국가유공자는 10%를 채용하게 돼 있습니다.  현황 좀 잠깐 말씀해 주시지요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리가 충분히 그 책임을 다하고 있지 못하고 있다고 생각됩니다만, 행정과장이 대신 답변을 올리도록 양해해 주시기 바랍니다. 
</p>
<p><b>○ 행정지원과장 김영수 </b> 행정지원과장 김영수입니다.  저희는 장애인은 기존 채용프로를 채용하고 있지 않고요.  다만 국가보훈자는 1명을 채용하고 있습니다. 
</p>
<p><b>○ 김기수 위원 </b> 1명을 채용하고 있어요?
</p>
<p><b>○ 행정지원과장 김영수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김기수 위원 </b> 퍼센티지는 어떻게 됩니까?  
</p>
<p><b>○ 행정지원과장 김영수 </b> 저희가 기준이 5%인데요.
</p>
<p><b>○ 김기수 위원 </b> 법적인 게 5%입니까?  10%가 아니고?
</p>
<p><b>○ 행정지원과장 김영수 </b> 네, 5%입니다.
</p>
<p><b>○ 김기수 위원 </b> 그래요?  5%면 몇 명 채용하게 됩니까?
</p>
<p><b>○ 행정지원과장 김영수 </b> 전체적으로 저희가 최소한 3.5명 이상을 해야 되는데요.  국가보훈처에서도 저희하고 협의를 하고 있지만 저희는 연구직이 있으면 줘라 그런 말입니다.  그런데 그런 사람은 추천을 못하고 일반관리직 쪽으로만 추천해서 1명만 채용하고 있습니다. 
</p>
<p><b>○ 김기수 위원 </b> 연구직은 대개 석사, 박사 이상 아닙니까? 
</p>
<p><b>○ 행정지원과장 김영수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김기수 위원 </b> 그런 사람은 채용을 안 해도 자기가 다 알아서 합니다.  알아서 하니까 장애인하고 연구원 채용 이것 좀 꼭 지켜주시기…….
</p>
<p><b>○ 행정지원과장 김영수 </b> 그것은 신규채용 때마다 거기다 집어넣고 있습니다.  가점제도 운영하고요.
</p>
<p><b>○ 김기수 위원 </b> 지켜 주시기 바라고요.
</p>
<p><b>○ 행정지원과장 김영수 </b> 네, 알겠습니다. 
</p>
<p><b>○ 김기수 위원 </b> 그리고 원장님께서 말씀하셨지만 직원 후생복지제도는 그렇게 썩, 하위점수는 안 줘도 되는 겁니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 말씀을, 누구한테 하위점수…….
</p>
<p><b>○ 김기수 위원 </b> 하위점수는 중간은 된다 이거지요?  서울시정은 조금…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다.  죄송한 말씀입니다만 제가 민간연구소에 있다가 왔는데 항목은 오히려 민간연구소보다 더 많은 항목을 복지제도로 갖추고 있는데 내용상으로 약간 부실한 면도 있고 해서 전반적으로 보면 시정개발연구원보다는 다소 미흡하지만 다른 지방발전연구원보다는 낫다 하는 게 제 판단입니다.
</p>
<p><b>○ 김기수 위원 </b> 앞으로 인력수급방안에 대해서 더 중장기적인 대책을 세우시고요.  다른 위원님들 계시니까 다른 위원님들 끝나고 다시 추가 질의를 드리겠습니다.  이상입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 감사합니다. 
</p>
<p><b>○ 위원장 김영복 </b> 김기수 위원님 수고하셨습니다.  김기수 위원님이 임직원에 대한 후생복지제도 운영에 대해서 말씀하셨는데 거기에 대한 보충질의하실 위원 계십니까?  임우영 위원님 보충질의하시기 바랍니다. 
</p>
<p><b>○ 임우영 위원 </b> 인사도 같이 하셨지요?
</p>
<p><b>○ 위원장 김영복 </b> 네, 인사도 같이 하셨습니다. 
</p>
<p><b>○ 임우영 위원 </b> 원장님, 연구원들 채용하실 때 공개로 채용하는 게 원칙인데 혹시 특별채용을 하신 현황 같은 것은 없습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 와서 보니까 과거에 한두 건 그런 경우가 있었던 것 같고요.  그리고 작년에도 감사에서 그런 문제에 대해서 지적이 있었던 것으로 알고 있습니다.  기본적으로는 저희가 공개채용을 원칙으로 하고 있지요.  
</p>
<p><b>○ 임우영 위원 </b> 과거에 특별채용을 했던 그 분은 탁월한 어떤 다른 면이 있어서 특별채용을 하셨었나요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그 당시에 그런 판단이 있었기 때문에 원장께서 하시지 않았느냐 저는 그렇게 판단하고 있고요.  우선 연구원의 인사권은 원장한테 있지 않습니다.  채용의 인사권은 이사장님한테 있기 때문에 사실 이 질의는 제가 답변하기가 적절치 않다고 생각하는데요.  어쨌든 제가 느끼기에는 훌륭한 분이기 때문에 특별채용을 하지 않았느냐 하는 게 제가 드릴 수 있는 답변입니다.  
</p>
<p><b>○ 임우영 위원 </b> 제가 보충질의를 하는 이유는 잘 아시겠지만 이사장님이 바뀜으로 해서 여러 가지 문제점이 있었다는 것은 알고 계실 겁니다.  그런데 특히 연구직에 한해서는 그분이 가지고 있는 경력이라든가 모든 것이 다른 분에 비해서 굉장히 탁월하다면 특별채용하는 것 저는 그게 굳이 나쁘다고 판단하지는 않습니다.  오히려 그런 분은 우리 경기개발연구원에서 특별히 모셔와야 되지 않나 그런 개인적인 생각도 가지고 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저도 같은 생각입니다.
</p>
<p><b>○ 임우영 위원 </b> 하지만 내가 왜 이런 문제제기를 하냐면 형식은 공개채용의 형식을 다 취하는데 사전에 벌써 다 내정돼 있는 것 아니냐는 의구심을 이쪽에 응시했던 분들이 가지고 있다는 데 문제가 있다, 저는 그것을 지적하고 싶어서 말씀드리는 겁니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 
</p>
<p><b>○ 임우영 위원 </b> 그런 의심을 받지 않도록 이사장님한테도 원장님께서 말씀을 해 주시고 그런 것을 환기시키는 그런 것도 필요하다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 
</p>
<p><b>○ 임우영 위원 </b> 그래서 문제제기를 합니다.  이상입니다.
</p>
<p><b>○ 위원장 김영복 </b> 임우영 위원님 수고하셨습니다.  보충질의하실 위원 계십니까?  정인영 위원님 보충질의하시기 바랍니다. 
</p>
<p><b>○ 정인영 위원 </b> 정인영 위원입니다.  존경하는 김기수 위원께서 후생복지문제하고 인사문제를 말씀하셨는데 연구직 인원이 현재도 9명이 과부족이지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다.  
</p>
<p><b>○ 정인영 위원 </b> 금년에도 자료를 보면 채용을 많이 한 것으로 돼 있어요.  연구직 8명, 관리직 2명 해서 10명을 채용했지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 정인영 위원 </b> 10명을 채용했는데 물론 공채를 통해서 했겠지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 정인영 위원 </b> 전공분야를 보면 지방세제, 복지행정일반, 거시경제, 교통계획, 환경정책, 자연생태, 도로관리 및 교통계획 이 부분에 아주 훌륭하신 분들을 채용하신 것 같습니다.  그동안 6대 의회에서도 이 관리직 인원은 계속 충원이 되는데 정원에 대한 현원이 늘 과부족되는 상태였었습니다.  그래서 훌륭한 박사님들을 많이 모셔야 되지 않겠느냐 하는 이야기를 계속했는데 지금 보니까 2006년도에 연구직 8명을 채용했음에도 불구하고 과부족 인원이 9명이 되는 것은 정원이 늘어났기 때문이지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 정원이 늘어난 것은 아닌가 싶은데요.  아, 작년 2005년에 저희 연구원에 정책개발센터라고 하는 새로운 조직을 만들면서 저희 정원이 늘어난 것으로 알고 있습니다.  그런데 그게 2006년 들어오면서 센터가 폐지된 것으로 알고 있습니다.  그런 과정에서 정원 숫자가 이렇게…….
</p>
<p><b>○ 정인영 위원 </b> 정책개발센터가 폐지되면서 실질적인 정원이 늘어난 거지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 늘어난 TO는 남아있는 셈이지요.
</p>
<p><b>○ 정인영 위원 </b> TO는 남아있고.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 정인영 위원 </b> 그런데 문제는 뭐냐면 물론 원장님께서 취임하신 후에 채용된 인원이지요?  아닙니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아닙니다. 
</p>
<p><b>○ 정인영 위원 </b> 그 전에 채용됐습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 정인영 위원 </b> 그런데 그동안 인력충원을 하라고 계속 촉구를 했음에도 불구하고 안 하다가 2006년도 인원 충원실적에 10명의 인원이 충원된 것을 다행으로 생각하고 앞으로 남은 9명의 과부족 인원도 훌륭하신 분들을 모셔야 된다고 생각하는데 어떤 계획을 갖고 계십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지난번에 도의회에서 보고올릴 때 아마 같은 질의와 같은 제안을 하신 것으로 알고 있습니다.  그래서 그 후에 저희가 몇 분야의 사람을 더 추가로 뽑기 위해서 공모도 하고, 현재도 공모 중입니다만 쭉 신청자를 받아보니까 사실은 저희 연구원이 기대하는 수준에 못 미치는 사람이 대부분이어서 4개 분야의 직을 뽑다가 사실은 다 못 뽑고 한 직만 지사님의 결재를 받아서 결론을 내렸고요.  나머지 직은 계속 공개적으로 신청서를 받고 있는 중입니다.  사람 뽑기가 그렇게 용이하지는 않습니다. 
</p>
<p><b>○ 정인영 위원 </b> 물론 인재를 뽑기 위해서는 참 삼고초려하는 심정으로 인재를 등용해야 된다고 생각됩니다.  일화를 얘기하면 삼성그룹에서 이건희 회장이 사장단회의에서 인재를 등용하라고 했더니 어떤 사장이 “내 연봉에 준하는 그런 인재를 구하고 있습니다.”라고 하는 답변을 했다가 이건희 회장으로부터 굉장히 혼났다라고 하는 이야기를 들은 적이 있습니다.  그러니까 인재를 등용하고 채용하는 데는 물론 심사숙고해야 되겠지만 삼고초려하는 심정으로 인재를 등용하시기를 거듭 부탁의 말씀을 드리고, 왜 연구직 인원이 계속적으로 지금까지 과부족 상태에 있었냐 하는 내용을 지적하면서, 2006년 3월 22일 경기개발연구원 제48차 임시 이사회 회의록을 보면 미집행 인건비와 미집행 연구비를 기금으로 전용한 내용이 있습니다.  미집행 인건비를 기금으로 전용한다고 하는 것은 사람을 쓸 만큼 쓰지 않고 연구를 하지 않고, 그것을 이월해서 예비비나 또 이월해서 사업비로 계속 사용해야 됨에도 불구하고 그러한 사례가 있는데 이 기금 전입에 관한 문제는 우리 존경하는 이해문 위원께서 본질의 시에 다루어 주실 것으로 생각되기 때문에 더 깊이 발언하지 않겠습니다만 이런 인건비를 아껴서는 안 되겠다.  사람을 구하고 인재를 등용하기 위해서는 미집행 인건비를 남겨서 기금에 전용하는 그런 사례는 발생해서는 안 되겠다고 하는 의미에서 질의를 드렸고 답변을 받았습니다.  이상입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 감사합니다.  제가 보충답변을 드려도 괜찮을지 모르겠습니다만…….
</p>
<p><b>○ 정인영 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아까 임우영 위원님도 비슷한 맥락에서 채용방법을 말씀하셨는데 정인영 위원님께서 지적하신 훌륭한 연구자를 모시는 일은 사실은 꼭 공개채용이라고 하는 공식적인 그런 과정만 통해서 할 것이 아니라 특별채용이라고 하는 과정을 통해서 능력되는 분한테 파격적인 대우도 제안을 하면서 모셔올 수 있어야 되는데 제가 보기에는 연구원이 그동안 운영해온 방식과 이런 게 공무원과 대단히 비슷한 것 같아요.  대단히 관료주의적이고 사람을 뽑는데도 경직성이 있어서 앞으로 이런 면에서 연구원이 조금 유연성을 가지고 인력을 활용하는 그런 방안을 모색해야만 좋은 인력을 활용할 수 있지 않을까 싶어서 그런 쪽으로 노력을 하도록 하겠습니다. 
</p>
<p><b>○ 정인영 위원 </b> 감사합니다.  그런 쪽으로 더욱 노력해서 훌륭하신 원장님을 모신 경기개발연구원은 더욱 발전하리라 봅니다.  이상입니다.
</p>
<p><b>○ 위원장 김영복 </b> 정인영 위원님 수고하셨습니다.  보충질의하실 위원님 계십니까?  보충질의하실 위원 안 계십니까?  그러면 김대원 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 김대원 위원 </b> 5년차 이렇게 경기개발연구원 감사에 참여하다보니까 감회가 새롭습니다.  1년에 한 번 뵙습니다만 반가운 얼굴들도 계시고 또 나날이 발전해가는 경기개발연구원을 같이 보고 있으니까 본 위원으로서도 무척 흐뭇한 생각이 듭니다.  특히 좌승희 원장님이 부임하시고 경기개발연구원이 활기차고 능동적으로 운영되는 게 보이는 것 같아서 기획위원의 한 사람으로서 상당한 자부심을 느낍니다.  본 위원이 인사는 이쯤 하고요.
</p>
<p style="padding-left:1.2em">  자료에 의해서 질의를 드리겠습니다.  제가 추가자료로 요청한 세 가지 부분을 비교를 해보겠습니다.  연구원별 각종 위원회 위촉현황하고 거기에 연구원이 각종 자문에 응한 횟수와 연구원별 연구실적의 상관관계를 내봤습니다.  그래서 연구원별 편차는 있습니다만 연구원들이 각종 위원회에 많게는 10여개씩 소속이 돼 있습니다.  그러다 보면 여기 우리 경기도 위원회만 소속이 돼 있는 게 아니라 각 시ㆍ군 및 국가기관 10여개 위원회에 소속이 돼 있다 보면 출장이 아주 잦게 되고 그 위원회에 관한 핵심적인 사안을 맡다보니까 자문역할도 아울러서 많이 수행하는 것으로 돼 있습니다.  결과적으로 이렇게 많은 위원회에 소속돼서 그 위원회에 소속된 자문에 응하다보면 연구실적 면에서, 제가 아까 추가자료를 요구했는데 아직 안 왔습니다만 질이나 양에서 떨어지지 않을까 하는 부분에 대해서 어떻게 생각하시는지 원장님 말씀해 주시지요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 김대원 위원님 질의에 대해서 감사말씀 드리겠습니다.  아주 좋은 지적을 해 주셨는데요.  당연히 위원회 활동을 많이 하면 연구실적이 줄어들 수밖에 없겠지요.  사람이 주어진 시간 안에 슈퍼스타가 아니니까 그렇습니다만 저는 위원회 참석을 너무 규제하는 것은 바람직하지 않다고 생각합니다.  왜냐하면 연구원의 위상이라는 게 그런 위원회를 통해서 좋은 의견을 내고 경기개발연구원의 위상을 높임으로써 연구원이 국가연구원으로서의 기능도 할 수 있고 여러 가지 좋은 점이 있기 때문에 그렇게 합니다만 이 위원회 활동이 너무 과다해서 연구실적에 부정적인 효과가 오지 않도록 저희가 잘 관리해 나가도록 노력은 하겠습니다.  그런데 그동안에 보면 여러분들 아시겠습니다만 우리 연구원이 전국 시ㆍ도연구원 중에, 시ㆍ도연구원만이 아닙니다.  국책연구원까지 포함해서 1인당 연구실적이 제일 많은 연구원이에요.  그래서 아까 걱정하신 대로 양에 대해서는 제가 보기에는 아직도 잘 하는 것 같아요.  참 놀랍습니다, 이렇게 많이 나오는 것이.  그런데 그런 이면에는 결국 질적인 면에서 문제가 생길 수 있지 않을까 그런 생각이 들어서 그러면 질적인 문제를 어떻게 관리할 거냐.  여러 가지 어렵습니다, 질적인 문제를 컨트롤하는 것은.  그래서 저희가 구상하는 것은 모든 연구에 대해서 세미나를 통해서 주변 다른 박사들의 평가도 받고 이렇게 하면서 연구자들이 질에 대해서 더 신경 쓰지 않으면 안 되도록 하는 일종의 모니터링하는 시스템을 도입해서 그런 쪽으로 질 평가를 강화하도록 하는 그런 체제를 정비하도록 노력하고 있습니다.  그래서 두 가지가 서로 잘 갈 수 있도록 해야 되는데 앞으로 최선을 다하겠습니다. 
</p>
<p><b>○ 김대원 위원 </b> 그리고 연구과제를 선정하실 때 경기개발연구원의 역할이라면 사실상 우리 경기도의 정책개발이라든가 이슈사항에 대한 논리적 부분을 대응하는 그런 역할을 수행하고 있는 것으로 알고 있습니다.  그런데 최근 언론에 평택항과 관련해서 동북아지역연구부에서 연구한 수도권 항만의 경합성 및 보완성 분석연구부분이 평택부분에 대해서 언론에서 상당한 문제점을 야기해서 우리 경기도의 경쟁력을 약화시키는 과제물로 비춰지고 있는데 원장님 생각은 어떻습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우선은 그런 보도가 나가서 평택시민들한테 염려를 끼쳐드리고 도를 운영하시는 여러분한테 염려를 끼쳐드린 데 대해서 저는 대단히 죄송하다는 말씀을 드리고요.  그러나 보도내용이 저는 사실이 아니라고 생각합니다.  저희 연구보고서 내용을 잘 보시면 평택항이 과잉투자가 되고 인천항은 그렇지 않고 그래서 평택항이 경쟁력이 떨어진다는 그런 연구결과를 낸 게 아니라 지금 서로 경쟁적으로 이렇게 하면 평택항에 대해서는 투자도 잘 안 하고 인천이나 부산에 자꾸 이렇게 하니까 잠재력을 보면 평택항이 상당히 높은데 그걸 이렇게 해서 그냥 갈 수가 있겠느냐.  상호 간에 경쟁력을 감안해서 소위 말하자면 전문화할 수 있는 어떤 체제를 만들기 위해서 포트 간에 상호 경쟁성, 보완성 이런 것을 검토한 연구입니다.  그래서 이게 무슨 평택항의 경쟁력이 떨어진다는 것을 하려고 한 게 아닌데, 제가 죄송합니다.  이것은 오프 더 레코드로 말씀드렸으면 좋겠는데 평택항하고 경쟁적인 위치에 있는 쪽에서 이것을 약간 편하게 해석하는 바람에 이렇게 누를 끼치게 된 것 아닌가 하는 생각이 듭니다만 어쨌든 저희 연구가 원인이 됐기 때문에 저는 대단히 죄송하다는 말씀을 올리고요.
</p>
<p><b>○ 김대원 위원 </b> 원장님, 답변이 이런 답변이 아니고 이것은 책 자체로만 보면 인터넷에도 나왔습니다만 정책건의 란에, 지금 제가 인터넷에 보고 있는데요.  정책건의 란에도 보면 경쟁력이 약화되어 있다.  중복투자라고 이렇게 정책건의까지 하고 있습니다.  명칭도 아시다시피 경합성 및 보완성 분석 연구다 보니까 경합성에서 떨어지는 결과물을 내놓을 수밖에 없는 거잖아요.  그런데 이런 문제가 야기되었으면, 제가 오늘 답변을 기대했던 부분은 오늘 문제제기가 되었으면 결과물이 나와야 되지 않느냐.  평택항을 이런 기초적인 잠재력을 가지고 있는 부분에 대해서 활성화시킬 방안에 관한 연구가 후속으로 뒤따라 나왔어야지 이렇게 문제제기만 해 놓고, 불만 질러놓고 끄지는 않는 그런 연구행태는 바람직하지 않다는 얘기죠.
</p>
<p style="padding-left:1.2em">  경기개발연구원의 목적은 실질적으로 평택항을 어떻게 발전, 육성시킬 것인가라는 부분의 결과물을 내기 위해서 이런 연구를 하신 것 아닙니까?  그런데 불을 질렀으면 6월 30일 연구과제물이 완료된 사안인데 2006년 1월 1일부터 6월 30일까지 6개월간 이 과제물을 완성시켜서 문제를 야기시킨 것 아닙니까?  그랬으면 지금쯤 민선4기가, 이것은 민선3기 때 마무리되었다고 보고 그러면 7월부터 민선4기 때는 평택항 발전방안에 대한 정책연구가 시작이 되어서 지금쯤은 중간발표가 되어서 수습되어가는 그런 차원의 연구원으로 만드셔야지 문제만 제기해 놓고.  여기 과제물만 보면 누가 봐도 평택항이 열악한 것으로 나와 있습니다.  열악하다라고 만들기 위한 과제였고요.  과제 자체가.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다.  충분히 이해가 가는 질의신데요.  사실은 평택항에 대해서는 자료를 보셨는지 모르겠지만 그동안 연구원 설립 이래 21건에 걸쳐서 평택항의 경쟁력 강화와 경기도의 주요포트로 키우기 위한 여러 가지 비전이 나와 있습니다.  그 연구는 21건 중 하나인데 21건의 다른 연구를 보면 “평택을 키워야 되고 이게 경기도의 미래다.”라는 연구를 이미 많이 냈기 때문에 저희가 그런 점에서 조금 가볍게 생각한 것이 아닌가, 아니면 우리가 미흡하게 대처한 게 아닌가 생각이 들어서 어쨌든 죄송합니다.  이것을 저희가 다시 바꿀 수 있는, 연구할 수 있는 길이 있으면 더 열심히 해서 보완하도록 최선을 다하겠습니다. 
</p>
<p><b>○ 김대원 위원 </b> 경기도가 대한민국의 성장엔진이고 심장이라고 생각하신다면, 경기도가 허울만 좋은 거인이지 실제 속으로 들어가 보면 내실이 너무 없다는 지적을 다른 자치단체로부터 받고 있습니다.  평택항 얘기가 부분이지만 정말로 평택항이 당진항과의 경계분쟁 문제도 너무 안일하게 경기도가 대처했단 말이에요.  그러다 보니까 경기도에서 투자해서 개발해 놓은 부분을 충청남도에 빼앗기는 이런 사례까지 만들었어요.  미래를 예측할 수 있는 그런 부분에 실질적으로 경기도가 다른 도 아니면 국가 간에 또 외국 간에라도 경쟁할 수 있는 대안제시와 사실에 입각할 수 있는, 현실에 접목시킬 수 있는 그런 과제물을 연구하셔서 정책건의도 하시고 정책에 반영되어서 바로 정책으로 이루어질 수 있는 그런 연구원으로 거듭나시기를 당부드리겠습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 명심하겠습니다.  그리고 2～3일 안에 저희가 도하고 같이 협력해서, 평택항의 비전을 다시 재정립하는 내부 움직임이 있고 지금도 노력하고 있고 그동안 21개의 연구가 전부 다 그런 연구를 했기 때문에 이것을 추가로 잘 정리해서 좋은 비전을 제시하도록 하겠습니다. 
</p>
<p><b>○ 김대원 위원 </b> 이렇게 21건의 연구물이 나왔다면 분야별로 쪼개져 있는 부분도 집대성하셔서 한 권으로 만드셔서, 지금 아시다시피 수도권 규제문제라든가 이런 부분에 같이 얽혀져 있는 부분이란 말이에요.  저희들이 대응논리가 지금 동경권이라든가 상해권이라든가 광동성권 이렇게 권역별 전략에 맞추어서 수도권도 수도권규제 개선 문제에 대해서 대처하고 있지 않습니까?  논리는.  그런 차원에서 평택항이 가진 장점을 상당히 부각시켜서 권역별 수도권 부분에 대해서, 여기서 지적했다시피 경쟁성이 아닌 인천항과의 상호보완성, 제가 알고 있기로는 인천항은 해수면이 너무 낮아서 대형 선박이 접안을 못 하고 우리 평택항 같은 경우에는 대형 선박이 접안할 수 있는 장점을 가지고 있으니까 서로 상호보완성이 있다면 작은 선박은 인천항으로 가고 큰 선박은 평택항으로 받는다든가 이런 보완성 관계가 수도권에서 이루어져서 실질적인 대안을 제시하는 그런 연구원이 되시기를 바랍니다. 
</p>
