<p><b>○ 정인영 위원 </b> 정인영 위원입니다.  수도권 항만의 경합성 및 보완성 분석연구에 대해서 자료를 가지고 존경하는 김대원 위원님께서 심도 있는 질의를 해 주셨습니다만 본 위원도 신문지상에서 이것을 봤고 문제점이 있다고 해서 준비를 했습니다.  그런데 질의에 원장님께서 쭉 답변하셨는데 그것보다는 본 위원은 연구책임자인 강승우 책임연구원에게 질의코자 합니다.  지금 나와 있습니까? 
