<p><b>○ 정인영 위원 </b> 김태승 공동연구하신 분은 나와 계십니까?  본 위원이 왜 연구책임자를 불러서 얘기하고자 하냐면 이 부분에 대해서는 연구책임자가 책임질 일이지 원장님이 책임질 일은 아니라고 봅니다.  또 원장님이 어떤 연구결과물에 대한 종합적인 결과를 제시해 놓고 거기에 맞춰서 연구하는 것은 연구 목적에도 합당치 않다고 생각이 되고 또 하나는 지금 언론지상에 오해로 비쳐졌다고 답변하시던데 그 부분은 원장님께서 적극적인 홍보를 통해서 해야 될 부분이라고 생각됩니다.  우선 원장님께서 홍보문제에 대해서 답변해 주시죠.
