<p><b>○ 경기개발연구원장 좌승희 </b> 정 위원님 의견에 저도 같은 생각입니다만 물론 연구하는 사람한테 원장이 연구결과에 대해서 사전에 얘기할 수도 없는 것이고 해서도 안 되는 것이고 연구결과에 대해서는 연구한 사람의 책임 하에 하는 것이죠.  그러나 연구원의 이름을 걸고 나가는 모든 서류와 자료와 보고서는 어쨌든 연구원장 책임이라고 생각합니다.  실질적으로 내용의 책임은 못 지더라도 도덕적인 책임은 면할 길이 없기 때문에 아까 김대원 위원님 질의에 답변을 시도했는데 강 박사한테 이야기를 듣고 나름대로 저도 사안을 파악했다고 생각했는데 김 위원님이 충분치 않다고 생각했던 것 같습니다.  강 박사가 올라오는 대로 답변을 드리도록 하고 보도한 바로 그날 아침에 강 박사가 해명자료를 내고 보도해서 일부에는 해명자료가 나갔습니다만 일단 언론에 보도가 되면 계속 살아서 움직이기 때문에 어쩔 수 없는 그런 생리도 있습니다.  그래서 어려움이 있습니다만 저희가 사태를 반전시킬 수 있는 노력을 해 보도록 하겠습니다. 
</p>
<p><b>○ 정인영 위원 </b> 그러니까 책임연구원인 강승우 박사가 해명자료도 내고 해명보도 자료도 냈다고 하는 것은 언론에 비쳐진 것은 내가 연구한 결과물하고는 전혀 다른 의도로 보도가 되었다고 하는 것을 인정하는 것이죠?  보도내용을 인정한 게 아니죠?
