<p><b>○ 경기개발연구원장 좌승희 </b> 물론이죠.  제가 보도자료를 가지고 말씀을 올린 겁니다.  그 내용과.  제가 강 박사하고 만나서 그 내용을 확인한 것을 말씀드리는 거죠.  강 박사가 올라왔습니다. 
