<p><b>○ 동북아지역연구부책임연구원 강승우 </b> 네, 그렇습니다.  
</p>
<p><b>○ 정인영 위원 </b> 얼마 전 언론보도에 의하면 평택항이 과잉중복투자가 되고 있다고 하는 보도가 있었는데 그 부분에 대해서 어떻게 생각하십니까? 
</p>
<p><b>○ 동북아지역연구부책임연구원 강승우 </b> 그 부분에 대해서 저희가 27일 해명자료를 배포했고요.  그 부분 연구를 하게 된 동기는 사실 수도권 항만의 중요성을 강조하고 자, 투포트시스템의 정부정책이 잘못 되었다는 것을 한번 지적하고 싶었던 것이 연구의 목적이었습니다.  그리고 이차적으로는 인천항에 비해서 평택항이 경쟁력이 뒤지지 않는다는 것을 보여주고 싶었고요.  그래서 평택항의 문제점을 한번 짚어보고 향후 발전전략을 제시하고자 하였던 것입니다.  그런 부분에서 약간의 오해 소지가 있었던 것 같습니다. 
</p>
<p><b>○ 정인영 위원 </b> 경합성과 보완성 측면에서 인천항과 지리적으로 떨어져 있는 부산항이 보완성을 가지고 있는 반면 인천항과 평택항은 많은 품목에서 서로 경합적인 관계에 있다는 결론을 도출할 수 있다는 결론을 맺으시면서 인천항은 농산물, 광물, 음식료, 목재, 펄프, 금속기계, 정밀기계, 자동차 등 분석대상 10개 중 7개에서 경쟁우위를 보였다.  그런데 평택항은 5개 중 3개에서 경쟁열위를 나타냈다고 표현을 했습니다.  이것은 무슨 얘기죠?
</p>
<p><b>○ 동북아지역연구부책임연구원 강승우 </b> 그 부분에서 약간의 오해의 소지가 있었던 것 같습니다.  7개 품목이라는 것은 평택항하고 비교해서 7개 품목이 아니라 우리나라 전체 4개 항만을 비교했을 때 인천항의 가장 최근 5～6년간의 어떤 점유, 분석한 기준 툴에 의해서 경쟁력이 가장 향상되고 있다고 보여진 것이고요.  평택하고 인천하고 비교한 분석은 물동량 증가치라든가 점유율에 따라서 분석하다 보니까 물동량의 변동이 심해서 분석하기 어려웠던 품목도 있었습니다.  그래서 평택항과 인천항과의 분석대상 품목 중에 4개 품목이 분석이 가능했습니다.  그 중에서 3개 품목이 인천항이 약간 우세했고 1개 품목이 평택항이 우세했던 내용이었습니다.  그 부분이 약간 간략하게 써지다 보니까 오해의 소지가 있었던 것 같습니다. 
</p>
<p><b>○ 정인영 위원 </b> 그래서 강 연구원께서는 정책건의를 어떻게 하셨냐면 “인천항과 경쟁항의 시설경쟁은 자칫 과잉투자라는 문제를 낳을 가능성이 매우 높기 때문에 이에 대한 조정이 필요하다는 것임.  검토대상 품목의 상당부분에서 인천항과 평택항은 상호 경합관계에 있음.  따라서 시설투자경쟁보다는 인접한 항만 간 상호보완성을 제고할 수 있는 역할분담을 위한 노력이 선행되어야 할 것임.” 이렇게 정책건의를 했습니다.  이 부분에 대해서는 어떻게 답변하실 겁니까?
</p>
<p><b>○ 동북아지역연구부책임연구원 강승우 </b> 표현상 약간의 오해 소지를 가질 수 있다는 것을, 표현상 약간 미숙함을 인정합니다.  하지만 인천항과 경쟁항만에 있다는 표현 자체가 인천항을 기준으로 해서 경쟁항만에 대한 과잉투자 우려가 아니라 인천항뿐만 아니라 경쟁항만이 전부 대상이 된다고 보면 될 것 같습니다.  그래서 저희가 그 의도는 사실 평택항이 잠재력을 가지고 있는데도 불구하고 인천항에 비해서 정부의 투자라든가 관심이 항상 개발 후순위에 있기 때문에 그것에 대한 문제점을 지적하고 자 그런 문장을 썼던 것인데 그 표현이 약간 미숙했었던 것 같습니다.
