<p><b>○ 임우영 위원 </b> 제가 왜 이런 말씀을 드리냐면 존경하는 선배 위원이신 정인영 위원님께서도 말씀하셨는데 언론에 보도되고 나니까 실질적으로 우리 위원님들이 우려했던 것도 언론에서 이야기하듯이 우리 강 박사님이 원래 의도했던 연구는 책자가 맞습니다.  그게 왜 그런 줄 압니까?  여러분들이 지금 정책건의만 가지고 말씀하셨는데 분명히 연구개요에 나와 있어요.  뭐라고 나와 있냐, “본 논문의 목적은 수도권의 인천항과 평택항과 기간 항로상에 있는 부산항과 광양항 간에 대중국 처리물동량을 기준으로 경합 및 보완관계를 분석하여 국내 항만의 역할 및 기능에 대한 가이드라인을 제시하는 데 있다.  항만 간 경합성 및 보완성을 분석하기 위해 항만별로 경쟁력 지수를 산정하여 항만 간의 비교 분석에 의해 이루어졌다.” 이렇게 분명히 얘기해 놨습니다.  여기에 우리 박사님이 이야기하듯이 평택항의 앞으로의 그런 문제점에 대해서 목적에는 아무 것도 없어요.  거론이 안 되어 있습니다.  평택항 하나만 거론이 안 되어 있어요.  분명히 여기 결론적으로 내린 “독자적 발전 가능성을 가지고 있는 항만의 기능을 손상시킬 수 있기 때문이다.” 이렇게 내렸으면 제가 이거 평택항이라고 인정합니다.  그런데 방금 말씀드린 그게 독자적 발전가능성을 가지고 있는 항만들의, 분명히 복수입니다.  이것은 평택항만 가지고 이야기했다고는 보여지지 않기 때문에 그렇습니다.  그래서 제가 말씀드리는 것은 여기서 문제제기는 되었고 언론에서 그렇게 되었지만 연구하시는 박사님들은 개인적으로 당신이 연구하신 결과물에 대해서는 소신을 가져 달라 하는 것을 말씀드리고 싶습니다.  물론 언론에 그렇게 보도되고 결과가 이렇게 나와서 경기도의 이미지, 어떻게 보면 평택항을 중심으로 해서 우리 항만을 개발하고자 하는 경기도 입장에서 보면 손상시킬 수 있어요.  그렇지만 학자의 입장에서 연구결과물을 내놨으면 그것에 대한 입장은 소신을 가져 달라.  꼭 이 문제뿐만이 아니라 어느 결과도 마찬가지입니다.  그래서 그게 진짜 문제가 있다면 도 차원에서 정책을 바꾸는 것도, 과감하게 바꾸는 것도 생각을 해 봐야 된다고 저는 개인적으로 생각을 합니다.  그래서 자꾸만 궁색하게 이렇게 저렇게 변명하시려고 그러지 마시고 소신을 가져주시기 바랍니다.  이상입니다.
