<p><b>○ 김기수 위원 </b> 저는 언론에 이게 처음 보도되었을 때 참 훌륭했다, 잘 했다 이렇게 생각을 했습니다.  저는 견해를 달리 하거든요.  오늘 와서 보니까 박사님 소신이, 우리 존경하는 임우영 위원님께서 끝머리에 말씀드렸지만 소신이 없으신 것 같아요.  왜 그렇습니까?  당당하게 하셨으면 진짜 본 위원이 다 보지는 못했습니다.  언론에서 보고 결론부분만 봤지만 이것은 잘했다고 봅니다.
