<p style="padding-left:1.2em">  물론 예스맨만 할 수 있습니다.  마음에 저 양반 의도되는 대로 할 수 있습니다.  우리 박사님께서 잘 하셨습니다.  그렇게 되어야지 경기개발연구원이 발전이 되고 여기 존경하는 위원님들 중에서 이 연구 가지고 뭐라고 하면 안 됩니다.  이것은 프라이버시입니다.  프라이버시인데 박사님께서 단지 거기에서 변명을 약간 하신 것에 대해서 저는 참으로 안타까운 마음을 가지고 있어요.
</p>
<p><b>○ 동북아지역연구부책임연구원 강승우 </b> 위원님, 제가 한 말씀 잠깐 드려도 되겠습니까?
</p>
<p><b>○ 김기수 위원 </b> 됐습니다.  됐고, 쉬운 말로 지식 야바위꾼은 되지 않아야 됩니다.  저는 경기도 정책건의를 읽어봤는데 이것은 다른 위원님들하고 견해를 다르게 합니다.  이것은 우리 박사님께서 아주 잘 했다고 칭찬을 해 주고 싶습니다.  이상입니다.  답변은 됐습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 김기수 위원님 수고하셨습니다.  장윤영 위원님 보충질의해 주시기 바랍니다. 
</p>
<p><b>○ 장윤영 위원 </b> 지금까지 진행되는 것을 옆에서 봤습니다.  이것은 약간 연구원에서 조직의 문제가 아닌가 하는 생각이 들면서 질의를 드리겠습니다.  지금 경기개발연구원에는 연구위원회가 있지 않습니까?  연구위원회가 몇 명입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 연구위원회가 원장, 부원장 포함해서 각 실장, 센터장…….
</p>
<p><b>○ 장윤영 위원 </b> 10명입니다.  그 다음에 심의위원회가 있습니다.  8명 맞습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 맞습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 그 다음에 연구평가심의회가 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 지금 언론에 나오고 그 다음에 위원님들이 말씀을 주십니다.  제일 중요한 것은 연구자한테, 연구하신 박사님한테 어떤 예단을 줘서는 안 된다.  그래서 분명한 근거와 자료를 통해서 있는 그대로의 작품이 나오게끔 해 주고요.  그 다음 평가 자체에서는 여러 가지 나올 수 있습니다만, 그래서 처음에 연구과제로 선정하게 되는, 아마 연구위원회에서 먼저 결정이 될 겁니다.  그렇지요?  그 다음에 이 결과물이 나왔을 적에 연구평가심의회가 과제별로 몇 명이 선정됩니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 외부에서 두 사람 이상의 평가위원을 초청하고 원내에서 원장을 포함해서 이렇게 들어가서 하게 돼 있습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 죄송합니다.  원장님께서 지금 답변에 대해서, 제가 가지고 있는 자료 있지 않습니까?  연구평가심의회는 각 과제당 4명으로 해서 선정되는데 원장님 포함 안 되십니다.  맞습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 원장이 들어갈 수도 있고 안 들어갈 수도 있습니다.  그러나…….
</p>
<p><b>○ 장윤영 위원 </b> 지금 다른 명수가 중요한 것이 아니라 소신있게, 임의대로 작성하신 작품은 아닐 겁니다.  이렇게 논란이 있을 수 있는 것은 충분히 의미있는 작품인데 문제는 안에서 제도적으로 먼저 필터링을 해달라는 겁니다.  그래서 이 문제에 관한 한은 연구위원회, 그 다음에 연구평가심의회, 그 다음에 심의위원회 이 역할이 좀 모자랐기 때문에 이런 논란이 일어난 것이 아닌가라는 부분에 있어서 조직에 대한 재정비와 다시 한 번 검토가 있어야 될 중요한 사안이라고 판단하면서 질의가 아닌 권면의 말씀으로 발언을 마치도록 하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 감사합니다.  명심하겠습니다.
</p>
<p><b>○ 위원장 김영복 </b> 장윤영 위원님 수고하셨습니다.  전동석 위원님 보충질의해 주시기 바랍니다. 
</p>
<p><b>○ 전동석 위원 </b> 전동석 위원입니다.  평택항 개발사업에 대한 문제가 상당히 커지고 있는데요.  본 위원의 생각으로는 사실상 경기개발연구원이 중요한 역할을 해야 되는데도 불구하고 역으로 어떻게 상당한 후속 다른 조치가 이루어졌다고 하는 것에 대해서 상당히 경악을 금치 못하는데요.  아까 말씀하시기를 처음에 이 자료가 보도됐을 때 보도자료를 먼저 배포한 것은 아니지요?
</p>
<p><b>○ 동북아지역연구부책임연구원 강승우 </b> 네, 그렇습니다. 
</p>
<p><b>○ 전동석 위원 </b> 그게 이제 불거지니까 결국에는 그것에 대해서 해명자료를 낸 게 보도자료지요?
</p>
<p><b>○ 동북아지역연구부책임연구원 강승우 </b> 네, 그렇습니다. 
</p>
<p><b>○ 전동석 위원 </b> 그러면 처음에 이 연구과제가 끝난 다음에 이것이 유출된 경위를 말씀하실 수 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 유출이라기보다는 배포를 저희가…….
</p>
<p><b>○ 전동석 위원 </b> 배포하니까 그것을 가지고 썼다 이런 말입니까? 
</p>
<p><b>○ 동북아지역연구부책임연구원 강승우 </b> 연구결과가 나오면 저희 연구원 홈페이지에 연구보고서와 함께 초록이 올라오게 돼 있습니다.  그것을 보신 것 같습니다.
</p>
<p><b>○ 전동석 위원 </b> 경기개발연구원의 역할이 굉장히 중요하고 실제로 개발한 내용이 아까도 말씀드렸어요.  홍보를 어떻게 하느냐에 따라서 그것이 얼마나 이득이 되고 얼마만큼 해가 되는가를 단적으로 보여주는 예인데요.  실제로 이런 것을 처음부터 그냥 배포하는 것이 아니라 아까 그러셨잖아요.  “언론브리핑을 통한 연구결과의 홍보활성화다.” 이런 말씀을 하셨는데 처음부터 이것도 언론브리핑을 통해서 처음에 그런 일이 있었으면 그것에 대해서 전혀 문제가 없지 않았나 이런 생각을 합니다.  특히 평택항에 대해서는 첨예의 관심사가 되고 있는 사항이에요, 사실상.  그런 차원에서 생각한다면 어떤 싱크탱크의 역할을 하고 있다는 경기개발연구원이 정말 큰 우를 범하지 않았나 이런 생각합니다.
</p>
<p><b>○ 김기수 위원 </b> 위원장님, 의사진행발언 있습니다.  잠깐만요.  이것은 지금 위원들이 연구논문 갖고, 이것을 하는 것을 소신있게 하는 건데 논문 갖고 얘기하면…….
</p>
<p><b>○ 전동석 위원 </b> 제가 지금 얘기하고 있는 중인데요, 나중에…….
</p>
<p><b>○ 김기수 위원 </b> 의사진행발언을 했습니다.  이것은 제지를 위원장께서 해 주셨으면 좋겠습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 위원님들은 나름대로 발언을 할 수 있습니다.  거기서 참고만 하시지요.  의견에 대해서는 서로 존중해 주시고 판단은 나름대로…….
</p>
<p><b>○ 전동석 위원 </b> 나중에 그것을 보도자료로 내놓으셔서 이게 이런 의도가 아니라고 분명히 말씀하셨기 때문에 말씀드리는 거예요, 그렇지요?  처음에 이런 의도였다고 말씀했으면, 처음부터 김기수 위원님 말씀대로 그랬다면 어떤 소신을 이야기할 수도 있겠지만 다음에 분명히 보도자료를 내놓고 이것은 이런 의도가 아니라 저런 의도였다고 분명히 다른 설명을 하셨기 때문에, 그러면 처음부터 이런 중요한 결과물이 나왔으면 깊이 생각하고 언론브리핑을 통한 어떤 조치가 있었으면 뒤에 이런 문제가 없지 않았느냐 이런 생각이 듭니다.  그래서 앞으로 특히 경기도의 중요과제사업에 대해서는 그 결과물이 나오면 반드시 언론브리핑을 통해서 알리고 그게 얼마나 나라에 중요한 역할을 미치는가 하는 것을 알려주시면 고맙겠습니다.  원장님, 그렇게 해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다.  이 연구는 사실 그 제도가 들어오기 전에 마무리가 되고 이래서 제가 좀 소홀하게 다룬 면이 그런 게 아닌가 하는 생각이 들어서요.  앞으로 철저하게 그런 브리핑을 해야 된다고 하는 의무감이 있어야 연구결과에 대해서 보다 분명한 소신을 가지고 발표도 하고 이렇게 할 수 있기 때문에…….
</p>
<p><b>○ 전동석 위원 </b> 아울러 하나만 더 짚고 넘어가겠습니다.  지금 강 박사님께서 말씀하신 것이 김기수 위원님이 말씀하신 대로 소신을 굽히신 겁니까? 
</p>
<p><b>○ 동북아지역연구부책임연구원 강승우 </b> 그런 건 아닙니다. 
</p>
<p><b>○ 전동석 위원 </b> 그런 게 아니라 실제로 오해의 소지가 있다는 쪽으로 간 거지요, 그렇지요?
</p>
<p><b>○ 동북아지역연구부책임연구원 강승우 </b> 아까 제가 잠깐 답변을 드리고 싶었던 말씀은 이 연구는 저희가 연구를 하면서 분석까지만 가고 이 연구와 함께 동시에 같이 진행됐던 게 있습니다.  그래서 거기에 이 분석을 토대로 해서 향후 발전전략을 제시하고자 한 연구가 지금 진행되고 있습니다.  사실 그 부분에 대해서 언급이 빠진 부분 때문에 평택항을 외면한 채 보고서를 만든 것 아니냐는 그런 기사가 난 것 같습니다.  그래서 그것과 병행해서 평택항 발전전략을 지금 연구하고 있기 때문에 그것에 대한 소신은 가지고 있습니다. 
</p>
<p><b>○ 전동석 위원 </b> 일반 기사가 쭉 나왔는데 제가 보도자료를 가지고 있습니다만 “과잉투자는커녕 평택항 찬밥 신세다.” 이런 제목으로 나가니까 상당히 문제가 됐습니다.  저도 평택항 관련된 사람 중에 한 사람입니다.  그런데 실제로 이런 것을 통해서 그것이 소신있게 추진될 수 있도록 하는 것은 좋습니다.  그러니까 그것이 처음부터 “이게 소신이다.” 하는 것을 반드시 다른 사람이 오해할 소지가 없도록 진행하는 것이 굉장히 중요하다고 생각하거든요.  이것에 대한 앞으로 후속조치를 충분히 해서 더 오해소지가 없도록 조치를 해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 원장으로서 정말 다시 한 번 죄송하다는 말씀을 드리고요.  아까 강 박사가 얘기했지만 이것은 테크니컬 한 분석파트지 정책제언연구보고라고 생각하지 않습니다.  그러니까 사실은 후속연구를 통해서 평택항이 나갈 길을 제시하고자 하는 그런 의도가 있었고 지금 그 연구가 진행되고 있기 때문에 가능한 한 빨리 마무리 짓고 이것을 분명한 소신을 가지고 언론이라든가 외부에 발표할 수 있도록 하는 일을 빨리 추진하겠습니다.  조금 전에 김대원 위원님께서도 하루빨리 이 후속조치를 해달라고 하셨는데 사실은 그게 이미 동북아연구팀에서 진행되고 있는 거니까 하루빨리 마무리해서 좋은 결과, 옳은 결과를 내도록 노력을 다하겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 이상 질의를 마치겠습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 전동석 위원님 수고하셨습니다.  행정사무감사장입니다만 위원님들이 나름대로 분석이 다 다릅니다.  그래서 행정사무감사 자리에서는 어떤 누구든지 자기 소신껏 말할 수 있고 또 우리 연구원에서는 이런 연구과제된 것을 굽히지 말고 소신껏 해서 우리 연구원이 싱크탱크로 다시 태어날 수 있는 이런 기회가 됐으면 하는 그런 바람입니다.
</p>
<p style="padding-left:1.2em">  질의하실 위원 계십니까?  보충질의요.  아니면 자료요구.  이해문 위원님 자료요구해 주십시오. 
</p>
<p><b>○ 이해문 위원 </b> 자료요구 좀 하고 오후에 질의하도록 하겠습니다.  과천 출신 이해문 위원입니다.  경기개발연구원의 정관과 재무회계규정에 의해서 몇 가지 자료요구를 부족한 것을 하겠습니다.  먼저 연도별 이월금 현황 및 잉여금 처분계획서를 제출해 주시고요.  그 다음 연도별 예비비 예산 및 집행현황, 그리고 지금 경기개발연구원이 가지고 있는 토지, 건물 관련 등기부등본과 임대차계약서, 그 다음에 지금 기업회계 기준에 의해서 처리하고 있는 회계장부 중에 총계정원장하고 현금출납, 그 다음에 일계표 이 세 가지를 2005년 12월 31일자 것하고 또 2006년 10월 30일 이틀의 자료만 제출해 주시면 감사하겠습니다.  이상 자료요구를 마치겠습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 위원님들께 양해의 말씀을 드리겠습니다.  행정사무감사 기간 중 중식시간이 많이 경과되었습니다.  따라서 중식 후에 계속 감사를 진행코자 하는데 이의가 없습니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 중식과 휴식을 위해서 14시 30분까지 감사를 중지하겠습니다. 
</p>
<p class=''ar''>(12시29분 감사중지)
</p>
<p class=''ar''>(14시33분 감사계속)
</p>
<p><b>○ 위원장 김영복 </b> 좌석을 정돈해 주시기 바랍니다.  감사를 계속하겠습니다.  계속해서 감사 질의답변을 진행토록 하겠습니다.  그러면 질의하실 위원께서는 거수로 신청하여 주시기 바랍니다.  권혁조 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 권혁조 위원 </b> 안산 출신 권혁조 위원입니다.  점심 잘 드셨습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 권혁조 위원 </b> 행정사무감사 준비를 위해서 노고해 주신 좌승희 경기개발연구원장님과 관계 공무원 여러분께 치하와 감사의 말씀을 드립니다.  책임감을 갖고 도정발전을 위해서 경쟁력 강화와 삶의 질 향상을 위해서 정책개발을 하시느라고 수고가 많습니다.  예산에 대해서 질의하겠습니다.  연구원은 1995년 3월에 개원하여 벌써 11년째 접어들었습니다.  그간 경기도에서 운영에 따른 예산과 기금적립금으로 매년 적지 않은 예산을 지원해 왔습니다.  이제는 어느 정도 자체수익사업이 궤도에 올라 도민의 부담을 줄여줄 수 있어야 한다고 생각하는데 그렇지 못한 것 같습니다.
</p>
<p style="padding-left:1.2em">  업무보고서 4쪽에 2006년 재정운용을 보면 2006년도 총수입과 지출은 167억 3,500만원입니다.  그중 경기개발연구원이 수익사업으로 얻은 사업수익은 8억 1,300만원으로 4%에 그치고 있습니다.  경기개발연구원의 목적과 도정 기여 정도를 생각한다면 수익사업이 목적이 아닐 것입니다.  그렇지만 개원 11년째를 맞이해서 아직 4% 대의 수익사업은 기대에 아주 못 미친다고 생각하는데 원장님의 앞으로 비전과 계획에 대해서 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 말씀 올리겠습니다.  오전 시간에도 논의가 있었습니다만 제가 보기에 우리 연구원이 현재 하는 연구결과를 가지고 기금을 확보하기 위한 재원으로 활용하기는 대단히 어려움이 있어 보입니다.  그런데 지금 예산을 보는 관점에 따라서는 도의 출연금이 사실은 도의 모든 자금을 저희에게 해 주기 때문에 나오는 돈이라고 봅니다.  저희 수탁과제도 그렇고 연간 하는 거의 모든 정책과제, 수탁과제가 도의 요청에 의해서 하는 게 많은데 저 개인적으로 판단하기에는 그게 시장가격을 받고 있다고 생각 안 합니다.  그래서 그런 면에서 사실은 지금 출연금도 우리가 서비스한 것에 대한 대가를 받는 것이라고 생각하기 때문에 물론 이게 재정에서 나오는 돈이라서 우려가 되기는 하겠습니다만 그런 면에서 저희가 충분히 저희가 서비스해서 대가를 받는 거다 그런 말씀을 드리고요.  그럼에도 불구하고 도에서 하는 일뿐만 아니라 다른 민간부문에까지, 도나 시ㆍ군에서 하는 일뿐만 아니라 민간부문에까지 기금예산을 확보하기 위해서 벌이에 나선다고 하면 그게 가져올 파장이 적지 않을 것 같은 생각이 들어서 그 문제를 저희가 좀 심도있게 더 고민해 보고 앞으로 예산독립이라든가 이런 문제에 대한 저희 방침을 정리해서 보고를 드리는 게 어떤가 하는 생각이 듭니다.  사실은 그냥 답변드리기에는 어려운 난제라고 생각합니다. 
</p>
<p><b>○ 권혁조 위원 </b> 감사합니다.  그러면 제가 요청한 행정사무감사자료 211페이지를 보시면 장서보유현황이 단행본, 간행물, 학위논문 등을 합해서 3만 5,683권의 장서를 보유하고 있습니다.  이러한 장서규모는 중간규모의 공공도서관에 해당한다고 하는 장서규모일 것입니다.  장서 이용실적을 보면 6,410건으로 대출돼 있는데 이 실적은 대략 1일에 30～40권 정도로 일반 공공도서관에 비해 턱없이 적은 실적입니다.  물론 경기개발연구원의 성격상 일반대출의 목적은 아닐 것입니다만 그렇다 하더라도 학생들이나 전문가들이 많이 이용할 수 있는 것이 바람직한 일이라 생각합니다.  이에 대한 원장님의 고견을 듣고 싶습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지적하신 말씀에 저도 동감합니다.  물론 저희 연구원이 기술적인 부분에 대한 연구를 많이 하기 때문에 장서가 상당히 기술적인 그런 서적들이 많아서 일반용도로 읽히기에는 어려움도 있다고 생각합니다만 향후에 저희가 좀더 개방도서정책을 써서 도민들이 활용할 수 있도록 기회를 넓히도록 하겠습니다. 
</p>
<p><b>○ 권혁조 위원 </b> 도민들이 많이 활용할 수 있도록 부탁을 드립니다.  제가 요구한 행정사무감사 자료 215쪽입니다.  각종 위원회 개최현황을 보면 연구과제의 필요성, 연구내용, 실행예산, 참여연구진, 진행계획 등에 대해서 심도있는 심의ㆍ의결을 위해 연구위원회를 개최하는 것으로 생각됩니다.  연구위원회의 회의실적을 보면 2005년도는 251건을 심의하였고 2006년도에는 54건을 심의한 것으로 돼 있습니다.  2005년도와 2006년도의 심의건수가 이렇게 차이 나는 이유에 대해서 말씀해 주시기를 부탁드립니다.  215페이지입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 자료를 보고 있는데요.  상식적인 답변을 우선 드린다면 금년은 아직 연도가 끝나지 않았기 때문에 연구보고회가 계속 진행되고 있어서 그렇고 내년도 연구계획이 추가로 나오면서 연구심의위원회를 보다 더 많이 하게 되지 않을까 하는 그런 생각을 합니다만 너무 차이가 나서, 우리 실무자한테 답변을 요청해도 괜찮을지 모르겠습니다.
</p>
<p><b>○ 권혁조 위원 </b> 네.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기조실장 이상훈입니다.  위원님께서 질의하신 내용은 2005년도에 비해서 2006년도 연구위원회 실적이 떨어지지 않느냐는 그 지적사항이신 것 같습니다.  그래서 이것은 연구위원회의 심의내용을 분리했습니다.  그래서 이전에 특히 심의위원회 건 부분을 연구위원회에서 많이 소화해 낸 데 비해서 2006년도부터는 연구위원회는 순수한 연구과제 관련된 내용만을 심의하다보니까 이 건수가 많이 줄어들었습니다. 
</p>
<p><b>○ 권혁조 위원 </b> 그러면 연구위원회 심의내용을 보면 2005년도에 251건을 심의하여 5건을 부결처리하였고 2006년도에는 178건을 심의해서 27건을 부결처리하였습니다.  연구위원회 심의결과 부결처리가 2006년도에 급증한 이유에 대해서 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기조실장 이상훈입니다.  그것도 제가 답변을 드리겠습니다.  앞서 답변드린 2006년도 연구위원회 건수가 줄어든, 같은 한 건수당 처리과제, 한 건수당 처리내용이 많아졌습니다.  실질적으로 2006년도 들어오면서 상당한 부분이 기획조정실의 연구기획팀으로 넘어오면서 연구기획팀에서 일괄해서 상정해서 처리하다보니까 연구위원회 개최건수는 줄어들지만 각 건마다 처리한 내용들은 숫자가 많습니다.  그러다보니까 일괄해서 올리다보니까 부결된 내용들이 많이 나오게 될 수밖에 없었습니다. 
</p>
<p><b>○ 권혁조 위원 </b> 잘 알겠습니다.  경기개발연구원은 경기도의 싱크탱크로서 기대하는 바가 매우 큽니다.  지사님께서도 좌승희 원장께서 역량을 발휘하여 경기도의 비전을 제시하는데 기여할 것을 기대할 것입니다.  따라서 앞으로 경기개발연구원의 이러한 기대만큼이나 연구수준을 높이고 도민의 기대에 부응할 수 있기를 기대하면서, 지금 질의책자를 보니까 1080페이지인데 너무 두꺼워서 갖고 다니기도 힘들어서 이것을 앞으로는 2권이나 3권으로 하는 건 어떻게 생각하는가 질의하겠습니다.  간단하게 해줄 수 없습니까?  너무 두꺼워서 들고 다니기가 힘든데.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 알겠습니다.
</p>
<p><b>○ 권혁조 위원 </b> 질의를 마치겠습니다.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 격려말씀 감사하고요.  지적하신 대로 내년도에는 부담이 안 가도록 하겠습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 권혁조 위원님 수고하셨습니다.  권혁조 위원님이 질의하신 연구원의 장서보유현황 등 각종 위원회 운영실정, 연구조성사업 운영실정 이런 것에 대해서 보충질의하실 위원 계십니까?  장윤영 위원님 보충질의해 주시기 바랍니다. 
</p>
<p><b>○ 장윤영 위원 </b> 아까 실장님께서 말씀하신 거요.  회의 개최실적 및 주요안건 처리결과에서 다시 한 번 설명을 주시겠습니까?  부결건수가 많았던 것에 대해서.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기조실장 이상훈입니다.  위원님께서 보충질의하신 내용이 부결 건수가 많다는 그 건 이유에 대해서 말씀하신…….
</p>
<p><b>○ 장윤영 위원 </b> 일괄상정 뭐…….
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네.  그 이전에는 연구위원회 개최가 개별 박사가 제안한 과제 건에 대해서 연구위원회에서 심의를 해서 결정했는데 2006년도 이후의 사업방식이 기획조정실에서 일괄해서 과제를 다루게 됐고 그 다음에 연구위원회 개최 1건당 올라가는 안건 수가 많아졌습니다.  안건 하나하나가 과제가 됐고요.  그리고 과제 수행을 하는 데 있어서 지나치게 너무 많은 과제를 수행하고 있다는 지적도 많고 연구의 질에 대해서 지적도 많이 나왔기 때문에 그것을 기획조정실에 1차적으로 스크린을 하고 스크린을 한 내용에 대해서 연구위원회에 올려서 개최하고 그러면서 아마 부결건수도 많이 늘어난 것으로 파악하고 있습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 스크린을 했다고 한다면 상정되지 않아야 되지 않습니까? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 그래도 연구과제 수행여부 내지 필요성 이런 내용에 대해서는 기획조정실에서 일괄적으로 판단할 수 없기 때문에 그것은 연구위원회 심의ㆍ의결 건으로 처리하고 있습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 그러면 일단 상세질의에 앞서서 기안자 있지 않습니까?  236페이지부터 나와 있는 거요.  기안자하고 연구책임자의 관계는 어떻습니까?  
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기안자와 연구책임자요?
</p>
<p><b>○ 장윤영 위원 </b> 네.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 일반적으로 여기서 나온 기안자가 되는 경우는 수탁과제 같은 경우는 연구책임자가 결정돼 있는 경우가 있습니다.  사전에 무슨 협의를 했다든지 사전에 어떤 일정논의가 진행된 이후에 수행되는 과제에 대해서 기안자는 연구책임자가 될 수 있고요.  다만 연구책임자가 결정되지 않은 상태의 과제, 그 기안자는 기조실에서 연구기획팀장 명의로 해서 과제를 추진하다가 연구위원회에 상정을 하고 연구위원회에서 연구책임자를 결정해 주는 그런 절차가 있습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 그러면 참고적으로 하겠습니다.  그러면 기안자하고 상정돼서 기안하신 연구원이 있습니다.  그런데 정해졌을 때 기안자가 배제되는 경우가 있습니까?  해당 연구에서 배제되는 경우가 있습니까? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 연구위원회에서 심의할 경우가 있습니다.  일단 그렇게 생각하시면 될 거예요.  예를 들어서 특정한 A라고 하는 과제가 의뢰 들어왔을 때 그 과제에 대한 연구책임자가 결정되기 전까지의 기안자는 기획조정실 기획팀장입니다.  그래서 각종 과제의 적당한 연구진하고 연구책임자를 고려하고 그것을 검토한 내용을 연구위원회에 상정시켜서 연구위원회에서 연구책임자를 결정하게 됩니다.  그러면 과제수행 여부, 그 다음에 연구책임자를 결정하는 것을 1차 연구위원회에서 심의해서 결정하고요.  그렇게 된 이후에 연구책임자가 결정되면 그 이후에 해당과제에 대한 실행예산이라든지 연구기간, 연구진 편성, 이런 내용, 여기서부터는 연구책임자가 기안자가 돼서 수행하고 있습니다.
</p>
<p><b>○ 장윤영 위원 </b> 일단 이해는 잘 가지 않지만 세부적으로 한번 묻겠습니다.  245페이지 봐주시겠습니까?  이거 자체는 보통 과제수행 여부하고 그 다음에 실질적으로, 제가 질의하고 있는 것은 148번하고 그 다음에 193번이거든요.  실질적으로 심의일자가 불과 한두 달에 불과한데 똑같은 제목으로 올라가 있습니다, 물론 두 개 다 가결됐습니다만.  이렇게 같은 제목으로, 앞에서 심의ㆍ의결내용에서는 다르거든요. 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 그 내용에 대해서 자세히 설명드리겠습니다.  일단 수탁과제라고 하면 일반적으로 얘기하는 용역입니다.  외부에서 저희 연구원에 예산을 할애해서 의뢰한 과제입니다.  그래서 148번인 경우에는 당시에 연구기획팀장이 이양주 팀장입니다.  그래서 과제를 누가 할 것인가가 결정되지 않은 상태에서 이양주 박사가 과제수행 여부를, 이 과제는 이러이러해서 우리 연구원의, 193번으로 봐서 이정훈 박사가 수행하는 것이 타당할 것 같다.  그래서 이정훈 박사의 전문분야영역하고 이 과제 내용하고 안건을 올려서 이것이 가결돼서, 그러면 148차에서 결정된 내용은 이 과제를 수행한다라고 하는 것 하고 이 과제에 대한 연구책임자는 이정훈 박사다.  그렇게 결정이 됐을 겁니다.  제가 자료는 보지 않았지만.  그러면 과제가 이정훈 박사가 수행하는 것으로 결정된 것이 148쪽이고요.  그러면 기획조정실에서 연구위원회 심의결과가 이러니까 개인한테 통보가 됐습니다.  그러면 이정훈 박사는 그 통보된 내용을 가지고 그렇다면 이 연구를 나는 앞으로 어떻게 수행하겠다, 연구기간하고…….
</p>
<p><b>○ 장윤영 위원 </b> 지금 하나 가지고 너무 긴데, 실질적으로 이거 자체는 이름이 바뀌지만 부결의 사이하고 가결의 사이를 단적으로 질의하겠습니다.  바로 246페이지 한번 봐주시겠습니까?  173번하고 177번이요.  똑같은 심의ㆍ의결 내용이 같습니다.  제목도 같습니다.  그 다음에 기안자도 같습니다.  그런데 날짜가 하루 차이입니다.  하루 차이에서 부결됐던 게 다음 날 가결됐거든요.  이런 경우가 있습니까?  
</p>
<p><b>○ 기획조정실장 이상훈 </b> 이 내용으로 봐서는 173차에 부결된 이유가 아마 우리 과제 중에 일부 외부 위탁 나가는, 부분위탁부문에 대해서 아마 그런 건에 조건을 달아서 부결을 시켰습니다.  그래서 그러한 내용을 다시 조정해서 재상정이 돼서 177번이 변경된 내용으로 통과된 것으로, 이 자료상으로 보면 그렇게 해석이 됩니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 1차 연구위원회에서 부적격하다고 몇 가지를 지적 받았겠죠.  그것을 가지고 그 다음에 연구자가 다시 고쳐서 다시 상정해서 통과되었다고…….
</p>
<p><b>○ 장윤영 위원 </b> 문제 자체는 지금 하루 사이입니다.  9월 7일 열려서 부결되었던 게 9월 8일 가결되거든요.  그래서 연구위원회라는 게 어떤 거냐는 겁니다.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 연구위원회는 통상 1주일에 한 번씩 간부회의를 한 그날 간부회의가 끝나고, 부서장 회의가 끝난 이후에 심의위원들을 통해서 연구위원회가 개최됩니다.  그리고 그 이외 특정한 사안이 발생했을 때 연구과제 건에 대해서 별도로 추가적으로 긴급하게 처리해 주어야 될 상황이 있을 때 다시 소집해서, 이것은 언제든지 소집이 가능한 위원회 건이 되겠습니다.  그러니까 예를 들어서 173차가 이런 이유를 들어서 조건부로 부결이 되어서 이것은 고쳐라 해서 하루 만에 수정이 되어서 그 다음날 개최해서 통과시킨 그런 건이 되겠습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 잘은 모르겠습니다만 하루 만에 하는 경우라면 당일 회의에서 있지 않습니까?  형식에 너무 얽매이면 안 된다는 거죠.  그러니까 오늘 부결이 났는데 내일 가결하기 위해서 회의를 또다시 중복하는 것이 아니라 그 자리에서 문제가 되었으면 수정가결시킬 수 있는 여지는 없습니까?  회의를 또 열어야만 되느냐라는 거죠.  
</p>
<p><b>○ 기획조정실장 이상훈 </b> 여기에 나온 내용으로 봐서 부분위탁이기 때문에, 연구과제 전체 내용 중에 일부를 우리가 외부에 발주하는 내용이기 때문에, 계약에 관한 사항이기 때문에 이것은 연구위원회에서 심의해서 의결해 주어야 될 사안으로 판단됩니다. 
</p>
<p><b>○ 장윤영 위원 </b> 186번 한번만 봐 주시겠습니까?  이것은 186, 187 둘로 나뉘어져야 될 사항인지 아니면 동일한 사항인지, 매향리 사격장의 활용방안 및 타당성 분석용역하고 두 번째 한 칸에 들어가 있는 것 있지 않습니까?  이게 상관되는 용역입니까, 서로 별개의 겁니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 서로 별개의 것입니다.  서로 별개의 것인데 위원회에 연구심의는 하나로 올렸지만 과제수행 여부를 안건 1, 안건 2 이렇게 해서 두 개가 통과되었다는 그런 표현으로.  그래서 차수는 186차는 연구위원회에 올릴 때마다 차수가 변경이 되기 때문에 차수변경은 없고 다만 그 안에 있는 내용 중에서 두 개 과제 건에 대해서 수탁여부, 수탁과제에 대한 과제수행 여부가 가결된 것으로 해석이 됩니다. 
</p>
<p><b>○ 장윤영 위원 </b> 마무리질의 하겠습니다.  수탁과제 같은 경우 이것은 분명히 연구용역비가 경기개발연구원에 들어오는 거죠?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 그렇습니다.
</p>
<p><b>○ 장윤영 위원 </b> 그렇다라고 한다면 수탁과제에 관한 한 경기개발연구원에서 특별한 사유가 없는 한 수용을 해 주어야만 재정자립도라든지 여러 면에서, 늘 문제되는 수익에 영향을 받을 텐데 254하고 255페이지 보면 똑같은 게 있습니다.  25-1번 하고21-1번.  수탁인데 “통일시대를 대비한 연천군 발전구상수립용역” 이것은 지역적으로 나 경기도 측면에서나 타당한 사항이라고 보여지고요.  이런 부분인데 두 번 다 부결이 났거든요.  이것에 대해서는 간략하게 설명이 가능하시겠습니까?  수탁사업임에도 불구하고 필요한 사업이라고 판단되는데 두 번 상정해서 두 번 다 부결 난 것은…….
</p>
<p><b>○ 기획조정실장 이상훈 </b> 이 건은 사실 위원님이 질의하신 재정자립도라든지 여러 상황으로 봐서 모든 과제를 다 수탁으로 의뢰하는 경우에는 오케이를 놔야 되겠죠.  그렇지만 저희는 그렇게 생각합니다.  경기개발연구원에 의뢰하는 수탁과제 다 수용하면 저희 재정자립도 100% 됩니다.  그러나 상당히 많은 과제들이 소위 얘기해서 연구원의 연구방향과 맞지 않는 부분들이 있고요.  그 다음에 제한된 연구원, 한정된 연구원이 있습니다.  53명이지만 그 중에서 외부에 파견된 인력도 있고 제한된 인력 가지고 하고 있고 그 다음에 경우에 따라서는 연구내용이 저희 연구진에서 수행하기가 어려운 내용들도 때로는 있습니다.  그래서 연구위원회에서 그런 부분들을 종합적으로 판단해서 그것은 연구책임자가 적당하지 않다.  또 이 연구는 우리가 아니어도 제3의 기관이…….
</p>
<p><b>○ 장윤영 위원 </b> 잠깐만요.  그것은 포괄적인 답변이시고요.  분명히 두 번이나 상정시켰다는 이유는 연천군에 굉장히 애달픈 사연이 있을 것 같습니다.  
</p>
<p><b>○ 기획조정실장 이상훈 </b> 연구원에서 그 연구책임자를 결정하는 과정에서 연천군 장기발전계획이다 보니까 종합계획이고 한데 우리 정치학 박사가 수행하다 보니까 그 문제에 대해서 이것은 정치학 박사가 이 문제를 해결하는 것이 낫냐 아니면 다른 전공 분야인 사람이 하느냐 하는 이런 문제 가지고 논의하다가 부결되고 그렇습니다.  이 과제는 그 이후에 연구진 편성을 보완하는 조건으로 해서 통과되었습니다.  그래서 현재 수행하고 있습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 그러면 여기서 참고적으로 오늘 보고한 내용으로 제가 질의를 마무리하고자 합니다.  보고서 11페이지 있지 않습니까?  수탁연구과제요.  지금 관심 있게 보고 있는 것은 수탁연구과제거든요.  조금 전에 말씀드렸지만 수탁연구물의 경우는 연구용역비가 있고 보통 계약 당시에 선급금을 받게 되죠?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네, 그렇습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 보통 3억원 이하짜리 경우는 50%, 10억 이상 같은 경우는 20% 내외의 선급금을 받는 것이 관행입니까, 아니면 정해져 있는 겁니까?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 그것은 계약요건에 의해서 우리가 신청하기 때문에.
</p>
<p><b>○ 장윤영 위원 </b> 그런데 과제가 중지되었을 때는 어떻게 됩니까? 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 중지되었을 때는 해당 기관의 회계부서하고 경기개발연구원의 회계부서하고 그동안의 연구결과물, 진행되었던 인건비를 각 항목별로 정산을 해서 우리 연구원에서 해당기관의 회계과에 통보하고 협의해서 결정하게 됩니다.  그래서 정산하게 됩니다. 
</p>
<p><b>○ 장윤영 위원 </b> 여기서 질의를 마치는데 지금 2005년도에서 중지된 사업이 2개가 있습니다.  정산내역을 지금 바로 자료요청하면서 질의마치도록 하겠습니다. 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 위원님, 죄송합니다.  2005년도에 그러니까 7번하고 8번 보고자료, 남양주시하고 시흥시 건이 되겠습니까? 
</p>
<p><b>○ 장윤영 위원 </b> 2005년도에 중지된 사례 있지 않습니까?  수탁연구과제 있지 않습니까?  이정훈 박사님인지.  17번하고 26번이요.  가평군. 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 이 건은 주로 연구기간에 대한 조정입니다.  과제중지 사유가 예를 들어서 관광개발계획 같은 경우 법정 계획이다 보니까 법정 계획이 결정되기 전에 이 보고서가 나왔을 때 어떤 상충되는 문제가 있기 때문에 법정 계획이 결정된 이후라든지 그런 법정 계획을 결정하는 과정에서 기간조정 내용 때문에 하던 것을 중단하는 것이지 이것을 중간에 아예 철회하는 그런 과제는 아니었습니다.  두 과제 다 기간을 일정기간 이후까지 중지하고 기다려 달라 그런 내용이었습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 저는 일단 내용을 모르니까 자료요청했던 것은 2005년도 분 2개에 대해서 연구용역비와 관련해서 선급금 받은 것 있을 것이고 그 다음에 기간에 따라서는 중간 기성으로 받은 게 있을 겁니다.  중지가 되었기 때문에 어떻게 되었는지 이 두 가지 사업에 대해서 용역비에 대한 정산내용을 자료요청한 것입니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다.  17번, 26번에 대해서 정산내용을 위원님께 보고올리도록 하겠습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 장 위원님 끝나셨습니까?  수고하셨습니다.  보충질의 계십니까?  보충질의 없으면 이해문 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이해문 위원 </b> 과천 출신 이해문 위원입니다.  이번 감사준비 하느라고 애 많이 쓰셨고 오전에 제가 요구한 자료를 잘 제출해 주셔서 감사합니다.  우리 동료 위원 여러분에게도 자리에 놔 드린 연도별 도비지원 현황, 연도별 이월금 현황, 잉여금처분계산서, 예비비 예산집행 현황 이 자료도 아울러 본 위원이 질의하면서 같이 참조 좀 해 주시기 바랍니다.  원장님!  원장으로 취임하시고 여러 가지 업무파악 또 오전에 답변을 잘 들었습니다만 많은 부분에 대해서 관심 있게 많이 준비하셨는데 본 위원은 경기개발연구원의 재정과 관련해서, 특히 이월잉여금과 기금에 대해서 질의하려고 합니다.  원장님께서도 이 부분은 연구원을 운영하면서 총 책임자로 되어 있으시고 또 이 분야에도 관심 있게 봐 주십사하는 그런 의미에서 원장님께서 아시는 대로 답변해 주시고요.  나중에 세부적이고 조금 구체적인 것은 담당으로 하여금 답변을 듣도록 하겠습니다.  괜찮으시겠습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 이해문 위원 </b> 먼저 경기개발연구원에서 그동안 기금을 적립하면서 애를 많이 썼습니다.  경기도에서 그동안 출연을 쭉 해서 기금을 확보해 왔고 또 시ㆍ군에서도, 일부 금융기관에서도 기금을 준비해서 현재 기금이 272억원이죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니다.
</p>
<p><b>○ 이해문 위원 </b> 그래서 많은 기금을 확보했습니다.  그런데 본 위원이 생각하기에는, 지금 IMF 이후에 이자율이 많이 떨어졌죠?  그래서 기금의 이자를 활용해서도 일부 도움이 되고 있습니다만 경기도에서도 도비지원을 계속 받고 있죠?  출연금 형태로 계속 지원을 받고 있습니다.  그런데 지금 작년도 2005 회계연도의 결산을 하면서 결산보고서에 따르면 잉여금 처분을 할 때 15억원의 기금으로 금년 이사회에서 결의를 한 바 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이해문 위원 </b> 결의를 하면서 혹시 이사회 회의록을 보셨습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 상세히는 못 봤습니다만 약간의 얘기는 듣고…….
</p>
<p><b>○ 이해문 위원 </b> 내용은 알고 계시죠?  여기서 제출해 주신 행정사무감사 자료에 보면 이 부분이 자세하게 기록이 되어 있습니다.  그래서 이 부분에 대해서 원장님께서 아신다고 그러니까 388페이지 기금적립에 대한 회의록 중에 황준기 그 당시 기획관리실장도 여기 이사로 되어 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 기획관리실장이 당연직 이사로 되어 있습니다. 
</p>
<p><b>○ 이해문 위원 </b> 여기 회의록에 보면 황준기 그 당시 이사, 기획관리실장께서 기금을 적립하는 방식과 절차가 옳지 않다는 의견을 냈습니다.  회의록 388페이지에 보면 자세히 나와 있습니다.  본 위원이 생각하기에도 기금적립과 관련해서는, 물론 기금을 적립해서 목적사업에 부합하는 사업도 할 수가 있습니다만 그러나 이월금 처리에 있어서는 다소 문제가 있다고 생각되는데 이 문제에 대해서 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 연구원 입장에서는 위원님들이 그동안 계속 질의를 주셨습니다만 기금이 많이 쌓이면 금리가 다소 적더라도 연구원 자립에 많이 도움이 된다고 생각합니다.  그리고 연구원 측에서는 그런 입장을 견지하지 않을까 생각이 들어서 2005년에 쓰던 불용액을 어떻게 할 거냐.  인건비라든가 연구비가 거기 다 포함이 될 텐데요.  그걸 가지고 논쟁이 된 게 아닌가 싶습니다.  그래서 어떻게 보면 그것을 다음 해 예산으로 포함시켜서 계속 연구를 더 하고 필요한 인력은 더 확충하는 것도 한 가지 방법이겠지만 만일 이번처럼 2005년에 시작된 정책연구센터가 2006년에 문을 닫는 그런 상황에서는 그 분야의 추가적인 연구수요가 있다고 보기는 어렵지 않을까 그래서 이 돈을 연구원 기금으로 환입하는 것이 좋겠다고 하는 의견을 연구원 쪽에서 낸 게 아닌가하는 그런 생각이 듭니다.  그러나 법적으로는 제가 보기에는 아까 확인해 봤습니다만 정관이나 이런 면에서 문제가 있다고 생각되지 않지만 사전에 기금적립을 위해서 할당되지 않은 그런 예산을 기금으로 할당한 것에 대해서는 다소 문제제기를 할 수 있지 않을까 하는 생각도 듭니다. 
</p>
<p><b>○ 이해문 위원 </b> 원장님, 그래서 여기 정관 11조에 보면 잉여금 처리에 대한 규정이 나와 있습니다.  그동안에 여기에 잉여금이 남으면 전년도 이월손실을 보전하고 또 잔여가 있을 때는 이월하거나 기금으로 적립할 수 있다는 이 규정을 말씀하시는 거죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.  그렇습니다.
</p>
<p><b>○ 이해문 위원 </b> 본 위원이 그동안의 자료를 쭉 체크해 보니까 한 번도 결손 난 적이 없었죠?  설립 이후에.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 이해문 위원 </b> 원장님도 자료 가지고 계시죠?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 가지고 있습니다.
</p>
<p><b>○ 이해문 위원 </b> 오전에 요구한 자료를 보시면 ’95년도에 설립해서 2006년까지 매년 이월금이 발생했고요.  그 다음에 잉여금을 처분함에 있어서 그것을 재원으로 해서 ’97년부터 쭉 2004년까지 기금으로 확보했죠?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다.
</p>
<p><b>○ 이해문 위원 </b> 그런데 2005년에도 약 51억 9,000만원의 이월금이 생겼는데 2005년도에는 왜 기금을 잉여금 처리하면서 확보를 못했습니까?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이것은 그 당시에 연구원 이사님들이 이렇게 결정해 주셨기 때문에 그런 것이 아닌가 싶은데요.  제가 답변드리기가 어렵다는 생각이…….
</p>
<p><b>○ 이해문 위원 </b> 원장님, 2005년도에는 기금적립이 없었어요.  그리고 2006년도에 와서, 2006년도는 사실 2005회계연도입니다.  이 때 결산하면서 이월금이 무려 54억원이 나왔어요.  이것을 가지고 기금을 15억 적립했습니다.  그런데 이것도 사실은 54억의 순세계잉여금 중에 2006년도로 지출예산에 반영한 것이 약 29억입니다.  그리고도 남은 것이 25억이에요.  그러면 제가 볼 때는 꼭 이렇게 기금을 확보한다 그러면 더 많은 기금도 확보할 수 있었는데 마찬가지로 2004년도에도 차인잔액이 34억이나 났거든요.  그런데 그때 분위기에 따라서 한다는 것도 맞지 않고요.  또 기금이란 것이 경기도에서 매년 출연되고 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니다. 
</p>
<p><b>○ 이해문 위원 </b> 2006년도에도 88억을 도에서 지원받았죠?  도비지원금이.  그것이 출연금 형식이지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 이해문 위원 </b> 물론 내년도 예산에 올린 자료에 보니까 104억을 요구했더라고요.  중기재정계획에도 계속해서 110억 이상씩 향후 5년 동안 이렇게 반영이 되어 있고요.  이런 것을 봐서 정책적으로 이월금을 가지고 기금으로 일부 하는 것이 앞으로 한번 연구해 봐야 될 대상이라고 생각하는데요.  왜냐하면 기금에 대한 이자도 많지도 않고 또 정관에 보면 목적사업이 분명히 나와 있거든요.  여기 경기개발연구원이 기금을 자체로 약 1,000억 정도 모은다면 몰라도 그렇지 않다면 이 목적사업에 경기도와 관련해서 다 사업을 하도록 되어 있거든요.  중요한 목적사업이.  그렇다면 굳이 이월한 그 내용도 지금 더 구체적으로 말씀드리면 기업회계 기준에 의해서 회계를 하도록 되어 있습니다.  알고 계시죠?  복식부기에 의해서 정관이나 재무회계규정에 의하면 기업회계 규정에 따르도록 되어 있거든요.  그래서 요구한 자료에 의해서 감사도 하고 외부감사도 받고 이렇게 하게 되어 있습니다만 실제로 여기에서 논의되는 것은 예산회계에 의해서 다 움직이고 있어요.  우리에게 제출된 자료라든지 여기에서 일어나는 것들은, 설명하는 것들은.  그렇다면 굳이 이렇게 기금 때문에 궁색할 필요가 없고 또 이월된 것들을 가지고 충분히 경기개발연구원의 발전을 위해서 연구도 하고 아까 동료 위원님들께서 오전에 질의가 있었습니다만 충분히 연구원 발전을 위해서 쓸 수 있는 재원인데도 불구하고 왜 기금으로 자꾸 묶으려고 하는지.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 말씀올리겠습니다.  2005년, 2006년.  2005년에는 기금전입이 없었다 하는 지적에 대해서 저는 그렇게 생각합니다.  이게 일관성이 없어 보이기는 합니다.  그리고 기금을 확보하고자 하면 연구원에서 장기적으로 기금확보 비전을 만들어 놓고, 우선 그러려면 기금의 필요성에 대해서 공감대가 형성되어야 되겠지만 그런 장기계획을 가지고 꾸준하게 연차적으로 그런 계획에 따라서 기금으로 전입하는 것이 옳은 일이 아니었느냐 하는 생각이 들지만 어쨌든 이 당시에 이런 결정이 있었던 것에 대해서는 제가 사후적으로 내용을 파악하기도 어려울 뿐만 아니라 제가 코멘트 하는 게 적절치 않다는 생각이 들고요.  그러나 기금문제 전반에 대해서는, 도에서 저희 연구원에 재정을 잘 지원하고 서로 도정에 대한 연구를 저희가 뒷받침하는 관행이 앞으로 잘 갈 수 있으면 사실 기금이 없더라도 될 수 있다고 생각하지만 저는 이 문제에 대해서 당장 어떤 가부간에, 앞으로 기금적립을 안 하는 것이 좋겠다는 답변을 드리기는 대단히 자신이 없습니다.  고민을 좀 더 해 보고 연구원의 장기재원확보 방안을 한번 연구를 해서 큰 그림 속에서 답변을 드려야지 제가 섣불리 답변을 드리게 되지 않을까 하는 그런 생각이 듭니다.
</p>
<p><b>○ 이해문 위원 </b> 알겠습니다.  그래서 기금 문제는 또 다른 분들의 의견이 있을 수 있고 하니까 줄이고요.  이것이 금년에도 10월까지 나와 있는 제출해 주신 회계장부를 보면 또 많은 위험이 발생하게 되어 있어요.  그래서 똑같은 것을 또 반복해야 되거든요.  그래서 제가 질의를 드렸습니다.  연구해 보시고요.  
</p>
<p style="padding-left:1.2em">  그 다음에 지금 경기개발연구원이 소유하고 있는 건물이 있죠?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 녹지재단이 활용하고 있는…….
</p>
<p><b>○ 이해문 위원 </b> 경기도자료관으로 지금 쓰고 있는 건물이 있죠?  여기에 무상으로 주고 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니다. 
</p>
<p><b>○ 이해문 위원 </b> 2007년 6월이면 계약기간이 끝나는데 앞으로 연구원이 소유하고 있는 건물을 달리 활용할 수 있는 방법을 검토해 본 적은 없습니까?  예를 들면 지금 여기에 있는 현재 쓰고 있는 이 건물도 임대되어 있죠?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 임대라기보다 무상으로 활용하고 있습니다, 운영비는 같이 부담하지만.
</p>
<p><b>○ 이해문 위원 </b> 그래서 장부에 보면 토지와 건물도 가지고 있고 감가상각도 매년 하고 있고요.  정액법으로.  그 다음에 경기도자료관으로 현재 무상으로 임대를 주고 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다.
</p>
<p><b>○ 이해문 위원 </b> 그 다음 여기는 임차해 쓰고 있고요.  그래서 이런 문제와 관련해서 여기도 연구하시는 인원도 자꾸 늘어나고 앞으로 비전도 있을 텐데 연구실도 부족한 것 같고 그래서 혹시 이 건물의 활용, 자체건물을 매각한다든지 하고 지금 쓰고 있는 장소를 다른 장소로 옮긴다든지 하는 계획은 가지고 있지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 온 다음에 따로 이 문제에 대해서 고민을 못했습니다만 과거에 어떤 논의가 있었는지, 제가 보기에는 위원님 질의가 아주 적절한 질의라고 생각되는데요.  오늘 기금문제도 그렇고 연구원 장래문제에 대한 질의가 아닌가 싶어서 감사 끝나면 바로 연구원의 독립적인 오피스빌딩을 확보하는 문제까지 포함해서 구상해서 다음번에 기획위원회에 보고올리도록 저한테 기회를 주시면 좋겠다는 생각이 듭니다.
</p>
<p><b>○ 이해문 위원 </b> 알겠습니다.  그것은 그렇게 연구하신다니까 자료가 나오는 대로 상의를 좀 해 주시고요.  끝으로 하나만 더 말씀드리겠습니다.  지금 여기에 공인회계사 감사를 받고 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 외부감사를 받고 있습니다.
</p>
<p><b>○ 이해문 위원 </b> 정관에도 보면 지금 두 사람의 감사를 선임하도록 되어 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 이해문 위원 </b> 그리고 세무회계규정과 감사규정에도 보면 감사가 감사를 하도록 되어 있죠?  그런데 실제로 여기 감사 두 분이 감사합니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 당연직 감사로 도의 감사관이 감사를 하고 있어서 결산감사는 정기적으로 받고 있다고 보고받고 있고요.  제2의 감사는 저희가 아직 임명을 하지 않고 있습니다.  그러나 회계결과를 외부 공인회계사한테 외부감사를 통해서 저희 회계의 정확성을 높이기 위해서 노력하고 있습니다. 
</p>
<p><b>○ 이해문 위원 </b> 감사 두 사람이 다 선임되어 있는 것으로 자료에 나와 있는데.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 비상임으로 한 분 있습니다. 
</p>
<p><b>○ 이해문 위원 </b> 물론 감사는 다 비상임이지 않습니까?  그래서 본 위원이 자료를 검토해 보니까 실제적으로 도의 감사관하고 외부에서 이사회에 선임된 감사 두 사람이 감사를 하고 또 외부의 공인회계사의 감사를 받도록 되어 있거든요.  맞죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 맞습니다. 
</p>
<p><b>○ 이해문 위원 </b> 도에 제출할 때는 외부에 있는 공인회계사 감사를 받은 감사결과와 감사증빙서를 제출하도록 되어 있는데 현재 여기 시스템을 보니까 실제적으로 이런 비상근 감사들이 감사를 한 내용들이 별로 없고요.  또 여기에서 재정관계를 외부에 용역을 주어서 회계처리라든지 이런 것에 대해서 자문을 받고 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그 사항은 제가 확인을 해야 되겠는데요.  특별히 자문 받는 것은 없습니다.  외부 자문 받는 것은 없고 비상임으로 있는 감사가 이사회 때 결산결과를 보고하고 있다고 합니다. 
</p>
<p><b>○ 이해문 위원 </b> 그러면 결산 때 이사회 기록을 보면 감사가 의견을 “적정하다.” 그 표현뿐이 없어요.  감사보고에서 뒤에 보면 “적정하다.”는 사인만 있고요.  그런데 여기에 쭉 보면 대행해서 감사를 실시하고 있거든요.  감사대행을 해서 실시하고 있어요, 돈을 주고.  제가 요지를 설명드릴게요.  왜 그러냐면 원장님도 아셔야 되기 때문에 그렇습니다.  담당직원들 설명보다는 원장님이 이 규정을 아셔야 되거든요.  자체로 회계를 해서 재무제표가 나오면 기업회계 기준으로 하게 되어 있어요.  그런데 전부 여기에 보고되는 것은 예산회계에 의해서만 하고 있거든요.  그런데 기업회계 기준에 의해서 감사를 내부감사를 하고 그 다음에 감사한 내용을 또 이사회에 보고하고 한편으로 외부의 공인회계사 감사를 받아서 도지사에게 제출하게 되어 있습니다.  그런데 감사대행기관으로 지정된 이 회계사가 여기 감사를 해서 그것을 보고 내부감사가 이사회에 보고하는 것으로 자료에 나와 있고요.  그 다음에 도에 제출한 자료는 감사대행기관에서 실시한 그 공인회계사가 낸 보고서를 마치 공인회계사 감사, 다른 데에다 한 것처럼 그 보고서를 또 도지사한테 내고 있어요.  그래서 이것은 감사를 대행한 기관이 공인회계사가 또 자기가 감사한 것을 공인회계사라고 해서 하는 것은 어떤 흐름에 맞지 않다고 본 위원은 생각하거든요.  투명성이란 것, 왜 그것을 하겠습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 위원님 관심은 한 공인회계사한테 받은 감사결과를 가지고 이사회에 보고할 뿐만 아니라 동시에 그것을 도에 외부감사 결과라고 해서 보고하는 것이 어떻게 보면 제2의 공인회계사 감사를 통해서 상호 점검하고 하는 그런 시스템을 생각한다면 문제가 있을 수 있다.
</p>
<p><b>○ 이해문 위원 </b> 잘 지적하셨습니다.  그래서 제가 여쭤보는 거예요.  내부감사들에게 감사비용 주고 있습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 비상임 감사에 해당하는 비용을 지급하고 있는 것으로 알고 있습니다. 
</p>
<p><b>○ 이해문 위원 </b> 네?  주고 있다고요?  그거 근거 있으면 제출해 주시고요.  그 다음에 아까 대행감사했는데 감사비용이 있지요.  담당자 계시면 비용이 얼마 나갔습니까, 작년도에.  감사대행 실시한 기관.  담당자가 답변해 주세요, 원장님 잘 모르시는 것 같으니까.
</p>
<p><b>○ 재정지원과장 강윤구 </b> 재정과장 강윤구입니다.  2005년도의 감사비용으로는 440만원을 집행했습니다. 
</p>
<p><b>○ 이해문 위원 </b> 이것은 누구한테 지출한 겁니까?  공인회계사 앞으로 지출됩니다, 계약에 의해서.  공인회계사라는 것은 여기에 임승빈 감사도 있고 정규환 감사도 공인회계사고요.  그 다음에 김문환 공인회계사도 있고.  여기 자료 제출했기 때문에 실명을 거론하겠습니다.  어느 공인회계사한테 440만원을 주는 겁니까? 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 감사를 대행해 주는 김문환 공인회계사한테 지급되고 있습니다.  
</p>
<p><b>○ 이해문 위원 </b> 그러면 나중에 도에다 재무제표 감사받은 것을 제출하게 돼 있지요, 도지사에게.
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 그렇습니다.
</p>
<p><b>○ 이해문 위원 </b> 그것은 또 어느 보고서를 제출합니까?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 저희가 이사회에서 의결받은 결산서를 제출하고 있습니다.  
</p>
<p><b>○ 이해문 위원 </b> 도지사한테 제출할 때는 재무제표와 그 부속서류, 공인회계사 감사증명서를 제출하게 돼 있지요?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 그렇습니다.
</p>
<p><b>○ 이해문 위원 </b> 이때 공인회계사 감사증명서는 누구한테 받습니까?  
</p>
<p><b>○ 재정지원과장 강윤구 </b> 공인회계사는 회계에 대한 적정성을 검사하는 국가에서 자격증을 교부한 분으로서 그 분의 실인이 찍힌 의견서는 제출하도록 돼 있기 때문에 그것을 제출하고 있습니다. 
</p>
<p><b>○ 이해문 위원 </b> 그것을 감사증명서로 대신한다는 것 아니에요, 감사보고서를?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 그렇습니다.
</p>
<p><b>○ 이해문 위원 </b> 그런데 본 위원이 질의한 요지는 이때 440만원을 주고 감사대행을 실시한 공인회계사가 대행했다는 얘기 아닙니까? 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 그렇습니다.  한 분은 연구원의 공인회계 선임직 감사시고 한 분은 공인회계사를 업으로 하시는 분이고.
</p>
<p><b>○ 이해문 위원 </b> 정리를 해보면, 잘 들어보세요.  흐름이 이렇습니다.  내부감사가 두 사람 있지요?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이해문 위원 </b> 본 위원이 볼 때 내부감사는 전혀 감사를 안 하는 것 같아요.  그런 증명자료가 감사계획에 의해서 감사계획서를 내게 돼 있어요, 내부감사가.  감사계획서 냈습니까? 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 저희 회계 쪽 결산감사에 대해서는 계획서를 세워서 사전에 결재를 받아서 대행감사를 받고 있습니다만 일상적인 업무감사는 비상임감사로서 하지 않고 있습니다. 
</p>
<p><b>○ 이해문 위원 </b> 감사규정에 의해서는 감사를 하게 돼 있잖아요?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 그렇습니다.  저희 정관의 감사규정에는…….
</p>
<p><b>○ 이해문 위원 </b> 그래서 본 위원이 생각할 때는, 왜냐하면 여기는 막대한 예산을 다루고 도민의 세금이 들어가고 이러는데 이 흐름이, 물론 연구원이기 때문에 중요한 논문이라든지 경기도가 원하는 정책적인 그런 목적사업도 중요하지만 여기에 도민의 세금이 들어가는 이 돈도 잘 관리해야 될 책무가 있거든요.  원장님, 그렇지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 옳은 말씀입니다.
</p>
<p><b>○ 이해문 위원 </b> 그래서 자체적으로 감사도 선임하는 거고요.  그 다음에 내부감사가 지금 업무를 충실히 할 게 없다고 해서 감사대행을 실시해요, 돈을 주고.  그렇지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 이해문 위원 </b> 그래서 보고서를 또 만들었어요.  그러면 도지사가 원하는 감사보고서는 또 다른 공인회계사의 감사보고서를 제출하라는 의미인데 감사대행한 사람이, 다시 말해 이 보고서를 만들어준 사람이 거기에 도장 찍으면 그것을 도지사한테 낸다고 하면 그것은 감사를 제3자인 김문환 공인회계사는 감사대행기관으로 감사한 거지 공인회계사협회에서 이것을 감사한 것이라고는 보지 않거든요.  그래서 이런 것은 문제가 있다고 본 위원은 지적합니다.  왜냐하면 이 내용들이 기업회계기준에 의해서 다 하게 돼 있어요.  그래서 검토한 자료에 의하면, 또 여기서 설명해 주신 내용들, 아까 잉여금 처리하는 문제도 마찬가지입니다.  그게 예산회계에 의해서 하다보니까 누적돼서 오는 거고요.  기업회계기준에 의한다면 바로바로 떨어야 돼요.  그렇지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 이해문 위원 </b> 또 수탁사업해서 수익이 들어왔어요.  수탁사업해서 수익이 들어왔으면 이익이 돼서 처분해야 되는데, 여기에 혹시 사업자등록증 원장님 보셨습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아직 못 봤습니다. 
</p>
<p><b>○ 이해문 위원 </b> 본 위원한테 제출한 사업자등록증에 보면 이게 비영리법인으로 해서 사업자번호가 번호만 있는 거거든요.  그래서 수익사업을 하게 되면 다시 사업자를 내야 됩니다.  그런데 어떤 면에서는 수탁사업도 수익사업의 일부로 볼 수 있거든요.  그래서 만약에 어떤 것이 세무서의 문제가 된다면 한꺼번에 굉장히 많은 추징을 당할 수 있다고 생각되는데 이런 문제와 관련해서 검토해 보셨어요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아직 못했습니다. 
</p>
<p><b>○ 이해문 위원 </b> 알겠습니다.  나중에 시간 있으면 다시 보충질의하도록 하고요.  이상 시간돼서 질의 마치겠습니다.  이상입니다.
</p>
<p><b>○ 위원장 김영복 </b> 이해문 위원님 수고하셨습니다.  보충질의 있습니까?  정인영 위원님 보충질의해 주시기 바랍니다. 
</p>
<p><b>○ 정인영 위원 </b> 정인영 위원입니다.  존경하는 이해문 위원님께서 기금문제하고 여러 가지 심도있게 질의를 해 주셨는데 저는 기금전입과 관련해서 보충질의를 하겠습니다.  2006년 3월 22일 경기개발연구원 제48차 임시 이사회를 했습니다.  당시에는 제가 6대 의회 후반기 기획위원장으로서 경기개발연구원 당연직이사였습니다.  그런데 참 불행하게도 그 당시가 7대 의회 선거기간은 아니었지만 선거를 준비하는 기간이었기 때문에 제가 참석을 못했습니다.  그런데 중대한 하자가 발생됐다고 생각했기 때문에 보충질의를 드리는 것입니다. 
</p>
<p style="padding-left:1.2em">  정관 11조 규정에 의하면 “매 회계연도에 잉여금은 전년도 이월손실을 보전하고 또 잔여가 있을 때에는 다음 회계연도로 이월하거나 기금으로 전입한다.” 이렇게 돼 있습니다.  알고 계시지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 정인영 위원 </b> 그런데 문제는 15억을 기금으로 전입한 재원은 잉여금이 아니라고 하는 것입니다.  잉여금은 회사의 순재산액이 자본액을 초과한 부분을 잉여금이라고 얘기합니다.  복잡하게 얘기하지 않고 쉽게 얘기하면 남는 돈입니다.  그러나 그 남는 돈이 사업을 집행하고 남은 돈이냐 미집행 잔액이냐 이것을 구분하셔야 됩니다.  그런데 그 15억을 기금으로 전입한 재원을 보면 미집행 인건비 13억하고 미집행 연구비 26억입니다.  그러니까 이것은 잉여금으로 볼 수가 없는 거지요.  그 부분에 대해서 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 동감입니다.
</p>
<p><b>○ 정인영 위원 </b> 잉여금으로 볼 수 없는데도 불구하고 정관 11조 규정을 들어서 “잉여금은 기금으로 전입한다.”라고 하는 이 조항을 활용해서 전입을 했다고 하는 겁니다.  이것은 중대한 하자입니다.  차라리 그때 미집행 인건비 13억은 어떻게 해석을 해야 되냐면 2006년도에 인원 10명을 채용했지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 
</p>
<p><b>○ 정인영 위원 </b> 그러면 미집행 인건비 13억을 이월했으면 지금 집행되는 겁니다.  집행을 자연스럽게 할 수 있는데 그것을 못하니까 2007년도에 104억의 출연금을 또 경기도에 요청한 것 아닙니까?  이게 문제가 있습니다.  그래서 이것은 잉여금으로 볼 수 없고 연구용역비용을, 미집행 연구비를 26억인데 이것도 잉여금으로 보고 그 중에 일부를 기금으로 전입한 거지요.  그러니까 잉여금이라고 하면 사업을 하고 남은 잔액을 얘기하는 겁니다.  예를 들어서 100만원의 예산을 세워서 수탁을 해서 90만원만 지출했을 때 나머지 10만원이 잉여금이 되는데 그 집행 자체를 안 하고 그것을 잉여금으로 본 것입니다.  거기에 문제가 있는 겁니다.  그래서 이사회에서 감액처리를 했어야 된다고 본 위원은 생각을 하고, 물론 기금을 활용해서 경기개발연구원이 자립하는 데 도움이 된다고 하겠지만 예산을 사용하지 않고 그것을 기금으로 넣는다면 그거 누가 못하겠습니까?  다 할 수 있지요.  그래서 이 부분은 2007년도 예산안을 다룰 때 위원님들께서 심도있게 다루어 주시리라고 봅니다만 이것은 분명히 정관 11조 규정을 인용한 그런 기금전입이 아니고 예산집행 상의 중대한 하자다 이렇게 본 위원은 지적합니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 
</p>
<p><b>○ 정인영 위원 </b> 여기에 대해서 답변하실 사항 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 특별한 사항 없습니다. 
</p>
<p><b>○ 정인영 위원 </b> 그렇기 때문에 이 부분은 위원님들과 심도있게 다시 검토해서 2007년도 예산을 다룰 때 충분히 고려해서 예산심의를 해야 될 사항이라고 보면서 보충질의를 마치겠습니다.  이상입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 한 말씀 더 올려도 괜찮겠습니까? 
</p>
<p><b>○ 정인영 위원 </b> 네, 답변하시지요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 정인영 위원님 말씀, 이해문 위원님 말씀을 듣고 나서 제가 여러 가지 새롭게 깨달은 점이 있습니다.  결국은 저희가 연구계획을 세워놓고 충실하게 집행을 못한 데 문제가 있는 게 아닌가 싶습니다, 모든 문제의 근원이.  그래서 차후에는 불용액이 생기지 않도록 계획대로 연구가 잘 되도록 하고 보다 적극적으로 연구를 많이 하는 그런 방향으로 노력해서 이런 문제가 다시 안 생기도록 노력하겠습니다.  이번 예산에 대해서도 특별히 잘 배려해 주시기를 부탁드리겠습니다.
</p>
<p><b>○ 정인영 위원 </b> 사실은 명시이월을 했었어야 되는 그런 부분인데도 불구하고 이것을 잉여금 처리를 했다고 하는 것은 문제가 있는 거고요.  그리고 사실 지금 경기도 재정도 굉장히 어렵지 않습니까?  그래서 기금을 활용하는 데 있어서 목적을 가지고 그 기금을 활용해야 되는데 물론 금리도 싸고 해서 지금 경기도에서도 통합관리기금조례를 만들어서 기금을 갖다가 예산에 활용하는 그러한 사례들이 있습니다.  이런데도 불구하고 이런 정관 제11조 규정을 잘못 원용해서 기금으로 전입시킨 것은 문제가 있다고 보는 거고요.  그리고 경기도가 재원이 상당히 어렵고 2007년도 예산을 세우는 데 있어서도 굉장히 힘든 부분들이 많았었기 때문에 특별히 지금 도비 지원현황을 보면 민선3기에 들어와서 대폭적으로 도비지원금이 됐습니다.  2006년도에는 100억을 요청했는데 12억을 삭감해서 88억원을 도비지원했고 2005년도에는 97억 이렇게 했습니다만 도비지원에 의존하는 퍼센티지가 2006년도에는 53%, 2005년도에는 56%, 2004년도에는 65%까지 올라갑니다.  앞으로 경기개발연구원이 자체 재원을 확보할 수 있는, 수익을 낼 수 있는 그러한 연구를 통해서 자립하고 독립할 수 있는 그런 연구원이 되기를 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 명심하겠습니다. 
</p>
<p><b>○ 정인영 위원 </b> 향후 이러한 사례는 발생하지 않도록 해야 되겠습니다.  이상입니다.
</p>
<p><b>○ 위원장 김영복 </b> 정인영 위원님 수고하셨습니다.  보충질의하실 위원님 계십니까?  임우영 위원님 보충질의해 주시기 바랍니다.  
</p>
<p><b>○ 임우영 위원 </b> 임우영 위원입니다.  한 가지만 여쭤보겠습니다.  수탁용역사업에서 현재까지 용역사업을 완료하고 났는데 아직 비용을 회수 못한 미수금의 현황이 어떻게 됩니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 완료한 사업은 없다고 합니다.
</p>
<p><b>○ 임우영 위원 </b> 계속 용역하는 것에 대해서는 미수금액이 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇지요.  완결되면 용역관계도 다 완결처리가 되기 때문에 미수금이 남을 수가 없다고 봅니다. 
</p>
<p><b>○ 임우영 위원 </b> 그래서 아까 정인영 위원님하고 이해문 부위원장님께서도 말씀을 하셨지만, 제가 이사회 회의록을 요구해서 보니까 여러분들이 내주신 결산서, 결산을 하는 결산서가 우선 잘못 의회에 보고된 것 아닌가.  저는 이번이 처음이기 때문에 그렇게 생각할 수밖에 없습니다.  뭐냐 하면 여기 아까 이해문 부위원장님 이야기하신 388페이지에 보면 황준기 이사가 뭐라고 이야기를 했냐면 “지난 2005년, 2006년도 예산을 하는 과정에서 경기개발연구원에 대해서 도의회 상임위원회에서나 이런 문제가 걸러질 수 있었을 텐데” 하는 그런 이야기를 했어요.  여러분들이 이렇게 잉여금으로, 미집행금액을 잉여금으로 잡지 않고 불용액으로 잡았다면, 아니면 명시이월을 해줘서 잡았다면 분명히 이런 부분들이 벌써 의회 심의과정에서 충분히 거론이 되고 여러 가지 예산이나 결산에 반영이 됐을 텐데 여러분이 그것을, 이런 표현을 쓰면 뭐합니다만 결산에 대한 해석 잘못, 어떻게 불용액하고 미집행액에 대한 잉여금하고의, 그것은 있을 수 없는 일입니다.  특히 결산을, 회계를 보는 분들이 이것을 모를 리가 없거든요.  이런 부분은 회계하시는 분이 회계학을 전공하신 분 맞지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 회계전문가로 알고 있습니다. 
</p>
<p><b>○ 임우영 위원 </b> 얘기가 안 되는 거지요.  분명히 이사회에서 이사들이 문제제기를 했으면 그 부분에 대해서 한 번쯤은 더 검토를 해서 제대로 처리되도록 했어야 옳지 않나 저는 그런 문제를 지적합니다.  다시 한 번 미집행금을, 불용액을 잉여금으로 해서 기금으로 전용하는 이런 일이 다시는 일어나지 않도록, 원장님 새로 오셨으니까 전반적으로 연구과제도 물론이겠지만 연구원 운영과 관련해서 이런 부분도 꼭 챙겨보셔야 되겠다 하는 생각을 합니다.  또 하나, 이것은 질의가 되니까 나중에 다시 질의하겠습니다.  이상입니다.
</p>
<p><b>○ 위원장 김영복 </b> 임우영 위원님 수고하셨습니다.  보충질의하실 위원, 전동석 위원님 보충질의해 주시기 바랍니다. 
</p>
<p><b>○ 전동석 위원 </b> 전동석 위원입니다.  기금 관련해서 보충질의입니다.  실제로 경기개발연구원의 기금운용현황을 보면 이사회 기금관리위원회 결정사항으로 진행되지만 사실 다른 것은 연구를 하면서도 이 기금 관련해서만은 유독 너무 허술하지 않나 이런 생각을 해봅니다.  꼭 규정을 들지 않더라도 실제로 이 기금에 대해서 일반 예산처럼, 일반 기금, 다른 기금들을 보면 거기에 대해서 승인을 받고 결재를 받고 또 일반 기금처럼 하는데 여기서는 좀 달리 해결하지 않느냐 이런 생각이 들어서 말씀드리는데요.  기금관리위원회에서 심의승인을 받습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다. 
</p>
<p><b>○ 전동석 위원 </b> 그리고 기금운영계획을 수정해서 연말에 또 심의하고 이사회 의결을 받기도 하고요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저희 담당과장에게 답변을 대신 부탁해도 되겠습니까?
</p>
<p><b>○ 전동석 위원 </b> 그렇게 하시지요.
</p>
<p><b>○ 재정지원과장 강윤구 </b> 재정과장 강윤구입니다.  저희가 기금의 운용계획을 받는 게 아니고 기금의 운용실적을 기금관리규정에 의해서 이사회에 보고해서 승인을 받도록 돼 있습니다.  현재까지도 그렇게 받고 있습니다. 
</p>
<p><b>○ 전동석 위원 </b> 그렇습니까?  지금은 이사회의 승인의결을 받지 않고, 기금관리위원회의 심의를 받지 않고 처리하고 있는 것은 아닙니까?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 그렇지 않습니다. 
</p>
<p><b>○ 전동석 위원 </b> 그렇지 않습니까? 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네.
</p>
<p><b>○ 전동석 위원 </b> 제 생각에는 일반 기금으로 일반 예산처럼 심의를 받지 않기 때문에 그런 현상이 일어나지 않았나 생각해서 그렇습니다.  아까 15억에 대해서 그렇게 기금으로 넣은 것은 많은 위원님들이 그런 지적을 하셨는데요.  그런 과정을 거치지 않아서였지 않았나 이런 생각이 들었고요.  그리고 많이 생각한 다음에 처리해 주셨으면 좋겠다는 생각이 듭니다. 
</p>
<p style="padding-left:1.2em">  15억 관련해서는 아까도 지적했지만 도의 재정도 사실 긴축재정이 많거든요.  긴축재정이 많이 되고 있는데 그 도비를 다음에 104억이라는 것을 신청하면서도 그거에 대해서 또 자기의 어떤 몸집만 불려나가는 그런 차원이 아닌가 생각해서 말씀드리는 건데요.  그렇지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그것은 우리 강 과장이 답변하기가 어렵지 않은가 싶은데요.  기금으로 해서 연구원이 특별하게 이득을 본다기보다 장기적으로 결국 도민의 돈이 아니겠습니까?  저희가 저축해 놓고 거기서 나오는 이자를 가지고 쓰겠다고 하는, 어떻게 보면 좋은 뜻인데 도정의 어려움, 요즘 금리의 문제 이런 여러 가지를 감안해 볼 때 기금에 너무 의존하는 전략이 옳지 않느냐 하는 위원님들의 지적에 대해서는 저희가 다시 한 번 검토하고 숙고해서 저희 연구원 예산 확보방안에 대해서 한 번 더 고민을 하도록 하겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 네, 알겠습니다.  기금의 운용 및 관리를 보면 실제로 모든 돈을 은행에다 넣고, 물론 규정에 의해서 그때 이율이 가장 높은 데 넣고 하는 규정은 있습니다.  그런데 그것을 제가 쭉 제출한 자료를 살펴보면 전체적인 생각은 ‘야, 정말 가만히 앉아서 입을 열고 있는 그런 상황이 아닌가.’ 이런 생각이 들어서 말씀드리고요.  규정에 보면 기타방법으로 수익을, 이게 이자만 받는 것이 아니라 다른 방법으로도 가능하지 않느냐 하는 내용이 있던데요.  다른 방법은 생각해 보지 않았습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 오전에도 그런 질의가 있으셨습니다만 저희가 수탁과제를 받을 때 오버헤드(Over Head)로 떼는 돈도 저희 연구원 예산으로 충당이 되는 것이고요.  우리 도서판매대금도 할 수 있기 때문에 위원님들 걱정하시는 재정문제, 도의 재정문제의 어려움 이런 것을 다 감안해서 저희도 최대한 긴축하고 질의하신 그런 방향으로 기금을 운용하고 예산을 운영하는 그런 노력을 경주해 나가도록 하겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 제 생각에는 경기개발연구원이 다른 분야에 대해서는 굉장히 개발하고 연구하고 해서 좋은 방안을 내놓는데 유독 이 기금에 대해서는 그냥 이자만 계속 받아서 운영하는 그런 시스템을 가지고 있는 게 아닌가 이런 생각이 들어서 그렇습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 기금이야말로 가장 안전한 데에 투자하는 게 원칙이라고 저는 생각합니다.  그렇다고 저희가 부동산투자를 할 수도 없는 것이고 증권투자를 하면 그거야말로 정말 위험부담이 높기 때문에 금리가 낮음에도 불구하고 그렇게 밖에 할 수 없는 것은 제가 보기에 위원님들께서 조금 이해를 해 주셔야 되지 않을까 하는 그런 생각이 듭니다.  좌우간 어쨌든 기금에 너무 의존하는 행태, 이것은 저희가 앞으로 반성하고 새로운 활로를 찾도록 노력하겠다는 약속을 드리겠습니다. 
</p>
<p><b>○ 전동석 위원 </b> 바로 그 점 때문에 제가 말씀을 드렸는데요.  너무 의존해서 또 도의 출연금만 의지해서 하는 게 너무 나타나지 않는가 해서 앞으로도 그런 부분에 대해서 연구해서 실제로 경기개발연구원이 더 좋은 방향으로 나갈 수 있으면 좋겠습니다.  보충질의 마치겠습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 감사합니다.
</p>
<p><b>○ 위원장 김영복 </b> 전동석 위원님 수고하셨습니다.  보충질의하실 위원님.
</p>
<p><b>○ 임우영 위원 </b> 보충질의가 아니고요.  우리 원장님께서 아까 말씀하시는 중에 저희가 이 문제를 제기한 것이 우리 경기개발연구원의 기금을 조성하는 것을 문제 삼은 게 아닙니다.  분명히 알아두셔야 될 것은 불용액을 잉여금으로 처리했다는 거예요.  불용액과 잉여금을 구별 못 하면 안 된다 이 점을 분명하게 지적하는 거지 기금을 조성, 기금 조성하는 거야 개발연구원에서야 당연히 기금조성 해야 되겠지요, 방법이 있으면.  그게 아니고 불용액처리해야 될 미집행 인건비나 미집행 연구과제비 이런 것을 잉여금으로 처리했다는 데 문제가 있다는 거예요.  그것은 분명히 알아두시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아까 정인영 위원님도 같은 질의를 하셔서 제가 동감한다는 말씀을 드렸다시피 그 점에 대해서는 제가 더 이상 드릴 말씀이 없습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 질의하실 위원님 계십니까?  조선미 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 조선미 위원 </b> 고양시 출신 조선미 위원입니다.  장시간 고생 많으십니다.  경기개발연구원의 금년도 연구사업 중에 기본연구하고 정책연구과제를 살펴보면 모두 93건입니다.  앞으로 도와 시ㆍ군에서 의뢰한 것 75건 정도가 추가될 것으로 생각됩니다.  지금까지 한 주요 연구과제 중에서 문화와 관광분야에는 한 15개 정도로 돼 있는데 이중에서 경기도 지역축제하고 관련된 연구과제가 포함되어 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지역축제와 관련된 연구가 있었느냐는 질의신가요?
</p>
<p><b>○ 조선미 위원 </b> 네. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 경제사회연구부장께서 대신 답변하도록 양해해 주시면…….
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 경사부장 김군수입니다.  제가 구체적인 것은 잘 알지 못합니다만 지금까지 경기도의 지역축제와 관련된 과제는 우선 도자기엑스포와 관련된 과제가 3건 있었습니다.  그 다음에 올해 제4차 경기관광개발계획 속에 지역축제와 관련된 계획을 수립하였습니다. 
</p>
<p><b>○ 조선미 위원 </b> 수립결과서가 나왔습니까?
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 네, 보고서는 나와 있습니다. 
</p>
<p><b>○ 조선미 위원 </b> 기본과제입니까? 
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 수탁과제입니다.
</p>
<p><b>○ 조선미 위원 </b> 수탁과제는 여러 가지가 있었습니다.  그런데 지금 제가 질의하려고 하는 것은 저희 경기도와 31개 시ㆍ군에 있는 축제가 106개가 개최되고 있습니다.  그리고 개최할 예정으로 있습니다.  이렇다 보니까 대부분의 행사들이 지역특성과 정체성이 명확하지가 않습니다.  그냥 단체장의 홍보용 행사로 전락하고 있다는 시민단체들의 지적도 있고 도민의 혈세를 낭비하는 대표적인 전시행정의 표본이라는 반발을 사고 있습니다.  지난 2004년도 감사원 감사 결과에 경기도 내 각 시ㆍ군에서 추진 중인 축제들이 인접한 지역에 유사 중복성 지역축제가 많아 예산낭비실태가 심각하다는 지적도 받은 바 있습니다.  본 위원이 말씀드리고자 하는 것은 지역의 중복성 축제에 대한 문제점을 경기개발연구원이 세밀히 검토하고 분석해서 시민의 혈세를 지켜내고 올바른 지역축제의 방향을 제시하는 연구가 필요하다고 봅니다.  이러한 연구야말로 특색있는 지역축제로 자리 잡을 수 있는 지침서가 될 수 있다고 생각하는데 여기에 대해서는 어떻게 생각하십니까? 
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 담당부장으로서 의견을 말씀드리겠습니다.  먼저 도 축제가 상당히 많이 있습니다만 개별 축제에 대한 연구는 하지 않았습니다.  그러나 각 축제들의 종합적인 브랜드나 정체성에 관련된 연구는 지금까지 계속 해왔습니다.  그러나 지금 위원님이 말씀하신 축제들의 중복성 문제, 예산낭비 문제 이런 문제에 대해서는 지금까지 연구를 안 해봤기 때문에 담당자하고 협의해서 계획을 세우도록 노력하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 보충답변을 드리겠습니다.  대단히 적절한 지적이 아니신가 싶습니다.  그래서 저희 연구원에서 도내에 진행되고 있는 각종 축제를 종합적으로 한번 보고 중복성이라든가 이런 것들을 한번 정리하는 그런 연구를 하나 수행하도록 하겠습니다. 
</p>
<p><b>○ 조선미 위원 </b> 지금 예산낭비를 막기 위해서는 지역축제에 대한 통폐합이 이루어 져야 할 것 같습니다.  하나의 좋은 예로 경기문화재단에서 주최하는 실학축전하고 남양주문화재단이 주최하는 다산문화제를 지금 통합, 현재 협의 중에 있습니다.  이것은 도비 6억, 그 다음에 다산문화제 같은 경우에는 시비 1억 2,000만원으로 진행되고 있던 겁니다.  이런 것들을 지금 통합하려는 움직임이 있는데요.  지역별 특성을 살린 이런 시기나 날짜를 맞추어서 패키지 관광상품이나 유사한 축제들을 통폐합한 다음에 관광상품으로서의 여건을 갖춘 관광상품으로 만든 사례를 연구개발하여서 모델로 제시함으로써 아까 우리 장윤영 위원님도 말했지만 31개 시ㆍ군과 1,100만 경기도민의 싱크탱크인 경기개발연구원을 활용하는 계기로 삼았으면 하는데 이번에 그것을 기본연구과제로 하시든지 아니면 정책연구과제로 해서 31개 시ㆍ군뿐만 아니라 경기도민에게 주목받은 그런 연구원으로 거듭나는 계기가 되었으면 합니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다.  명심하겠고요.  사실은 관광을 담당하는 전문연구박사가 와 있는데 조금 답변을 추가로 하는 게 좋겠습니까?
</p>
<p><b>○ 조선미 위원 </b> 전체적으로 한번 기본수탁과제나 정책연구로 기획하고 있는 것이 있는지 말씀해 주시면 감사하겠습니다. 
</p>
<p><b>○ 경제사회연구부책임연구원 이정훈 </b> 경제사회연구부의 이정훈입니다.  문화관광 쪽 연구를 담당하고 있습니다.  위원님께서 말씀하시는 부분 잘 들었고요.  굉장히 정확하게 현황을 파악하고 계시고 그런 필요성, 지역축제를 더 전략적이고 핵심적인 것으로 줄여나가면서 경기도의 대표적인 지역성을 부각해야 될 필요성에 대해서는 저도 또 우리 연구원에서 상당히 많이 느끼고 있고요.  또 일부 시ㆍ군에서는 그런 움직임들이 조금씩 있습니다.  그래서 예를 들어서 제가 양주시하고 한번 그냥 과제를, 연구과제를 한 것은 아니고요.  양주시 축제를 어떻게 정리해 보고자 하는 컨설팅을 했었는데요.  15개 정도의 축제가 있었습니다.  그래서 그것을 대표축제를 중심으로 세 개로 묶는 안을 제출한 바 있는데 그 과정에서 지금 위원님께서 말씀하신 그런 하나로, 경기도의 지역축제 전체를 대상으로 해서 연구과제를 하는 게 대단히 방대한 작업이기 때문에 기본과제나 정책과제로 당장 수행을 해서 어떤 효과를 얻기가 그렇게 쉬운 작업은 아닙니다.  양주의 예를 조금 더 말씀드리면 지역마다 읍ㆍ면ㆍ동에서 행하는 축제도 있고 또 시에서 하는 대표축제가 있습니다.  그래서 그런 축제들을 지역상황마다 하나하나 고려해서 순위를 매겨줘야 되고 전략적인 우선순위들을 고려해 주어야 되기 때문에 샘플로 몇 개 정도의 축제, 아까 위원님께서 말씀하신 실학축전이라든가 도자축제라든가 이런 몇 개 정도의 축제를 샘플로 해서 모델들을 만들어 보는 것은 빠른 시일 안에 한번 시도를 해 볼 수 있겠습니다만 31개 시ㆍ군 전체를 100여개가 넘는 축제를 평가하고 하기에는 조금 더 시간이 많이 걸리는 작업이라고 생각하고요.  저희들이 그런 전체적인 현황들을 조금 더 파악해서 정리할 수 있는 그런 조금 더 장기적인 관점에서 과제를 만들어 내는 게 좋겠다고 저는 생각을 하고 있습니다. 
