<p><b>○ 조선미 위원 </b> 네.  지금 이것을 기본수탁과제로 삼은 것은 경기도에서 관광인프라를 구축해서 민간이 오게 하려고 하는데 지역축제들이 다 관광을 목적으로 누군가가 찾아와서 우리 지역을 봐주었으면 하는 게 축제의 기본이거든요.  그래서 이런 것들이 이루어졌으면 좋겠다.  보니까 경기문화재단하고 경기관광공사에서 수탁하신 과제들이 있으시잖아요.  그런 것들을 함께 인접지역을 같이 묶어서 하면 좋겠다.  지금 고양시 같은 경우 고양시, 파주는 11건씩이나 축제들이 있습니다.  이런 인접한 지역의 유사한 축제들을 묶어서 관광상품으로 개발해 내는 그런 수탁이 있었으면 좋겠다, 기본과제로 아니면 연구과제로 했으면 좋겠다 이런 생각인데 하여튼 진지한 논의 후에 좋은 결과로 한번 저한테 대면답변해 주시기 바랍니다. 
