<p><b>○ 조선미 위원 </b> 마지막으로 한 가지만 더 말씀드리겠습니다.  지난 10월 17일 경기통계청이 2005년도 인구주택 총조사 표본집계결과 자료를 살펴보니까 5년 전 거주지를 기준으로 다른 시ㆍ도에서 경기도로 유입한 인구는 무려 178만 7,000명으로 2000년도에 비해서 10만 7,000명이 증가한 것으로 조사되었습니다.  지역별로 살펴볼 때 서울이 105만 8,000명으로 전체 유입인구의 59.7%로 가장 높습니다.  지금 인구가 유입된 이후에 경기도에서 인구만 유입되지 통학인구를 조사해 보니까 경기도 내 12세 이상 인구 가운데 통학ㆍ통근인구는 530만 6,000명으로 2000년에 비해서 17.9%가 증가했으며 통근ㆍ통학률은 62.6%에 달했습니다.  그러나 경기도는 증가하는 인구유입에 대한 대책마련이 부족한 상태일 뿐만 아니라 인구유입에 따른 늘어나는 차량으로 인한 교통체증, 경제적 낭비, 교통대란이 예상되고 있는 가운데 여기에 대한 다양한 연구가 시급하다고 보는데 어떻게 생각하십니까? 
