<p><b>○ 경기개발연구원장 좌승희 </b> 우선은 교통문제는 지금 지사님도 가장 중점사업으로 “뚫리는 경기” 해 가지고 교통체증 완화 프로젝트를 하고 있고요.  저희 연구원의 교통연구부의 많은 박사들이 도청하고 협력해서 현재 도청에 가서 근무하고 있고요. 다른 일자리 문제라든가 이런 것들은 다른 국가정책하고 수도권 규제문제하고 다 연결이 되어 있어서 유입인구에 대한 대책을 마련하는데 경기도가 가지고 있는 정책수단이 많지 않다는 생각을 합니다.  아시다시피 인구가 경기도가 대한민국 일등이죠.  1,100만 가까이 되는데, 기업체 수도 경기도가 제일 많지만 사실은 1인당 GRDP로 보면 경기도가 대한민국 여덟 번째밖에 안 되기 때문에 일자리 창출에 한계가 있는 상황이라서 그래서 저희 연구원에서 수도권규제 철폐라든가 기업입지규제 철폐 등과 같은 수도권 경쟁력 강화를 위한 연구를 하고 있는 것이고요.  그런 다각도의 방법을 통해서 일자리를 만들어 내고 동시에 교통체증을 막을 수 있는 교통시스템을 개선하는, 수도권의 전반적인 교통효율성을 높일 수 있는 방향으로 도와 더불어 저희가 노력하고 있습니다.  답이 되었는지 모르겠습니다만. 
