<p><b>○ 조선미 위원 </b> 가장 심각한 것은 금방 말씀하신 것처럼 일자리가 있어야지만 아무래도 통학인구를 줄일 수 있고 그 다음에 통학을 하게 된다면 지금 경기도 내에 있는 뉴타운 개발하고 신도시 건설이 지속적으로 추진되고 있지 않습니까?  그 가운데 실제로 SOC 확충에는 미흡한 추진을 보이고 있습니다.  도로, 문화, 생활 여러 가지 문제들.  특히 경기북부 같은 경우에는 대학이 들어올 수 없음으로 인해서 일어나는 통학문제 이런 것들이 있는데, 이런 경기북부지역은 좀더 열악한데 그런 것에 대한 전반적인 연구가 시급하다고 생각합니다. 
