<p><b>○ 전동석 위원 </b> 신 부원장님의 “2005년 GRI 비전과 전략 연구”를 제가 보니까 11월 30일까지 마무리되는 것으로 되어 있었는데 한번 여쭤보니까 한 6개월 늦어졌더라고 요.  여기에 보면 기본연구의 결과가 도출되면 기획위원회에 별도 보고를 통하여서 얘기를 하고 협조하겠다고 말씀하셨는데 앞으로 여기에도 실제로 그 사례만 그렇게 하는 것이 아니라 연구한 것이, 사실 저도 그렇습니다.  보내준 책자들을 시간이 없어서 거의 못 볼 정도로 쌓아두고 있는 것이 많습니다.  그런 차원에서 더 접근해야 되지 않나 하는 생각이 듭니다.  연구과제에 대해서 버려둔다면 그게 전부 혈세인데요.  그래서 신 원장님 하실 때 그 부분에 대해서 좀더 명확하게 연구결과가 어떻게 적용되었는가 하는 것을 객관적으로 증명할 수 있는 것을 포함시켜주었으면 좋겠습니다. 
