<p><b>○ 경기개발연구원장 좌승희 </b> 일부 연구에 대해서는 저희가 수요처의 느낌, 연구결과에 대한 평가를 받고 있다고 제가 듣고 있습니다.  발주처의 평가를 잘 받고 그래서 자화자찬 같습니다만 상당히 수요자들이 높게 평가하고 있다는 보고를 제가 들었습니다.
