<p><b>○ 전동석 위원 </b> 감사합니다.  저는 포괄적인 질의만 몇 개 했는데요.  실제로 일반적으로 생각하면 연구기관이 내 일이다 생각하고 최선을 다하는 길이 가장 중요하다고 생각합니다.  그런 차원에서 제가 원장님을 존경하고 잘 하시리라고 생각되는데 쭉 정리하다 보니까 이미 다 질의된 사항도 많고 보충질의를 통해서 많이 답을 얻었기 때문에 질의를 이것으로 마치도록 하겠습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 전동석 위원님 수고하셨습니다.  보충질의하실 위원 계십니까?  보충질의가 안 계시면 질의하실 위원님, 장윤영 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 장윤영 위원 </b> 인사말은 생략하도록 하겠습니다.  조금 전에 굉장히 위험한 발언을 하셨습니다.  기조실장님께서 임창열 지사 시절에 도 정책을 결정함에 있어서 경기개발연구원들 박사님들의 자문이 없이는 결정이 어려웠다는 말씀을 하셨습니다.  그러면 제일 중요한 것입니다.  손학규 지사 시절과 김문수 지사 시절에는 어떻습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그게 공식적으로 꼭 연구원의 결재를 받으라는 얘기는 아니었던 것 아닌가 싶고요.  연구원의 의견을 적극적으로 참조하도록 노력하라는 그런 취지로 해석을 해야 되지 않을까 싶은데요.
</p>
<p><b>○ 장윤영 위원 </b> 이것은…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이것은 기조실장 보고 말씀을…….
</p>
<p><b>○ 장윤영 위원 </b> 이것은 해명이 아니라 일단, 기조실장님!  그 부분에 대해서 그렇다고 한다면 민선2기를 말씀하셨습니다. 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 그 부분에 대해서는 제가 실수를 한 것 같습니다.  저는 강조하느라고, 위원님들께서 이해하기 쉬우시도록 거론했는데 부적절한 표현이었던 것  같습니다.  그 정도로 연구원의 의견과 검토의견을 중요하게 생각했다 이 표현으로 이해해 주시면 감사하겠습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 지금 이게 바로 그러다보니까 어떻게 보면 오늘 감사의 핵심이 될 것 같습니다.  민선2기에는 경기개발연구원의 위상이 한없이 높았다는 겁니다.  그런데 경기개발연구원의 위상이 민선3기, 민선4기 대표적인 것을 말씀드리겠습니다.  대표적인 말씀을 드리는 게 뭐냐면 오늘 여러분들이 주요업무보고 28쪽을 보게 되면 느낄 수가 있습니다.  기본연구과제 안에 있는 26가지 있지 않습니까?  여기서 보면 바로 김문수 지사의 주요핵심과제가 대부분 빠져있습니다.  이게 2007년도 바로 연구원의 고유 설립목적입니다.  결국은 경기도하고 경기개발연구원하고 엇박자로 가고 있다고 하는 그런 증거가 될 수도 있다고 보여집니다.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 말씀을 우선 드리고 미진하면 기조실장한테 답변을 더 요청하겠습니다.
</p>
<p style="padding-left:1.2em">  우선은 이게 2007년 내년도 과제인데 아까도 말씀드렸지만 각 부서에서 민선4기 4대 과제, 지금 제가 다 열거를 금방 못하겠습니다만 그것에 대해서 수도권정책센터가 적극적으로 그것을 다루기 위해서 생긴 것이고 이것은 기본연구과제라고 해서 개인이 자기 연구 커리어를 계속 이어나가기 위해서 하는 소위 깊이 있는 주제를 다루는 약간은 아카데믹한 연구라고 볼 수 있고요.  정책연구는 정책연구대로 계속 다 진행되고 있습니다.  그래서 수도권정책센터가 생긴 이유가 바로 김문수 지사의 4대 추진시책을 다루기 위해서 생긴 것이고 아까도 말씀드렸지만 교통연구부는 사실 교통 원활화를 위해서 지금 도에 나가서 근무를 하다시피 하고 있고 그래서 오해가 없었으면 좋겠다는 생각이 듭니다.
</p>
<p><b>○ 장윤영 위원 </b> 원장님, 말씀 잘 들었습니다.  중요한 것은 자료를 통해서 말씀을 주시기 바랍니다.  조금 전에 제가 오전에 보충질의를 통해서 기조실장님의 말씀을 들었습니다만 저는 자료를 가지고 말씀을 드렸고요.  실장님하고 연구원 측에서는, 죄송합니다.  입으로 말씀해 주셨습니다.  그러다보니까 이 시간만을 넘기자라고 하는, 표현이 적절치 못하지만 구태의연한, 어쩌면 이 감사자리를 통해서 감사의 결과로써 경기개발연구원이 한층 더 성숙하고 진짜 경기도의 싱크탱크로 자리 잡을 수 있는 계기가 될 수도 있을 겁니다.  제일 중요한 겁니다.  부족함과 잘못을 인정하게 되면 시정이 가능합니다만 인정이 안 됐을 때는 발전할 수 없습니다.  그래서 조금 전에 원장님 말씀하셨습니다.  제일 중요한 부분 중에 하나가 교통부분입니다.  그런데 내년도의 계획이 컴퓨터를 활용한 전화교통조사시스템 도입 연구입니다.  시민사회에서 요구하는 것인지 아니면 정책부서에서 요구하는 것인지 아니면 미래비전산업 중에 하나인지 잘 모르겠습니다.  그리고 “김문수 도지사” 하면 연관되는 것이 바로 “맑은 물 대책”입니다.  “팔당상수원 보호”입니다.  26개 과제 중에서 유사한 과제 자체가 없습니다.  그래서 본 위원이 이번 행정사무감사에서 요청한 자료가 좀 생뚱맞을 것이라고 판단이 될 겁니다.  연구원 주관 각종 세미나와 워크숍 현황이었습니다.  왜 이 자료를 요청했는지 아십니까?  여러분들이 정책연구과제, 그 다음에 기본연구과제 선정을 위해서 얼마만큼 현장의 소리를 듣는가라고 하는 것을 간접적으로 파악하기 위해서 이 자료를 요구했습니다만 이것은 의견을 수렴하는 자리가 아니라는 것이 자료를 통해서 나타났습니다.
</p>
<p style="padding-left:1.2em">  중복연구과제, 왜 요청했는지 아십니까?  바로 여러분들이 이것은 연결이 돼야 된다고 보여집니다.  대표적으로 2006년도 과제는 지금 홈페이지에 올라와 있지 않습니다.  그런데 바로 전년도 과제에 대해서는 새로운 산업의 핵심인 디지털 컨버전스에 대한 연구부분이 있습니다.  그런데 금년도 과제하고 정책과제, 내년도 과제 속에서 핵심이 되는 디지털 컨버전스의 계속되는 연속성이 없어져 버렸습니다.
</p>
<p style="padding-left:1.2em">  그렇게 하고 왜 한ㆍ미FTA 관련 자체 보고서와 용역보고서를 얘기했느냐.  한ㆍ미FTA로 인해서 경기도 지역이 가장 피해를 받는 것이 뭐냐, 바로 농업관련입니다.  쌀 시장이 8% 개방돼 버렸습니다.  앞으로 계속 늘어날 겁니다.  미래를 위한 연구내역이 없습니다.  참고적으로 말씀을 드리겠습니다.  경기도는 매년 민선지사가 TV에 나옵니다, G마크라는 것을 가지고요.  아마 브랜드파워에 대해서는 굳이 말씀드리지 않아도, 그 중요성은 강조하지 않아도 잘 알 것 같습니다.  그런데 중요한 것은 경기도 공무원이, 농정국 직원이, 경기개발연구원이 G마크가 뭔지 모릅니다.  여러분의 구내식당과 경기도청의 구내식당에서 G마크가 박힌 쌀 먹지 않습니다.  경기도에서 가장 많이 팔리는 이천의 임금님표 쌀이 G마크 붙어있지 않습니다.  지금은 품질을 개선시켜야 됩니다.  경쟁력 강화시켜야 됩니다.  바로 그런 부분에 대해서 시장을 제대로 봐달라는 겁니다.  그래서 여러분들한테 말씀을 드리고자 하는 겁니다.  바로 오늘 보고자료 28페이지, 아까 쉬는 시간에 잠깐 말씀드렸지만 중장기 연구 로드맵에 의해서 2007년도의 연구과제가 선정됐다, 인정하려고 했습니다.  중장기 연구 로드맵 있습니까, 실장님?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 네, 지금 수립 중에 있습니다.  
</p>
<p><b>○ 장윤영 위원 </b> 그렇다고 한다면 바로 28페이지 상단에 있는 부분은 잘못 기재된 거지요?
</p>
<p><b>○ 기획조정실장 이상훈 </b> 그렇지 않습니다.  중장기 로드맵이라는 게 그동안 전혀 이런 과정이 없었던 게 아니고 2006년도까지 GRI 비전계획이 있었습니다.  그 계획에 의해서 지금까지 추진됐고 다음 연결되는 로드맵이 아직 미완성단계이고요.  그 다음에 위원님 지적하신 내용에 대해서는 상당부분 인정합니다.  그렇지만 오늘 감사가 그냥 일시적으로 넘기기 위해서, 지금 연구과제가 어차피 일시적으로 끝나는 사업들이 아니기 때문에 전혀 그런 생각은 없고요.  그리고 2007년도 기본연구과제에 왜 4대 현안내용들이 없느냐고 했는데 이것은 2007년도부터, 앞에서 우리 평가에 대한 지적도 있었지만 현안문제 중심으로 박사들이 쫓아다니다 보니까 논리라든지 각종 이론이나 이런 부분에 대해서 취약한 점이 논문을 게재한다든지 이런 부분에 나타나고 있습니다.  그래서 2007년도 기본연구과제, 거기 보시면 다 아카데믹한 내용 같지만 실질적으로 결국은 경기도 현안문제 관련된 것입니다.  이런 부분에 대해서 집중적으로 연구를 하고 이것이 기본연구과제입니다.  이것만큼은 아카데믹한 최소한의 상황을 유지하자.  그리고 그 이후에 오른쪽 29페이지 보시면 정책연구과제 71과제가 지금 제목이 안 정해진 상태에서 기다리고 있습니다.  이것은…….
</p>
<p><b>○ 장윤영 위원 </b> 잠깐만요.  말씀 끊겠습니다.  다시 한 번 말씀드리는데 정책연구과제는 우리 경기개발연구원에 나와 있는 풀예산을 활용해서 도의 결정권이 여러분한테 있습니까?  아니면 정책기획관실이라든지 도에 주도권이 있습니까?  
</p>
<p><b>○ 기획조정실장 이상훈 </b> 경기개발연구원에서 결정합니다.  다만 정책연구과제는 도에서 의뢰를 할 때 정책기획관실의 창구를 통해서 스크린을 한번 점검받고 그 다음에 연구원에 의뢰를 하는 그런 과제들로 구성돼 있습니다.
</p>
<p><b>○ 장윤영 위원 </b> 다시 한 번 말씀드리겠습니다.  본 연구원의 고유사업인 기본연구과제가 여러분의 고유사업입니다.  기본연구과제 속에서 경기개발연구원의 존립근거가 나옵니다.  그래서 원장님께 질의를 먼저 드리겠습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 보충으로 답을 드릴까요?
</p>
<p><b>○ 장윤영 위원 </b> 우선 질의를, 분명히 휴식시간에 말씀드렸지만 중장기 연구 로드맵이 있어도 문제입니다.  중요한 것은 세상이 어떻게 변할지 모릅니다.  우리가 과연 북한의 핵실험을 예측할 수 있었습니까?  한ㆍ미FTA가 연내에 끝난다, 예상할 수 있습니까?  예상하지 못하는 상태에서 여러분들이 바로 6층에, 원장실이 있는 중간에 뭐라고 써 있냐면 “경기개발연구원은 도정의 중장기 비전제시입니다.  정책개발을 지원합니다.” 그런데 이 연구에서 중장기 로드맵에 의해서 연구과제가 선정된다고 하면 현실감, 비전제시가 아니라 연구를 위한 연구가 될 수도 있다는 겁니다.  그런 면에 있어서 제목을 자세히 뜯어봤습니다.  조금 전에 말씀드렸지만 자료를 봤습니다.  자료를 요청한 이유가 2005년의 소속 연구원의 연구목록과 FTA관련 목록과 세미나 내용을 봤었던 겁니다.
</p>
<p style="padding-left:1.2em">  그래서 원장님께 질의하겠습니다.  김문수 지사께서 시장경제주의자이신, 자유경제주의자이신 우리 좌승희 원장님을 원장님으로 모셨던 가장 커다란 이유는 앞으로 경기도의 미래는 경제에 있다라고 하는 아마 깊은 뜻이 담겨 있을 것이라고 보여집니다.  내년도의 26개 기본연구과제 중에서 원장님의 의지가 반영된 과제가 있으면 말씀주시고요.  부탁을 드리겠습니다.  답변은 간단하게 해 주시기 바랍니다.  우선 26개 과제 중에서 원장님의 의지가 반영돼서 채택된 과제가 있으면 말씀주시기 바랍니다.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우선 기본과제를 선정하는 프로세스를 좀 설명 올리겠습니다.  각 연구자가 자기 연구 커리어를 앞으로 어떻게 가져갈지에 대한 개인적인 플랜이 다 있지요.  그런 것을 기초해서 자기 연구베이스를 넓히기 위한 연구이기 때문에 이 연구의 첫 번째 이니시에이터(initiator)는 연구자입니다.  그런데 그 내용을 어떤 형식으로 하고 이게 정말 적합하냐, 아니냐 하는 것은 연구원에서 전 과제에 대해 세미나를 통해서 점검을 다 했습니다.  그런데 여기서 장 위원님이 알아두셔야 할 것은 기본과제는 정책을 연구하고자 하는 과제가 아닙니다.  그러니까 지금 김문수 지사님이 내걸고 있는 정책방향이라든가 이런 것을 우리가 정책과제에 통해서 해결하는 것이기 때문에 죄송하지만 지금 제가 보고드린 자료 14페이지를 보시면 정책과제에 2006년 신규과제라고 해서, 그 다음 15페이지 2006년 7월 이후에 수없이 많은 새로운 정책과제들이 등장을 했고 그 내용을 잘 보시면 지금 우리 도에서 추진하는 그런 정책들하고 크게 다르지 않습니다.  그리고 두 페이지에 걸쳐서 나와 있지요.  그 다음 페이지 더 가셔서 18페이지를 보시면 이것도 2006년 신규과제가 쭉 나와 있잖아요.  이것 보시면 맨 뒤에 FTA에 대해서 제가 온 다음에 새로 시작해서 이거 다 하고 있습니다.  그래서 제가 뭘 더 잘 하고 있다는 의미가 아니라 연구원은 연구원으로서…….
</p>
<p><b>○ 장윤영 위원 </b> 죄송합니다.  그것은 조금 전에 말씀하신 위탁연구과제 같습니다.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이것은 우리가 해야 될 일이지만 우리 안에 특별한 노하우를 엑스퍼티즈(expertise)를 가진 박사가 없으면 외부 사람을 참여시켜서 하는 거지요.  외부위탁이라는 얘기는 우리가 하는 연구에 외부사람을 활용해서 한다는 의미지요.  그래서 여기에 쭉 보시면 신규과제가 한ㆍ미FTA에 대해서 벌써 두 가지가 시작되고 있고요.  앞에 아까 보여드린 정책과제는 상당히 많습니다, 7월 이후에 시작된 것들이.  그래서 포인트는 뭐냐면 기본…….
</p>
<p><b>○ 장윤영 위원 </b> 원장님, 잠깐만요.  지금 18페이지를 말씀주셨는데 한ㆍ미FTA가 경기도에 미치는 경제적 파급효과와 대응방안에 경기개발연구원에서 위탁을 어디에 줬느냐 하면 공주대학교입니다.  분명하게 충청도하고 경기도는 규제 차원에서 틀립니다.  규제 차원에서 틀리고 그 다음에 주요 농업생산물에 대해서 분명히 틀립니다.  그렇다고 한다면 한ㆍ미FTA, 지역적인 특성이 있지 않습니까?  지역적인 특성에 대해서 과연 공주대학교가 경기도…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다.  뭘 우려하시는지 제가 아는데요.  이 프로젝트의 내용은 이렇습니다.  지방경제, 특히 농업부문이라든가 이런 부문에 FTA에 따른 효과를 연구한 사람이 그렇게 많지 않습니다.  그런데 여기 공주대학교 이름은 제가 기억 못하겠는데 그 사람은 지금까지 중앙연구원에 있으면서 지방의 농업부문에 대한 연구를 했던 사람이고 경기도에 대한 연구를 했던 사람이기 때문에 저희가 그 사람을 이 연구에 참여시킨 것이고 그 사람 혼자서 하고 있지 않습니다, 물론.  이게 한 네 사람 정도의 팀을 만들어서 하고 있기 때문에 지금 말씀하신 그런 우려는 안 하셔도 되지 않을까, 저희가 사람을 선정할 때 그냥 간단하게 연구하는 사람을 선정하지 않습니다.  그래서 그 점은 저희를 믿어주시면 어떨까.  저희가 최선을 다해서 경기도에 미치는 영향을 가능한 우리가 잘 알아내야지만 대응하기 때문에 연구자를 선정할 때 최선을 다하고 있고요.  마찬가지로 FTA가 농업에 미치는 영향도 이미 서울대학이라든가, 서울대학에 농업문제와 FTA를 연구하는 사람들이 있기 때문에 그런 사람을 찾아서 간 것이지요.  저희가 무슨 지역이나 이런 것을 따로 생각해서 그런 것은 아니니까 걱정 안 하셔도 되지 않을까 싶습니다.
</p>
<p><b>○ 장윤영 위원 </b> 제가 원장님께 드렸던 질의 자체는 분명히 어떤 조직에 어떤 리더가 들어가느냐에 따라 그 조직은 바뀌게 됩니다.  그래서 좌 원장님의 기대가 굉장히 크다는 말씀을 먼저 드리는 겁니다.  그래서 원장님께서 들어오셔서 경기개발연구원의 바뀐 패러다임은 무엇이냐는 겁니다.  원장님 때문에 새로 도입된 내년도나 앞으로의 아젠다는 무엇이냐는 것이고요.  그런 면에 있어서 질의했던 것 자체는 내년도 기본연구과제 속에서 혹여라도 원장님의 관심과 이런 것 때문에, 실질적으로 많은 사업부가 있지 않습니까?  혹시 반영된 것이 있으시다면.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 개인연구에 대해서는 제가 그렇게 강요하지 않습니다.  각자 자기 연구주제를 선택할 자유가 있고 아젠다가 우리 경기도의 문제하고 중요성에서 동떨어지지 않으면 저는 그것을 연구원이 자율적으로 할 수 있게 하는 것이 옳다고 생각합니다.  그 대신에 제가 아까 보고할 때도 말씀드렸지만 중앙정부 정책에 대한 연구가 저는 대단히 미흡하다고 생각하고 그래서 제가 수도권정책센터를 만들어서 하는 것도 바로 중앙정책, 수도권규제정책에 대한 반론이라면 죄송하지만 그게 국가경제에 얼마나 피해를 미치고 있는지를 연구하도록 하고 있을 뿐만 아니라 환경부분에 있어서도, 제가 계속 환경부분에 얘기를 하고 있습니다만 그동안 우리가 해온 환경패러다임이랄까 이게 중앙정부가 다 정해준 것인데 그 속에서 우리가 물이라든가 다른 환경정책 집행수단을 가지고 여러 가지 연구를 하고 있지만 그것만 해서는 안 되지 않겠느냐.  중앙정부의 정책을 한번 다시 검토해야 된다.  그래서 그 부분도 저희가 더 연구를 할 것이고 예를 들면 지방자치제도에 대해서도 저는 옳은 방향으로 가고 있다고 생각을 안 합니다.  그런 면에 대해서도 제가 중앙정책에 대해서 다시 연구를 할 것이고 이것을 하는 과정에서 또 경기도에서 해야 될 일이 생기면 경기도 문제하고 연결시켜서 다루어나가야 되지 않을까 생각을 하고 있는데요.  그렇게 해서 제가 생각하는 시각이라든가 이런 것은 팀이면 팀, 부서면 부서가 가는 방향에 대한 그것을 설정하고 그것이 잘못 됐으면 바꾸거나 하는 그런 쪽에서 제가 영향을 미치는 것은 필요하지만 개인연구의 연구관심은 그것도 지켜줘야 되지 않을까 하는 게 저 개인적인 생각이라서요.  그래서 기본연구과제는 개별 연구박사가 이니시에이트(initiate)를 했지만 정책연구로 가기 시작하면 그때부터 저나 지휘부 혹은 도에서 요청하는 사업도 할 수가 있고 필요에 따라서는 의회에서 요청한 사업도 저희가 정책과제로 수행할 수 있음을 보고드립니다. 
</p>
<p><b>○ 장윤영 위원 </b> 알겠습니다.  그러면 이 부분에 대해서만 하겠습니다.  상당히 폭이 넓은 부분이기 때문에요.  지금 원장님께서는 연구원의 베이스를 넓혀주고 확보해 주기 위해서 기본연구과제에서는 재량에 맡기신다고 하셨지만…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 가능한, 그러나 동떨어지면 안 되지요. 
</p>
<p><b>○ 장윤영 위원 </b> 최소한 정관과 조례에 따르면 여러분들이 제시하신 495페이지 말씀드리겠습니다.  바로 기본연구과제는 뭐냐면 “경기도의 중장기 비전제시와”입니다.  그 다음에 두 번째가 원장님께서 말씀하신 연구원들의 대외전문학술활동을 장려하기 위한 연구베이스를 보호해 주시는 겁니다.  그래서 전제조건이 있다는 면에 있어서, 저것을 확인해 주시기 바랍니다.  바로 이 과제 때문에 위원회가 있지요?  그 다음 496페이지에 선정절차가 있습니다.  이 절차과정 속에서 혹여 개선돼야 될 점이 있다면 개선을 해달라는 겁니다.  무엇이냐면 연구원들이 제목과 내용을 설명하겠지요.  배경이 뭐냐, 최소한 이러한 과제가 선정될 때 근거를 확인해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 알겠습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 최근이나 전년도나 향후 봤을 적에 경기도에서 가장 커다란 문제점과 우리 경기개발연구원의 합목적성에 따라서 어떤 근거에 의해서 이 과제가 선정됐습니다라고 하는 걸 확인해 달라는 겁니다.  그래서 연구제목 자체 하나하나가 진짜 우리 도민들하고, 지역은 물론 국가에 필요한 과제가 돼 줬으면 좋겠다.  그런데 내가 이것을 전공했으니까, 지역사회에 미치는 영향은 없지만 내가 전공했으니까 이것을 한번 해보겠다라고 하는 부분도 말릴 수는 없겠지만 제일 중요한 것 있지 않습니까?  이것은 진짜 원장님한테 여쭙고 싶습니다.  경기개발연구원 여러분들이 6층에 그대로 써놓은 것 있지 않습니까?  “경기개발연구원은 도정의 중장기 비전제시와 정책개발을 지원합니다.”라고 하는 경기도에 국한된 연구원으로 갈 것인지 아니면 아까 전동석 위원님 잠깐 말씀하셨지만 경기개발연구원이지만 대한민국에서 손꼽히는 싱크탱크 기관으로서 존립할 것인지에 대해서는 아마 차후에 반드시 말씀을 한번 주셨으면 좋겠습니다.  하지만 여러분들이 밝혀주신 것은 도정의 중장기 비전제시와 정책개발을 지원한다고 돼 있습니다.  이런 부분에 있어서 연구원님들의 연구베이스에 대해서 보호해 주시는 원장님, 대단히 감명스럽지만 경기도의 고민을 같이 해달라는 것이고요.
</p>
<p style="padding-left:1.2em">  그러면서 우리 실장님 서계시니까, 금년도에 경기도가 외부에 용역을 준 사업내용 중에서 2005년도는 빼겠습니다.  혹시 맑은물관리과에서 평택호 수질개선 대책마련을 위한 연구용역이라는 것이 발주된 것을 알고 계십니까?  예산액은 8,000만원입니다.  혹시 알고 계셨습니까?  용역기간은 금년도 7월 6일부터입니다.
</p>
<p><b>○ 기획조정실장 이상훈 </b> 혹시 위원님, 죄송합니다만…….
</p>
<p><b>○ 장윤영 위원 </b> 여기 자료에는 없습니다.  자료에는 없는데 맑은물관리과에서 금년도에 발주한 도정발전연구용역입니다.  이중에서 평택호 수질개선 대책마련을 위한 연구용역사업, 8,000만원짜리 사업을 개발연구원에서 알고 있었느냐는 겁니다.  참고적으로 말씀드리면 여러분의 홈페이지를 통해서 수질과 관련한 용역이 16개가 수행됐습니다.  16개가 수행됐는데, 똑같습니다.  화옹호의 수질개선대책, 바로 여기서 하셨습니다.  팔당상수원 수질개선을 위한 용역 여기서 하셨습니다.  16개나 수행했는데 이 사업이 어디로 갔느냐, 현대엔지니어링으로 갔습니다.  현대엔지니어링은 잘 모르지만 연구하는 곳이 아니라 플랜트(plant)를 시설하는 곳이라고 판단합니다.  
</p>
<p><b>○ 기획조정실장 이상훈 </b> 그 부분에 대해서 제가 답변을 드려도 되겠습니까?  상당히 많은 연구과제를 의뢰하는데 저희는 주로 환경정책, 수질관련 등 정책을 연구하다보니까 특정한 기술적인 부분들이 있습니다.  기계를 작동해서 해당 부문 시료를 채취해서 수질을 분석한다, 이런 내용들이 있습니다.  
</p>
<p><b>○ 장윤영 위원 </b> 실장님, 제 질의 자체는 금년 7월에 발주가 된 맑은물관리과에서 평택호 수질과 관련해서 대책마련한 연구용역 8,000만원짜리를 알고 계시냐고 물어봤습니다.  
</p>
<p><b>○ 기획조정실장 이상훈 </b> 제가 지금 기억은 없습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 그러면 “기억이 없습니다.”가 답변입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 죄송합니다.  환경부장을…….
</p>
<p><b>○ 기획조정실장 이상훈 </b> 이 답변에 대해서는 환경정책연구부장으로 하여금 답변을 하도록 하겠습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 답변은 간단합니다.  알고 계셨습니까, 모르고 계셨습니까 입니다.
</p>
<p><b>○ 환경정책연구부장 성현찬 </b> 환경정책연구부장 성현찬입니다.  저희는 환경 전 분야를 하고 있는데 수질분야가 이번에 정책개발센터로 옮겼습니다만 그 전에 저희 부서에 같이 있었기 때문에 저희 수질을 담당하는 송미영 박사님이 계십니다.  도 맑은물관리과에서 협의가 돼서 평택호 그 부분에 대해서 용역협의가 왔습니다.  그리고 저하고도 잠깐 협의했었는데 그 부분은 기간이 짧았고요.  그리고 저희는 정책연구기관이기 때문에 평택호의 수질을 측정하고 여러 가지 기술적인 부분을 저희 연구원에서 다 수행하기 어렵습니다.  그래서 짧은 기간에 대책을 내달라고 해서 도하고 협의를 해서 그러면 외부에 짧은 기간에 할 수 있는 엔지니어링 회사 쪽으로 가는 것으로 해당 박사하고 협의한 것으로 알고 있습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 지금 말씀드린 것은 진짜입니다.  이것은 더군다나 7월 발주입니다.  바로 김문수 지사의 핵심사업이 평택호는 아니지만 있는 부분입니다.  이 부분만큼은 향후 4년 동안 김문수 지사의 맑은물 관련해서 기준이 될 수 있었던 용역이라는 겁니다.  그래서 이 부분만큼은 욕심을 내셨어야 했다.  그래서 연구능력이 없는가보다 했는데 조금 전에 말씀하셨던 송미영 박사님을 비롯해서 굉장히 많이 연구를 하셨더라고요, 다른 그 어떤 분야보다도.  그러다보니까 우리 경기개발연구원의 정체성 있지 않습니까?  그래서 경우에 따라서는 아픔도 각오를 해야 되지만 이 부분은 아까운 사업입니다.
</p>
<p style="padding-left:1.2em">  그 다음에 또 하나 있습니다.  됐습니다.  박사님, 들어가셔도 되겠습니다.  여기에 금년도에 했던 것 중에서 보니까 경기도 전략사업 육성을 위한 기술조사 수립연구, 경기도의 문제입니다.  분명히 삼성전자나 LG 같은 곳은 한국기업이 아닙니다.  글로벌기업입니다.  지금 경기도의 가장 커다란 문제가 뭐냐면 매출은 올라가고 있지 않습니까?  장부상의 수치는 올라가고 있지만 이것이 고용효과에 미치는 영향이 전혀 없다는 것이 지금 우리나라의 문제 아니겠습니까?  그러면서 지금 현재 IT분야만 하더라도 보면 대기업은 살아남습니다.  중소기업은 다 죽습니다.  경기도의 전략사업 육성을 위한 연구용역이었습니다.  1억원짜리였습니다.  이것은 진짜 경기도의 미래를 위해서, 그러면서 다시 한 번 내년도의 기본연구과제 제목을 쫙 훑어봤습니다.  경우에 따라서는 연구를 위한 연구를 하고 있는 경기개발연구원일 수도 있다는 겁니다.  경기도민이 필요로 해야 됩니다.  모든 정책집행자, 수립자가 경기개발연구원을 필요로 해야 됩니다.  그런데 우리 기조실장님 말씀에 의하면 과거 민선2기에 임 지사님은 그랬다고 합니다.  그래서 손 지사나 지금의 김 지사는 경기개발연구원을 필요로 하는지에 대해서, 아마 제가 지사라 하더라도 내년도의 기본연구과제를 보는 순간에 파르르 떨렸을 수도 있을 것 같다는 겁니다.
</p>
<p style="padding-left:1.2em">  그래서 이 부분, 제가도 요청했던 자료, 아시겠지요?  그래서 원장님께 부탁드리겠습니다.  향후에 기본연구과제를 비롯해서 정책연구과제 있지 않습니까?  근거를 제시해라.  언론에서 떠들든 아니면 모든 자료의 근거에 있어서 경기도에 이게 진짜 문제가 있다라는 관련 자료를 제시해라.  그것을 과제로 올릴 수 있게끔.  그래서 진짜 연구ㆍ노력하고 도를 위해서 진짜 끓는 정성이 보이는 과제로 선정해 주시기 바랍니다.  그래서 연구원들한테 배분해서, 연구비를 배분한다는 형식의 과제선정이 아니라 진짜 뿌리가 있는 연구를 부탁…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다.  장 위원님 우려하시는 것 다 아는데요.  제가 다시 말씀드리고 싶은 것은 기본연구과제 2007년도 것을 잘 보시면 조금 동떨어진 것처럼 들리는 게 있습니다.  그런데 이 연구의 특징은 이런 연구들이 돼 있어야지만 그 다음에 경기도 현안에 대한 정책을 연구하는데 대체로 다 도움이 되는 연구들입니다.  그렇기 때문에 아카데믹하게 들리고 동떨어지게 보이지만 제가 보기에는 이런 연구들이 쌓이고 쌓여야지만 우리가 도에서 하는 정책과제라든지 다른 단기과제를 쉽게 할 수 있기 때문에 저는 아까 말씀하신 대로 다시 한 번 점검은 물론 하겠습니다만 그런 점을 같이 생각을 해 주셨으면 좋겠다는 말씀을 드립니다.
</p>
<p><b>○ 장윤영 위원 </b> 알겠습니다.  기조실장님 들어가셔도 좋습니다.  사무처장님, 잠깐 부탁하겠습니다.  이게 사무처장님 담당업무인지 모르겠지만 경기개발연구원 규정집에 의한 제7편 재산회계부분 있지 않습니까?  여기서 계약과 관련된 업무가 사무처에서 이루어집니까? 
</p>
<p><b>○ 사무처장 이정열 </b> 네, 그렇습니다.
</p>
<p><b>○ 장윤영 위원 </b> 그러면 제8장 계약 부분, 제69조 계약원칙 제2항, 계약을 체결할 때는 일반경쟁계약에 의함을 원칙으로 한다라고 하는 부분 혹시 알고 계십니까? 
</p>
<p><b>○ 사무처장 이정열 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 그러면 질의토록 하겠습니다.  감사자료 423페이지부터 437페이지까지입니다.  여기도 기회를 드리겠습니다.  혹시 431페이지 사항에서 수정해야 될 부분이 있습니까?  혹시라도 제출하고 나서.  혹시 없겠습니까? 
</p>
<p><b>○ 사무처장 이정열 </b> 확인을 하지 못했습니다.
</p>
<p><b>○ 장윤영 위원 </b> 431페이지 아홉 번째 대한인쇄정보산업협동조합, 수원에 소재하고 있는 업체 맞습니까? 
</p>
<p><b>○ 사무처장 이정열 </b> 조합이기 때문에 인쇄조합이 서울에 소재하고 있습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 오기된 것입니까? 
</p>
<p><b>○ 사무처장 이정열 </b> 여기에서 보면 우리가 계약할 때 중소기업협동조합에다 하면 그 조합에서 업체를 선정합니다. 
</p>
<p><b>○ 장윤영 위원 </b> 처장님!  지금 단체수의계약을 설명하시려고 하는 겁니까? 
</p>
<p><b>○ 사무처장 이정열 </b> 네.
</p>
<p><b>○ 장윤영 위원 </b> 그런데 이것 금액이 얼마인지 봐주시기 바랍니다.  867만원입니다. 
</p>
<p><b>○ 사무처장 이정열 </b> 그렇습니다.
</p>
<p><b>○ 장윤영 위원 </b> 지금 질의의 핵심을 아셔야 되겠습니다.  바로 전 페이지 430페이지한번 봐주시겠습니까?  여기도 경기도인쇄정보산업협동조합이 있습니다.  그런데 분명하게 서울 소재한 것을 수원으로 하고 있습니다.  그리고 여기에서 실질적으로 경기개발연구원, 경기도민의 세금으로 운영이 되는 연구원입니다.  소재지에 대해서 눈여겨서 한번 봐 주시고요.  진짜 가슴 답답한 것은 436페이지, 437페이지입니다.  29개 계약 중에서 경기도에 소재한 회사로 9개가 갔습니다.  나머지 전부 다 서울로 갔습니다.  특별한 기술이 있는지 봤습니다.  바로 여기서는 대한인쇄정보산업협동조합이 전부 서울입니다.  지역경제 활성화에 대한 대안을 연구하는 곳이 경기개발연구원입니다.  특히 2006년도에 밀집된 이유에 대해서 설명 가능하시겠습니까? 
</p>
<p><b>○ 사무처장 이정열 </b> 양해해 주신다면 계약을 집행한 실무자한테 답변드리도록 하겠습니다.
</p>
<p><b>○ 장윤영 위원 </b> 말씀해 주시죠.
</p>
<p><b>○ 재정지원과장 강윤구 </b> 재산과장 강윤구입니다.  저희가 통상 500만원 이상 인쇄공업협동조합을 사용해서 계약을 하는데 2005년도까지는 경기도인쇄공업협동조합이 단체수의계약 품목에 들어있었습니다.  그런데 2006년 1월 1일부터는 실제적으로는 수원에 소재하거나 경기도에 소재한 업체가 일은 했습니다만 대한인쇄공업협동조합으로 수의계약 업무가 이관되었기 때문에 거기 조합을 사용하다 보니까, 대한인쇄공업협동조합은 서울에 있고요.  실제적인 업무처리는 경기도인쇄공업협동조합을 통해서 이루어지는데 서류상 명목상 대표자가 서울로 되어 있기 때문에 그런 현상이 일어났습니다.  실제적으로 일을 하는 것은 경기도 소재의 업체들입니다.
</p>
<p><b>○ 장윤영 위원 </b> 지금 설명을 잘 들었습니다.  조금 전에 말씀드렸지 않습니까?  436, 437.  그러면 조합이 아닌 서울 업체로 간 내용이 보고서 인쇄입니다.  조합으로 단체 수의계약을 해야 될 이유가 있었습니까? 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 통상 저희는 500만원 이상은 중소기업진흥촉진법에 의해서 단체수의계약을 내부적 지침으로 하고 있는데.
</p>
<p><b>○ 장윤영 위원 </b> 금액을 봐 가면서 말씀을 주십시오.  분명히 500만원이 넘는 것 있습니다. 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 있습니다.
</p>
<p><b>○ 장윤영 위원 </b> 그러면서도 조합으로 안 간 것 있습니다. 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 그렇습니다.
</p>
<p><b>○ 장윤영 위원 </b> 이 판단은 부채도사가 합니까? 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 실제적으로 저희가 출판을 결정해서 인쇄소를 정할 때는 해당 박사의 의견을 많이 들어서 하는데 디자인이나 출판 상태를 봐서 하기 때문에 저희 계약부서에 의뢰가 오면 검토는 합니다만 가능한 한 연구책임자가 건의하는 출판사를 활용하고 있습니다. 
</p>
<p><b>○ 장윤영 위원 </b> 469페이지부터 봐 주시겠습니까?  여기서는 진짜 고통스러운 부분이 있습니다.  470, 471페이지 보게 되면, 특히 471페이지 오른쪽 하단 부분에 보면 왠지 모르지만 토를 달았습니다.  “국가기관이기 때문에 6,900만원짜리를 수의계약했습니다.” 이것 수의계약명단 맞죠?  469페이지 보면.
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 그렇습니다.
</p>
<p><b>○ 장윤영 위원 </b> 여기는 토를 달았거든요.  조금 전에 500만원 말씀하셨는데 470페이지 보면 4,000만원 이상도 수의계약을 했습니다.  참고적으로 말씀드리면 예전에는 국가를 당사자로 하는 계약에 관한 법률이 있지만 지금은 지방자치단체를 당사자로 하는 계약에 관한 법률이 있죠?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 그렇습니다.
</p>
<p><b>○ 장윤영 위원 </b> 그쪽에서는 1,000만원 이상이면 G2B시스템을 이용해서 계약을 하도록 하고 있습니다.  알고 계신가요? 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 알고 있습니까? 
</p>
<p><b>○ 장윤영 위원 </b> 그러지 않은 이유가 있습니까? 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 저희는 아직 국가계약법을 준용하도록 저희 재무회계 규정에 되어 있는데 그것은 행정자치부 예규로 발령이 되어 있습니다.  가능하면 일반경쟁을 하는 게 원칙인데 여기 국가기관이라고 토를 단 이유는 국가기관은 수의계약 대상, 3,000만원 이상 시에도 수의계약 대상 기관이 되기 때문입니다.
