<p><b>○ 장윤영 위원 </b> 제가 질의한 의도를 모르고 계십니다.  여기 토를 달았다라는 것은, 경쟁입찰대상인데 수의계약을 했는데 이런 이유 때문이라고 토를 달았다는 것은 알고 있었다라는 겁니다.  그러다 보니까 국가기관이 아닌 주식회사 가이드어소시에이트에다 수의계약한 이유를 묻는 겁니다.  여기도 토를 달았어야 돼요.  지금 말씀하신 그 내용을 보면, 지금 행자부 예규에 나와 있는 추정가격 1,000만원 이상이면 사용해야 되거든요.  그런데 이 토를 달았던 것은 알고 있었는데 그 외 1,000만원 넘는 게 한두 개가 아니거든요.  
