<p><b>○ 장윤영 위원 </b> 그 다음 페이지 470페이지에 6,300만원짜리 있고요.  그 밑에 토 하나 달아주고 국책연구원, 통일연구원 6,400만원짜리.  한국세스소프트웨어도 국책기관인가요?
