<p><b>○ 장윤영 위원 </b> 그렇다고 한다면 지금 제가 질의한 것은 행자부 예규에 의한 G2B시스템을 이용한, 그렇다라고 한다면 여기서는 수의계약이 아닐 것 같은데요.  이 자료가 바로 269페이지 상단에 있지만 수의계약 현황이거든요.  자료가 잘못된 겁니까? 아니면 질의가 잘못된 겁니까? 
