<p><b>○ 임우영 위원 </b> 임우영 위원입니다.  장시간 하셨는데 제가 마지막으로 몇 가지만 확인하고 질의를 하겠습니다.  먼저 수탁연구과제 중에서 중지되어 있는 과제가 있습니다.  중지이유를 설명해 주셨으면 좋겠습니다.  업무보고 11페이지.
