<p><b>○ 경기개발연구원장 좌승희 </b> 제가 아까 업무보고 시에도 언급했습니다만 이게 아마용역기관 발주처 사정에 의해서 그런 것 같은데 구체적인 내용을 대신 답변하게 하도록 하겠습니다. 
</p>
<p><b>○ 기획조정실장 이상훈 </b> 기조실장 이상훈입니다.  수탁과제 중에서 중지되어 있는 것은 전부 발주처의 요청에 의해서 중지된 건이 되겠습니다.  우선 업무보고 11쪽에 있는 2005년도 중지과제 건을 보면 첫 번째가 제4차 경기도권역 관광개발계획수립 연구용역, 이정훈 박사가 수행했는데요.  중지가 어떻게 되었냐면 용역기간의 일시중지입니다.  그래서 용역비용은 정산을 안 하는 것이고, 왜 그러냐면 관광진흥법 제49조2항 규정에 의해서 중앙관계부처 협의 및 문화관광부장관의 조정 필요, 이 과업을 수행하다가 발주기관의 의지와 관계없이 기간이 연장된다든지 협의가 잘 안 된다든지 그런 내용입니다.  그런 경우에 해당 기관에서 요청하고요.  그 다음에 가평군 오염총량관리계획수립 용역 건이 있습니다.  이것은 2005년 12월 5일 해서 일시중지되었는데 중지사유가 뭐냐면 행정절차입니다.  결국은 오염총량관리계획 수립을 하다보면 이게 법정 계획이 되고 환경부하고 협의를 하다 보면 협의기간이 연구용역 수행기간을 초과한다든지 하는 경우에 협의내용을 반영하고 우리가 논리적으로 보완도 해야 되기 때문에 발주처에서 요청합니다.  그래서 용역기간을 중지해 달라라고 하는, 대개 기간을 맞추기 위해서 그런 경우가 많고요.  그리고 협의가 잘 안 되는 경우가 있습니다.  상당히 많은 법정 계획.  이 두 건이 법정 계획입니다.  협의가 안 되다 보니까 발주처에서 해당 연구기간이 끝나면 연구수행기관으로서 경기개발연구원은 그냥 납품하면 되는데 해당 발주처에서 협의과정이 아직 안 끝났으니까 중간에 논리 제공도 해야 되고 또 용역한 내용을 반영해야 되기 때문에 그런 경우 중지요청이 오면 연구원에서 그것을 받아들여서 연구위원회에 심의해서 인정이 되었을 경우에 그것을 받아들이고 있습니다. 
</p>
<p><b>○ 임우영 위원 </b> 일시중지 요청을 했을 때는 수탁비용을…….
