<p><b>○ 도시ㆍ지역계획연구부장 이외희 </b> 도시ㆍ지역계획연구부장 이외희입니다.  지금 자료가 없어서 책임연구원이 와야 말씀드릴 수 있을 것 같은데요.  각 부분별로 필요한 연구진들로 구성되어 있습니다.  제가 기억하기로는 저희 부서에 주택부분을 맡고 있는 봉인식 박사하고 경제사회연구부의 산업관련 해서 김군수 박사님하고 이정훈 박사님하고 그 다음에 환경 쪽에 고재경 박사님하고 그런 식으로 각 부분별로 필요한 연구진으로 구성되어 있는 것으로 알고 있습니다. 
</p>
<p><b>○ 임우영 위원 </b> 제가 왜 이런 질의를 드리냐면 제가 아까 자료요구를 해 가지고 여러분들이 주신 종합발전계획수립 연구에 대해서 연구계획 및 추진일정을 도에 보고하셨어요.  그런데 그 뒤의 첨부물에 참여연구진 편성을 했는데 교통분야 정책개발에 있어서는 김문수 지사님께서 굉장히 중요하게 여기는 교통개발분야에 연구원이 없는 것으로 나왔습니다.  그래서 제가 여쭤보는 겁니다. 
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이외희 </b> 연구진에는 포함이 되어 있는데 아직 정해지지 않은 것으로 알고 있습니다.  조만간 정해서.
