</p>
<p><b>○ 임우영 위원 </b> 이상규 박사가 올라오십니까?  경기개발연구원에서 아까 여러 번 말씀이 계셨지만 경기도의 주한미군반환공여지 관련해서 주변지역 등에 관한 특별지원법이 제정되는 데에도 굉장히 크게 기여했고 시행령이 만들어지는 데도 경기개발연구원이 기여한 것은 잘 알고 있습니다.  왜냐면 이 법의 발의자가 파주의 이재창 국회의원이시기 때문에 제가 그와 관련해서 관심도 많이 가지고 있었고 특히 지난번 이와 관련해서 제2청에서 독일과 미국의 미군반환기지 및 미군기지 시찰하는데 제가 우리 기획위원회를 대표해서 다녀왔습니다.  독일지역에는 책임연구원으로 있는 이상규 박사가 같이 다녀왔는데 그 이후에 시행령에 따라서 경기도의 지방발전위원회 구성과 관련된 조례안을 제가 입안했고 그와 관련해서 행자부에서는 2008년도 예산을 짜기 위해서 1월 15일까지 경기도의 발전계획안을 제출하도록 현재 그렇게 되어 있습니다.  그런데 용역이, 물론 시행령과 모든 것이 늦게 되다 보니까.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 너무 촉박하지 않느냐 걱정이 되시는 거죠?
