<p><b>○ 도시ㆍ지역계획연구부책임연구원 이상규 </b> 도시지역계획연구부의 이상규입니다.  교통연구부는 아직 정해지지 않았습니다. 
</p>
<p><b>○ 임우영 위원 </b> 그런데 제가 알고 있기로는 도의 발전계획안을 1월 15일까지 행자부에 제출하도록 되어 있고 그렇기 때문에 우리 경기개발연구원에서 1차 보고서를 12월 말까지 제출하도록 그렇게 되어 있죠?  
</p>
<p><b>○ 도시ㆍ지역계획연구부책임연구원 이상규 </b> 네. 
</p>
<p><b>○ 임우영 위원 </b> 그러면 지금 교통 분야가 전혀 검토가 안 되고 있는 겁니까? 
</p>
<p><b>○ 도시ㆍ지역계획연구부책임연구원 이상규 </b> 지금 저희가 연구용역을 1차와 2차로 나누어서 하는데 1차 관계는 시ㆍ군의 사업계획을 중심으로 담아 가지고 가는 것으로 삼았거든요.  그래서 각 분야별 연구들도 거의 한 달 내에 보고서 앞부분들을 정리해야 되는 문제가 있는데 그 부분에 대해서는 저희가 현황파트 정리와 그 다음의 시ㆍ군의 자료를 통합해서 일단 1차 보고서를 내려고 하고 있고요.  그리고 1차 보고서에 따른 중심 부분이 사업계획이 중심이기 때문에 아까처럼 분야적인 중요성 이 부분에 대해서는 저희가 도하고 공감하고 있지만 그 부분에 대해서는 추후 2차 보고 때 심도 있게 다루도록 하고 이번 1차 보고서 때는 2008년도 사업을 중심으로 계획하고 있습니다. 
</p>
<p><b>○ 임우영 위원 </b> 제가 왜 이 부분을 지적하냐면 특히 경기북부지역은 지난 50여년간 여러 가지 규제로 인해서 어떻게 보면 상대적 피해를 본 지역입니다.  그런데 지원특별법에 의해서 이번에 그런 것을 많이 만회해야 될 이런 시점에 와 있거든요.  각종규제법을 초월해서 지원특별법이 만들어졌고 그것에 의해서 모든 시설이나 학교나 이전도 가능하고 개교도 가능하도록 현재 그렇게 되어 있단 말이에요.  그래서 이게 꼭 미군반환공여지 뿐만 아니라 주변지역 등 지원특별법이라고요.  무슨 얘기냐면 미군기지가 있던 읍ㆍ면ㆍ동과 경계에 있는 읍ㆍ면ㆍ동 또 미군공여지가 있던 시ㆍ군과 접해 있는 시ㆍ군 이래 가지고 어떻게 보면 경기도 거의 전역이 특별법의 혜택을 볼 수 있는 이런 기회라고 저는 생각하고 있고 또 그렇기 때문에 이런 법에 의해서 종합발전계획안을 짤 때는 될 수 있으면 그동안 각종 규제로 인해서 우리가 하지 못했던 이런 것도 감안해서 모든 것이 이루어져야 되겠다 하는 노파심에서 제가 말씀드리는 거고 꼭 반환구역 내만 한정해서 할 게 아니고, 여기 여러분들이 주신 자료에도 보면 경기도의 2010 계획에 의거해서 각종 계획을 수립하겠다 이렇게 되어 있어요.
</p>
<p style="padding-left:1.2em">  그것은 제가 봤을 때 굉장히 접근이 타당성이 있다고 보고 또 하나 문제는 지금 1차 보고안을 각 지자체에서 지난주까지 제출하도록 되어 있었습니다.  저희 파주 같은 경우는 좀더 개별적인 용역을 주어 가지고 발전안을 만들기 위해서 도에 제출하는 것을 다음 주까지 1주일 연장해 놓은 상태인데 그런 것으로 봤을 때 파주에서도 굉장히 우려하는 게 뭐냐, 우선 주변지역은 기존 데이터를 가지고 계획을 수립하면 되는데 공여지 매각문제입니다.
</p>
<p style="padding-left:1.2em">  어제 2청에서도 문제제기를 했어요.  뭐냐 하면 2006년도에 미군반환공여지를 분명히 한국에 주겠다 그래놓고 아직까지도 미군에서 완전히 넘겨주고 있지 않은 상태입니다.  그런데 법은 벌써 시행되고 있고 그러다 보니까는 각 지자체에서 그 안에 있는 각종 시설이라든가 이런 것을 면밀히 검토해서 재활용할 수 있는 시설은 어느 게 있고 또 이것은 과감하게 철거해야 되겠다라든가 기본 시설파악이 되어야 되는데 그러기 위해서는 안에 들어가서 시설파악을 해야 되는데 아직까지 출입이 안 되고 있어요.  그런 상황에서 2008년도 예산안을 반영하기 위해서 기본계획안을 1월 15일까지 내라, 행자부에서 이렇게 하고 있고.  그래서 전반적으로 이런 계획안을 잡는 데 있어서 좀더 우리가 모든 면을 타당성 있게 검토해야 되겠지만, 특별히 내부야 어차피 다음에 면밀히 검토해서 하면 되겠지만 주변지역, 그동안 우리가 각종 규제로 인해서 활용 못 했던 부분들을 좀더 심층 있게 검토해 주십사 하는 당부의 말씀을 드리기 위해서 제가 거론하는 겁니다. 
</p>
<p><b>○ 도시ㆍ지역계획연구부책임연구원 이상규 </b> 알겠습니다.
</p>
<p><b>○ 임우영 위원 </b> 그러면 12월말까지 하는 안은 각 기초자치단체에서 올라오는 안을 갖고 그것에 의해서 수립하시겠다는 겁니까?
</p>
<p><b>○ 도시ㆍ지역계획연구부책임연구원 이상규 </b> 네, 그것을 다 받아들이는 것이 아니라 1차적으로, 내부적으로 걸러야 되겠죠.  그래서 저희 연구진과 도청하고 협의를 해서 1차 사업계획들을 정리한 다음에 집행부에 제출할 예정입니다.
</p>
<p><b>○ 임우영 위원 </b> 그래서 이 안 자체가 도지사가 안을 수립하도록 되어 있습니다, 시행령에 보면.  각 시장ㆍ군수가 하게 되어 있는 것이 아니고 도지사가 하도록 되어 있어요.  그러니까 도지사, 시장이 하도록 되어 있기 때문에 특별히 각 기초자치단체에서는 굉장히 관심이 많습니다.  우리가 제출한 안이 과연 100% 반영이 될 것이냐, 안 될 거냐.  또 우리가 주변계획 발전을 위해서 이 안을 집어넣었는데 될 거냐, 안 될 거냐.  굉장히 고민들도 많이 하고 있고 또 이것이 절호의 기회기 때문에 그 안을 만들 때 굉장히 심사숙고해서 만듭니다.  그런데 기간이 너무 촉박하다 보니까 어떻게 보면 진짜 담아야 될 것을 못 담는 우를 범하는, 물론 차후에 보완해 나가도록 되어 있지만 그런 것을 하나하나 검토하시면서 모든 것을 담을 수 있도록 그렇게 해 주시면 고맙겠습니다. 
