<p><b>○ 이해문 위원 </b> 그러면 원장님, 어떠한 평가기준으로 연봉계약을 합니까?  그런 어떤 아이디어가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우선 제가 그동안 보고받은 바에 의하면 지난 1년 동안 연구가 진행되는 과정에서 각종 연심회라든가 평가과정을 통해서 연구과제의 결과를 평가한 게 있고요.  그 다음에 각종 개인이 1년 동안 연구활동, 대외활동한 이런 것을 모두 묶어서 각자가, 말하자면 일종의 자기 성적표를 제출하게 돼 있습니다.  그것을 기초로 해서 각자의 1년 성과를 평가하게 되지요.  그것을 기초로 해서 각 연구위원들을 S에서부터 D까지 5등급으로 분류합니다.  물론 그것을 기초로 해서 장려금도 지급하고 하지만 동시에 작년 연봉에 일정 퍼센티지를 부과해서 추가해서 내년 연봉을 결정합니다.  그런데 그것을 하는 과정에서 연봉을 무작정 많이 할 수는 없기 때문에 도에서 준 예산을 바탕으로 해서 일정 평균상승률을 가지고 필요에 따라서는 성적에 따라서, 성과에 따라서 차등하는…….
</p>
<p><b>○ 이해문 위원 </b> 네, 알겠습니다.  원장님의 소신은 잘 알겠고요.  본 위원이 알기에는 아까 서울시정개발원은 연구원하고 비교한 가운데 우리 경기개발연구원이 더 발전하기 위해서는 급여문제도 고려해야 될 것 중에 하나거든요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니다. 
</p>
<p><b>○ 이해문 위원 </b> 대체적으로 서울시하고 비교해 본다면 한 10여% ± 차이가 있다고 하고 있는데요.  지금 경기개발연구원 예산편성이나 도에서 보조해 주는 거라든지 자체 회계장부를 쭉 보면 예산이 부족하지는 않거든요.  측면에서 원장님이 경기개발연구원을 앞으로 활성화할 수 있는 방안 중에 하나가 본 위원이 생각할 때는 연봉에 상당히 관심을 가지고 어떠한 대안을 마련하는 것이 중요하다고 생각합니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 연봉이 물론 중요한데요.  거기에 더 나아가서 성과급 차등을 많이 할 필요가 있지 않은가 하는 개인적인 생각을 가지고 있습니다, 추가로.  연봉이라는 것은 그 사람의 퇴직금이라든가 장기근무여건하고 관련이 있기 때문에 연봉차등도 물론 해야 되겠지만 사실은 매년 성과에 따라서 성과급을 더 차등하는 것이 좋은 인센티브가 되지 않을까 해서 두 가지를 다 감안해서 운영할 계획입니다.
</p>
<p><b>○ 이해문 위원 </b> 원장님, 그러면 성과급은 어떤 식으로 줍니까?  본 위원이 알고 있기에는 연봉계약이라고 하면 그 안에 다 포함되는 것으로 알고 있는데.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 연말에 지급하는…….
</p>
<p><b>○ 이해문 위원 </b> 따로 보너스가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 보너스가 있지요.  이것을 보너스라고 불러야 돼나?
</p>
<p><b>○ 이해문 위원 </b> 아니, 정확하게.  그러면 원장님도 지금 이사장하고 연봉계약을 체결했지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 원장은 그런 게 없습니다. 
</p>
<p><b>○ 이해문 위원 </b> 아니, 그러니까 예를 들면.  그러면 그런 성과가 있으면 당연히 원장님한테도 그런 성과급을 더 드려야 되는데 그런 성과급에 대해서 원장님이 말씀하셨기 때문에…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 기본연봉이 있고요.  그것을 성과연봉이라고 이름 붙였던가요?  그래서 그게 성과급이지만 그것을 연봉성격으로 한다고 해서 그동안 그렇게 해온 것 같습니다.  그래서 저는 기본연봉에다 성과연봉을 좀더 차등을 두는, 그동안에 성과연봉을 평균 200만원 정도씩 차등을 뒀다고 제가 알고 있는데요.  필요하면 성과에 따라서 다소 더 차등을 두는 방향으로 하겠다는 말씀이고요.  그 다음에 수탁연구과제 결과에 따라서 개별 박사들한테 가는, 그것도 일종의 성과급이 될 수 있는데요.  그 부분도 아주 적지만 약간씩 지급이 되고 있습니다.  원장은 그런 성과급이 없습니다. 
</p>
<p><b>○ 이해문 위원 </b> 없으면 앞으로 더 필요하다면 만들어서라도 할 수 있는 부분이고요.  그래서 일단은 제가 보수규정을 보고 또 연구원들이 받아갈 수 있는 지금 말씀하신 연봉 외에, 여기에는 나와 있지 않습니다.  성과급이라는 말이 여기에는 따로 없어요, 보수규정에는.  찾지를 못했는데 그러한 보수규정 외에 다른 인센티브제가 있으면 자료로 제출해 주시고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 이해문 위원 </b> 그 다음에 아까 수탁사업에 의해서 성과가 있으면 따로 인센티브를 줍니까?  과제가 끝날 때마다?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 과제 수행기간 중에 분기별로 지급하는 것으로 돼 있는 모양입니다.
</p>
<p><b>○ 이해문 위원 </b> 그럼 원장님, 혹시 지금 이런 관계를 잘 아는 담당자가 있으면 연구원들이 전체적인 연봉 외에 받는 인센티브가 어떤 것이 있는지 구체적으로 설명을 들었으면 좋겠습니다.  왜냐하면 서울시하고 비교해서 어떤 부분이 부족한지 또 지금 저희들이 볼 때는 하는 업무라든지 양으로 본다면 서울시 못지않은 일을 하거든요.  그래서 활성화할 수 있는 차원이 과연 무엇인가를 생각하고요.  혹시 연구원뿐만 아니라 여기에 정규직도 있고 비정규직도 있지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니다.  비정규직도 있습니다. 
</p>
<p><b>○ 이해문 위원 </b> 그래서 우리 동료 위원이 요구한 자료에 보니까 보수금액들이 쭉 나와 있는데 어떤 것이 과연 비교해서 적은지, 연구원들이 적은 건지 직원들이 적은 건지, 또 비정규직들은 보니까 수시로 교체되고 있어요.  그래서 요즘 비정규직에 대해서도 사회에서 여러 가지 제도적으로 보완하는 것이 있습니다.  그래서 여기서 하는 보수와 관련된 것에 대해서 전반적으로 원장님이 관심을 가지고 재검토를 해보고, 아까 원장님 말씀하신 대로 일정률의 인센티브를 주는 건지 그런 부분이 명확하지 않아서 제가 추가 질의를 드렸고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다.  제가 그 자료를 제공해 올리겠고요.  다른 연구원하고 비교하는 문제가 이런 어려움이 있습니다.  봉급과 급여에 관련된 것은 대외비가 돼서 다른 연구원이 실제로 어떤 구체적인 내용을 가지고 하는지 참 알기가 어렵습니다.  그래서 아주 대체적인 것을 가지고 하고 있기 때문에 설령 저희 것을 정확히 아신다 하더라도 그것을 다른 데와 비교할 레퍼런스(reference)가 분명치 않아서 애로사항이 없지 않아 있다는 생각은 듭니다만 좌우간 저희가 정보를 제공하도록 하겠습니다. 
</p>
<p><b>○ 이해문 위원 </b> 그래서 이월임금이라든지 또 그 동안의 재무제표를 분석해 보면 그런 것이 충분히 고려될 수도 있지 않겠냐.  그래서 제대로 급여를 충분히 보상하고 또 원하는 많은 아웃풋이 나올 수 있도록 그런 측면에서 제도적으로 획기적인, 원장님도 오셨으니까.  원장님이 또 활성화할 수 있는 것 중에 하나도 이런 방법도 있지 않겠냐 해서 제가 제의를 드렸고요.  관례대로, 해온 대로 일정률의 정률적으로 똑같이 인상하는 것은 큰 의미가 없다고 생각하거든요.  그래서 그런 긍정적인 측면에서의 필요성이 있다고 본 위원은 생각합니다.  참고로 보시고요.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 
</p>
<p><b>○ 이해문 위원 </b> 그 다음에 아까 자료 주신 것에 의하면 미수금 문제를 짚고 넘어가겠습니다.  미수금이 없다고 얘기하셨는데 과제를 아까 설명하시면서 과제가 중간에 중단된 것들이 많이 있어요.  아까 과제 중에 7건이 하다가 중단됐다고 하셨지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 이해문 위원 </b> 그러면 중단된 것에 대한 과제에 대해서 자체적으로 재무제표를 보면 미수금이라는 항목들이 쭉 있거든요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 이해문 위원 </b> 그래서 미수금이 아까 없다고 답변 중에 하셨는데 이것을 어떻게 회계를 정산했는지 궁금해서 그렇습니다.  그래서 ’99년에 광역도시계획 이게 당초예산액이 4억 8,300인데 수입은 4억 7,200이에요.  약 1,000만원 정도가 미수금으로 돼 있는 것을 비롯해서 2001년, 2003년에 화성 기반시설 부담, 그 다음 2004년도에 남양주개발 관리계획, 예를 들어 몇 건들이 미수금이 쭉 발생했거든요.  그래서 이것에 대해서 어떻게 정산하고 어떻게 처리하는 건지.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 실무자한테 답변을 요청하겠습니다. 
</p>
<p><b>○ 이해문 위원 </b> 답변을 부탁드리겠습니다. 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 재정지원과장 강윤구입니다.  저희 수탁사업은 완료시점에서 대차대조표에 적용하기 때문에 실제 수탁사업을 완료하지 못한 것은 미수금으로 정리가 되고요.  당해연도에 썼던 비용은 선급비용으로 정리되고 있습니다.  그래서 완료하면 미수금이 차감되게 돼 있습니다.  그래서 아까 말씀드린 미수금이 없다는 것은 완료한 과제에 못 받은 돈이 없다는 뜻으로 말씀을 드렸습니다. 
</p>
<p><b>○ 이해문 위원 </b> 완료한 것에 대해서는 못 받은 게 없다고 답변하셨는데 본 위원이 자료요구한 거라든지 자료에 보면 분명히 미수금 항목이 있거든요.
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 있습니다. 
</p>
<p><b>○ 이해문 위원 </b> 인식 차이인데 그러면 여기에서는 사업이 다 끝난 것은 미수금이 없다고 얘기하지만 재무제표에 보면 미수금 항목이 있어요.  
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 있습니다.  
</p>
<p><b>○ 이해문 위원 </b> 그래서 미수금 자료를 제가 요청했는데도 “해당사항 없음”이라고 답변했고 또 결산한 자료에도 보면 미수금이 쭉 있거든요.  그러면 ’99년도에 광역도시계획 하다가 2002년에 중지된 사업이 있어요, 예를 들면.  이런 사업은 언제까지 중지되고 여기에 미수로 달아놓습니까?  언제까지 이렇게 나갑니까? 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 그것은 저희는 수탁기관이고 수탁을 준 기관에서 재개공문이 떨어지면 재개에 대해서 완료를 시키는데 그때까지 미수금으로 정리됩니다.  선급비용과 미수금으로.
</p>
<p><b>○ 이해문 위원 </b> 아니, 그러면 그때까지는 계속 미수로 잡아놓는다고 지금 말씀하셨는데 그러면 예를 들어서 ’99년에 건설교통부에서 발주를 했어요, 보니까.  그렇지요?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이해문 위원 </b> 교통부에서 발주해서 ’99년 12월에 연구가 시작돼서 2002년 2월에 중지됐어요. 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 그렇습니다.
</p>
<p><b>○ 이해문 위원 </b> 그러면 약 5년이 지났는데 이런 사업을 건설교통부에서 얘기가 없으면 우리 경기개발연구원에서는 계속해서 미수로 가져가는 겁니까? 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 저희는 재무제표 상의 정리는 그렇게 할 수밖에 없습니다. 
</p>
<p><b>○ 이해문 위원 </b> 이게 어느 원칙에 의해서 그렇습니까?  기업회계기준에 의해서 하고 있지 않습니까? 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 기업회계기준에 의하면 발생기준이니까 완료사업만 완납금이 되고요.
</p>
<p><b>○ 이해문 위원 </b> 그러니까 이렇게 중지한 사업들이 쭉 나오는데 중지했으면 경기개발연구원에서는 이것을 이렇게 몇 년씩, 5년씩 기다릴 하등의 이유가 없지 않습니까? 
