<p><b>○ 재정지원과장 강윤구 </b> 저희가 할 수 있는 방법은 갑 측에서 재개해서 완료하는 방법인데 ’99년에 중지된 사업은 금년 중에 끝나는 것으로 제가 알고 있습니다만 갑 측의 재개공문이 없이 저희 일방적으로 완료처리한 다음에 재무제표를 정리할 수는 없는 사항이 되겠습니다. 
</p>
<p><b>○ 이해문 위원 </b> 그러면 건설교통부에다 이 건에 대해서 그동안에 어떤 노력을 해봤습니까?  그냥 거기서 올 때까지 무작정 기다릴 수는 없잖아요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그 프로젝트 자체를 담당했던 박사보고…….
