<p><b>○ 이해문 위원 </b> 네, 답변해 주세요.
</p>
<p><b>○ 수도권정책센터장 이상대 </b> 수도권정책센터장 이상대입니다.  1999년부터 시작된 광역도시계획은 아시는 바와 같이 국민의 정부 때부터 시작된 개발제한구역 조정을 위해서 수립된 것입니다.  지금 중앙도시계획위원회 심의 중인데 조만간 준공처리될 그런 예정입니다.
</p>
<p><b>○ 이해문 위원 </b> 언제요?
</p>
<p><b>○ 수도권정책센터장 이상대 </b> 조만간 곧 준공처리가 될 예정입니다.
</p>
<p><b>○ 이해문 위원 </b> 무슨?
</p>
<p><b>○ 수도권정책센터장 이상대 </b> 조만간 곧 끝날 예정입니다.
</p>
<p><b>○ 이해문 위원 </b> 중앙정부에서 하는 일이 5년씩이나 이렇게 수탁연구를 위탁해놓고 기관에다 이렇게 하는 것은 본 위원이 볼 때는 바람직하지 않다고 생각하거든요.  그래서…….
</p>
<p><b>○ 수도권정책센터장 이상대 </b> 그런데 광역도시계획이 개별 시ㆍ군마다 개발제한구역 조정 그 부분을 다 확정해 나가는 그런 작업들이 있기 때문에 지금 많이 늦어지고 있습니다. 
</p>
<p><b>○ 이해문 위원 </b> 네, 알겠습니다.  위원장님, 시간을 조금 더 써도 됩니까?  다른 위원님 양해해 주시면 준비한 자료니까 조금 하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 지금 시ㆍ군 지자체에서 올라온 사업 중에 예를 들면 과천지식정보타운 수탁용역을 111억에 수탁을 한 적이 있습니다.  그래서 집행을 보면 59억 8,600을 집행하고 잔액이 51억이 남은 것으로 자료에 나와 있어요, 예를 들면.  그러면 예산을 세울 때 거기에 보면 초빙연구원 6,260만원부터 시작해서 전출금 6,152만원 이렇게 예산을 세워놓고 집행액도 보면 아주 10원 하나 안 틀리고 그대로 집행을 했거든요.  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 너무 정확하게 집행한 것 아니냐 하는…….
</p>
<p><b>○ 이해문 위원 </b> 아니, 너무 정확하게 집행한 게 아니라 본 위원은 이것은 정확하게, 예를 들어서 국내여비 1,417만 5,000원 예산, 집행 1,417만 5,000원 이렇게 모든 항목이 예산 대비 집행액을 딱 맞추어서 지출한다는 게 현실적으로 불가능할 텐데 어떻게 이런 계산이 나오지요?  혹시 이거 담당했던 분이 있으면 답변해 주시지요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 해당 박사가 따로 있습니다만 우선 실무자가 답변하고 필요하면 강 박사가…….
</p>
<p><b>○ 재정지원과장 강윤구 </b> 재정과장 강윤구입니다.  그것은 저희 예산상에 수탁사업을 완료하면 12월 31일자로 정산해서 일반회계 수입 조치를 하면 실질적으로 전출금과 집행잔액은 일반회계 세입이 되기 때문에 결산서 상에 예산과 집행은 100%로 나타나게 됩니다.  그래서 실제적으로 회계 계리 상의 표기문제지요, 실제 일어나는 것은 100% 집행은 아닙니다.  집행잔액과 전출금을 일반회계수입금으로 12월 31일자로 정산해서 전출시키기 때문에 그런 현상이 있습니다. 
</p>
<p><b>○ 이해문 위원 </b> 그러면 재무제표 64쪽에 재래시장 특화육성에서 여기 예산에 보면 3,474만원의 예산이 잡혀있고 집행은 2만원, 잔액이 3,472만원 돼 있어요.  거기 잔액에 보면 잔액이 다 나와 있어요.  그러면 이 사업은 끝난 겁니까? 
</p>
<p><b>○ 재정지원과장 강윤구 </b> 그것은 완료하지 않은 사업으로 익년도로 넘어가는 돈이 잔액이 되겠습니다. 
</p>
<p><b>○ 이해문 위원 </b> 그러면 여기 국내여비 2만원, 이것은 어떠한 품목이에요?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 당해연도 집행만 2만원이 이루어졌고요.  나머지 예산은 2개 연도에 걸쳐서 했기 때문에 다음연도로 이월되는 예산액이 되겠습니다.  
</p>
<p><b>○ 이해문 위원 </b> 그래서 본 위원이 아까도 수탁사업의 수익부분하고도 관련해서 얘기했고요.  그래서 사실은 구조적으로 지금 경기개발연구원의 수입과 지출에 대해 클리어하게 우리가 분석할 필요가 있다는 얘기지요.  그래서 정말 수탁사업은 수탁사업으로서 비용이 과연 얼마 들어갔느냐.  쉽게 말하면 원가가 얼마 들어갔느냐.  그래서 얼마의 이익이 났으면 물론 우리가 떳떳하게 적립할 수 있어요.  아까 기금의 적립도 얼마든지 가능합니다.  물론 세금도 예를 들어서 국가에 내는 것이기 때문에 필요하면 이익이 났으면 세금도 당연히 내야 되는 거지요.  그러나 현재 여기 시스템 상으로 보면 사업자교부만 받아가지고 번호만 지정돼 있는 이런 시스템 상에서는 우리가 클리어하지 못하다보면 문제가 될 수 있다고 생각하거든요, 본 위원이 생각할 때는.  그래서 한번 심도있게 연구를 해보시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 
</p>
<p><b>○ 이해문 위원 </b> 앞으로도 계속 수탁사업이 일어날 거고 또 거기에 따른 비용도 발생할 겁니다.  그러면 그 비용 중에 수탁사업의 결과는 뭐라고 했냐면 여기 연구원들의 인건비라고 이렇게 얘기하셨거든요.  인건비가 남는 거다라고 이렇게 얘기하셨는데 그러면 거기에 인건비도 사실은 원가에 포함되는 부분이 있거든요.  그래서 쉽게 말하면 경기개발연구원에서 도비보조 받는 것에서 인건비로 충당하고 수탁사업에서 남는 것은 다 인건비다 이렇게 생각한다면 나중에 기업회계기준에 의해서 우리가 구분계리할 때도 문제가 없는지 해볼 필요가 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 
</p>
<p><b>○ 이해문 위원 </b> 특히 내년부터는 경기도에도 복식회계에 의해서 우리가 모든 거래를 하도록 돼 있는 것 알고 계시지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 알고 있습니다. 
</p>
<p><b>○ 이해문 위원 </b> 그래서 물론 여기는 이미 기업회계 기준에 의해서 하고 있습니다.  장부도 하고 있고 제가 다 확인했고요.  그런데 편의상 이 예산회계에 대해서 전부 보고를 하고 있어요.  그러니까 저희들이 볼 때는 두 가지를 놓고 봐야 되거든요.  여기 담당하는 분들도 사실 두 가지를 하다보니까 힘들 줄은 알고 있습니다.  그런데 이게 하나의 복식부기의 시스템이 된다면 떨 것은 빨리 떨고 하나로 할 수 있는 그런 것으로 정리가 됐으면 좋겠습니다.  연구해 보시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 감사합니다.  오늘 아주 좋은 점을 지적해 주셔서 우리 연구원의 회계제도가 훨씬 선진화되는 계기가 되지 않을까 하는 생각이 듭니다. 
</p>
<p><b>○ 이해문 위원 </b> 그리고 이왕 질의했으니까 시간이 갔습니다만 사무처장님한테 잠깐 질의드리겠습니다.  사무처장님 여러 가지로 오래 많이 기다리셨는데, 여기 규정에 보면 내년도 예산을 수립하도록 돼 있고 예산이 수립되면 1개월 전에 도에다 보고하도록 돼 있지요? 
</p>
<p><b>○ 사무처장 이정열 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이해문 위원 </b> 내년도 예산이 수립됐습니까? 
</p>
<p><b>○ 사무처장 이정열 </b> 네.
</p>
<p><b>○ 이해문 위원 </b> 이사회 거쳤습니까? 
</p>
<p><b>○ 사무처장 이정열 </b> 이사회는 아직, 예산이 의회에서 성립되면…….
</p>
<p><b>○ 이해문 위원 </b> 아니요.  본 위원이 질의하는 거는 회계규정에 보면 내년도 예산을 수립해서, 쉽게 말씀드리면 자체 이사회 결의를 거쳐서 그 다음에 도지사한테 한 달 전에 제출하도록 돼 있다는 얘기지요.  그런데 우리 도 예산의 결정심의받는 게 아니라 여기 자체 예산을 한 달 전에 제출하도록 돼 있다는 얘기예요, 규정에.  그렇다면 오늘이 11월 21일, 그러니까 적어도 이달 말까지는 내야 되는데 그러면 이사회를 해야 되는데 아직 이사회가 소집이 안 돼 있지요?
</p>
<p><b>○ 사무처장 이정열 </b> 네, 안 돼 있습니다. 
</p>
<p><b>○ 이해문 위원 </b> 내년도 예산도 아직 정확하게 수립이 안 된 것 같은데.
</p>
<p><b>○ 사무처장 이정열 </b> 자체적으로 예산을 수립해서 도에 제출된 상태입니다.  
</p>
<p><b>○ 이해문 위원 </b> 그런데 이사회 승인은 언제 받았어요?
</p>
<p><b>○ 사무처장 이정열 </b> 이사회 승인은 도의회에서 승인이 나면 그것을 가지고 다시 또 집행계획을 이사회에 상정해서 확정을 짓게 되는 겁니다. 
</p>
<p><b>○ 이해문 위원 </b> 제가 질의한 내용하고 조금 답변이 틀린데요.  이 규정에는 이사회를 하고 내게 돼 있다는 얘기지요, 예산 수립을 해서.  처장님, 그 내용을 다른 담당자가 있으면 확인해 보십시오. 
</p>
<p><b>○ 사무처장 이정열 </b> 이사회의 계획은 12월 20일경에 소집할 예정으로 있습니다.  
</p>
<p><b>○ 이해문 위원 </b> 12월 20일.  이사회 날짜를 잡았어요?
</p>
<p><b>○ 사무처장 이정열 </b> 네.  
</p>
<p><b>○ 이해문 위원 </b> 그래도 이사회를 12월 20일에 해서 그때 결정되면 한 달 계획 전에 이사회를 해서 승인을 받아내야 하는데 벌써 안 되지 않습니까?  왜 이런 얘기를 하냐면 이런 예산을 사전에 충분히, 규정에 보면 각 부서에다 예산을 수립하고 그것을 또 자체적으로 계획해서 이사회 승인을 받아서 그 다음에 도에다 내는 이런 시스템을, 규정을 잘 안 지킨다 이런 얘기지요.  그래서 본 위원이 질의한 겁니다. 
</p>
<p><b>○ 사무처장 이정열 </b> 앞으로 그런 문제…….
</p>
<p><b>○ 이해문 위원 </b> 담당자가 있으면 이 규정을 한번 확인해 보세요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리 김영수 과장이 그동안 쭉 이것을 해 와서 내용을 좀 알기 때문에 제가 답변을 하도록 하겠습니다.
</p>
<p><b>○ 이해문 위원 </b> 네, 답변해 주세요. 
</p>
<p><b>○ 행정지원과장 김영수 </b> 행정지원과장 김영수입니다.  위원님께서 지적하신 대로 1개월 전에 사업계획서와 예산서를 도에 제출해서 승인을 받도록 돼 있는데 쭉 그것을 이행해서 11월에 주로 이사회를 해왔습니다.  그런데 작년 이사회부터 저희가 12월에 하는 이유가 이사님들 중에서 “도비지원이 확정되지도 않았는데 어떻게 여기서 도비규모를 가지고 예산을 편성하냐.” 그런 지적이 있어서 예결특위가 거의 진행된 어느 정도 결과를 아는 시점인 20일경으로 저희가 이사회 날짜를 잡은 겁니다. 
</p>
<p><b>○ 이해문 위원 </b> 시간이 좀 갔지만 명확하게 합시다.  그러면 도에서는, 우리는 반대의견이에요.  아까도 제가 얘기했습니다만 여기가 12월 결산 법인이기 때문에 12월 결산을 해서 이월금이 나오지 않습니까?  그러면 2월에 가서 이사회를 해서 이월금을, 잉여금을 어떻게 처리할 것인가 결정해요.  그렇지요?
</p>
<p><b>○ 행정지원과장 김영수 </b> 네. 
</p>
<p><b>○ 이해문 위원 </b> 그런데 우리는 통상적으로 12월에 의회에서 내년도 예산을 승인한단 말이에요.  승인하는 절차 중에는 경기개발연구원이 2006년도에 얼마나 예산이 남았는지 이월된 것을 정확하게 모른단 말이에요.  모르니까 달라는 대로 예산을 주니까 이미 우리는 12월에 다음해 예산을 승인해 버렸단 말이에요.  그렇지 않습니까? 
</p>
<p><b>○ 행정지원과장 김영수 </b> 네.
</p>
<p><b>○ 이해문 위원 </b> 그런데 여기는 12월 31일 결산을 하고 2월에 보고할 때 잉여금 처분을 이렇게 한다고 보고한단 말이에요.  그럼 아까 같은 그런 문제가 있는 게 여기 회의록에 있습니다만 그러면 결과적으로 의회에서는 그러한 내년도 추정예산이, 여기에 추정재무제표를 만들게 돼 있어요.  금년도에 공익법인에 대한 추정대차대조표와 손익계산서를 1개월 전에 만들게 돼 있다고요.
</p>
<p style="padding-left:1.2em">  그러면 그것을 보고 지사한테 제출한다는 얘기는 집행부에 냈다는 얘기예요.  그러면 저희들은 그것을 보고 경기개발연구원이 금년도 12월에 추계가 이 정도 해서 이월이 이 만큼 될 것이다라고 생각해서 내년도 예산을 줄 때 저희들이 가감할 수 있다는 얘기죠.  그런 것을 위해서 이 재무규정에 나와 있기 때문에 그것을 했냐고 묻는데 여기 편의상 우리와 반대의견이란 말이에요.  “도에서 예산이 승인되어야 된다.  그것을 보고 여기에서는 이사회를 하겠다.” 그러면 안 맞죠.  그러면 이 규정을 바꾸어야 되죠.  
</p>
<p><b>○ 행정지원과장 김영수 </b> 저희가 1개월 이내인데 1개월 이내가 너무 짧지 않느냔 말씀 아니십니까?  12월 20일이기 때문에.  11월말 정도 했으면 적당한 시기인데.  그런데 그것은 저희가 변명은 아니고요.  이사회에서 이사님들이 도비 규모가 굳어지지도 않았는데 임의적으로 이사회에서 얼마 신청하는 것을 가지고 되느냐 그런 말씀이 있으셔서 늦춘 겁니다.
</p>
<p><b>○ 이해문 위원 </b> 반복되는 얘기입니다만.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 위원님, 제가 충분히 이해가 됩니다.  사전에 기획위원회에서 우리 연구원의 예컨대 불용액이 얼마이고, 추정이지만, 그것을 기초로 해서 내년에 어떻게 예산을 짜겠다는 그게 와야지 할 수 있는데 저희가 그것을 사전에 안 해줌으로 해서 여러분들이 문제가 된다는 것은 충분히 이해가 됩니다.  원칙은 그런데 현실적으로는 사실은 도에서 나오는 예산이 거의 저희 예산 전부나 다름없는데 그것이 책정되지 않았는데 이사님들 모아 놓고 “우리 연구원 예산을 결정해 주십시오.” 하는 것이 그것도 또, 그래서 이것을 지적하신 것을 충분히 공감하는데요.  한번 검토를 해서 내년에는 규정도 어기지 않으면서 이사님들한테도 불편을 안 드리고 할 수 있는 방안이 있는지 규정에 맞게끔…….
</p>
<p><b>○ 이해문 위원 </b> 당연히 우리 의회 입장에서는 짚고 넘어가야 돼요.  물론 종합감사 때 기획관리실장에게도 질의하겠습니다만 이런 것이 선행이 안 된다면, 예를 들어서 지금 여기 마찬가지입니다.  매년 예산 대비 1%에 해당하는 예비비를 책정만 해 놓고 10년 동안 단 1원도 안 썼어요, 예비비를.  예비비로 책정만 해 놓고 안 썼다고.  예비비 쓸 수 있는 규정 다 있어요.  각 부서에서 예비비 쓰겠다고 올라오면 사무처장이 원장에게 보고하고 집행할 수 있도록 되어 있거든요.  그동안에 경기개발연구원의 재정이 풍부하고 여러 가지 여건이 좋아서 그런지 모르겠습니다만 예비비도 쓸 수 있도록 다 승인해 준 겁니다.  또 그에 따라서 지출할 수 있는 항목도 있는 거고요.  그래서 의회 입장에서는 앞으로 우리가 이월금 남겨 가지고 계속해서 정관 11조에 의해서 기금으로 넣겠다고 그러면 우리는 심의할 때 추정재무제표를 보겠다는 얘기예요, 규정에 의해서.  그것을 제출해 주셔야죠.  그래야 이번에 심의할 때도, 제가 10월까지의 재무제표는 봤어요.  결산이 아직 안 되었으니까.  상당히 많은 부분이 이월될 것으로 예측됩니다.  그렇다면 내년도에 이월이 정확하게 결산하기 전이라도 대충 추계를 알아야, 내년에 104억쯤 예산 신청했죠?  그것하고 대비해서 저희들이 예산을 확정시켜야 되는데 그런 계리에 문제가 있습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 원칙적으로 104억을 저희가 신청할 때 그런 추정 대차대조표를 다 만들고 이래서 그것에 기초해서 내년 사업을 감안해서 신청하지 않을까 싶은데.
</p>
<p><b>○ 이해문 위원 </b> 그러면 추정재무제표가 있어요?  제출해 줘 보세요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 내부 예산계획이라는 것을 수립했다고 합니다.
</p>
<p><b>○ 이해문 위원 </b> 내부관리 예산이고 여기에 보면 공익법인에 대해서 추정재무제표를 작성하게 되어 있어요.  여기도 법인이잖아요.  비영리법인이고.  추정재무제표가 나와야죠.  그것을 근거로 해서 내년도 예산을 반영해야죠.  이것이 안 되니까 결과적으로 우리가 의회에서도 미스를 한단 말이에요.  달라는 것 필요하니까 줘야 되겠다 하니까 다음에 2월에 가서 결산서에 보니까, 처분하는 것 보니까 이 만큼 이월되어 내려왔다.  우리도 의회 입장에서 이 문제를 지적하지 않을 수 없습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 위원님 논리에 전혀 문제가 없습니다.  충분히 제가 동의합니다. 
</p>
<p><b>○ 이해문 위원 </b> 만약에 규정이 틀렸다면 규정을 바꿔야죠.  검토하시고요.  추정재무제표가 있으면 제출해 주시기 바랍니다.  이상 마치겠습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 이해문 위원님 수고하셨습니다.  질의하실 위원님 계십니까?  더 이상 질의하실 위원이 안 계시면, 우리 위원님들과 감사와 관련해서 협의한 결과 위원회 일정에 11월 28일 미진한 사항에 대해서 감사를 하기로 되어 있습니다.  그러나 우리 경기개발연구원 관계자들이 많은 업무로 인해서 효율적인 감사를 위해서 오늘 감사는 마쳐주되, 단 11월 28일 본 위원회 종합감사 시에 장윤영 위원님과 임우영 위원님이 인쇄물 계약과 관련하여 제출 요구한 자료내용에 대해서 추가 질의답변이 필요할 경우에 원장님께서는 경기개발연구원 관계자가 출석해서 답변할 수 있도록 조치가 가능한지 답변을 부탁드립니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 다른 무슨 업무보다도 저는 감사를 받는 일이 가장 중요한 일이라고 생각합니다.  만사를 불구하고 가야 된다고 생각합니다만 저희가 11월 28일 미군주둔지역에서 미군과 지역주민 간에 화합 방안에 대한 심포지엄을 마련해서 오후에 진행하기로 되어 있어서, 물론 지사님이 나오시기 때문에 제가 위원회에 나가고 대신 부원장이라도 세미나에 나가도록 허용해 준다면 제가 위원회에 나가도록 하겠습니다.  위원회 조치에 따르겠습니다.
</p>
<p><b>○ 위원장 김영복 </b> 그래서 저희가 위원님들이 사전협의를 해서 우리 연구원의 이런 애로사항 여러 가지가 있는 것을 감안해서 이런 식으로 하려고 합니다.  문제가 있는 것에 대해서만, 그 부분만 기획관리실이라든가 다른 업무 감사 시에 나중에 시간을 할애해서 질의 및 답변을 듣고자 하는데 가능하시겠습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다.
</p>
<p><b>○ 위원장 김영복 </b> 위원님 여러분!  거기에 대해서 이의 있으십니까?  임우영 위원님 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 임우영 위원 </b> 아까 수의계약 부분만 말씀하셨는데 기획관리실 감사에서 방금 이해문 부위원장님 말씀하신 부분도 굉장히 중요한 사안입니다.  결국은 이 문제가 아까 불용액을 잉여금으로 처리하는 근본적인 원인을 제공한 부분이거든요.  그렇기 때문에 이 부분에 대해서도 기획관리실 감사에서 문제제기가 되고 그에 따른 기획관리실장 답변이 미진하면 그 부분도 그날 같이 확인하되, 물론 2시 반부터 은행연합회 건물에서 하죠?  세미나가 2시 반에 은행연합회에서 있어요.  그러니까 저희들이 그것을 오전에 처리하는 방법도 있고 운영의 묘를 살리면 좋겠습니다.  그 부분도 같이 첨가해서 해 주셨으면 좋겠습니다. 
</p>
<p><b>○ 위원장 김영복 </b> 그래서 그런 문제가 드러났을 시에 거기에 관여되신 분들만 하고 효율적인 감사를 위해서 다른 것은 오늘 질의를 다 마치는 것으로 하는데, 그렇지 않으면 오늘 마치지 않고 다음으로 계속 지속되거든요.  거기에 대해서 이의 없습니까?
</p>
<p style="padding-left:2.4em">    (「네」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 좀 전에 말씀드린 그런 내용과 임우영 위원님이 말씀하신 사항에 대해서 자료와 설명을 미리 해 주시고요.  그게 미진할 경우에 11월 28일 추가 질의답변을 하는 것으로 하겠습니다. 
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원이 안 계시면 이상으로 경기개발연구원에 대한 질의와 답변을 모두 마치겠습니다.  장시간 열의를 갖고 감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료준비와 위원님들의 질의에 성실히 답변해 주신 좌승희 원장을 비롯한 임직원 여러분에게 감사드립니다.  다만 한 가지 지적하고자 합니다.  2005년도 미집행 인건비와 미집행 연구비 15억 잉여금 처분에 대하여는 이사회를 열어서라도 신중하게 재검토해 주실 것을 말씀드립니다.
</p>
<p style="padding-left:1.2em">  오늘 여러 위원님들께서 감사 시 지적해 주신 사항은 도민들의 뜻이니 만큼 겸허히 받아들여서 연구원 업무에 적극 반영될 수 있도록 최선의 노력을 다해 주시기 바랍니다.  위원 여러분 그리고 연구원임직원 여러분!  수고하셨습니다.  그러면 이상으로 경기개발연구원에 대한 2006년도 행정사무감사를 마치겠습니다. 
</p>
<p class=''ar''>(20시37분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원
</b></p>
<p class=''aMan''>김영복이해문조선미권혁조김기수김대원임우영장윤영전동석정인영</p>
<p><b>○ 출석전문위원
</b></p>
<p class=''em15''>   박춘배
</p>
<p><b>○ 피감사기관 참석자
</b></p>
<p><p class=''em15''>경기개발연구원장 좌승희부원장 신원득</p>
<p><p class=''em15''>기획조정실장 이상훈사무처장 이정열</p>
<p><p class=''em15''>수도권정책센터장 이상대자치행정연구부장 이용환</p>
